/* ============================================================
   FILTROS MULTI-SELEÇÃO (.msel); dropdown com checkboxes
   ============================================================ */
function criarMultiSelect(id, rotulo, onChange) {
  const host = document.getElementById(id);
  if (!host) return null;
  host.classList.add('msel');
  host.innerHTML =
    '<button type="button" class="msel-btn">' +
      '<span class="msel-label">' + esc(rotulo) + '</span>' +
      '<span class="msel-count" hidden></span>' +
      '<svg class="msel-chev" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>' +
    '</button>' +
    '<div class="msel-menu" hidden>' +
      '<input type="text" class="msel-busca" placeholder="Buscar..." />' +
      '<div class="msel-itens"></div>' +
      '<div class="msel-foot">' +
        '<button type="button" class="msel-todos">Selecionar todos</button>' +
        '<button type="button" class="msel-limpar">Limpar seleção</button>' +
      '</div>' +
    '</div>';
  const menu = host.querySelector('.msel-menu');
  const busca = host.querySelector('.msel-busca');
  const itensWrap = host.querySelector('.msel-itens');
  const countEl = host.querySelector('.msel-count');
  const btnTodos = host.querySelector('.msel-todos');
  // Dentro de um MODAL o menu não pode ser `position:absolute`: ele nasce dentro do .msel, que
  // vive no `.modal` (`overflow:auto; max-height:92vh`) — e o fim da lista morria na borda do
  // modal (bug relatado no "Novo EPI": os últimos contratos apareciam cortados). Aqui ele vira
  // FLUTUANTE: vai para o <body> e é posicionado por ancorarMenuFixo (o mesmo helper das
  // pílulas), que abre para cima quando não cabe abaixo e limita a altura ao espaço da tela,
  // com rolagem própria. Precisa ser o <body> e não só `position:fixed` no lugar: em alguns
  // temas o `.modal` tem backdrop-filter, o que o tornaria o containing block do fixed e o
  // corte voltaria (mesma armadilha documentada em ancorarMenuFixo).
  const flutuante = !!host.closest('.modal-overlay');
  // O visual de "lista" do dropdown de contratos é escrito como `.msel-bloco .msel-item…`
  // (descendente do HOST). Ao portar o menu para o <body> esses seletores deixariam de casar e
  // o menu voltaria à cara de filtro; a classe espelhada no próprio menu viaja junto com ele.
  if (host.classList.contains('msel-bloco')) menu.classList.add('msel-menu-bloco');
  let ancorado = false;
  function posicionarMenuFlutuante() {
    const r = host.querySelector('.msel-btn').getBoundingClientRect();
    menu.style.width = r.width + 'px'; // largura do gatilho (o `width:100%` do bloco resolveria contra o <body>)
    // Só a PRIMEIRA ancoragem pode animar. ancorarMenuFixo zera e devolve o `animation` para
    // medir a altura escondida, e devolver reinicia a animação de entrada (menuIn: opacity 0 +
    // scale .97) — a cada evento de rolagem o menu piscava e sumia por um quadro.
    if (ancorado) menu.style.animation = 'none';
    ancorarMenuFixo(r, menu, r.width);
    ancorado = true;
  }
  function reancorar() {
    // Se o modal fechou por baixo do menu, ele ficaria órfão flutuando na tela.
    if (!host.isConnected || !host.querySelector('.msel-btn').getClientRects().length) { api.fechar(); return; }
    posicionarMenuFlutuante();
  }
  function soltarMenu() {
    window.removeEventListener('scroll', reancorar, true);
    window.removeEventListener('resize', reancorar);
    ancorado = false;
    if (!menu.classList.contains('msel-menu-flutuante')) return;
    menu.classList.remove('msel-menu-flutuante');
    menu.removeAttribute('style'); // limpa o posicionamento inline deixado por ancorarMenuFixo
    host.appendChild(menu);
  }
  let opcoes = [];
  const sel = new Set();
  function atualizarBotao() {
    if (sel.size) { countEl.hidden = false; countEl.textContent = sel.size; host.classList.add('tem-sel'); }
    else { countEl.hidden = true; host.classList.remove('tem-sel'); }
  }
  // Opções que a busca do dropdown está deixando à VISTA — a "lista filtrada" do menu, e é
  // sobre ela que agem tanto o desenho dos itens quanto o "Selecionar todos". Sem busca
  // digitada, é a lista inteira. Vive fora de renderItens de propósito: duas cópias da mesma
  // regra divergiriam no primeiro ajuste de busca (acento, startsWith...) e o botão passaria
  // a marcar um conjunto diferente do que está na tela.
  // Ex.: opcoes = ['NTE','KV','SUL'] e busca = 'j'  →  visiveis() === ['NTE']
  function visiveis() {
    const q = busca.value.trim().toLowerCase();
    return q ? opcoes.filter(o => String(o).toLowerCase().includes(q)) : opcoes.slice();
  }
  // O MESMO botão marca e desmarca, e o rótulo diz qual das duas vai acontecer antes do
  // clique. Não desabilitamos quando tudo já está marcado porque isso seria beco sem saída:
  // quem marcou 30 sob a busca "NTE" e quer desfazer SÓ esses 30 não teria caminho — o
  // "Limpar seleção" ao lado é grosso demais (apaga também o que foi marcado sob outra
  // busca). O único estado morto honesto é "Nada encontrado".
  function atualizarBotaoTodos() {
    if (!btnTodos) return;
    const vis = visiveis();
    const todos = vis.length > 0 && vis.every(o => sel.has(o));
    btnTodos.disabled = vis.length === 0;
    // A contagem no rótulo desfaz sozinha a ambiguidade "todos = os 3 à vista ou os 47 da lista?".
    btnTodos.textContent = (todos ? 'Desmarcar todos' : 'Selecionar todos') + (vis.length ? ' (' + vis.length + ')' : '');
    btnTodos.title = todos
      ? 'Desmarca as ' + vis.length + ' opções que a busca está mostrando (as demais seguem marcadas)'
      : 'Marca as ' + vis.length + ' opções que a busca está mostrando';
  }
  function renderItens() {
    const vis = visiveis();
    itensWrap.innerHTML = vis.length
      ? vis.map(o => '<label class="msel-item"><input type="checkbox" value="' + esc(o) + '"' + (sel.has(o) ? ' checked' : '') + ' /><span>' + esc(o) + '</span></label>').join('')
      : '<div class="msel-vazio">Nada encontrado</div>';
    atualizarBotaoTodos();
    // A lista mudou de altura (abriu, filtrou pela busca, o rótulo do rodapé trocou de
    // tamanho): reancora para continuar dentro da tela. Depois de atualizarBotaoTodos de
    // propósito — é ancorarMenuFixo que decide se o menu abre para cima e onde corta.
    if (menu.classList.contains('msel-menu-flutuante')) posicionarMenuFlutuante();
  }
  host.querySelector('.msel-btn').addEventListener('click', (e) => {
    e.stopPropagation();
    if (menu.hidden) {
      fecharMsels(host);
      menu.hidden = false; host.classList.add('aberto');
      if (flutuante) {
        menu.classList.add('msel-menu-flutuante');
        window.addEventListener('scroll', reancorar, true); // captura: pega a rolagem do modal também
        window.addEventListener('resize', reancorar);
      }
      renderItens(); // monta a lista e, se flutuante, já a posiciona
      setTimeout(() => busca.focus(), 0);
    }
    else api.fechar();
  });
  busca.addEventListener('input', renderItens);
  busca.addEventListener('click', (e) => e.stopPropagation());
  menu.addEventListener('click', (e) => e.stopPropagation());
  itensWrap.addEventListener('change', (e) => {
    const cb = e.target.closest('input[type=checkbox]'); if (!cb) return;
    if (cb.checked) sel.add(cb.value); else sel.delete(cb.value);
    atualizarBotao(); if (onChange) onChange();
  });
  if (btnTodos) btnTodos.addEventListener('click', (e) => {
    e.stopPropagation();
    const vis = visiveis();
    if (!vis.length) return;
    // ADITIVO: a busca do dropdown é uma LENTE, não um recorte da seleção. O fluxo real é
    // "busco NTE → marco todos → busco SUL → marco todos", e o usuário espera os dois
    // conjuntos. É também a semântica de marcar item a item (marcar um nunca desmarca outro):
    // o botão é atalho para N cliques, não uma operação diferente.
    // Quando tudo o que está à vista já está marcado, o mesmo botão faz o inverso — e só
    // sobre o que está à vista, sem tocar no que foi marcado sob outra busca.
    const desmarcar = vis.every(o => sel.has(o));
    for (const o of vis) { if (desmarcar) sel.delete(o); else sel.add(o); }
    renderItens(); atualizarBotao();
    // Dispara onChange porque é ação do USUÁRIO, igual ao "Limpar seleção" abaixo — e ao
    // contrário da API limpar(), chamada em lote pelos "Limpar filtros", que já redesenham
    // a aba por conta própria.
    if (onChange) onChange();
  });
  host.querySelector('.msel-limpar').addEventListener('click', (e) => {
    e.stopPropagation(); sel.clear(); renderItens(); atualizarBotao(); if (onChange) onChange();
  });
  const api = {
    host,
    setOpcoes(vals) {
      const novas = (vals || []).map(String);
      const mudou = novas.length !== opcoes.length || novas.some((v, i) => v !== opcoes[i]);
      opcoes = novas;
      for (const s of [...sel]) if (!opcoes.includes(s)) sel.delete(s); // remove seleções que sumiram
      if (!menu.hidden && mudou) renderItens(); // só reconstrói o menu aberto se a lista mudou (evita jank ao marcar vários)
      atualizarBotao();
    },
    getSelecionados() { return [...sel]; },
    setSelecionados(vals) { sel.clear(); for (const v of (vals || [])) sel.add(String(v)); if (!menu.hidden) renderItens(); atualizarBotao(); },
    limpar() { sel.clear(); renderItens(); atualizarBotao(); },
    fechar() { menu.hidden = true; host.classList.remove('aberto'); soltarMenu(); },
  };
  MSEL[id] = api;
  return api;
}
function fecharMsels(exceto) { for (const k in MSEL) if (MSEL[k] && MSEL[k].host !== exceto) MSEL[k].fechar(); }
function getSel(id) { return MSEL[id] ? MSEL[id].getSelecionados() : []; }
// `.dp-cal` é o popover do calendário do date picker interno, que vive no <body>: clicar num
// dia borbulharia até aqui como "fora do .msel" e fecharia o menu do filtro de período no meio
// da escolha da data. O calendário é parte do controle, não "fora".
document.addEventListener('click', (e) => { if (!e.target.closest('.msel') && !e.target.closest('.dp-cal')) fecharMsels(null); });

/* ============================================================
   FILTRO DE PERÍODO (irmão do multiselect, mesma casca .msel)

   Dropdown de período único (dia / mês / ano / intervalo de-até) com a MESMA
   anatomia de botão do criarMultiSelect — herda todo o CSS do Design System
   (§4/§4.1 do 05-components) e o sheet mobile sem uma linha nova. Registra-se
   em MSEL[id] com API compatível: fecharMsels, o clique-fora acima e o
   PainelFiltros.fechar() funcionam sem saber que ele existe.

   O estado só muda no botão APLICAR (ou no Limpar): abrir, mexer e fechar sem
   aplicar preserva o período anterior — ao reabrir, o menu re-sincroniza a
   partir do que está aplicado, descartando o rascunho.

   Ex.: criarFiltroPeriodo('fmVencPeriodo', 'Vencimento', filtrarMulta);
        // usuário escolhe "Mês: Agosto/2026" e clica Aplicar →
        MSEL['fmVencPeriodo'].getPeriodo()
          // → { modo:'mes', ini: <ts 01/08/2026 00:00>, fim: <ts 31/08/2026 00:00>, texto: 'ago/2026' }
        getSel('fmVencPeriodo')  // → ['ago/2026']  (conta 1 no contador do painel)
        MSEL['fmVencPeriodo'].limpar()  // → getPeriodo() === null, rótulo volta a "Vencimento"
   `opcoes` (opcional) serve às outras abas: `prefixo` do botão com período aplicado
   (padrão 'Venc.', o das Multas) e `anos` (função que devolve os anos a oferecer; padrão:
   os anos dos vencimentos das multas).
   Ex.: criarFiltroPeriodo('fodoPeriodo', 'Período', renderOdometro,
          { prefixo: 'Período', anos: () => [2026, 2025] }); // botão: "Período: ago/2026"
   ============================================================ */
function criarFiltroPeriodo(id, rotulo, onChange, opcoes = {}) {
  const host = document.getElementById(id);
  if (!host) return null;
  const prefixo = opcoes.prefixo === undefined ? 'Venc.' : opcoes.prefixo;
  host.classList.add('msel');
  const MESES_CURTO = ['jan', 'fev', 'mar', 'abr', 'mai', 'jun', 'jul', 'ago', 'set', 'out', 'nov', 'dez'];
  const MESES_LONGO = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];
  host.innerHTML =
    '<button type="button" class="msel-btn">' +
      '<span class="msel-label">' + esc(rotulo) + '</span>' +
      '<span class="msel-count" hidden></span>' +
      '<svg class="msel-chev" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>' +
    '</button>' +
    '<div class="msel-menu fperiodo-menu" hidden>' +
      '<div class="fperiodo-modos">' +
        '<button type="button" class="forn-chip on" data-modo="dia">Dia</button>' +
        '<button type="button" class="forn-chip" data-modo="mes">Mês</button>' +
        '<button type="button" class="forn-chip" data-modo="ano">Ano</button>' +
        '<button type="button" class="forn-chip" data-modo="faixa">Intervalo</button>' +
      '</div>' +
      // O wrapper .almox-data é de propósito: o date picker do app transforma o input nativo
      // no campo segmentado .hdate (régua oficial do DS §3.3.1) em vez do seletor do navegador.
      '<div class="fperiodo-campos" data-modo="dia">' +
        '<label class="almox-data">Dia <input type="date" class="fp-dia" /></label>' +
      '</div>' +
      '<div class="fperiodo-campos" data-modo="mes" hidden>' +
        '<div class="fperiodo-linha">' +
          '<select class="fp-mes" aria-label="Mês">' + MESES_LONGO.map((n, i) => '<option value="' + (i + 1) + '">' + n + '</option>').join('') + '</select>' +
          '<select class="fp-mes-ano" aria-label="Ano do mês"></select>' +
        '</div>' +
      '</div>' +
      '<div class="fperiodo-campos" data-modo="ano" hidden>' +
        '<select class="fp-ano" aria-label="Ano"></select>' +
      '</div>' +
      '<div class="fperiodo-campos" data-modo="faixa" hidden>' +
        '<label class="almox-data">De <input type="date" class="fp-de" /></label>' +
        '<label class="almox-data">Até <input type="date" class="fp-ate" /></label>' +
      '</div>' +
      '<div class="msel-foot">' +
        '<button type="button" class="fp-aplicar">Aplicar</button>' +
        '<button type="button" class="msel-limpar">Limpar período</button>' +
      '</div>' +
    '</div>';
  const menu = host.querySelector('.msel-menu');
  const label = host.querySelector('.msel-label');
  const inpDia = host.querySelector('.fp-dia');
  const selMes = host.querySelector('.fp-mes');
  const selMesAno = host.querySelector('.fp-mes-ano');
  const selAno = host.querySelector('.fp-ano');
  const inpDe = host.querySelector('.fp-de');
  const inpAte = host.querySelector('.fp-ate');

  // per === null → sem filtro; senão { modo, ini, fim, texto }.
  // ini/fim = timestamps 00:00 LOCAL do primeiro/último dia, INCLUSIVOS (mesma base do parseBR).
  // Na faixa, um lado null = intervalo aberto ("desde…" / "até…").
  let per = null;

  // 'aaaa-mm-dd' (o input nativo guarda ISO mesmo vestido de .hdate) → timestamp 00:00 local.
  // NUNCA new Date('aaaa-mm-dd'): o construtor por string interpreta UTC e desloca o dia.
  function isoParaTs(iso) {
    const x = String(iso || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!x) return null;
    const d = new Date(Number(x[1]), Number(x[2]) - 1, Number(x[3]));
    // round-trip: rejeita 31/02 etc. (o nativo não deixa, mas a defesa é barata)
    return (d.getMonth() === Number(x[2]) - 1 && d.getDate() === Number(x[3])) ? d.getTime() : null;
  }
  const tsParaIso = (ts) => {
    const d = new Date(ts);
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  };
  const brDe = (ts, curto) => {
    const d = new Date(ts);
    const ano = curto ? String(d.getFullYear()).slice(2) : d.getFullYear();
    return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + ano;
  };

  // Anos oferecidos: dos vencimentos existentes em MULTAS (min→max) quando houver;
  // fallback anoAtual−5..anoAtual+1 quando a lista está vazia ou ainda não carregou.
  // Recalculados a cada abertura do menu (a base muda sem recarregar a página).
  function anosDisponiveis() {
    const anoAtual = new Date().getFullYear();
    const anos = new Set();
    if (typeof opcoes.anos === 'function') opcoes.anos().forEach((a) => anos.add(Number(a))); // a aba dona do filtro diz quais anos existem
    else if (typeof MULTAS !== 'undefined' && Array.isArray(MULTAS)) {
      for (const m of MULTAS) {
        const dv = parseBR(m.dataVencimento);
        if (dv) anos.add(dv.getFullYear());
      }
    }
    if (!anos.size) for (let a = anoAtual - 5; a <= anoAtual + 1; a++) anos.add(a);
    anos.add(anoAtual); // o ano corrente sempre aparece (base velha não pode esconder o hoje)
    return [...anos].sort((a, b) => b - a);
  }
  function popularAnos() {
    const anos = anosDisponiveis();
    const html = anos.map((a) => '<option value="' + a + '">' + a + '</option>').join('');
    for (const sel of [selMesAno, selAno]) {
      const antes = sel.value;
      sel.innerHTML = html;
      // preserva a escolha se o ano ainda existe; senão cai no mais recente
      if (antes && anos.includes(Number(antes))) sel.value = antes;
    }
  }

  function modoAtivo() { return host.querySelector('.fperiodo-modos .forn-chip.on').dataset.modo; }
  function trocarModo(modo) {
    host.querySelectorAll('.fperiodo-modos .forn-chip').forEach((c) => c.classList.toggle('on', c.dataset.modo === modo));
    host.querySelectorAll('.fperiodo-campos').forEach((p) => { p.hidden = p.dataset.modo !== modo; });
  }

  // Reflete no menu o período APLICADO (não o rascunho): chamado ao abrir, para que
  // mexer-e-fechar-sem-aplicar não deixe lixo na próxima abertura.
  function sincronizarDoAplicado() {
    popularAnos();
    const hoje = new Date();
    inpDia.value = ''; inpDe.value = ''; inpAte.value = '';
    selMes.value = String(hoje.getMonth() + 1);
    if (!per) { trocarModo('dia'); return; }
    trocarModo(per.modo);
    if (per.modo === 'dia') inpDia.value = tsParaIso(per.ini);
    else if (per.modo === 'mes') {
      const d = new Date(per.ini);
      selMes.value = String(d.getMonth() + 1);
      if (![...selMesAno.options].some((o) => o.value === String(d.getFullYear()))) selMesAno.insertAdjacentHTML('afterbegin', '<option value="' + d.getFullYear() + '">' + d.getFullYear() + '</option>');
      selMesAno.value = String(d.getFullYear());
    } else if (per.modo === 'ano') {
      const a = new Date(per.ini).getFullYear();
      if (![...selAno.options].some((o) => o.value === String(a))) selAno.insertAdjacentHTML('afterbegin', '<option value="' + a + '">' + a + '</option>');
      selAno.value = String(a);
    } else {
      if (per.ini != null) inpDe.value = tsParaIso(per.ini);
      if (per.fim != null) inpAte.value = tsParaIso(per.fim);
    }
  }

  function atualizarBotao() {
    if (per) { label.textContent = (prefixo ? prefixo + ': ' : '') + per.texto; host.classList.add('tem-sel'); }
    else { label.textContent = rotulo; host.classList.remove('tem-sel'); }
  }

  // Monta o período a partir do modo ativo. Nada preenchido → null (sem filtro).
  function montarPeriodo() {
    const modo = modoAtivo();
    if (modo === 'dia') {
      const t = isoParaTs(inpDia.value);
      return t == null ? null : { modo, ini: t, fim: t, texto: brDe(t) };
    }
    if (modo === 'mes') {
      const a = Number(selMesAno.value), m = Number(selMes.value);
      if (!a || !m) return null;
      return {
        modo,
        ini: new Date(a, m - 1, 1).getTime(),
        fim: new Date(a, m, 0).getTime(), // dia 0 do mês seguinte = ÚLTIMO dia do mês, incluído
        texto: MESES_CURTO[m - 1] + '/' + a,
      };
    }
    if (modo === 'ano') {
      const a = Number(selAno.value);
      if (!a) return null;
      return { modo, ini: new Date(a, 0, 1).getTime(), fim: new Date(a, 11, 31).getTime(), texto: String(a) };
    }
    // faixa: qualquer lado pode ficar aberto; invertido troca os lados em silêncio
    let ini = isoParaTs(inpDe.value), fim = isoParaTs(inpAte.value);
    if (ini == null && fim == null) return null;
    if (ini != null && fim != null && ini > fim) { const t = ini; ini = fim; fim = t; }
    const texto = ini != null && fim != null ? brDe(ini, true) + '–' + brDe(fim, true)
      : ini != null ? 'desde ' + brDe(ini) : 'até ' + brDe(fim);
    return { modo, ini, fim, texto };
  }

  host.querySelector('.msel-btn').addEventListener('click', (e) => {
    e.stopPropagation();
    if (menu.hidden) {
      fecharMsels(host);
      menu.hidden = false; host.classList.add('aberto');
      sincronizarDoAplicado();
    } else api.fechar();
  });
  menu.addEventListener('click', (e) => e.stopPropagation());
  host.querySelector('.fperiodo-modos').addEventListener('click', (e) => {
    const chip = e.target.closest('.forn-chip'); if (!chip) return;
    trocarModo(chip.dataset.modo); // trocar de modo é rascunho: só o Aplicar filtra
  });
  host.querySelector('.fp-aplicar').addEventListener('click', (e) => {
    e.stopPropagation();
    per = montarPeriodo();
    atualizarBotao();
    api.fechar();
    if (onChange) onChange();
  });
  host.querySelector('.msel-limpar').addEventListener('click', (e) => {
    e.stopPropagation(); api.limpar(); api.fechar(); if (onChange) onChange();
  });

  const api = {
    host,
    getPeriodo() { return per; },
    // Compatível com getSel()/contador do painel: período ativo (qualquer modo,
    // inclusive intervalo com um lado só) conta como 1 filtro.
    getSelecionados() { return per ? [per.texto] : []; },
    // Sem onChange, como a limpar() do multiselect: os "Limpar filtros" já redesenham a aba.
    limpar() {
      per = null;
      inpDia.value = ''; inpDe.value = ''; inpAte.value = ''; // value='' repinta o .hdate (setter do date picker)
      trocarModo('dia');
      atualizarBotao();
    },
    fechar() { menu.hidden = true; host.classList.remove('aberto'); },
  };
  MSEL[id] = api;
  return api;
}

/* ============================================================
   "SELECIONAR TODOS" DA TABELA (um por aba, na barra de filtros)
   ------------------------------------------------------------
   NÃO existe coluna de caixinhas: marcar uma a uma continua sendo o CLIQUE NA LINHA. Este
   controle vive na barra de filtros, está sempre visível, e "todos" quer dizer a LISTA
   FILTRADA INTEIRA — inclusive os itens que estão nas outras páginas. Trocar de página não
   mexe nele (o controle antigo, removido na 1.53.32, era por página e zerava a cada
   "Próxima ›"; é justamente isso que mudou).

   Tri-estado no <input type="checkbox">: ✓ (tudo do filtro marcado) · – (parte, via
   `indeterminate`, que já tem estilo global no styles.css) · vazio (nada). Fica `disabled`
   quando o filtro não devolve nada — marcar zero itens é promessa falsa.

   Desmarcar tira SÓ o que está no filtro do momento; o que foi marcado sob outro filtro
   continua. Quem zera tudo é o "Limpar seleção" da .sel-bar. São as duas granularidades
   sem inventar um terceiro botão.

   cfg:
     id       id do <input type="checkbox"> no index.html (o <span> do rótulo é id + 'Rot')
     selecao  o Set de chaves da aba (SELECAO_*)
     chave    (item) => chave — é FUNÇÃO porque a Frota guarda placa e as outras guardam id
     lista    () => lista filtrada da aba; precisa devolver EXATAMENTE o que o render desenha
     aoMudar  o que redesenhar depois de marcar/desmarcar
     visivel  (opcional) () => boolean, para aba cuja barra é compartilhada por várias visões

   Ex. de uso (Multas):
     const SEL_TODOS_MULTAS = criarSelecionarTodos({
       id: 'selTodosMultas', selecao: SELECAO_MULTAS, chave: (m) => m.id,
       lista: aplicarFiltrosMulta, aoMudar: renderMultas,
     });
     SEL_TODOS_MULTAS.sincronizar(lista); // no render, com a lista já calculada
     SEL_TODOS_MULTAS.sincronizar();      // no atualizarBarraSel*, reaproveitando o cache

   Com 26 multas filtradas e 25 por página: clicar marca as 26 (a da 2ª página também), o
   rótulo vira "Selecionar todos (26)" e a barra passa a dizer "26 selecionada(s)". Clicar de
   novo desmarca essas 26 e preserva o que estiver marcado fora do filtro.
   ============================================================ */
function criarSelecionarTodos(cfg) {
  // A lista filtrada só muda quando a aba REDESENHA (filtro, busca, página, ordenação); por
  // isso guardamos as chaves calculadas no render. Sem esse cache, cada clique numa linha de
  // Abastecimento refaria abtFiltrados() → contextoAlertasAbt(), que varre a base inteira
  // montando 5 Map e calculando medianas por placa/combustível.
  let chaves = null;
  const input = () => document.getElementById(cfg.id);
  const inst = {
    sincronizar(lista) {
      const el = input();
      if (!el) return;
      const host = el.closest('.sel-todos');
      // `visivel` é decisão da ABA (Funcionários só mostra na visão Detalhes, porque a
      // .func-topo é compartilhada pelas 6 visões). Sem ela, fica sempre visível.
      const visivel = cfg.visivel ? !!cfg.visivel() : true;
      if (host) host.hidden = !visivel;
      if (!visivel) return;
      if (lista) chaves = lista.map(cfg.chave);
      else if (!chaves) chaves = (cfg.lista() || []).map(cfg.chave);
      const n = chaves.length;
      let marcados = 0;
      for (const k of chaves) if (cfg.selecao.has(k)) marcados++;
      el.disabled = n === 0;
      el.checked = n > 0 && marcados === n;
      el.indeterminate = marcados > 0 && marcados < n;
      const rot = document.getElementById(cfg.id + 'Rot');
      if (rot) rot.textContent = n ? `Selecionar todos (${n})` : 'Selecionar todos';
      el.setAttribute('aria-label', n
        ? `Selecionar os ${n} itens do filtro atual, inclusive os das outras páginas`
        : 'Selecionar todos — nenhum item no filtro atual');
    },
    marcar(ligar) {
      if (!chaves) chaves = (cfg.lista() || []).map(cfg.chave);
      for (const k of chaves) { if (ligar) cfg.selecao.add(k); else cfg.selecao.delete(k); }
      if (cfg.aoMudar) cfg.aoMudar(); else inst.sincronizar();
    },
  };
  const el = input();
  // Clicar num checkbox `indeterminate` sempre resulta em checked=true → "parte marcada"
  // vira "tudo marcado", que é o passo esperado. O elemento é estático no index.html, então
  // listener direto, sem delegação.
  if (el) el.addEventListener('change', () => inst.marcar(el.checked));
  return inst;
}

/* ============================================================
   AUTOCOMPLETE no estilo do site (substitui o <datalist> nativo)
   ============================================================ */
const AC_MAX = 50; // máximo de sugestões exibidas
function ativarAutocomplete(input) {
  const listId = input.getAttribute('list');
  if (!listId) return;
  const datalist = document.getElementById(listId);
  input.removeAttribute('list');          // desliga a caixinha nativa do navegador
  input.setAttribute('autocomplete', 'off');
  const menu = document.createElement('div');
  menu.className = 'ac-menu';
  menu.hidden = true;
  document.body.appendChild(menu);
  let ativo = -1, itens = [];

  const opcoes = () => datalist ? [...datalist.querySelectorAll('option')].map(o => o.value).filter(Boolean) : [];
  function posicionar() {
    ancorarMenuFixo(input.getBoundingClientRect(), menu, input.getBoundingClientRect().width);
  }
  function abrir() {
    if (input._semAbrirAuto) { input._semAbrirAuto = false; return; } // foco programático (modal abrindo) não deve estourar a lista
    const q = input.value.trim().toLowerCase();
    itens = opcoes().filter(o => !q || o.toLowerCase().includes(q)).slice(0, AC_MAX);
    if (!itens.length) { fechar(); return; }
    menu.innerHTML = itens.map((o, i) => `<div class="ac-item${i === ativo ? ' ativo' : ''}" data-val="${esc(o)}">${esc(o)}</div>`).join('');
    posicionar();
    menu.hidden = false;
  }
  function fechar() { menu.hidden = true; ativo = -1; }
  function escolher(val) {
    input.value = val;
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
    fechar();
  }
  input.addEventListener('focus', abrir);
  input.addEventListener('input', () => { ativo = -1; abrir(); });
  input.addEventListener('keydown', (e) => {
    if (menu.hidden) return;
    if (e.key === 'ArrowDown') { e.preventDefault(); ativo = Math.min(ativo + 1, itens.length - 1); abrir(); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); ativo = Math.max(ativo - 1, 0); abrir(); }
    else if (e.key === 'Enter' && ativo >= 0) { e.preventDefault(); escolher(itens[ativo]); }
    else if (e.key === 'Escape') { fechar(); }
  });
  // mousedown (antes do blur) para o clique não ser perdido
  menu.addEventListener('mousedown', (e) => {
    const it = e.target.closest('.ac-item');
    if (it) { e.preventDefault(); escolher(it.dataset.val); }
  });
  input.addEventListener('blur', () => setTimeout(fechar, 120));
  // Ao rolar qualquer container (ex.: o modal), fecha o menu em vez de fazê-lo
  // seguir o campo — senão ele flutua por cima do formulário ao rolar.
  window.addEventListener('scroll', (e) => {
    if (menu.hidden) return;
    if (e.target && e.target.closest && e.target.closest('.ac-menu')) return; // rolar a própria lista não fecha
    fechar();
  }, { capture: true, passive: true });
}
document.querySelectorAll('input[list]').forEach(ativarAutocomplete);
// Foca um campo com autocomplete próprio sem estourar a lista de sugestões — usado ao abrir
// modais (o foco automático não é uma interação do usuário pedindo sugestões).
function focarSemAbrirLista(input) {
  if (!input) return;
  input._semAbrirAuto = true;
  input.focus();
}

/* ============================================================
   SELECT custom no estilo do site (esconde o <select> nativo,
   mantém-no como fonte do valor para o formulário continuar igual)
   ============================================================ */
function customSelect(select) {
  if (select.dataset.cs) return;
  select.dataset.cs = '1';
  const wrap = document.createElement('div');
  wrap.className = 'cs';
  select.parentNode.insertBefore(wrap, select);
  wrap.appendChild(select);
  select.classList.add('cs-native');
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'cs-btn';
  const nomeAcessivel = select.getAttribute('aria-label');
  if (nomeAcessivel) btn.setAttribute('aria-label', nomeAcessivel);
  btn.setAttribute('aria-haspopup', 'listbox');
  btn.setAttribute('aria-expanded', 'false');
  btn.innerHTML = '<span class="cs-val"></span><svg class="cs-chev" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>';
  const menu = document.createElement('div');
  menu.className = 'cs-menu';
  menu.hidden = true;
  menu._csWrap = wrap; // referência de volta ao wrap: o menu não fica dentro dele (ver abaixo)
  wrap.appendChild(btn);
  // O menu é anexado ao <body> (portaled), e não ao `wrap` — assim ele escapa de qualquer
  // ancestral com overflow:hidden/auto OU que crie um "containing block" para position:fixed
  // (backdrop-filter, transform, filter, contain). É exatamente o caso do tema "comando": o
  // .modal daquele tema tem backdrop-filter, e um <select> dentro de um modal ficava com a
  // listagem cortada pela borda do modal em vez de flutuar por cima de tudo. .ac-menu/.msel-menu/
  // .pill-menu-portaled já usam esta mesma técnica.
  document.body.appendChild(menu);
  const valEl = btn.querySelector('.cs-val');
  // Mostra o TEXTO da option selecionada (ex.: "Com seguro"), não o value cru ("sim").
  // Quando o value está vazio (option placeholder "Escolher"), marca como placeholder (cinza).
  const sync = () => {
    const opt = select.selectedOptions[0] || select.options[select.selectedIndex];
    valEl.textContent = opt ? opt.textContent : '';
    // cinza só quando a option selecionada é um placeholder real (disabled), não
    // qualquer value vazio — opções legítimas como "— manter —" não são placeholder.
    valEl.classList.toggle('cs-placeholder', !!(opt && opt.disabled));
  };
  function posicionar() {
    const r = btn.getBoundingClientRect();
    ancorarMenuFixo(r, menu, r.width);
  }
  function abrir() {
    // Esconde da lista apenas placeholders reais (disabled/hidden, ex.: "Escolher").
    // Opções legítimas de value vazio (ex.: "— manter —" da edição em lote) continuam visíveis.
    menu.innerHTML = [...select.options].filter(o => !o.disabled && !o.hidden).map(o => `<div class="cs-item${o.value === select.value ? ' ativo' : ''}" data-val="${esc(o.value)}">${esc(o.textContent)}</div>`).join('');
    fecharCustomSelects(menu);
    posicionar();
    menu.hidden = false;
    wrap.classList.add('aberto');
    btn.setAttribute('aria-expanded', 'true');
  }
  function fechar() { menu.hidden = true; wrap.classList.remove('aberto'); btn.setAttribute('aria-expanded', 'false'); }
  btn.addEventListener('click', (e) => { e.stopPropagation(); menu.hidden ? abrir() : fechar(); });
  menu.addEventListener('click', (e) => {
    const it = e.target.closest('.cs-item');
    if (!it) return;
    select.value = it.dataset.val;
    select.dispatchEvent(new Event('change', { bubbles: true }));
    sync();
    fechar();
  });
  window.addEventListener('scroll', () => { if (!menu.hidden) posicionar(); }, { capture: true, passive: true });
  // Quando o VALOR do select muda por CÓDIGO (carregar cadastro p/ editar, contrato
  // preenchendo a empresa, importação, etc.), o <select> NÃO dispara 'change' — então o
  // botão ficava em "—" mesmo com o dado salvo. Espelhamos sobrescrevendo o setter de
  // .value (mesma técnica do date picker dos campos de data) e também ouvimos 'change'
  // para mudanças vindas do próprio menu/teclado. Cobre TODOS os módulos de uma vez.
  select.addEventListener('change', sync);
  const descSelVal = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value');
  Object.defineProperty(select, 'value', {
    configurable: true,
    get() { return descSelVal.get.call(this); },
    set(v) { descSelVal.set.call(this, v); sync(); },
  });
  select._syncCustom = sync;
  sync();
}
function fecharCustomSelects(except) {
  document.querySelectorAll('.cs-menu').forEach(m => { if (m !== except) { m.hidden = true; const w = m._csWrap; if (w) { w.classList.remove('aberto'); const b = w.querySelector('.cs-btn'); if (b) b.setAttribute('aria-expanded', 'false'); } } });
}
function syncCustomSelects() { document.querySelectorAll('select.cs-native').forEach(s => s._syncCustom && s._syncCustom()); }
document.querySelectorAll('form select').forEach(customSelect);
// form.reset() volta os selects ao default SEM passar pelo setter sobrescrito acima —
// re-sincroniza os botões logo após o reset (o evento 'reset' borbulha de qualquer <form>).
document.addEventListener('reset', (e) => {
  const f = e.target; if (!f || !f.querySelectorAll) return;
  setTimeout(() => f.querySelectorAll('select.cs-native').forEach(s => s._syncCustom && s._syncCustom()), 0);
});
document.addEventListener('click', () => fecharCustomSelects(null));

