// Fecha modal ao clicar no fundo (overlay) — só se o clique COMEÇOU no fundo.
// Evita que selecionar texto num campo e soltar o mouse fora feche o modal.
function fecharAoClicarNoFundo(overlayId, fecharFn) {
  const ov = document.getElementById(overlayId);
  if (!ov) return;
  _modalFechar[overlayId] = fecharFn;
  let inicioNoFundo = false;
  ov.addEventListener('mousedown', (e) => { inicioNoFundo = (e.target === ov); });
  ov.addEventListener('click', (e) => { if (e.target === ov && inicioNoFundo) fecharFn(); });
}
fecharAoClicarNoFundo('modal', fecharModal);
// Esc fecha o modal/overlay VISÍVEL mais ao topo (o de maior z-index). O #confirmModal
// se gerencia sozinho (tem seu próprio Esc dentro de confirmar()): com ele aberto, este handler
// não faz nada, senão o mesmo Esc fecharia também o modal que está por baixo da confirmação.
// EXEMPLO: modal "Links do treinamento" aberto → "Gerar novo link" abre a confirmação → Esc
//          fecha só a confirmação; um segundo Esc fecha o modal.
document.addEventListener('keydown', (e) => {
  if (e.key !== 'Escape') return;
  const conf = document.getElementById('confirmModal');
  if (conf && !conf.hidden) return;
  // Antes do modal, o Esc fecha o dropdown de multi-seleção aberto (é o que o usuário espera e,
  // dentro de um modal, esse menu flutua no <body>: fechar o modal por baixo dele o deixaria
  // órfão na tela).
  if (document.querySelector('.msel.aberto')) { e.preventDefault(); fecharMsels(null); return; }
  const abertos = [...document.querySelectorAll('.modal-overlay:not(#confirmModal)')].filter(ov => !ov.hidden);
  if (!abertos.length) return;
  const topo = abertos.reduce((a, b) =>
    ((parseInt(getComputedStyle(b).zIndex, 10) || 0) >= (parseInt(getComputedStyle(a).zIndex, 10) || 0) ? b : a));
  e.preventDefault();
  if (_modalFechar[topo.id]) _modalFechar[topo.id](); else topo.hidden = true;
});

// Acessibilidade: prende o Tab dentro do modal aberto no topo (vale para todos os
// modais de uma vez, via prenderFoco). confirmModal/midiaModal já têm o próprio.
document.addEventListener('keydown', (e) => {
  if (e.key !== 'Tab') return;
  const abertos = [...document.querySelectorAll('.modal-overlay:not(#confirmModal)')].filter(ov => !ov.hidden);
  if (!abertos.length) return;
  const topo = abertos.reduce((a, b) =>
    ((parseInt(getComputedStyle(b).zIndex, 10) || 0) >= (parseInt(getComputedStyle(a).zIndex, 10) || 0) ? b : a));
  prenderFoco(topo, e);
});

