const ESC_MAP = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, c => ESC_MAP[c]);
}

/** Pluralização pt-BR simples — evita o ternário `n === 1 ? x : y` copiado em cada
 * ponto de uso (era a causa do "multa(s) vencida(s)" nos avisos de topo de aba).
 * Ex.: `${n} ${plural(n, 'multa vencida', 'multas vencidas')}` → "1 multa vencida" /
 * "5 multas vencidas". */
function plural(n, um, muitos) { return n === 1 ? um : muitos; }

/* Ícone de aviso do .ds-alert — o mesmo triângulo que o piloto da Frota usa em
 * .v2-ofi-ico (app.js, faixaOficinaV2), reaproveitado por qualquer consumidor do
 * componente genérico. Cor vem de currentColor: a variante de severidade decide,
 * o SVG nunca escreve cor própria. */
const ICONE_DS_ALERT_AVISO = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M10.3 3.6 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.6a2 2 0 0 0-3.4 0z"/><path d="M12 9v4"/><path d="M12 17h.01"/></svg>';

/**
 * Monta (e liga o clique/teclado de) uma faixa `.ds-alert` com resumo recolhido +
 * lista expansível de itens — o componente genérico para qualquer aviso de "N
 * registros vencidos/a vencer" no topo de uma aba (docs/DESIGN.md, registro do
 * componente de alerta). Não usar para alerta de status ÚNICO sem lista (aí é só
 * `.ds-alert` puro, sem `itens`) — ver a faixa de backup do Início.
 *
 * `host` precisa ter `id` estável (vira a base do id da lista/botão) e nascer
 * `hidden` no HTML, sem classe própria — quem estiliza é o `.ds-alert` injetado.
 *
 * Ex.: montarFaixaAlerta({
 *   host: document.getElementById('multasAlertas'),
 *   itens: alertasMulta().map(a => ({
 *     id: a.m.id, rotuloId: a.m.placa || 'Sem placa', codigo: true, // placa é código → mono
 *     desc: a.m.autoInfracao ? 'Nº ' + a.m.autoInfracao : (a.m.descricao || 'Multa'),
 *     info: a.rotulo, severidade: a.classe === 'vencido' ? 'error' : 'warning',
 *     onClick: () => abrirMultaModal(a.m.id),
 *   })),
 *   singular: 'multa vencida ou a vencer', plural: 'multas vencidas ou a vencer',
 *   sufixo: ` em até ${DIAS_AVISO_MULTA} dias`,
 *   acaoSingular: 'multa', acaoPlural: 'multas',
 * }); // preenche #multasAlertas com a faixa; clique num item chama onClick().
 */
function montarFaixaAlerta({ host, itens, singular, plural: plur, sufixo = '', acaoSingular, acaoPlural }) {
  if (!host) return;
  if (!itens.length) { host.hidden = true; host.innerHTML = ''; return; }
  host.hidden = false;
  host.classList.add('ds-alert-faixa'); // respiro abaixo da faixa (07-alert.css), igual à da Frota
  const n = itens.length;
  const listaId = `${host.id}-lista`;
  const btnId = `${host.id}-ver`;
  host.innerHTML = `<div class="ds-alert ds-alert-warning">
      <div class="ds-alert-icon">${ICONE_DS_ALERT_AVISO}</div>
      <div class="ds-alert-content">
        <div class="ds-alert-cab"><span class="ds-alert-title">${esc(`${n} ${plural(n, singular, plur)}${sufixo}`)}</span></div>
        <ul class="ds-alert-lista" id="${listaId}" aria-label="${esc(plural(n, singular, plur))}" hidden>${itens.map((it, i) => `
          <li class="ds-alert-item">
            <button type="button" class="ds-alert-linha ds-alert-${it.severidade}" data-idx="${i}"
              aria-label="${esc(`${it.rotuloId}, ${it.desc}, ${it.info}`)}">
              <span class="ds-alert-linha-id${it.codigo ? ' ds-alert-linha-codigo' : ''}">${esc(it.rotuloId)}</span>
              <span class="ds-alert-linha-desc">${esc(it.desc)}</span>
              <span class="ds-alert-linha-info">${esc(it.info)}</span>
            </button>
          </li>`).join('')}</ul>
      </div>
      <button type="button" class="ds-alert-action" id="${btnId}" aria-expanded="false" aria-controls="${listaId}">Ver ${n} ${esc(plural(n, acaoSingular, acaoPlural))}</button>
    </div>`;
  const btn = host.querySelector(`#${btnId}`);
  const lista = host.querySelector(`#${listaId}`);
  btn.addEventListener('click', () => {
    const abrir = lista.hidden;
    lista.hidden = !abrir;
    btn.setAttribute('aria-expanded', String(abrir));
  });
  // Escape recolhe só quando o foco está DENTRO da faixa — não sequestra o Escape de
  // quem tem modal/painel de filtros/multiselect aberto (mesmo comportamento do piloto
  // da Frota, .v2-ofi-*, que este componente generaliza). Ligado UMA vez por host e
  // procurando lista/botão na hora: a faixa é remontada a cada render (o Acompanhamento
  // remonta a cada tecla da busca) e um listener por chamada se acumulava, cada um
  // segurando a faixa antiga na memória.
  if (!host.dataset.faixaEsc) {
    host.dataset.faixaEsc = '1';
    host.addEventListener('keydown', (e) => {
      const l = host.querySelector('.ds-alert-lista'), b = host.querySelector('.ds-alert-action');
      if (e.key === 'Escape' && l && b && !l.hidden) {
        l.hidden = true;
        b.setAttribute('aria-expanded', 'false');
        b.focus();
      }
    });
  }
  host.querySelectorAll('.ds-alert-linha').forEach((el, i) => {
    el.addEventListener('click', () => itens[i].onClick());
  });
}

/* ============================================================
   DESIGN SYSTEM — identidade visual única (ex-"piloto design-v2")
   ------------------------------------------------------------
   Consolidação visual (ago/2026): o Design System é a identidade do app, sem
   opt-in nem kill switch — `design-v2` é escrita direto no `<body>` do
   index.html (não aqui: este script carrega no fim do body e a classe chegaria
   depois do primeiro paint, fazendo a tela piscar sem estilo). O antigo
   `?design=off` foi aposentado: o styles.css não guarda mais uma aparência
   alternativa mantida, então desligar só deixava o app sem estilo.
   `frontend/design-v2.css` continua com o nome histórico por causa das
   referências no restante do código/CSS.

   Alto contraste NÃO desliga o Design System (ver sincronizarAltoContraste
   acima) — as duas coisas são independentes.
   ============================================================ */
/* O SHELL (sidebar, topbar, fundo e os menus que o app porta para o <body>) só é vestido pelo
   Design System quando a view EM CENA é um módulo migrado — quem sai de um módulo migrado
   recebe de volta o tema que escolheu.

   Antes isso era feito no CSS com `body.design-v2:has(#frota.view.active)`. Virou uma classe
   no <body> por dois motivos: tira o nome do módulo de dentro do CSS (migrar o próximo passa
   a ser só acrescentar `ds-modulo` na <section> dele) e evita reavaliar um `:has` no <body> a
   cada troca entre as 28 abas.

   ⚠️ TODO caminho de troca de aba passa pelo handler de clique de `.tab` — deep link,
   popstate, atalhos `data-goto` e a restauração no boot todos terminam em `tab.click()`. Por
   isso basta chamar daqui (boot/troca de tema) e de lá (troca de aba). */
function sincronizarShellDS() {
  const ativa = document.querySelector('.view.active');
  document.body.classList.toggle('ds-shell', !!ativa && ativa.classList.contains('ds-modulo'));
}
sincronizarShellDS();

// Densidade das tabelas (compacta/confortável) — antes só a Frota tinha o controle;
// agora TODA aba com tabela padrão (`.tabela-wrap`) ganha o toggle, injetado no fim
// de cada `.toolbar` da section. Preferência local por aba (chave `dens-<sectionId>`),
// sem ida ao servidor: é escolha de exibição, não dado do sistema. O atributo
// `data-densidade` vai na PRÓPRIA section (a regra genérica de 03-base.css casa
// `.ds-modulo[data-densidade="confortavel"]`), então todas as sub-abas acompanham.
// Exemplo de uso: aplicarDensidade(document.getElementById('multas'), 'confortavel')
//   → linhas da tabela de Multas passam a 40px e a escolha fica salva em
//   localStorage['dens-multas']; os botões da section marcam aria-pressed sozinhos.
function aplicarDensidade(sec, modo) {
  if (!sec) return;
  const valor = modo === 'confortavel' ? 'confortavel' : 'compacta';
  sec.dataset.densidade = valor;
  sec.querySelectorAll('.v2-dens-btn').forEach((b) =>
    b.setAttribute('aria-pressed', String(b.dataset.densidade === valor)));
  try { localStorage.setItem('dens-' + sec.id, valor); } catch (e) { /* ignora */ }
}
function injetarTogglesDensidade() {
  const html =
    '<div class="v2-densidade" data-densidade-toggle role="group" aria-label="Densidade da tabela">' +
    '<button type="button" class="v2-dens-btn" data-densidade="compacta" aria-pressed="true" title="Linhas compactas" aria-label="Linhas compactas">' +
    '<svg viewBox="0 0 16 16" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" aria-hidden="true"><path d="M2.5 3.5h11M2.5 6.5h11M2.5 9.5h11M2.5 12.5h11"/></svg></button>' +
    '<button type="button" class="v2-dens-btn" data-densidade="confortavel" aria-pressed="false" title="Linhas confortáveis" aria-label="Linhas confortáveis">' +
    '<svg viewBox="0 0 16 16" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" aria-hidden="true"><path d="M2.5 4h11M2.5 8h11M2.5 12h11"/></svg></button></div>';
  // migração da chave do piloto (Frota) — o atributo agora vive na section, não em #frota-lista
  try {
    const antiga = localStorage.getItem('frota-densidade');
    if (antiga) { localStorage.setItem('dens-frota', antiga); localStorage.removeItem('frota-densidade'); }
  } catch (e) { /* ignora */ }
  document.querySelectorAll('main section.ds-modulo').forEach((sec) => {
    if (!sec.id || !sec.querySelector('.tabela-wrap')) return;
    sec.querySelectorAll('.toolbar').forEach((tb) => {
      if (!tb.querySelector('[data-densidade-toggle]')) tb.insertAdjacentHTML('beforeend', html);
    });
    let salvo = 'compacta';
    try { salvo = localStorage.getItem('dens-' + sec.id) || 'compacta'; } catch (e) { /* ignora */ }
    aplicarDensidade(sec, salvo);
  });
}
document.addEventListener('click', (e) => {
  const b = e.target.closest('[data-densidade-toggle] .v2-dens-btn');
  if (b) aplicarDensidade(b.closest('section.ds-modulo'), b.dataset.densidade);
});
injetarTogglesDensidade();

// Chip de filtro ativo: clicar remove SÓ aquele valor (o "Limpar tudo" continua
// sendo o limparFiltros de sempre). Delegado — os chips são recriados a cada render.
document.getElementById('frotaChips')?.addEventListener('click', (e) => {
  const b = e.target.closest('[data-chip-tipo]');
  if (!b) return;
  const tipo = b.dataset.chipTipo;
  if (tipo === 'tudo') { limparFiltros(); return; }
  if (tipo === 'busca') { document.getElementById('busca').value = ''; renderTabela(); return; }
  const m = MSEL[tipo];
  if (!m) return;
  m.setSelecionados(m.getSelecionados().filter((x) => x !== b.dataset.chipVal));
  renderTabela();
});

/* ---------- Painel de filtros (componente genérico, um por aba) ----------
   O painel É o `.filtros` de sempre — os mesmos multiselects, os mesmos handlers,
   o mesmo "Limpar". Aqui só entram: abrir/fechar, o contador do botão e os
   atributos de acessibilidade, que são POSTOS E RETIRADOS conforme o Design System:
   fora dele o `.filtros` volta a ser uma fileira inline, e anunciar "diálogo" numa
   fileira seria regressão de leitor de tela.
   Tudo é resolvido por getElementById na hora (sem const de módulo) porque
   o boot do Design System roda antes deste trecho ser avaliado.

   Ex. de uso (nasceu na Frota; para registrar o painel de outra aba):
     // HTML: <button id="xFiltrosBtn" class="v2-filtros-btn" aria-controls="xFiltrosPainel">…</button>
     //       <div class="filtros" id="xFiltrosPainel"><span class="v2-filtros-tit" id="xFiltrosTit">…</span>…</div>
     const p = criarPainelFiltros({
       btnId: 'xFiltrosBtn', painelId: 'xFiltrosPainel', contId: 'xFiltrosCont', titId: 'xFiltrosTit',
       contarAtivos: () => getSel('fAlgo').length,   // → contador "(n)" do botão
       aoAtualizar: (n) => { … },                     // opcional (ex.: desabilitar o "Limpar")
     });
     p.atualizar(); // chamar no render da aba (recalcula contador/aria) */
// `var` de propósito: este arquivo já teve código de boot que tocava a lista ANTES
// deste trecho ser avaliado — com const/let o acesso cairia na zona morta temporal e
// derrubava o boot. Com var o hoisting entrega undefined e o `|| []` cobre esse caso.
var PAINEIS_FILTROS = PAINEIS_FILTROS || [];
function criarPainelFiltros(cfg) {
  const el = (id) => (id ? document.getElementById(id) : null);
  const inst = {
    cfg,
    aberto() {
      const p = el(cfg.painelId);
      return !!p && p.classList.contains('aberto');
    },
    abrir() {
      const btn = el(cfg.btnId), painel = el(cfg.painelId);
      if (!btn || !painel) return;
      fecharKebab(false); // um menu flutuante de cada vez
      painel.classList.add('aberto');
      btn.setAttribute('aria-expanded', 'true');
      // No celular o painel vira um sheet fixo no rodapé (design-mobile.css): o left
      // inline da ancoragem venceria o CSS, então aqui ele é limpo em vez de calculado.
      if (window.matchMedia('(max-width: 767px)').matches) { painel.style.left = ''; return; }
      // ancora no botão sem deixar vazar pela direita da barra (o painel é absolute
      // dentro da barra, que no Design System é position:relative)
      const barra = painel.offsetParent || btn.parentElement;
      const limite = Math.max(0, barra.clientWidth - painel.offsetWidth);
      painel.style.left = Math.min(btn.offsetLeft, limite) + 'px';
    },
    fechar(devolverFoco = false) {
      const btn = el(cfg.btnId), painel = el(cfg.painelId);
      if (!painel) return;
      const estava = painel.classList.contains('aberto');
      painel.classList.remove('aberto');
      if (btn) btn.setAttribute('aria-expanded', 'false');
      if (estava) fecharMsels(null); // um multiselect aberto não pode sobreviver ao painel que o contém
      if (estava && devolverFoco && btn) btn.focus();
    },
    atualizar() {
      const btn = el(cfg.btnId);
      if (!btn) return;
      const n = cfg.contarAtivos ? cfg.contarAtivos() : 0;
      const cont = el(cfg.contId);
      if (cont) { cont.textContent = n ? String(n) : ''; cont.hidden = !n; }
      btn.classList.toggle('tem-filtros', !!n);
      // o rótulo acessível começa por "Filtros" (o texto visível) e só então diz a contagem
      btn.setAttribute('aria-label', n ? `Filtros, ${n} ${n === 1 ? 'ativo' : 'ativos'}` : 'Filtros, nenhum ativo');
      if (cfg.aoAtualizar) cfg.aoAtualizar(n);
    },
    // Vocabulário de diálogo do painel (o Design System é a identidade única do app,
    // então os atributos são fixos — só o contador precisa ser recalculado depois).
    sincronizar() {
      const painel = el(cfg.painelId), btn = el(cfg.btnId);
      if (!painel) return;
      painel.setAttribute('role', 'dialog');
      if (cfg.titId) painel.setAttribute('aria-labelledby', cfg.titId);
      if (btn) btn.setAttribute('aria-haspopup', 'dialog');
      inst.atualizar();
    },
  };
  PAINEIS_FILTROS.push(inst);
  // Cada instância se sincroniza ao nascer para ganhar os atributos de diálogo.
  inst.sincronizar();
  // Sem focus trap: sair do painel pelo Tab simplesmente fecha e segue a navegação.
  el(cfg.painelId)?.addEventListener('focusout', (e) => {
    if (!inst.aberto()) return;
    const indo = e.relatedTarget;
    if (indo && !indo.closest(`#${cfg.painelId}, #${cfg.btnId}`)) inst.fechar(false);
  });
  return inst;
}
function painelFiltrosAbertoQualquer() { return PAINEIS_FILTROS.find((p) => p.aberto()) || null; }
// Contador "(n)" recalculado após QUALQUER clique/change da página (agendado para depois
// do handler que mudou o filtro). Antes o recálculo ficava preso a interações dentro do
// painel — mas vários "Limpar busca" vivem FORA dele (sub-abas do EPI, por ex.) e limpam
// via MSEL[..].limpar(), que não dispara onChange: o filtro zerava e o "(2)" ficava aceso.
// Custo desprezível: contarAtivos é getSel sobre arrays em memória, ~10 painéis no total.
{
  let _contadorAgendado = false;
  const reagendar = () => {
    if (_contadorAgendado) return;
    _contadorAgendado = true;
    setTimeout(() => { _contadorAgendado = false; (PAINEIS_FILTROS || []).forEach((p) => p.atualizar()); }, 0);
  };
  document.addEventListener('click', reagendar);
  document.addEventListener('change', reagendar);
}
// Toggle no botão + clique fora fecha (sem roubar o foco). Cliques nos itens de filtro
// ficam DENTRO do painel, então escolher uma opção não fecha o painel. Delegado: um
// listener para todos os painéis registrados.
document.addEventListener('click', (e) => {
  const btn = e.target.closest('.v2-filtros-btn');
  if (btn) {
    const inst = PAINEIS_FILTROS.find((p) => p.cfg.btnId === btn.id);
    if (inst) {
      e.stopPropagation();
      if (inst.aberto()) inst.fechar(true); else { PAINEIS_FILTROS.forEach((p) => p.fechar(false)); inst.abrir(); }
      return;
    }
  }
  const aberto = painelFiltrosAbertoQualquer();
  // `.dp-cal` (popover do calendário, no <body>): escolher uma data no De/Até não é "clicar fora"
  if (aberto && !e.target.closest(`#${aberto.cfg.painelId}, #${aberto.cfg.btnId}, .dp-cal`)) aberto.fechar(false);
});
document.addEventListener('keydown', (e) => {
  const aberto = painelFiltrosAbertoQualquer();
  if (e.key === 'Escape' && aberto) { e.stopPropagation(); aberto.fechar(true); }
});

/* ----- Instância da Frota (a 1ª; as demais abas registram as suas nos rollouts) ----- */
function filtrosAtivosFrota() {
  return FILTROS_FROTA.reduce((n, [fid]) => n + (MSEL[fid] ? MSEL[fid].getSelecionados().length : 0), 0);
}
// "Há recorte na tela?" — busca conta como filtro. Fonte única: os rótulos dos KPIs, o texto da
// faixa de oficina e o estado do "Limpar filtros" precisam concordar sobre o que é um recorte.
function temFiltroOuBuscaFrota(nAtivos) {
  const busca = document.getElementById('busca');
  return (nAtivos ?? filtrosAtivosFrota()) > 0 || !!(busca && busca.value.trim());
}
// "Limpar filtros" só faz sentido quando há o que limpar: o botão mora dentro do
// painel e um botão aceso que não faz nada é promessa falsa.
function atualizarLimparFiltros(nAtivos) {
  const btn = document.getElementById('btnLimpar');
  if (!btn) return;
  btn.disabled = !temFiltroOuBuscaFrota(nAtivos);
}
const PAINEL_FILTROS_FROTA = criarPainelFiltros({
  btnId: 'frotaFiltrosBtn', painelId: 'frotaFiltrosPainel', contId: 'frotaFiltrosCont', titId: 'frotaFiltrosTit',
  contarAtivos: filtrosAtivosFrota,
  aoAtualizar: atualizarLimparFiltros,
});
function atualizarBotaoFiltros() { PAINEL_FILTROS_FROTA.atualizar(); }

/* ---------- Menu "⋯" (mais ações) — componente genérico por toolbar ----------
   Agrupa as ações secundárias (Importar/Exportar/Relatório/...) num menu flutuante,
   deixando a linha principal com busca + Filtros + ⋯ + botão primário. Os <button>
   originais são MOVIDOS para dentro do menu (nunca duplicados): ids, handlers e as
   regras de permissão que os escondem por `hidden` continuam valendo — item oculto
   simplesmente não aparece no menu. Fora do Design System o wrapper e o menu são
   `display:contents` no CSS: os botões voltam a ser itens inline da toolbar.

   Ex. de uso (HTML — basta envolver os botões existentes; nenhum JS por aba):
     <div class="toolbar-mais">
       <button type="button" class="v2-kebab-btn" aria-haspopup="menu" aria-expanded="false" aria-label="Mais ações">⋯</button>
       <div class="v2-kebab-menu" role="menu">
         <button id="btnImportar" class="btn btn-ghost">⬆ Importar</button>
         <button id="btnExportar" class="btn btn-ghost">⬇ Exportar</button>
       </div>
     </div> */
var KEBAB_ABERTO = null; // { btn, menu, dono } — `var` pelo mesmo motivo de PAINEIS_FILTROS (o idioma `X = X || null` estoura TDZ com const/let)
function fecharKebab(devolverFoco = false) {
  if (!KEBAB_ABERTO) return;
  const { btn, menu, dono } = KEBAB_ABERTO;
  KEBAB_ABERTO = null;
  menu.classList.remove('aberto');
  menu.removeAttribute('style'); // limpa o position:fixed que ancorarMenuFixo aplicou
  btn.setAttribute('aria-expanded', 'false');
  // devolve o menu ao dono: permissões e encaixarBotaoDesfazer precisam achar os botões no lugar
  if (dono && dono.isConnected && menu.parentElement !== dono) dono.appendChild(menu);
  if (devolverFoco) btn.focus();
}
function abrirKebab(btn) {
  const dono = btn.closest('.toolbar-mais');
  const menu = dono && dono.querySelector('.v2-kebab-menu');
  if (!menu) return;
  fecharKebab(false);
  PAINEIS_FILTROS.forEach((p) => p.fechar(false)); // um menu flutuante de cada vez
  // Mede o botão ANTES de abrir o menu: como .toolbar-mais é display:contents, o menu aberto vira
  // item de flex da PRÓPRIA barra e, numa barra lotada (ex. .func-topo), força quebra de linha — o ⋯
  // se desloca e o menu era ancorado nesse retângulo errado. Como ancorarMenuFixo porta o menu para o
  // <body> logo em seguida, a barra voltava ao normal e o menu ficava congelado longe do botão.
  const r = btn.getBoundingClientRect();
  sincronizarKebabMobile(dono); // itens só do celular (Selecionar todos/Desfazer), antes de medir
  menu.classList.add('aberto'); // antes de ancorar: display:none não tem medida
  ancorarMenuFixo(r, menu, 200);
  menu.hidden = false;
  btn.setAttribute('aria-expanded', 'true');
  KEBAB_ABERTO = { btn, menu, dono };
}
// O botão "⋯" só aparece se o menu tiver ao menos um item visível (permissões podem
// esconder todos — ex. perfil só-leitura numa aba em que tudo no menu é de edição).
// Chamar depois de aplicar permissões e ao trocar de aba.
function sincronizarKebabs() {
  document.querySelectorAll('.toolbar-mais').forEach((dono) => {
    const kb = dono.querySelector('.v2-kebab-btn');
    const menu = dono.querySelector('.v2-kebab-menu');
    if (!kb || !menu) return;
    const temItem = [...menu.querySelectorAll('button, a')].some((el) =>
      !el.hidden && el.style.display !== 'none' && !el.closest('[hidden]'));
    kb.hidden = !temItem;
  });
}
document.addEventListener('click', (e) => {
  const kb = e.target.closest('.v2-kebab-btn');
  if (kb) {
    e.stopPropagation();
    if (KEBAB_ABERTO && KEBAB_ABERTO.btn === kb) fecharKebab(true); else abrirKebab(kb);
    return;
  }
  // clique num item do menu: o handler do próprio botão já rodou (bubbling); só fechar
  if (KEBAB_ABERTO) fecharKebab(false);
});
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && KEBAB_ABERTO) { e.stopPropagation(); fecharKebab(true); }
});

/* ----- Painéis de filtros das demais abas (mesmo componente da Frota) -----
   Todos resolvem por getElementById/getSel NA HORA, então podem nascer aqui
   mesmo que os multiselects da aba ainda não existam (getSel devolve []).
   O contador se atualiza sozinho por interação dentro do painel (ver
   criarPainelFiltros); valores iniciais são sempre vazios. */
const contaMsels = (ids) => ids.reduce((n, fid) => n + getSel(fid).length, 0);
const contaInputs = (ids) => ids.reduce((n, id) => n + (document.getElementById(id)?.value ? 1 : 0), 0);
// chips de período (Almoxarifado/EPI): conta 1 quando o chip aceso não é o "Tudo" padrão
const contaChipPeriodo = (contId) => {
  const on = document.querySelector(`#${contId} .forn-chip.on`);
  return on && on.dataset.periodo !== 'tudo' ? 1 : 0;
};
criarPainelFiltros({
  btnId: 'rastFiltrosBtn', painelId: 'rastFiltrosPainel', contId: 'rastFiltrosCont', titId: 'rastFiltrosTit',
  contarAtivos: () => contaMsels(['frSituacao', 'frTipo', 'frPlaca']) + contaInputs(['frDevDe', 'frDevAte']),
});
