  btnId: 'mntFiltrosBtn', painelId: 'mntFiltrosPainel', contId: 'mntFiltrosCont', titId: 'mntFiltrosTit',
  contarAtivos: () => contaMsels(['fmntPlaca', 'fmntPeriodo', 'fmntCentro', 'fmntTipo', 'fmntMontadora']),
