  contarAtivos: () => contaMsels(['fepiEmpresa', 'fepiContrato', 'fepiColab', 'fepiTipo', 'fepiSitCA', 'fepiMes'])
    + contaInputs(['epiDe', 'epiAte']) + contaChipPeriodo('epiAtalhos'),
