// ----- Termos de multas: modelos + PDFs assinados em veículo → motorista -----
function trocarSubMultas(sub) {
  const alvo = document.querySelector(`#multasSubtabs .subtab[data-sub="${sub}"]`);
  if (!alvo) return;
  document.querySelectorAll('#multasSubtabs .subtab').forEach(b => b.classList.toggle('active', b === alvo));
  document.querySelectorAll('#multas > .subview').forEach(v => v.classList.toggle('active', v.id === sub));
  if (sub === 'multas-termos') carregarTermosMultas();
  if (sub === 'multas-mensal') renderMultasMensal();
}
document.querySelectorAll('#multasSubtabs .subtab').forEach(b => {
  b.onclick = () => { if (!b.classList.contains('active')) trocarSubMultas(b.dataset.sub); };
});

async function carregarTermosMultas() {
  try {
    const r = await fetch('/api/termos-multas', { cache: 'no-store' });
    if (r.status === 401) { window.location = '/login'; return; }
    if (!r.ok) throw new Error();
    const dados = await r.json();
    TERMOS_MULTAS = Array.isArray(dados.termos) ? dados.termos : [];
    PASTAS_TERMOS_MULTAS = Array.isArray(dados.pastas) ? dados.pastas : [];
    while (CAMINHO_TERMOS_MULTAS.length && !PASTAS_TERMOS_MULTAS.some(p => p.id === CAMINHO_TERMOS_MULTAS.at(-1))) CAMINHO_TERMOS_MULTAS.pop();
    renderTermosMultas();
  } catch (e) { toast('Erro ao carregar os termos de multas.', 'erro'); }
}
const chavePastaTermo = (v) => String(v || '').trim().toLocaleLowerCase('pt-BR');
const pastaTermoPorId = (id) => PASTAS_TERMOS_MULTAS.find(p => p.id === id);
const pastaTermoAtualId = () => CAMINHO_TERMOS_MULTAS.at(-1) || '';
function caminhoDaPastaTermo(id) {
  const caminho = [], visitadas = new Set();
  while (id && !visitadas.has(id)) {
    visitadas.add(id);
    const pasta = pastaTermoPorId(id); if (!pasta) break;
    caminho.unshift(pasta);
    id = pasta.pastaPaiId;
  }
  return caminho;
}
function rotuloCaminhoPastaTermo(id) {
  const nomes = caminhoDaPastaTermo(id).map(p => p.nome);
  return nomes.length ? `Início / ${nomes.join(' / ')}` : 'Início';
}
function termoMultaCasaBusca(t, busca) {
  return !busca || [t.placa, t.motorista, t.titulo, t.descricao, t.arquivo && t.arquivo.nome]
    .some(v => String(v || '').toLocaleLowerCase('pt-BR').includes(busca));
}
function marcadorPastaTermo(p) {
  if (p.id === 'TP-MODELOS') return 'data-termos-modelos';
  const pai = pastaTermoPorId(p.pastaPaiId);
  if (pai && pai.id === 'TP-CARROS') return `data-termo-placa="${esc(p.nome)}"`;
  if (pai && pastaTermoPorId(pai.pastaPaiId)?.id === 'TP-CARROS') return `data-termo-motorista="${esc(p.nome)}"`;
  return '';
}
function renderTermosMultas() {
  const atualId = pastaTermoAtualId();
  const busca = chavePastaTermo(document.getElementById('termosMultaBusca')?.value);
  const todasPastas = PASTAS_TERMOS_MULTAS.filter(p => p.pastaPaiId === atualId);
  const todosCards = TERMOS_MULTAS.filter(t => (t.pastaId || '') === atualId);
  const pastas = todasPastas.filter(p => !busca || chavePastaTermo(p.nome).includes(busca)).sort((a, b) => a.nome.localeCompare(b.nome, 'pt-BR'));
  const cards = todosCards.filter(t => termoMultaCasaBusca(t, busca)).sort((a, b) => Number(b.atualizadoEm || 0) - Number(a.atualizadoEm || 0));
  const pastaHead = document.getElementById('termosMultaPastaHead');
  const atual = pastaTermoPorId(atualId);
  pastaHead.hidden = !atual;
  if (atual) {
    document.getElementById('termosMultaNivel').textContent = rotuloCaminhoPastaTermo(atual.pastaPaiId);
    document.getElementById('termosMultaTitulo').textContent = atual.nome;
    document.getElementById('termosMultaResumo').textContent = `${todasPastas.length} subpasta(s) · ${todosCards.length} arquivo(s)`;
  }
  const podeEditar = permissaoAtual('multas') === 'editar';
  document.getElementById('btnAddPastaTermos').hidden = !podeEditar;
  document.getElementById('btnAddTermoModelo').hidden = !podeEditar;
  document.getElementById('btnAddTermoAssinado').hidden = !podeEditar;
  document.getElementById('termosMultaPastas').innerHTML = pastas.map(p => {
    const itens = PASTAS_TERMOS_MULTAS.filter(x => x.pastaPaiId === p.id).length + TERMOS_MULTAS.filter(t => t.pastaId === p.id).length;
    return `<article class="documento-empresa-card" data-pasta-id="${esc(p.id)}">
      <button type="button" class="documento-empresa-abrir" data-abrir-pasta="${esc(p.id)}" ${marcadorPastaTermo(p)} aria-label="Abrir pasta ${esc(p.nome)}, ${itens} item(ns)">
        <span class="doc-emp-pasta" aria-hidden="true">${svgIconeDocumentoEmpresa('pasta')}</span>
        <span class="doc-emp-corpo"><strong>${esc(p.nome)}</strong><span>${itens} item(ns)</span></span>
        <span class="doc-emp-rodape"><span></span><span class="doc-emp-abrir">Abrir →</span></span>
      </button>${podeEditar ? `<div class="termo-pasta-acoes"><button type="button" class="empresa-acao-icone editar" data-pasta-acao="renomear" aria-label="Renomear pasta ${esc(p.nome)}" title="Renomear">${ICONE_LAPIS}</button><button type="button" class="empresa-acao-icone excluir" data-pasta-acao="excluir" aria-label="Excluir pasta ${esc(p.nome)}" title="Excluir">${ICONE_LIXEIRA}</button></div>` : ''}
    </article>`;
  }).join('');
  // Array-adaptador da prévia: mesma ordem dos cards (data-i = índice) — ver _pdfPreviewListas.
  _termosMultaPrev = cards.map(t => ({ id: t.arquivo && t.arquivo.id || '', tipo: t.arquivo && t.arquivo.tipo || '', nome: t.titulo || (t.arquivo && t.arquivo.nome) || '' }));
  document.getElementById('termosMultaCards').innerHTML = cards.map((t, i) => {
    const formato = t.arquivo && t.arquivo.tipo === 'application/pdf' ? 'PDF' : 'DOCX';
    const meta = t.tipo === 'modelo' ? 'Modelo editável' : `${t.placa || 'Sem veículo'} · ${t.motorista || 'Sem motorista'}`;
    return `<article class="empresa-card documento-card" data-id="${esc(t.id)}" data-termo-id="${esc(t.id)}" data-i="${i}">
      <div class="empresa-card-top">${miniaturaDocCard(t.arquivo, i, formato)}<div><span class="empresa-tag">${t.tipo === 'modelo' ? 'MODELO' : esc(t.placa)}</span><h3>${esc(t.titulo)}</h3></div></div>
      <p class="empresa-descricao">${esc(t.descricao || 'Sem descrição.')}</p>
      <div class="documento-meta"><span>${esc(meta)}</span><span title="Nome do arquivo">${esc(t.arquivo && t.arquivo.nome || 'Arquivo')}</span></div>
      <div class="empresa-acoes"><a class="btn btn-ghost small" href="/api/midia/${encodeURIComponent(t.arquivo && t.arquivo.id || '')}" download="${esc(t.arquivo && t.arquivo.nome || 'termo')}">Baixar ${formato}</a>${podeEditar ? `<button type="button" class="btn btn-ghost small" data-acao="mover">Mover</button><button type="button" class="btn btn-ghost small" data-acao="editar">Editar</button><button type="button" class="btn btn-ghost small danger" data-acao="excluir">Excluir</button>` : ''}</div>
    </article>`;
  }).join('');
  const vazio = !pastas.length && !cards.length;
  document.getElementById('termosMultaVazio').hidden = !vazio;
  document.getElementById('termosMultaContagem').textContent = `${pastas.length} pasta(s) · ${cards.length} arquivo(s)`;
  _termosMultaPrev.forEach((m) => { if (m.tipo === 'application/pdf') pedirPdfPreview(m); });
}
// Clique no card (fora dos botões de ação) abre o termo no visor.
document.getElementById('termosMultaCards')?.addEventListener('click', (e) => {
  if (e.target.closest('.empresa-acoes, button, a')) return;
  const card = e.target.closest('.documento-card[data-i]');
  if (card) abrirVisorDocCard(_termosMultaPrev, +card.dataset.i);
});
function atualizarDatalistsTermosMultas() {
  const placas = [...new Set([...VEICULOS.map(v => v.placa), ...TERMOS_MULTAS.map(t => t.placa)].filter(Boolean))].sort();
  const cad = typeof CADASTROS !== 'undefined' && Array.isArray(CADASTROS.responsaveis) ? CADASTROS.responsaveis : [];
  const motoristas = [...new Set([...cad, ...TERMOS_MULTAS.map(t => t.motorista)].filter(Boolean))].sort((a, b) => String(a).localeCompare(String(b), 'pt-BR'));
  document.getElementById('listaPlacasTermos').innerHTML = placas.map(v => `<option value="${esc(v)}"></option>`).join('');
  document.getElementById('listaMotoristasTermos').innerHTML = motoristas.map(v => `<option value="${esc(v)}"></option>`).join('');
}
function abrirTermoMultaModal(tipo, item = null) {
  const f = document.getElementById('formTermoMulta');
  f.reset();
  editandoTermoMultaId = item && item.id || null;
  arquivoTermoMultaAtual = item && item.arquivo || null;
  pastaTermoMultaAtualId = item ? (item.pastaId || '') : pastaTermoAtualId();
  tipo = item && item.tipo || tipo || 'assinado';
  f.elements.tipo.value = tipo;
  if (item) ['placa', 'motorista', 'titulo', 'descricao'].forEach(k => { f.elements[k].value = item[k] || ''; });
  const assinado = tipo !== 'modelo';
  document.querySelectorAll('#formTermoMulta .termo-assinado-campo').forEach(el => { el.hidden = !assinado; });
  f.elements.placa.required = assinado;
  f.elements.motorista.required = assinado;
  f.elements.arquivo.required = !item;
  f.elements.arquivo.accept = assinado ? '.pdf,application/pdf' : '.pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document';
  document.getElementById('termoMultaModalTitulo').textContent = `${item ? 'Editar' : 'Novo'} ${assinado ? 'termo assinado' : 'modelo de termo'}`;
  document.getElementById('termoMultaModalAjuda').textContent = assinado ? 'Envie o PDF já preenchido e assinado pelo motorista.' : 'Salve um PDF ou DOCX pronto para baixar, preencher e editar.';
  document.getElementById('termoMultaArquivoRotulo').textContent = assinado ? 'PDF assinado *' : 'Modelo em PDF ou DOCX *';
  document.getElementById('termoMultaFormatoAjuda').textContent = assinado ? 'Somente PDF, até 9 MB.' : 'PDF ou DOCX, até 9 MB.';
  document.getElementById('termoMultaDestino').textContent = `Salvar em: ${rotuloCaminhoPastaTermo(pastaTermoMultaAtualId)}`;
  const atual = document.getElementById('termoMultaArquivoAtual');
  atual.hidden = !arquivoTermoMultaAtual;
  atual.textContent = arquivoTermoMultaAtual ? `Arquivo atual: ${arquivoTermoMultaAtual.nome}` : '';
  atualizarDatalistsTermosMultas();
  document.getElementById('termoMultaModal').hidden = false;
  (assinado ? f.elements.placa : f.elements.titulo).focus();
}
function fecharTermoMultaModal() {
  document.getElementById('termoMultaModal').hidden = true;
  editandoTermoMultaId = null;
  arquivoTermoMultaAtual = null;
  pastaTermoMultaAtualId = '';
}
function abrirPastaTermoMultaModal(item = null) {
  editandoPastaTermoMultaId = item && item.id || null;
  const f = document.getElementById('formPastaTermoMulta'); f.reset();
  if (item) f.elements.nome.value = item.nome;
  document.getElementById('pastaTermoMultaTitulo').textContent = item ? 'Renomear pasta' : 'Nova pasta';
  document.getElementById('pastaTermoMultaAjuda').textContent = item ? `Pasta em ${rotuloCaminhoPastaTermo(item.pastaPaiId)}` : `Criar dentro de ${rotuloCaminhoPastaTermo(pastaTermoAtualId())}`;
  document.getElementById('pastaTermoMultaModal').hidden = false;
  f.elements.nome.focus(); if (item) f.elements.nome.select();
}
function fecharPastaTermoMultaModal() { document.getElementById('pastaTermoMultaModal').hidden = true; editandoPastaTermoMultaId = null; }
function abrirMoverTermoMultaModal(item) {
  movendoTermoMultaId = item.id;
  const f = document.getElementById('formMoverTermoMulta');
  const opcoes = [{ id: '', rotulo: 'Início' }, ...PASTAS_TERMOS_MULTAS.map(p => ({ id: p.id, rotulo: rotuloCaminhoPastaTermo(p.id) }))].sort((a, b) => a.rotulo.localeCompare(b.rotulo, 'pt-BR'));
  f.elements.pastaId.innerHTML = opcoes.map(p => `<option value="${esc(p.id)}">${esc(p.rotulo)}</option>`).join('');
  f.elements.pastaId.value = item.pastaId || '';
  document.getElementById('moverTermoMultaAjuda').textContent = item.titulo;
  document.getElementById('moverTermoMultaModal').hidden = false;
  f.elements.pastaId.focus();
}
function fecharMoverTermoMultaModal() { document.getElementById('moverTermoMultaModal').hidden = true; movendoTermoMultaId = null; }
document.getElementById('btnAddTermoAssinado').onclick = () => abrirTermoMultaModal('assinado');
document.getElementById('btnAddTermoModelo').onclick = () => abrirTermoMultaModal('modelo');
document.getElementById('btnAddPastaTermos').onclick = () => abrirPastaTermoMultaModal();
document.getElementById('fecharTermoMultaModal').onclick = document.getElementById('cancelarTermoMultaModal').onclick = fecharTermoMultaModal;
document.getElementById('fecharPastaTermoMulta').onclick = document.getElementById('cancelarPastaTermoMulta').onclick = fecharPastaTermoMultaModal;
document.getElementById('fecharMoverTermoMulta').onclick = document.getElementById('cancelarMoverTermoMulta').onclick = fecharMoverTermoMultaModal;
fecharAoClicarNoFundo('termoMultaModal', fecharTermoMultaModal);
fecharAoClicarNoFundo('pastaTermoMultaModal', fecharPastaTermoMultaModal);
fecharAoClicarNoFundo('moverTermoMultaModal', fecharMoverTermoMultaModal);
document.getElementById('termosMultaBusca').addEventListener('input', debounce(renderTermosMultas, 100));
document.getElementById('termosMultaVoltar').onclick = () => { CAMINHO_TERMOS_MULTAS.pop(); document.getElementById('termosMultaBusca').value = ''; renderTermosMultas(); };
document.getElementById('termosMultaPastas').onclick = async (e) => {
  const card = e.target.closest('[data-pasta-id]'); if (!card) return;
  const pasta = pastaTermoPorId(card.dataset.pastaId); if (!pasta) return;
  const acao = e.target.closest('[data-pasta-acao]');
  if (acao?.dataset.pastaAcao === 'renomear') return abrirPastaTermoMultaModal(pasta);
  if (acao?.dataset.pastaAcao === 'excluir') {
    if (!(await confirmar(`Excluir a pasta “${pasta.nome}”? Ela precisa estar vazia.`, { perigo: true, okTexto: 'Excluir' }))) return;
    const r = await fetch(`/api/termos-multas/pastas/${encodeURIComponent(pasta.id)}`, { method: 'DELETE' });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) return toast(j.erro || 'Não foi possível excluir a pasta.', 'erro');
    await carregarTermosMultas(); toast('Pasta excluída.', 'ok'); return;
  }
  if (e.target.closest('[data-abrir-pasta]')) {
    CAMINHO_TERMOS_MULTAS.push(pasta.id);
    document.getElementById('termosMultaBusca').value = '';
    renderTermosMultas();
  }
};
document.getElementById('termosMultaCards').onclick = async (e) => {
  const b = e.target.closest('[data-acao]'), card = e.target.closest('[data-id]'); if (!b || !card) return;
  const item = TERMOS_MULTAS.find(t => t.id === card.dataset.id); if (!item) return;
  if (b.dataset.acao === 'mover') return abrirMoverTermoMultaModal(item);
  if (b.dataset.acao === 'editar') return abrirTermoMultaModal(item.tipo, item);
  if (!(await confirmar(`Excluir “${item.titulo}” e o arquivo anexado?`, { perigo: true, okTexto: 'Excluir' }))) return;
  const r = await fetch(`/api/termos-multas/${encodeURIComponent(item.id)}`, { method: 'DELETE' });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) return toast(j.erro || 'Não foi possível excluir o termo.', 'erro');
  await carregarTermosMultas();
  toast('Termo excluído.', 'ok');
};
document.getElementById('formPastaTermoMulta').onsubmit = async (e) => {
  e.preventDefault();
  const f = e.currentTarget, nome = f.elements.nome.value.trim();
  const editando = !!editandoPastaTermoMultaId;
  const url = editandoPastaTermoMultaId ? `/api/termos-multas/pastas/${encodeURIComponent(editandoPastaTermoMultaId)}` : '/api/termos-multas/pastas';
  const body = editandoPastaTermoMultaId ? { nome } : { nome, pastaPaiId: pastaTermoAtualId() };
  const r = await fetch(url, { method: editandoPastaTermoMultaId ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) return toast(j.erro || 'Não foi possível salvar a pasta.', 'erro');
  fecharPastaTermoMultaModal(); await carregarTermosMultas(); toast(editando ? 'Pasta renomeada.' : 'Pasta criada!', 'ok');
};
document.getElementById('formMoverTermoMulta').onsubmit = async (e) => {
  e.preventDefault();
  const f = e.currentTarget;
  const r = await fetch(`/api/termos-multas/${encodeURIComponent(movendoTermoMultaId)}/mover`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ pastaId: f.elements.pastaId.value }) });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) return toast(j.erro || 'Não foi possível mover o arquivo.', 'erro');
  fecharMoverTermoMultaModal(); await carregarTermosMultas(); toast('Arquivo movido.', 'ok');
};
document.getElementById('formTermoMulta').onsubmit = async (e) => {
  e.preventDefault();
  const f = e.currentTarget, tipo = f.elements.tipo.value, file = f.elements.arquivo.files[0];
  const editando = !!editandoTermoMultaId;
  let arquivo = arquivoTermoMultaAtual;
  if (file) {
    if (file.size > 9 * 1024 * 1024) return toast('Arquivo muito grande (máx. 9 MB).', 'erro');
    const ext = String(file.name).toLowerCase();
    if (tipo === 'assinado' && !ext.endsWith('.pdf')) return toast('O termo assinado deve ser um PDF.', 'erro');
    if (tipo === 'modelo' && !ext.endsWith('.pdf') && !ext.endsWith('.docx')) return toast('O modelo deve ser um PDF ou DOCX.', 'erro');
  }
  if (!arquivo && !file) return toast('Selecione um arquivo.', 'erro');
  const btn = f.querySelector('button[type="submit"]'), textoBtn = btn.textContent;
  btn.disabled = true; btn.textContent = 'Salvando...';
  try {
    if (file) {
      const fd = new FormData(); fd.append('tipo', tipo); fd.append('arquivo', file);
      const ur = await fetch('/api/termos-multas/midia', { method: 'POST', body: fd });
      const uj = await ur.json().catch(() => ({}));
      if (!ur.ok) throw new Error(uj.erro || 'Não foi possível enviar o arquivo.');
      arquivo = uj;
    }
    const body = { tipo, pastaId: pastaTermoMultaAtualId, placa: f.elements.placa.value.trim().toUpperCase(), motorista: f.elements.motorista.value.trim(), titulo: f.elements.titulo.value.trim(), descricao: f.elements.descricao.value.trim(), arquivo };
    const url = editandoTermoMultaId ? `/api/termos-multas/${encodeURIComponent(editandoTermoMultaId)}` : '/api/termos-multas';
    const r = await fetch(url, { method: editandoTermoMultaId ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(j.erro || 'Não foi possível salvar o termo.');
    fecharTermoMultaModal();
    await carregarTermosMultas();
    toast(editando ? 'Termo atualizado.' : 'Termo adicionado!', 'ok');
  } catch (err) { toast(err.message || 'Erro ao salvar.', 'erro'); }
  finally { btn.disabled = false; btn.textContent = textoBtn; }
};

