let RASTREADORES = [];
const ICONE_VINCULOS_RAST = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 3v5h5M3.1 13A9 9 0 1 0 6 5.3L3 8M12 7v5l4 2"/></svg>';
let vinculosRastCtx = { id: '', pagina: 1, seq: 0, foco: null };
const ROTULOS_VINCULOS_RAST = {
  vinculacao: 'Vínculo detectado', transferencia: 'Transferência detectada', remocao: 'Remoção detectada',
  cadastro: 'Aparelho cadastrado sem veículo', cadastroExcluido: 'Cadastro excluído',
  identificacao: 'Identificação corrigida', estadoInicial: 'Situação já existente',
  referencia: 'Placa de referência alterada',
  instalacao: 'Instalação registrada', instalacaoCorrigida: 'Registro de instalação corrigido',
  instalacaoExcluida: 'Registro de instalação excluído', associacaoCorrigida: 'Instalação associada a outro aparelho',
};
const ORIGENS_VINCULOS_RAST = { manual: 'Cadastro', planilha: 'Planilha', cobli: 'Cobli',
  instalacoes: 'Instalações', legado: 'Cadastro anterior', desfazer: 'Desfazer', restauracao: 'Restauração' };

// USO: abrirVinculosRast('R1') → modal com vínculos, datas informadas/detectadas e fotos desse aparelho.
async function abrirVinculosRast(id) {
  vinculosRastCtx = { id, pagina: 1, seq: vinculosRastCtx.seq + 1, foco: document.activeElement };
  document.getElementById('rastVinculosTitulo').textContent = 'Histórico de vínculos';
  document.getElementById('rastVinculosModal').hidden = false;
  document.getElementById('fecharRastVinculos').focus();
  await carregarVinculosRast();
}
// USO: fecharVinculosRast() → fecha o histórico e devolve o foco ao botão da linha.
function fecharVinculosRast() {
  document.getElementById('rastVinculosModal').hidden = true;
  vinculosRastCtx.seq++;
  vinculosRastCtx.id = '';
  if (vinculosRastCtx.foco && vinculosRastCtx.foco.isConnected) vinculosRastCtx.foco.focus();
}
// USO: carregarVinculosRast(2) → consulta a página 2; falha de leitura mostra aviso e permite tentar de novo.
async function carregarVinculosRast(pagina = vinculosRastCtx.pagina) {
  const { id } = vinculosRastCtx;
  if (!id) return;
  const seq = ++vinculosRastCtx.seq;
  const lista = document.getElementById('rastVinculosLista');
  lista.innerHTML = '<p role="status">Carregando histórico…</p>';
  document.getElementById('rastVinculosNav').hidden = true;
  document.getElementById('rastVinculosResumo').textContent = '';
  try {
    const r = await fetch(`/api/rastreadores/${encodeURIComponent(id)}/vinculos?pagina=${pagina}`, { cache: 'no-store' });
    const d = await r.json();
    if (seq !== vinculosRastCtx.seq) return;
    if (!r.ok) throw new Error(d.erro || 'Não foi possível carregar o histórico.');
    vinculosRastCtx.pagina = d.pagina;
    document.getElementById('rastVinculosTitulo').textContent = `Histórico de vínculos · ${d.rastreador.codigo || d.rastreador.esn || 'Rastreador'}`;
    document.getElementById('rastVinculosResumo').textContent = `${d.rastreador.placa ? 'Vínculo atual: ' + d.rastreador.placa : 'Sem vínculo atual'} · ${d.total} registro(s)`;
    lista.innerHTML = d.eventos.length ? '<ol class="rast-vinculos-lista">' + d.eventos.map((e, idx) => {
      const movimento = e.placaAnterior && e.placa ? `${e.placaAnterior} → ${e.placa}`
        : e.placa ? `Veículo: ${e.placa}` : e.placaAnterior ? `Veículo anterior: ${e.placaAnterior}` : 'Sem veículo vinculado';
      const carimbo = new Date(e.ts).toLocaleString('pt-BR');
      const daInstalacao = !!e.instalacaoId;
      const data = e.tipo === 'estadoInicial' ? 'Data do vínculo não informada'
        : daInstalacao ? (e.dataInstalacao ? `Data informada da instalação: ${e.dataInstalacao}` : 'Data da instalação não informada') : `Detectado em: ${carimbo}`;
      return `<li class="rast-vinculo" data-tipo="${esc(e.tipo)}">
        <div class="rast-vinculo-cab"><strong>${esc(ROTULOS_VINCULOS_RAST[e.tipo] || e.tipo)}</strong><span>${esc(ORIGENS_VINCULOS_RAST[e.origem] || e.origem)}${e.recuperado ? ' · Recuperado' : ''}</span></div>
        <p class="rast-vinculo-placa">${esc(movimento)}</p><p>${esc(data)}</p>
        ${daInstalacao ? `<p class="rast-vinculo-meta">Registro no sistema: ${esc(carimbo)}</p>` : ''}
        ${e.colaborador ? `<p>Responsável pela instalação: ${esc(e.colaborador)}</p>` : ''}
        ${e.local ? `<p>Local: ${esc(e.local)}</p>` : ''}${e.por ? `<p>Registrado por: ${esc(e.por)}</p>` : ''}
        ${e.tipo === 'identificacao' ? `<p>Código: ${esc(e.codigoAnterior || '—')} → ${esc(e.codigo || '—')} · ESN: ${esc(e.esnAnterior || '—')} → ${esc(e.esn || '—')}</p>` : ''}
        ${e.observacoes ? `<p>${esc(e.observacoes)}</p>` : ''}
        ${(e.fotos || []).length ? `<button type="button" class="btn btn-ghost small" data-vinculo-fotos="${idx}">Ver fotos (${e.fotos.length})</button>` : ''}
      </li>`;
    }).join('') + '</ol>' : '<p>Nenhum vínculo registrado para este aparelho.</p>';
    lista.querySelectorAll('[data-vinculo-fotos]').forEach(b => b.onclick = () => abrirMidia(d.eventos[Number(b.dataset.vinculoFotos)].fotos, 0));
    document.getElementById('rastVinculosNav').hidden = d.paginas <= 1;
    document.getElementById('rastVinculosPagina').textContent = `${d.pagina} de ${d.paginas}`;
    document.getElementById('rastVinculosAnterior').disabled = d.pagina <= 1;
    document.getElementById('rastVinculosProxima').disabled = d.pagina >= d.paginas;
  } catch (e) {
    if (seq === vinculosRastCtx.seq) lista.innerHTML = `<p role="alert">${esc(e.message || 'Não foi possível carregar o histórico.')}</p>`;
  }
}
document.getElementById('fecharRastVinculos').onclick = fecharVinculosRast;
document.getElementById('rastVinculosAtualizar').onclick = () => carregarVinculosRast();
document.getElementById('rastVinculosCadastro').onclick = () => {
  const r = RASTREADORES.find(r => r.id === vinculosRastCtx.id);
  if (r) { fecharVinculosRast(); abrirHistRastreador(r.codigo); }
};
document.getElementById('rastVinculosAnterior').onclick = () => carregarVinculosRast(vinculosRastCtx.pagina - 1);
document.getElementById('rastVinculosProxima').onclick = () => carregarVinculosRast(vinculosRastCtx.pagina + 1);
fecharAoClicarNoFundo('rastVinculosModal', fecharVinculosRast);
const SELECAO_RAST = new Set(); // ids selecionados (declarado aqui p/ evitar TDZ se renderRast rodar cedo)
let editandoRastId = null;
let ordemRast = { campo: '', dir: 1 };
const filtroCardRast = new Set(); // classes das situações marcadas nos cards (ex.: 'r-novo' + 'r-ativo' = união); vazio = sem filtro
const pgRast = { pagina: 1, porPagina: 50 };

const CAMPOS_RAST = [
  { titulo: 'Ações' },
  { titulo: 'Código/ID', campo: 'codigo' },
  { titulo: 'ESN', campo: 'esn' },
  { titulo: 'Placa', campo: 'placa' },
  { titulo: 'Versão', campo: 'versao' },
  { titulo: 'Tipo', campo: 'tipo' },
  { titulo: 'Situação', campo: 'situacao' },
  { titulo: 'Pedido Devolução', campo: 'dataPedidoDevolucao', tipo: 'data' },
  { titulo: 'Data Devolução', campo: 'dataDevolucao', tipo: 'data' },
  { titulo: 'Protocolo', campo: 'protocolo' },
  { titulo: 'Substituído por', campo: 'substituidoPor' },
  { titulo: 'Veículo Destino', campo: 'veiculoDestino' },
  { titulo: 'Observações', campo: 'observacoes' },
];

function classeSitRast(s) {
  const u = (s || '').toLowerCase();
  if (u.includes('ativo')) return 'r-ativo';
  if (u.includes('devolv')) return 'r-devolvido';
  if (u.includes('troc')) return 'r-trocado';
  if (u.includes('transfer')) return 'r-transferido';
  if (u.includes('extrav')) return 'r-extraviado';
  if (u.includes('novo')) return 'r-novo';
  return 'r-removido';
}

async function carregarRastreadores() {
  try {
    const r = await fetch('/api/rastreadores', { cache: 'no-store' });
    if (r.status === 401) { window.location = '/login'; return; }
    const d = r.ok ? await r.json() : [];
    RASTREADORES = Array.isArray(d) ? d : [];
  } catch (e) { toast('Erro ao carregar os rastreadores. Verifique a conexão.', 'erro'); return; }
  renderRast();
}

function valoresUnicosRast(campo) {
  return [...new Set(RASTREADORES.map(r => r[campo]).filter(x => x && String(x).trim()))].sort();
}

function popularFiltrosRast() {
  const cfg = [['frSituacao', 'situacao'], ['frTipo', 'tipo'], ['frPlaca', 'placa']];
  for (const [id, campo] of cfg) if (MSEL[id]) MSEL[id].setOpcoes(valoresUnicosRast(campo));
  document.getElementById('listaPlacasRast').innerHTML =
    [...new Set(VEICULOS.map(v => v.placa))].sort().map(p => `<option value="${esc(p)}">`).join('');
}

function aplicarFiltrosRast() {
  const q = document.getElementById('buscaRast').value.trim().toLowerCase();
  const fS = getSel('frSituacao');
  const fT = getSel('frTipo');
  const fP = getSel('frPlaca');
  const de = parseBR(document.getElementById('frDevDe').value);
  const ate = parseBR(document.getElementById('frDevAte').value);
  return RASTREADORES.filter(r => {
    if (r.desativado) return false; // desativados moram na sub-aba própria
    if (filtroCardRast.size && !filtroCardRast.has(classeSitRast(r.situacao))) return false;
    if (fS.length && !fS.includes(r.situacao)) return false;
    if (fT.length && !fT.includes(r.tipo)) return false;
    if (fP.length && !fP.includes(r.placa)) return false;
    if (de || ate) {
      const d = parseBR(r.dataDevolucao);
      if (!d) return false;
      if (de && d < de) return false;
      if (ate && d > ate) return false;
    }
    if (q) {
      const blob = [r.codigo, r.placa, r.tipo, r.situacao, r.protocolo, r.substituidoPor, r.veiculoDestino, r.observacoes].join(' ').toLowerCase();
      if (!blob.includes(q)) return false;
    }
    return true;
  });
}

function situacaoPillRast(r) {
  const opts = ['Novo', 'Ativo', 'Removido', 'Devolvido', 'Trocado', 'Transferido', 'Extraviado'];
  const itens = opts.map(o => `<button type="button" class="pill-item ${classeSitRast(o)}" data-valor="${o}">${o}</button>`).join('');
  return `<div class="pill-select" data-id="${esc(r.id)}" data-campo="situacao">
      <button type="button" class="pill-trigger ${classeSitRast(r.situacao)}" title="Clique para alterar"><span>${esc(r.situacao)}</span>${CHEVRON}</button>
      <div class="pill-menu" hidden><div class="pill-itens">${itens}</div></div>
    </div>`;
}

function renderRast() {
  popularFiltrosRast();
  const cab = document.getElementById('cabecalhoRast');
  cab.innerHTML = CAMPOS_RAST.map(c => {
    if (!c.campo) return `<th class="col-acoes acoes-com-leitura">${c.titulo || ''}</th>`;
    return `<th data-campo="${c.campo}" data-tipo="${c.tipo || 'texto'}" title="Clique para ordenar">${c.titulo}${iconeOrd(ordemRast.campo === c.campo, ordemRast.dir)}</th>`;
  }).join('');
  cab.querySelectorAll('th[data-campo]').forEach(th => th.onclick = () => {
    const campo = th.dataset.campo;
    if (ordemRast.campo === campo) ordemRast.dir *= -1;
    else { ordemRast.campo = campo; ordemRast.dir = 1; }
    pgRast.pagina = 1;
    renderRast();
  });

  const totalPrincipal = RASTREADORES.filter(r => !r.desativado).length; // desativados vivem na sub-aba própria
  let lista = aplicarFiltrosRast();
  if (ordemRast.campo) {
    const col = CAMPOS_RAST.find(c => c.campo === ordemRast.campo) || {};
    lista = lista.slice().sort((a, b) => {
      let x = a[ordemRast.campo], y = b[ordemRast.campo];
      if (col.tipo === 'data') {
        const dx = parseBR(x), dy = parseBR(y);
        const vx = dx ? dx.getTime() : (ordemRast.dir === 1 ? Infinity : -Infinity);
        const vy = dy ? dy.getTime() : (ordemRast.dir === 1 ? Infinity : -Infinity);
        return (vx - vy) * ordemRast.dir;
      }
      return String(x ?? '').localeCompare(String(y ?? ''), 'pt-BR') * ordemRast.dir;
    });
  }

  const corpo = document.getElementById('corpoRast');
  estadoVazio('rastVazio', totalPrincipal, lista.length, 'Nenhum rastreador cadastrado ainda. Clique em "+ Adicionar rastreador".', () => document.getElementById('btnLimparRast').click());
  const pg = fatiarPagina(lista, pgRast);
  corpo.innerHTML = pg.itens.map(r => {
    // placa "limpa": ignora placeholders como "-" (sem placa vinculada => célula vazia)
    const placa = /[A-Z0-9]/i.test(r.placa || '') ? (r.placa || '').toUpperCase() : '';
    const semVeic = placa && !VEICULOS.some(v => v.placa === placa);
    const placaCel = placa
      ? `<button class="placa-btn placa-chip" data-placa="${esc(placa)}" title="Ver histórico do veículo">${esc(placa)}</button>` +
        (semVeic ? ` <span class="aviso-veic" title="Placa não encontrada na Frota">⚠</span>` : '')
      : '';
    const selOn = SELECAO_RAST.has(r.id) ? ' sel-on' : '';
    return `<tr data-id="${esc(r.id)}" data-placa="${esc(placa)}" class="${selOn}">
      <td class="acoes acoes-com-leitura">
        <button type="button" class="hist-vinculos-rast acao-leitura" data-id="${esc(r.id)}" title="Histórico de vínculos" aria-label="Histórico de vínculos">${ICONE_VINCULOS_RAST}</button>
        <button class="edit edit-rast" data-id="${esc(r.id)}" title="Editar" aria-label="Editar">${ICONE_LAPIS}</button>
        <button class="del del-rast" data-id="${esc(r.id)}" title="Excluir" aria-label="Excluir">${ICONE_LIXEIRA}</button>
        <button class="edit desat-rast" data-id="${esc(r.id)}" title="Mover para Desativados (devolvido/extraviado; não está mais conosco)" aria-label="Mover para Desativados">📦</button>
      </td>
      <td data-label="Código/ID">${r.codigo ? `<button class="placa-btn cod-rast" data-codigo="${esc(r.codigo)}" title="Ver histórico de vínculos"><b>${esc(r.codigo)}</b></button>` : '—'}</td>
      <td class="cel-sec" data-label="ESN">${esc(r.esn) || '—'}</td>
      <td class="cel-sub" data-label="Placa">${placaCel}</td>
      <td class="cel-sec" data-label="Versão">${esc(r.versao) || '—'}</td>
      <td data-label="Tipo"><span class="tipo-badge ${r.tipo === 'Removível' ? 'tipo-rem' : (r.tipo === 'Instalado' ? 'tipo-inst' : 'tipo-outros')}">${esc(r.tipo)}</span></td>
      <td data-label="Situação">${situacaoPillRast(r)}</td>
      <td class="cel-sec" data-label="Pedido de devolução">${esc(fmtData(r.dataPedidoDevolucao)) || '—'}</td>
      <td class="cel-sec" data-label="Devolução">${esc(fmtData(r.dataDevolucao)) || '—'}</td>
      <td class="cel-sec" data-label="Protocolo">${esc(r.protocolo) || '—'}</td>
      <td class="cel-sec" data-label="Substituído por">${esc(r.substituidoPor) || '—'}</td>
      <td class="cel-sec" data-label="Veículo destino">${esc(r.veiculoDestino) || '—'}</td>
      <td class="cel-sec cel-trunc" data-label="Observações" title="${esc(r.observacoes)}">${esc(r.observacoes) || '—'}</td>
    </tr>`;
  }).join('');

  document.getElementById('resumoRast').innerHTML =
    `Exibindo <b>${pg.de}–${pg.ate}</b> de <b>${lista.length}</b> rastreadores${lista.length !== totalPrincipal ? ` (${totalPrincipal} no total)` : ''}`;
  renderCardsRast();
  renderRastDesativados();
  renderNavPaginacao('rast', pg);

  // ----- Seleção (clique na linha) -----
  if (SELECAO_RAST.size) { const vivos = new Set(RASTREADORES.map(x => x.id)); for (const id of [...SELECAO_RAST]) if (!vivos.has(id)) SELECAO_RAST.delete(id); }
  SEL_TODOS_RAST.sincronizar(lista); // alimenta o cache de chaves com a lista filtrada recém-calculada
  atualizarBarraSelRast();
  // Cliques tratados por DELEGAÇÃO única em #corpoRast (definida 1x).
}

// ----- Barra de seleção dos Rastreadores (exportar selecionados / limpar) -----
// (SELECAO_RAST é declarado junto do estado de RASTREADORES, lá em cima.)
function atualizarBarraSelRast() {
  const bar = document.getElementById('selBarRast');
  if (!bar) return;
  SEL_TODOS_RAST.sincronizar(); // antes do return de "nada selecionado": o (N) do rótulo tem de seguir certo
  if (!SELECAO_RAST.size) { bar.hidden = true; return; }
  document.getElementById('selBarRastInfo').innerHTML =
    `<span class="sb-item"><b>${SELECAO_RAST.size}</b> selecionado(s)</span>`;
  bar.hidden = false;
}
document.getElementById('selBarRastLimpar').onclick = () => { SELECAO_RAST.clear(); renderRast(); };
document.getElementById('selBarRastExportar').onclick = () => {
  const ids = [...SELECAO_RAST];
  if (!ids.length) return;
  window.location = '/api/rastreadores/exportar?ids=' + encodeURIComponent(ids.join(','));
};
// Ação em lote na seleção (helper): POST com os ids, recarrega e avisa.
async function _acaoLoteRast(ep, corpoExtra, msgOk) {
  const ids = [...SELECAO_RAST];
  if (!ids.length) return;
  const r = await fetch('/api/rastreadores/' + ep, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(Object.assign({ ids }, corpoExtra)) });
  const j = await r.json().catch(() => ({}));
  if (!r.ok || !j.ok) { toast(j.erro || 'Erro na ação em lote.', 'erro'); return; }
  SELECAO_RAST.clear();
  await carregarRastreadores();
  toast(typeof msgOk === 'function' ? msgOk(j) : msgOk, 'ok');
}
document.getElementById('selBarRastExcluir').onclick = async () => {
  const n = SELECAO_RAST.size; if (!n) return;
  if (!(await confirmar(`Excluir ${n} rastreador(es) selecionado(s)? Esta ação não pode ser desfeita.`, { perigo: true, okTexto: 'Excluir' }))) return;
  _acaoLoteRast('lote-excluir', {}, (j) => `${j.excluidos || 0} rastreador(es) excluído(s).`);
};
document.getElementById('selBarRastDesativar').onclick = async () => {
  const n = SELECAO_RAST.size; if (!n) return;
  if (!(await confirmar(`Mover ${n} rastreador(es) para a sub-aba Desativados? Eles saem da lista principal (dá para restaurar depois).`, { okTexto: 'Desativar' }))) return;
  _acaoLoteRast('lote-desativar', {}, (j) => `${j.desativados || 0} rastreador(es) movido(s) para Desativados.`);
};
document.getElementById('selBarRastEditar').onclick = () => abrirEditarLoteRast();
// Modal de edição em lote: escolher nova situação e/ou tipo para os selecionados.
function abrirEditarLoteRast() {
  const n = SELECAO_RAST.size; if (!n) return;
  const ov = document.createElement('div');
  ov.className = 'modal-overlay';
  const optS = ['', 'Novo', 'Ativo', 'Removido', 'Devolvido', 'Trocado', 'Transferido', 'Extraviado'].map(s => `<option value="${s}">${s || '(não alterar)'}</option>`).join('');
  const optT = ['', 'Instalado', 'Removível', 'Outros'].map(t => `<option value="${t}">${t || '(não alterar)'}</option>`).join('');
  ov.innerHTML = `<div class="modal" style="max-width:440px">
    <div class="modal-head"><h2>Editar ${n} rastreador(es)</h2><button class="icon-btn" type="button" data-fechar aria-label="Fechar">✕</button></div>
    <div class="form-grid" style="padding:22px">
      <label class="full">Situação<select id="loteRastSit">${optS}</select></label>
      <label class="full">Tipo<select id="loteRastTipo">${optT}</select></label>
      <p class="dica full">Só os campos escolhidos são alterados; "não alterar" mantém o valor atual de cada um.</p>
    </div>
    <div class="modal-foot"><button class="btn btn-ghost" type="button" data-fechar>Cancelar</button><button class="btn btn-primary" type="button" id="loteRastAplicar">Aplicar</button></div>
  </div>`;
  document.body.appendChild(ov);
  const fechar = () => ov.remove();
  ov.querySelectorAll('[data-fechar]').forEach(b => b.onclick = fechar);
  ov.addEventListener('click', (e) => { if (e.target === ov) fechar(); });
  ov.querySelector('#loteRastAplicar').onclick = async () => {
    const situacao = ov.querySelector('#loteRastSit').value;
    const tipo = ov.querySelector('#loteRastTipo').value;
    if (!situacao && !tipo) { toast('Escolha situação e/ou tipo.', 'erro'); return; }
    fechar();
    _acaoLoteRast('lote-editar', { campos: { situacao, tipo } }, (j) => `${j.alterados || 0} rastreador(es) atualizado(s).`);
  };
}
document.getElementById('corpoRast').addEventListener('click', (e) => {
  const hist = e.target.closest('.hist-vinculos-rast'); if (hist) { abrirVinculosRast(hist.dataset.id); return; }
  const editBtn = e.target.closest('.edit-rast'); if (editBtn) { abrirRastModal(editBtn.dataset.id); return; }
  const delBtn = e.target.closest('.del-rast'); if (delBtn) { excluirRast(delBtn.dataset.id); return; }
  const desatBtn = e.target.closest('.desat-rast'); if (desatBtn) { moverRastDesativado(desatBtn.dataset.id); return; }
  const cod = e.target.closest('.cod-rast'); if (cod) { e.stopPropagation(); abrirVinculosRast(cod.closest('tr').dataset.id); return; }
  const placaBtn = e.target.closest('.placa-btn'); if (placaBtn) { e.stopPropagation(); abrirHistVeiculo(placaBtn.dataset.placa); return; }
  const pTrig = e.target.closest('.pill-trigger'); if (pTrig) { e.stopPropagation(); const sel = pTrig.closest('.pill-select'); const aberto = sel.classList.contains('aberto'); fecharPillMenus(); if (!aberto) abrirPillMenu(sel); return; }
  const pItem = e.target.closest('.pill-item'); if (pItem) { e.stopPropagation(); const sel = donoPillMenu(pItem); if (!sel) return; fecharPillMenus(); alterarCampoRast(sel.dataset.id, sel.dataset.campo, pItem.dataset.valor); return; }
  // Toque/clique no corpo do card (fora de botões/pílulas) seleciona/deseleciona — igual à Frota.
  if (e.target.closest('button, input, select, textarea, a, .pill-select, .placa-btn')) return;
  const tr = e.target.closest('tr'); if (!tr || !tr.dataset.id) return;
  const id = tr.dataset.id;
  if (SELECAO_RAST.has(id)) SELECAO_RAST.delete(id); else SELECAO_RAST.add(id);
  tr.classList.toggle('sel-on', SELECAO_RAST.has(id));
  atualizarBarraSelRast();
});

function renderCardsRast() {
  const ativos = RASTREADORES.filter(r => !r.desativado); // desativados não entram nos cards
  const cont = {};
  for (const r of ativos) { const c = classeSitRast(r.situacao); cont[c] = (cont[c] || 0) + 1; }
  // cls = cor + card-clic (clicável) + card-ativo (selecionado). Vários cards podem estar
  // marcados ao mesmo tempo (a lista mostra a UNIÃO das situações marcadas).
  const cls = (cor, sit) => [cor, 'card-clic', sit && filtroCardRast.has(sit) ? 'card-ativo' : ''].filter(Boolean).join(' ');
  const at = (sit) => `data-sit="${sit}"`; // role/tabindex vêm do cardV2
  document.getElementById('cardsRast').innerHTML = `
    ${cardV2('Total', ativos.length, cls('', ''), false, at(''))}
    ${cardV2('Novos', cont['r-novo'] || 0, cls('', 'r-novo'), false, at('r-novo'))}
    ${cardV2('Ativos', cont['r-ativo'] || 0, cls('green', 'r-ativo'), false, at('r-ativo'))}
    ${cardV2('Devolvidos', cont['r-devolvido'] || 0, cls('', 'r-devolvido'), false, at('r-devolvido'))}
    ${cardV2('Trocados', cont['r-trocado'] || 0, cls('amber', 'r-trocado'), false, at('r-trocado'))}
    ${cardV2('Transferidos', cont['r-transferido'] || 0, cls('', 'r-transferido'), false, at('r-transferido'))}
    ${cardV2('Removidos', cont['r-removido'] || 0, cls('red', 'r-removido'), false, at('r-removido'))}
    ${cardV2('Extraviados', cont['r-extraviado'] || 0, cls('red', 'r-extraviado'), false, at('r-extraviado'))}
  `;
  document.querySelectorAll('#cardsRast .v2-kpi[data-sit]').forEach(c => {
    const acionar = () => {
      const sit = c.dataset.sit;
      // Cada card é um toggle e pode combinar com os outros (ex.: Novos + Ativos).
      // Total limpa tudo.
      if (sit === '') filtroCardRast.clear();
      else if (filtroCardRast.has(sit)) filtroCardRast.delete(sit);
      else filtroCardRast.add(sit);
      pgRast.pagina = 1;
      renderRast();
    };
    c.onclick = acionar;
    c.onkeydown = (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); acionar(); } };
  });
}

// ----- Sub-aba Desativados (rastreadores devolvidos/extraviados, fora do painel) -----
function trocarSubRast(sub) {
  const alvo = document.querySelector(`#rastSubtabs .subtab[data-sub="${sub}"]`);
  if (!alvo) return;
  document.querySelectorAll('#rastSubtabs .subtab').forEach(x => x.classList.remove('active'));
  document.querySelectorAll('#rastreadores .subview').forEach(x => x.classList.remove('active'));
  alvo.classList.add('active');
  document.getElementById(sub).classList.add('active');
}
document.querySelectorAll('#rastSubtabs .subtab').forEach(b => b.onclick = () => { if (!b.classList.contains('active')) trocarSubRast(b.dataset.sub); });

function renderRastDesativados() {
  const corpo = document.getElementById('corpoRastDesat');
  if (!corpo) return;
  // Mais recentes primeiro (pela data em que foram movidos para cá).
  const lista = RASTREADORES.filter(r => r.desativado).slice().sort((a, b) => {
    const da = parseBR(a.desativadoEm), db = parseBR(b.desativadoEm);
    return (db ? db.getTime() : 0) - (da ? da.getTime() : 0);
  });
  const chip = document.querySelector('#rastSubtabs .subtab[data-sub="rast-desativados"]');
  if (chip) chip.textContent = lista.length ? `Desativados (${lista.length})` : 'Desativados';
  document.getElementById('rastDesatVazio').hidden = lista.length > 0;
  corpo.innerHTML = lista.map(r => {
    const placa = /[A-Z0-9]/i.test(r.placa || '') ? (r.placa || '').toUpperCase() : '';
    return `<tr data-id="${esc(r.id)}">
      <td class="acoes acoes-com-leitura">
        <button type="button" class="hist-vinculos-rast acao-leitura" data-id="${esc(r.id)}" title="Histórico de vínculos" aria-label="Histórico de vínculos">${ICONE_VINCULOS_RAST}</button>
        <button class="edit rest-rast" data-id="${esc(r.id)}" title="Restaurar (volta para a lista principal)" aria-label="Restaurar">↩</button>
        <button class="del del-rast-desat" data-id="${esc(r.id)}" title="Excluir de vez" aria-label="Excluir">${ICONE_LIXEIRA}</button>
      </td>
      <td>${r.codigo ? `<button class="placa-btn cod-rast" data-codigo="${esc(r.codigo)}" title="Ver histórico de vínculos"><b>${esc(r.codigo)}</b></button>` : '—'}</td>
      <td class="cel-sec">${esc(r.esn) || '—'}</td>
      <td class="cel-sub">${placa ? `<button class="placa-btn placa-chip" data-placa="${esc(placa)}" title="Ver histórico do veículo">${esc(placa)}</button>` : '—'}</td>
      <td><span class="pill-trigger ${classeSitRast(r.situacao)}" style="cursor:default">${esc(r.situacao)}</span></td>
      <td class="cel-sec">${esc(fmtData(r.desativadoEm)) || '—'}</td>
      <td class="cel-sec" title="${esc(r.observacoes)}">${esc(trunc(r.observacoes, 60)) || '—'}</td>
    </tr>`;
  }).join('');
}
document.getElementById('corpoRastDesat').addEventListener('click', (e) => {
  const hist = e.target.closest('.hist-vinculos-rast'); if (hist) { abrirVinculosRast(hist.dataset.id); return; }
  const rest = e.target.closest('.rest-rast'); if (rest) { restaurarRastDesativado(rest.dataset.id); return; }
  const del = e.target.closest('.del-rast-desat'); if (del) { excluirRast(del.dataset.id); return; }
  const cod = e.target.closest('.cod-rast'); if (cod) { abrirVinculosRast(cod.closest('tr').dataset.id); return; }
  const placaBtn = e.target.closest('.placa-btn'); if (placaBtn && placaBtn.dataset.placa) { abrirHistVeiculo(placaBtn.dataset.placa); return; }
});
async function moverRastDesativado(id) {
  const r = RASTREADORES.find(x => x.id === id);
  if (!r) return;
  if (!(await confirmar(`Mover o rastreador ${r.codigo || ''} para a sub-aba Desativados? Ele sai da lista principal (dá para restaurar depois).`, { okTexto: 'Mover' }))) return;
  const hoje = new Date();
  const dataBR = `${String(hoje.getDate()).padStart(2, '0')}/${String(hoje.getMonth() + 1).padStart(2, '0')}/${hoje.getFullYear()}`;
  const at = Object.assign({}, r, { desativado: true, desativadoEm: dataBR });
  const resp = await fetch('/api/rastreadores/' + encodeURIComponent(id), {
    method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(at),
  });
  if (!resp.ok) { toast('Erro ao mover para Desativados.', 'erro'); return; }
  Object.assign(r, at);
  SELECAO_RAST.delete(id);
  renderRast();
  toast(`Rastreador ${r.codigo} movido para Desativados.`, 'ok', { texto: 'Desfazer', fn: () => restaurarRastDesativado(id, false) });
}
async function restaurarRastDesativado(id, comConfirmacao = true) {
  const r = RASTREADORES.find(x => x.id === id);
  if (!r) return;
  if (comConfirmacao && !(await confirmar(`Restaurar o rastreador ${r.codigo || ''} para a lista principal?`, { okTexto: 'Restaurar' }))) return;
  const at = Object.assign({}, r, { desativado: false, desativadoEm: '' });
  const resp = await fetch('/api/rastreadores/' + encodeURIComponent(id), {
    method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(at),
  });
  if (!resp.ok) { toast('Erro ao restaurar.', 'erro'); return; }
  Object.assign(r, at);
  renderRast();
  toast(`Rastreador ${r.codigo} de volta à lista principal.`, 'ok');
}

async function alterarCampoRast(id, campo, valor, comDesfazer = true) {
  const r = RASTREADORES.find(x => x.id === id);
  if (!r || r[campo] === valor) return;
  const anterior = r[campo];
  const at = Object.assign({}, r, { [campo]: valor });
  const resp = await fetch('/api/rastreadores/' + encodeURIComponent(id), {
    method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(at),
  });
  if (!resp.ok) { toast('Erro ao alterar.', 'erro'); return; }
  Object.assign(r, at);
  renderRast();
  const desfazer = comDesfazer ? { texto: 'Desfazer', fn: () => alterarCampoRast(id, campo, anterior, false) } : null;
  toast(`Rastreador ${r.codigo} atualizado.`, 'ok', desfazer);
}

async function excluirRast(id) {
  const r = RASTREADORES.find(x => x.id === id);
  if (!(await confirmar(`Excluir o rastreador ${r ? r.codigo : ''}? Esta ação não pode ser desfeita.`, { perigo: true, okTexto: 'Excluir' }))) return;
  const resp = await fetch('/api/rastreadores/' + encodeURIComponent(id), { method: 'DELETE' });
  if (!resp.ok) { toast('Erro ao excluir.', 'erro'); return; }
  await carregarRastreadores();
  toast('Rastreador excluído.', 'ok');
}

