// Sincronização direta com o painel da Cobli (API) — cria os novos e atualiza ESN/placa.
document.getElementById('btnCobliSync').onclick = async () => {
  const btn = document.getElementById('btnCobliSync');
  if (!(await confirmar('Sincronizar com o painel da Cobli? Dispositivos novos são criados e, nos existentes, ESN e placa passam a refletir o painel (situação/tipo definidos na mão são preservados).', { okTexto: 'Sincronizar' }))) return;
  btn.disabled = true; const txt = btn.textContent; btn.textContent = '⟳ Sincronizando…';
  try {
    const r = await fetch('/api/rastreadores/cobli/sincronizar', { method: 'POST' });
    const d = await r.json().catch(() => ({}));
    if (!r.ok || !d.ok) throw new Error(d.erro || 'Falha na sincronização.');
    await carregarRastreadores();
    toast(`Cobli: ${d.totalCobli} no painel · ${d.criados} criado(s) · ${d.atualizados} atualizado(s)${d.semVeiculo ? ` · ${d.semVeiculo} sem veículo` : ''}`, 'ok');
  } catch (e) { toast(String(e.message || e), 'erro'); }
  btn.disabled = false; btn.textContent = txt;
};
document.getElementById('inputImportRast').onchange = async (e) => {
  const file = e.target.files[0];
  e.target.value = '';
  if (!file) return;
  abrirRastImport();
  progressoRastImport(true);
  try {
    const fd = new FormData(); fd.append('arquivo', file);
    const r = await fetch('/api/rastreadores/importar/preview', { method: 'POST', body: fd });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) { fecharRastImport(); toast(j.erro || 'Erro ao ler a planilha.', 'erro'); return; }
    rastImportRegistros = j.registros || [];
    mostrarPreviewRastImport(j);
  } catch (err) { fecharRastImport(); toast('Erro ao importar.', 'erro'); }
};

