/* ---------- Mídia: compressão + upload + lightbox ---------- */
// Reduz a imagem no navegador (máx ~1280px, JPEG q0.8) antes de enviar.
function comprimirImagem(file) {
  return new Promise((resolve) => {
    if (!/^image\//.test(file.type)) return resolve(file); // PDF/outros: envia como está
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      const MAX = 1280;
      let { width: w, height: h } = img;
      if (w > MAX || h > MAX) { const k = Math.min(MAX / w, MAX / h); w = Math.round(w * k); h = Math.round(h * k); }
      const cv = document.createElement('canvas');
      cv.width = w; cv.height = h;
      cv.getContext('2d').drawImage(img, 0, 0, w, h);
      URL.revokeObjectURL(url);
      cv.toBlob((blob) => resolve(blob || file), 'image/jpeg', 0.8);
    };
    img.onerror = () => { URL.revokeObjectURL(url); resolve(file); };
    img.src = url;
  });
}
// ---------- Progresso do envio (barra fina no topo da tela) ----------
// Um anexo grande (digitalização de 7 MB numa linha de subida lenta) passa dezenas de segundos
// sem sinal nenhum na tela — e "sem sinal" é lido como "travou", que foi exatamente o relato.
// Fica no TOPO para não disputar espaço com o toast e a barra de seleção (ambos embaixo).
function progressoUpload(estado) {
  let box = document.getElementById('uploadProg');
  if (!estado) { if (box) box.remove(); return; }
  if (!box) {
    box = document.createElement('div');
    box.id = 'uploadProg';
    box.className = 'upload-prog';
    // Sem aria-live de propósito: anunciar cada pacote faria o leitor de tela falar sem parar.
    // O resultado (sucesso/erro) continua sendo anunciado pelo toast de sempre.
    box.innerHTML = '<div class="upload-prog-barra"></div><div class="upload-prog-txt"></div>';
    document.body.appendChild(box);
  }
  const pct = estado.gravando ? 100 : Math.min(100, Math.round((estado.enviado / (estado.total || 1)) * 100));
  box.classList.toggle('gravando', !!estado.gravando);
  box.querySelector('.upload-prog-barra').style.width = pct + '%';
  box.querySelector('.upload-prog-txt').textContent = estado.gravando
    ? `Guardando "${estado.nome}"…`
    : `Enviando "${estado.nome}" · ${pct}%` + (estado.total ? ` de ${fmtTamanho(estado.total)}` : '');
}

// Envia um arquivo ao cofre de mídia COM progresso e com detecção de envio parado.
// Usa XMLHttpRequest porque `fetch` não expõe progresso de upload — sem isso não há como
// mostrar quanto falta nem como distinguir "ainda subindo" de "conexão morreu no meio".
// São DOIS relógios, porque o envio tem duas fases bem diferentes:
//   1) subindo os bytes  → cão de guarda rearmado a cada pacote (parou de andar = caiu);
//   2) bytes entregues   → o servidor ainda está gravando (no Mongo isso leva segundos num
//      arquivo de vários MB) e NENHUM evento de progresso chega; aqui vale um prazo único,
//      generoso. Sem essa separação, o cão de guarda mataria uma gravação que ia dar certo.
const UPLOAD_SEM_AVANCO_MS = 45000;        // 45s sem um byte novo
const UPLOAD_ESPERA_RESPOSTA_MS = 120000;  // 2min esperando o servidor confirmar a gravação
function enviarMidia(blob, nome, tipo, aoProgresso) {
  return new Promise((resolve, reject) => {
    const fd = new FormData();
    fd.append('arquivo', blob, nome);
    const xhr = new XMLHttpRequest();
    let relogio = null, parou = false;
    const rearmar = (ms) => {
      clearTimeout(relogio);
      relogio = setTimeout(() => { parou = true; xhr.abort(); }, ms);
    };
    const encerrar = () => { clearTimeout(relogio); progressoUpload(null); };
    const avisar = (estado) => { progressoUpload(estado); if (typeof aoProgresso === 'function') aoProgresso(estado); };
    xhr.open('POST', '/api/midia');
    xhr.upload.onprogress = (e) => {
      rearmar(UPLOAD_SEM_AVANCO_MS);
      if (e.lengthComputable) avisar({ nome, enviado: e.loaded, total: e.total });
    };
    // Bytes entregues: entra na fase 2 (servidor gravando).
    xhr.upload.onloadend = () => { rearmar(UPLOAD_ESPERA_RESPOSTA_MS); avisar({ nome, gravando: true }); };
    xhr.onload = () => {
      encerrar();
      let j = {};
      try { j = JSON.parse(xhr.responseText || '{}'); } catch (e) { /* resposta não-JSON (proxy, HTML de erro) */ }
      if (xhr.status < 200 || xhr.status >= 300) {
        return reject(new Error(j.erro || `Falha ao enviar "${nome}" (erro ${xhr.status}).`));
      }
      resolve({ id: j.id, nome: j.nome || nome, tipo: j.tipo || tipo });
    };
    xhr.onerror = () => { encerrar(); reject(new Error(`Sem conexão ao enviar "${nome}". Confira a internet e tente de novo.`)); };
    xhr.onabort = () => {
      encerrar();
      reject(new Error(parou
        ? `O envio de "${nome}" (${fmtTamanho(blob && blob.size)}) parou de responder e foi cancelado. Tente de novo; se repetir, use um arquivo menor.`
        : `Envio de "${nome}" cancelado.`));
    };
    rearmar(UPLOAD_SEM_AVANCO_MS);
    xhr.send(fd);
  });
}
const ehImagem = (tipo) => /^image\//.test(tipo || '');
function urlMidia(m) { return m.id ? '/api/midia/' + encodeURIComponent(m.id) : (m._url || ''); }

// ---------- Prévia de PDF na miniatura do documento (aba Documentos de Funcionários) ----------
// pdf.js SOB DEMANDA (só quando existe PDF sem prévia em cache) — não pesa quando não há PDF.
// Servido LOCALMENTE (public/pdf.min.mjs + pdf.worker.min.mjs), não por CDN: CDNs externas são
// bloqueadas por proxies corporativos/firewalls (mesmo motivo do qrcode.js) — era por isso que a
// prévia nunca aparecia para quem está numa rede assim, mesmo sem erro visível. Falhou mesmo
// assim (PDF corrompido...)? cai de volta pro selo "PDF" de sempre — nunca trava, sem erro pro usuário.
let _pdfjsPromise = null;
function carregarPdfJs() {
  if (window.pdfjsLib) return Promise.resolve(window.pdfjsLib);
  if (_pdfjsPromise) return _pdfjsPromise;
  _pdfjsPromise = import('/pdf.min.mjs').then((lib) => {
    lib.GlobalWorkerOptions.workerSrc = '/pdf.worker.min.mjs'; // mesma origem — sem CDN, sem truque de blob
    window.pdfjsLib = lib;
    return lib;
  }).catch((e) => { _pdfjsPromise = null; throw e; });
  return _pdfjsPromise;
}
// Cache em memória (chave = id no cofre OU _url local do arquivo ainda não salvo) — gera a
// miniatura da 1ª página só uma vez por documento, mesmo com vários re-renders da lista.
// Valor '' = já tentou e falhou (não tenta de novo); null = em andamento.
const _pdfPreviewCache = new Map();
let _pdfPreviewFila = Promise.resolve(); // serializa os renders — evita pico de CPU com vários PDFs juntos
function pdfPreviewChave(m) { return (m && (m.id || m._url)) || ''; }
// TETO da prévia. Gerar a miniatura obriga o navegador a DECODIFICAR a página inteira: uma
// digitalização sem compressão de ~5 megapixels vira ~19 MB de bitmap, o bastante para derrubar
// a aba num celular. Acima do teto o documento simplesmente fica com o selo "PDF" — não é erro,
// é o mesmo visual de antes da prévia existir. (O teto é por TAMANHO do arquivo, que é o que dá
// para saber sem abrir o PDF; não cobre um JPEG pequeno com resolução absurda.)
const PDF_PREVIA_MAX_BYTES = 3 * 1024 * 1024;
// Descobre o tamanho de um arquivo já salvo sem baixar o conteúdo (HEAD devolve só cabeçalhos).
async function pdfPesadoDemais(src) {
  try {
    const r = await fetch(src, { method: 'HEAD' });
    return Number(r.headers.get('content-length') || 0) > PDF_PREVIA_MAX_BYTES;
  } catch (e) {
    return false; // não deu para saber o tamanho: segue e tenta a prévia
  }
}
async function gerarPdfPreview(src, blob) {
  // Confere o peso ANTES de carregar o pdf.js: o arquivo pendente já traz o tamanho no Blob;
  // o que está no cofre é consultado por HEAD (sem transferir os megabytes).
  const pesado = blob ? blob.size > PDF_PREVIA_MAX_BYTES : await pdfPesadoDemais(src);
  if (pesado) return ''; // sem prévia, sem erro — fica o selo "PDF"
  const pdfjsLib = await carregarPdfJs();
  // Buscamos os bytes nós mesmos (em vez de passar a URL pro pdf.js buscar): o stream interno
  // dele não lida bem com blob: (prévia local ainda não salva) em todo navegador.
  // Arquivo ainda NÃO salvo: lê do próprio Blob. Não dá pra fazer fetch('blob:...') — a CSP tem
  // connect-src 'self' (sem blob:) e o navegador recusa ("Refused to connect"), então a prévia de
  // um PDF recém-anexado nunca era gerada. Ler do Blob também dispensa a ida à rede.
  const bytes = blob ? await blob.arrayBuffer() : await fetch(src).then(r => r.arrayBuffer());
  const pdf = await pdfjsLib.getDocument({ data: bytes }).promise;
  const page = await pdf.getPage(1);
  // ~2x o MAIOR box que exibe esta prévia (a do painel de edição, 132px) — nítido em tela retina
  // e ainda barato (1 página). A miniatura do resumo (40px) só reduz a mesma imagem.
  const alvo = 264;
  const escala = alvo / page.getViewport({ scale: 1 }).width;
  const viewport = page.getViewport({ scale: escala });
  const canvas = document.createElement('canvas');
  canvas.width = viewport.width; canvas.height = viewport.height;
  await page.render({ canvasContext: canvas.getContext('2d'), viewport }).promise;
  const dataUrl = canvas.toDataURL('image/png');
  pdf.destroy();
  return dataUrl;
}
// Listas que exibem prévia de PDF nas miniaturas. Era fixo na ficha do colaborador; virou registro
// para os anexos da multa (mesmo componente) aproveitarem o MESMO gerador/cache, sem duplicá-lo.
// A função devolve o array de trabalho (não o array direto) porque este registro é avaliado antes
// da declaração das listas — e a lista pode ser substituída inteira depois.
// `sel` (opcional) diz onde injetar a prévia dentro do container — sem ele vale o par
// padrão da ficha do colaborador (.func-doc-ver/.func-doc-prev por data-i).
// Ex. de registro de uma lista nova de cards:
//   _pdfPreviewListas.push({ lista: 'meusCards', work: () => MEUS_ITENS,
//     sel: (idx) => `.doc-card-mini[data-i="${idx}"]` });
const _pdfPreviewListas = [
  { lista: 'funcDocsLista', work: () => docsFuncWork },
  { lista: 'multaDocsLista', work: () => (typeof docsMultaWork === 'undefined' ? [] : docsMultaWork) },
  { lista: 'acaoDocsLista', work: () => (typeof evidAcaoWork === 'undefined' ? [] : evidAcaoWork) },
  // Cards da aba Documentos (empresa) e de Multas·Termos: arrays-adaptador preenchidos no
  // render de cada aba, na MESMA ordem dos cards (data-i = índice).
  { lista: 'documentoCards', work: () => _docsEmpresaPrev, sel: (idx) => `.doc-card-mini[data-i="${idx}"]` },
  { lista: 'termosMultaCards', work: () => _termosMultaPrev, sel: (idx) => `.doc-card-mini[data-i="${idx}"]` },
];
var _docsEmpresaPrev = [];  // {id, tipo, nome} do arquivo de cada card visível (aba Documentos)
var _termosMultaPrev = [];  // idem para Multas·Termos
// Troca o selo "PDF" pela prévia real, achando a linha pela CHAVE (não pelo índice: a lista
// pode ter sido reordenada/reduzida enquanto o render assíncrono ainda estava em andamento).
function aplicarPdfPreview(chave, dataUrl) {
  if (!dataUrl) return;
  for (const alvo of _pdfPreviewListas) {
    const idx = (alvo.work() || []).findIndex(d => pdfPreviewChave(d) === chave);
    if (idx === -1) continue;
    const cont = document.getElementById(alvo.lista);
    if (!cont) continue;
    // DOIS lugares mostram a prévia: a miniatura do resumo (.func-doc-ver) e a prévia grande do
    // painel de edição (.func-doc-prev). Preencher só a primeira deixava a do painel travada no
    // selo "PDF" até um re-render.
    const seletor = alvo.sel ? alvo.sel(idx) : '.func-doc-ver[data-i="' + idx + '"], .func-doc-prev[data-i="' + idx + '"]';
    cont.querySelectorAll(seletor).forEach(el => {
      if (el.querySelector('img')) return;
      el.innerHTML = `<img class="doc-preview-nova" src="${dataUrl}" alt="" loading="lazy" />`;
    });
  }
}
function pedirPdfPreview(m) {
  const chave = pdfPreviewChave(m);
  const src = chave && urlMidia(m);
  if (!chave || !src || _pdfPreviewCache.has(chave)) return;
  _pdfPreviewCache.set(chave, null); // marca "em andamento" — não entra na fila de novo
  _pdfPreviewFila = _pdfPreviewFila
    .then(() => gerarPdfPreview(src, m && m._file))
    .then((dataUrl) => { _pdfPreviewCache.set(chave, dataUrl); aplicarPdfPreview(chave, dataUrl); })
    // A prévia é um extra: falhar não pode atrapalhar o usuário (cai no selo "PDF"). Mas o erro
    // vai para o console — engoli-lo por completo tornava impossível descobrir POR QUE não
    // aparece (biblioteca bloqueada, PDF corrompido, aba em segundo plano...).
    .catch((e) => {
      _pdfPreviewCache.set(chave, '');
      console.warn('[prévia PDF] não foi possível gerar a miniatura de', chave, '—', e && e.message, e);
    });
}

// ---------- Miniatura + visor nos cards de documento (Documentos da empresa e Multas·Termos) ----------
// Ex. de uso (dentro do render dos cards, com `prev` = array-adaptador na ordem dos cards):
//   html += miniaturaDocCard(d.arquivo, i, 'PDF');           // no template do card
//   prev.forEach((m) => { if (m.tipo === 'application/pdf') pedirPdfPreview(m); });  // após o innerHTML
// Clique no card (fora dos botões) → abrirVisorDocCard(prev, i).
function miniaturaDocCard(arq, idx, selo) {
  if (!arq || !arq.id) return `<span class="empresa-icone arquivo" aria-hidden="true">${esc(selo)}</span>`;
  if (ehImagem(arq.tipo)) return `<span class="empresa-icone arquivo doc-card-mini" data-i="${idx}" aria-hidden="true"><img class="doc-preview-nova" src="${esc(urlMidia(arq))}" alt="" loading="lazy" /></span>`;
  if (arq.tipo === 'application/pdf') return `<span class="empresa-icone arquivo doc-card-mini" data-i="${idx}" aria-hidden="true">${esc(selo)}</span>`;
  return `<span class="empresa-icone arquivo" aria-hidden="true">${esc(selo)}</span>`;
}
// Abre o card `i` no visor: imagem/PDF entram no lightbox (com galeria dos demais visualizáveis
// da pasta); formatos sem renderização inline vão para nova aba/download.
function abrirVisorDocCard(prev, i) {
  const m = prev && prev[i];
  if (!m || !m.id) return;
  if (!ehImagem(m.tipo) && m.tipo !== 'application/pdf') {
    const src = urlMidia(m);
    if (src) window.open(src, '_blank', 'noopener');
    return;
  }
  const veiaveis = prev.filter((x) => x && x.id && (ehImagem(x.tipo) || x.tipo === 'application/pdf'));
  abrirMidia(veiaveis, veiaveis.indexOf(m));
}

// Lightbox: mostra imagem grande ou abre o PDF embutido
// Lightbox com galeria: aceita 1 item OU uma lista + índice, com setas e teclado.
let _midiaLista = [], _midiaIdx = 0;
function abrirMidia(lista, idx) {
  _midiaLista = (Array.isArray(lista) ? lista : [lista]).filter(Boolean);
  _midiaIdx = Math.max(0, Math.min(idx || 0, _midiaLista.length - 1));
  if (!_midiaLista.length) return;
  // PDF agora abre DENTRO do visor (iframe do renderMidiaAtual), com botão "abrir em nova
  // aba" como saída para quem preferir o visualizador do navegador. Outros formatos sem
  // renderização inline (docx, pfx, zip...) continuam indo para a nova aba/download.
  const atual = _midiaLista[_midiaIdx];
  if (atual && !ehImagem(atual.tipo) && atual.tipo !== 'application/pdf') {
    const src = urlMidia(atual) || atual._url;
    if (src) window.open(src, '_blank', 'noopener');
    return;
  }
  renderMidiaAtual();
  const modal = document.getElementById('midiaModal');
  modal.hidden = false;
  const fechar = document.getElementById('fecharMidia');
  if (fechar) fechar.focus(); // leva o foco para dentro do modal (acessibilidade)
}
function renderMidiaAtual() {
  const m = _midiaLista[_midiaIdx];
  if (!m) return;
  const visor = document.getElementById('midiaVisor');
  const src = urlMidia(m);
  const total = _midiaLista.length;
  const miolo = ehImagem(m.tipo)
    ? `<img src="${esc(src)}" alt="${esc(m.nome || '')}" />`
    : `<iframe src="${esc(src)}" title="${esc(m.nome || 'documento')}"></iframe>`;
  const nav = total > 1
    ? `<button type="button" class="midia-nav midia-prev" aria-label="Anterior">‹</button>
       <button type="button" class="midia-nav midia-next" aria-label="Próxima">›</button>
       <span class="midia-contador">${_midiaIdx + 1} / ${total}</span>`
    : '';
  // Baixar o arquivo (só p/ mídia já salva no cofre; o "download" usa o nome com extensão coerente).
  const baixar = m.id ? `<a class="midia-baixar" href="${esc(src)}" download="${esc(nomeMidiaComExt(m))}" title="Baixar arquivo">⬇ Baixar</a>` : '';
  // PDF no iframe: oferece a saída para o visualizador nativo do navegador.
  const novaAba = !ehImagem(m.tipo) ? `<a class="midia-baixar midia-novaaba" href="${esc(src)}" target="_blank" rel="noopener" title="Abrir no visualizador do navegador">↗ Nova aba</a>` : '';
  visor.innerHTML = miolo + nav + novaAba + baixar;
  const p = visor.querySelector('.midia-prev'), n = visor.querySelector('.midia-next');
  if (p) p.onclick = (e) => { e.stopPropagation(); navMidia(-1); };
  if (n) n.onclick = (e) => { e.stopPropagation(); navMidia(1); };
  const b = visor.querySelector('.midia-baixar'); if (b) b.onclick = (e) => e.stopPropagation();
}
function navMidia(d) {
  if (_midiaLista.length < 2) return;
  _midiaIdx = (_midiaIdx + d + _midiaLista.length) % _midiaLista.length;
  renderMidiaAtual();
}
// Extensão de arquivo a partir do tipo MIME (os nomes de documento são salvos sem extensão).
function extDeTipo(tipo) {
  return ({ 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif', 'application/pdf': 'pdf' })[tipo] || '';
}
// Nome de download com extensão coerente: usa o nome salvo e, se ele não tiver nenhuma
// extensão, acrescenta a do tipo MIME (documentos são salvos sem extensão, ex.: "ASO" → "ASO.pdf").
function nomeMidiaComExt(m) {
  let nome = (m && m.nome) || 'arquivo';
  if (!/\.[a-z0-9]{2,4}$/i.test(nome)) { const ext = extDeTipo(m && m.tipo); if (ext) nome += '.' + ext; }
  return nome;
}
// Baixa uma mídia direto (sem abrir o lightbox): vale p/ arquivo salvo no cofre ou prévia local.
async function baixarMidia(m) {
  const src = m && (urlMidia(m) || m._url);
  if (!src) return;
  const nome = nomeMidiaComExt(m); // garante extensão coerente (documento "ASO" → "ASO.pdf")
  const disparar = (href) => {
    const a = document.createElement('a');
    a.href = href; a.download = nome;
    document.body.appendChild(a); a.click(); a.remove();
  };
  // Arquivo ainda não salvo (data:/blob: local): baixa direto, sem rede.
  if (!m.id) { disparar(src); return; }
  // Com id no cofre: busca antes de baixar — se o servidor responder erro (arquivo removido,
  // sessão expirada...), avisa num toast em vez de baixar um ".json" de erro sem explicação.
  try {
    const r = await fetch(src, { cache: 'no-store' });
    if (!r.ok) {
      let msg = `Não foi possível baixar (erro ${r.status}).`;
      if (r.status === 404) msg = 'Este arquivo não está mais disponível no site (foi removido do cofre).';
      else if (r.status === 401) msg = 'Sua sessão expirou. Recarregue a página e entre novamente.';
      else if (r.status === 403) msg = 'Você não tem permissão para baixar este arquivo.';
      toast(msg, 'erro');
      return;
    }
    const blob = await r.blob();
    const objUrl = URL.createObjectURL(blob);
    disparar(objUrl);
    setTimeout(() => URL.revokeObjectURL(objUrl), 5000);
  } catch (e) {
    toast('Falha de conexão ao baixar o arquivo.', 'erro');
  }
}
// HTML de um anexo único (PPP na desmobilização / documento de programa SST):
// miniatura real (imagem) ou selo PDF + nome + baixar + remover. Reusado pelos dois fluxos.
function progDocItemHTML(m, nomePadrao) {
  const src = urlMidia(m);
  const miolo = ehImagem(m.tipo) && src ? `<img src="${esc(src)}" alt="" loading="lazy" />` : '<span class="func-doc-pdf">PDF</span>';
  return `<div class="prog-doc-item">
    <button type="button" class="prog-doc-ver" title="Ver em tamanho real">${miolo}</button>
    <span class="prog-doc-nome">${esc(m.nome || nomePadrao)}</span>
    <button type="button" class="prog-doc-baixar" title="Baixar" aria-label="Baixar">⬇</button>
    <button type="button" class="prog-doc-rem" title="Remover" aria-label="Remover">✕</button>
  </div>`;
}
function fecharMidiaModal() { document.getElementById('midiaModal').hidden = true; document.getElementById('midiaVisor').innerHTML = ''; _midiaLista = []; }
// Teclado quando o lightbox está aberto: setas navegam, Esc fecha, Tab fica preso.
document.addEventListener('keydown', (e) => {
  const modal = document.getElementById('midiaModal');
  if (modal.hidden) return;
  if (e.key === 'ArrowLeft') navMidia(-1);
  else if (e.key === 'ArrowRight') navMidia(1);
  else if (e.key === 'Escape') fecharMidiaModal();
  else prenderFoco(modal, e);
});
document.getElementById('fecharMidia').onclick = fecharMidiaModal;
fecharAoClicarNoFundo('midiaModal', fecharMidiaModal);

// Crachá do colaborador: fechar (botão / fundo / Esc) e imprimir (window.print c/ CSS @media print).
(() => {
  const fechar = document.getElementById('fecharCracha');
  if (fechar) fechar.onclick = fecharCracha;
  fecharAoClicarNoFundo('crachaModal', fecharCracha);
  const imp = document.getElementById('crachaImprimir');
  // Tela: crachá pequeno (max-width 460). Impressão: o @media print dimensiona o card em mm p/
  // preencher a folha A4 (não depende de JS).
  if (imp) imp.onclick = () => window.print();
  document.addEventListener('keydown', (e) => {
    const m = document.getElementById('crachaModal');
    if (!m || m.hidden) return;
    if (e.key === 'Escape') fecharCracha();
    else prenderFoco(m, e);
  });
})();

// Renderiza as miniaturas de uma lista de mídias (de trabalho) num container, com remover.
// opts.capa = true mostra a 1ª como "Capa" e permite tornar qualquer outra a capa (★).
// Revoga os object URLs locais de uma lista de mídias (evita vazar Blobs na memória do navegador).
function liberarUrls(arr) { for (const m of (arr || [])) if (m && m._url) { URL.revokeObjectURL(m._url); m._url = ''; } }
function renderThumbs(containerId, work, onChange, opts = {}) {
  const cont = document.getElementById(containerId);
  cont.innerHTML = work.map((m, i) => {
    const src = urlMidia(m);
    const miolo = ehImagem(m.tipo)
      ? `<img src="${esc(src)}" alt="" />`
      : `<span class="thumb-pdf">PDF</span>`;
    const capa = opts.capa
      ? (i === 0
          ? `<span class="thumb-capa-badge">Capa</span>`
          : `<button type="button" class="thumb-capa" data-i="${i}" title="Tornar capa">★</button>`)
      : '';
    return `<div class="midia-thumb${opts.capa && i === 0 ? ' eh-capa' : ''}" data-i="${i}">
        <button type="button" class="thumb-abrir" data-i="${i}" title="Ver">${miolo}</button>
        ${capa}
        <button type="button" class="thumb-remover" data-i="${i}" title="Remover">✕</button>
        <span class="thumb-nome" title="${esc(m.nome || '')}">${esc(trunc(m.nome || '', 16))}</span>
      </div>`;
  }).join('');
  cont.querySelectorAll('.thumb-abrir').forEach(b => b.onclick = () => abrirMidia(work, +b.dataset.i));
  cont.querySelectorAll('.thumb-remover').forEach(b => b.onclick = () => { const [rem] = work.splice(+b.dataset.i, 1); if (rem && rem._url) URL.revokeObjectURL(rem._url); onChange(); });
  cont.querySelectorAll('.thumb-capa').forEach(b => b.onclick = () => { const i = +b.dataset.i; const [m] = work.splice(i, 1); work.unshift(m); onChange(); });
}

// Processa arquivos escolhidos: comprime imagens e adiciona à lista de trabalho (preview local)
async function adicionarArquivos(files, work, onChange, soImagem) {
  for (const file of files) {
    if (soImagem && !/^image\//.test(file.type)) { toast('Só são aceitas imagens aqui.', 'erro'); continue; }
    if (!soImagem && !/^image\//.test(file.type) && file.type !== 'application/pdf') { toast('Aceita apenas imagem ou PDF.', 'erro'); continue; }
    const blob = await comprimirImagem(file);
    if (blob.size > 9 * 1024 * 1024) { toast(`"${file.name}" é muito grande (máx. 9 MB).`, 'erro'); continue; }
    work.push({ _file: blob, _url: URL.createObjectURL(blob), nome: file.name, tipo: /^image\//.test(file.type) ? 'image/jpeg' : file.type });
  }
  onChange();
}
// Drag-and-drop de anexos, compartilhado por qualquer modal que aceite arquivos (ficha do
// colaborador, multa). O aviso de soltar fica LIMITADO ao quadro tracejado de anexar (a zona):
// um overlay de tela cheia (versões anteriores) cobria as linhas de documento e brigava com o
// arrastar-para-substituir por linha. Enquanto o arrasto passeia pelo modal a zona ganha um
// realce sutil ("dá para soltar aqui"); só COM o arquivo sobre a zona ela acende de vez.
//   modalId  = o .modal-overlay que precisa estar visível;
//   zonaId   = o quadro tracejado que recebe o arquivo (ex.: funcDocsDrop);
//   ativo(modal) = quando o arrasto vale (ex.: só na aba Documentos);
//   aoSoltar(files) = o que fazer com os arquivos soltos NA ZONA.
function instalarDropOverlay({ modalId, zonaId, ativo, aoSoltar }) {
  const modal = document.getElementById(modalId);
  const zona = document.getElementById(zonaId);
  if (!modal || !zona) return;
  const podeAnexar = () => !modal.hidden && (!ativo || ativo(modal));
  // Só reage ao arrasto de ARQUIVOS (ignora arrastar texto/campos internos do formulário).
  const temArquivo = (e) => { const dt = e.dataTransfer; return !!dt && Array.from(dt.types || []).includes('Files'); };
  // Durante o arrasto o texto do quadro vira o convite de soltar (ele é o único aviso agora).
  const txtZona = zona.querySelector('.fdrop-txt');
  const txtOriginal = txtZona ? txtZona.innerHTML : '';
  const marcarArrasto = (on) => {
    if (zona.classList.contains('arrastando') !== on) { // dragover dispara em rajada; só escreve na troca
      zona.classList.toggle('arrastando', on);
      if (txtZona) txtZona.innerHTML = on ? '<b>Solte os arquivos aqui</b> para anexar' : txtOriginal;
    }
    if (!on) zona.classList.remove('dragover');
  };
  // Fim de arrasto limpa tudo: o realce da zona e o destaque de substituição das linhas —
  // se a linha sumir num re-render ou o arrasto terminar fora, o dragleave dela nunca dispara.
  const limparEstados = () => {
    marcarArrasto(false);
    document.querySelectorAll('.func-doc-row.solta-substituir').forEach(r => r.classList.remove('solta-substituir'));
  };
  window.addEventListener('dragover', (e) => {
    if (modal.hidden || !temArquivo(e)) return;
    e.preventDefault(); // impede o navegador de abrir o arquivo se soltar fora das áreas válidas
    // Zona e linha têm handlers próprios com stopPropagation; chegar aqui = cursor fora delas.
    if (e.dataTransfer) e.dataTransfer.dropEffect = 'none';
    marcarArrasto(podeAnexar());
  });
  window.addEventListener('drop', (e) => {
    if (modal.hidden || !temArquivo(e)) return;
    e.preventDefault(); // soltou fora da zona e fora de linha: só cancela a navegação
    limparEstados();
  });
  // Segurança: arrasto cancelado (Esc/solto fora da janela) também limpa o realce.
  window.addEventListener('dragend', limparEstados);
  // A zona em si: acende cheia com o arquivo por cima, e é o ÚNICO lugar que anexa.
  zona.addEventListener('dragover', (e) => {
    if (!temArquivo(e) || !podeAnexar()) return;
    e.preventDefault(); e.stopPropagation();
    if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
    zona.classList.add('dragover');
  });
  zona.addEventListener('dragleave', (e) => {
    // dragleave borbulha dos filhos da zona; sair de um filho para outro NÃO é sair da zona.
    if (e.relatedTarget && zona.contains(e.relatedTarget)) return;
    zona.classList.remove('dragover');
  });
  zona.addEventListener('drop', async (e) => {
    if (!temArquivo(e)) return;
    e.preventDefault(); e.stopPropagation();
    limparEstados();
    if (!podeAnexar()) return;
    const files = (e.dataTransfer && e.dataTransfer.files) ? [...e.dataTransfer.files] : [];
    if (files.length) await aoSoltar(files);
  });
}
// Envia ao servidor as mídias ainda não enviadas (_file) e devolve só as refs {id,nome,tipo}
async function subirPendentes(work) {
  const refs = [];
  for (const m of work) {
    if (m.id) { refs.push({ id: m.id, nome: m.nome, tipo: m.tipo }); continue; }
    const ref = await enviarMidia(m._file, m.nome, m.tipo);
    refs.push(ref);
  }
  return refs;
}

/* ---------- Instalações: filtros, render, modal ---------- */
function valoresUnicosInst(campo) {
  return [...new Set(INSTALACOES.map(i => i[campo]).filter(x => x && String(x).trim()))].sort((a, b) => String(a).localeCompare(String(b), 'pt-BR'));
}
function popularFiltrosInst() {
  if (MSEL.fiColaborador) MSEL.fiColaborador.setOpcoes(valoresUnicosInst('colaborador'));
  if (MSEL.fiPlaca) MSEL.fiPlaca.setOpcoes(valoresUnicosInst('placa'));
  if (MSEL.fiSerie) MSEL.fiSerie.setOpcoes(valoresUnicosInst('numeroSerie'));
}
function popularDatalistsInst() {
  const colab = [...new Set([...(CADASTROS.responsaveis || []), ...INSTALACOES.map(i => i.colaborador)].filter(Boolean))].sort((a, b) => a.localeCompare(b, 'pt-BR'));
  document.getElementById('listaColaboradores').innerHTML = colab.map(c => `<option value="${esc(c)}">`).join('');
  // Códigos/ID disponíveis (N° Cobli dos rastreadores) + os já usados em instalações
  const placaDeCodigo = {};
  for (const r of RASTREADORES) if (r.codigo) placaDeCodigo[String(r.codigo).toUpperCase()] = r.placa || '';
  const codigos = [...new Set([...RASTREADORES.map(r => r.codigo), ...INSTALACOES.map(i => i.numeroSerie)].filter(Boolean))].sort();
  document.getElementById('listaSeries').innerHTML = codigos.map(c => {
    const p = placaDeCodigo[String(c).toUpperCase()];
    return `<option value="${esc(c)}"${p ? ` label="${esc(c)} · ${esc(p)}"` : ''}>`;
  }).join('');
  document.getElementById('listaPlacasInst').innerHTML = [...new Set(VEICULOS.map(v => v.placa))].sort().map(p => `<option value="${esc(p)}">`).join('');
}
function aplicarFiltrosInst() {
  const q = document.getElementById('buscaInst').value.trim().toLowerCase();
  const fC = getSel('fiColaborador'), fP = getSel('fiPlaca'), fS = getSel('fiSerie');
  const de = parseBR(document.getElementById('fiDe').value), ate = parseBR(document.getElementById('fiAte').value);
  return INSTALACOES.filter(i => {
    if (fC.length && !fC.includes(i.colaborador)) return false;
    if (fP.length && !fP.includes(i.placa)) return false;
    if (fS.length && !fS.includes(i.numeroSerie)) return false;
    if (de || ate) { const d = parseBR(i.data); if (!d) return false; if (de && d < de) return false; if (ate && d > ate) return false; }
    if (q) {
      const blob = [i.placa, i.numeroSerie, i.colaborador, i.veiculoEquip, i.local, i.observacoes, i.data].join(' ').toLowerCase();
      if (!blob.includes(q)) return false;
    }
    return true;
  });
}
function renderInstalacoes() {
  popularFiltrosInst();
  popularDatalistsInst();
  const tempoInst = (x) => { const d = parseBR(x.data); return d ? d.getTime() : x.ts; };
  let lista = aplicarFiltrosInst().slice().sort((a, b) => tempoInst(b) - tempoInst(a));
  const cont = document.getElementById('galeriaInst');
  estadoVazio('instVazio', INSTALACOES.length, lista.length, 'Nenhuma instalação registrada ainda. Clique em "+ Registrar instalação".', () => document.getElementById('btnLimparInst').click());
  cont.innerHTML = lista.map(i => {
    const capa = i.fotos && i.fotos[0];
    const extra = (i.fotos && i.fotos.length > 1) ? `<span class="inst-mais">+${i.fotos.length - 1}</span>` : '';
    const placa = /[A-Z0-9]/i.test(i.placa || '') ? i.placa.toUpperCase() : '';
    return `<div class="inst-card" data-id="${esc(i.id)}">
      <div class="inst-capa" data-id="${esc(i.id)}" title="Ver fotos">
        ${capa ? `<img src="/api/midia/${encodeURIComponent(capa.id)}" alt="" loading="lazy" />` : `<span class="inst-semfoto">sem foto</span>`}
        ${extra}
      </div>
      <div class="inst-info">
        <div class="inst-topo">
          <b>${esc(i.numeroSerie) || 'Sem código'}</b>
          ${placa ? `<button class="placa-btn placa-chip" data-placa="${esc(placa)}" title="Ver histórico do veículo">${esc(placa)}</button>` : ''}
        </div>
        <div class="inst-meta">
          ${i.data ? `<span>📅 ${esc(fmtData(i.data))}</span>` : ''}
          ${i.colaborador ? `<span>👷 ${esc(i.colaborador)}</span>` : ''}
          ${i.local ? `<span>📍 ${esc(trunc(i.local, 26))}</span>` : ''}
        </div>
        ${i.veiculoEquip ? `<div class="inst-equip">${esc(trunc(i.veiculoEquip, 40))}</div>` : ''}
        ${i.observacoes ? `<div class="inst-obs" title="${esc(i.observacoes)}">${esc(trunc(i.observacoes, 60))}</div>` : ''}
      </div>
      <div class="inst-acoes">
        <button class="edit edit-inst" data-id="${esc(i.id)}" title="Editar" aria-label="Editar">${ICONE_LAPIS}</button>
        <button class="del del-inst" data-id="${esc(i.id)}" title="Excluir" aria-label="Excluir">${ICONE_LIXEIRA}</button>
      </div>
    </div>`;
  }).join('');
  document.getElementById('resumoInst').innerHTML = `Exibindo <b>${lista.length}</b> de <b>${INSTALACOES.length}</b> instalações`;
  cont.querySelectorAll('.edit-inst').forEach(b => b.onclick = (e) => { e.stopPropagation(); abrirInstModal(b.dataset.id); });
  cont.querySelectorAll('.del-inst').forEach(b => b.onclick = (e) => { e.stopPropagation(); excluirInst(b.dataset.id); });
  // Card inteiro clicável abre a galeria (exceto botões/placa). A capa também conta como clique no card.
  cont.querySelectorAll('.inst-card').forEach(card => card.onclick = (e) => {
    if (e.target.closest('button, .placa-btn, .inst-acoes')) return;
    const i = INSTALACOES.find(x => x.id === card.dataset.id);
    if (i && i.fotos && i.fotos.length) abrirMidia(i.fotos, 0);
  });
  cont.querySelectorAll('.placa-btn').forEach(b => b.onclick = (e) => { e.stopPropagation(); abrirHistVeiculo(b.dataset.placa); });
}

const formInst = document.getElementById('formInst');
function abrirInstModal(id) {
  editandoInstId = id || null;
  formInst.reset();
  document.getElementById('instTitulo').textContent = id ? 'Editar instalação' : 'Registrar instalação';
  liberarUrls(fotosInstWork); fotosInstWork = [];
  if (id) {
    const i = INSTALACOES.find(x => x.id === id);
    for (const campo of ['data', 'colaborador', 'veiculoEquip', 'numeroSerie', 'placa', 'local', 'observacoes']) {
      if (formInst.elements[campo]) formInst.elements[campo].value = i[campo] ?? '';
    }
    fotosInstWork = (i.fotos || []).map(f => Object.assign({}, f));
  } else if (formInst.elements['data']) {
    formInst.elements['data'].value = hojeBR(); // novo registro: já vem com a data de hoje
  }
  refreshFotosInst();
  popularDatalistsInst();
  document.getElementById('instModal').hidden = false;
}
async function fecharInstModal(forcar) {
  // Não descarta silenciosamente fotos novas anexadas (clique fora / Esc / Cancelar).
  if (!forcar && fotosInstWork.some(m => m._file)) {
    if (!(await confirmar('Descartar este cadastro e as fotos já anexadas?', { perigo: true, okTexto: 'Descartar' }))) return;
  }
  document.getElementById('instModal').hidden = true;
}
function refreshFotosInst() { renderThumbs('fotosInstGrade', fotosInstWork, refreshFotosInst, { capa: true }); }
document.getElementById('btnAddInst').onclick = () => abrirInstModal(null);
document.getElementById('fecharInst').onclick = fecharInstModal;
document.getElementById('cancelarInst').onclick = fecharInstModal;
fecharAoClicarNoFundo('instModal', fecharInstModal);
document.getElementById('btnAddFotoInst').onclick = () => document.getElementById('inputFotoInst').click();
document.getElementById('inputFotoInst').onchange = async (e) => {
  const files = [...e.target.files]; e.target.value = '';
  await adicionarArquivos(files, fotosInstWork, refreshFotosInst, true);
};
formInst.addEventListener('submit', async (e) => {
  e.preventDefault();
  if (!fotosInstWork.length) { toast('Anexe ao menos uma foto da instalação.', 'erro'); return; }
  const btn = formInst.querySelector('button[type="submit"]'); btn.disabled = true;
  try {
    const fotos = await subirPendentes(fotosInstWork);
    const dados = {};
    for (const el of formInst.elements) if (el.name) dados[el.name] = el.value;
    dados.fotos = fotos;
    if (editandoInstId) dados.id = editandoInstId;
    const metodo = editandoInstId ? 'PUT' : 'POST';
    const url = editandoInstId ? '/api/instalacoes/' + encodeURIComponent(editandoInstId) : '/api/instalacoes';
    const r = await fetch(url, { method: metodo, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(dados) });
    if (!r.ok) { const j = await r.json().catch(() => ({})); throw new Error(j.erro || 'Erro ao salvar.'); }
    fecharInstModal(true); // salvou → fecha sem perguntar
    await garantirCadastrado('responsaveis', dados.colaborador); // colaborador novo vira entidade cadastrada
    await carregarInstalacoes();
    toast(editandoInstId ? 'Instalação atualizada!' : 'Instalação registrada!', 'ok');
  } catch (err) { toast(err.message || 'Erro ao salvar.', 'erro'); }
  finally { btn.disabled = false; }
});
async function excluirInst(id) {
  const i = INSTALACOES.find(x => x.id === id);
  if (!(await confirmar(`Excluir esta instalação${i && i.numeroSerie ? ' (código ' + i.numeroSerie + ')' : ''}? As fotos também serão removidas.`, { perigo: true, okTexto: 'Excluir' }))) return;
  const r = await fetch('/api/instalacoes/' + encodeURIComponent(id), { method: 'DELETE' });
  if (!r.ok) { toast('Erro ao excluir.', 'erro'); return; }
  await carregarInstalacoes();
  toast('Instalação excluída.', 'ok');
}
const rerenderInst = debounce(renderInstalacoes);
['buscaInst', 'fiDe', 'fiAte'].forEach(id => {
  const el = document.getElementById(id);
  el.addEventListener('input', rerenderInst);
  el.addEventListener('change', renderInstalacoes);
});
[['fiColaborador', 'Colaborador'], ['fiPlaca', 'Placa'], ['fiSerie', 'Código/ID']]
  .forEach(([fid, rot]) => criarMultiSelect(fid, rot, renderInstalacoes));
document.getElementById('btnLimparInst').onclick = () => {
  document.getElementById('buscaInst').value = '';
  document.getElementById('fiDe').value = '';
  document.getElementById('fiAte').value = '';
  ['fiColaborador', 'fiPlaca', 'fiSerie'].forEach(fid => MSEL[fid] && MSEL[fid].limpar());
  renderInstalacoes();
};

// ----- Máscara automática de data (DD/MM/AAAA) — só nos campos da aba Instalações -----
function dataValidaBR(v) {
  const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(String(v).trim());
  if (!m) return false;
  const dd = +m[1], mm = +m[2], yy = +m[3];
  if (mm < 1 || mm > 12 || dd < 1 || dd > 31 || yy < 1900 || yy > 2200) return false;
  const dt = new Date(yy, mm - 1, dd);
  return dt.getFullYear() === yy && dt.getMonth() === mm - 1 && dt.getDate() === dd; // rejeita 31/02 etc.
}
function aplicarMascaraData(input) {
  if (!input || input._mascaraData) return;
  input._mascaraData = true;
  input.setAttribute('inputmode', 'numeric');
  input.setAttribute('maxlength', '10');
  input.addEventListener('input', () => {
    const d = input.value.replace(/\D/g, '').slice(0, 8);
    let out = d;
    if (d.length > 4) out = d.slice(0, 2) + '/' + d.slice(2, 4) + '/' + d.slice(4);
    else if (d.length > 2) out = d.slice(0, 2) + '/' + d.slice(2);
    input.value = out;
    input.classList.remove('data-invalida');
  });
  input.addEventListener('blur', () => {
    const v = input.value.trim();
    if (!v) { input.classList.remove('data-invalida'); return; }
    const ok = dataValidaBR(v);
    input.classList.toggle('data-invalida', !ok);
    // motivo específico ("junho tem só 30 dias") em vez do genérico "use DD/MM/AAAA" —
    // para 31/06 o formato está certo, o problema é o calendário.
    if (!ok && v.length === 10) toast(erroDataBR(v), 'erro'); // só avisa quando "parece" completa
  });
}
// Máscara de data automática em TODO campo de data do site (qualquer input com
// placeholder ".../aaaa"): Frota, Multas (inclui etapas do Detran), Rastreadores,
// Envios e Instalações. Campos de data novos que sigam essa convenção já nascem
// com a formatação automática — sem precisar ligar campo por campo.
document.querySelectorAll('input[placeholder*="/aaaa" i]').forEach(aplicarMascaraData);

// Máscara de hora (hh:mm) automática em todo campo de hora (placeholder "hh:mm").
function aplicarMascaraHora(input) {
  if (!input || input._mascaraHora) return;
  input._mascaraHora = true;
  input.setAttribute('inputmode', 'numeric');
  input.setAttribute('maxlength', '5');
  input.addEventListener('input', () => {
    let d = input.value.replace(/\D/g, '').slice(0, 4);
    if (d.length >= 3) d = d.slice(0, 2) + ':' + d.slice(2);
    input.value = d;
    input.classList.remove('data-invalida');
  });
  input.addEventListener('blur', () => {
    const v = input.value.trim();
    if (!v) { input.classList.remove('data-invalida'); return; }
    const m = /^(\d{2}):(\d{2})$/.exec(v);
    const ok = m && +m[1] <= 23 && +m[2] <= 59;
    input.classList.toggle('data-invalida', !ok);
    if (!ok && v.length === 5) toast('Hora inválida: use hh:mm.', 'erro');
  });
}
document.querySelectorAll('input[placeholder*="hh:mm" i]').forEach(aplicarMascaraHora);

// Máscara de milhar viva p/ campos de dinheiro (digitar 1000 vira 1.000; aceita
// centavos com vírgula: 1.180,50). numBR() já desfaz os pontos no cálculo. Aplicada
// só a inputs com a classe .sim-money (nunca em % ou contagem de parcelas).
function aplicarMascaraMilhar(input) {
  if (!input || input._mascaraMilhar) return;
  input._mascaraMilhar = true;
  input.setAttribute('inputmode', 'decimal');
  input.addEventListener('input', () => {
    // conta dígitos E vírgula à esquerda do cursor (incluir a vírgula evita que, ao digitá-la,
    // o cursor caia ANTES dela e o próximo decimal entre na parte inteira: 45000,5 → 450.005,)
    const antes = input.value.slice(0, input.selectionStart).replace(/[^\d,]/g, '').length;
    let s = input.value.replace(/[^\d,]/g, '');           // mantém só dígitos e vírgula
    const iv = s.indexOf(',');
    const temVirg = iv >= 0;
    let intP = (temVirg ? s.slice(0, iv) : s).replace(/,/g, '');
    const decP = temVirg ? s.slice(iv + 1).replace(/,/g, '').slice(0, 2) : ''; // máx. 2 casas
    intP = intP.replace(/^0+(?=\d)/, '');                  // remove zeros à esquerda (mantém "0")
    const intFmt = intP === '' ? '' : intP.replace(/\B(?=(\d{3})+(?!\d))/g, '.'); // agrupa milhar
    input.value = intFmt + (temVirg ? ',' + decP : '');
    // recoloca o cursor após a mesma quantidade de dígitos/vírgula que havia à sua esquerda
    let c = 0, p = 0;
    for (; p < input.value.length && c < antes; p++) if (/[\d,]/.test(input.value[p])) c++;
    input.setSelectionRange(p, p);
  });
}
document.querySelectorAll('input.sim-money').forEach(aplicarMascaraMilhar);

// ----- Ao escolher um Código/ID ligado a uma placa, puxa Placa + Veículo/equipamento -----
function autofillPorCodigo() {
  const campo = formInst.elements['numeroSerie'];
  const cod = (campo.value || '').trim().toUpperCase();
  if (!cod) return;
  const r = RASTREADORES.find(x => (x.codigo || '').toUpperCase() === cod);
  if (!r || !r.placa) return; // código novo ou sem placa vinculada: não mexe em nada
  const placaEl = formInst.elements['placa'];
  if (placaEl) placaEl.value = (r.placa || '').toUpperCase();
  const equipEl = formInst.elements['veiculoEquip'];
  const veic = VEICULOS.find(v => (v.placa || '').toUpperCase() === (r.placa || '').toUpperCase());
  if (equipEl && veic) {
    const desc = [veic.modelo, veic.versao].filter(Boolean).join(' ').trim();
    if (desc) equipEl.value = desc;
  }
}
if (formInst && formInst.elements['numeroSerie']) {
  formInst.elements['numeroSerie'].addEventListener('input', autofillPorCodigo);
  formInst.elements['numeroSerie'].addEventListener('change', autofillPorCodigo);
}

// ----- Fotos padrão (ilustrações) para quem não tem uma foto real do equipamento -----
const PRESET_SVG = (icone, rotulo) => `<svg xmlns="http://www.w3.org/2000/svg" width="900" height="600" viewBox="0 0 900 600">
  <defs><linearGradient id="g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#4a5058"/><stop offset="1" stop-color="#1d2024"/></linearGradient></defs>
  <rect width="900" height="600" fill="url(#g)"/>
  <g transform="translate(270 138) scale(15)" fill="none" stroke="#fff" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round">${icone}</g>
  <text x="450" y="545" font-family="Arial, sans-serif" font-size="46" font-weight="bold" fill="#fff" text-anchor="middle">${rotulo}</text>
</svg>`;
const ICONE_CAMINHAO = '<path d="M10 17h4V5H2v12h3"/><path d="M20 17h2v-3.34a4 4 0 0 0-1.17-2.83L19 9h-5v8h1"/><circle cx="7.5" cy="17.5" r="2.5"/><circle cx="17.5" cy="17.5" r="2.5"/>';
const ICONE_CAMINHONETE = '<path d="M3 15V11h2l2-3.5h4V11h10v4"/><circle cx="7" cy="17" r="2"/><circle cx="17" cy="17" r="2"/>';
const ICONE_CARRO = '<path d="M19 17h2c.6 0 1-.4 1-1v-3c0-.9-.7-1.7-1.5-1.9C18.7 10.6 16 10 16 10s-1.3-1.4-2.2-2.3c-.5-.4-1.1-.7-1.8-.7H5c-.6 0-1.1.4-1.4.9l-1.4 2.9A3.7 3.7 0 0 0 2 12v4c0 .6.4 1 1 1h2"/><circle cx="7" cy="17" r="2"/><circle cx="17" cy="17" r="2"/>';
