// Converte o SVG da ilustração em PNG (no canvas) — o servidor não aceita SVG por segurança.
function svgParaPngBlob(svg) {
  return new Promise((resolve) => {
    const url = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
    const img = new Image();
    img.onload = () => {
      const cv = document.createElement('canvas');
      cv.width = 900; cv.height = 600;
      const ctx = cv.getContext('2d');
      ctx.fillStyle = '#1d2024'; ctx.fillRect(0, 0, 900, 600); // fundo sólido de garantia
      ctx.drawImage(img, 0, 0, 900, 600);
      cv.toBlob((blob) => resolve(blob), 'image/png', 0.92);
    };
    img.onerror = () => resolve(null);
    img.src = url;
  });
}
(function montarFotosPadrao() {
  const cont = document.getElementById('fotosPadrao');
  if (!cont) return;
  for (const f of FOTOS_PADRAO) {
    const svg = PRESET_SVG(f.icone, f.rotulo);
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'foto-padrao-btn';
    b.title = 'Usar foto padrão: ' + f.rotulo;
    b.innerHTML = `<span class="fp-thumb">${svg}</span><span class="fp-rotulo">${f.rotulo}</span>`;
    b.onclick = async () => {
      const blob = await svgParaPngBlob(svg);
      if (!blob) { toast('Não foi possível gerar a foto padrão.', 'erro'); return; }
      fotosInstWork.push({ _file: blob, _url: URL.createObjectURL(blob), nome: 'padrao-' + f.chave + '.png', tipo: 'image/png' });
      refreshFotosInst();
      toast(`Foto padrão "${f.rotulo}" adicionada.`, 'ok');
    };
    cont.appendChild(b);
  }
})();

