/* ---------- Envios: filtros, render, pílula de status, modal ---------- */
function classeStatusEnvio(s) {
  const u = (s || '').toLowerCase();
  if (u.includes('aguard')) return 'e-aguardando';
  if (u.includes('trânsito') || u.includes('transito')) return 'e-transito';
  if (u.includes('entreg')) return 'e-entregue';
  if (u.includes('extrav')) return 'e-extraviado';
  return 'e-devolvido';
}
function statusPillEnvio(en) {
  const itens = STATUS_ENVIO.map(o => `<button type="button" class="pill-item ${classeStatusEnvio(o)}" data-valor="${o}">${o}</button>`).join('');
  return `<div class="pill-select" data-id="${esc(en.id)}" data-campo="status">
      <button type="button" class="pill-trigger ${classeStatusEnvio(en.status)}" title="Clique para alterar"><span>${esc(en.status)}</span>${CHEVRON}</button>
      <div class="pill-menu" hidden><div class="pill-itens">${itens}</div></div>
    </div>`;
}
function valoresUnicosEnvio(campo) {
  return [...new Set(ENVIOS.map(e => e[campo]).filter(x => x && String(x).trim()))].sort((a, b) => String(a).localeCompare(String(b), 'pt-BR'));
}
function popularFiltrosEnvio() {
  if (MSEL.feTipo) MSEL.feTipo.setOpcoes(valoresUnicosEnvio('tipoItem'));
  if (MSEL.feStatus) MSEL.feStatus.setOpcoes(STATUS_ENVIO);
  if (MSEL.feDestinatario) MSEL.feDestinatario.setOpcoes(valoresUnicosEnvio('destinatario'));
}
function popularDatalistsEnvio() {
  document.getElementById('listaDestinatarios').innerHTML = valoresUnicosEnvio('destinatario').map(d => `<option value="${esc(d)}">`).join('');
  const transp = [...new Set(['Correios', ...ENVIOS.map(e => e.transportadora)].filter(Boolean))].sort((a, b) => a.localeCompare(b, 'pt-BR'));
  document.getElementById('listaTransportadoras').innerHTML = transp.map(t => `<option value="${esc(t)}">`).join('');
}
function aplicarFiltrosEnvio() {
  const q = document.getElementById('buscaEnvio').value.trim().toLowerCase();
  const fT = getSel('feTipo'), fS = getSel('feStatus'), fD = getSel('feDestinatario');
  const de = parseBR(document.getElementById('feDe').value), ate = parseBR(document.getElementById('feAte').value);
  return ENVIOS.filter(en => {
    if (filtroCardEnvio && classeStatusEnvio(en.status) !== filtroCardEnvio) return false;
    if (fT.length && !fT.includes(en.tipoItem)) return false;
    if (fS.length && !fS.includes(en.status)) return false;
    if (fD.length && !fD.includes(en.destinatario)) return false;
    if (de || ate) { const d = parseBR(en.dataEnvio); if (!d) return false; if (de && d < de) return false; if (ate && d > ate) return false; }
    if (q) {
      const blob = [en.tipoItem, en.destinatario, en.transportadora, en.codigoRastreamento, en.status, en.observacoes].join(' ').toLowerCase();
      if (!blob.includes(q)) return false;
    }
    return true;
  });
}
const CAMPOS_ENVIO = [
  { titulo: 'Ações' }, { titulo: 'Tipo', campo: 'tipoItem' }, { titulo: 'Destinatário', campo: 'destinatario' },
  { titulo: 'Envio', campo: 'dataEnvio', tipo: 'data' }, { titulo: 'Transportadora', campo: 'transportadora' },
  { titulo: 'Cód. rastreamento', campo: 'codigoRastreamento' }, { titulo: 'Status', campo: 'status' },
  { titulo: 'Entrega', campo: 'dataEntrega', tipo: 'data' }, { titulo: 'Comprovante' }, { titulo: 'Observações', campo: 'observacoes' },
];
let ordemEnvio = { campo: '', dir: 1 };
function renderEnvios() {
  popularFiltrosEnvio();
  popularDatalistsEnvio();
  const cab = document.getElementById('cabecalhoEnvios');
  cab.innerHTML = CAMPOS_ENVIO.map(c => {
    // A coluna "Ações" precisa de .col-acoes p/ o cabeçalho congelar junto com o corpo
    // (td.acoes é sticky) — senão, no scroll horizontal, o corpo fica e o cabeçalho desliza.
    // Outras colunas sem `campo` (Observação/Comprovante) seguem como <th> normal.
    if (!c.campo) return `<th${c.titulo === 'Ações' ? ' class="col-acoes"' : ''}>${c.titulo}</th>`;
    return `<th data-campo="${c.campo}" data-tipo="${c.tipo || 'texto'}" title="Clique para ordenar">${c.titulo}${iconeOrd(ordemEnvio.campo === c.campo, ordemEnvio.dir)}</th>`;
  }).join('');
  cab.querySelectorAll('th[data-campo]').forEach(th => th.onclick = () => {
    const campo = th.dataset.campo;
    if (ordemEnvio.campo === campo) ordemEnvio.dir *= -1; else { ordemEnvio.campo = campo; ordemEnvio.dir = 1; }
    renderEnvios();
  });
  let lista = aplicarFiltrosEnvio();
  if (ordemEnvio.campo) {
    const col = CAMPOS_ENVIO.find(c => c.campo === ordemEnvio.campo) || {};
    lista = lista.slice().sort((a, b) => {
      if (col.tipo === 'data') {
        const dx = parseBR(a[ordemEnvio.campo]), dy = parseBR(b[ordemEnvio.campo]);
        const vx = dx ? dx.getTime() : (ordemEnvio.dir === 1 ? Infinity : -Infinity);
        const vy = dy ? dy.getTime() : (ordemEnvio.dir === 1 ? Infinity : -Infinity);
        return (vx - vy) * ordemEnvio.dir;
      }
      return String(a[ordemEnvio.campo] ?? '').localeCompare(String(b[ordemEnvio.campo] ?? ''), 'pt-BR') * ordemEnvio.dir;
    });
  } else {
    lista = lista.slice().sort((a, b) => b.ts - a.ts);
  }
  const corpo = document.getElementById('corpoEnvios');
  estadoVazio('enviosVazio', ENVIOS.length, lista.length, 'Nenhum envio registrado ainda. Clique em "+ Registrar envio".', () => document.getElementById('btnLimparEnvio').click());
  corpo.innerHTML = lista.map(en => {
    const comp = (en.comprovantes && en.comprovantes.length)
      ? `<button class="comp-btn" data-id="${esc(en.id)}" title="Ver comprovante" aria-label="Ver ${en.comprovantes.length} comprovante(s) deste envio">📎 ${en.comprovantes.length}</button>`
      : '—';
    return `<tr data-id="${esc(en.id)}">
      <td class="acoes">
        <button class="edit edit-envio" data-id="${esc(en.id)}" title="Editar" aria-label="Editar">${ICONE_LAPIS}</button>
        <button class="del del-envio" data-id="${esc(en.id)}" title="Excluir" aria-label="Excluir">${ICONE_LIXEIRA}</button>
      </td>
      <td>${esc(en.tipoItem) || '—'}</td>
      <td>${esc(en.destinatario) || '—'}</td>
      <td>${esc(en.dataEnvio) || '—'}</td>
      <td>${esc(en.transportadora) || '—'}</td>
      <td>${en.codigoRastreamento ? `<span class="cod-rastr">${esc(en.codigoRastreamento)}</span>` : '—'}</td>
      <td>${statusPillEnvio(en)}</td>
      <td>${esc(en.dataEntrega) || '—'}</td>
      <td>${comp}</td>
      <td title="${esc(en.observacoes)}">${esc(trunc(en.observacoes, 36)) || '—'}</td>
    </tr>`;
  }).join('');
  document.getElementById('resumoEnvios').innerHTML = `Exibindo <b>${lista.length}</b> de <b>${ENVIOS.length}</b> envios`;
  renderCardsEnvios();
}
// Delegação de eventos: um listener só, registrado uma vez (não reanexa handlers a
// cada render). Alinha ao padrão das tabelas de Multas/Rastreadores.
document.getElementById('corpoEnvios').addEventListener('click', (e) => {
  const editBtn = e.target.closest('.edit-envio'); if (editBtn) { abrirEnvioModal(editBtn.dataset.id); return; }
  const delBtn = e.target.closest('.del-envio'); if (delBtn) { excluirEnvio(delBtn.dataset.id); return; }
  const compBtn = e.target.closest('.comp-btn'); if (compBtn) { const en = ENVIOS.find(x => x.id === compBtn.dataset.id); if (en && en.comprovantes.length) abrirMidia(en.comprovantes, 0); return; }
  const pTrig = e.target.closest('.pill-trigger'); if (pTrig) { e.stopPropagation(); const sel = pTrig.closest('.pill-select'); const aberto = sel.classList.contains('aberto'); fecharPillMenus(); if (!aberto) abrirPillMenu(sel); return; }
  const pItem = e.target.closest('.pill-item'); if (pItem) { e.stopPropagation(); const sel = donoPillMenu(pItem); if (!sel) return; fecharPillMenus(); alterarCampoEnvio(sel.dataset.id, sel.dataset.campo, pItem.dataset.valor); return; }
});
// (filtroCardEnvio é declarado junto do estado de ENVIOS, lá em cima.)
function renderCardsEnvios() {
  const cont = {};
  for (const en of ENVIOS) { const c = classeStatusEnvio(en.status); cont[c] = (cont[c] || 0) + 1; }
  const cls = (cor, st) => [cor, 'card-clic', filtroCardEnvio === st ? 'card-ativo' : ''].filter(Boolean).join(' ');
  const at = (st) => `data-st="${st}"`; // role/tabindex vêm do cardV2
  document.getElementById('cardsEnvios').innerHTML = `
    ${cardV2('Total', ENVIOS.length, cls('', ''), false, at(''))}
    ${cardV2('Aguardando', cont['e-aguardando'] || 0, cls('amber', 'e-aguardando'), false, at('e-aguardando'))}
    ${cardV2('Em trânsito', cont['e-transito'] || 0, cls('', 'e-transito'), false, at('e-transito'))}
    ${cardV2('Entregues', cont['e-entregue'] || 0, cls('green', 'e-entregue'), false, at('e-entregue'))}
    ${cardV2('Extraviados', cont['e-extraviado'] || 0, cls('red', 'e-extraviado'), false, at('e-extraviado'))}
    ${cardV2('Devolvidos', cont['e-devolvido'] || 0, cls('', 'e-devolvido'), false, at('e-devolvido'))}
  `;
  document.querySelectorAll('#cardsEnvios .v2-kpi[data-st]').forEach(c => {
    const acionar = () => { const st = c.dataset.st; filtroCardEnvio = (st === '' || filtroCardEnvio === st) ? '' : st; renderEnvios(); };
    c.onclick = acionar;
    c.onkeydown = (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); acionar(); } };
  });
}
async function alterarCampoEnvio(id, campo, valor, comDesfazer = true) {
  const en = ENVIOS.find(x => x.id === id);
  if (!en || en[campo] === valor) return;
  const anterior = en[campo];
  const at = Object.assign({}, en, { [campo]: valor });
  // Ao marcar como "Entregue", já preenche a data de entrega com hoje (se estiver vazia)
  if (campo === 'status' && /entreg/i.test(valor) && !at.dataEntrega) at.dataEntrega = hojeBR();
  const r = await fetch('/api/envios/' + encodeURIComponent(id), { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(at) });
  if (!r.ok) { toast('Erro ao alterar.', 'erro'); return; }
  Object.assign(en, at);
  renderEnvios(); renderPainelInst();
  const desfazer = comDesfazer ? { texto: 'Desfazer', fn: () => alterarCampoEnvio(id, campo, anterior, false) } : null;
  toast('Envio atualizado.', 'ok', desfazer);
}

const formEnvio = document.getElementById('formEnvio');
function abrirEnvioModal(id) {
  editandoEnvioId = id || null;
  formEnvio.reset();
  document.getElementById('envioTitulo').textContent = id ? 'Editar envio' : 'Registrar envio';
  liberarUrls(comprovWork); comprovWork = [];
  if (id) {
    const en = ENVIOS.find(x => x.id === id);
    for (const campo of ['tipoItem', 'destinatario', 'dataEnvio', 'transportadora', 'codigoRastreamento', 'status', 'dataEntrega', 'observacoes']) {
      if (formEnvio.elements[campo]) formEnvio.elements[campo].value = en[campo] ?? '';
    }
    comprovWork = (en.comprovantes || []).map(c => Object.assign({}, c));
  } else if (formEnvio.elements['dataEnvio']) {
    formEnvio.elements['dataEnvio'].value = hojeBR(); // novo envio: data de envio = hoje
  }
  refreshComprov();
  syncCustomSelects();
  popularDatalistsEnvio();
  document.getElementById('envioModal').hidden = false;
}
async function fecharEnvioModal(forcar) {
  if (!forcar && comprovWork.some(m => m._file)) {
    if (!(await confirmar('Descartar este envio e os comprovantes já anexados?', { perigo: true, okTexto: 'Descartar' }))) return;
  }
  document.getElementById('envioModal').hidden = true;
}
function refreshComprov() { renderThumbs('comprovantesGrade', comprovWork, refreshComprov); }
document.getElementById('btnAddEnvio').onclick = () => abrirEnvioModal(null);
document.getElementById('fecharEnvio').onclick = fecharEnvioModal;
document.getElementById('cancelarEnvio').onclick = fecharEnvioModal;
fecharAoClicarNoFundo('envioModal', fecharEnvioModal);
document.getElementById('btnAddComprovante').onclick = () => document.getElementById('inputComprovante').click();
document.getElementById('inputComprovante').onchange = async (e) => {
  const files = [...e.target.files]; e.target.value = '';
  await adicionarArquivos(files, comprovWork, refreshComprov, false);
};
formEnvio.addEventListener('submit', async (e) => {
  e.preventDefault();
  const btn = formEnvio.querySelector('button[type="submit"]'); btn.disabled = true;
  try {
    const comprovantes = await subirPendentes(comprovWork);
    const dados = {};
    for (const el of formEnvio.elements) if (el.name) dados[el.name] = el.value;
    dados.comprovantes = comprovantes;
    if (editandoEnvioId) dados.id = editandoEnvioId;
    const metodo = editandoEnvioId ? 'PUT' : 'POST';
    const url = editandoEnvioId ? '/api/envios/' + encodeURIComponent(editandoEnvioId) : '/api/envios';
    const r = await fetch(url, { method: metodo, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(dados) });
    if (!r.ok) { const j = await r.json().catch(() => ({})); throw new Error(j.erro || 'Erro ao salvar.'); }
    fecharEnvioModal(true); // salvou → fecha sem perguntar
    await carregarEnvios();
    toast(editandoEnvioId ? 'Envio atualizado!' : 'Envio registrado!', 'ok');
  } catch (err) { toast(err.message || 'Erro ao salvar.', 'erro'); }
  finally { btn.disabled = false; }
});
async function excluirEnvio(id) {
  const en = ENVIOS.find(x => x.id === id);
  if (!(await confirmar(`Excluir este envio${en ? ' (' + (en.tipoItem || 'item') + ')' : ''}? Os comprovantes também serão removidos.`, { perigo: true, okTexto: 'Excluir' }))) return;
  const r = await fetch('/api/envios/' + encodeURIComponent(id), { method: 'DELETE' });
  if (!r.ok) { toast('Erro ao excluir.', 'erro'); return; }
  await carregarEnvios();
  toast('Envio excluído.', 'ok');
}
const rerenderEnvio = debounce(renderEnvios);
['buscaEnvio', 'feDe', 'feAte'].forEach(id => {
  const el = document.getElementById(id);
  el.addEventListener('input', rerenderEnvio);
  el.addEventListener('change', renderEnvios);
});
[['feTipo', 'Tipo'], ['feStatus', 'Status'], ['feDestinatario', 'Destinatário']]
  .forEach(([fid, rot]) => criarMultiSelect(fid, rot, () => { filtroCardEnvio = ''; renderEnvios(); }));
document.getElementById('btnLimparEnvio').onclick = () => {
  document.getElementById('buscaEnvio').value = '';
  document.getElementById('feDe').value = '';
  document.getElementById('feAte').value = '';
  ['feTipo', 'feStatus', 'feDestinatario'].forEach(fid => MSEL[fid] && MSEL[fid].limpar());
  filtroCardEnvio = '';
  renderEnvios();
};

/* ---------- Painel (indicadores + gráficos) ---------- */
function renderPainelInst() {
  const agora = new Date();
  const mesAtual = agora.getFullYear() + '-' + String(agora.getMonth() + 1).padStart(2, '0');
  const mesDe = (d) => { const dt = parseBR(d); return dt ? dt.getFullYear() + '-' + String(dt.getMonth() + 1).padStart(2, '0') : ''; };
  const instMes = INSTALACOES.filter(i => mesDe(i.data) === mesAtual).length;
  const cont = {};
  for (const en of ENVIOS) cont[classeStatusEnvio(en.status)] = (cont[classeStatusEnvio(en.status)] || 0) + 1;
  const emTransito = cont['e-transito'] || 0;
  const entregues = cont['e-entregue'] || 0;
  const pendentes = cont['e-aguardando'] || 0;
  // "aguardando instalação": rastreadores Cobli ainda não entregues (a caminho do campo)
  const aguardandoInst = ENVIOS.filter(en => /rastreador/i.test(en.tipoItem || '') && !/entreg/i.test(en.status || '')).length;
  const wrap = document.getElementById('cardsPainelInst');
  if (wrap) wrap.innerHTML = `
    ${cardV2('Dispositivos instalados', INSTALACOES.length, '')}
    ${cardV2('Instalações no mês', instMes, 'green')}
    ${cardV2('Itens em trânsito', emTransito, 'amber')}
    ${cardV2('Itens entregues', entregues, 'green')}
    ${cardV2('Pendentes de postagem', pendentes, '')}
    ${cardV2('Aguardando instalação', aguardandoInst, 'red')}
  `;
  // Só desenha os gráficos quando o painel está visível (Chart precisa de container medido)
  const painelVisivel = document.getElementById('inst-painel') && document.getElementById('inst-painel').classList.contains('active');
  if (!painelVisivel) return;
  desenhar('chartEnvioStatus', 'doughnut', {
    labels: STATUS_ENVIO,
    datasets: [{ data: STATUS_ENVIO.map(s => cont[classeStatusEnvio(s)] || 0), backgroundColor: ['#f59e0b', '#3b82f6', '#22c55e', '#ef4444', '#94a3b8'] }],
  });
  // instalações por mês (últimos 6 meses)
  const meses = [];
  for (let k = 5; k >= 0; k--) { const d = new Date(agora.getFullYear(), agora.getMonth() - k, 1); meses.push(d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0')); }
  const rotMes = (ym) => { const [a, m] = ym.split('-'); return ['jan', 'fev', 'mar', 'abr', 'mai', 'jun', 'jul', 'ago', 'set', 'out', 'nov', 'dez'][+m - 1] + '/' + a.slice(2); };
  const contMes = {};
  for (const i of INSTALACOES) { const ym = mesDe(i.data); if (ym) contMes[ym] = (contMes[ym] || 0) + 1; }
  desenhar('chartInstMes', 'bar', {
    labels: meses.map(rotMes),
    datasets: [{ label: 'Instalações', data: meses.map(m => contMes[m] || 0), backgroundColor: '#1b56ff' }],
  }, { plugins: { legend: { display: false } }, scales: { y: { beginAtZero: true, ticks: { precision: 0 } } } });
}

/* ============================================================
   CONTRATOS (consórcios / financiamentos / empréstimos) · SÓ ADMIN
   ============================================================ */
let CONTRATOS = [];
let editandoContratoId = null;
let ordemContr = { campo: '', dir: 1 };
let paginaContr = 1;          // página atual da tabela
let porPaginaContr = 50;      // quantos lançamentos por página (Number ou 'all')
let totalPaginasContr = 1;    // total de páginas do último render (usado para travar "Próxima")
const SELECAO_CONTR = new Set(); // ids selecionados (persiste ao filtrar/buscar/paginar)
const EMPRESAS_CONTR = ['KV', 'NTE', 'ED', 'RICARDO', 'SUL'];
const BANCOS_CONTR = ['Itaú', 'Caixa', 'Bradesco', 'Disal', 'Embracom', 'BB'];
const PRODUTOS_CONTR = ['Consórcio', 'Financiamento', 'Empréstimo'];
const contrPago = (c) => (Number(c.valorPago) > 0) || !!(c.dataPagamento && String(c.dataPagamento).trim());
// Regra ÚNICA de parcela atrasada (espelho de contratoAtrasadoDados no backend/server.js —
// mudou lá, muda aqui): não paga E vencimento ANTES do início do dia de hoje. Vencer HOJE
// ainda não é atraso. Datas sempre em calendário local (parseBR), nunca ISO/UTC.
// Ex.: hoje 28/08/2026 → contrAtrasado({vencimento:'27/08/2026'}) = true (1 dia),
//      contrAtrasado({vencimento:'28/08/2026'}) = false.
const inicioHojeContr = () => { const d = new Date(); d.setHours(0, 0, 0, 0); return d; };
const contrAtrasado = (c) => { if (contrPago(c)) return false; const v = parseBR(c.vencimento); return !!v && v < inicioHojeContr(); };
// Marco COERENTE de parcelas pagas de uma série — ESPELHO de pagasAteCoerente no backend/server.js
// (mesma regra do completar-series e do scripts/corrigir-series-contratos.js; mudou lá, muda aqui).
// A maior evidência (nº realmente pago ou parcelasPagas declarado) vale só até a menor parcela
// EXISTENTE em aberto: aberta na frente refuta a declaração de uma parcela posterior.
// Ex.: pagasAteCoerente([{numero:1,pago:true},{numero:3,pago:false},{numero:4,pago:false,parcelasPagas:3}]) === 2
function pagasAteCoerente(itens, total) {
  let maiorEvidencia = 0;     // maior evidência por linha (declarada ou inferida)
  let menorAberta = Infinity; // menor nº de parcela EXISTENTE e em aberto
  for (const it of itens || []) {
    if (!Number.isInteger(it.numero) || it.numero < 1) continue;
    if (!it.pago) menorAberta = Math.min(menorAberta, it.numero);
    // Evidência da linha: parcelasPagas EXPLÍCITO tem precedência (0 é declaração válida —
    // "0 pagas" ≠ campo vazio); sem declaração, inferência estrutural: paga ⇒ nº, aberta ⇒ nº−1.
    const declarado = Number(it.parcelasPagas);
    const declarou = it.parcelasPagas !== '' && it.parcelasPagas !== null && it.parcelasPagas !== undefined
      && Number.isFinite(declarado) && declarado >= 0;
    maiorEvidencia = Math.max(maiorEvidencia, declarou ? declarado : (it.pago ? it.numero : it.numero - 1));
  }
  const teto = Number(total); // clamp: declaração corrompida (> total) não pode inflar o marco
  if (Number.isFinite(teto) && teto >= 1) maiorEvidencia = Math.min(maiorEvidencia, teto);
  if (!Number.isFinite(menorAberta)) return maiorEvidencia;      // nenhuma aberta (ou todas pagas)
  return Math.max(0, Math.min(maiorEvidencia, menorAberta - 1)); // aberta existente refuta a evidência
}
// Coluna "Faltam" da lista de Parcelas: POSICIONAL — quantas parcelas ainda vêm DEPOIS desta
// linha na série (total − nº da parcela), independente de pagamento. Não confundir com o
// Progresso (paga de maior nº / restantes), que é o estado financeiro da série. Exibição E
// ordenação usam esta MESMA função (espelho de faltamDaParcelaContrato no server, para o Excel).
// Sem "N/M" válido devolve null → a UI mostra "—" e o sort trata como ausente (NÃO usa o
// campo salvo: um registro sem PARC com parcelasFaltantes=0 aparecia como "Faltam 0" ao lado
// da 54/54 verdadeira).
// Ex.: faltamDaParcela({parcela:'10/20'}) === 10 · '11/20' → 9 · '20/20' → 0 · '54/54' → 0
//      faltamDaParcela({parcela:''}) === null · 'abc' → null · null → null
function faltamDaParcela(c) {
  const m = String((c && c.parcela) || '').match(/(\d+)\s*\/\s*(\d+)/);
  if (!m) return null;
  const numero = Number(m[1]), total = Number(m[2]);
  if (!Number.isFinite(numero) || !Number.isFinite(total) || total <= 0) return null;
  return Math.max(0, total - numero);
}
const diasAtrasoContr = (c) => (contrAtrasado(c) ? Math.round((inicioHojeContr() - parseBR(c.vencimento)) / 86400000) : 0);
// Saldo devedor = soma do valor das parcelas AINDA NÃO PAGAS (cada linha é uma parcela).
// (Antes multiplicava parcelasFaltantes × valorParcela em cada linha e somava → contava o
//  mesmo contrato ~33× e inflava o total para dezenas de milhões.)
const saldoDevedorContr = (c) => (contrPago(c) ? 0 : (Number(c.valorParcela) || 0));
// Identidade estável da série. No legado, Grupo/Cota identifica a mesma carta mesmo que
// a descrição do bem tenha mudado; sem esse par, a descrição identifica o contrato.
const chaveSerieContrato = (c) => {
  const serieId = String(c.serieId || '').trim();
  const texto = (x) => String(x || '').trim().replace(/\s+/g, ' ').toUpperCase();
  const grupo = texto(c.grupo), cota = texto(c.cota);
  const legado = grupo && cota ? ['GRUPO_COTA', grupo, cota] : ['DESCRICAO', texto(c.material)];
  return serieId ? `ID|${serieId}` : `LEGADO|${[texto(c.empresa), texto(c.banco), texto(c.produto), ...legado].join('|')}`;
};
// "MM/AAAA" de uma data (Date) — usado na previsão de quitação.
const mesAnoBR = (d) => d ? String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear() : '';

// A tabela deve mostrar exatamente a descrição cadastrada. Resumos como "Carta" escondiam
// o identificador do bem/contrato, que é justamente o trecho usado para diferenciar lançamentos.
function descricaoContr(c) {
  return String(c.material || '').trim();
}
// Ordenação PADRÃO (sem clicar em coluna): LISTA CRONOLÓGICA PLANA — todas as parcelas
// misturadas, ordenadas pela data de vencimento (mais antiga → mais nova). Sem blocos por
// contrato. Parcelas sem data vão para o fim. Empate de data desempata por banco/empresa/nº.
function parcNumContr(p) { const m = String(p || '').match(/\d+/); return m ? +m[0] : 0; }
function ordemPadraoContr(a, b) {
  const va = parseBR(a.vencimento), vb = parseBR(b.vencimento);
  if (va && vb && va.getTime() !== vb.getTime()) return va.getTime() - vb.getTime();
  if (va && !vb) return -1; if (!va && vb) return 1;
  let c = String(a.banco || '').localeCompare(String(b.banco || ''), 'pt-BR'); if (c) return c;
  c = String(a.empresa || '').localeCompare(String(b.empresa || ''), 'pt-BR'); if (c) return c;
  return parcNumContr(a.parcela) - parcNumContr(b.parcela);
}

// Recarrega CONTRATOS do servidor e re-renderiza. Devolve true quando a tela foi de fato
// atualizada e false quando a recarga falhou (rede/erro) — quem dispara mutação pode
// diferenciar "servidor gravou mas a tela ficou velha" de sucesso completo.
// Ex.: const ok = await carregarContratos(); if (!ok) toast('…atualize a página…', 'erro');
async function carregarContratos() {
  try {
    const r = await fetch('/api/contratos', { cache: 'no-store' });
    if (r.status === 401) { window.location = '/login'; return false; }
    if (!r.ok) { toast('Erro ao carregar os contratos. Tente novamente.', 'erro'); return false; }
    CONTRATOS = await r.json();
  } catch (e) { toast('Erro ao carregar os contratos. Verifique a conexão.', 'erro'); return false; }
  renderContratos(); renderCronogramaContr(); renderPainelContr();
  return true;
}

// Sub-abas (Parcelas | Cronograma | Painel)
document.querySelectorAll('#contratosSubtabs .subtab').forEach(b => b.onclick = () => {
  if (b.classList.contains('active')) return;
  document.querySelectorAll('#contratosSubtabs .subtab').forEach(x => x.classList.remove('active'));
  document.querySelectorAll('#contratos .subview').forEach(x => x.classList.remove('active'));
  b.classList.add('active');
  document.getElementById(b.dataset.sub).classList.add('active');
  const modoCronograma = b.dataset.sub === 'contr-cronograma';
  document.getElementById('contratos').classList.toggle('cronograma-ativo', modoCronograma);
  document.body.classList.toggle('cronograma-tela-cheia', modoCronograma);
  const ptc = document.getElementById('pageTitle'); if (ptc) ptc.textContent = 'Contratos › ' + b.textContent.trim();
  if (b.dataset.sub === 'contr-painel') renderPainelContr();
  if (b.dataset.sub === 'contr-cronograma') renderCronogramaContr();
});

/* ---------- Cronograma mensal (visão estilo planilha) ---------- */
function inicioMesContr(d) { return new Date(d.getFullYear(), d.getMonth(), 1); }
function chaveMesContr(d) { return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`; }
function somarMesContr(d, n) { return new Date(d.getFullYear(), d.getMonth() + n, 1); }
let cronoMesOffset = 0;
// `var` de propósito: o criarPainelFiltros do Cronograma (registrado lá em cima, junto dos
// outros painéis) lê esta flag no contarAtivos JÁ na criação — com let/const cairia na zona
// morta temporal e derrubaria o boot (mesmo motivo do `var PAINEIS_FILTROS`).
var cronoSoAtraso = false;   // chip "Só com atraso": mostra só contratos com parcela atrasada
let cronoIdsAtuais = [];     // ids das parcelas do recorte atual (TODOS os meses, não só os visíveis) — alimenta o export
function rotuloMesContr(d) {
  const nome = d.toLocaleDateString('pt-BR', { month: 'short' }).replace('.', '');
  return `${nome.charAt(0).toUpperCase()}${nome.slice(1)}/${String(d.getFullYear()).slice(-2)}`;
}
function ehConsorcioContr(c) { return /cons[oó]rcio/i.test(String(c.produto || '')); }
function identidadeCronoContr(c) {
  const numero = [c.grupo && `Grupo ${c.grupo}`, c.cota && `Cota ${c.cota}`].filter(Boolean).join(' · ');
  const descricao = descricaoContr(c);
  return {
    titulo: descricao || numero || String(c.produto || 'Contrato'),
    detalhe: [c.banco, numero].filter(Boolean).join(' · '),
  };
}
function consolidarParcelasCronoContr(parcelas) {
  const unicas = new Map();
  for (const p of parcelas) {
    const m = String(p.c.parcela || '').match(/(\d+)\s*\/\s*(\d+)/);
    const chave = m ? `${Number(m[1])}/${Number(m[2])}` : `id:${p.c.id}`;
    const atual = unicas.get(chave);
    const substituir = !atual
      || (contrPago(p.c) && !contrPago(atual.c))
      || (contrPago(p.c) === contrPago(atual.c) && Number(p.c.ts) > Number(atual.c.ts));
    if (substituir) unicas.set(chave, p);
  }
  return [...unicas.values()];
}
function referenciaCronoContr(parcelas) {
  const pagas = parcelas.filter(x => contrPago(x.c));
  if (pagas.length) return pagas.sort((a, b) => parcNumContr(b.c.parcela) - parcNumContr(a.c.parcela))[0].c;
  return parcelas.slice().sort((a, b) => a.data - b.data)[0]?.c || {};
}
function progressoCronoContr(parcelas, referencia = referenciaCronoContr(parcelas)) {
  const texto = String(referencia.parcela || '');
  const m = texto.match(/(\d+)\s*\/\s*(\d+)/);
  const atual = m ? Number(m[1]) : Number(referencia.parcelasPagas) || 0;
  const total = m ? Number(m[2]) : Number(referencia.totalParcelas) || 0;
  const faltam = total ? Math.max(0, total - atual) : Number(referencia.parcelasFaltantes) || 0;
  const largura = Math.max(2, String(total).length);
  return { atual, total, faltam, texto: total ? `${String(atual).padStart(largura, '0')}/${String(total).padStart(largura, '0')}` : (texto || '—'), pct: total ? Math.min(100, Math.max(0, atual / total * 100)) : 0 };
}
function renderCronogramaContr() {
  // Só recalcula quando a sub-aba Cronograma está visível — evita reagrupar/redesenhar a
  // planilha inteira a cada salvamento/baixa feito na sub-aba Parcelas (mesma ideia do guard
  // já usado em renderPainelContr). Ao abrir a sub-aba, o handler do subtab rechama.
  const cronoView = document.getElementById('contr-cronograma');
  if (!cronoView || !cronoView.classList.contains('active')) return;
  const cab = document.getElementById('contrCronoCab');
  const corpo = document.getElementById('contrCronoCorpo');
  const vazio = document.getElementById('contrCronoVazio');
  const resumo = document.getElementById('contrCronoResumo');
  if (!cab || !corpo || !vazio || !resumo) return;

  if (MSEL.fcrBanco) MSEL.fcrBanco.setOpcoes([...new Set([...BANCOS_CONTR, ...valoresUnicosContr('banco')])]);
  if (MSEL.fcrProduto) MSEL.fcrProduto.setOpcoes([...new Set([...PRODUTOS_CONTR, ...valoresUnicosContr('produto')])]);
  if (MSEL.fcrEmpresa) MSEL.fcrEmpresa.setOpcoes(valoresUnicosContr('empresa'));
  const q = String(document.getElementById('buscaCronoContr')?.value || '').trim().toLowerCase();
  const correspondeBusca = c => [c.material, c.grupo, c.cota, c.localCarro, c.banco, c.produto, c.empresa].join(' ').toLowerCase().includes(q);
  const seriesBusca = q ? new Set(CONTRATOS.filter(correspondeBusca).map(chaveSerieContrato)) : null;
  const fB = getSel('fcrBanco'), fP = getSel('fcrProduto'), fE = getSel('fcrEmpresa');
  const contratosFiltrados = CONTRATOS.filter(c => {
    if (fB.length && !fB.includes(c.banco)) return false;
    if (fP.length && !fP.includes(c.produto)) return false;
    if (fE.length && !fE.includes(c.empresa)) return false;
    if (seriesBusca && !seriesBusca.has(chaveSerieContrato(c))) return false;
    return true;
  });
  const hoje = new Date();
  const mesAtual = inicioMesContr(hoje);
  const comData = contratosFiltrados.map(c => ({ c, data: parseBR(c.vencimento) })).filter(x => x.data);

  const grupos = new Map();
  for (const { c, data } of comData) {
    const chave = chaveSerieContrato(c);
    if (!grupos.has(chave)) grupos.set(chave, { parcelas: [] });
    grupos.get(chave).parcelas.push({ c, data });
  }
  let linhas = [...grupos.values()].map(grupo => {
    const parcelas = consolidarParcelasCronoContr(grupo.parcelas);
    return { base: referenciaCronoContr(parcelas), parcelas };
  }).sort((a, b) => {
    const ia = identidadeCronoContr(a.base).titulo, ib = identidadeCronoContr(b.base).titulo;
    return ia.localeCompare(ib, 'pt-BR');
  });
  // O chip olha TODAS as parcelas do contrato (o conjunto filtrado), não só os meses na tela.
  if (cronoSoAtraso) linhas = linhas.filter(l => l.parcelas.some(x => contrAtrasado(x.c)));
  const chipAtraso = document.getElementById('fcrSoAtraso');
  if (chipAtraso) { chipAtraso.classList.toggle('on', cronoSoAtraso); chipAtraso.setAttribute('aria-pressed', cronoSoAtraso ? 'true' : 'false'); }
  const parcelasCrono = linhas.flatMap(linha => linha.parcelas);
  cronoIdsAtuais = parcelasCrono.map(x => x.c.id);
  const pendentes = parcelasCrono.filter(x => !contrPago(x.c));
  // Atrasada e futura são complementares dentro das pendentes — a soma sempre fecha.
  const emAtraso = pendentes.filter(x => contrAtrasado(x.c));
  const futuras = pendentes.filter(x => !contrAtrasado(x.c));

  // Janela de meses: 12 a partir do mês atual, ESTENDIDA para trás até o mês da parcela
  // MAIS ANTIGA do recorte (qualquer status — paga, atrasada ou a pagar). A timeline é o
  // CRONOGRAMA COMPLETO: antes a janela começava no mês atual e a coluna "Atrasadas antes de
  // hoje" dizia "2 atrasadas" sem as parcelas aparecerem em lugar nenhum; depois passou a
  // recuar só até a atrasada mais antiga, e as parcelas já PAGAS (01/80, 02/80) continuavam
  // fora da tela. Cada parcela é pendurada no mês REAL do vencimento (porMes, abaixo) — a
  // janela só garante que esse mês esteja entre as colunas. ‹/›/Hoje continuam deslocando a
  // janela (cronoMesOffset). Custo: contrato longo com muito histórico pago abre com mais
  // colunas (rolagem horizontal interna, sem limite — limite silencioso esconderia parcela).
  // Ex.: hoje = 31/08/2026, série 01/80 paga em Mai/26 … 04/80 atrasada em Ago/26 → colunas
  //      Mai/26 … Jul/27 (15 meses); recorte só com futuras → Ago/26 … Jul/27 (12).
  const inicioJanela = parcelasCrono.reduce((m, x) => { const mx = inicioMesContr(x.data); return mx < m ? mx : m; }, mesAtual);
  const mesesAtras = (mesAtual.getFullYear() - inicioJanela.getFullYear()) * 12 + (mesAtual.getMonth() - inicioJanela.getMonth());
  const primeiroMes = somarMesContr(inicioJanela, cronoMesOffset);
  const totalMeses = 12 + mesesAtras;
  const meses = Array.from({ length: totalMeses }, (_, i) => somarMesContr(primeiroMes, i));
  const fimPeriodo = meses[meses.length - 1];
  const periodo = document.getElementById('contrCronoPeriodo');
  if (periodo) periodo.textContent = `${rotuloMesContr(primeiroMes)} – ${rotuloMesContr(fimPeriodo)}`;

  cab.innerHTML = `<tr><th scope="col" class="contr-crono-id">Contrato</th><th scope="col" class="contr-crono-progresso-cab">Progresso</th><th scope="col" class="contr-crono-mes contr-crono-atrasadas">Atrasadas<span>antes de hoje</span></th>${meses.map(m => `<th scope="col" class="contr-crono-mes${chaveMesContr(m) === chaveMesContr(mesAtual) ? ' atual' : ''}">${rotuloMesContr(m)}${chaveMesContr(m) === chaveMesContr(mesAtual) ? '<span>mês atual</span>' : ''}</th>`).join('')}</tr>`;
  corpo.innerHTML = linhas.map(({ base, parcelas }) => {
    const ident = identidadeCronoContr(base);
    const prog = progressoCronoContr(parcelas, base);
    const veiculoBanco = ehConsorcioContr(base) ? (String(base.localCarro || '').trim() || String(base.banco || '').trim() || 'Não informado') : (String(base.banco || '').trim() || 'Não informado');
    const atrasadas = parcelas.filter(x => contrAtrasado(x.c));
    const porMes = new Map();
    for (const p of parcelas) {
      const k = chaveMesContr(p.data);
      if (!porMes.has(k)) porMes.set(k, []);
      porMes.get(k).push(p.c);
    }
    // REGRA DA CÉLULA: o mês TEM parcela quando `ps` (todas as parcelas do mês, qualquer
    // status) não está vazio — nunca use `!abertas.length` como "não existe parcela aqui".
    // A timeline é o cronograma completo; o status só decide aparência e indicadores:
    //   só pagas            → célula `paga`: MESMO verde da "a pagar" (nº da parcela + valor;
    //                         a data do pagamento fica só no title/aria — sem texto "Paga")
    //   abertas (± pagas)   → verde/vermelha com o valor EM ABERTO; pagas do mesmo mês
    //                         aparecem numa linha extra ("1 paga"), sem somar no valor.
    //   nada                → "—"
    // Os totais do rodapé/coluna "Atrasadas" NÃO leem daqui (vêm de emAtraso/futuras).
    // Ex.: Mai/26 [01/80 paga]           → <td class="… paga">01/80 · R$ 2.190,00</td>
    //      Jul/26 [03/80 atrasada]       → <td class="… atrasada">03/80 · R$ 2.190,00</td>
    //      Set/26 [05/80 paga, 06/80 ok] → <td class="… pendente">2 parcelas · R$ 2.190,00 · 1 paga</td>
    const plural = (n, um, varios) => (n === 1 ? um : varios);
    const rotuloParc = (lista) => (lista.length === 1 ? String(lista[0].parcela || 'Parcela') : `${lista.length} parcelas`);
    const somaValor = (lista) => lista.reduce((s, c) => s + (Number(c.valorParcela) || 0), 0);
    const celulas = meses.map(m => {
      const ps = porMes.get(chaveMesContr(m)) || [];
      if (!ps.length) return '<td class="contr-crono-cel sem-pendencia" title="Sem parcela neste mês"><span aria-hidden="true">—</span><span class="sr-only">Sem parcela neste mês</span></td>';
      const abertas = ps.filter(c => !contrPago(c));
      const pagas = ps.filter(c => contrPago(c));
      if (!abertas.length) { // mês só com parcela(s) paga(s): histórico, sem peso nos indicadores
        const valor = somaValor(pagas);
        const datas = [...new Set(pagas.map(c => String(c.dataPagamento || '').trim()).filter(Boolean))];
        const quando = datas.length ? ` em ${datas.join(', ')}` : '';
        const acessivel = `${pagas.length} ${plural(pagas.length, 'parcela paga', 'parcelas pagas')}${quando}${valor ? `, ${fmtMoneyDec(valor)}` : ''}`;
        const tituloCel = pagas.length > 1 ? `Abrir a 1ª de ${pagas.length} parcelas pagas deste mês` : `Parcela paga${quando}`;
        return `<td class="contr-crono-cel paga"><button type="button" class="contr-crono-acao" data-contr-id="${esc(pagas[0].id)}" aria-label="Abrir ${esc(acessivel)}${pagas.length > 1 ? ' (mostra a 1ª; use a lista para ver as demais)' : ''}" title="${esc(tituloCel)}"><span class="contr-crono-status">${esc(rotuloParc(pagas))}</span><strong>${esc(valor ? fmtMoneyDec(valor) : 'Paga')}</strong></button></td>`;
      }
      const valor = somaValor(abertas); // só o que está em aberto — o valor pago não entra
      const qtd = abertas.length;
      const vencida = abertas.some(c => contrAtrasado(c)); // parcela do mês já vencida → célula vermelha
      const texto = valor ? fmtMoneyDec(valor) : `${qtd} parcela${qtd > 1 ? 's' : ''}`;
      const parcTexto = rotuloParc(ps); // conta TODAS as parcelas do mês (pagas inclusive)
      const extraPagas = pagas.length ? `<small class="contr-crono-extra">${pagas.length} ${plural(pagas.length, 'paga', 'pagas')}</small>` : '';
      const acessivel = `${qtd} parcela${qtd > 1 ? 's' : ''} ${vencida ? 'atrasada' : 'pendente'}${qtd > 1 ? 's' : ''}${valor ? `, ${fmtMoneyDec(valor)}` : ''}${pagas.length ? ` e ${pagas.length} ${plural(pagas.length, 'paga', 'pagas')} neste mês` : ''}`;
      const tituloCel = ps.length > 1 ? `Abrir a 1ª de ${ps.length} parcelas deste mês` : (vencida ? 'Abrir parcela atrasada' : 'Abrir parcela');
      return `<td class="contr-crono-cel ${vencida ? 'atrasada' : 'pendente'}"><button type="button" class="contr-crono-acao" data-contr-id="${esc(abertas[0].id)}" aria-label="Abrir ${esc(acessivel)}${ps.length > 1 ? ' (mostra a 1ª; use a lista para ver as demais)' : ''}" title="${esc(tituloCel)}"><span class="contr-crono-status">${esc(parcTexto)}</span><strong>${esc(texto)}</strong>${extraPagas}</button></td>`;
    }).join('');
    const valorAtrasado = atrasadas.reduce((s, x) => s + (Number(x.c.valorParcela) || 0), 0);
    const tituloAtrasada = atrasadas.length > 1 ? `Abrir a 1ª de ${atrasadas.length} parcelas atrasadas` : 'Abrir parcela atrasada';
    const celulaAtrasadas = atrasadas.length
      ? `<td class="contr-crono-cel atrasada"><button type="button" class="contr-crono-acao" data-contr-id="${esc(atrasadas[0].c.id)}" aria-label="Abrir ${atrasadas.length} parcela${atrasadas.length > 1 ? 's' : ''} atrasada${atrasadas.length > 1 ? 's' : ''}, ${esc(fmtMoneyDec(valorAtrasado))}${atrasadas.length > 1 ? ' (mostra a 1ª; use a lista para ver as demais)' : ''}" title="${esc(tituloAtrasada)}"><span class="contr-crono-status">${atrasadas.length} atrasada${atrasadas.length > 1 ? 's' : ''}</span><strong>${esc(fmtMoneyDec(valorAtrasado))}</strong></button></td>`
      : '<td class="contr-crono-cel sem-pendencia" title="Sem parcelas atrasadas"><span aria-hidden="true">—</span><span class="sr-only">Sem parcelas atrasadas</span></td>';
    const badges = [base.produto, base.grupo && `Grupo ${base.grupo}`, base.cota && `Cota ${base.cota}`].filter(Boolean).map(x => `<span>${esc(x)}</span>`).join('');
    return `<tr><th scope="row" class="contr-crono-id"><button type="button" class="contr-crono-ir" title="Ir para a primeira parcela deste contrato no período exibido" aria-label="${esc(ident.titulo)}: ir para a primeira parcela"><strong>${esc(ident.titulo)}</strong></button><span class="contr-crono-local">${esc(veiculoBanco)} · ${esc(base.banco || '')} · ${esc(base.empresa || '')}</span><div class="contr-crono-badges">${badges}</div></th><td class="contr-crono-progresso"><div><strong>${esc(prog.texto)}</strong><span>${prog.faltam} restantes</span></div><div class="contr-crono-barra" role="progressbar" aria-label="Parcela ${prog.atual} de ${prog.total || 'total não informado'}; faltam ${prog.faltam}" aria-valuemin="0" aria-valuemax="${prog.total || 0}" aria-valuenow="${prog.atual}"><i style="--progresso:${prog.pct}%"></i></div></td>${celulaAtrasadas}${celulas}</tr>`;
  }).join('');
  vazio.hidden = linhas.length > 0;
  const valorFuturo = futuras.reduce((s, x) => s + (Number(x.c.valorParcela) || 0), 0);
  const valorAtraso = emAtraso.reduce((s, x) => s + (Number(x.c.valorParcela) || 0), 0);
  resumo.innerHTML = `<span class="contr-crono-legenda-status" aria-label="Legenda do cronograma"><small><i class="paga" aria-hidden="true"></i> Verde: paga</small><small><i class="pendente" aria-hidden="true"></i> Vermelho: não paga</small><small><i class="sem-pendencia" aria-hidden="true">—</i> Sem parcela</small></span><span><small>Contratos</small><b>${linhas.length}</b></span><span><small>Parcelas futuras</small><b>${futuras.length}</b></span><span><small>Valor previsto</small><b>${fmtMoneyDec(valorFuturo)}</b></span>${emAtraso.length ? `<span class="contr-crono-atraso"><small>Atrasadas</small><b>${emAtraso.length}</b></span><span class="contr-crono-atraso"><small>Valor em atraso</small><b>${fmtMoneyDec(valorAtraso)}</b></span>` : ''}`;
}

/* ---------- Parcelas ---------- */
function valoresUnicosContr(campo) {
  return [...new Set(CONTRATOS.map(c => c[campo]).filter(x => x && String(x).trim()))].sort((a, b) => String(a).localeCompare(String(b), 'pt-BR'));
}
function popularFiltrosContr() {
  if (MSEL.fcBanco) MSEL.fcBanco.setOpcoes([...new Set([...BANCOS_CONTR, ...valoresUnicosContr('banco')])]);
  if (MSEL.fcProduto) MSEL.fcProduto.setOpcoes([...new Set([...PRODUTOS_CONTR, ...valoresUnicosContr('produto')])]);
  if (MSEL.fcEmpresa) MSEL.fcEmpresa.setOpcoes(valoresUnicosContr('empresa'));
  if (MSEL.fcStatus) MSEL.fcStatus.setOpcoes(['Pago', 'Pendente']);
  if (MSEL.fcJustica) MSEL.fcJustica.setOpcoes(['Na justiça', 'Normal']);
  const dlBanco = document.getElementById('listaBancosC'); if (dlBanco) dlBanco.innerHTML = [...new Set([...BANCOS_CONTR, ...valoresUnicosContr('banco')])].map(x => `<option value="${esc(x)}">`).join('');
  const dlProd = document.getElementById('listaProdutosC'); if (dlProd) dlProd.innerHTML = [...new Set([...PRODUTOS_CONTR, ...valoresUnicosContr('produto')])].map(x => `<option value="${esc(x)}">`).join('');
  document.getElementById('listaEmpresasC').innerHTML = [...new Set([...EMPRESAS_CONTR, ...valoresUnicosContr('empresa')])].map(x => `<option value="${esc(x)}">`).join('');
  document.getElementById('listaGruposC').innerHTML = valoresUnicosContr('grupo').map(x => `<option value="${esc(x)}">`).join('');
}
// Busca e filtros da aba Parcelas como estão na tela agora (lidos UMA vez por filtragem).
// Ex.: estadoFiltrosContr() → { q: 'l200', fB: ['Bradesco'], fP: [], fE: [], fS: ['Pendente'], fJ: [] }
function estadoFiltrosContr() {
  return {
    q: document.getElementById('buscaContr').value.trim().toLowerCase(),
    fB: getSel('fcBanco'), fP: getSel('fcProduto'), fE: getSel('fcEmpresa'), fS: getSel('fcStatus'), fJ: getSel('fcJustica'),
  };
}
// Regra ÚNICA "esta linha aparece na lista?" — usada pela lista, pelo Excel (via aplicarFiltrosContr)
// e pelo aviso de parcelas escondidas, que testa uma linha com os dados trocados.
// Ex.: passaFiltrosContr({ banco: 'Bradesco', material: 'Carta', parcela: '53/54' }, { q: 'carta', fB: [], ... }) === true
function passaFiltrosContr(c, f) {
  if (f.fB.length && !f.fB.includes(c.banco)) return false;
  if (f.fP.length && !f.fP.includes(c.produto)) return false;
  if (f.fE.length && !f.fE.includes(c.empresa)) return false;
  if (f.fS.length && !f.fS.includes(contrPago(c) ? 'Pago' : 'Pendente')) return false;
  if (f.fJ.length && !f.fJ.includes(c.naJustica ? 'Na justiça' : 'Normal')) return false;
  if (f.q) {
    const grupoCota = [c.grupo, c.cota].filter(x => x !== '' && x != null).join(' / ');
    const blob = [c.banco, c.produto, c.fornecedor, c.material, c.empresa, c.grupo, c.cota, grupoCota, c.parcela, c.localCarro, c.escritorio].join(' ').toLowerCase();
    const normalizarBusca = texto => String(texto).replace(/\s*\/\s*/g, '/').replace(/\s+/g, ' ').trim();
    if (!normalizarBusca(blob).includes(normalizarBusca(f.q))) return false;
  }
  return true;
}
function aplicarFiltrosContr() {
  const f = estadoFiltrosContr();
  return CONTRATOS.filter(c => passaFiltrosContr(c, f));
}
const CAMPOS_CONTR = [
  { titulo: 'Banco', campo: 'banco' }, { titulo: 'Produto', campo: 'produto' }, { titulo: 'Emp.', campo: 'empresa' },
  { titulo: 'Descrição', campo: 'material' }, { titulo: 'Grupo/Cota', campo: 'grupo' }, { titulo: 'Parcela', campo: 'parcela' },
  { titulo: 'Faltam', campo: 'parcelasFaltantes', tipo: 'num' }, { titulo: 'Valor parc.', campo: 'valorParcela', tipo: 'num' },
  { titulo: 'Saldo quit.', campo: 'saldoQuitacao', tipo: 'num' }, { titulo: 'Vcto', campo: 'vencimento', tipo: 'data' },
  { titulo: 'Valor pago', campo: 'valorPago', tipo: 'num' }, { titulo: 'Status', campo: 'status' },
];
function statusPillContr(c) {
  const pago = contrPago(c);
  return `<div class="pill-select" data-id="${esc(c.id)}" data-campo="status">
      <button type="button" class="pill-trigger ${pago ? 'm-pago' : 'm-pendente'}" title="Clique para dar baixa / reverter" aria-haspopup="listbox" aria-expanded="false"><span>${pago ? 'Pago' : 'Pendente'}</span>${CHEVRON}</button>
      <div class="pill-menu" hidden role="listbox"><div class="pill-itens">
        <button type="button" class="pill-item m-pago" role="option" data-valor="Pago">Pago</button>
        <button type="button" class="pill-item m-pendente" role="option" data-valor="Pendente">Pendente</button>
      </div></div></div>`;
}
function atualizarBarraSelecaoContr() {
  const bar = document.getElementById('selBarContr');
  if (!bar) return;
  SEL_TODOS_CONTR.sincronizar(); // antes do return de "nada selecionado": o (N) do rótulo tem de seguir certo
  const sel = CONTRATOS.filter(c => SELECAO_CONTR.has(c.id));
  if (!sel.length) { bar.hidden = true; return; }
  const parc = sel.reduce((s, c) => s + (Number(c.valorParcela) || 0), 0);
  const devedor = sel.reduce((s, c) => s + saldoDevedorContr(c), 0);
  document.getElementById('selBarContrInfo').innerHTML =
    `<span class="sb-item"><b>${sel.length}</b> selecionado(s)</span>` +
    `<span class="sb-item">Parcelas: <b>${fmtMoneyDec(parc)}</b></span>` +
    `<span class="sb-item">Saldo devedor: <b>${fmtMoneyDec(devedor)}</b></span>`;
  bar.hidden = false;
}
// Baixa um Excel dos lançamentos informados. Vazio = avisa. Usado tanto pelo botão "Excel" (que
// exporta a lista já filtrada da tela) quanto — se algum dia precisar — por um subconjunto qualquer.
// Ex.: exportarContratosIds(cronoIdsAtuais, '', 'CRONOGRAMA-CONTRATOS-2026-08-28.xlsx', true, filtrosCronoContr())
//      (o 5º argumento só descreve os filtros no cabeçalho da aba Resumo — o recorte já vem em `ids`)
// baixa as parcelas do recorte do Cronograma com as colunas extras de atraso; sem os dois
// últimos parâmetros mantém o comportamento do botão Excel da aba Parcelas (CONTRATOS.xlsx).
async function exportarContratosIds(ids, mensagem = '', nomeArquivo = 'CONTRATOS.xlsx', cronograma = false, filtros = null) {
  if (!ids || !ids.length) { toast('Nada para exportar com os filtros atuais.', 'erro'); return; }
  try {
    const r = await fetch('/api/contratos/exportar', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(cronograma ? { ids, cronograma: true, filtros } : { ids }) });
    if (!r.ok) { toast('Erro ao exportar.', 'erro'); return; }
    const blob = await r.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = nomeArquivo;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1500);
    toast(mensagem || `Exportado: ${ids.length} lançamento(s).`, 'ok');
  } catch (e) { toast('Erro ao exportar.', 'erro'); }
}
// A lista na ORDEM da tela (ordenação manual da coluna clicada, senão a padrão por vencimento).
// Separada do renderContratos para quem precisa saber em que página uma linha cai.
// Ex.: ordenarListaContr(aplicarFiltrosContr()).findIndex(c => c.id === id) → posição na lista (0 = 1ª linha)
function ordenarListaContr(lista) {
  // Coluna "Faltam": posicional (total − nº) pela MESMA função da exibição — senão a tela
  // mostraria "9" mas ordenaria pelo valor salvo.
  if (ordemContr.campo) {
    const col = CAMPOS_CONTR.find(c => c.campo === ordemContr.campo) || {};
    const valNum = (r) => {
      if (ordemContr.campo !== 'parcelasFaltantes') return Number(r[ordemContr.campo]) || 0;
      const f = faltamDaParcela(r); // "—" (sem N/M) é AUSENTE, não 0: vai para o fim da crescente
      return f === null ? (ordemContr.dir === 1 ? Infinity : -Infinity) : f;
    };
    return lista.slice().sort((a, b) => {
      if (col.tipo === 'num') return (valNum(a) - valNum(b)) * ordemContr.dir;
      if (col.tipo === 'data') { const dx = parseBR(a[ordemContr.campo]), dy = parseBR(b[ordemContr.campo]); const vx = dx ? dx.getTime() : (ordemContr.dir === 1 ? Infinity : -Infinity); const vy = dy ? dy.getTime() : (ordemContr.dir === 1 ? Infinity : -Infinity); return (vx - vy) * ordemContr.dir; }
      return String(a[ordemContr.campo] ?? '').localeCompare(String(b[ordemContr.campo] ?? ''), 'pt-BR') * ordemContr.dir;
    });
  }
  // Sem ordenação manual: lista cronológica plana (por data de vencimento), sem blocos por contrato.
  return lista.slice().sort(ordemPadraoContr);
}
function renderContratos() {
  popularFiltrosContr();
  const cab = document.getElementById('cabecalhoContr');
  cab.innerHTML = '<th class="col-acoes">Ações</th>' +
    CAMPOS_CONTR.map(c => `<th data-campo="${c.campo}" data-tipo="${c.tipo || 'texto'}" title="Ordenar" aria-sort="${ordemContr.campo === c.campo ? (ordemContr.dir === 1 ? 'ascending' : 'descending') : 'none'}">${c.titulo}${iconeOrd(ordemContr.campo === c.campo, ordemContr.dir)}</th>`).join('');
  cab.querySelectorAll('th[data-campo]').forEach(th => th.onclick = () => {
    const campo = th.dataset.campo;
    if (ordemContr.campo === campo) ordemContr.dir *= -1; else { ordemContr.campo = campo; ordemContr.dir = 1; }
    paginaContr = 1;
    renderContratos();
  });
  const lista = ordenarListaContr(aplicarFiltrosContr());
  const corpo = document.getElementById('corpoContr');
  estadoVazio('contrVazio', CONTRATOS.length, lista.length, 'Nenhum lançamento. Importe a planilha ou clique em "+ Lançamento".', () => document.getElementById('btnLimparContr').click());
  // Paginação: renderiza só a fatia da página atual (leve mesmo com centenas de lançamentos)
  const totalFiltrado = lista.length;
  const porPag = (porPaginaContr === 'all') ? (totalFiltrado || 1) : porPaginaContr;
  const totalPaginas = Math.max(1, Math.ceil(totalFiltrado / porPag));
  totalPaginasContr = totalPaginas;
  if (paginaContr > totalPaginas) paginaContr = totalPaginas;
  if (paginaContr < 1) paginaContr = 1;
  const ini = (porPaginaContr === 'all') ? 0 : (paginaContr - 1) * porPag;
  const pag = (porPaginaContr === 'all') ? lista : lista.slice(ini, ini + porPag);
  corpo.innerHTML = pag.map(c => {
    const gc = [c.grupo, c.cota].filter(Boolean).join(' / ');
    return `<tr data-id="${esc(c.id)}"${SELECAO_CONTR.has(c.id) ? ' class="sel-on"' : ''}>
      <td class="acoes">
        <button class="edit edit-contr" data-id="${esc(c.id)}" title="Editar" aria-label="Editar">${ICONE_LAPIS}</button>
        <button class="del del-contr" data-id="${esc(c.id)}" title="Excluir" aria-label="Excluir">${ICONE_LIXEIRA}</button>
      </td>
      <td>${esc(c.banco) || '—'}${c.naJustica ? ' <span class="just-badge" title="Em disputa na justiça">justiça</span>' : ''}</td>
      <td>${esc(c.produto) || '—'}</td>
      <td>${c.empresa ? `<span class="emp-badge">${esc(c.empresa)}</span>` : '—'}</td>
      <td class="contr-descricao cel-trunc" title="${esc(c.material)}">${esc(descricaoContr(c)) || '—'}</td>
      <td>${esc(gc) || '—'}</td>
      <td>${esc(c.parcela) || '—'}</td>
      <td>${(f => (f === '' || f === undefined || f === null) ? '—' : esc(f))(faltamDaParcela(c))}</td>
      <td>${c.valorParcela !== '' && Number(c.valorParcela) ? fmtMoneyDec(c.valorParcela) : '—'}</td>
      <td>${c.saldoQuitacao !== '' && Number(c.saldoQuitacao) ? fmtMoneyDec(c.saldoQuitacao) : '—'}</td>
      <td>${esc(fmtData(c.vencimento)) || '—'}</td>
      <td>${c.valorPago !== '' && Number(c.valorPago) ? fmtMoneyDec(c.valorPago) : '—'}</td>
      <td>${statusPillContr(c)}</td>
    </tr>`;
  }).join('');
  rotularCelulasMobile('cabecalhoContr', 'corpoContr'); // celular: tabela vira cartões
  const devedor = lista.reduce((s, c) => s + saldoDevedorContr(c), 0);
  const pago = lista.reduce((s, c) => s + (Number(c.valorPago) || 0), 0);
  const ate = (porPaginaContr === 'all') ? totalFiltrado : Math.min(ini + porPag, totalFiltrado);
  const de = totalFiltrado === 0 ? 0 : ini + 1;
  document.getElementById('resumoContr').innerHTML = `Exibindo <b>${de}–${ate}</b> de <b>${totalFiltrado}</b> filtrados (${CONTRATOS.length} no total) &nbsp;•&nbsp; Saldo devedor (filtro): <b>${fmtMoneyDec(devedor)}</b> &nbsp;•&nbsp; Pago: <b>${fmtMoneyDec(pago)}</b>`;
  renderCardsContr();
  renderPaginacaoContr(totalFiltrado, totalPaginas);
  // Os cliques (editar/excluir/status/seleção) são tratados por DELEGAÇÃO única em #corpoContr,
  // definida uma só vez — o render fica leve mesmo com muitas linhas.
  SEL_TODOS_CONTR.sincronizar(lista); // alimenta o cache de chaves com a lista filtrada recém-calculada
  atualizarBarraSelecaoContr();
}
function renderPaginacaoContr(total, totalPaginas) {
  const selV = (document.getElementById('contrPorPagina') || {}).value || '50';
  const porPag = selV === 'all' ? Math.max(total, 1) : Number(selV);
  const ini = (paginaContr - 1) * porPag;
  renderNavPaginacao('contr', { de: total ? ini + 1 : 0, ate: Math.min(ini + porPag, total), total, totalPaginas, pagina: paginaContr });
}
// Soma genérica usada pelos cards/painel de contratos (cada item é uma parcela).
const somaContr = (arr, f) => arr.reduce((s, c) => s + f(c), 0);
// Resumo financeiro dos contratos (usado pelos cards e pelo painel — evita recálculo duplicado).
function resumoContr() {
  return {
    devedor: somaContr(CONTRATOS, saldoDevedorContr),
    pago: somaContr(CONTRATOS, c => Number(c.valorPago) || 0),
    naJustica: somaContr(CONTRATOS.filter(c => c.naJustica), saldoDevedorContr),
    pendentes: CONTRATOS.filter(c => !contrPago(c)).length,
  };
}
function renderCardsContr() {
  const { devedor, pago, naJustica, pendentes } = resumoContr();
  document.getElementById('cardsContratos').innerHTML = `
    ${cardV2('Lançamentos', CONTRATOS.length, '')}
    ${cardV2('Saldo devedor (total)', fmtMoneyDec(devedor), 'red', true, 'title="Soma do valor de todas as parcelas ainda não pagas (inclusive as na justiça), sem considerar os filtros da tabela abaixo."')}
    ${cardV2('Total pago', fmtMoneyDec(pago), 'green', true)}
    ${cardV2('Pendentes', pendentes, 'amber')}
    ${cardV2('Na justiça (saldo)', fmtMoneyDec(naJustica), '', true)}
  `;
}
// Aplica Pago/Pendente a um lançamento (objeto in-memory) via PUT. Devolve true se gravou.
async function setStatusContr(c, querPago) {
  if (querPago === contrPago(c)) return false;
  const at = Object.assign({}, c);
  if (querPago) { at.dataPagamento = at.dataPagamento || hojeBR(); if (!Number(at.valorPago)) at.valorPago = at.valorParcela || 0; }
  else { at.dataPagamento = ''; at.valorPago = 0; }
  const r = await fetch('/api/contratos/' + encodeURIComponent(c.id), { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(at) });
  if (!r.ok) return false;
  Object.assign(c, at);
  return true;
}
async function aplicarStatusLoteContr(ids, querPago) {
  if (!ids.length) return;
  // 1 requisição só (o servidor altera todos e grava uma vez) — antes era 1 por lançamento (lento).
  const r = await fetch('/api/contratos/lote-status', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ids, pago: querPago }) });
  if (!r.ok) { toast(`Erro ao marcar ${ids.length} lançamento(s) como ${querPago ? 'Pago' : 'Pendente'}. Tente novamente.`, 'erro'); return; }
  const j = await r.json().catch(() => ({}));
  // espelha as mudanças localmente (resposta instantânea, sem recarregar tudo)
  const alvo = new Set(ids);
  for (const c of CONTRATOS) {
    if (!alvo.has(c.id) || querPago === contrPago(c)) continue;
    if (querPago) { c.dataPagamento = c.dataPagamento || hojeBR(); if (!Number(c.valorPago)) c.valorPago = Number(c.valorParcela) || 0; }
    else { c.dataPagamento = ''; c.valorPago = 0; }
  }
  renderContratos(); renderPainelContr();
  const n = j.alterados || 0;
  toast(n ? `${n} lançamento(s) marcado(s) como ${querPago ? 'Pago' : 'Pendente'}.` : 'Nada a alterar (já estavam nesse status).', n ? 'ok' : '');
}
async function darBaixaContr(id, valor) {
  if (!valor) return; // sem data-valor (HTML malformado) → não grava "undefined"
  const c = CONTRATOS.find(x => x.id === id); if (!c) return;
  const querPago = valor === 'Pago';
  // Se a linha clicada faz parte de uma seleção de 2+ → aplica a todas as selecionadas.
  if (SELECAO_CONTR.size >= 2 && SELECAO_CONTR.has(id)) { await aplicarStatusLoteContr([...SELECAO_CONTR], querPago); return; }
  if (querPago === contrPago(c)) return;
  const antesPag = c.dataPagamento, antesVal = c.valorPago;
  if (!(await setStatusContr(c, querPago))) { toast('Erro ao alterar.', 'erro'); return; }
  renderContratos(); renderPainelContr();
  toast(querPago ? 'Parcela marcada como paga.' : 'Parcela voltou a pendente.', 'ok', { texto: 'Desfazer', fn: async () => {
    const atual = CONTRATOS.find(x => x.id === id) || c;
    const rev = Object.assign({}, atual, { dataPagamento: antesPag, valorPago: antesVal });
    const rr = await fetch('/api/contratos/' + encodeURIComponent(id), { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(rev) });
    if (rr.ok) { Object.assign(atual, rev); renderContratos(); renderPainelContr(); }
  } });
}
async function excluirContratosLote(ids) {
  if (!ids.length) return;
  if (!(await confirmar(`Excluir ${ids.length} lançamento(s) selecionado(s)? Esta ação não pode ser desfeita.`, { perigo: true, okTexto: 'Excluir' }))) return;
  // 1 requisição só (o servidor exclui todos e grava uma vez).
  const r = await fetch('/api/contratos/lote-excluir', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ids }) });
  if (!r.ok) { toast('Erro ao excluir.', 'erro'); return; }
  const j = await r.json().catch(() => ({}));
  ids.forEach(id => SELECAO_CONTR.delete(id));
  await carregarContratos();
  toast(`${j.excluidos || 0} lançamento(s) excluído(s).`, 'ok');
}

const formContrato = document.getElementById('formContrato');
let _focoAntesContrato = null; // elemento focado antes de abrir o modal de contrato (restaurado ao fechar)
const CAMPOS_FORM_CONTR = ['banco', 'produto', 'empresa', 'material', 'grupo', 'cota', 'parcela', 'valorParcela', 'saldoQuitacao', 'descontoQuitacaoRS', 'descontoQuitacao', 'dataEmissao', 'carencia', 'inicioParcelas', 'vencimento', 'dataPagamento', 'valorPago', 'conta', 'localCarro', 'escritorio'];
function abrirContratoModal(id) {
  const c = id ? CONTRATOS.find(x => x.id === id) : null;
  if (id && !c) { toast('Lançamento não encontrado. A lista foi atualizada.', 'erro'); carregarContratos(); return; }
  editandoContratoId = id || null;
  formContrato.reset();
  document.getElementById('contratoTitulo').textContent = id ? 'Editar lançamento' : 'Novo lançamento';
  if (c) {
    for (const campo of CAMPOS_FORM_CONTR) if (formContrato.elements[campo]) formContrato.elements[campo].value = c[campo] ?? '';
    if (formContrato.elements['naJustica']) formContrato.elements['naJustica'].checked = !!c.naJustica;
  }
  // (datalists do formulário já são populados por popularFiltrosContr() no render da aba)
  // Completar série cria somente as parcelas ausentes, inclusive anteriores à atual.
  const _btnSerie = document.getElementById('gerarSerieContr');
  if (_btnSerie) {
    _btnSerie.textContent = id ? 'Completar série' : 'Gerar série completa';
    _btnSerie.title = 'Cria as parcelas que faltam de 1 até o total, sem duplicar as já cadastradas.';
  }
  const modalEl = document.getElementById('contratoModal');
  modalEl.hidden = false;
  _focoAntesContrato = document.activeElement;
  requestAnimationFrame(() => focarPrimeiroCampo(modalEl));
}
function fecharContratoModal() {
  document.getElementById('contratoModal').hidden = true;
  if (_focoAntesContrato && document.body.contains(_focoAntesContrato)) _focoAntesContrato.focus();
  _focoAntesContrato = null;
}
document.getElementById('btnAddContr').onclick = () => abrirContratoModal(null);
document.getElementById('fecharContrato').onclick = fecharContratoModal;
document.getElementById('cancelarContrato').onclick = fecharContratoModal;
fecharAoClicarNoFundo('contratoModal', fecharContratoModal);

document.getElementById('btnCompletarSeriesContr').onclick = async () => {
  if (!CONTRATOS.some(c => /(\d+)\s*\/\s*(\d+)/.test(String(c.parcela || '')))) {
    return toast('Nenhuma série de parcelas foi encontrada.', '');
  }
  if (!(await confirmar('Completar todas as séries de todos os contratos? Só serão CRIADAS as parcelas que faltam e a numeração será padronizada (ex.: 09/20). Nenhum lançamento existente é excluído ou alterado: parcelas sobrepostas (mesmo vencimento e valor) e datas contraditórias apenas entram no aviso do resultado.', { okTexto: 'Completar todas' }))) return;
  const btn = document.getElementById('btnCompletarSeriesContr');
  const rotulo = btn.textContent;
  btn.disabled = true;
  btn.textContent = 'Completando…';
  let seriesOcultas = []; // avisadas DEPOIS do finally, com o botão já liberado
  let resumoFinal = null; // [texto, tipo] do toast — sai depois do aviso, senão some embaixo dele
  try {
    const r = await fetch('/api/contratos/completar-series', { method: 'POST' });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) return toast(j.erro || 'Erro ao completar as séries.', 'erro');
    // Sincroniza a tela ANTES de anunciar o resultado (o botão segue travado até aqui): com
    // CONTRATOS recarregado, o Exportar — que monta {ids} de aplicarFiltrosContr() — já
    // enxerga as parcelas recém-criadas sem F5. Filtros, busca, ordenação e sub-aba não são
    // tocados: renderContratos relê o estado atual deles a cada render.
    const atualizou = await carregarContratos();
    if (!atualizou) {
      return toast('As séries foram completadas no servidor, mas não foi possível atualizar a tela. Atualize a página (F5) para ver as parcelas.', 'erro');
    }
    // A operação não exclui mais nada (sobreposta virou relatório), mas a seleção continua
    // sendo saneada: um id pode ter sumido por outra aba/aparelho. As parcelas novas NÃO
    // entram sozinhas na seleção.
    if (SELECAO_CONTR.size) {
      const vivos = new Set(CONTRATOS.map(c => c.id));
      for (const id of [...SELECAO_CONTR]) if (!vivos.has(id)) SELECAO_CONTR.delete(id);
      atualizarBarraSelecaoContr();
    }
    const criadas = Number(j.criadas) || 0;
    const padronizadas = Number(j.padronizadas) || 0;
    const sobrepostas = Number(j.sobrepostas) || 0;
    const ignoradas = Number(j.ignoradas) || 0;
    const avisos = Array.isArray(j.avisos) ? j.avisos : [];
    seriesOcultas = seriesComOcultasContr();
    if (!criadas && !padronizadas && !sobrepostas && !ignoradas && !avisos.length) {
      resumoFinal = ['Todas as séries já estavam completas, padronizadas e sem parcelas sobrepostas.', ''];
    } else {
      const resumo = [
        criadas && `${criadas} parcela(s) criada(s) em ${Number(j.series) || 0} série(s)`,
        padronizadas && `${padronizadas} numeração(ões) padronizada(s)`,
        sobrepostas && `${sobrepostas} sobreposição(ões) de vencimento e valor para conferir (nenhuma foi excluída)`,
        avisos.length && `${avisos.length} aviso(s) de data para conferir (Vencimento × "Início das parcelas", ou série com cadência irregular)`,
        ignoradas && `${ignoradas} série(s) precisam de revisão por terem a mesma parcela em vencimentos diferentes`,
      ].filter(Boolean).join(' · ');
      resumoFinal = [`${resumo}.`, (ignoradas || sobrepostas || avisos.length) ? 'erro' : 'ok'];
    }
  } catch (e) {
    toast('Erro ao completar as séries. Verifique a conexão e tente novamente.', 'erro');
  } finally {
    btn.disabled = false;
    btn.textContent = rotulo;
  }
  // "Todas completas" com parte de uma série fora da lista (cadastrada com outra descrição,
  // banco, grupo…) era exatamente o caso que parecia "faltou gerar": explica e oferece mostrar.
  if (seriesOcultas.length) {
    const [pri] = seriesOcultas;
    const nome = [pri.ref.banco, [pri.ref.grupo, pri.ref.cota].filter(Boolean).join('/') || pri.ref.material].filter(Boolean).join(' ');
    const mais = seriesOcultas.length > 1 ? ` Há mais ${seriesOcultas.length - 1} série(s) na mesma situação.` : '';
    const okTexto = pri.revelavel ? 'Mostrar a série' : 'Limpar filtros';
    if (await confirmar(`Parte de uma série que está na lista não aparece com a busca ou os filtros atuais. ${nome}: ${fraseOcultasContr(pri)}${mais}`, { okTexto })) {
      mostrarSerieContr(pri.ref, pri.revelavel, pri.ocultas.map(c => c.id));
    }
  }
  if (resumoFinal) toast(...resumoFinal);
};
// Séries que aparecem na lista mas têm parcelas FORA dela por estarem cadastradas com descrição,
// banco, produto, empresa, grupo ou cota diferentes das linhas visíveis da mesma série. Escondidas
// pelo filtro de Status/Justiça ou por busca de número NÃO entram (ver parcelasOcultasContr).
// Ex.: busca "Nome novo" com a 53/54 e a 54/54 gravadas com o nome antigo
//      → [{ ref: <uma linha visível da série>, ocultas: [53/54, 54/54], campos: ['descrição'], rotulo, revelavel }]
//      filtro Status = Pendente, sem busca → [] (recorte intencional)
function seriesComOcultasContr() {
  const f = estadoFiltrosContr();
  const visiveis = CONTRATOS.filter(c => passaFiltrosContr(c, f));
  const refPorSerie = new Map();
  for (const c of visiveis) { const k = chaveSerieContrato(c); if (!refPorSerie.has(k)) refPorSerie.set(k, c); }
  const linhasPorSerie = new Map();
  for (const c of CONTRATOS) {
    if (!/(\d+)\s*\/\s*(\d+)/.test(String(c.parcela || ''))) continue;
    const k = chaveSerieContrato(c);
    if (!refPorSerie.has(k)) continue;
    if (!linhasPorSerie.has(k)) linhasPorSerie.set(k, []);
    linhasPorSerie.get(k).push(c);
  }
  const res = [];
  for (const [k, ref] of refPorSerie) {
    const oc = parcelasOcultasContr(linhasPorSerie.get(k) || [], ref, f);
    if (oc.ocultas.length) res.push({ ref, ...oc });
  }
  return res;
}

// Atalho contextual no padrão do Conta Azul: Alt + D abre o cadastro da área atual.
// Cada tela reaproveita seu botão/função original, preservando validações e permissões.
const ATALHO_CADASTRO_BOTOES = [
  '#btnAdicionar', '#btnAddVist', '#btnAddMulta', '#btnAddRast', '#btnAddInst', '#btnAddEnvio',
  '#btnAddMnt', '#btnAddOfic', '#btnAddAbt', '#btnAddContr', '#btnAddApt', '#btnAddEmp',
  '#btnAddPct', '#btnAddRet', '#btnAddFeedback', '#btnAddSenha', '#btnAddDocumento', '#btnAddForn',
  '#btnAddFunc', '#btnNovoConvite', '#btnAddProg', '#btnNovoTreino', '#btnContabAddEmpresa',
  '#btnAddAlmox', '#btnAddEpi', '#btnAddEpiFicha', '#btnAddMovEpi', '#btnAddEpiNf', '#btnAddLoc',
];
function configurarIndicadoresAtalhoCadastro() {
  document.querySelectorAll(ATALHO_CADASTRO_BOTOES.join(',')).forEach((btn) => {
    btn.classList.add('btn-com-atalho');
    btn.setAttribute('aria-keyshortcuts', 'Alt+D');
    if (!btn.title.includes('Alt + D')) btn.title = `${btn.title ? btn.title + ' · ' : ''}Atalho: Alt + D`;
    if (!btn.querySelector('.atalho-tecla')) {
      const tecla = document.createElement('kbd');
      tecla.className = 'atalho-tecla';
      tecla.setAttribute('aria-hidden', 'true');
      tecla.textContent = 'Alt + D';
      btn.appendChild(tecla);
    }
  });
}
function contextoCadastroAtivo() {
  const view = document.querySelector('.view.active');
  const area = view?.id || '';
  const sub = view?.querySelector('.subview.active')?.id || '';
  const porArea = {
    frota: sub === 'frota-comprados' ? { foco: '#compraBuscaVeiculo' }
      : { botao: sub === 'frota-vistorias' ? '#btnAddVist' : '#btnAdicionar' },
    multas: { botao: '#btnAddMulta' },
    rastreadores: { botao: '#btnAddRast' },
    instalacoes: { botao: sub === 'inst-envios' ? '#btnAddEnvio' : '#btnAddInst' },
    manutencao: { botao: sub === 'mnt-notas' ? '#btnAddOfic' : '#btnAddMnt' },
    abastecimento: { botao: '#btnAddAbt' },
    contratos: { botao: '#btnAddContr' },
    controles: { botao: ({
      'ctrl-emprestimos': '#btnAddEmp', 'ctrl-percentuais': '#btnAddPct', 'ctrl-retiradas': '#btnAddRet',
    })[sub] || '#btnAddApt' },
    contabilidade: { botao: '#btnContabAddEmpresa' },
    feedback: { botao: '#btnAddFeedback' },
    senhas: { botao: '#btnAddSenha' },
    documentos: { botao: '#btnAddDocumento' },
    fornecedores: { botao: '#btnAddForn' },
    funcionarios: { botao: '#btnAddFunc' },
    admissao: { botao: '#btnNovoConvite' },
    programas: { botao: '#btnAddProg' },
    acoesSst: { botao: '#btnAddAcao' },
    integracao: { botao: '#btnNovoTreino' },
    simulador: { foco: '#simulador .subview.active .sim-form input:not([disabled])' },
    cadastros: { foco: '#cadastros .cad-add input:not([disabled])' },
    // Áreas por sub-aba: no celular o "+" da barra é o único caminho de cadastro (o botão
    // da toolbar fica fora da dobra), então a ausência delas aqui virava "não tem cadastro".
    almoxarifado: { botao: '#btnAddAlmox' },
    epi: { botao: ({
      'epi-catalogo': '#btnAddEpi', 'epi-fichas': '#btnAddEpiFicha',
      'epi-movimentacoes': '#btnAddMovEpi', 'epi-notas-fiscais': '#btnAddEpiNf',
    })[sub] || '#btnAddEpi' },
    locacoes: { botao: '#btnAddLoc' },
  };
  return { area, ...(porArea[area] || {}) };
}
function focarPrimeiroCampo(container) {
  const campo = container?.querySelector('input:not([type="hidden"]):not([type="file"]):not([disabled]):not([readonly]), textarea:not([disabled]):not([readonly]), select:not([disabled])');
  campo?.focus();
}
function abrirCadastroDaAbaPorAtalho() {
  const modalAberto = document.querySelector('.modal-overlay:not([hidden])');
  if (modalAberto) { focarPrimeiroCampo(modalAberto); return; }

  const contexto = contextoCadastroAtivo();
  if (!contexto.botao && !contexto.foco) {
    const nome = document.getElementById('pageTitle')?.textContent?.trim() || 'Esta aba';
    toast(`${nome} não possui um novo cadastro manual.`, 'erro');
    return;
  }
  if (permissaoAtual(contexto.area) !== 'editar') {
    toast('Você não tem permissão para cadastrar nesta aba.', 'erro');
    return;
  }
  if (contexto.foco) {
    const campo = document.querySelector(contexto.foco);
    if (campo) campo.focus();
    else toast('Esta tela não possui um campo de novo cadastro.', 'erro');
    return;
  }
  const botao = document.querySelector(contexto.botao);
  if (!botao || botao.disabled || botao.hidden) {
    toast('O novo cadastro não está disponível nesta tela.', 'erro');
    return;
  }
  botao.click();
  requestAnimationFrame(() => focarPrimeiroCampo(document.querySelector('.modal-overlay:not([hidden])')));
}
configurarIndicadoresAtalhoCadastro();
document.addEventListener('keydown', (e) => {
  if (e.defaultPrevented || e.repeat || !e.altKey || e.ctrlKey || e.metaKey || e.shiftKey || e.code !== 'KeyD') return;
  const alvo = e.target;
  if (alvo && (alvo.matches?.('input, textarea, select') || alvo.isContentEditable)) return;
  e.preventDefault();
  abrirCadastroDaAbaPorAtalho();
});
formContrato.addEventListener('submit', async (e) => {
  e.preventDefault();
  const dados = {};
  for (const el of formContrato.elements) if (el.name) dados[el.name] = (el.type === 'checkbox') ? el.checked : el.value;
  // Grupo e Cota andam em par: ou os dois preenchidos, ou os dois em branco.
  const _g = (dados.grupo || '').trim(), _c = (dados.cota || '').trim();
  if ((_g && !_c) || (!_g && _c)) {
    const alvo = formContrato.elements[_g ? 'cota' : 'grupo'];
    if (alvo) alvo.focus();
    return toast(`Preencha também ${_g ? 'a Cota' : 'o Grupo'}: Grupo e Cota precisam vir juntos (ou deixe os dois em branco).`, 'erro');
  }
  if (editandoContratoId) dados.id = editandoContratoId;
  const metodo = editandoContratoId ? 'PUT' : 'POST';
  const url = editandoContratoId ? '/api/contratos/' + encodeURIComponent(editandoContratoId) : '/api/contratos';
  // Trava o botão de salvar durante o fetch — evita clique duplo criando lançamento repetido.
  const btnSalvar = formContrato.querySelector('button[type="submit"]');
  const rotuloSalvar = btnSalvar ? btnSalvar.textContent : '';
  if (btnSalvar) { btnSalvar.disabled = true; btnSalvar.textContent = 'Salvando…'; }
  try {
    const r = await fetch(url, { method: metodo, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(dados) });
    if (!r.ok) { const j = await r.json().catch(() => ({})); return toast(j.erro || 'Erro ao salvar.', 'erro'); }
    fecharContratoModal();
    await carregarContratos();
    toast(editandoContratoId ? 'Lançamento atualizado!' : 'Lançamento adicionado!', 'ok');
  } finally {
    if (btnSalvar) { btnSalvar.disabled = false; btnSalvar.textContent = rotuloSalvar; }
  }
});
// Soma `n` meses a uma data "dd/mm/aaaa" preservando o dia (ajusta p/ fim do mês quando estoura: 31/01 +1 → 28/02).
function addMesesBR(dataBR, n) {
  const m = String(dataBR || '').match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/);
  if (!m) return dataBR || ''; // formato inesperado: devolve como veio
  let dia = +m[1], mes = +m[2] - 1, ano = +m[3]; if (ano < 100) ano += 2000;
  const d = new Date(ano, mes + n, 1);
  const ultimoDia = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
  d.setDate(Math.min(dia, ultimoDia));
  return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear();
}
// "a", "a e b", "a, b e c" — para montar frases de aviso em português.
// Ex.: juntarEContr(['53/54', '54/54']) === '53/54 e 54/54'
const juntarEContr = (itens) => (itens.length <= 1 ? (itens[0] || '') : `${itens.slice(0, -1).join(', ')} e ${itens[itens.length - 1]}`);
// Campos de DADO que tiram uma parcela da lista mesmo ela sendo da série: a série é identificada
// pelo grupo/cota (ou pela descrição, quando não há grupo/cota), mas a busca olha o TEXTO.
// [campo do lançamento, rótulo usado na frase do aviso]
const CAMPOS_DADO_SERIE_CONTR = [['material', 'descrição'], ['banco', 'banco'], ['produto', 'produto'], ['empresa', 'empresa'], ['grupo', 'grupo'], ['cota', 'cota']];
// Parcelas de uma série que EXISTEM mas ficam fora da lista por causa de um DADO diferente.
// O "Completar série" agrupa pelo ID da série e a busca filtra pelo texto: uma parcela cadastrada
// com outra descrição some da lista, e o botão, com razão, não a cria de novo — sem este aviso
// parecia que "faltou gerar" (caso real: 53/54 e 54/54 do Banco Exemplo 20416/315, cadastradas meses
// antes com o nome antigo, e a busca pelo nome novo).
// Só conta a parcela que VOLTARIA para a lista se tivesse os dados da referência. A escondida
// pelo filtro de Status/Justiça ou por uma busca pelo número ("54/54") é recorte do próprio
// usuário: não gera aviso, e o motivo nunca é atribuído a um campo que não é a causa.
// `linhasSerie` = linhas de CONTRATOS da série; `referencia` = a linha de comparação (o form ou uma
// linha visível); `filtros` = estadoFiltrosContr() (passado por quem já leu, para não reler).
// Devolve { ocultas, campos, rotulo, revelavel }:
//   ocultas   → linhas escondidas por dado, em ordem de número
//   campos    → rótulos dos campos cuja diferença as esconde (ex.: ['descrição'])
//   rotulo    → as parcelas por extenso ("53/54 e 54/54"; mais de 6 → "01/54, …, 05/54 e mais 3")
//   revelavel → true quando buscar "grupo / cota" traz de volta todas as escondidas
// Ex.: com a busca "Nome novo": parcelasOcultasContr(serie, { grupo: '20416', cota: '315', material: 'Nome novo', ... })
//      → { ocultas: [53/54, 54/54], campos: ['descrição'], rotulo: '53/54 e 54/54', revelavel: true }
//      com o filtro Status = Pendente e as pagas de nome antigo → { ocultas: [], campos: [], ... }
function parcelasOcultasContr(linhasSerie, referencia, filtros = estadoFiltrosContr()) {
  const norm = (x) => String(x ?? '').trim().replace(/\s+/g, ' ').toUpperCase();
  const num = (c) => { const m = String(c.parcela || '').match(/(\d+)\s*\/\s*(\d+)/); return m ? +m[1] : Infinity; };
  const ocultas = [], causas = new Set();
  for (const c of linhasSerie) {
    if (passaFiltrosContr(c, filtros)) continue; // aparece na lista
    const difs = CAMPOS_DADO_SERIE_CONTR.filter(([k]) => norm(c[k]) !== norm(referencia[k]));
    if (!difs.length) continue; // mesmos dados da referência: quem a tirou foi o filtro
    const comRef = (ks) => ({ ...c, ...Object.fromEntries(ks.map(([k]) => [k, referencia[k]])) });
    if (!passaFiltrosContr(comRef(difs), filtros)) continue; // nem com os dados da referência voltaria
    ocultas.push(c);
    // Causa = o campo cuja troca SOZINHA já a traz de volta; se nenhum basta sozinho, todos juntos.
    const sozinhos = difs.filter(d => passaFiltrosContr(comRef([d]), filtros));
    (sozinhos.length ? sozinhos : difs).forEach(([, rotulo]) => causas.add(rotulo));
  }
  ocultas.sort((a, b) => num(a) - num(b));
  const campos = CAMPOS_DADO_SERIE_CONTR.map(([, r]) => r).filter(r => causas.has(r));
  const nomes = ocultas.map(c => String(c.parcela || '').trim());
  const rotulo = nomes.length <= 6 ? juntarEContr(nomes) : `${nomes.slice(0, 5).join(', ')} e mais ${nomes.length - 5}`;
  const g = norm(referencia.grupo), ct = norm(referencia.cota);
  const revelavel = !!(g && ct) && ocultas.every(c => norm(c.grupo) === g && norm(c.cota) === ct);
  return { ocultas, campos, rotulo, revelavel };
}
// Frase do aviso a partir do resultado de parcelasOcultasContr ('' quando não há ocultas).
// Ex.: fraseOcultasContr({ ocultas: [a, b], campos: ['descrição'], rotulo: '53/54 e 54/54' })
//      → '53/54 e 54/54 já existem nesta série, mas não aparecem na lista porque estão cadastradas com descrição diferente.'
function fraseOcultasContr(oc) {
  const n = oc.ocultas.length;
  if (!n || !oc.campos.length) return '';
  const plural = n > 1;
  return `${oc.rotulo} já ${plural ? 'existem' : 'existe'} nesta série, mas não ${plural ? 'aparecem' : 'aparece'} na lista `
    + `porque ${plural ? 'estão cadastradas' : 'está cadastrada'} com ${juntarEContr(oc.campos)} ${oc.campos.length > 1 ? 'diferentes' : 'diferente'}.`;
}
// Mostra a série na aba Parcelas: limpa busca e filtros (pelo próprio botão "Limpar filtros") e
// busca por "grupo / cota", que casa TODAS as linhas da série, inclusive as de descrição
// diferente. Abre direto na página da 1ª parcela de `idsAlvo` — numa série de 54, a 53/54 e a
// 54/54 caem na página 2 da ordem por vencimento, e abrir na 1 escondia justamente as citadas.
// Com `porGrupoCota` falso (as escondidas têm outro grupo/cota) só limpa busca e filtros.
// Ex.: mostrarSerieContr({ grupo: '20416', cota: '315' }, true, [id53, id54]) → busca "20416 / 315", página 2
//      mostrarSerieContr(ref, false, [id])                                  → lista inteira, na página de `id`
function mostrarSerieContr(ref, porGrupoCota = true, idsAlvo = []) {
  document.querySelector('#contratosSubtabs .subtab[data-sub="contr-parcelas"]')?.click();
  document.getElementById('btnLimparContr').click();
  if (porGrupoCota) document.getElementById('buscaContr').value = `${String(ref.grupo).trim()} / ${String(ref.cota).trim()}`;
  paginaContr = 1;
  if (porPaginaContr !== 'all' && idsAlvo.length) {
    const alvo = new Set(idsAlvo);
    const i = ordenarListaContr(aplicarFiltrosContr()).findIndex(c => alvo.has(c.id));
    if (i >= 0) paginaContr = Math.floor(i / porPaginaContr) + 1;
  }
  renderContratos();
}
// O form de lançamento tem mudança não salva? Lançamento novo conta como alterado (nada foi salvo).
// Ex.: formContrAlterado(CONTRATOS.find(c => c.id === editandoContratoId)) → false logo depois de abrir
function formContrAlterado(ref) {
  if (!ref) return true;
  for (const campo of CAMPOS_FORM_CONTR) {
    const el = formContrato.elements[campo];
    if (el && String(el.value ?? '') !== String(ref[campo] ?? '')) return true;
  }
  const j = formContrato.elements['naJustica'];
  return !!(j && j.checked !== !!ref.naJustica);
}
// Gera as parcelas ausentes de 1..M. A parcela digitada é a referência para calcular
// vencimentos anteriores e seguintes; lançamentos já cadastrados não são duplicados.
document.getElementById('gerarSerieContr').onclick = async () => {
  const dados = {};
  for (const el of formContrato.elements) if (el.name) dados[el.name] = (el.type === 'checkbox') ? el.checked : el.value;
  // Grupo e Cota andam em par (mesma regra do salvar)
  const _g = (dados.grupo || '').trim(), _c = (dados.cota || '').trim();
  if ((_g && !_c) || (!_g && _c)) {
    const alvo = formContrato.elements[_g ? 'cota' : 'grupo']; if (alvo) alvo.focus();
    return toast(`Preencha também ${_g ? 'a Cota' : 'o Grupo'}: Grupo e Cota precisam vir juntos (ou deixe os dois em branco).`, 'erro');
  }
  const m = String(dados.parcela || '').match(/(\d+)\s*\/\s*(\d+)/);
  const inicio = m ? +m[1] : 1;
  const total = m ? +m[2] : (parseInt(dados.totalParcelas, 10) || 0);
  if (!total || total < 1) return toast('Informe a parcela como N/M (ex.: 2/24).', 'erro');
  if (inicio < 1 || inicio > total) return toast('A parcela atual deve ficar entre 1 e o total.', 'erro');

  const referencia = editandoContratoId ? CONTRATOS.find(c => c.id === editandoContratoId) : null;
  // ID da série que a TELA usa para achar as parcelas já cadastradas. Só o da própria linha vai
  // para o servidor; o herdado abaixo serve apenas às contas da tela — quem decide a série de um
  // lançamento novo continua sendo o servidor (resolverSerieIdContrato), com a lista atualizada.
  let serieIdTela = '';
  if (referencia?.serieId) { dados.serieId = referencia.serieId; serieIdTela = referencia.serieId; }
  else {
    // Lançamento NOVO (ainda não salvo) ou linha antiga sem ID de série: o servidor vai encaixá-lo
    // na série que já existe com o mesmo banco/produto/empresa + grupo/cota (backend/server.js).
    // Sem este espelho a tela não enxergava as parcelas já cadastradas: pedia para "gerar 54"
    // quando faltavam 3 e não conseguia avisar das que a busca esconde.
    const legado = chaveSerieContrato({ ...(referencia || dados), serieId: '' });
    const irma = CONTRATOS.find(c => c.serieId && c.id !== editandoContratoId && chaveSerieContrato({ ...c, serieId: '' }) === legado);
    if (irma) serieIdTela = irma.serieId;
  }
  const chave = serieIdTela ? chaveSerieContrato({ serieId: serieIdTela }) : chaveSerieContrato(referencia || dados);
  const daSerie = CONTRATOS
    .map(c => ({ c, m: String(c.parcela || '').match(/(\d+)\s*\/\s*(\d+)/) }))
    .filter(x => x.m && +x.m[2] === total && chaveSerieContrato(x.c) === chave);
  // Watermark coerente (regra única — pagasAteCoerente, espelho do server): a parcela digitada
  // entra como "parcela atual" (aberta ⇒ declara inicio−1 pagas, a MESMA heurística que o
  // normalizador aplicará ao salvar), e qualquer parcela aberta já existente na série limita a
  // declaração — antes, editar a 04 aberta gerava o resto da série com pagas=3 mesmo com a 03 aberta.
  const pagoAtual = contrPago(referencia || dados);
  const pagasAte = pagasAteCoerente(daSerie
    .filter(x => x.c.id !== editandoContratoId) // a versão digitada substitui a gravada
    .map(x => ({ numero: +x.m[1], pago: contrPago(x.c), parcelasPagas: x.c.parcelasPagas }))
    .concat([{ numero: inicio, pago: pagoAtual, parcelasPagas: referencia ? referencia.parcelasPagas : '' }]), total); // sem declaração explícita, a inferência (nº−1) é interna à função
  const existentes = new Set(daSerie.map(x => +x.m[1]));
  const numeros = Array.from({ length: total }, (_, i) => i + 1).filter(i => !existentes.has(i));
  // Parcelas desta série que existem mas um DADO diferente tira da lista (ver parcelasOcultasContr).
  // A linha aberta no form fica de fora: ela é a referência. Só com a lista de Parcelas na tela —
  // aberto pelo Cronograma, a busca da aba Parcelas nem está visível e o aviso não faria sentido.
  const naLista = !!document.getElementById('contr-parcelas')?.classList.contains('active');
  const ocultas = naLista
    ? parcelasOcultasContr(daSerie.map(x => x.c).filter(c => c.id !== editandoContratoId), dados)
    : { ocultas: [], campos: [], rotulo: '', revelavel: false };
  const avisoOcultas = fraseOcultasContr(ocultas);
  const acaoOcultas = avisoOcultas
    ? { texto: ocultas.revelavel ? 'Mostrar a série' : 'Limpar filtros', fn: () => mostrarSerieContr(dados, ocultas.revelavel, ocultas.ocultas.map(c => c.id)) }
    : null;
  if (!numeros.length) {
    if (!avisoOcultas) return toast(`A série 1/${total} até ${total}/${total} já está completa.`, '');
    // Série completa, mas parte dela não aparece na lista: é o momento em que parece que "faltou
    // gerar". Explica e oferece mostrar a série — fechar o modal descarta o que não foi salvo, e
    // o aviso diz isso antes, em vez de perder a edição calado.
    const descarta = formContrAlterado(referencia) ? ' O que foi digitado neste lançamento e não foi salvo será descartado.' : '';
    if (await confirmar(`A série 1/${total} até ${total}/${total} já está completa, então nada foi criado. ${avisoOcultas}${descarta}`, { okTexto: acaoOcultas.texto })) {
      fecharContratoModal();
      acaoOcultas.fn();
    }
    return;
  }
  // ÂNCORA DA SÉRIE (regra ÚNICA — espelho do bloco de mesmo nome em backend/server.js):
  //     vencimento(k) = vencimentoAncora + (k − numeroAncora) meses
  // PRIMÁRIA: o Vencimento desta parcela (a que está no form) ⇒ numeroAncora = `inicio`.
  // FALLBACK: "Início das parcelas" é o vencimento DECLARADO da parcela 01 ⇒ numeroAncora = 1.
  // Cada parcela sai da âncora, não da anterior: o clamp de fim de mês (31/01 → 28/02 → 31/03)
  // não vira cascata. Antes, o fallback usava `inicio` como número da âncora e deslocava a
  // série inteira em (inicio−1) meses quando o Vencimento estava vazio.
  const vctoDigitado = (dados.vencimento || '').trim();
  const inicioDigitado = (dados.inicioParcelas || '').trim();
  const baseVcto = vctoDigitado || inicioDigitado;
  const numeroAncora = vctoDigitado ? inicio : 1;
  if (!baseVcto) { formContrato.elements.vencimento?.focus(); return toast('Informe o Vencimento (ou o Início das parcelas) desta parcela para calcular as datas da série.', 'erro'); }
  // Os dois campos preenchidos e discordando: AVISA e segue com o Vencimento (a primária).
  // Nunca corrige em silêncio — a diferença pode ser legítima (carência empurrando a 1ª parcela).
  if (vctoDigitado && inicioDigitado) {
    const esperado = addMesesBR(inicioDigitado, inicio - 1);
    if (esperado && esperado !== vctoDigitado) {
      toast(`Atenção: "Início das parcelas" ${inicioDigitado} + ${inicio - 1} mês(es) daria ${esperado}, mas o Vencimento é ${vctoDigitado}. A série vai seguir o Vencimento; confira os dois campos.`, 'erro');
    }
  }
  const qtd = numeros.length;
  if (!(await confirmar(`Gerar ${qtd} parcela(s) que faltam nesta série, sem duplicar as existentes?${avisoOcultas ? ` Atenção: ${avisoOcultas}` : ''}`, { okTexto: 'Gerar' }))) return;
  const itens = [];
  // Menor parcela que JÁ existe (contando a que está no form): abaixo dela é preenchimento
  // retroativo — o único caso em que a parcela nova pode nascer paga (CT-3). Para a frente,
  // nasce sempre em aberto, mesmo com "pagas" declarado alto.
  const menorExistente = Math.min(inicio, ...existentes);
  for (const i of numeros) {
    const it = Object.assign({}, dados);
    const parcelasPagas = Math.min(i, pagasAte);
    const pago = i < menorExistente && i <= pagasAte;
    it.parcela = `${i}/${total}`;
    it.totalParcelas = total;
    it.parcelasPagas = parcelasPagas;
    it.parcelasFaltantes = Math.max(0, total - parcelasPagas);
    it.vencimento = baseVcto ? addMesesBR(baseVcto, i - numeroAncora) : '';
    it.dataPagamento = pago ? it.vencimento : '';
    it.valorPago = pago ? it.valorParcela : '';
    delete it.id;
    itens.push(it);
  }
  // Trava o botão e mostra "Gerando…" enquanto grava (evita clicar 2x e duplicar; dá feedback se o servidor demorar)
  const btn = document.getElementById('gerarSerieContr');
  const rotulo = btn.textContent;
  btn.disabled = true; btn.textContent = `Gerando ${qtd}…`;
  try {
    const r = await fetch('/api/contratos/lote-criar', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ itens }) });
    if (!r.ok) { const j = await r.json().catch(() => ({})); return toast(j.erro || 'Erro ao gerar série.', 'erro'); }
    const j = await r.json().catch(() => ({}));
    fecharContratoModal();
    await carregarContratos();
    const criados = Number.isFinite(Number(j.criados)) ? Number(j.criados) : itens.length;
    const ignorados = Number(j.ignorados) || 0;
    const resumo = criados ? `${criados} parcela(s) gerada(s)${ignorados ? ` · ${ignorados} já existia(m)` : ''}.` : 'A série já estava completa; nenhuma parcela foi duplicada.';
    // Com parcelas escondidas pela busca, o aviso lembra quais são e oferece mostrar a série.
    toast(acaoOcultas ? `${resumo} ${ocultas.rotulo} já existia(m) fora da lista.` : resumo, criados ? 'ok' : '', acaoOcultas);
  } catch (e) {
    toast('Erro ao gerar série. Verifique a conexão e tente de novo.', 'erro');
  } finally {
    btn.disabled = false; btn.textContent = rotulo;
  }
};
async function excluirContrato(id) {
  const c = CONTRATOS.find(x => x.id === id);
  const ident = c && [c.banco, c.produto, c.parcela].filter(Boolean).join(' · ');
  if (!(await confirmar(`Excluir este lançamento${ident ? ' (' + ident + ')' : ''}?`, { perigo: true, okTexto: 'Excluir' }))) return;
  const r = await fetch('/api/contratos/' + encodeURIComponent(id), { method: 'DELETE' });
  if (!r.ok) { toast('Erro ao excluir.', 'erro'); return; }
  await carregarContratos();
  toast('Lançamento excluído.', 'ok');
}
