formFeedback.elements['descricao'].addEventListener('input', atualizarRequisitosFeedback);
document.getElementById('btnAddFeedbackImg').onclick = () => document.getElementById('inputFeedbackImg').click();
async function adicionarImagensFeedback(files, origem = 'selecionada') {
  const livres = 3 - feedbackImgsWork.length;
  if (livres <= 0) return toast('Máximo de 3 imagens por sugestão.', 'erro');
  if (files.length > livres) toast(`Você pode anexar só mais ${livres} imagem(ns).`);
  const antes = feedbackImgsWork.length;
  await adicionarArquivos(files.slice(0, livres), feedbackImgsWork, refreshFeedbackImgs, true);
  const adicionadas = feedbackImgsWork.length - antes;
  if (origem === 'colada' && adicionadas > 0) toast(`${adicionadas === 1 ? 'Captura colada' : `${adicionadas} capturas coladas`} com sucesso!`, 'ok');
}
document.getElementById('inputFeedbackImg').onchange = async (e) => {
  const files = [...e.target.files]; e.target.value = '';
  await adicionarImagensFeedback(files);
};
// Capturas copiadas do Windows (Print Screen/Recorte) chegam como itens image/* no evento paste.
// Só bloqueamos a colagem padrão quando há imagem; textos continuam sendo colados normalmente.
document.getElementById('feedbackModal').addEventListener('paste', async (e) => {
  const itens = [...((e.clipboardData && e.clipboardData.items) || [])];
  const imagens = itens
    .filter(item => item.kind === 'file' && /^image\//.test(item.type || ''))
    .map(item => item.getAsFile())
    .filter(Boolean);
  if (!imagens.length) return;
  e.preventDefault();
  const agora = Date.now();
  const nomeadas = imagens.map((arquivo, i) => {
    const ext = ({ 'image/jpeg': 'jpg', 'image/webp': 'webp' })[arquivo.type] || 'png';
    return new File([arquivo], `captura-colada-${agora}${i ? `-${i + 1}` : ''}.${ext}`, { type: arquivo.type, lastModified: agora });
  });
  await adicionarImagensFeedback(nomeadas, 'colada');
});
formFeedback.addEventListener('submit', async (e) => {
  e.preventDefault();
  const dados = { tipo: formFeedback.elements['tipo'].value, titulo: formFeedback.elements['titulo'].value, descricao: formFeedback.elements['descricao'].value };
  if (dados.titulo.trim().length < FEEDBACK_TITULO_MIN) {
    toast(`O título precisa ter pelo menos ${FEEDBACK_TITULO_MIN} caracteres.`, 'erro');
    return formFeedback.elements['titulo'].focus();
  }
  if (dados.descricao.trim().length < FEEDBACK_DESCRICAO_MIN) {
    toast(`A descrição precisa ter pelo menos ${FEEDBACK_DESCRICAO_MIN} caracteres.`, 'erro');
    return formFeedback.elements['descricao'].focus();
  }
  if (!feedbackImgsWork.length) {
    toast('Adicione ao menos uma imagem ao feedback.', 'erro');
    return document.getElementById('btnAddFeedbackImg').focus();
  }
  const btn = formFeedback.querySelector('button[type="submit"]');
  btn.disabled = true; const txtBtn = btn.textContent; btn.textContent = 'Enviando…';
  try {
    dados.imagens = await subirPendentes(feedbackImgsWork); // sobe os anexos ao cofre e guarda só as refs
    const r = await fetch('/api/feedbacks', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(dados) });
    if (!r.ok) { const j = await r.json().catch(() => ({})); return toast(j.erro || 'Erro ao enviar.', 'erro'); }
    fecharFeedbackModal();
    await carregarFeedbacks();
    toast('Obrigado! Sua sugestão foi enviada. 💙', 'ok');
  } catch (err) {
    toast(err.message || 'Erro ao enviar a imagem.', 'erro');
  } finally {
    btn.disabled = false; btn.textContent = txtBtn;
  }
});
