    + cartaoEpi('Sem assinatura', n(RAPIDOS_EPI_MOV.semAssinatura), 'fichas a assinar', n(RAPIDOS_EPI_MOV.semAssinatura) ? 'amber' : 'green', 'semAssinatura', 'mov')
    + cartaoEpi('Entregue com CA vencido', n(RAPIDOS_EPI_MOV.caVencidoNaEntrega), 'irregularidade', n(RAPIDOS_EPI_MOV.caVencidoNaEntrega) ? 'red' : 'green', 'caVencidoNaEntrega', 'mov');
