function fecharOficModal() { document.getElementById('oficModal').hidden = true; liberarDocOfic(); }
const _btnAddOfic = document.getElementById('btnAddOfic');
if (_btnAddOfic) _btnAddOfic.onclick = () => abrirOficModal(null);
document.getElementById('fecharOfic').onclick = fecharOficModal;
document.getElementById('cancelarOfic').onclick = fecharOficModal;
fecharAoClicarNoFundo('oficModal', fecharOficModal);
document.getElementById('btnDocOfic').onclick = () => document.getElementById('inputDocOfic').click();
document.getElementById('inputDocOfic').onchange = async (e) => {
  const file = e.target.files[0]; e.target.value = '';
  if (!file) return;
  if (!/^image\//.test(file.type) && file.type !== 'application/pdf') { toast('Aceita apenas imagem ou PDF.', 'erro'); return; }
  const blob = await comprimirImagem(file);
  if (blob.size > 9 * 1024 * 1024) { toast('Arquivo muito grande (máx. 9 MB).', 'erro'); return; }
  liberarDocOfic();
  oficDocWork = { _file: blob, _url: URL.createObjectURL(blob), nome: file.name, tipo: /^image\//.test(file.type) ? 'image/jpeg' : file.type };
  renderDocOfic();
};
// Ao informar a placa, autopreenche o modelo pelo cadastro da Frota (só se ainda estiver vazio).
if (formOfic && formOfic.elements['placa']) formOfic.elements['placa'].addEventListener('change', () => {
  const pl = (formOfic.elements['placa'].value || '').trim().toUpperCase();
  const v = VEICULOS.find(x => (x.placa || '').toUpperCase() === pl);
  const elModelo = formOfic.elements['modelo'];
  if (v && elModelo && !elModelo.value.trim()) elModelo.value = v.modelo || v.versao || '';
});
if (formOfic) formOfic.addEventListener('submit', async (e) => {
  e.preventDefault();
  const dados = {};
  for (const el of formOfic.elements) if (el.name) dados[el.name] = el.value;
  if (!dados.placa.trim()) { formOfic.elements['placa'].focus(); toast('Informe a placa do veículo.', 'erro'); return; }
  const btn = formOfic.querySelector('button[type="submit"]');
  btn.disabled = true; const txtBtn = btn.textContent; btn.textContent = 'Salvando...';
  try {
    if (oficDocWork) {
      dados.anexo = oficDocWork.id
        ? { id: oficDocWork.id, nome: oficDocWork.nome, tipo: oficDocWork.tipo }
        : await enviarMidia(oficDocWork._file, oficDocWork.nome, oficDocWork.tipo);
    } else dados.anexo = null;
    const url = editandoOficId ? '/api/oficina/' + encodeURIComponent(editandoOficId) : '/api/oficina';
    const r = await fetch(url, { method: editandoOficId ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(dados) });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) { toast(j.erro || 'Erro ao salvar.', 'erro'); return; }
    fecharOficModal();
    await carregarOficina(); atualizarInicioStats();
    toast(editandoOficId ? 'Nota fiscal atualizada.' : 'Nota fiscal adicionada!', 'ok');
  } catch (err) { toast(err.message || 'Erro ao salvar.', 'erro'); }
  finally { btn.disabled = false; btn.textContent = txtBtn; }
});

/* ============================================================
   VISTORIAS; checklist de saída/retorno do veículo (sub-aba da Frota)
   Fotos vão para o cofre de mídia no SALVAR (deferidas, como nas
   instalações); o termo de responsabilidade fica gravado na vistoria.
   ============================================================ */
let VISTORIAS = [];
let editandoVistId = null;
let fotosVistWork = []; // { id?|_file, nome, tipo, _url? }
// ⚠️ Mantenha as CHAVES idênticas a ITENS_VISTORIA do server.js (os rótulos são livres).
const ITENS_VISTORIA_UI = [
  ['pneus', 'Pneus'], ['lataria', 'Lataria / pintura'], ['vidros', 'Vidros / retrovisores'],
  ['farois', 'Faróis / lanternas'], ['oleo', 'Óleo do motor'], ['agua', 'Água / arrefecimento'],
  ['freios', 'Freios'], ['estepe', 'Estepe / triângulo'], ['extintor', 'Extintor'],
  ['documentos', 'Documentos (CRLV)'], ['limpeza', 'Limpeza / interior'],
];
async function carregarVistorias() {
  try {
    const r = await fetch('/api/vistorias', { cache: 'no-store' });
    if (r.status === 401) { window.location = '/login'; return; }
    const d = r.ok ? await r.json() : [];
    VISTORIAS = Array.isArray(d) ? d : [];
  } catch (e) { VISTORIAS = []; }
  renderVistorias();
}
function vistFiltradas() {
  const q = (document.getElementById('vistBusca').value || '').trim().toLowerCase();
  const fP = getSel('fvistPlaca'), fT = getSel('fvistTipo');
  return VISTORIAS.filter(v => {
    if (fP.length && !fP.includes(v.placa)) return false;
    if (fT.length && !fT.includes(v.tipo)) return false;
    if (q && !`${v.placa} ${v.motorista} ${v.avarias}`.toLowerCase().includes(q)) return false;
    return true;
  });
}
function renderVistorias() {
  const corpo = document.getElementById('corpoVist');
  if (!corpo) return;
  if (MSEL.fvistPlaca) MSEL.fvistPlaca.setOpcoes([...new Set(VISTORIAS.map(v => v.placa).filter(Boolean))].sort());
  if (MSEL.fvistTipo) MSEL.fvistTipo.setOpcoes(['Saída', 'Retorno']);
  const dlP = document.getElementById('listaPlacasVist');
  if (dlP) dlP.innerHTML = [...new Set(VEICULOS.map(v => v.placa).filter(Boolean))].sort().map(p => `<option value="${esc(p)}">`).join('');
  const dlM = document.getElementById('listaMotoristasVist');
  if (dlM) dlM.innerHTML = [...new Set([...(CADASTROS.motoristas || []), ...VISTORIAS.map(v => v.motorista)])].filter(Boolean).sort((a, b) => a.localeCompare(b, 'pt-BR')).map(m => `<option value="${esc(m)}">`).join('');
  const lista = vistFiltradas().slice().sort((a, b) => String(b.data || '').localeCompare(String(a.data || '')) || (b.ts || 0) - (a.ts || 0));
  estadoVazio('vistVazio', VISTORIAS.length, lista.length,
    'Nenhuma vistoria registrada ainda. Clique em "+ Vistoria" para registrar a primeira saída ou retorno.',
    () => document.getElementById('btnLimparVist').click());
  const podeEditar = permissaoAtual('frota') === 'editar';
  const btnAdd = document.getElementById('btnAddVist');
  if (btnAdd) btnAdd.hidden = !podeEditar;
  corpo.innerHTML = lista.map(v => {
    const avarias = ITENS_VISTORIA_UI.filter(([k]) => v.itens && v.itens[k] === 'avaria');
    const check = avarias.length
      ? `<span class="func-doc-venc vencido" title="Avarias: ${esc(avarias.map(([, r]) => r).join(' · '))}${v.avarias ? ' · ' + esc(v.avarias) : ''}">⚠ ${avarias.length} avaria(s)</span>`
      : '<span class="func-doc-venc ok" title="Todos os itens do checklist em ordem">✓ ok</span>';
    const fotos = (v.fotos || []).length
      ? `<button type="button" class="placa-btn vist-fotos" data-id="${esc(v.id)}" title="Ver as fotos desta vistoria">📷 ${(v.fotos || []).length}</button>` : '—';
    return `<tr data-id="${esc(v.id)}">
      <td class="acoes">
        <button class="edit vist-edit" data-id="${esc(v.id)}" title="Editar" aria-label="Editar">${ICONE_LAPIS}</button>
        <button class="del vist-del" data-id="${esc(v.id)}" title="Excluir" aria-label="Excluir">${ICONE_LIXEIRA}</button>
      </td>
      <td class="cel-sec">${esc(dataBRdeISO(v.data))}</td>
      <td><button class="placa-btn placa-chip" data-placa="${esc(v.placa)}" title="Ver histórico do veículo">${esc(v.placa)}</button></td>
      <td><span class="tipo-badge ${v.tipo === 'Saída' ? 'tipo-rem' : 'tipo-inst'}">${esc(v.tipo)}</span></td>
      <td>${esc(v.motorista || '—')}</td>
      <td class="num cel-sec">${esc(v.km || '—')}</td>
      <td>${check}</td>
      <td>${fotos}</td>
      <td title="${v.termoAceito ? 'Termo de responsabilidade aceito pelo motorista' : 'Termo não marcado'}">${v.termoAceito ? '✓' : '—'}</td>
    </tr>`;
  }).join('');
  document.getElementById('vistResumo').innerHTML =
    `Exibindo <b>${lista.length}</b> de <b>${VISTORIAS.length}</b> vistorias`;
}
[['fvistPlaca', 'Placa'], ['fvistTipo', 'Tipo']].forEach(([fid, rot]) => criarMultiSelect(fid, rot, renderVistorias));
document.getElementById('vistBusca').addEventListener('input', debounce(renderVistorias, 120));
document.getElementById('btnLimparVist').onclick = () => {
  document.getElementById('vistBusca').value = '';
  ['fvistPlaca', 'fvistTipo'].forEach(f => MSEL[f] && MSEL[f].limpar());
  renderVistorias();
};
// ---- Modal ----
const formVist = document.getElementById('formVist');
function renderChecklistVist(itens) {
  document.getElementById('vistCheckGrid').innerHTML =
    '<span class="vist-check-tit">Checklist do veículo</span>' +
    ITENS_VISTORIA_UI.map(([k, rot]) => `
      <label class="vist-check-item">
        <span>${esc(rot)}</span>
        <select class="vck" data-k="${k}">
          <option value="ok"${(itens && itens[k]) === 'avaria' ? '' : ' selected'}>OK</option>
          <option value="avaria"${(itens && itens[k]) === 'avaria' ? ' selected' : ''}>Avaria</option>
        </select>
      </label>`).join('');
}
function renderFotosVist() {
  const grid = document.getElementById('fotosVistGrid');
  grid.innerHTML = fotosVistWork.map((f, i) => `
    <div class="vist-foto">
      <img src="${esc(urlMidia(f))}" alt="" loading="lazy" data-i="${i}" title="Ampliar" />
      <button type="button" class="vist-foto-rem" data-i="${i}" title="Remover foto" aria-label="Remover">✕</button>
    </div>`).join('');
  grid.querySelectorAll('img').forEach(im => im.onclick = () => abrirMidia(fotosVistWork, +im.dataset.i));
  grid.querySelectorAll('.vist-foto-rem').forEach(b => b.onclick = () => { fotosVistWork.splice(+b.dataset.i, 1); renderFotosVist(); });
}
function abrirVistModal(id) {
  editandoVistId = id || null;
  formVist.reset();
  liberarUrls(fotosVistWork); fotosVistWork = [];
  const v = id ? VISTORIAS.find(x => x.id === id) : null;
  document.getElementById('vistTitulo').textContent = id ? 'Editar vistoria' : 'Nova vistoria';
  if (v) {
    for (const el of formVist.elements) if (el.name && v[el.name] != null && el.type !== 'checkbox') el.value = v[el.name];
    formVist.elements['termoAceito'].checked = !!v.termoAceito;
    fotosVistWork = (v.fotos || []).map(f => Object.assign({}, f));
  } else {
    formVist.elements['data'].value = new Date().toISOString().slice(0, 10);
  }
  renderChecklistVist(v ? v.itens : null);
  renderFotosVist();
  syncCustomSelects();
  document.getElementById('vistModal').hidden = false;
  setTimeout(() => formVist.elements['placa'].focus(), 30);
}
function fecharVistModal() { document.getElementById('vistModal').hidden = true; }
document.getElementById('btnAddVist').onclick = () => abrirVistModal(null);
document.getElementById('fecharVist').onclick = fecharVistModal;
document.getElementById('cancelarVist').onclick = fecharVistModal;
fecharAoClicarNoFundo('vistModal', fecharVistModal);
document.getElementById('btnAddFotoVist').onclick = () => document.getElementById('inputFotoVist').click();
document.getElementById('inputFotoVist').addEventListener('change', async (e) => {
  for (const file of Array.from(e.target.files || [])) {
    const blob = await comprimirImagem(file);
    fotosVistWork.push({ _file: blob, nome: file.name || 'foto.jpg', tipo: 'image/jpeg', _url: URL.createObjectURL(blob) });
  }
  e.target.value = '';
  renderFotosVist();
});
formVist.addEventListener('submit', async (e) => {
  e.preventDefault();
  const dados = {};
  for (const el of formVist.elements) if (el.name && el.type !== 'checkbox') dados[el.name] = el.value;
  dados.termoAceito = formVist.elements['termoAceito'].checked;
  dados.itens = {};
  document.querySelectorAll('#vistCheckGrid .vck').forEach(s => { dados.itens[s.dataset.k] = s.value; });
  if (!dados.placa.trim()) { formVist.elements['placa'].focus(); return toast('Informe a placa do veículo.', 'erro'); }
  if (!dados.motorista.trim()) { formVist.elements['motorista'].focus(); return toast('Informe o motorista/responsável.', 'erro'); }
  const btn = formVist.querySelector('button[type="submit"]');
  btn.disabled = true; const txt = btn.textContent; btn.textContent = 'Salvando…';
  try {
    const fotos = [];
    for (const f of fotosVistWork) fotos.push(f.id ? { id: f.id, nome: f.nome, tipo: f.tipo } : await enviarMidia(f._file, f.nome, f.tipo));
    dados.fotos = fotos;
    const url = editandoVistId ? '/api/vistorias/' + encodeURIComponent(editandoVistId) : '/api/vistorias';
    const r = await fetch(url, { method: editandoVistId ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(dados) });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(j.erro || 'Erro ao salvar.');
    fecharVistModal();
    await carregarVistorias();
    toast(editandoVistId ? 'Vistoria atualizada.' : 'Vistoria registrada!', 'ok');
  } catch (err) { toast(err.message || 'Erro ao salvar.', 'erro'); }
  finally { btn.disabled = false; btn.textContent = txt; }
});
// Ações da tabela (delegação) + fotos no lightbox + placa → histórico.
document.getElementById('corpoVist').addEventListener('click', async (e) => {
  const ed = e.target.closest('.vist-edit'); if (ed) { abrirVistModal(ed.dataset.id); return; }
  const del = e.target.closest('.vist-del');
  if (del) {
    const v = VISTORIAS.find(x => x.id === del.dataset.id);
    if (!(await confirmar(`Excluir a vistoria de ${v ? v.tipo.toLowerCase() : ''} ${v ? 'de ' + v.placa : ''}? As fotos anexadas também serão removidas.`, { perigo: true, okTexto: 'Excluir' }))) return;
    const r = await fetch('/api/vistorias/' + encodeURIComponent(del.dataset.id), { method: 'DELETE' });
    if (!r.ok) { toast('Erro ao excluir.', 'erro'); return; }
    await carregarVistorias();
    toast('Vistoria excluída.', 'ok');
    return;
  }
  const ft = e.target.closest('.vist-fotos');
  if (ft) { const v = VISTORIAS.find(x => x.id === ft.dataset.id); if (v && v.fotos && v.fotos.length) abrirMidia(v.fotos, 0); return; }
  const pb = e.target.closest('.placa-btn'); if (pb && pb.dataset.placa) abrirHistVeiculo(pb.dataset.placa);
});

/* ============================================================
   INTEGRAÇÃO (treinamentos: vídeo do Drive + prova) · lado RH
   ============================================================ */
// Catálogo de treinamentos. O gabarito (alternativa correta) NUNCA chega na listagem;
// ao editar, buscamos o detalhe com ?editar=1 (gated por permissão de editar no servidor).
let TREINAMENTOS = [];
const intgEstado = { busca: '', tipo: 'all', vis: 'catalogo', acmpBusca: '', acmpStatus: 'all', acmpTreino: 'all', acmp: [], acmpCarregado: false };
// Seleção múltipla do Acompanhamento (1.55.40): ids dos convites marcados para "Excluir
// selecionados". Só entra convite NÃO concluído (concluído é histórico com certificado; o servidor
// recusa com 409) e só para quem edita a Integração. O "Selecionar todos" (SEL_TODOS_ACMP) é
// registrado no fim do arquivo, junto das outras abas (TDZ dos const).
// Ex.: clicar na linha de Ana (aguardando) → SELECAO_ACMP = {'cv_1'} → barra "1 convite selecionado".
const SELECAO_ACMP = new Set();
// Painel lateral do convite aberto agora (abrirDetalheAcmp): { id, sincronizar, fechar } ou null.
// Declarado aqui em cima porque renderAcompanhamento() o consulta.
let _detalheAcmp = null;
async function carregarIntegracao() {
  try {
    const r = await fetch('/api/treinamentos', { cache: 'no-store' });
    if (r.status === 401) { window.location = '/login'; return; }
    if (r.ok) { const j = await r.json(); TREINAMENTOS = Array.isArray(j.treinamentos) ? j.treinamentos : []; }
    else { toast('Não foi possível carregar os treinamentos. Verifique a conexão e tente novamente.', 'erro'); }
  } catch (e) { toast('Não foi possível carregar os treinamentos. Verifique a conexão e tente novamente.', 'erro'); }
  renderIntegracao();
  if (intgEstado.vis === 'acompanha') carregarAcompanhamento();
}
// Alterna entre o Catálogo e o Acompanhamento (rastreio de quem fez a prova).
function setIntgVis(vis) {
  intgEstado.vis = (vis === 'acompanha') ? 'acompanha' : 'catalogo';
  document.querySelectorAll('#intgVis .func-vis-btn').forEach(b => b.classList.toggle('on', b.dataset.intgvis === intgEstado.vis));
  const cat = document.getElementById('intgPainelCatalogo'), acm = document.getElementById('intgPainelAcompanha');
  if (cat) cat.hidden = intgEstado.vis !== 'catalogo';
  if (acm) acm.hidden = intgEstado.vis !== 'acompanha';
  if (intgEstado.vis === 'acompanha') carregarAcompanhamento();
  sincronizarUrlIntg();
}
// Roteamento da Integração: /integracao (catálogo) e /integracao/acompanhamento.
function intgPathAtual() { return BASE_PAINEL + '/integracao' + (intgEstado.vis === 'acompanha' ? '/acompanhamento' : ''); }
function sincronizarUrlIntg() {
  if (rotaDaPath() !== 'integracao') return;
  if (_navModo === 'silent') return;
  const destino = intgPathAtual();
  if (location.pathname === destino) return;
  if (_navModo === 'replace') history.replaceState(null, '', destino);
  else history.pushState(null, '', destino);
}
function aplicarIntgViewDaPath(seg) {
  if (seg === undefined) seg = subDaPath();
  const vis = (seg === 'acompanhamento') ? 'acompanha' : 'catalogo';
  const prev = _navModo; _navModo = 'replace';   // aplica no endereço sem empurrar histórico
  try { setIntgVis(vis); } finally { _navModo = prev; }
}
// Busca o rastreio no servidor (cruza convites + conclusões). Recarrega sempre que abre.
async function carregarAcompanhamento() {
  const host = document.getElementById('acmpLista');
  if (host && !intgEstado.acmpCarregado) host.innerHTML = '<p class="forn-contagem">Carregando…</p>';
  try {
    const r = await fetch('/api/treinamentos/acompanhamento', { cache: 'no-store' });
    if (r.ok) { const j = await r.json(); intgEstado.acmp = Array.isArray(j.itens) ? j.itens : []; intgEstado.acmpCarregado = true; }
    else if (r.status !== 401) { toast('Não foi possível carregar o acompanhamento.', 'erro'); }
  } catch (e) { toast('Não foi possível carregar o acompanhamento.', 'erro'); }
  renderAcompanhamento();
}
const ACMP_STATUS = {
  concluido: { rot: 'Concluído', cls: 't-aprovado' },
  aguardando: { rot: 'Em andamento', cls: 't-pendente' }, // mesmo nome do indicador (1.55.45)
  expirado: { rot: 'Expirado', cls: 't-reprovado' },
  cancelado: { rot: 'Cancelado', cls: 't-reprovado' },
};
// Filtro de treinamento do Acompanhamento (montado a partir dos dados). A situação saiu dos chips
// (1.55.45): quem filtra por situação são os indicadores do topo (renderAcmpKpis), como na Multas.
function renderAcmpFiltros() {
  const host = document.getElementById('acmpFiltros');
  if (!host) return;
  // O treinamento escolhido pelo "Acompanhar" do catálogo entra na lista mesmo sem nenhum envio ainda.
  const treinos = [...new Set(intgEstado.acmp.map(a => a.treino).concat(intgEstado.acmpTreino !== 'all' ? [intgEstado.acmpTreino] : []).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'pt-BR'));
  const opts = ['<option value="all">Todos os treinamentos</option>']
    .concat(treinos.map(t => `<option value="${esc(t)}"${intgEstado.acmpTreino === t ? ' selected' : ''}>${esc(t)}</option>`)).join('');
  host.innerHTML = `<select id="acmpTreinoSel" class="acmp-treino-sel" aria-label="Filtrar por treinamento">${opts}</select>`;
}
// ---- Situação de cada convite (1.55.45): categoria, "vencendo" e o recorte da tela ----
// Categoria = a do filtro/indicadores: concluído vence o status do servidor (aprovado por este
// convite); o resto é o status efetivo ('aguardando' | 'expirado' | 'cancelado').
// "Vencendo" é um subconjunto do aguardando: link que vence hoje, amanhã ou depois de amanhã.
// USO: acmpCategoria({ concluido: true, status: 'aguardando' }) → 'concluido'
//      acmpCategoria({ status: 'expirado' })                   → 'expirado'
//      acmpVencendo({ status: 'aguardando', validadeTs: <amanhã> }) → true
//      acmpNoFiltro({ status: 'aguardando', validadeTs: <daqui a 5 dias> }, 'vencendo') → false
//      acmpNoFiltro({ comentarios: [{ avaliacao: 'ok' }] }, 'comentario')                → true
const ACMP_DIAS_VENCENDO = 2;
// Comentários que o colaborador deixou ao lado do vídeo (1.55.43) e quantos relatam problema.
// USO: acmpComentarios({ comentarios: [{ avaliacao: 'problema' }] }) → [{ avaliacao: 'problema' }]
//      acmpProblemas({ comentarios: [{ avaliacao: 'ok' }, { avaliacao: 'problema' }] }) → 1
function acmpComentarios(a) { return Array.isArray(a && a.comentarios) ? a.comentarios : []; }
function acmpProblemas(a) { return acmpComentarios(a).filter(c => c.avaliacao === 'problema').length; }
function acmpCategoria(a) { return acmpConcluido(a) ? 'concluido' : ((a && a.status) || 'aguardando'); }
function acmpVencendo(a) {
  return acmpCategoria(a) === 'aguardando' && !!a.validadeTs && acmpDiasAte(a.validadeTs) <= ACMP_DIAS_VENCENDO;
}
function acmpNoFiltro(a, st) {
  if (!st || st === 'all') return true;
  if (st === 'vencendo') return acmpVencendo(a);
  if (st === 'comentario') return acmpComentarios(a).length > 0;
  return acmpCategoria(a) === st;
}
// Recorte = busca + treinamento escolhido (sem a situação). É a base dos indicadores e da faixa de
// atenção: os números contam o que a pessoa está olhando, e clicar num indicador só troca a situação.
// USO: intgEstado.acmpTreino = 'NR-35'; acmpRecorte() → só os convites de NR-35 (todas as situações)
function acmpRecorte() {
  const termo = intgEstado.acmpBusca.trim().toLowerCase();
  return intgEstado.acmp.filter(a => {
    if (intgEstado.acmpTreino !== 'all' && a.treino !== intgEstado.acmpTreino) return false;
    if (termo && ![a.nome, a.treino].some(c => (c || '').toLowerCase().includes(termo))) return false;
    return true;
  });
}
// Há recorte (busca ou treinamento escolhido)? Decide se o 1º indicador diz "no recorte".
// USO: intgEstado.acmpBusca = 'ana'; acmpTemRecorte() → true · sem busca e 'all' → false
function acmpTemRecorte() { return !!intgEstado.acmpBusca.trim() || intgEstado.acmpTreino !== 'all'; }
// O que está NA TELA: recorte + situação escolhida no indicador (é também o que o Excel exporta).
// USO: intgEstado.acmpStatus = 'expirado'; acmpFiltrados() → só os expirados do recorte
function acmpFiltrados() { return acmpRecorte().filter(a => acmpNoFiltro(a, intgEstado.acmpStatus)); }
// ---- Acompanhamento: formato das células (1.55.35) ----
// Concluído = flag `concluido` do servidor (aprovado por ESTE convite) ou status efetivo 'concluido'.
// USO: acmpConcluido({ concluido: true }) → true · acmpConcluido({ status: 'aguardando' }) → false
function acmpConcluido(a) { return !!(a && (a.concluido === true || a.status === 'concluido')); }
// Só o que pode ser excluído entra na seleção múltipla (e no "Selecionar todos").
// USO: acmpSelecionaveis([{ id: 'a', status: 'concluido' }, { id: 'b', status: 'aguardando' }]) → [{ id: 'b', … }]
function acmpSelecionaveis(lista) { return (lista || []).filter(a => !acmpConcluido(a)); }
// Datas do Acompanhamento e dos modais de link (fuso do navegador).
// USO: acmpData(1790000000000) → '21/09/2026' · acmpDataCurta(1790000000000) → '21/09'
//      acmpDataHora(1790000000000) → '21/09/2026 14:13' · qualquer uma com 0/null → ''
function acmpData(ts) { return ts ? new Date(ts).toLocaleDateString('pt-BR') : ''; }
function acmpDataCurta(ts) { return ts ? new Date(ts).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }) : ''; }
function acmpDataHora(ts) {
  return ts ? new Date(ts).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }).replace(',', '') : '';
}
// Dias de CALENDÁRIO de hoje até `ts` (0 = hoje, 1 = amanhã, negativo = já passou).
// USO: acmpDiasAte(Date.now() + 86400000) → 1 · acmpDiasAte(Date.now() - 3 * 86400000) → -3
function acmpDiasAte(ts) {
  const hoje = new Date(); hoje.setHours(0, 0, 0, 0);
  const alvo = new Date(ts); alvo.setHours(0, 0, 0, 0);
  return Math.round((alvo - hoje) / 86400000);
}
// Dia e hora curtos, para as sub-linhas da tabela: '24/09 08:48' ('' sem data).
// USO: acmpDataHoraCurta(1790000000000) → '21/09 11:13' (horário de Brasília; é o fuso do navegador)
function acmpDataHoraCurta(ts) {
  return ts ? new Date(ts).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }).replace(',', '') : '';
}
// Quando o link aguardando vence, em palavras (hoje/amanhã/em N dias).
// USO: acmpVenceTxt({ validadeTs: <amanhã> }) → 'vence amanhã' · acmpVenceTxt({ validadeTs: <+5 dias> }) → 'vence em 5 dias'
function acmpVenceTxt(a) {
  const dias = acmpDiasAte(a.validadeTs);
  return dias <= 0 ? 'vence hoje' : dias === 1 ? 'vence amanhã' : `vence em ${dias} dias`;
}
// Duração do link em uso, em dias (do último link gerado até a validade). 0 = não dá para saber.
// USO: acmpDuracaoLinkDias({ geradoTs: t, validadeTs: t + 7 * 86400000 }) → 7
function acmpDuracaoLinkDias(a) {
  const base = Number(a.regeradoTs || a.geradoTs) || 0;
  return base && a.validadeTs > base ? Math.round((a.validadeTs - base) / 86400000) : 0;
}
// Validade do certificado, pronta do servidor (item.certificadoAte, AAAA-MM-DD no fuso de Brasília:
// a MESMA data do PDF do atestado e da planilha, datasCertificadoTreino no server.js).
// Devolve 'dd/mm/aaaa', '' = sem vencimento, null = sem aprovação ou treinamento excluído.
// USO: acmpCertificadoAte({ concluido: true, certificadoAte: '2028-09-24' }) → '24/09/2028'
//      acmpCertificadoAte({ concluido: true, certificadoAte: '' })           → ''
//      acmpCertificadoAte({ status: 'aguardando', certificadoAte: null })     → null
function acmpCertificadoAte(a) {
  if (!acmpConcluido(a) || a.certificadoAte == null) return null;
  const m = String(a.certificadoAte).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return m ? `${m[3]}/${m[2]}/${m[1]}` : '';
}
// Coluna PRAZO: o prazo do link enquanto ele vale; para quem foi aprovado, a validade do certificado.
// USO: acmpPrazoColHtml({ status: 'aguardando', validadeTs: <+5 dias>, geradoTs: <-2 dias> }) → 'Até 29/09' / 'link de 7 dias'
//      acmpPrazoColHtml({ status: 'aguardando', validadeTs: <amanhã 08:22> })               → 'Vence amanhã' (aviso) / '25/09 08:22'
//      acmpPrazoColHtml({ status: 'expirado', validadeTs: <21/09> })                        → 'Venceu' (perigo) / 'em 21/09'
//      acmpPrazoColHtml({ concluido: true, certificadoAte: '2028-09-24' })                  → 'Certificado' (ok) / 'válido até 24/09/2028'
function acmpPrazoColHtml(a) {
  const cel = (txt, sub, cls = '', dica = '') => `<span class="acmp-cel"${dica ? ` title="${esc(dica)}"` : ''}><span class="${cls}">${esc(txt)}</span>${sub ? `<span class="acmp-sub">${esc(sub)}</span>` : ''}</span>`;
  if (acmpConcluido(a)) {
    const ate = acmpCertificadoAte(a);
    return cel('Certificado', ate ? `válido até ${ate}` : ate === '' ? 'sem vencimento' : '', 'acmp-tom-ok');
  }
  if (a.status === 'cancelado') return cel('Cancelado', '', 'acmp-nao');
  if (!a.validadeTs) return '<span class="acmp-nao">—</span>';
  const dica = `Link válido até ${acmpDataHora(a.validadeTs)}`;
  if (a.status === 'expirado') return cel('Venceu', `em ${acmpDataCurta(a.validadeTs)}`, 'acmp-tom-perigo', dica);
  if (acmpVencendo(a)) {
    const t = acmpVenceTxt(a);
    return cel(t.charAt(0).toUpperCase() + t.slice(1), acmpDataHoraCurta(a.validadeTs), 'acmp-tom-aviso', dica);
  }
  const dur = acmpDuracaoLinkDias(a);
  return cel(`Até ${acmpDataCurta(a.validadeTs)}`, dur ? `link de ${dur} ${plural(dur, 'dia', 'dias')}` : '', '', dica);
}
// Abriu o link? (acesso registrado; aprovado ou com prova feita também conta, para registro antigo.)
// USO: acmpAbriu({ acessadoTs: t }) → true · acmpAbriu({ status: 'aguardando' }) → false
function acmpAbriu(a) { return !!(a && (a.ultimoAcessoTs || a.acessadoTs || acmpConcluido(a) || Number(a.tentativas) > 0)); }
// ---- Progresso em 5 etapas (1.55.45): Enviado → Acessou → Vídeo → Prova → Aprovado ----
// Estados de cada etapa (viram classe CSS `.acmp-passo.<estado>` em design-integracao.css):
//   'feito' · 'atual' (primeira etapa que falta, só com o link valendo) · 'falta' · 'falhou' (prova
//   reprovada: quadrado vermelho, pode refazer) · 'sem-trava' (vídeo pelo Drive: não dá para saber se
//   assistiu, contorno tracejado) · 'sem-info' (treinamento excluído: não se sabe nem a origem do
//   vídeo; mesmo tracejado) · 'liberado' (prova liberada pelo RH sem o vídeo: losango âmbar).
// A forma muda junto com a cor (reprovado = quadrado, liberado = losango, Drive = tracejado), para
// não depender só de cor. `estado` é a frase da situação e `tom` a cor dela.
// USO: acmpEtapas({ status: 'aguardando', acessadoTs: t, video: { concluidoTs: t2 } })
//      → { passos: ['feito','feito','feito','atual','falta'], alcancadas: [true,true,true,false,false],
//          estado: 'Vídeo assistido, falta a prova', tom: 'tinta' }
//      acmpEtapas({ status: 'expirado', origemVideo: 'drive' })
//      → { passos: ['feito','falta','sem-trava','falta','falta'], alcancadas: [true,false,false,false,false],
//          estado: 'Link vencido sem ser aberto', tom: 'perigo' }
//      acmpEtapas({ status: 'expirado', acessadoTs: t, tentativas: 1, provas: [{ nota: 40, aprovado: false }], origemVideo: 'drive' })
//      → { passos: ['feito','feito','sem-trava','falhou','falta'], …, estado: 'Reprovado, link vencido', tom: 'perigo' }
//      acmpEtapas({ concluido: true, video: null, origemVideo: 'drive' })
//      → { passos: ['feito','feito','sem-trava','feito','feito'], alcancadas: [true,true,true,true,true], estado: 'Aprovado', tom: 'ok' }
const ACMP_ETAPAS = ['Enviado', 'Acessou', 'Vídeo', 'Prova', 'Aprovado'];
const ACMP_PASSO_DESC = { feito: 'feito', atual: 'etapa atual', falta: 'pendente', falhou: 'reprovado', 'sem-trava': 'sem trava (Drive)', 'sem-info': 'sem registro', liberado: 'liberado pelo RH' };
function acmpEtapas(a) {
  const concl = acmpConcluido(a);
  const abriu = acmpAbriu(a);
  const v = a.video && typeof a.video === 'object' ? a.video : null;
  const n = Number(a.tentativas) || 0;
  const passoVideo = !v ? (a.origemVideo === 'drive' ? 'sem-trava' : 'sem-info')
    : v.concluidoTs ? 'feito' : v.liberadoTs ? 'liberado' : (concl ? 'sem-trava' : 'falta');
  const passos = ['feito', abriu ? 'feito' : 'falta', passoVideo, concl ? 'feito' : (n > 0 ? 'falhou' : 'falta'), concl ? 'feito' : 'falta'];
  // Marca onde a pessoa parou: só com o link valendo e sem prova reprovada (o quadrado já diz).
  if (!concl && a.status === 'aguardando' && !passos.includes('falhou')) {
    const i = passos.indexOf('falta');
    if (i >= 0) passos[i] = 'atual';
  }
  // Até onde a pessoa chegou (pinta os trilhos): etapa feita, reprovada ou liberada, ou o vídeo do
  // Drive depois de ter aberto o link. Uma etapa só conta se todas as anteriores contaram.
  const alcancadas = [];
  passos.forEach((p, i) => {
    alcancadas[i] = (i === 0 || alcancadas[i - 1]) && (p === 'feito' || p === 'falhou' || p === 'liberado' || ((p === 'sem-trava' || p === 'sem-info') && abriu));
  });
  let estado, tom = 'tinta';
  if (concl) { estado = 'Aprovado'; tom = 'ok'; }
  else if (a.status === 'cancelado') { estado = 'Convite cancelado'; tom = 'neutro'; }
  else if (a.status === 'expirado') { estado = n > 0 ? 'Reprovado, link vencido' : abriu ? 'Link vencido antes da prova' : 'Link vencido sem ser aberto'; tom = 'perigo'; }
  else if (n > 0) { estado = 'Reprovado, pode refazer'; tom = 'perigo'; }
  else if (!abriu) { estado = 'Enviado, ainda não abriu'; tom = 'neutro'; }
  else if (v && v.liberadoTs && !v.concluidoTs) { estado = 'Prova liberada pelo RH'; tom = 'aviso'; }
  else if (v && v.concluidoTs) estado = 'Vídeo assistido, falta a prova';
  else if (v && v.iniciadoTs) estado = 'Assistindo ao vídeo';
  else if (v) estado = 'Abriu, vídeo não iniciado';
  else estado = 'Abriu, falta a prova';
  return { passos, alcancadas, estado, tom };
}
// Marcadores das etapas (bolinhas ligadas por trilhos) com a frase da situação embaixo. O leitor
// de tela ouve as etapas pelo aria-label e a frase pelo texto que vem logo depois (não repete);
// o mouse vê o nome de cada etapa no title.
// USO: acmpProgressoHtml({ status: 'aguardando' })
//      → '<span class="acmp-prog" role="img" aria-label="Progresso: Enviado: feito, Acessou: etapa atual, …">…</span>
//         <span class="acmp-estado neutro">Enviado, ainda não abriu</span>'
function acmpProgressoHtml(a) {
  const { passos, alcancadas, estado, tom } = acmpEtapas(a);
  const aria = `Progresso: ${passos.map((p, i) => `${ACMP_ETAPAS[i]}: ${ACMP_PASSO_DESC[p]}`).join(', ')}.`;
  const marcas = passos.map((p, i) => (i ? `<span class="acmp-trilho${alcancadas[i] ? ' feito' : ''}"></span>` : '')
    + `<span class="acmp-passo ${p}" title="${esc(`${ACMP_ETAPAS[i]}: ${ACMP_PASSO_DESC[p]}`)}"></span>`).join('');
  return `<span class="acmp-prog" role="img" aria-label="${esc(aria)}">${marcas}</span><span class="acmp-estado ${tom}">${esc(estado)}</span>`;
}
// Última coisa que aconteceu com o convite (a mais recente entre envio, novo link, acesso, vídeo e
// provas). Empate no mesmo instante: vale a etapa mais adiantada (a que vem depois na lista).
// USO: acmpUltimaAtividade({ geradoTs: 1, criadoPor: 'Ana', acessadoTs: 5, acessos: 3, provas: [{ ts: 9, nota: 40, aprovado: false }] })
//      → { ts: 9, txt: 'Reprovado na prova', extra: '40%' }
//      acmpUltimaAtividade({}) → null
function acmpUltimaAtividade(a) {
  const ev = [];
  const add = (ts, txt, extra = '') => { if (Number(ts) > 0) ev.push({ ts: Number(ts), txt, extra }); };
  add(a.geradoTs, 'Link enviado', a.criadoPor ? `por ${a.criadoPor}` : '');
  add(a.regeradoTs, 'Novo link gerado', a.regeradoPor ? `por ${a.regeradoPor}` : '');
  const nAc = Number(a.acessos) || 0;
  add(a.ultimoAcessoTs || a.acessadoTs, 'Abriu o link', nAc > 1 ? `${nAc} acessos` : '');
  const v = a.video && typeof a.video === 'object' ? a.video : null;
  if (v) {
    add(v.iniciadoTs, 'Começou o vídeo');
    add(v.concluidoTs, 'Terminou o vídeo');
    add(v.liberadoTs, 'Prova liberada pelo RH', v.liberadoPor ? `por ${v.liberadoPor}` : '');
  }
  const provas = Array.isArray(a.provas) ? a.provas : [];
  provas.forEach(p => add(p.ts, p.aprovado ? 'Aprovado na prova' : 'Reprovado na prova', p.nota != null ? `${p.nota}%` : ''));
  acmpComentarios(a).forEach(c => add(c.ts, c.avaliacao === 'problema' ? 'Relatou um problema' : 'Deixou um comentário'));
  if (!provas.length && acmpConcluido(a)) add(a.concluidoTs, 'Aprovado na prova');
  return ev.length ? ev.reduce((m, e) => (e.ts >= m.ts ? e : m)) : null;
}
// Coluna ÚLTIMA ATIVIDADE: o que aconteceu + quando (dd/mm hh:mm) e o detalhe (quem, nota, acessos).
// USO: acmpAtividadeHtml({ acessadoTs: t, acessos: 11 }) → 'Abriu o link' / '24/09 08:48 · 11 acessos'
function acmpAtividadeHtml(a) {
  const u = acmpUltimaAtividade(a);
  if (!u) return '<span class="acmp-nao">—</span>';
  const sub = [acmpDataHoraCurta(u.ts), u.extra].filter(Boolean).join(' · ');
  return `<span class="acmp-cel" title="${esc(acmpDataHora(u.ts))}"><span>${esc(u.txt)}</span><span class="acmp-sub">${esc(sub)}</span></span>`;
}
// Coluna NOTA: nota da última tentativa + em qual tentativa foi aprovado ou quantas já fez.
// USO: acmpNotaHtml({ concluido: true, ultimaNota: 100, tentativas: 2, provas: [{ aprovado: false }, { aprovado: true }] })
//      → '100%' (ok) / '2ª tentativa'
//      acmpNotaHtml({ ultimaNota: 40, tentativas: 1 }) → '40%' (perigo) / '1 tentativa'
//      acmpNotaHtml({ ultimaNota: null })               → '—'
function acmpNotaHtml(a) {
  const n = Number(a.tentativas) || 0;
  if (a.ultimaNota == null || !n) return '<span class="acmp-nao">—</span>';
  const concl = acmpConcluido(a);
  const k = Array.isArray(a.provas) ? a.provas.findIndex(p => p.aprovado) + 1 : 0;
  const sub = concl ? (k ? `${k}ª tentativa` : 'aprovado') : `${n} ${plural(n, 'tentativa', 'tentativas')}`;
  return `<span class="acmp-cel"><span class="acmp-nota ${concl ? 'acmp-tom-ok' : 'acmp-tom-perigo'}">${esc(String(a.ultimaNota))}%</span><span class="acmp-sub">${esc(sub)}</span></span>`;
}
// Por que um convite precisa de atenção do RH (faixa "N convites precisam de atenção"), ou null.
// Prioridade: link vencido > reprovado > comentário relatando problema > link vencendo. Concluído
// e cancelado nunca entram (aprovado que comentou problema aparece no aviso da linha e no painel).
// USO: acmpMotivoAtencao({ status: 'expirado', validadeTs: <21/09> })
//      → { sev: 'error', peso: 0, texto: 'Link venceu em 21/09 sem ser aberto' }
//      acmpMotivoAtencao({ status: 'aguardando', tentativas: 1, ultimaNota: 40, validadeTs: <amanhã> })
//      → { sev: 'warning', peso: 1, texto: 'Reprovado com 40% em 1 tentativa; o link vence amanhã' }
//      acmpMotivoAtencao({ status: 'aguardando', validadeTs: <+5 dias>, comentarios: [{ avaliacao: 'problema' }] })
//      → { sev: 'warning', peso: 1.5, texto: 'Relatou 1 problema nos comentários' }
//      acmpMotivoAtencao({ status: 'aguardando', validadeTs: <amanhã> })
//      → { sev: 'warning', peso: 2, texto: 'Link vence amanhã e ainda não foi aberto' }
function acmpMotivoAtencao(a) {
  if (!a || acmpConcluido(a)) return null;
  const abriu = acmpAbriu(a);
  if (a.status === 'expirado') {
    return { sev: 'error', peso: 0, texto: `Link venceu${a.validadeTs ? ` em ${acmpDataCurta(a.validadeTs)}` : ''} ${abriu ? 'antes da aprovação' : 'sem ser aberto'}` };
  }
  if (a.status !== 'aguardando') return null;
  const n = Number(a.tentativas) || 0;
  const vencendo = acmpVencendo(a);
  if (n > 0) {
    const base = `Reprovado com ${a.ultimaNota != null ? `${a.ultimaNota}%` : 'nota baixa'} em ${n} ${plural(n, 'tentativa', 'tentativas')}`;
    return { sev: 'warning', peso: 1, texto: vencendo ? `${base}; o link ${acmpVenceTxt(a)}` : `${base}; pode refazer no mesmo link` };
  }
  const nProb = acmpProblemas(a);
  if (nProb) {
    const base = `Relatou ${nProb} ${plural(nProb, 'problema', 'problemas')} nos comentários`;
    return { sev: 'warning', peso: 1.5, texto: vencendo ? `${base}; o link ${acmpVenceTxt(a)}` : base };
  }
  if (vencendo) return { sev: 'warning', peso: 2, texto: `Link ${acmpVenceTxt(a)}${abriu ? '' : ' e ainda não foi aberto'}` };
  return null;
}
// Ações da linha (botões quadrados do DS, `.acoes button`): Link e Certificado para todos
// (`acao-leitura`: quem só vê continua com eles); para quem EDITA, Excluir (não concluído) ou Novo
// convite (concluído) e, por último, "Liberar prova" (vídeo travado pendente). O Certificado fica
// SEMPRE no lugar (1.55.42): sem aprovação ele aparece apagado, com `aria-disabled` (continua
// focável para a dica, DESIGN.md) e o clique é ignorado — assim não sobra buraco no meio da linha.
// A vaga do "Liberar prova" só existe se alguma linha da lista tem o botão (`comLiberar`) e fica no
// FIM, onde a vaga invisível (ACAO_VAGA) não abre espaço entre os ícones.
// USO: acoesLinhaAcmp({ id: 'cv_1', nome: 'Ana', token: 'T', status: 'aguardando' }, true)
//      → '<td class="acoes acoes-com-leitura">[Link][Certificado apagado][Excluir]</td>'
//      acoesLinhaAcmp({ id: 'cv_2', nome: 'Bia', token: 'T', concluido: true, concluidoTs: t }, true)
//      → '<td …>[Link][Certificado][Novo convite]</td>'
//      acoesLinhaAcmp({ …aguardando }, false) → '<td …>[Link][Certificado apagado]</td>' (só vê)
function acoesLinhaAcmp(a, podeEditar, comLiberar = false) {
  const nome = a.nome || 'colaborador';
  const id = esc(a.id);
  const vagaLeitura = ACAO_VAGA.replace('class="acoes-vaga"', 'class="acoes-vaga acao-leitura"');
  const concl = acmpConcluido(a);
  const btn = (cls, rot, icone) => `<button type="button" class="${cls}" data-id="${id}" title="${esc(rot)}" aria-label="${esc(rot)}">${icone}</button>`;
  let html = a.token ? btn('acmp-link acao-leitura', `Link e andamento de ${nome}`, ICONE_LINK) : vagaLeitura;
  html += concl && a.concluidoTs
    ? btn('acmp-cert acao-leitura', `Baixar o certificado de ${nome}`, ICONE_PDF)
    : `<button type="button" class="acmp-cert acmp-cert-off acao-leitura" data-id="${id}" aria-disabled="true" title="${esc(`O certificado fica disponível quando ${nome} for aprovado na prova`)}" aria-label="${esc(`Certificado indisponível: ${nome} ainda não foi aprovado`)}">${ICONE_PDF}</button>`;
  if (podeEditar) {
    html += concl
      ? btn('acmp-repetir', `Novo convite para ${nome} repetir o treinamento`, ICONE_REPETIR)
      : btn('acmp-del del', `Excluir o convite de ${nome}`, ICONE_LIXEIRA);
    if (comLiberar) html += botaoLiberarProvaAcmp(a, true) || ACAO_VAGA;
  }
  return `<td class="acoes acoes-com-leitura">${html}</td>`;
}
// Indicadores do Acompanhamento (1.55.45): seis `.v2-kpi` clicáveis que também são o filtro de
// situação (clicar de novo no ativo volta para "todos"). Contam o RECORTE (busca + treinamento),
// nunca a situação escolhida; com recorte, o primeiro diz "no recorte" e a nota traz o total
// (regra de escopo dos KPIs, docs/DESIGN.md §5). Antes de carregar (ou se a carga falhou) não há
// número: todos mostram "—" (zero é dado; "não consegui consultar" não é).
// USO: renderAcmpKpis() → #acmpKpis com Enviados · Em andamento · Concluídos · Vencem em até 2 dias ·
//      Expirados · Com comentário
function renderAcmpKpis() {
  const host = document.getElementById('acmpKpis');
  if (!host) return;
  const rotVenc = `Vencem em até ${ACMP_DIAS_VENCENDO} dias`;
  if (!intgEstado.acmpCarregado) {
    host.innerHTML = ['Enviados', 'Em andamento', 'Concluídos', rotVenc, 'Expirados', 'Com comentário'].map(r => kpiV2(r, '', { extraCls: 'v2-kpi-indisp' })).join('');
    return;
  }
  const base = acmpRecorte();
  const st = intgEstado.acmpStatus;
  const andamento = base.filter(a => acmpCategoria(a) === 'aguardando');
  const abriram = andamento.filter(acmpAbriu).length;
  const concl = base.filter(a => acmpCategoria(a) === 'concluido').length;
  const venc = base.filter(acmpVencendo);
  const vencSemAbrir = venc.filter(a => !acmpAbriu(a)).length;
  const exp = base.filter(a => acmpCategoria(a) === 'expirado').length;
  const comComent = base.filter(a => acmpComentarios(a).length);
  const comProblema = comComent.filter(a => acmpProblemas(a)).length;
  const pct = base.length ? Math.round(concl * 100 / base.length) : 0;
  const nTreinos = new Set(base.map(a => a.treinamentoId)).size;
  const card = (id, rot, n, estado, nota, dica) => kpiV2(rot, String(n), {
    estado: n ? estado : '', nota, clicavel: true, ativo: st === id,
    attrs: { 'data-acmpstatus': id, 'aria-pressed': String(st === id), title: dica },
  });
  host.innerHTML = [
    card('all', acmpTemRecorte() ? 'Enviados no recorte' : 'Enviados', base.length, '',
      acmpTemRecorte() ? `de ${intgEstado.acmp.length} no total` : `${nTreinos} ${plural(nTreinos, 'treinamento', 'treinamentos')}`,
      'Mostrar todos os convites'),
    card('aguardando', 'Em andamento', andamento.length, '',
      andamento.length ? (abriram ? `${abriram} ${plural(abriram, 'já abriu', 'já abriram')} o link` : 'ninguém abriu o link ainda') : 'nenhum link valendo',
      'Mostrar só os convites com link valendo e ainda não aprovados'),
    card('concluido', 'Concluídos', concl, 'positivo', `${pct}% de conclusão`, 'Mostrar só os aprovados'),
    card('vencendo', rotVenc, venc.length, 'aviso',
      venc.length === 1 ? (venc[0].nome || '1 convite') : venc.length ? (vencSemAbrir ? `${vencSemAbrir} ainda sem abrir o link` : 'todos já abriram o link') : 'nenhum link perto de vencer',
      `Mostrar só os links que vencem hoje ou nos próximos ${ACMP_DIAS_VENCENDO} dias`),
    card('expirado', 'Expirados', exp, 'risco',
      exp ? plural(exp, 'precisa de um novo link', 'precisam de um novo link') : 'nenhum link vencido',
      'Mostrar só os convites com o link vencido'),
    card('comentario', 'Com comentário', comComent.length, comProblema ? 'aviso' : '',
      comComent.length ? (comProblema ? `${comProblema} ${plural(comProblema, 'relata', 'relatam')} problema` : 'nenhum relata problema') : 'ninguém comentou',
      'Mostrar só quem deixou comentário sobre o treinamento'),
  ].join('');
}
// Faixa "N convites precisam de atenção" (componente .ds-alert, montarFaixaAlerta): link vencido,
// reprovado e link vencendo, do recorte atual. Clicar num item abre o painel do convite, onde estão
// as ações (gerar novo link, copiar/reenviar, liberar prova).
// USO: renderAcmpAlerta() → #acmpAlerta com "3 convites precisam de atenção [Ver 3 convites]"
function renderAcmpAlerta() {
  const host = document.getElementById('acmpAlerta');
  if (!host) return;
  const itens = !intgEstado.acmpCarregado ? [] : acmpRecorte()
    .map(a => ({ a, m: acmpMotivoAtencao(a) }))
    .filter(x => x.m)
    .sort((x, y) => x.m.peso - y.m.peso || (x.a.validadeTs || 0) - (y.a.validadeTs || 0));
  montarFaixaAlerta({
    host,
    itens: itens.map(({ a, m }) => ({
      id: a.id, rotuloId: a.nome || 'Colaborador', desc: a.treino || 'Treinamento',
      // O item clicado (foco atual) vira o gatilho: ao fechar o painel, o foco volta para a faixa.
      info: m.texto, severidade: m.sev, onClick: () => abrirDetalheAcmp(a.id, document.activeElement),
    })),
    singular: 'convite precisa de atenção', plural: 'convites precisam de atenção',
    acaoSingular: 'convite', acaoPlural: 'convites',
  });
}
// Legenda dos marcadores do progresso (fica embaixo da tabela). Só entra a partir de 768 px: no
// celular os marcadores não têm desenho (o design-mobile.css não foi mexido) e a legenda seria um
// texto sem sentido. Os espaços entre os itens não aparecem no computador (flex ignora texto só
// de espaço); estão lá para o texto não grudar se um dia ela aparecer sem estilo.
const ACMP_LEGENDA_HTML = `<p class="acmp-legenda"><span class="acmp-legenda-tit">Progresso:</span>`
  + [['feito', 'etapa feita'], ['atual', 'etapa atual'], ['falta', 'etapa pendente'], ['sem-trava', 'vídeo sem trava (Drive)'], ['liberado', 'prova liberada pelo RH'], ['falhou', 'reprovado']]
    .map(([p, rot]) => ` <span><span class="acmp-passo ${p}" aria-hidden="true"></span>${rot}</span>`).join('')
  + ` <span class="acmp-legenda-ordem">${ACMP_ETAPAS.join(' · ')}</span></p>`;
// Tabela do Acompanhamento (redesenho 1.55.45): Colaborador · Treinamento · Progresso · Prazo ·
// Última atividade · Nota · Ações. As fixas somam o mesmo das 7 colunas antigas, então continua
// cabendo em 1366 px com o menu lateral fixado (larguras em design-integracao.css, table-layout
// fixo, sem rolagem horizontal). Clique na área livre da linha seleciona (só quem edita, só não
// concluído). Também repinta indicadores, faixa de atenção e o painel do convite, se aberto.
function renderAcompanhamento() {
  const host = document.getElementById('acmpLista');
  if (!host) return;
  renderAcmpFiltros();
  renderAcmpKpis();
  renderAcmpAlerta();
  const lista = acmpFiltrados();
  const cont = document.getElementById('acmpContagem');
  if (cont) cont.textContent = `${lista.length} ${lista.length === 1 ? 'convite' : 'convites'}`;
  const podeEditar = permissaoAtual('integracao') === 'editar';
  const btnEnviar = document.getElementById('btnAcmpEnviar');
  if (btnEnviar) btnEnviar.hidden = !podeEditar;
  SEL_TODOS_ACMP.sincronizar(podeEditar ? acmpSelecionaveis(lista) : []);
  if (!lista.length) {
    const semEnvio = intgEstado.acmpTreino !== 'all' && !intgEstado.acmp.some(a => a.treino === intgEstado.acmpTreino);
    const filtrando = intgEstado.acmp.length && !semEnvio;
    host.innerHTML = `<div class="acmp-vazio"><p class="func-docs-vazio">${semEnvio ? 'Este treinamento ainda não foi enviado. Use o botão Enviar treinamento.' : filtrando ? 'Nenhum convite com os filtros atuais.' : 'Nenhum treinamento enviado ainda. Use o botão Enviar treinamento.'}</p>`
      + `${filtrando ? '<button type="button" class="btn btn-ghost acmp-limpar">Limpar filtros</button>' : ''}</div>`;
    atualizarSelBarAcmp();
    if (_detalheAcmp) _detalheAcmp.sincronizar();
    return;
  }
  const comLiberar = podeEditar && lista.some(a => botaoLiberarProvaAcmp(a, true));
  const nAcoes = 2 + (podeEditar ? 1 : 0) + (comLiberar ? 1 : 0);
  const linhas = lista.map(a => {
    const concl = acmpConcluido(a);
    const selecionavel = podeEditar && !concl;
    const cls = [selecionavel ? 'acmp-selecionavel' : '', selecionavel && SELECAO_ACMP.has(a.id) ? 'sel-on' : ''].filter(Boolean).join(' ');
    const nome = a.nome || '—';
    const quem = a.acessoCpf ? `CPF ${cpfCrachaMasc(a.acessoCpf)}` : (acmpAbriu(a) ? 'abriu o link' : 'ainda não abriu');
    const origem = a.origemVideo === 'arquivo' || a.video
      ? `<span class="acmp-origem">${ICONE_VIDEO_TRN}<span>Vídeo travado</span></span>`
      : a.origemVideo === 'drive' ? `<span class="acmp-origem">${ICONE_DRIVE_TRN}<span>Drive, sem trava</span></span>` : '';
    return `<tr data-id="${esc(a.id)}"${cls ? ` class="${cls}"` : ''}${selecionavel ? ` aria-selected="${SELECAO_ACMP.has(a.id)}"` : ''}>
      <td class="acmp-nome"><span class="acmp-cel"><button type="button" class="acmp-nome-btn" data-id="${esc(a.id)}" title="Ver o link e o andamento de ${esc(nome)}">${esc(nome)}</button><span class="acmp-sub">${esc(quem)}</span></span></td>
      <td class="acmp-treino"><span class="acmp-cel"><span title="${esc(a.treino || '')}">${esc(a.treino || '—')}</span>${origem}</span></td>
      <td>${acmpProgressoHtml(a)}${comentariosAcmpHtml(a)}</td>
      <td>${acmpPrazoColHtml(a)}</td>
      <td>${acmpAtividadeHtml(a)}</td>
      <td class="num">${acmpNotaHtml(a)}</td>
      ${acoesLinhaAcmp(a, podeEditar, comLiberar)}
    </tr>`;
  }).join('');
  host.innerHTML = `<div class="acmp-tabela-wrap"><table class="acmp-tabela acmp-acoes-${nAcoes}">
    <colgroup><col class="acmp-c-nome"><col class="acmp-c-treino"><col class="acmp-c-prog"><col class="acmp-c-prazo"><col class="acmp-c-ativ"><col class="acmp-c-nota"><col class="acmp-c-acoes"></colgroup>
    <thead><tr><th>Colaborador</th><th>Treinamento</th><th>Progresso</th><th>Prazo</th><th>Última atividade</th><th class="num">Nota</th><th class="acmp-th-acoes">Ações</th></tr></thead>
    <tbody>${linhas}</tbody>
  </table></div>${window.matchMedia('(min-width: 768px)').matches ? ACMP_LEGENDA_HTML : ''}`;
  atualizarSelBarAcmp();
  // Depois de pintar: se o painel fechar (convite excluído), o foco acha a tabela NOVA.
  if (_detalheAcmp) _detalheAcmp.sincronizar();
}
// Barra de seleção do Acompanhamento: poda o que sumiu ou virou concluído (SSE, outro usuário),
// sincroniza o "Selecionar todos" e mostra "N selecionado(s)". Só aparece para quem edita.
// USO: SELECAO_ACMP.add('cv_1'); atualizarSelBarAcmp() → #selBarAcmp visível, "1 convite selecionado"
function atualizarSelBarAcmp() {
  const bar = document.getElementById('selBarAcmp');
  if (!bar) return;
  const podeEditar = permissaoAtual('integracao') === 'editar';
  const vivos = new Set(acmpSelecionaveis(intgEstado.acmp).map(a => a.id));
  for (const id of [...SELECAO_ACMP]) if (!podeEditar || !vivos.has(id)) SELECAO_ACMP.delete(id);
  SEL_TODOS_ACMP.sincronizar();
  const n = SELECAO_ACMP.size;
  bar.hidden = !n;
  const info = document.getElementById('selBarAcmpInfo');
  if (info) info.textContent = `${n} ${plural(n, 'convite selecionado', 'convites selecionados')}`;
}
// Exclui convites do Acompanhamento (lixeira da linha ou "Excluir selecionados"). Confirma com um
// resumo do impacto; 1 id → DELETE, vários → excluir-lote (tudo ou nada no servidor: 403 se algum
// está fora do recorte, 409 se algum já foi concluído). Sucesso → toast com "Desfazer" (15 min).
// USO: excluirConvitesAcmp(['cv_1'])          → confirmar → DELETE /api/treinamentos/convites/cv_1
//      excluirConvitesAcmp(['cv_1', 'cv_2']) → confirmar → POST /api/treinamentos/convites/excluir-lote { ids:[…] }
//      → toast "2 convites excluídos." [Desfazer] e a tabela recarrega sem piscar.
let _acmpExcluindo = false;
async function excluirConvitesAcmp(ids) {
  ids = [...new Set((ids || []).filter(Boolean))];
  if (!ids.length || _acmpExcluindo) return;
  const regs = ids.map(id => intgEstado.acmp.find(a => a.id === id)).filter(Boolean);
  const n = ids.length;
  const acessaram = regs.filter(a => a.ultimoAcessoTs || a.acessadoTs).length;
  const comTentativa = regs.some(a => Number(a.tentativas) > 0);
  const um = n === 1 && regs[0];
  let msg = um
    ? `Excluir o convite de ${um.nome || 'colaborador'} para "${um.treino || 'treinamento'}"?`
    : `Excluir ${n} convites de treinamento?`;
  if (acessaram) msg += um ? ' Esta pessoa já acessou o link.' : ` ${acessaram} ${plural(acessaram, 'deles já acessou', 'deles já acessaram')} o link.`;
  if (comTentativa) msg += ' As tentativas reprovadas da prova saem junto.';
  msg += ` ${plural(n, 'O link para', 'Os links param')} de funcionar na hora. Dá para desfazer por 15 minutos pelo botão Desfazer.`;
  if (!(await confirmar(msg, { perigo: true, okTexto: 'Excluir' }))) return;
  _acmpExcluindo = true;
  const btnBarra = document.getElementById('selBarAcmpExcluir');
  if (btnBarra) btnBarra.disabled = true;
  try {
    const r = n === 1
      ? await fetch('/api/treinamentos/convites/' + encodeURIComponent(ids[0]), { method: 'DELETE' })
      : await fetch('/api/treinamentos/convites/excluir-lote', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ids }) });
    const d = await r.json().catch(() => ({}));
    if (!r.ok || !d.ok) {
      toast(d.erro || 'Não foi possível excluir. Nada foi apagado.', 'erro');
      await carregarAcompanhamento();
      return;
    }
    for (const id of ids) SELECAO_ACMP.delete(id);
    await carregarAcompanhamento();
    const qtd = Number(d.excluidos) || n;
    toast(`${qtd} ${plural(qtd, 'convite excluído', 'convites excluídos')}.`, 'ok', { texto: 'Desfazer', fn: () => desfazerUltimaAlteracao('integracao') });
    atualizarUndoStatus();
  } catch (e) {
    toast('Não foi possível excluir. Verifique a conexão.', 'erro');
  } finally {
    _acmpExcluindo = false;
    if (btnBarra) btnBarra.disabled = false;
  }
}
// Novo convite para REPETIR um treinamento já concluído (a conclusão e o certificado ficam
// guardados; nasce um registro novo). Usa o envio em lote com uma pessoa só; se ela já tiver um
// link ativo desse treinamento, o resultado mostra esse link em "Já tinham link ativo".
// USO: repetirTreinoAcmp({ id: 'cv_1', nome: 'Ana', funcionarioId: 'F1', treinamentoId: 'TRN1', treino: 'NR-35' })
//      → confirmar → POST /api/treinamentos/convites/lote { treinamentoId:'TRN1', funcionarioIds:['F1'], dias:7 }
//      → modal "Links do treinamento" com o link novo; o Acompanhamento recarrega.
//      `aoEnviar` (opcional) roda antes de abrir o resultado (ex.: fechar o modal de origem).
async function repetirTreinoAcmp(a, aoEnviar) {
  if (!a || !a.funcionarioId || !a.treinamentoId) return;
  const treino = TREINAMENTOS.find(t => t.id === a.treinamentoId) || { id: a.treinamentoId, titulo: a.treino || 'treinamento' };
  const dias = 7;
  const ok = await confirmar(`Enviar um novo convite para ${a.nome || 'o colaborador'} repetir "${treino.titulo}"? Nasce um registro novo com link válido por ${dias} dias; a conclusão atual e o certificado continuam guardados.`, { okTexto: 'Enviar novo convite' });
  if (!ok) return;
  try {
    const r = await fetch('/api/treinamentos/convites/lote', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ treinamentoId: a.treinamentoId, funcionarioIds: [a.funcionarioId], dias }),
    });
    const d = await r.json().catch(() => ({}));
    if (!r.ok || !d.ok) { toast(d.erro || 'Não foi possível enviar o novo convite.', 'erro'); return; }
    if (typeof aoEnviar === 'function') aoEnviar();
    abrirResultadoLoteTreino(d, treino, dias);
    carregarAcompanhamento();
  } catch (e) { toast('Não foi possível enviar o novo convite. Verifique a conexão.', 'erro'); }
}
// Baixa o certificado (atestado PDF) de um registro do Acompanhamento.
async function baixarCertificadoAcmp(conviteId) {
  try {
    const r = await fetch('/api/treinamentos/acompanhamento/' + encodeURIComponent(conviteId) + '/certificado', { cache: 'no-store' });
    if (!r.ok) { const j = await r.json().catch(() => ({})); toast(j.erro || 'Não foi possível baixar o certificado.', 'erro'); return; }
    const blob = await r.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = (r.headers.get('Content-Disposition') || '').match(/filename="?([^"]+)"?/)?.[1] || 'atestado.pdf';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  } catch (e) { toast('Erro ao baixar o certificado.', 'erro'); }
}
// Botão "Liberar prova" de uma linha do Acompanhamento: só para quem EDITA a Integração, só
// enquanto o vídeo travado está pendente e o treinamento não foi concluído.
// Formato de botão QUADRADO do DS (`.acoes button`, dentro de acoesLinhaAcmp): só o ícone, com o
// nome no title/aria-label.
// USO: botaoLiberarProvaAcmp({ id: 'cv_1', nome: 'Ana', video: { pendente: true } }, true) → '<button type="button" class="acmp-liberar" data-id="cv_1" title="Liberar a prova de Ana…" aria-label="…">(cadeado)</button>'
//      botaoLiberarProvaAcmp({ id: 'cv_1', video: { pendente: true } }, false)             → '' (só vê)
//      botaoLiberarProvaAcmp({ id: 'cv_1', status: 'concluido', video: { pendente: true } }, true) → ''
function botaoLiberarProvaAcmp(a, podeEditar) {
  if (!podeEditar || !a || !a.video || !a.video.pendente) return '';
  const concluido = typeof a.concluido === 'boolean' ? a.concluido : a.status === 'concluido';
  if (concluido) return '';
  const rot = `Liberar a prova de ${a.nome || 'colaborador'} sem o vídeo ter terminado`;
  return `<button type="button" class="acmp-liberar" data-id="${esc(a.id)}" title="${esc(rot)}" aria-label="${esc(rot)}">${ICONE_LIBERAR_TRN}</button>`;
}
// Saída de emergência do vídeo travado: libera a prova sem o vídeo ter terminado (aparelho que
// não toca o vídeo, treinamento dado presencialmente). O servidor registra quem liberou.
// USO: liberarProvaAcmp('cv_1a2b3c') → confirmação → POST /api/treinamentos/convites/cv_1a2b3c/liberar-prova
//      → toast "Prova liberada para Ana." e o Acompanhamento recarrega (409 se já concluído ou sem vídeo).
async function liberarProvaAcmp(conviteId) {
  const a = (intgEstado.acmp || []).find(x => x.id === conviteId);
  if (!a) return;
  const nome = a.nome || 'o colaborador';
  const ok = await confirmar(`Liberar a prova para ${nome} sem terminar o vídeo? A prova fica disponível no link na hora, mesmo sem o vídeo ter sido assistido até o fim, e fica registrado que foi você quem liberou. Use só quando o aparelho não toca o vídeo ou o treinamento foi dado presencialmente.`, { okTexto: 'Liberar prova' });
  if (!ok) return;
  try {
    const r = await fetch('/api/treinamentos/convites/' + encodeURIComponent(conviteId) + '/liberar-prova', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
    const d = await r.json().catch(() => ({}));
    if (!r.ok || !d.ok) { toast(d.erro || 'Não foi possível liberar a prova.', 'erro'); if (r.status === 409 || r.status === 404) { intgEstado.acmpCarregado = false; carregarAcompanhamento(); } return; }
    toast(`Prova liberada para ${nome}.`, 'ok');
  } catch (e) { toast('Não foi possível liberar a prova. Verifique a conexão.', 'erro'); return; }
  intgEstado.acmpCarregado = false;
  carregarAcompanhamento();
}
// Sub-linha da coluna Situação com os comentários que o funcionário deixou ao lado do vídeo.
// Mostra o total e quantos relatam problema (o que o RH precisa ver primeiro); clicar abre a lista.
// USO: comentariosAcmpHtml({ id: 'cv_1', comentarios: [{ avaliacao: 'ok' }, { avaliacao: 'problema' }] })
//        → '<button class="acmp-coment tem-problema" …>2 comentários · 1 problema</button>'
//      comentariosAcmpHtml({ comentarios: [] }) → ''
function comentariosAcmpHtml(a) {
  const coms = Array.isArray(a && a.comentarios) ? a.comentarios : [];
  if (!coms.length) return '';
  const nProb = coms.filter(c => c.avaliacao === 'problema').length;
  // Dois pedaços que não quebram por dentro: em coluna estreita o "1 problema" desce inteiro.
  const total = `${coms.length} ${coms.length === 1 ? 'comentário' : 'comentários'}`;
  const prob = nProb ? `${nProb} ${nProb === 1 ? 'problema' : 'problemas'}` : '';
  return `<button type="button" class="acmp-coment${nProb ? ' tem-problema' : ''}" data-id="${esc(a.id)}" title="Ler os comentários de ${esc(a.nome || 'colaborador')} no painel do convite" aria-label="${esc(total + (prob ? ', ' + prob : ''))}">${ICONE_COMENT_TRN}<span class="acmp-coment-txt-linha"><span>${esc(total)}</span>${prob ? `<span>${esc(prob)}</span>` : ''}</span></button>`;
}
const ICONE_COMENT_TRN = '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>';
// Botão "Enviar treinamento" do Acompanhamento (1.55.45): manda um treinamento sem voltar ao
// Catálogo. Com um treinamento escolhido no filtro (ou só um cadastrado), abre direto o envio em lote
// dele; senão pergunta qual. Só aparece para quem edita a Integração.
// USO: enviarTreinoDoAcompanhamento() → (filtro "NR-35") abrirGerarLinkTreino('TRN1')
//      enviarTreinoDoAcompanhamento() → (sem filtro) modal "Enviar treinamento" → Continuar → abrirGerarLinkTreino(id)
function enviarTreinoDoAcompanhamento() {
  if (permissaoAtual('integracao') !== 'editar') return;
  const lista = TREINAMENTOS.slice().sort((a, b) => (a.titulo || '').localeCompare(b.titulo || '', 'pt-BR'));
  if (!lista.length) { toast('Cadastre um treinamento no Catálogo antes de enviar.', 'erro'); return; }
  const escolhido = intgEstado.acmpTreino !== 'all' ? lista.find(t => t.titulo === intgEstado.acmpTreino) : null;
  if (escolhido || lista.length === 1) { abrirGerarLinkTreino((escolhido || lista[0]).id); return; }
  const opts = lista.map(t => `<option value="${esc(t.id)}">${esc(t.titulo)}</option>`).join('');
  const { ov, fechar } = abrirModalTrn('Enviar treinamento',
    `<div class="form-grid trn-escolha-corpo">
      <label class="full">Treinamento<select class="trn-escolha-sel">${opts}</select></label>
      <p class="full dica">Na próxima tela você escolhe os colaboradores e a validade do link.</p>
    </div>`,
    { largura: 460, rodape: '<button class="btn btn-ghost" type="button" data-fechar>Cancelar</button><button class="btn btn-primary trn-escolha-ok" type="button">Continuar</button>' });
  const sel = ov.querySelector('.trn-escolha-sel');
  ov.querySelector('.trn-escolha-ok').addEventListener('click', () => { const id = sel.value; fechar(); abrirGerarLinkTreino(id); });
  sel.focus();
}
// Botão "Acompanhar" do card do catálogo: abre o Acompanhamento já filtrado pelo treinamento
// (todas as situações, sem busca). Vale também para quem só vê a Integração.
// USO: acompanharTreino('TRN1') → intgEstado.acmpTreino = 'NR-35 Trabalho em altura' → /painel/integracao/acompanhamento
function acompanharTreino(treinoId) {
  const t = TREINAMENTOS.find(x => x.id === treinoId);
  if (!t) return;
  intgEstado.acmpTreino = t.titulo;
  intgEstado.acmpStatus = 'all';
  intgEstado.acmpBusca = '';
  const busca = document.getElementById('acmpBusca'); if (busca) busca.value = '';
  SELECAO_ACMP.clear();
  setIntgVis('acompanha');
}
function intgRotuloTipo(t) { return t === 'curso' ? 'Curso' : 'NR'; }
// Etiqueta de ORIGEM do vídeo no card do catálogo (1.55.41): mostra ao RH o que ainda falta
// migrar do Drive (sem trava) para o vídeo enviado (player travado).
// USO: etiquetaOrigemVideoTreino({ video: { duracaoSeg: 720 } }) → '<span class="treino-meta treino-origem com-video" …>(svg) Vídeo · 12 min</span>'
//      etiquetaOrigemVideoTreino({ fileId: '1AbC…' })          → '<span class="treino-meta treino-origem so-drive" …>(svg) Drive (sem trava)</span>'
//      etiquetaOrigemVideoTreino({})                           → '' (sem vídeo nenhum: nada a mostrar)
function etiquetaOrigemVideoTreino(t) {
  const v = t && t.video;
  if (v && typeof v === 'object') {
    return `<span class="treino-meta treino-origem com-video" title="Vídeo enviado: o colaborador não consegue adiantar nem acelerar, e a prova só abre no fim">${ICONE_VIDEO_TRN}<span>Vídeo · ${esc(minutosVideoTxt(v.duracaoSeg))}</span></span>`;
  }
  if (t && t.fileId) {
    return `<span class="treino-meta treino-origem so-drive" title="Vídeo pelo Google Drive: o colaborador pode adiantar. Para travar, edite e envie o arquivo">${ICONE_DRIVE_TRN}<span>Drive (sem trava)</span></span>`;
  }
  return '';
}
// Duração do vídeo em minutos para etiqueta curta (arredonda; mínimo 1 min).
// USO: minutosVideoTxt(720) → '12 min' · minutosVideoTxt(20) → '1 min' · minutosVideoTxt(3725) → '1 h 02 min'
function minutosVideoTxt(seg) {
  const min = Math.max(1, Math.round((Number(seg) || 0) / 60));
  if (min < 60) return `${min} min`;
  return `${Math.floor(min / 60)} h ${String(min % 60).padStart(2, '0')} min`;
}
// Duração no formato de relógio, para o vídeo atual do modal e a situação do Acompanhamento.
// USO: fmtDuracaoVideo(612) → '10:12' · fmtDuracaoVideo(3725) → '1:02:05' · fmtDuracaoVideo(0) → '0:00'
function fmtDuracaoVideo(seg) {
  const s = Math.max(0, Math.round(Number(seg) || 0));
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), r = s % 60;
  const mm = h ? String(m).padStart(2, '0') : String(m);
  return (h ? h + ':' : '') + mm + ':' + String(r).padStart(2, '0');
}
function renderIntgFiltros() {
  const host = document.getElementById('intgFiltros');
  if (!host) return;
  const cont = (val) => val === 'all' ? TREINAMENTOS.length : TREINAMENTOS.filter(t => t.tipo === val).length;
  const chip = (val, rot) => `<button class="forn-chip${intgEstado.tipo === val ? ' on' : ''}" data-tipo="${esc(val)}">${esc(rot)}</button>`;
  host.innerHTML = chip('all', `Todos (${cont('all')})`) + chip('NR', `NR (${cont('NR')})`) + chip('curso', `Cursos (${cont('curso')})`);
}
function intgFiltrados() {
  const termo = intgEstado.busca.trim().toLowerCase();
  return TREINAMENTOS.filter(t => {
    if (intgEstado.tipo !== 'all' && t.tipo !== intgEstado.tipo) return false;
    if (!termo) return true;
    return [t.titulo, intgRotuloTipo(t.tipo), t.descricao].some(c => (c || '').toLowerCase().includes(termo));
  });
}
function renderIntgVazio(total, filtrado, podeEditar) {
  const el = document.getElementById('intgVazio');
  if (!el) return;
  if (filtrado > 0) { el.hidden = true; return; }
  el.hidden = false;
  if (total > 0) { // filtrando, sem resultado
    el.innerHTML = `<span class="empty-ico" aria-hidden="true">${_EMPTY_ICO_LUPA}</span><span class="empty-msg">Nenhum resultado para os filtros atuais.</span>`;
    const b = document.createElement('button');
    b.type = 'button'; b.className = 'btn btn-primary empty-acao'; b.textContent = 'Limpar filtros';
    b.onclick = () => { intgEstado.busca = ''; intgEstado.tipo = 'all'; const s = document.getElementById('intgBusca'); if (s) s.value = ''; renderIntegracao(); };
    el.appendChild(b);
    return;
  }
  // catálogo realmente vazio (copy do UI-SPEC, visão RH)
  el.innerHTML = `<span class="empty-ico" aria-hidden="true">${_EMPTY_ICO_BOX}</span>`
    + `<span class="empty-msg"><strong>Catálogo de treinamentos vazio</strong><br>Cadastre o primeiro treinamento para a equipe começar a se capacitar.</span>`;
  if (podeEditar) {
    const b = document.createElement('button');
    b.type = 'button'; b.className = 'btn btn-primary empty-acao'; b.textContent = '+ Novo treinamento';
    b.onclick = () => abrirTreinoModal(null);
    el.appendChild(b);
  }
}
function renderIntegracao() {
  renderIntgFiltros();
  const podeEditar = permissaoAtual('integracao') === 'editar';
  const btnNovo = document.getElementById('btnNovoTreino');
  if (btnNovo) btnNovo.hidden = !podeEditar;
  const cont = document.getElementById('intgCards');
  if (!cont) return;
  const lista = intgFiltrados().slice().sort((a, b) => (a.titulo || '').localeCompare(b.titulo || '', 'pt-BR'));
  const contagem = document.getElementById('intgContagem');
  if (contagem) contagem.textContent = (intgEstado.busca || intgEstado.tipo !== 'all')
    ? `${lista.length} de ${TREINAMENTOS.length} treinamentos`
    : `${TREINAMENTOS.length} ${TREINAMENTOS.length === 1 ? 'treinamento' : 'treinamentos'}`;
  renderIntgVazio(TREINAMENTOS.length, lista.length, podeEditar);
  cont.innerHTML = lista.map(t => {
    const tipoCls = t.tipo === 'curso' ? 't-tipo-curso' : 't-tipo-nr';
    const nQ = (t.questoes || []).length;
    const val = Number(t.validadeMeses) || 0;
    const valTxt = val > 0 ? `Validade: ${val} ${val === 1 ? 'mês' : 'meses'}` : 'Sem validade';
    return `<article class="card treino-card" data-id="${esc(t.id)}">
      <div class="treino-card-top">
        <h3 class="treino-card-tit" title="${esc(t.titulo)}">${esc(t.titulo)}</h3>
        <span class="pill-trigger ${tipoCls}">${esc(intgRotuloTipo(t.tipo))}</span>
      </div>
      ${t.descricao ? `<p class="treino-card-desc">${esc(t.descricao)}</p>` : ''}
      <div class="treino-card-pe">
        <span class="treino-meta">${ICONE_QUESTOES_TRN}<span>${nQ} ${nQ === 1 ? 'questão' : 'questões'}</span></span>
        <span class="treino-meta">${ICONE_RELOGIO_TRN}<span>${esc(valTxt)}</span></span>
        ${etiquetaOrigemVideoTreino(t)}
      </div>
      <div class="treino-card-acoes">
        <span class="treino-card-acoes-btns">
          ${podeEditar ? `<button type="button" class="btn btn-ghost small treino-link" data-id="${esc(t.id)}" title="Enviar este treinamento para um ou vários colaboradores">${ICONE_ENVIAR_TRN}<span>Enviar</span></button>` : ''}
          <button type="button" class="btn btn-ghost small treino-acompanhar" data-id="${esc(t.id)}" title="Ver quem recebeu este treinamento, acessou e concluiu">${ICONE_ACOMPANHAR_TRN}<span>Acompanhar</span></button>
        </span>
        ${podeEditar ? `<span class="treino-card-acoes-icones">
          <button class="treino-edit" data-id="${esc(t.id)}" title="Editar" aria-label="Editar">${ICONE_LAPIS}</button>
          <button class="treino-del" data-id="${esc(t.id)}" title="Excluir" aria-label="Excluir">${ICONE_LIXEIRA}</button>
        </span>` : ''}
      </div>
    </article>`;
  }).join('');
}
// Busca + filtros por tipo + ações do card (delegação)
(() => {
  // Alternância Catálogo / Acompanhamento
  const vis = document.getElementById('intgVis');
  if (vis) vis.addEventListener('click', (e) => { const b = e.target.closest('.func-vis-btn'); if (b) setIntgVis(b.dataset.intgvis); });
  const acmpBusca = document.getElementById('acmpBusca');
  if (acmpBusca) acmpBusca.addEventListener('input', debounce(() => { intgEstado.acmpBusca = acmpBusca.value; renderAcompanhamento(); }, 120));
  const acmpReload = document.getElementById('btnAcmpReload');
  if (acmpReload) acmpReload.addEventListener('click', () => { intgEstado.acmpCarregado = false; carregarAcompanhamento(); });
  // Exportar o Acompanhamento em Excel: manda os ids que estão NA TELA (busca, chips de situação e
  // treinamento escolhido), na ordem da tabela. O servidor aplica o recorte por empresa e não põe o link.
  // USO: filtrar "Expirados" → Exportar → ACOMPANHAMENTO_TREINAMENTOS.xlsx só com os expirados.
  const acmpExcel = document.getElementById('btnExportAcmp');
  if (acmpExcel) acmpExcel.addEventListener('click', async () => {
    const ids = acmpFiltrados().map(a => a.id);
    if (!ids.length) { toast('Nada para exportar com os filtros atuais.', 'erro'); return; }
    await baixarArquivoAlmox('/api/treinamentos/acompanhamento/exportar', { ids }, 'ACOMPANHAMENTO_TREINAMENTOS.xlsx', acmpExcel);
  });
  // Seletor de treinamento do Acompanhamento — delegação (o host é repintado a cada render).
  const acmpFiltros = document.getElementById('acmpFiltros');
  if (acmpFiltros) {
    acmpFiltros.addEventListener('change', (e) => { const s = e.target.closest('#acmpTreinoSel'); if (s) { intgEstado.acmpTreino = s.value; renderAcompanhamento(); } });
  }
  // Indicadores = filtro de situação (1.55.45). Clique ou Enter/Espaço; o ativo clicado de novo
  // volta para "todos". O foco volta ao mesmo cartão depois do repintar.
  const acmpKpis = document.getElementById('acmpKpis');
  if (acmpKpis) {
    const escolher = (c) => {
      const id = c.dataset.acmpstatus;
      intgEstado.acmpStatus = (id === intgEstado.acmpStatus && id !== 'all') ? 'all' : id;
      renderAcompanhamento();
      const novo = acmpKpis.querySelector(`[data-acmpstatus="${id}"]`); if (novo) novo.focus();
    };
    acmpKpis.addEventListener('click', (e) => { const c = e.target.closest('.v2-kpi-clicavel'); if (c) escolher(c); });
    acmpKpis.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      const c = e.target.closest('.v2-kpi-clicavel'); if (!c) return;
      e.preventDefault(); escolher(c);
    });
  }
  const acmpEnviar = document.getElementById('btnAcmpEnviar');
  if (acmpEnviar) acmpEnviar.addEventListener('click', enviarTreinoDoAcompanhamento);
  // Ações da tabela (delegação): nome/Link abrem o painel do convite, Certificado, Liberar prova,
  // Excluir, Novo convite; clique na área livre da linha seleciona (padrão do Almoxarifado).
  const acmpLista = document.getElementById('acmpLista');
  if (acmpLista) acmpLista.addEventListener('click', (e) => {
    // Certificado apagado (ainda sem aprovação, aria-disabled): não baixa nem seleciona a linha.
    const b = e.target.closest('.acmp-cert'); if (b) { if (b.getAttribute('aria-disabled') !== 'true') baixarCertificadoAcmp(b.dataset.id); return; }
    // Aviso de comentários da linha: abre o painel do convite já na seção Comentários.
    const cm = e.target.closest('.acmp-coment'); if (cm) { abrirDetalheAcmp(cm.dataset.id, cm, { secao: 'comentarios' }); return; }
    const l = e.target.closest('.acmp-link, .acmp-nome-btn'); if (l) { abrirDetalheAcmp(l.dataset.id, l); return; }
    if (e.target.closest('.acmp-limpar')) {
      intgEstado.acmpStatus = 'all'; intgEstado.acmpTreino = 'all'; intgEstado.acmpBusca = '';
      const bb = document.getElementById('acmpBusca'); if (bb) bb.value = '';
      renderAcompanhamento();
      if (bb) bb.focus(); // o botão some no repintar: o foco não pode cair no <body>
      return;
    }
    const lib = e.target.closest('.acmp-liberar'); if (lib) { liberarProvaAcmp(lib.dataset.id); return; }
    const del = e.target.closest('.acmp-del'); if (del) { excluirConvitesAcmp([del.dataset.id]); return; }
    const rep = e.target.closest('.acmp-repetir');
    if (rep) { const a = intgEstado.acmp.find(x => x.id === rep.dataset.id); if (a) repetirTreinoAcmp(a); return; }
    if (e.target.closest('button, input, select, textarea, a')) return;
    const tr = e.target.closest('tr.acmp-selecionavel'); if (!tr || !tr.dataset.id) return;
    if (permissaoAtual('integracao') !== 'editar') return;
    const id = tr.dataset.id;
    if (SELECAO_ACMP.has(id)) SELECAO_ACMP.delete(id); else SELECAO_ACMP.add(id);
    tr.classList.toggle('sel-on', SELECAO_ACMP.has(id));
    tr.setAttribute('aria-selected', String(SELECAO_ACMP.has(id)));
    atualizarSelBarAcmp();
  });
  // Barra de seleção do Acompanhamento: excluir os marcados ou limpar a seleção.
  const selAcmpExcluir = document.getElementById('selBarAcmpExcluir');
  if (selAcmpExcluir) selAcmpExcluir.addEventListener('click', () => excluirConvitesAcmp([...SELECAO_ACMP]));
  const selAcmpLimpar = document.getElementById('selBarAcmpLimpar');
  if (selAcmpLimpar) selAcmpLimpar.addEventListener('click', () => { SELECAO_ACMP.clear(); renderAcompanhamento(); });
  const busca = document.getElementById('intgBusca');
  if (busca) busca.addEventListener('input', debounce(() => { intgEstado.busca = busca.value; renderIntegracao(); }, 120));
  const filtros = document.getElementById('intgFiltros');
  if (filtros) filtros.addEventListener('click', (e) => {
    const chip = e.target.closest('.forn-chip'); if (!chip) return;
    intgEstado.tipo = chip.dataset.tipo; renderIntegracao();
  });
  const cards = document.getElementById('intgCards');
  if (cards) cards.addEventListener('click', async (e) => {
    const lk = e.target.closest('.treino-link'); if (lk) { abrirGerarLinkTreino(lk.dataset.id); return; }
    const acp = e.target.closest('.treino-acompanhar'); if (acp) { acompanharTreino(acp.dataset.id); return; }
    const ed = e.target.closest('.treino-edit'); if (ed) { abrirTreinoModal(ed.dataset.id); return; }
    const del = e.target.closest('.treino-del');
    if (del) {
      const t = TREINAMENTOS.find(x => x.id === del.dataset.id); if (!t) return;
      const ok = await confirmar(`Excluir "${t.titulo}" do catálogo? As aprovações já registradas dos funcionários são mantidas. Esta ação não pode ser desfeita.`, { perigo: true, okTexto: 'Excluir' });
      if (!ok) return;
      const r = await fetch('/api/treinamentos/' + encodeURIComponent(t.id), { method: 'DELETE' });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) { toast(j.erro || 'Erro ao excluir.', 'erro'); return; }
      await carregarIntegracao();
      toast('Treinamento excluído.', 'ok');
    }
  });
})();

// ---- Gerar / compartilhar link público de treinamento (lado RH) ----
// O funcionário abre /treinamento/<token> SEM login e assiste ao vídeo. O link é gerado por
// (funcionário + treinamento), respeitando o acesso por empresa (o servidor valida podeVerFunc).
function urlDoTreinamento(token) { return location.origin + '/treinamento/' + token; }

// Modal de escolha do funcionário. Construído via JS (index.html não muda neste plano);
// reaproveita as classes de modal/form já existentes (.modal-overlay/.modal/.form-grid).
// Gera links de treinamento para UM ou VÁRIOS funcionários (envio em lote). Lista com
// busca + "marcar todos os visíveis"; ao gerar, mostra os links prontos para copiar/WhatsApp.
function abrirGerarLinkTreino(treinoId) {
  const treino = TREINAMENTOS.find(t => t.id === treinoId);
  if (!treino) return;
  const _selTrn = new Set();
  const montar = (funcs) => {
    // Só ATIVOS podem receber treinamento (o servidor também pula desligados).
    const ativos = (funcs || []).filter(f => (f.status || 'Ativo') !== 'Desligado')
      .sort((a, b) => String(a.nome || '').localeCompare(String(b.nome || ''), 'pt-BR'));
    const ov = document.createElement('div');
    ov.className = 'modal-overlay';
    ov.innerHTML = `<div class="modal" style="max-width:560px">
      <div class="modal-head"><h2>Enviar treinamento · ${esc(treino.titulo)}</h2><button class="icon-btn" type="button" data-fechar aria-label="Fechar">✕</button></div>
      <div class="trn-lote-corpo">
        <div class="trn-lote-topo">
          <input type="search" id="trnLoteBusca" class="busca" placeholder="Buscar por nome, cargo ou contrato..." autocomplete="off">
          <label class="trn-lote-dias">Validade (dias)<input type="number" id="trnLoteDias" min="1" max="90" value="7"></label>
        </div>
        <div class="trn-lote-acoes-topo">
          <label class="seg-check"><input type="checkbox" id="trnLoteTodos"> marcar todos os visíveis</label>
          <span id="trnLoteContagem" class="trn-lote-contagem">0 selecionado(s)</span>
        </div>
        <div id="trnLoteLista" class="trn-lote-lista"></div>
      </div>
      <div class="modal-foot">
        <button class="btn btn-ghost" type="button" data-fechar>Cancelar</button>
        <button class="btn btn-primary" type="button" id="trnLoteGerar" disabled>Gerar links</button>
      </div>
    </div>`;
    document.body.appendChild(ov);
    const fechar = () => ov.remove();
    ov.querySelectorAll('[data-fechar]').forEach(b => b.onclick = fechar);
    ov.addEventListener('click', (e) => { if (e.target === ov) fechar(); });
    const lista = ov.querySelector('#trnLoteLista');
    const cont = ov.querySelector('#trnLoteContagem');
    const btnGerar = ov.querySelector('#trnLoteGerar');
    const atualizarContagem = () => {
      cont.textContent = `${_selTrn.size} selecionado(s)`;
      btnGerar.disabled = _selTrn.size === 0;
    };
    const filtrados = () => {
      const q = (ov.querySelector('#trnLoteBusca').value || '').trim().toLowerCase();
      if (!q) return ativos;
      return ativos.filter(f => `${f.nome} ${f.cargo || ''} ${f.contratoNome || ''}`.toLowerCase().includes(q));
    };
    const render = () => {
      const fs = filtrados();
      lista.innerHTML = fs.length ? fs.map(f => `
        <label class="trn-lote-item">
          <input type="checkbox" class="trn-lote-chk" value="${esc(f.id)}"${_selTrn.has(f.id) ? ' checked' : ''}>
          <span class="trn-lote-nome">${esc(f.nome || '(sem nome)')}</span>
          ${f.cargo ? `<span class="trn-lote-cargo">${esc(f.cargo)}</span>` : ''}
        </label>`).join('') : '<p class="seg-hint" style="padding:12px">Nenhum colaborador para o filtro.</p>';
      lista.querySelectorAll('.trn-lote-chk').forEach(c => c.onchange = () => {
        if (c.checked) _selTrn.add(c.value); else _selTrn.delete(c.value);
        atualizarContagem();
        // sincroniza o "todos" com o estado visível
        const vis = [...lista.querySelectorAll('.trn-lote-chk')];
        ov.querySelector('#trnLoteTodos').checked = vis.length > 0 && vis.every(x => x.checked);
      });
    };
    ov.querySelector('#trnLoteBusca').addEventListener('input', debounce(() => { render(); ov.querySelector('#trnLoteTodos').checked = false; }, 120));
    ov.querySelector('#trnLoteTodos').onchange = (e) => {
      filtrados().forEach(f => { if (e.target.checked) _selTrn.add(f.id); else _selTrn.delete(f.id); });
      render(); atualizarContagem();
    };
    render(); atualizarContagem();
    btnGerar.onclick = async () => {
      const funcionarioIds = [..._selTrn];
      if (!funcionarioIds.length) return;
      const dias = Math.min(90, Math.max(1, Number(ov.querySelector('#trnLoteDias').value) || 7));
      btnGerar.disabled = true; const txt = btnGerar.textContent; btnGerar.textContent = 'Gerando…';
      try {
        const r = await fetch('/api/treinamentos/convites/lote', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ treinamentoId: treino.id, funcionarioIds, dias }),
        });
        const d = await r.json().catch(() => ({}));
        if (!r.ok || !d.ok) throw new Error(d.erro || 'Falha ao gerar os links.');
        fechar();
        abrirResultadoLoteTreino(d, treino, dias);
        // Recarrega o Acompanhamento para os novos links já aparecerem no rastreio.
        if (typeof carregarAcompanhamento === 'function') { intgEstado.acmpCarregado = false; carregarAcompanhamento(); }
      } catch (e) { toast(e.message, 'erro'); btnGerar.disabled = false; btnGerar.textContent = txt; }
    };
  };
  if (typeof FUNCIONARIOS !== 'undefined' && FUNCIONARIOS && FUNCIONARIOS.length) montar(FUNCIONARIOS);
  else fetch('/api/funcionarios', { cache: 'no-store' }).then(r => r.ok ? r.json() : [])
    .then(d => { if (Array.isArray(d)) { try { FUNCIONARIOS = d; } catch (e) { /* ignora */ } } montar(Array.isArray(d) ? d : []); })
    .catch(() => montar([]));
}

// ---- Envio do link (Copiar / WhatsApp / E-mail), comum aos modais de link (1.55.35) ----
// Mensagem pronta do convite (WhatsApp e e-mail). Usa só o primeiro nome.
// USO: mensagemConviteTreino({ nome: 'Ana Souza', titulo: 'NR-35', url: 'https://gestao.example.com/treinamento/abc', validadeTs: t })
//      → 'Olá Ana! Assista ao treinamento "NR-35" da Norte Engenharia e faça a prova neste link: https://…/abc\nO link vale até 30/09/2026.'
function mensagemConviteTreino({ nome, titulo, url, validadeTs } = {}) {
  const primeiro = String(nome || '').trim().split(/\s+/)[0] || '';
  return `Olá${primeiro ? ` ${primeiro}` : ''}! Assista ao treinamento "${titulo || 'treinamento'}" da Norte Engenharia e faça a prova neste link: ${url}`
    + (validadeTs ? `\nO link vale até ${acmpData(validadeTs)}.` : '');
}
// Botões de envio de UM link. `desabilitado` (link vencido/cancelado): Copiar desabilitado e os
// links do WhatsApp/E-mail sem href e com aria-disabled (não abrem nada).
// Os cliques de "Copiar" são tratados por delegação em ligarAcoesEnvioTreino(raiz).
// USO: acoesEnvioTreinoHtml('https://…/abc', msg) → '<span class="trn-envio">[Copiar][WhatsApp][E-mail]</span>'
//      acoesEnvioTreinoHtml('https://…/abc', msg, { desabilitado: true }) → os três desabilitados
function acoesEnvioTreinoHtml(url, msg, { desabilitado = false } = {}) {
  if (desabilitado || !url) {
    return `<span class="trn-envio trn-envio-off">
      <button type="button" class="btn btn-ghost small trn-envio-copiar" disabled>Copiar</button>
      <a class="btn btn-ghost small" role="link" aria-disabled="true">WhatsApp</a>
      <a class="btn btn-ghost small" role="link" aria-disabled="true">E-mail</a>
    </span>`;
  }
  const assunto = 'Treinamento · Norte Engenharia';
  return `<span class="trn-envio">
      <button type="button" class="btn btn-ghost small trn-envio-copiar" data-url="${esc(url)}" title="Copiar o link">Copiar</button>
      <a class="btn btn-ghost small" href="https://wa.me/?text=${encodeURIComponent(msg)}" target="_blank" rel="noopener" title="Abrir o WhatsApp com a mensagem pronta">WhatsApp</a>
      <a class="btn btn-ghost small" href="mailto:?subject=${encodeURIComponent(assunto)}&amp;body=${encodeURIComponent(msg)}" title="Abrir o e-mail com a mensagem pronta">E-mail</a>
    </span>`;
}
// Copia um texto (com o plano B do execCommand para navegador sem clipboard assíncrono).
// USO: await copiarTextoTreino('https://…/abc') → toast "Link copiado."
//      await copiarTextoTreino(lista, 'Links copiados.')
async function copiarTextoTreino(texto, aviso = 'Link copiado.') {
  try { await navigator.clipboard.writeText(texto); toast(aviso, 'ok'); return; } catch (e) { /* plano B abaixo */ }
  const ta = document.createElement('textarea');
  ta.value = texto; ta.setAttribute('readonly', ''); ta.className = 'sr-only';
  document.body.appendChild(ta); ta.select();
  let ok = false;
  try { ok = document.execCommand('copy'); } catch (e) { ok = false; }
  ta.remove();
  toast(ok ? aviso : 'Não consegui copiar. Selecione o link e copie manualmente.', ok ? 'ok' : 'erro');
}
// Liga (uma vez, por delegação) os botões "Copiar" gerados por acoesEnvioTreinoHtml dentro de `raiz`.
// USO: ligarAcoesEnvioTreino(overlayDoModal)
function ligarAcoesEnvioTreino(raiz) {
  raiz.addEventListener('click', (e) => {
    const b = e.target.closest('.trn-envio-copiar');
    if (b && !b.disabled && b.dataset.url) copiarTextoTreino(b.dataset.url);
    const off = e.target.closest('.trn-envio a[aria-disabled="true"]');
    if (off) e.preventDefault();
  });
}
// Monta o casco de um modal da Integração (overlay no body, Esc e clique fora fecham).
// O Esc passa pelo handler global (registro em _modalFechar pelo id do overlay): ele fecha só o
// overlay do topo e ignora o Esc quando a confirmação (#confirmModal) está aberta por cima.
// `lateral: true` (1.55.45) abre como PAINEL à direita, na altura toda (variante .modal-lateral do
// 08-modal.css), para ver o detalhe de uma linha sem perder a lista de vista. `aoFechar` roda depois
// de fechar por qualquer caminho (X, Fechar, Esc, clique fora ou o `fechar()` devolvido).
// USO: const { ov, fechar } = abrirModalTrn('Link do treinamento', '<div class="…">…</div>', { largura: 520 })
//      abrirModalTrn('Ana Souza', corpo, { largura: 540, lateral: true, aoFechar: () => botao.focus() })
let _modalTrnSeq = 0;
function abrirModalTrn(titulo, corpoHtml, { largura = 520, rodape = '<button class="btn" type="button" data-fechar>Fechar</button>', lateral = false, aoFechar = null } = {}) {
  const ov = document.createElement('div');
  ov.className = 'modal-overlay' + (lateral ? ' modal-lateral' : '');
  ov.id = 'trnModal' + (++_modalTrnSeq);
  const idTit = 'trnModalTit' + Date.now().toString(36) + _modalTrnSeq;
  ov.innerHTML = `<div class="modal" role="dialog" aria-modal="true" aria-labelledby="${idTit}" style="max-width:${Number(largura) || 520}px">
    <div class="modal-head"><h2 id="${idTit}">${esc(titulo)}</h2><button class="icon-btn" type="button" data-fechar aria-label="Fechar">✕</button></div>
    ${corpoHtml}
    <div class="modal-foot">${rodape}</div>
  </div>`;
  document.body.appendChild(ov);
  let fechado = false;
  const fechar = () => {
    if (fechado) return;
    fechado = true;
    delete _modalFechar[ov.id]; ov.remove();
    if (typeof aoFechar === 'function') aoFechar();
  };
  _modalFechar[ov.id] = fechar;
  ov.querySelectorAll('[data-fechar]').forEach(b => b.onclick = fechar);
  ov.addEventListener('click', (e) => { if (e.target === ov) fechar(); });
  return { ov, fechar };
}
// Gera um link NOVO para um convite (token e prazo novos; o link antigo para de funcionar).
// Atualiza a linha do Acompanhamento na hora e recarrega em segundo plano (sem piscar).
// USO: const novo = await regenerarLinkTreino('cv_1', 15)
//      → POST /api/treinamentos/convites/cv_1/regenerar { dias:15 } → { …convite, token, validadeTs, regeracoes }
//      → null em erro (já avisado por toast; 409 = já concluído)
async function regenerarLinkTreino(conviteId, dias) {
  try {
    const r = await fetch('/api/treinamentos/convites/' + encodeURIComponent(conviteId) + '/regenerar', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ dias }),
    });
    const d = await r.json().catch(() => ({}));
    if (!r.ok || !d.ok || !d.convite) {
      toast(d.erro || 'Não foi possível gerar um novo link.', 'erro');
      carregarAcompanhamento();
      return null;
    }
    const a = intgEstado.acmp.find(x => x.id === d.convite.id);
    if (a) {
      const c = d.convite;
      Object.assign(a, { token: c.token, validadeTs: c.validadeTs, status: c.status, regeradoTs: c.regeradoTs, regeradoPor: c.regeradoPor, regeracoes: c.regeracoes });
      renderAcompanhamento();
    }
    carregarAcompanhamento();
    return d.convite;
  } catch (e) {
    toast('Não foi possível gerar um novo link. Verifique a conexão.', 'erro');
    return null;
  }
}
// Validade (dias) digitada: inteiro de 1 a 90; vazio/inválido cai no padrão de 7.
// USO: diasValidadeTrn('15') → 15 · diasValidadeTrn('200') → 90 · diasValidadeTrn('') → 7
function diasValidadeTrn(v) {
  const n = Math.round(Number(v));
  if (!Number.isFinite(n) || n <= 0) return 7;
  return Math.min(90, Math.max(1, n));
}

// Resultado do envio em lote: "Links do treinamento", em três seções:
//   · Links novos (N): os criados agora;
//   · Já tinham link ativo (N): quem já tinha um link aguardando (o servidor devolve esse link em
//     ignorados[].convite); dá para reenviar ou "Gerar novo link" com os mesmos `dias`;
//   · Não enviados (N): desligado, sem acesso à empresa, não encontrado (sem link nenhum).
// "Copiar todos" = novos + ativos, com a data real de validade de cada um.
// USO: abrirResultadoLoteTreino({ criados:[{ id, nome, token, validadeTs }], ignorados:[{ nome:'Bia', motivo:'já tem link ativo', convite:{ id, token, validadeTs } }] }, treino, 7)
function abrirResultadoLoteTreino(d, treino, dias = 7) {
  const titulo = (treino && treino.titulo) || d.treinamento || 'treinamento';
  const podeEditar = permissaoAtual('integracao') === 'editar';
  const novos = (d.criados || []).filter(c => c && c.token).map(c => ({ id: c.id, nome: c.nome, token: c.token, validadeTs: c.validadeTs }));
  const ativos = (d.ignorados || []).filter(i => i && i.convite && i.convite.token)
    .map(i => ({ id: i.convite.id, nome: i.nome, token: i.convite.token, validadeTs: i.convite.validadeTs }));
  const outros = (d.ignorados || []).filter(i => !(i && i.convite && i.convite.token));
  const MOTIVO = { 'não encontrado': 'não encontrado no cadastro', 'sem acesso à empresa': 'sem acesso à empresa deste colaborador', desligado: 'colaborador desligado' };
  const linha = (c, ativo) => {
    const url = urlDoTreinamento(c.token);
    const msg = mensagemConviteTreino({ nome: c.nome, titulo, url, validadeTs: c.validadeTs });
    const nome = c.nome || 'colaborador';
    return `<div class="trn-res-linha" data-id="${esc(c.id)}">
      <div class="trn-res-info">
        <span class="trn-res-topo"><b>${esc(nome)}</b>${c.validadeTs ? `<span class="trn-res-validade">Válido até ${esc(acmpData(c.validadeTs))}</span>` : ''}</span>
        <input type="text" class="trn-res-url" readonly value="${esc(url)}" aria-label="Link de ${esc(nome)}">
      </div>
      <div class="trn-res-acoes">${acoesEnvioTreinoHtml(url, msg)}${ativo && podeEditar
        ? `<button type="button" class="btn btn-ghost small trn-res-regerar" data-id="${esc(c.id)}" title="Gerar um link novo para ${esc(nome)}, válido por ${dias} ${plural(dias, 'dia', 'dias')}; o atual para de funcionar">${ICONE_SUBSTITUIR}<span>Gerar novo link</span></button>`
        : ''}</div>
    </div>`;
  };
  const secao = (rot, n, html, dica = '') => n
    ? `<section class="trn-res-secao"><h3>${esc(rot)} (${n})</h3>${dica ? `<p class="trn-res-dica">${esc(dica)}</p>` : ''}${html}</section>`
    : '';
  const total = novos.length + ativos.length;
  const resumo = [
    `${novos.length} ${plural(novos.length, 'link novo', 'links novos')}`,
    ativos.length ? `${ativos.length} já ${plural(ativos.length, 'tinha', 'tinham')} link ativo` : '',
    outros.length ? `${outros.length} não ${plural(outros.length, 'enviado', 'enviados')}` : '',
  ].filter(Boolean).join(' · ');
  const corpo = `<div class="trn-lote-corpo trn-res">
      <div class="trn-res-barra">
        <p class="trn-res-resumo"><b>${esc(titulo)}</b><span>${esc(resumo)}</span></p>
        ${total ? `<button class="btn btn-ghost small" type="button" data-copiar-todos>${ICONE_COPIAR_TRN}<span>Copiar todos</span></button>` : ''}
      </div>
      ${secao('Links novos', novos.length, `<div class="trn-res-lista">${novos.map(c => linha(c, false)).join('')}</div>`)}
      ${secao('Já tinham link ativo', ativos.length, `<div class="trn-res-lista">${ativos.map(c => linha(c, true)).join('')}</div>`,
        'Não foi criado um link novo para quem já tinha um válido deste treinamento. Reenvie o link atual ou gere um novo.')}
      ${secao('Não enviados', outros.length, `<ul class="trn-res-nao">${outros.map(i => `<li><b>${esc(i.nome || i.funcionarioId || 'colaborador')}</b><span>${esc(MOTIVO[i.motivo] || i.motivo || 'não enviado')}</span></li>`).join('')}</ul>`)}
      ${!total && !outros.length ? '<p class="seg-hint">Nenhum link foi criado.</p>' : ''}
    </div>`;
  const { ov } = abrirModalTrn('Links do treinamento', corpo, { largura: 680 });
  ligarAcoesEnvioTreino(ov);
  ov.addEventListener('click', async (e) => {
    if (e.target.closest('[data-copiar-todos]')) {
      const todos = novos.concat(ativos).map(c => `${c.nome || 'colaborador'}: ${urlDoTreinamento(c.token)}${c.validadeTs ? ` (válido até ${acmpData(c.validadeTs)})` : ''}`);
      copiarTextoTreino(todos.join('\n'), `${todos.length} ${plural(todos.length, 'link copiado', 'links copiados')}.`);
      return;
    }
    const rg = e.target.closest('.trn-res-regerar');
    if (!rg) return;
    const c = ativos.find(x => x.id === rg.dataset.id);
    if (!c) return;
    const ok = await confirmar(`Gerar um novo link para ${c.nome || 'o colaborador'}, válido por ${dias} ${plural(dias, 'dia', 'dias')}? O link atual para de funcionar na hora.`, { okTexto: 'Gerar novo link' });
    if (!ok) return;
    rg.disabled = true;
    const novo = await regenerarLinkTreino(c.id, dias);
    if (!novo) { rg.disabled = false; return; }
    Object.assign(c, { token: novo.token, validadeTs: novo.validadeTs });
    const el = ov.querySelector(`.trn-res-linha[data-id="${CSS.escape(c.id)}"]`);
    if (el) el.outerHTML = linha(c, true);
    toast(`Novo link gerado para ${c.nome || 'o colaborador'}, válido até ${acmpData(novo.validadeTs)}.`, 'ok');
  });
}

// ---- Painel do convite (1.55.45), no lugar do modal "Link do treinamento" ----
// Painel lateral (abrirModalTrn com `lateral: true`) aberto pelo nome, pelo botão Link e pelos
// avisos da faixa "precisam de atenção" do Acompanhamento. Reúne num lugar só:
//   · cabeçalho: treinamento, CPF informado, situação e origem do vídeo;
//   · Link: endereço + Copiar/WhatsApp/E-mail (desligados com o link vencido/cancelado), validade,
//     histórico e, para quem edita, "Gerar novo link" com a validade em dias (não concluído) ou
//     "Novo convite (repetir treinamento)" (concluído);
//   · Andamento: as 5 etapas com as datas (envio e novos links, acessos, vídeo, cada tentativa da
//     prova, aprovação e validade do certificado), "Liberar prova sem o vídeo" no vídeo travado
//     pendente e "Baixar certificado" (apagado, com aria-disabled, até a aprovação);
//   · rodapé: "Excluir convite" (quem edita, não concluído) e Fechar.
// Quem só vê a Integração vê tudo, sem nenhum botão de edição.
// Acompanha a lista: renderAcompanhamento() chama sincronizar(), que repinta com o registro novo
// (novo link, prova liberada) ou fecha o painel se o convite sumiu (excluído). Ao fechar, o foco
// volta para quem abriu (ou para o nome da mesma linha, se a tabela foi repintada).
// Comentários do colaborador (1.55.43) viram a última seção, do mais novo para o mais antigo;
// `{ secao: 'comentarios' }` (aviso de comentários da linha) abre o painel já nela.
// USO: abrirDetalheAcmp('cv_1a2b3c')             → painel à direita com o link e o andamento
//      abrirDetalheAcmp('cv_1a2b3c', botaoLink)   → idem; ao fechar, o foco volta para botaoLink
//      abrirDetalheAcmp('cv_1a2b3c', aviso, { secao: 'comentarios' }) → rola até "Comentários" e põe o foco nela
function abrirDetalheAcmp(conviteId, gatilho, opcoes = {}) {
  const a0 = (intgEstado.acmp || []).find(x => x.id === conviteId);
  if (!a0) return;
  if (_detalheAcmp) _detalheAcmp.fechar();
  const podeEditar = permissaoAtual('integracao') === 'editar';
  // Guardado agora: a faixa é repintada a cada render e o botão dela sai do documento.
  const veioDaFaixa = !!(gatilho && gatilho.closest && gatilho.closest('#acmpAlerta'));
  let c = { ...a0 };
  let diasSel = 7;
  const { ov, fechar } = abrirModalTrn(c.nome || 'Colaborador', '<div class="trn-det-corpo"></div>', {
    largura: 540, lateral: true, rodape: '',
    // Para onde o foco volta, na ordem: quem abriu (se ainda existe) → o "Ver N convites" da faixa
    // (se abriu por ela; a faixa é repintada e o item some) → o nome da mesma linha → o indicador
    // ativo → a busca. A linha pode ter saído da tela (novo link tirou o convite do filtro
    // "Expirados", convite excluído…).
    aoFechar: () => {
      if (_detalheAcmp && _detalheAcmp.id === conviteId) _detalheAcmp = null;
      const alvo = [
        gatilho && document.contains(gatilho) ? gatilho : null,
        veioDaFaixa ? document.querySelector('#acmpAlerta:not([hidden]) .ds-alert-action') : null,
        document.querySelector(`#acmpLista .acmp-nome-btn[data-id="${CSS.escape(conviteId)}"]`),
        document.querySelector('#acmpKpis .v2-kpi-clicavel.ativo'),
        document.getElementById('acmpBusca'),
      ].find(Boolean);
      if (alvo) alvo.focus();
    },
  });
  const corpo = ov.querySelector('.trn-det-corpo');
  const pe = ov.querySelector('.modal-foot');
  const tit = ov.querySelector('.modal-head h2');
  ligarAcoesEnvioTreino(ov);
  const pintar = () => {
    const treino = TREINAMENTOS.find(t => t.id === c.treinamentoId);
    const titulo = (treino && treino.titulo) || c.treino || 'treinamento';
    const concl = acmpConcluido(c);
    const status = concl ? 'concluido' : (c.status || 'aguardando');
    const vencido = !concl && (status === 'expirado' || status === 'cancelado');
    const st = ACMP_STATUS[status] || { rot: status, cls: 't-pendente' };
    const url = c.token ? urlDoTreinamento(c.token) : '';
    const msg = mensagemConviteTreino({ nome: c.nome, titulo, url, validadeTs: c.validadeTs });
    const v = c.video && typeof c.video === 'object' ? c.video : null;
    const abriu = acmpAbriu(c);
    const provas = Array.isArray(c.provas) ? c.provas : [];
    const { passos, alcancadas } = acmpEtapas(c);
    if (tit) tit.textContent = c.nome || 'Colaborador';

    // Cabeçalho
    const origem = c.origemVideo === 'arquivo' || v
      ? `<span class="acmp-origem">${ICONE_VIDEO_TRN}<span>Vídeo travado</span></span>`
      : c.origemVideo === 'drive' ? `<span class="acmp-origem">${ICONE_DRIVE_TRN}<span>Drive, sem trava</span></span>` : '';
    const cab = `<div class="trn-det-cab">
        <div class="trn-det-sub">${esc(titulo)}${c.acessoCpf ? ` · CPF ${esc(cpfCrachaMasc(c.acessoCpf))}` : ''}</div>
        <div class="trn-det-selos"><span class="treino-status ${st.cls}">${esc(st.rot)}</span> ${origem}</div>
      </div>`;

    // Link
    let validade = '';
    if (concl) validade = `Concluído${c.concluidoTs ? ` em ${acmpData(c.concluidoTs)}` : ''}${c.ultimaNota != null ? ` com nota ${c.ultimaNota}%` : ''}.`;
    else if (status === 'cancelado') validade = 'Este convite foi cancelado. Gere um novo link para reenviar.';
    else if (vencido) validade = `Este link venceu${c.validadeTs ? ` em ${acmpData(c.validadeTs)}` : ''}. Gere um novo link para reenviar.`;
    else if (c.validadeTs) {
      const dias = acmpDiasAte(c.validadeTs);
      validade = `Válido até ${acmpDataHora(c.validadeTs)} (${dias <= 0 ? 'vence hoje' : dias === 1 ? 'falta 1 dia' : `faltam ${dias} dias`}).`;
    }
    let edicao = '';
    if (podeEditar && !concl) {
      edicao = `<div class="full trn-regerar-linha">
          <label class="trn-lote-dias">Validade (dias)<input type="number" class="trn-regerar-dias" min="1" max="90" step="1" value="${diasSel}" inputmode="numeric"></label>
          <button type="button" class="btn ${vencido ? 'btn-primary' : 'btn-ghost'} trn-regerar">${ICONE_SUBSTITUIR}<span>Gerar novo link</span></button>
        </div>
        <p class="full dica trn-regerar-nota">O novo link vale a partir de agora pelo número de dias escolhido; o link atual para de funcionar na hora.</p>`;
    } else if (podeEditar && concl) {
      edicao = `<div class="full trn-regerar-linha">
          <button type="button" class="btn btn-ghost trn-repetir">${ICONE_REPETIR}<span>Novo convite (repetir treinamento)</span></button>
        </div>
        <p class="full dica trn-regerar-nota">A conclusão atual e o certificado continuam guardados; o novo convite gera um registro novo.</p>`;
    }
    const secLink = `<section class="trn-det-secao" aria-labelledby="${ov.id}-link">
        <h3 id="${ov.id}-link">Link do treinamento</h3>
        <div class="form-grid trn-det-link">
          ${url ? `<label class="full">Endereço do link
            <input type="text" class="trn-link-url${vencido ? ' vencido' : ''}" readonly value="${esc(url)}">
          </label>` : '<p class="full trn-validade vencido">Este convite não tem link. Envie o treinamento de novo.</p>'}
          ${validade ? `<p class="full trn-validade${vencido ? ' vencido' : ''}">${esc(validade)}</p>` : ''}
          <div class="full">${acoesEnvioTreinoHtml(url, msg, { desabilitado: vencido })}</div>
          ${edicao}
        </div>
      </section>`;

    // Andamento: as 5 etapas com as datas
    // <p> (bloco): no celular, sem o CSS da camada nova, cada linha continua separada da outra.
    const info = (linhas) => linhas.filter(Boolean).map(t => `<p class="trn-det-info">${esc(t)}</p>`).join('');
    const nReg = Number(c.regeracoes) || 0;
    const nAc = Number(c.acessos) || 0;
    const primeiro = c.acessadoTs || c.ultimoAcessoTs;
    const ultimoAc = c.ultimoAcessoTs || c.acessadoTs;
    const infoEnvio = info([
      c.geradoTs ? `Em ${acmpDataHora(c.geradoTs)}${c.criadoPor ? ` por ${c.criadoPor}` : ''}.` : '',
      nReg ? `Novo link ${nReg}×; o último em ${acmpDataHora(c.regeradoTs)}${c.regeradoPor ? ` por ${c.regeradoPor}` : ''}.` : '',
    ]);
    const infoAcesso = info(primeiro ? [
      `Primeira vez em ${acmpDataHora(primeiro)}${c.acessoCpf ? `, com o CPF ${cpfCrachaMasc(c.acessoCpf)}` : ''}.`,
      nAc > 1 ? `${nAc} acessos; o último em ${acmpDataHora(ultimoAc)}.` : '',
    ] : [abriu ? 'Abriu o link.' : status === 'expirado' ? 'Não abriu o link antes de ele vencer.' : 'Ainda não abriu o link.']);
    let infoVideo;
    if (!v) {
      infoVideo = info([c.origemVideo === 'drive'
        ? 'Vídeo pelo Google Drive, sem trava: não dá para saber se foi assistido até o fim.'
        : 'Sem registro do vídeo.']);
    } else {
      infoVideo = info([
        v.concluidoTs ? `Assistiu até o fim em ${acmpDataHora(v.concluidoTs)}${v.iniciadoTs ? ` (começou em ${acmpDataHoraCurta(v.iniciadoTs)})` : ''}, sem adiantar nem acelerar.`
          : v.liberadoTs ? `Prova liberada sem o vídeo terminar${v.liberadoPor ? ` por ${v.liberadoPor}` : ''} em ${acmpDataHora(v.liberadoTs)}.`
          : v.iniciadoTs ? `Começou a assistir em ${acmpDataHora(v.iniciadoTs)}; a prova abre quando o vídeo terminar.`
          : concl ? 'Aprovado antes de o vídeo ser travado.' : 'Ainda não começou o vídeo.',
        v.duracaoSeg ? `O vídeo tem ${fmtDuracaoVideo(v.duracaoSeg)}.` : '',
      ]);
    }
    const btnLiberar = podeEditar && botaoLiberarProvaAcmp(c, true)
      ? `<button type="button" class="btn btn-ghost small trn-det-liberar">${ICONE_LIBERAR_TRN}<span>Liberar prova sem o vídeo</span></button>` : '';
    const infoProva = provas.length
      ? `<ol class="trn-det-provas">${provas.map((p, i) => `<li><span>${i + 1}ª tentativa: <b>${esc(String(p.nota))}%</b> em ${esc(acmpDataHora(p.ts))}</span>`
          + `<span class="${p.aprovado ? 'acmp-tom-ok' : 'acmp-tom-perigo'}">${p.aprovado ? 'aprovado' : 'reprovado'}</span></li>`).join('')}</ol>`
      : info([vencido ? 'Nenhuma tentativa antes de o link vencer.' : (v && v.pendente) ? 'A prova abre quando o vídeo terminar.' : 'Nenhuma tentativa ainda.']);
    const ate = acmpCertificadoAte(c);
    const infoAprov = info(concl ? [
      `Aprovado${c.concluidoTs ? ` em ${acmpDataHora(c.concluidoTs)}` : ''}${c.ultimaNota != null ? ` com ${c.ultimaNota}%` : ''}.`,
      ate ? `Certificado válido até ${ate}.` : ate === '' ? 'Certificado sem vencimento.' : '',
    ] : ['O certificado fica disponível aqui quando o colaborador for aprovado na prova.']);
    const btnCert = concl && c.concluidoTs
      ? `<button type="button" class="btn btn-ghost small trn-det-cert">${ICONE_PDF}<span>Baixar certificado</span></button>`
      : `<button type="button" class="btn btn-ghost small trn-det-cert" aria-disabled="true" title="O certificado fica disponível depois da aprovação na prova">${ICONE_PDF}<span>Baixar certificado</span></button>`;
    const etapas = [
      { tit: 'Link enviado', html: infoEnvio },
      { tit: 'Abriu o link', html: infoAcesso },
      { tit: 'Vídeo', html: infoVideo + btnLiberar },
      { tit: 'Prova', html: infoProva },
      { tit: 'Aprovado e certificado', html: infoAprov + btnCert },
    ];
    const secAndamento = `<section class="trn-det-secao" aria-labelledby="${ov.id}-and">
        <h3 id="${ov.id}-and">Andamento</h3>
        <ol class="trn-det-linha">${etapas.map((e, i) => `<li class="trn-det-etapa ${passos[i]}${alcancadas[i] ? ' alcancada' : ''}">
            <span class="acmp-passo ${passos[i]}" aria-hidden="true"></span>
            <div class="trn-det-etapa-txt"><strong>${esc(e.tit)}<span class="sr-only"> (${esc(ACMP_PASSO_DESC[passos[i]])})</span></strong>${e.html}</div>
          </li>`).join('')}</ol>
      </section>`;

    // Comentários do colaborador sobre o treinamento (só leitura; mais novo primeiro).
    const coms = acmpComentarios(c).slice().sort((x, y) => (y.ts || 0) - (x.ts || 0));
    const secComent = coms.length ? `<section class="trn-det-secao" aria-labelledby="${ov.id}-com">
        <h3 id="${ov.id}-com" tabindex="-1">Comentários sobre o treinamento</h3>
        <ul class="acmp-coment-lista">${coms.map(k => `<li class="acmp-coment-item">
            <div class="acmp-coment-cab">
              <span class="treino-status ${k.avaliacao === 'problema' ? 't-reprovado' : 't-aprovado'}">${k.avaliacao === 'problema' ? 'Tem problema' : 'Está OK'}</span>
              <span class="trn-det-info">${esc(acmpDataHora(k.ts))}</span>
            </div>
            ${k.texto ? `<p class="acmp-coment-txt">${esc(k.texto)}</p>` : '<p class="trn-det-info">Sem texto.</p>'}
          </li>`).join('')}</ul>
      </section>` : '';

    corpo.innerHTML = cab + secLink + secAndamento + secComent;
    const inp = corpo.querySelector('.trn-regerar-dias');
    if (inp) inp.addEventListener('change', () => { diasSel = diasValidadeTrn(inp.value); inp.value = diasSel; });
    if (pe) {
      pe.innerHTML = (podeEditar && !concl ? `<button type="button" class="btn btn-ghost trn-det-excluir">${ICONE_LIXEIRA}<span>Excluir convite</span></button>` : '')
        + '<button class="btn" type="button" data-fechar>Fechar</button>';
    }
  };
  pintar();
  const focarPrimeiro = () => {
    const f = corpo.querySelector('.trn-envio-copiar:not([disabled])') || corpo.querySelector('.trn-regerar') || ov.querySelector('[data-fechar]');
    if (f) f.focus();
  };
  // Repinta só quando o registro mudou (não perde o que está sendo digitado à toa) e devolve o foco
  // para dentro do painel se o elemento focado sumiu no repintar (ou se ele já estava no <body>,
  // que é onde a confirmação deixa o foco ao fechar).
  const sincronizar = () => {
    const novo = (intgEstado.acmp || []).find(x => x.id === conviteId);
    if (!novo) { fechar(); return; }
    if (JSON.stringify(novo) === JSON.stringify(c)) return;
    const tinhaFoco = ov.contains(document.activeElement) || document.activeElement === document.body;
    c = { ...novo };
    pintar();
    if (tinhaFoco && document.contains(ov) && !ov.contains(document.activeElement)) focarPrimeiro();
  };
  _detalheAcmp = { id: conviteId, sincronizar, fechar };
  // Depois de uma confirmação (aceita ou cancelada) o foco volta ao botão que a abriu, se ele ainda
  // existe; se o repintar o trocou, vai para o primeiro controle do painel. Painel já fechado: nada.
  const devolverFoco = (btn) => {
    if (!document.contains(ov)) return;
    if (btn && document.contains(btn)) btn.focus(); else focarPrimeiro();
  };
  ov.addEventListener('click', async (e) => {
    if (e.target.closest('.modal-foot [data-fechar]')) { fechar(); return; }
    const rg = e.target.closest('.trn-regerar');
    if (rg) {
      const inp = corpo.querySelector('.trn-regerar-dias');
      diasSel = diasValidadeTrn(inp ? inp.value : 7);
      if (inp) inp.value = diasSel;
      const ok = await confirmar(`Gerar um novo link para ${c.nome || 'o colaborador'}, válido por ${diasSel} ${plural(diasSel, 'dia', 'dias')}? O link atual para de funcionar na hora.`, { okTexto: 'Gerar novo link' });
      if (!ok) { devolverFoco(rg); return; }
      rg.disabled = true;
      const novo = await regenerarLinkTreino(c.id, diasSel);
      if (!novo) { rg.disabled = false; devolverFoco(rg); return; }
      // O convite do servidor não traz os campos calculados do Acompanhamento (geradoTs, nota…): mescla.
      c = { ...c, token: novo.token, validadeTs: novo.validadeTs, status: novo.status || 'aguardando', regeradoTs: novo.regeradoTs, regeradoPor: novo.regeradoPor, regeracoes: novo.regeracoes };
      pintar();
      toast(`Novo link gerado, válido até ${acmpData(novo.validadeTs)}.`, 'ok');
      focarPrimeiro();
      return;
    }
    const rep = e.target.closest('.trn-repetir');
    if (rep) { await repetirTreinoAcmp(c, fechar); devolverFoco(rep); return; }
    const lib = e.target.closest('.trn-det-liberar');
    if (lib) { await liberarProvaAcmp(c.id); devolverFoco(lib); return; }
    const cert = e.target.closest('.trn-det-cert');
    if (cert) { if (cert.getAttribute('aria-disabled') !== 'true') baixarCertificadoAcmp(c.id); return; }
    const exc = e.target.closest('.trn-det-excluir');
    if (exc) { await excluirConvitesAcmp([c.id]); devolverFoco(exc); return; }
  });
  const tituloComent = opcoes.secao === 'comentarios' && corpo.querySelector(`#${ov.id}-com`);
  if (tituloComent) { tituloComent.scrollIntoView({ block: 'start' }); tituloComent.focus(); }
  else focarPrimeiro();
}

// ---- Modal de cadastro/edição (com editor de prova) ----
let editandoTreinoId = null;
let _treinoQSeq = 0;
const formTreino = document.getElementById('formTreino');
// Estado do bloco "Vídeo" do modal (1.55.41). `atual` = vídeo salvo no treinamento (vem do GET
// ?editar=1); `novo` = o que acabou de subir (resposta do /concluir), ainda não salvo;
// `removido` = o RH clicou "Remover vídeo" no atual; `enviando` = controle do envio em curso
// (null quando parado). `arquivoLocal`/`urlLocal` servem só à prévia do `novo` sem ida ao servidor;
// `config` = GET /api/treinamentos/videos/config; `tocouOrigem` = o RH já escolheu a origem.
// Ex.: depois de subir NR-35.mp4 → { atual: null, novo: { chave: 'videos-treino/2026/<32hex>.mp4',
//      nome: 'NR-35.mp4', bytes: 52428800, mime: 'video/mp4', duracaoSeg: 612, enviadoTs, enviadoPor },
//      removido: false, enviando: null, … }
const videoTreinoWork = { atual: null, novo: null, removido: false, enviando: null, arquivoLocal: null, urlLocal: '', config: null, tocouOrigem: false };
// Sobe a cada abertura do modal: respostas atrasadas de uma abertura anterior são ignoradas.
let _videoTreinoSeq = 0;
function _treinoMontarAlternativa(qEl, alt, marcada) {
  const grupo = qEl.dataset.qid;
  const aid = (alt && alt.id) || ('a' + (++_treinoQSeq));
  const div = document.createElement('div');
  div.className = 'treino-alt';
  div.dataset.aid = aid;
  div.innerHTML = `<input type="radio" name="correta-${grupo}" value="${esc(aid)}" title="Marcar como correta"${marcada ? ' checked' : ''} />`
    + `<input type="text" class="treino-alt-txt" maxlength="600" placeholder="Texto da alternativa" />`
    + `<button type="button" class="treino-alt-del icon-btn" title="Remover alternativa" aria-label="Remover alternativa">✕</button>`;
  div.querySelector('.treino-alt-txt').value = (alt && alt.texto) || '';
  qEl.querySelector('.treino-alts').appendChild(div);
}
function _treinoMontarQuestao(q) {
  const host = document.getElementById('treinoQuestoes');
  const qid = 'q' + (++_treinoQSeq);
  const qEl = document.createElement('div');
  qEl.className = 'treino-questao';
  qEl.dataset.qid = qid;
  qEl.innerHTML = `<div class="treino-questao-top">
      <span class="treino-qnum"></span>
      <button type="button" class="treino-q-del icon-btn" title="Remover questão" aria-label="Remover questão">✕</button>
    </div>
    <input type="text" class="treino-q-enun" maxlength="1000" placeholder="Enunciado da questão" />
    <div class="treino-alts"></div>
    <button type="button" class="treino-add-alt btn btn-ghost small">+ Alternativa</button>`;
  host.appendChild(qEl);
  qEl.querySelector('.treino-q-enun').value = (q && q.enunciado) || '';
  const alts = (q && Array.isArray(q.alternativas) && q.alternativas.length) ? q.alternativas : [null, null];
  alts.forEach(a => _treinoMontarAlternativa(qEl, a, !!(a && q && a.id === q.correta)));
  _treinoRenumerar();
  return qEl;
}
function _treinoRenumerar() {
  document.querySelectorAll('#treinoQuestoes .treino-questao').forEach((qEl, i) => {
    const n = qEl.querySelector('.treino-qnum'); if (n) n.textContent = 'Questão ' + (i + 1);
  });
}
function abrirTreinoModal(id) {
  editandoTreinoId = id || null;
  formTreino.reset();
  resetarVideoTreino(); // bloco "Vídeo": estado limpo + consulta o armazenamento (GET videos/config)
  document.getElementById('treinoQuestoes').innerHTML = '';
  document.getElementById('treinoTitulo').textContent = id ? 'Editar treinamento' : 'Novo treinamento';
  if (id) {
    const seq = _videoTreinoSeq;
    // Busca o detalhe COM gabarito (caminho de edição gated no servidor).
    fetch('/api/treinamentos/' + encodeURIComponent(id) + '?editar=1', { cache: 'no-store' })
      .then(r => r.ok ? r.json() : Promise.reject(r))
      .then(t => {
        if (seq !== _videoTreinoSeq) return; // o modal foi fechado/reaberto no meio
        formTreino.elements['titulo'].value = t.titulo || '';
        formTreino.elements['tipo'].value = t.tipo === 'curso' ? 'curso' : 'NR';
        formTreino.elements['validadeMeses'].value = Number(t.validadeMeses) || 0;
        formTreino.elements['fileId'].value = t.fileId || '';
        formTreino.elements['descricao'].value = t.descricao || '';
        aplicarVideoDoTreino(t);
        syncCustomSelects();
        (t.questoes && t.questoes.length ? t.questoes : [null]).forEach(q => _treinoMontarQuestao(q));
      })
      .catch(() => toast('Não foi possível abrir o treinamento para edição.', 'erro'));
  } else {
    _treinoMontarQuestao(null); // começa com 1 questão em branco
  }
  document.getElementById('treinoModal').hidden = false;
  setTimeout(() => { syncCustomSelects(); formTreino.elements['titulo'] && formTreino.elements['titulo'].focus(); }, 30);
}
// Fechar pelo X, "Cancelar", Esc ou clique no fundo (1.55.41): com vídeo SUBINDO pede
// confirmação e, se confirmado, cancela o envio (DELETE videos/upload); com vídeo enviado e
// ainda não salvo, avisa que ele não fica no treinamento. Depois de salvar usa-se
// ocultarTreinoModal(), que fecha direto.
// USO: fecharTreinoModal() → (durante o envio) "O vídeo ainda está sendo enviado…" → Descartar e fechar
let _fechandoTreino = false;
async function fecharTreinoModal() {
  const modal = document.getElementById('treinoModal');
  if (!modal || modal.hidden || _fechandoTreino) return;
  // O Esc com a confirmação aberta é dela (o confirmar() trata); não empilha outra por cima.
  const cm = document.getElementById('confirmModal');
  if (cm && !cm.hidden) return;
  if (videoTreinoWork.enviando || videoTreinoWork.novo) {
    _fechandoTreino = true;
    let ok = false;
    try {
      ok = videoTreinoWork.enviando
        ? await confirmar('O vídeo ainda está sendo enviado. Fechar agora cancela o envio e descarta o que já subiu. Fechar mesmo assim?', { perigo: true, okTexto: 'Descartar e fechar' })
        : await confirmar('O vídeo enviado ainda não foi salvo no treinamento. Fechar sem salvar?', { okTexto: 'Fechar sem salvar' });
    } finally { _fechandoTreino = false; }
    if (!ok) return;
    if (videoTreinoWork.enviando) cancelarEnvioVideoTreino();
  }
  ocultarTreinoModal();
}
// Fecha o modal do treinamento sem perguntar nada (depois de salvar, ou de já ter confirmado).
// USO: ocultarTreinoModal() → esconde #treinoModal, para a prévia e solta o arquivo local.
function ocultarTreinoModal() {
  encerrarBlocoVideoTreino();
  document.getElementById('treinoModal').hidden = true;
}
const _btnNovoTreino = document.getElementById('btnNovoTreino');
if (_btnNovoTreino) _btnNovoTreino.onclick = () => abrirTreinoModal(null);
const _fecharTreino = document.getElementById('fecharTreino');
if (_fecharTreino) _fecharTreino.onclick = fecharTreinoModal;
const _cancelarTreino = document.getElementById('cancelarTreino');
if (_cancelarTreino) _cancelarTreino.onclick = fecharTreinoModal;
fecharAoClicarNoFundo('treinoModal', fecharTreinoModal);
const _btnAddQuestao = document.getElementById('btnAddQuestao');
if (_btnAddQuestao) _btnAddQuestao.onclick = () => _treinoMontarQuestao(null);
// Delegação dentro do editor de prova: + alternativa / remover questão / remover alternativa.
const _treinoQHost = document.getElementById('treinoQuestoes');
if (_treinoQHost) _treinoQHost.addEventListener('click', (e) => {
  const addAlt = e.target.closest('.treino-add-alt');
  if (addAlt) { _treinoMontarAlternativa(addAlt.closest('.treino-questao'), null, false); return; }
  const delQ = e.target.closest('.treino-q-del');
  if (delQ) {
    if (document.querySelectorAll('#treinoQuestoes .treino-questao').length <= 1) { toast('A prova precisa de ao menos uma questão.', 'erro'); return; }
    delQ.closest('.treino-questao').remove(); _treinoRenumerar(); return;
  }
  const delAlt = e.target.closest('.treino-alt-del');
  if (delAlt) {
    const qEl = delAlt.closest('.treino-questao');
    if (qEl.querySelectorAll('.treino-alt').length <= 2) { toast('Cada questão precisa de ao menos duas alternativas.', 'erro'); return; }
    delAlt.closest('.treino-alt').remove(); return;
  }
});
function _treinoColetarQuestoes() {
  const out = [];
  document.querySelectorAll('#treinoQuestoes .treino-questao').forEach(qEl => {
    const grupo = qEl.dataset.qid;
    const enunciado = (qEl.querySelector('.treino-q-enun').value || '').trim();
    const marcada = qEl.querySelector(`input[name="correta-${grupo}"]:checked`);
    const correta = marcada ? marcada.value : '';
    const alternativas = [];
    qEl.querySelectorAll('.treino-alt').forEach(aEl => {
      const texto = (aEl.querySelector('.treino-alt-txt').value || '').trim();
      if (texto) alternativas.push({ id: aEl.dataset.aid, texto });
    });
    out.push({ id: grupo, enunciado, alternativas, correta });
  });
  return out;
}
if (formTreino) formTreino.addEventListener('submit', async (e) => {
  e.preventDefault();
  const dados = {
    titulo: (formTreino.elements['titulo'].value || '').trim(),
    tipo: formTreino.elements['tipo'].value === 'curso' ? 'curso' : 'NR',
    validadeMeses: Number(formTreino.elements['validadeMeses'].value) || 0,
    fileId: (formTreino.elements['fileId'].value || '').trim(),
    descricao: (formTreino.elements['descricao'].value || '').trim(),
    questoes: _treinoColetarQuestoes(),
  };
  if (!dados.titulo) { formTreino.elements['titulo'].focus(); toast('Informe o título do treinamento.', 'erro'); return; }
  // Vídeo (1.55.41): fileId (Drive) OU vídeo enviado. O servidor confere de novo (400).
  if (videoTreinoWork.enviando) { toast('Aguarde o envio do vídeo terminar antes de salvar.', 'erro'); return; }
  const videoCampo = videoParaSalvarTreino();
  if (videoCampo.erro) { videoCampo.foco && videoCampo.foco.focus(); toast(videoCampo.erro, 'erro'); return; }
  if (videoCampo.video !== undefined) dados.video = videoCampo.video; // ausente = mantém o atual (PUT)
  // Cada questão precisa de enunciado, >=2 alternativas e gabarito marcado.
  for (let i = 0; i < dados.questoes.length; i++) {
    const q = dados.questoes[i];
    if (!q.enunciado) { toast(`Preencha o enunciado da questão ${i + 1}.`, 'erro'); return; }
    if (q.alternativas.length < 2) { toast(`A questão ${i + 1} precisa de ao menos duas alternativas.`, 'erro'); return; }
    if (!q.correta || !q.alternativas.some(a => a.id === q.correta)) { toast(`Marque a alternativa correta da questão ${i + 1}.`, 'erro'); return; }
  }
  if (!dados.questoes.length) { toast('Cadastre ao menos uma questão com o gabarito marcado.', 'erro'); return; }
  const url = editandoTreinoId ? '/api/treinamentos/' + encodeURIComponent(editandoTreinoId) : '/api/treinamentos';
  const r = await fetch(url, { method: editandoTreinoId ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(dados) });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) { toast(j.erro || 'Erro ao salvar.', 'erro'); return; }
  videoTreinoWork.novo = null; // já está no treinamento: fechar não deve avisar "não salvo"
  ocultarTreinoModal();
  await carregarIntegracao();
  toast(editandoTreinoId ? 'Treinamento atualizado.' : 'Treinamento cadastrado!', 'ok');
});

/* ---- Vídeo do treinamento enviado ao armazenamento (player travado) · 1.55.41 ----
   O arquivo sobe do navegador para o NOSSO servidor em partes fixas (6 MiB, uma por vez) e o
   servidor repassa cada parte ao bucket (upload multipart, sem estado: o cliente devolve
   {chave, uploadId} a cada parte). Nada disso grava o treinamento: o /concluir devolve o objeto
   `video`, que vai no POST/PUT /api/treinamentos quando o RH clica "Salvar". Um envio
   abandonado é descartado (DELETE videos/upload) e o que sobrar a faxina do servidor apaga. */

// Origem escolhida no bloco "Vídeo". USO: origemVideoTreino() → 'arquivo' | 'drive'
function origemVideoTreino() {
  const r = formTreino && formTreino.querySelector('input[name="videoOrigem"]:checked');
  return r && r.value === 'arquivo' ? 'arquivo' : 'drive';
}
// Marca a origem sem disparar o "change" (usado ao abrir). USO: definirOrigemVideoTreino('arquivo')
function definirOrigemVideoTreino(origem) {
  formTreino.querySelectorAll('input[name="videoOrigem"]').forEach(r => { r.checked = r.value === origem; });
}
// Vídeo que vale neste momento: o recém-enviado, senão o salvo (se não foi removido).
// USO: videoEfetivoTreino() → { chave, nome, bytes, mime, duracaoSeg, … } | null
function videoEfetivoTreino() {
  return videoTreinoWork.novo || (videoTreinoWork.removido ? null : videoTreinoWork.atual);
}
// Decide o campo `video` do POST/PUT e valida "fileId OU vídeo" conforme a origem escolhida.
// USO: videoParaSalvarTreino()
//   → { video: { chave, nome, bytes, mime, duracaoSeg } }   (enviou um vídeo novo)
//   → { video: null }                                        (passou para o Drive: tira o vídeo salvo)
//   → {}                                                     (mantém o que já está salvo; no PUT, ausente = mantém)
//   → { erro: 'Envie o vídeo do treinamento ou informe o link do Google Drive.', foco: <botão> }
function videoParaSalvarTreino() {
  const w = videoTreinoWork;
  if (origemVideoTreino() === 'arquivo') {
    if (!videoEfetivoTreino()) {
      return { erro: 'Envie o vídeo do treinamento ou informe o link do Google Drive.', foco: document.getElementById('treinoVideoEscolher') };
    }
    if (w.novo) {
      const { chave, nome, bytes, mime, duracaoSeg } = w.novo;
      return { video: { chave, nome, bytes, mime, duracaoSeg } };
    }
    return {};
  }
  const fileId = (formTreino.elements['fileId'].value || '').trim();
  if (!fileId) return { erro: 'Envie o vídeo do treinamento ou informe o link do Google Drive.', foco: formTreino.elements['fileId'] };
  return w.atual ? { video: null } : {};
}

// Estado limpo a cada abertura do modal + consulta do armazenamento.
// USO: resetarVideoTreino() (chamado por abrirTreinoModal, depois do formTreino.reset())
function resetarVideoTreino() {
  _videoTreinoSeq++;
  encerrarBlocoVideoTreino();
  Object.assign(videoTreinoWork, { atual: null, novo: null, removido: false, enviando: null, arquivoLocal: null, urlLocal: '', tocouOrigem: false });
  definirOrigemVideoTreino('drive');
  mostrarAvisosVideoTreino([]);
  progressoVideoTreino(null);
  renderVideoTreino();
  carregarConfigVideoTreino(_videoTreinoSeq);
}
// Vídeo salvo do treinamento aberto para edição. Com vídeo → origem "arquivo"; sem → "drive".
// USO: aplicarVideoDoTreino({ video: { chave, nome: 'NR-35.mp4', bytes, duracaoSeg: 612, … }, fileId: '' })
function aplicarVideoDoTreino(t) {
  videoTreinoWork.atual = (t && t.video && typeof t.video === 'object') ? t.video : null;
  videoTreinoWork.removido = false;
  if (!videoTreinoWork.tocouOrigem) definirOrigemVideoTreino(videoTreinoWork.atual ? 'arquivo' : 'drive');
  renderVideoTreino();
}
// GET /api/treinamentos/videos/config → { ativo, tipo, motivo, maxBytes, parteBytes, mimes }.
// Treinamento NOVO com o armazenamento ativo já abre em "Enviar arquivo" (se o RH não mexeu).
// USO: carregarConfigVideoTreino(_videoTreinoSeq)
async function carregarConfigVideoTreino(seq) {
  videoTreinoWork.config = null;
  let cfg;
  try {
    const r = await fetch('/api/treinamentos/videos/config', { cache: 'no-store' });
    const d = await r.json().catch(() => ({}));
    cfg = r.ok ? d : { ativo: false, motivo: d.erro || 'Não foi possível consultar o armazenamento de vídeos.' };
  } catch (e) {
    cfg = { ativo: false, motivo: 'Não foi possível consultar o armazenamento de vídeos. Verifique a conexão.' };
  }
  if (seq !== _videoTreinoSeq) return;
  videoTreinoWork.config = cfg;
  if (cfg.ativo && !editandoTreinoId && !videoTreinoWork.tocouOrigem) definirOrigemVideoTreino('arquivo');
  // Sem armazenamento e sem vídeo para manter: "Enviar arquivo" não tem como valer, volta ao Drive.
  if (!cfg.ativo && !videoEfetivoTreino() && origemVideoTreino() === 'arquivo') definirOrigemVideoTreino('drive');
  renderVideoTreino();
}

// Redesenha o bloco "Vídeo" a partir de videoTreinoWork (painéis, motivo, vídeo atual, botões).
// USO: renderVideoTreino() depois de qualquer mudança de estado.
function renderVideoTreino() {
  if (!formTreino) return;
  const w = videoTreinoWork, cfg = w.config;
  const origem = origemVideoTreino();
  const efetivo = videoEfetivoTreino();
  const ativo = !!(cfg && cfg.ativo);
  const consultando = !cfg;
  const pArq = document.getElementById('treinoVideoArquivo');
  const pDrive = document.getElementById('treinoVideoDrive');
  if (pArq) pArq.hidden = origem !== 'arquivo';
  if (pDrive) pDrive.hidden = origem !== 'drive';
  // Sem armazenamento: a opção de arquivo só fica de pé se já existe um vídeo (para mantê-lo).
  const radioArq = formTreino.querySelector('input[name="videoOrigem"][value="arquivo"]');
  if (radioArq) radioArq.disabled = !ativo && !consultando && !efetivo;
  const motivo = document.getElementById('treinoVideoMotivo');
  if (motivo) {
    const txt = consultando ? 'Consultando o armazenamento de vídeos…'
      : (!ativo ? `Envio de arquivo indisponível: ${cfg.motivo || 'armazenamento de vídeos não configurado.'}` : '');
    motivo.textContent = txt;
    motivo.hidden = !txt;
  }
  const testar = document.getElementById('treinoVideoTestar');
  if (testar) testar.hidden = !ehAdminLocal();
  // Escolher / trocar o arquivo
  const escolha = document.getElementById('treinoVideoEscolha');
  if (escolha) escolha.hidden = !!w.enviando;
  const btnEsc = document.getElementById('treinoVideoEscolher');
  if (btnEsc) {
    btnEsc.textContent = efetivo ? 'Trocar vídeo' : 'Escolher arquivo de vídeo';
    btnEsc.disabled = !ativo || !!w.enviando;
  }
  // Vídeo atual / recém-enviado
  const host = document.getElementById('treinoVideoAtual');
  if (host) {
    const previaAberta = host.querySelector('.treino-video-previa:not([hidden])');
    if (previaAberta) { try { previaAberta.pause(); } catch (e) { /* ignora */ } }
    if (efetivo) {
      const quando = efetivo.enviadoTs ? new Date(efetivo.enviadoTs).toLocaleDateString('pt-BR') : '';
      const origemTxt = w.novo
        ? 'enviado agora, falta salvar'
        : (quando ? `enviado em ${quando}${efetivo.enviadoPor ? ` por ${efetivo.enviadoPor}` : ''}` : '');
      const meta = [fmtDuracaoVideo(efetivo.duracaoSeg), efetivo.bytes ? fmtTamanho(efetivo.bytes) : '', origemTxt].filter(Boolean).join(' · ');
      const troca = (w.novo && w.atual && !w.removido)
        ? `<p class="dica treino-video-nota">Ao salvar, este vídeo substitui "${esc(w.atual.nome || 'vídeo anterior')}". Quem ainda não foi aprovado vai precisar assistir de novo.</p>` : '';
      host.innerHTML = `<div class="treino-video-atual">
          <span class="treino-video-ico" aria-hidden="true">${ICONE_VIDEO_TRN}</span>
          <span class="treino-video-info"><b class="treino-video-nome" title="${esc(efetivo.nome || '')}">${esc(efetivo.nome || 'vídeo')}</b><span class="treino-video-meta">${esc(meta)}</span></span>
          <span class="treino-video-acoes">
            <button type="button" class="btn btn-ghost small" data-video-acao="previa" aria-expanded="false">Ver prévia</button>
            <button type="button" class="btn btn-ghost small" data-video-acao="remover"${w.enviando ? ' disabled' : ''}>Remover vídeo</button>
          </span>
        </div>${troca}
        <video class="treino-video-previa" controls preload="metadata" playsinline hidden></video>`;
    } else if (w.atual && w.removido) {
      host.innerHTML = `<p class="treino-video-removido">O vídeo "${esc(w.atual.nome || 'vídeo')}" sai do treinamento ao salvar. <button type="button" class="btn btn-ghost small" data-video-acao="manter">Manter o vídeo</button></p>`;
    } else {
      host.innerHTML = '';
    }
  }
  // Drive com vídeo enviado: salvar assim tira o vídeo (e a trava) do treinamento.
  const avisoDrive = document.getElementById('treinoVideoDriveAviso');
  if (avisoDrive) {
    const tira = origem === 'drive' && !!w.atual;
    avisoDrive.textContent = tira ? `Ao salvar pelo Google Drive, o vídeo enviado "${w.atual.nome || 'vídeo'}" deixa de ser usado e o colaborador volta a poder adiantar.` : '';
    avisoDrive.hidden = !tira;
  }
  // "Salvar" travado durante o envio
  const salvar = formTreino.querySelector('button[type="submit"]');
  if (salvar) {
    salvar.disabled = !!w.enviando;
    salvar.title = w.enviando ? 'Aguarde o envio do vídeo terminar' : '';
  }
}

// Avisos NÃO bloqueantes sobre o arquivo escolhido (lista abaixo do envio).
// USO: mostrarAvisosVideoTreino(['O vídeo está em HEVC…']) · mostrarAvisosVideoTreino([]) esconde
function mostrarAvisosVideoTreino(avisos) {
  const ul = document.getElementById('treinoVideoAvisos');
  if (!ul) return;
  const lista = Array.isArray(avisos) ? avisos : [];
  ul.innerHTML = lista.map(a => `<li>${esc(a)}</li>`).join('');
  ul.hidden = !lista.length;
}
// Barra de progresso DENTRO do modal (mesmo padrão do progressoUpload do cofre de mídia, mas
// aqui o envio é longo e em partes, então o texto diz a parte e as esperas de retentativa).
// USO: progressoVideoTreino({ fase: 'enviando', nome: 'NR-35.mp4', enviado: 12582912, total: 52428800, n: 3, totalPartes: 9 })
//      progressoVideoTreino({ fase: 'esperando', etapa: 'na parte 3 de 9', segundos: 5, tentativa: 2, maxTentativas: 4 })
//      progressoVideoTreino({ fase: 'esperando', etapa: 'na parte 3 de 9', segundos: 3, ocupado: true }) → "Aguardando o servidor…"
//      progressoVideoTreino({ fase: 'lendo' }) · ({ fase: 'concluindo' }) · progressoVideoTreino(null) esconde
function progressoVideoTreino(estado) {
  const box = document.getElementById('treinoVideoProg');
  if (!box) return;
  if (!estado) { box.hidden = true; return; }
  box.hidden = false;
  const trilho = box.querySelector('.treino-video-prog-trilho');
  const barra = box.querySelector('.treino-video-prog-barra');
  const txt = document.getElementById('treinoVideoProgTxt');
  const pct = estado.total ? Math.min(100, Math.floor((estado.enviado / estado.total) * 100)) : (estado.fase === 'concluindo' ? 100 : 0);
  // A espera (retentativa ou servidor ocupado) não traz bytes: a barra fica onde estava.
  const semBytes = estado.fase === 'esperando' && !estado.total;
  if (barra && !semBytes) barra.style.width = pct + '%';
  if (trilho && !semBytes) trilho.setAttribute('aria-valuenow', String(pct));
  box.classList.toggle('gravando', estado.fase === 'concluindo');
  box.classList.toggle('esperando', estado.fase === 'esperando');
  const parte = estado.totalPartes ? ` · parte ${estado.n} de ${estado.totalPartes}` : '';
  let t = '';
  if (estado.fase === 'lendo') t = 'Lendo o vídeo…';
  else if (estado.fase === 'iniciando') t = `Preparando o envio de "${estado.nome}"…`;
  else if (estado.fase === 'gravando') t = `Enviando "${estado.nome}" · ${pct}%${parte} (servidor guardando a parte)`;
  else if (estado.fase === 'esperando' && estado.ocupado) t = `Aguardando o servidor ${estado.etapa || 'no envio'}: outros vídeos estão sendo enviados agora. Nova tentativa em ${estado.segundos} s.`;
  else if (estado.fase === 'esperando') t = `Conexão instável ${estado.etapa || 'no envio'}. Tentando de novo em ${estado.segundos} s (tentativa ${estado.tentativa} de ${estado.maxTentativas}).`;
  else if (estado.fase === 'concluindo') t = 'Finalizando o envio…';
  else t = `Enviando "${estado.nome}" · ${pct}% de ${fmtTamanho(estado.total)}${parte}`;
  if (txt) txt.textContent = t;
}

// Tipo aceito a partir do arquivo (espelho do mimeDe do servidor). .mov/QuickTime fica de fora.
// USO: mimeVideoTreino({ name: 'aula.mp4', type: '' }) → 'video/mp4'
//      mimeVideoTreino({ name: 'aula.webm', type: 'video/webm' }) → 'video/webm'
//      mimeVideoTreino({ name: 'IMG_0001.MOV', type: 'video/quicktime' }) → ''
function mimeVideoTreino(file) {
  const ext = ((/\.([a-z0-9]+)$/i.exec(String((file && file.name) || '')) || [])[1] || '').toLowerCase();
  const pelaExt = { mp4: 'video/mp4', m4v: 'video/mp4', webm: 'video/webm' }[ext] || '';
  let inf = String((file && file.type) || '').toLowerCase().split(';')[0].trim();
  if (inf === 'video/x-m4v') inf = 'video/mp4';
  const informado = (inf === 'video/mp4' || inf === 'video/webm') ? inf : '';
  if (inf && !informado && inf !== 'application/octet-stream') return '';
  if (informado && pelaExt && informado !== pelaExt) return '';
  return informado || pelaExt;
}
// Procura um trecho ASCII (ex.: 'hvc1') dentro de bytes. USO: contemAsciiVideo(u8, 'moov') → true|false
function contemAsciiVideo(bytes, s) {
  const c = [...s].map(ch => ch.charCodeAt(0));
  outer: for (let i = 0; i + c.length <= bytes.length; i++) {
    for (let k = 0; k < c.length; k++) if (bytes[i + k] !== c[k]) continue outer;
    return true;
  }
  return false;
}
// Posição dos átomos de topo 'moov' (índice) e 'mdat' (dados) de um MP4, lendo só os cabeçalhos.
// USO: await ordemAtomosMp4(file) → { moov: 32, mdat: 18000 } (otimizado para web: moov antes)
//      → { moov: 52000000, mdat: 40 } (moov no fim: o vídeo demora a começar no celular)
async function ordemAtomosMp4(file) {
  const r = { moov: -1, mdat: -1 };
  let pos = 0;
  for (let i = 0; i < 64 && pos + 8 <= file.size; i++) {
    const h = new DataView(await file.slice(pos, pos + 16).arrayBuffer());
    if (h.byteLength < 8) break;
    let tam = h.getUint32(0);
    const tipo = String.fromCharCode(h.getUint8(4), h.getUint8(5), h.getUint8(6), h.getUint8(7));
    if (tam === 1) { if (h.byteLength < 16) break; tam = h.getUint32(8) * 4294967296 + h.getUint32(12); }
    else if (tam === 0) tam = file.size - pos;
    if (tipo === 'moov' && r.moov < 0) r.moov = pos;
    if (tipo === 'mdat' && r.mdat < 0) r.mdat = pos;
    if ((r.moov >= 0 && r.mdat >= 0) || tam < 8) break;
    pos += tam;
  }
  return r;
}
// Avisos não bloqueantes lendo ~2 MB do início e do fim do arquivo: HEVC (pode não tocar em
// Android) e MP4 com o índice no fim (não otimizado para web). Falha de leitura = sem avisos.
// USO: await avisosArquivoVideo(file, 'video/mp4') → ['O vídeo está em HEVC (H.265)…'] | []
async function avisosArquivoVideo(file, mime) {
  const avisos = [];
  if (mime !== 'video/mp4') return avisos;
  try {
    const DOIS_MB = 2 * 1024 * 1024;
    const inicio = new Uint8Array(await file.slice(0, Math.min(file.size, DOIS_MB)).arrayBuffer());
    const fim = file.size > DOIS_MB ? new Uint8Array(await file.slice(Math.max(DOIS_MB, file.size - DOIS_MB)).arrayBuffer()) : new Uint8Array(0);
    const hevc = ['hvc1', 'hev1'].some(s => contemAsciiVideo(inicio, s) || contemAsciiVideo(fim, s));
    if (hevc) avisos.push('O vídeo está em HEVC (H.265) e pode não tocar em celulares Android e em alguns navegadores. Se puder, converta para MP4 H.264 + AAC.');
    const at = await ordemAtomosMp4(file);
    if (at.mdat >= 0 && (at.moov < 0 || at.mdat < at.moov)) avisos.push('O arquivo não está otimizado para web (o índice do vídeo fica no fim), então demora mais para começar no celular. No HandBrake, marque "Web Optimized" ao converter.');
  } catch (e) { /* aviso é só conveniência: sem leitura, sem aviso */ }
  return avisos;
}
// Lê a duração do vídeo NO NAVEGADOR (o servidor não decodifica vídeo) e junta os avisos.
// Rejeita com mensagem pronta para toast quando o navegador não toca o arquivo.
// USO: const { duracaoSeg, avisos } = await lerDuracaoVideo(file)   // ex.: { duracaoSeg: 612, avisos: [] }
//      await lerDuracaoVideo(arquivoHevcNoFirefox) → Error('Este navegador não consegue tocar o arquivo. Converta para MP4 (H.264 + AAC).')
function lerDuracaoVideo(file) {
  const duracao = new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const v = document.createElement('video');
    v.preload = 'metadata';
    v.muted = true;
    v.playsInline = true;
    let feito = false;
    const terminar = (erro, dur) => {
      if (feito) return;
      feito = true;
      clearTimeout(relogio);
      v.removeAttribute('src');
      try { v.load(); } catch (e) { /* ignora */ }
      URL.revokeObjectURL(url);
      if (erro) reject(new Error(erro)); else resolve(dur);
    };
    const relogio = setTimeout(() => terminar('Não foi possível ler a duração do vídeo (15 s sem resposta). Converta para MP4 (H.264 + AAC) e tente de novo.'), 15000);
    const conferir = () => {
      const d = v.duration;
      if (Number.isFinite(d) && d > 0) { terminar('', d); return true; }
      return false;
    };
    v.addEventListener('loadedmetadata', () => {
      if (conferir()) return;
      // Duração Infinity (WebM sem índice, comum em gravação feita no navegador): pular para
      // "o fim" obriga o navegador a varrer o arquivo e publicar a duração real.
      v.addEventListener('durationchange', conferir);
      v.addEventListener('timeupdate', conferir);
      try { v.currentTime = 1e101; } catch (e) { /* ignora */ }
    });
    v.addEventListener('error', () => terminar('Este navegador não consegue tocar o arquivo. Converta para MP4 (H.264 + AAC).'));
    v.src = url;
  });
  return duracao.then(async (dur) => {
    const duracaoSeg = Math.max(1, Math.round(dur));
    if (duracaoSeg > 4 * 60 * 60) throw new Error('O vídeo passa de 4 horas, o máximo aceito. Divida em partes menores.');
    return { duracaoSeg, avisos: await avisosArquivoVideo(file, mimeVideoTreino(file)) };
  });
}

// Espera que o "Cancelar envio" consegue interromper. USO: await esperarVideoTreino(5000, ctl)
function esperarVideoTreino(ms, ctl) {
  return new Promise((resolve) => {
    const t = setTimeout(() => { ctl.acordar = null; resolve(); }, ms);
    ctl.acordar = () => { clearTimeout(t); ctl.acordar = null; resolve(); };
  });
}
// Erro de envio com o que a retentativa precisa saber. status 0 = rede/tempo esgotado.
// USO: throw erroEnvioVideo('Sem conexão…', 0) · erroEnvioVideo('Ocupado', 503, 7) (Retry-After 7 s)
function erroEnvioVideo(msg, status, retryAfterSeg) {
  const e = new Error(msg);
  e.status = status || 0;
  e.retryAfter = Number(retryAfterSeg) || 0;
  return e;
}
// Vale tentar de novo? Rede caiu, tempo esgotado, servidor ocupado/fora (408/429/5xx). 4xx de
// validação (400/403/413/415) não mudam repetindo.
// USO: repeteEnvioVideo({ status: 503 }) → true · repeteEnvioVideo({ status: 415 }) → false
function repeteEnvioVideo(e) {
  const s = Number(e && e.status) || 0;
  return !(e && e.cancelado) && (s === 0 || s === 408 || s === 429 || s >= 500);
}
// Servidor só OCUPADO (semáforo global de partes: 503 + Retry-After), não uma falha: vale esperar.
// O 503 de "armazenamento não configurado" vem sem Retry-After e fica de fora.
// USO: servidorOcupadoVideo({ status: 503, retryAfter: 2 }) → true · ({ status: 503, retryAfter: 0 }) → false
function servidorOcupadoVideo(e) {
  return !!e && Number(e.status) === 503 && Number(e.retryAfter) > 0;
}
// Tempo máximo esperando o servidor ocupado numa mesma etapa (parte), fora das 3 retentativas.
const VIDEO_OCUPADO_MAX_MS = 3 * 60 * 1000;
// Executa `fn` com até 3 retentativas de falha real (rede, tempo esgotado, 5xx) e espera
// crescente (2 s, 5 s, 10 s). O servidor OCUPADO (servidorOcupadoVideo) tem orçamento próprio:
// repete respeitando o Retry-After (mais até 1 s aleatório, para os envios não voltarem juntos)
// por até VIDEO_OCUPADO_MAX_MS, sem gastar as 3 retentativas. A queda de conexão rápida (< 3 s)
// logo depois de um "ocupado" conta como ocupado também (proxy que corta o corpo não lido).
// `aoEsperar` recebe {segundos, tentativa, maxTentativas} ou {segundos, ocupado: true}.
// USO: await comRetentativasVideo(() => enviarParteVideoTreino(…), ctl, (p) => progressoVideoTreino({ fase: 'esperando', …p }))
//      // 503 ocupado 40 vezes seguidas (~2 min) e depois 200 → resolve com a resposta da parte
async function comRetentativasVideo(fn, ctl, aoEsperar) {
  const ESPERAS = [2000, 5000, 10000];
  let falhas = 0, ocupadoDesde = 0, ultimoOcupado = false;
  for (;;) {
    if (ctl.cancelado) throw Object.assign(new Error('Envio do vídeo cancelado.'), { cancelado: true });
    const t0 = Date.now();
    try { return await fn(); }
    catch (e) {
      if (ctl.cancelado) throw Object.assign(new Error('Envio do vídeo cancelado.'), { cancelado: true });
      if (!repeteEnvioVideo(e)) throw e;
      const ocupado = servidorOcupadoVideo(e) || (ultimoOcupado && Number(e.status) === 0 && Date.now() - t0 < 3000);
      ultimoOcupado = ocupado;
      let ms;
      if (ocupado) {
        if (!ocupadoDesde) ocupadoDesde = Date.now();
        if (Date.now() - ocupadoDesde >= VIDEO_OCUPADO_MAX_MS) throw e;
        ms = Math.min(60000, Math.max(2000, (Number(e.retryAfter) || 2) * 1000)) + Math.floor(Math.random() * 1000);
        if (typeof aoEsperar === 'function') aoEsperar({ segundos: Math.ceil(ms / 1000), ocupado: true });
      } else {
        if (falhas >= ESPERAS.length) throw e;
        ms = ESPERAS[falhas++];
        if (typeof aoEsperar === 'function') aoEsperar({ segundos: Math.round(ms / 1000), tentativa: falhas + 1, maxTentativas: ESPERAS.length + 1 });
      }
      await esperarVideoTreino(ms, ctl);
    }
  }
}
// Envia UMA parte (PUT binário) com os mesmos dois relógios do enviarMidia: sem avanço de bytes
// (UPLOAD_SEM_AVANCO_MS) e esperando a resposta depois dos bytes entregues (UPLOAD_ESPERA_RESPOSTA_MS,
// o servidor ainda repassa a parte ao bucket).
// USO: await enviarParteVideoTreino(file.slice(0, 6291456), 1, { chave, uploadId }, ctl, (carregado, fase) => …)
//      → { ok: true, n: 1, bytes: 6291456 }
function enviarParteVideoTreino(blob, n, envio, ctl, aoProgresso) {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    ctl.xhr = xhr;
    let relogio = null, parou = false;
    const rearmar = (ms) => { clearTimeout(relogio); relogio = setTimeout(() => { parou = true; xhr.abort(); }, ms); };
    const encerrar = () => { clearTimeout(relogio); if (ctl.xhr === xhr) ctl.xhr = null; };
    const qs = `?chave=${encodeURIComponent(envio.chave)}&uploadId=${encodeURIComponent(envio.uploadId)}`;
    xhr.open('PUT', `/api/treinamentos/videos/partes/${n}${qs}`);
    xhr.setRequestHeader('Content-Type', 'application/octet-stream');
    xhr.upload.onprogress = (e) => { rearmar(UPLOAD_SEM_AVANCO_MS); if (e.lengthComputable) aoProgresso(e.loaded, 'enviando'); };
    xhr.upload.onloadend = () => { rearmar(UPLOAD_ESPERA_RESPOSTA_MS); aoProgresso(blob.size, 'gravando'); };
    xhr.onload = () => {
      encerrar();
      let j = {};
      try { j = JSON.parse(xhr.responseText || '{}'); } catch (e) { /* resposta não-JSON (proxy, HTML de erro) */ }
      if (xhr.status >= 200 && xhr.status < 300) return resolve(j);
      reject(erroEnvioVideo(j.erro || `Falha ao enviar a parte ${n} do vídeo (erro ${xhr.status}).`, xhr.status, xhr.getResponseHeader('Retry-After')));
    };
    xhr.onerror = () => { encerrar(); reject(erroEnvioVideo('Sem conexão ao enviar o vídeo. Confira a internet e tente de novo.', 0)); };
    xhr.onabort = () => {
      encerrar();
      if (ctl.cancelado) return reject(Object.assign(new Error('Envio do vídeo cancelado.'), { cancelado: true }));
      reject(erroEnvioVideo(parou ? `A parte ${n} do vídeo parou de subir e foi interrompida.` : 'Envio interrompido.', 0));
    };
    rearmar(UPLOAD_SEM_AVANCO_MS);
    xhr.send(blob);
  });
}
// POST/DELETE JSON do envio do vídeo, com o erro no formato das retentativas.
// USO: await chamadaVideoTreino('POST', '/api/treinamentos/videos/iniciar', { nome, bytes, mime, duracaoSeg })
async function chamadaVideoTreino(metodo, url, corpo) {
  let r;
  try {
    r = await fetch(url, { method: metodo, headers: { 'Content-Type': 'application/json' }, body: corpo === undefined ? undefined : JSON.stringify(corpo) });
  } catch (e) { throw erroEnvioVideo('Sem conexão com o servidor. Confira a internet e tente de novo.', 0); }
  const d = await r.json().catch(() => ({}));
  if (!r.ok) throw erroEnvioVideo(d.erro || `Falha no envio do vídeo (erro ${r.status}).`, r.status, r.headers.get('Retry-After'));
  return d;
}
// Controle de um envio: cancelar() aborta a parte em voo e a espera de retentativa.
// USO: const ctl = novoControleEnvioVideo(); … ctl.cancelar();
function novoControleEnvioVideo() {
  const ctl = { cancelado: false, descartado: false, xhr: null, acordar: null, chave: '', uploadId: '', video: null };
  ctl.cancelar = () => {
    ctl.cancelado = true;
    if (ctl.xhr) { try { ctl.xhr.abort(); } catch (e) { /* ignora */ } }
    if (ctl.acordar) ctl.acordar();
  };
  return ctl;
}
// Descarta no servidor o upload multipart iniciado (best effort; a faxina cobre o que escapar).
// USO: descartarEnvioVideoTreino(ctl) → DELETE /api/treinamentos/videos/upload?chave=…&uploadId=…
function descartarEnvioVideoTreino(ctl) {
  if (!ctl || ctl.descartado || !ctl.chave || !ctl.uploadId) return;
  ctl.descartado = true;
  const qs = `?chave=${encodeURIComponent(ctl.chave)}&uploadId=${encodeURIComponent(ctl.uploadId)}`;
  fetch('/api/treinamentos/videos/upload' + qs, { method: 'DELETE', keepalive: true }).catch(() => {});
}
// Envia o arquivo inteiro: iniciar → partes (1 por vez, 3 retentativas) → concluir. Resolve com
// o objeto `video` do /concluir, pronto para o POST/PUT do treinamento. Em erro ou cancelamento
// descarta o upload no servidor.
// USO: const video = await enviarVideoTreino(file, 612, { aoProgresso: progressoVideoTreino, controle: ctl })
//      // → { chave: 'videos-treino/2026/<32hex>.mp4', nome: 'NR-35.mp4', bytes, mime: 'video/mp4', duracaoSeg: 612, enviadoTs, enviadoPor }
async function enviarVideoTreino(file, duracaoSeg, opcoes = {}) {
  const aoProgresso = typeof opcoes.aoProgresso === 'function' ? opcoes.aoProgresso : () => {};
  const ctl = opcoes.controle || novoControleEnvioVideo();
  const nome = file.name, bytes = file.size, mime = opcoes.mime || mimeVideoTreino(file);
  const esperando = (etapa) => (p) => aoProgresso(Object.assign({ fase: 'esperando', nome, etapa }, p));
  aoProgresso({ fase: 'iniciando', nome });
  const ini = await comRetentativasVideo(() => chamadaVideoTreino('POST', '/api/treinamentos/videos/iniciar', { nome, bytes, mime, duracaoSeg }), ctl, esperando('ao preparar o envio'));
  ctl.chave = ini.chave; ctl.uploadId = ini.uploadId;
  // Cancelado no meio do /iniciar: o upload nasceu no servidor mesmo assim, então descarta.
  if (ctl.cancelado) { descartarEnvioVideoTreino(ctl); throw Object.assign(new Error('Envio do vídeo cancelado.'), { cancelado: true }); }
  const parteBytes = Number(ini.parteBytes) || 6 * 1024 * 1024;
  const totalPartes = Number(ini.totalPartes) || Math.ceil(bytes / parteBytes);
  try {
    for (let n = 1; n <= totalPartes; n++) {
      const inicio = (n - 1) * parteBytes;
      const blob = file.slice(inicio, Math.min(bytes, inicio + parteBytes));
      await comRetentativasVideo(
        () => enviarParteVideoTreino(blob, n, ini, ctl, (carregado, fase) => aoProgresso({ fase, nome, enviado: inicio + carregado, total: bytes, n, totalPartes })),
        ctl, esperando(`na parte ${n} de ${totalPartes}`));
    }
    aoProgresso({ fase: 'concluindo', nome, enviado: bytes, total: bytes, n: totalPartes, totalPartes });
    const fim = await comRetentativasVideo(() => chamadaVideoTreino('POST', '/api/treinamentos/videos/concluir', { chave: ini.chave, uploadId: ini.uploadId, nome, bytes, mime, duracaoSeg }), ctl, esperando('ao finalizar o envio'));
    if (!fim || !fim.video) throw new Error('O servidor não confirmou o vídeo enviado. Tente de novo.');
    return fim.video;
  } catch (e) {
    descartarEnvioVideoTreino(ctl);
    throw e;
  }
}

// Protege o envio contra fechar/recarregar a aba. USO: sinalizarEnvioVideoTreino(true|false)
function _antesDeSairVideoTreino(e) { if (videoTreinoWork.enviando) { e.preventDefault(); e.returnValue = ''; } }
function sinalizarEnvioVideoTreino(ativo) {
  if (ativo) window.addEventListener('beforeunload', _antesDeSairVideoTreino);
  else window.removeEventListener('beforeunload', _antesDeSairVideoTreino);
}
// Cancela o envio em curso e descarta o upload no servidor. USO: cancelarEnvioVideoTreino()
function cancelarEnvioVideoTreino() {
  const ctl = videoTreinoWork.enviando;
  if (!ctl) return;
  ctl.cancelar();
  descartarEnvioVideoTreino(ctl);
  videoTreinoWork.enviando = null;
  sinalizarEnvioVideoTreino(false);
  progressoVideoTreino(null);
  renderVideoTreino();
}
// Fluxo do arquivo escolhido: confere tipo/tamanho → lê a duração (+ avisos) → envia com
// progresso → guarda o resultado em videoTreinoWork.novo (o RH ainda precisa clicar "Salvar").
// USO: aoEscolherVideoTreino(inputFile.files[0])
async function aoEscolherVideoTreino(file) {
  if (!file || videoTreinoWork.enviando) return;
  const cfg = videoTreinoWork.config;
  if (!cfg || !cfg.ativo) { toast((cfg && cfg.motivo) || 'O envio de vídeo não está disponível agora.', 'erro'); return; }
  const mime = mimeVideoTreino(file);
  if (!mime) { toast('Formato não aceito. Envie MP4 (H.264 + AAC) ou WebM; vídeo .mov do iPhone precisa ser convertido.', 'erro'); return; }
  if (!file.size) { toast('O arquivo está vazio.', 'erro'); return; }
  if (cfg.maxBytes && file.size > cfg.maxBytes) { toast(`O vídeo tem ${fmtTamanho(file.size)} e o máximo é ${fmtTamanho(cfg.maxBytes)}. Converta em 720p e tente de novo.`, 'erro'); return; }
  const seq = _videoTreinoSeq;
  const ctl = novoControleEnvioVideo();
  videoTreinoWork.enviando = ctl;
  sinalizarEnvioVideoTreino(true);
  mostrarAvisosVideoTreino([]);
  renderVideoTreino();
  progressoVideoTreino({ fase: 'lendo' });
  try {
    const info = await lerDuracaoVideo(file);
    if (ctl.cancelado) return;
    mostrarAvisosVideoTreino(info.avisos);
    const video = await enviarVideoTreino(file, info.duracaoSeg, { mime, controle: ctl, aoProgresso: (p) => { if (!ctl.cancelado) progressoVideoTreino(p); } });
    if (ctl.cancelado || seq !== _videoTreinoSeq) return;
    if (videoTreinoWork.urlLocal) { URL.revokeObjectURL(videoTreinoWork.urlLocal); videoTreinoWork.urlLocal = ''; }
    videoTreinoWork.novo = video;
    videoTreinoWork.arquivoLocal = file;
    ctl.video = video; // o "Cancelar envio" confirmado depois do fim reconhece o resultado deste envio
    toast('Vídeo enviado. Clique em Salvar para gravar no treinamento.', 'ok');
  } catch (e) {
    if (!ctl.cancelado && !e.cancelado) toast(e.message || 'Não foi possível enviar o vídeo.', 'erro');
  } finally {
    if (videoTreinoWork.enviando === ctl) {
      videoTreinoWork.enviando = null;
      sinalizarEnvioVideoTreino(false);
      progressoVideoTreino(null);
    }
    if (seq === _videoTreinoSeq) renderVideoTreino();
  }
}
// Prévia do vídeo no próprio modal (o RH pode usar os controles). O recém-enviado toca do arquivo
// local; o salvo pede um endereço temporário ao servidor (GET /api/treinamentos/:id/video-url).
// USO: alternarPreviaVideoTreino(botaoVerPrevia)
async function alternarPreviaVideoTreino(btn) {
  const host = document.getElementById('treinoVideoAtual');
  const player = host && host.querySelector('.treino-video-previa');
  if (!player) return;
  if (!player.hidden) {
    try { player.pause(); } catch (e) { /* ignora */ }
    player.hidden = true;
    btn.textContent = 'Ver prévia'; btn.setAttribute('aria-expanded', 'false');
    return;
  }
  const w = videoTreinoWork;
  let url = '';
  if (w.novo && w.arquivoLocal) {
    if (!w.urlLocal) w.urlLocal = URL.createObjectURL(w.arquivoLocal);
    url = w.urlLocal;
  } else if (w.atual && editandoTreinoId) {
    btn.disabled = true;
    try {
      const r = await fetch('/api/treinamentos/' + encodeURIComponent(editandoTreinoId) + '/video-url', { cache: 'no-store' });
      const d = await r.json().catch(() => ({}));
      if (!r.ok || !d.url) throw new Error(d.erro || 'Não foi possível abrir a prévia do vídeo.');
      url = d.url;
    } catch (e) { toast(e.message, 'erro'); return; }
    finally { btn.disabled = false; }
  }
  if (!url || !player.isConnected) return;
  if (player.getAttribute('src') !== url) player.src = url;
  player.hidden = false;
  btn.textContent = 'Fechar prévia'; btn.setAttribute('aria-expanded', 'true');
}
// Ao fechar o modal: para a prévia e solta o arquivo local (URL de objeto).
// USO: encerrarBlocoVideoTreino() (chamado por ocultarTreinoModal e resetarVideoTreino)
function encerrarBlocoVideoTreino() {
  const host = document.getElementById('treinoVideoAtual');
  const player = host && host.querySelector('.treino-video-previa');
  if (player) { try { player.pause(); } catch (e) { /* ignora */ } player.removeAttribute('src'); try { player.load(); } catch (e) { /* ignora */ } }
  if (videoTreinoWork.urlLocal) { URL.revokeObjectURL(videoTreinoWork.urlLocal); videoTreinoWork.urlLocal = ''; }
}
// "Testar conexão" (só admin): o servidor grava, lê e apaga um objeto de teste no bucket.
// USO: testarConexaoVideoTreino(botao) → POST /api/treinamentos/videos/testar → toast com a mensagem
async function testarConexaoVideoTreino(btn) {
  const txt = btn.textContent;
  btn.disabled = true; btn.textContent = 'Testando…';
  try {
    const r = await fetch('/api/treinamentos/videos/testar', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
    const d = await r.json().catch(() => ({}));
    if (!r.ok || !d.ok) throw new Error(d.erro || `O teste do armazenamento falhou (erro ${r.status}).`);
    toast(d.mensagem || 'Armazenamento de vídeos respondendo.', 'ok');
    carregarConfigVideoTreino(_videoTreinoSeq);
  } catch (e) { toast(e.message || 'O teste do armazenamento falhou.', 'erro'); }
  finally { btn.disabled = false; btn.textContent = txt; }
}
// Ligações do bloco "Vídeo" (uma vez, no carregamento).
(() => {
  if (!formTreino) return;
  formTreino.querySelectorAll('input[name="videoOrigem"]').forEach(r => r.addEventListener('change', () => {
    videoTreinoWork.tocouOrigem = true;
    renderVideoTreino();
  }));
  const input = document.getElementById('treinoVideoInput');
  const escolher = document.getElementById('treinoVideoEscolher');
  if (escolher && input) escolher.addEventListener('click', () => { if (!escolher.disabled) input.click(); });
  if (input) input.addEventListener('change', () => { const f = input.files && input.files[0]; input.value = ''; aoEscolherVideoTreino(f); });
  const cancelar = document.getElementById('treinoVideoCancelar');
  // O envio segue enquanto a confirmação está aberta. Se ele terminar nesse meio-tempo, o
  // "Descartar envio" confirmado continua valendo: o vídeo recém-enviado sai de
  // videoTreinoWork.novo (não vai no Salvar) e o objeto órfão fica para a faxina do servidor.
  // EXEMPLO: RH clica "Cancelar envio" na última parte → o /concluir responde com a confirmação
  //          aberta → RH confirma → toast "O envio já tinha terminado; o vídeo foi descartado."
  //          e o cartão volta ao vídeo anterior (ou a "sem vídeo").
  if (cancelar) cancelar.addEventListener('click', async () => {
    const ctl = videoTreinoWork.enviando;
    if (!ctl) return;
    if (!(await confirmar('Cancelar o envio do vídeo? O que já subiu é descartado.', { perigo: true, okTexto: 'Descartar envio' }))) return;
    if (videoTreinoWork.enviando === ctl) {
      cancelarEnvioVideoTreino();
      toast('Envio do vídeo cancelado.', '');
      return;
    }
    // Terminou com a confirmação aberta. Deu certo e o resultado ainda é o vídeo pendente → descarta.
    // Falhou (o erro já foi avisado) ou outro treinamento foi aberto → não há o que descartar.
    if (ctl.video && videoTreinoWork.novo === ctl.video) {
      encerrarBlocoVideoTreino();
      videoTreinoWork.novo = null;
      videoTreinoWork.arquivoLocal = null;
      renderVideoTreino();
      toast('O envio já tinha terminado; o vídeo foi descartado.', '');
    }
  });
  const testar = document.getElementById('treinoVideoTestar');
  if (testar) testar.addEventListener('click', () => testarConexaoVideoTreino(testar));
  const host = document.getElementById('treinoVideoAtual');
  if (host) host.addEventListener('click', (e) => {
    const b = e.target.closest('[data-video-acao]');
    if (!b) return;
    const acao = b.dataset.videoAcao;
    const w = videoTreinoWork;
    if (acao === 'previa') { alternarPreviaVideoTreino(b); return; }
    if (acao === 'remover') {
      encerrarBlocoVideoTreino();
      if (w.novo) { w.novo = null; w.arquivoLocal = null; }
      else if (w.atual) w.removido = true;
      renderVideoTreino();
      return;
    }
    if (acao === 'manter') { w.removido = false; renderVideoTreino(); }
  });
})();

/* ============================================================
   APORTES (aportes dos sócios nos contratos/obras, com rendimentos)
   ============================================================ */
// A taxa é guardada como FRAÇÃO DIÁRIA (ex.: 0.000416667). No formulário a pessoa
// digita em "% ao mês" (mais intuitivo) — converte com mês de 30 dias.
const APT_SOCIOS = [
  { campo: 'marcelo', rotulo: 'Marcelo' },
  { campo: 'ricardo', rotulo: 'Ricardo' },
  { campo: 'fernando', rotulo: 'Fernando' },
  { campo: 'tiago', rotulo: 'Tiago' },
];
function diaParaMesPct(taxaDia) { return (Number(taxaDia) || 0) * 30 * 100; }
function mesPctParaDia(pctMes) { return (Number(pctMes) || 0) / 100 / 30; }
function taxaJurosAporteSegura(v) {
  const n = Number(v) || 0;
  return n > 0 && n <= 0.02 ? n : 0;
}
function dataQuitacaoAporteValida(a) {
  if (!a || !a.dataQuitacao) return false;
  const dt = parseBR(a.dataQuitacao);
  return !!(dt && dt.getFullYear() >= 2020);
}
// Valor numérico -> string BR (1.234,56) p/ preencher os campos .sim-money no "editar".
// Vazio quando 0/sem valor (mantém o campo limpo, como antes). numBR() desfaz no submit.
function valorParaCampo(n) { const v = Number(n); return v ? v.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : ''; }
// dias decorridos + rendimentos do aporte (da data até a quitação, ou até hoje se ativo).
function calcApt(a) {
  const ini = parseBR(a.data);
  // aporte ativo: usa HOJE à meia-noite (não a hora atual), senão (fim-ini) fica fracionário e
  // dias/rendimentos oscilam conforme a hora de acesso e ficam em base diferente dos quitados (parseBR = meia-noite).
  const hoje = new Date();
  const quitado = dataQuitacaoAporteValida(a);
  const fim = quitado ? parseBR(a.dataQuitacao) : new Date(hoje.getFullYear(), hoje.getMonth(), hoje.getDate());
  let dias = 0;
  if (ini && fim) dias = Math.max(0, Math.round((fim - ini) / 86400000));
  const rend = (Number(a.valor) || 0) * dias * taxaJurosAporteSegura(a.taxaJuros);
  return { dias, rend, ativo: !quitado };
}
const filtroCardApt = { v: '' }; // '' | 'ATIVO' | 'QUITADO'

async function carregarAportes() {
  try {
    const r = await fetch('/api/aportes', { cache: 'no-store' });
    if (r.status === 401) { window.location = '/login'; return; }
    if (r.ok) APORTES = await r.json();
  } catch (e) { /* mantém o que tem */ }
  renderAportes();
}
function aptValoresUnicos(campo) {
  return [...new Set(APORTES.map(a => a[campo]).filter(x => x && String(x).trim()))]
    .sort((a, b) => String(a).localeCompare(String(b), 'pt-BR'));
}
function popularFiltrosApt() {
  if (MSEL.faGrupo) MSEL.faGrupo.setOpcoes(aptValoresUnicos('grupo'));
  if (MSEL.faContrato) MSEL.faContrato.setOpcoes(aptValoresUnicos('contrato'));
  if (MSEL.faStatus) MSEL.faStatus.setOpcoes(['Ativo', 'Quitado']);
  // Sugestões de centro de custo = os já usados nos aportes + a lista oficial da Frota
  // (fonte compartilhada). Não restringe: aceita valores próprios (CONTRATOS, VEÍCULOS RM...).
  const dlG = document.getElementById('listaGruposApt');
  if (dlG) {
    const grupos = new Set([...aptValoresUnicos('grupo'), ...centrosCustoFrota()]);
    dlG.innerHTML = [...grupos].sort((a, b) => String(a).localeCompare(String(b), 'pt-BR')).map(x => `<option value="${esc(x)}">`).join('');
  }
  const dlC = document.getElementById('listaContratosApt'); if (dlC) dlC.innerHTML = aptValoresUnicos('contrato').map(x => `<option value="${esc(x)}">`).join('');
}
function aptFiltrados() {
  const q = (document.getElementById('buscaApt')?.value || '').trim().toLowerCase();
  const fG = getSel('faGrupo'), fC = getSel('faContrato'), fS = getSel('faStatus');
  return APORTES.filter(a => {
    if (fG.length && !fG.includes(a.grupo)) return false;
    if (fC.length && !fC.includes(a.contrato)) return false;
    const status = dataQuitacaoAporteValida(a) ? 'Quitado' : 'Ativo';
    if (fS.length && !fS.includes(status)) return false;
    if (filtroCardApt.v && status.toUpperCase() !== filtroCardApt.v) return false;
    if (q) {
      const blob = [a.grupo, a.contrato, a.data, a.valor, a.obs].join(' ').toLowerCase();
      if (!blob.includes(q)) return false;
    }
    return true;
  });
}
// Quais colunas de sócio têm algum valor (no conjunto todo) — evita colunas vazias na tabela.
function aptSociosUsados() {
  return APT_SOCIOS.filter(s => APORTES.some(a => Number(a[s.campo]) > 0));
}
function renderCardsApt() {
  const cont = document.getElementById('cardsAportes'); if (!cont) return;
  const soma = (arr, f) => arr.reduce((s, a) => s + (f ? f(a) : (Number(a.valor) || 0)), 0);
  const ativos = APORTES.filter(a => !dataQuitacaoAporteValida(a));
  const quitados = APORTES.filter(dataQuitacaoAporteValida);
  const rendTotal = soma(APORTES, a => calcApt(a).rend);
  const rendAtivos = soma(ativos, a => calcApt(a).rend);
  const at = (alvo) => filtroCardApt.v === alvo ? ' card-ativo' : '';
  cont.innerHTML = `
    ${cardV2('Total de aportes', APORTES.length, 'card-clic' + at(''), false, 'data-card="TODOS"')}
    ${cardV2('Valor aportado', fmtMoneyDec(soma(APORTES)), '', true)}
    ${cardV2('Ativos', `${ativos.length} • ${fmtMoneyDec(soma(ativos))}`, 'amber card-clic' + at('ATIVO'), false, 'data-card="ATIVO"')}
    ${cardV2('Quitados', `${quitados.length} • ${fmtMoneyDec(soma(quitados))}`, 'green card-clic' + at('QUITADO'), false, 'data-card="QUITADO"')}
    ${cardV2('Rendimentos (ativos)', fmtMoneyDec(rendAtivos), '', true)}
    ${cardV2('Rendimentos (total)', fmtMoneyDec(rendTotal), '', true)}
  `;
  cont.querySelectorAll('.v2-kpi[data-card]').forEach(c => {
    c.setAttribute('role', 'button'); c.tabIndex = 0;
    const aplicar = () => {
      const alvo = c.dataset.card;
      filtroCardApt.v = (alvo === 'TODOS' || filtroCardApt.v === alvo) ? '' : alvo;
      renderAportes();
    };
    c.onclick = aplicar;
    c.onkeydown = (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); aplicar(); } };
  });
}
function renderResumoApt(lista) {
  const host = document.getElementById('resumoApt'); if (!host) return;
  const soma = (f) => lista.reduce((s, a) => s + (Number(f(a)) || 0), 0);
  const socios = aptSociosUsados();
  const partes = socios.map(s => `${s.rotulo}: <b>${fmtMoneyDec(soma(a => a[s.campo]))}</b>`);
  const rend = lista.reduce((s, a) => s + calcApt(a).rend, 0);
  host.innerHTML = `Exibindo <b>${lista.length}</b> de <b>${APORTES.length}</b> aportes &nbsp;•&nbsp; Aportado (filtro): <b>${fmtMoneyDec(soma(a => a.valor))}</b>`
    + (partes.length ? ` &nbsp;•&nbsp; ${partes.join(' &nbsp; ')}` : '')
    + ` &nbsp;•&nbsp; Rendimentos (filtro): <b>${fmtMoneyDec(rend)}</b>`;
}
function renderTabelaApt() {
  const lista = aptFiltrados().slice().sort((a, b) => {
    const da = parseBR(a.data), db = parseBR(b.data);
    return (db ? db.getTime() : 0) - (da ? da.getTime() : 0); // mais recentes primeiro
  });
  const socios = aptSociosUsados();
  const cab = document.getElementById('cabecalhoApt');
  const podeExcluir = permissaoAtual('controles') === 'editar';
  // Carteira (grupo) e Contrato viram UMA coluna: o contrato só aparece quando difere da carteira
  // (na maioria das carteiras eles têm o mesmo nome — repetir confunde).
  const colunas = [
    { label: 'Ações', acoes: true }, { label: 'Data' }, { label: 'Centro de Custo' }, { label: 'Valor', num: true },
    ...socios.map(s => ({ label: s.rotulo, num: true })),
    { label: 'Dias', num: true }, { label: 'Rendimentos', num: true }, { label: 'Situação' },
  ];
  if (cab) cab.innerHTML = colunas.map(c => `<th${c.acoes ? ' class="col-acoes"' : (c.num ? ' class="num"' : '')}>${esc(c.label)}</th>`).join('');
  const corpo = document.getElementById('corpoApt');
  estadoVazio('aptVazio', APORTES.length, lista.length,
    'Nenhum aporte cadastrado ainda. Clique em "+ Aporte" para lançar o primeiro, ou importe as planilhas pelo script.',
    () => { limparFiltrosApt(); });
  if (corpo) corpo.innerHTML = lista.map(a => {
    const { dias, rend, ativo } = calcApt(a);
    const pill = ativo
      ? '<span class="apt-pill apt-ativo">Ativo</span>'
      : `<span class="apt-pill apt-quitado">Quitado</span>${dataQuitacaoAporteValida(a) ? `<span class="apt-quit-data">${esc(fmtData(a.dataQuitacao))}</span>` : ''}`;
    const dif = a.contrato && a.contrato.toUpperCase() !== (a.grupo || '').toUpperCase();
    const carteira = `${esc(a.grupo)}${dif ? `<span class="apt-sub"> › ${esc(a.contrato)}</span>` : ''}`;
    return `<tr data-id="${esc(a.id)}">
      <td class="acoes">
        <button class="edit edit-apt" data-id="${esc(a.id)}" title="Editar" aria-label="Editar">${ICONE_LAPIS}</button>
        ${podeExcluir ? `<button class="del del-apt" data-id="${esc(a.id)}" title="Excluir" aria-label="Excluir">${ICONE_LIXEIRA}</button>` : ''}
      </td>
      <td>${esc(fmtData(a.data))}</td>
      <td>${carteira}</td>
      <td class="num">${fmtMoneyDec(a.valor)}</td>
      ${socios.map(s => `<td class="num">${Number(a[s.campo]) ? fmtMoneyDec(a[s.campo]) : '<span class="apt-zero">—</span>'}</td>`).join('')}
      <td class="num">${dias}</td>
      <td class="num">${rend ? fmtMoneyDec(rend) : '<span class="apt-zero">—</span>'}</td>
      <td>${pill}</td>
    </tr>`;
  }).join('');
  renderResumoApt(lista);
}
function renderAportes() {
  popularFiltrosApt();
  renderCardsApt();
  renderTabelaApt();
  // se a sub-aba Dashboard estiver aberta, mantém os gráficos em sincronia
  const dash = document.getElementById('apt-dashboard');
  if (dash && dash.classList.contains('active')) renderDashboardApt();
}
// Carrega TODAS as áreas de Controles (aportes, empréstimos, percentuais, retiradas)
function carregarControles() {
  carregarAportes(); carregarEmprestimos(); carregarPercentuais(); carregarRetiradas();
}
// Sub-abas (Aportes | Empréstimos | Percentuais | Retiradas | Dashboard)
document.querySelectorAll('#controlesSubtabs .subtab').forEach(b => b.onclick = () => {
  if (b.classList.contains('active')) return;
  document.querySelectorAll('#controlesSubtabs .subtab').forEach(x => x.classList.remove('active'));
  document.querySelectorAll('#controles .subview').forEach(x => x.classList.remove('active'));
  b.classList.add('active');
  document.getElementById(b.dataset.sub).classList.add('active');
  const pt = document.getElementById('pageTitle'); if (pt) pt.textContent = 'Controles › ' + b.textContent.trim();
  if (b.dataset.sub === 'apt-dashboard') renderDashboardApt();
  if (b.dataset.sub === 'ctrl-emprestimos') renderEmprestimos();
  if (b.dataset.sub === 'ctrl-percentuais') renderPercentuais();
  if (b.dataset.sub === 'ctrl-retiradas') renderRetiradas();
});
// Rótulo curto de mês: "2026-06" -> "jun/26"
const APT_MESES = ['jan', 'fev', 'mar', 'abr', 'mai', 'jun', 'jul', 'ago', 'set', 'out', 'nov', 'dez'];
function aptMesLabel(k) { const [a, m] = k.split('-'); return `${APT_MESES[Number(m) - 1]}/${a.slice(2)}`; }

// Limite (em dias) que um centro de custo pode ficar SEM retornar valor do que foi
// aportado antes de acender o alerta. Configurável: ajuste só este número.
const ALERTA_RETORNO_DIAS = 60;
// Data do último "retorno" de capital de um centro de custo (grupo): conta devolução de
// capital (retirada) E quitação de aporte — quitar também devolve o capital. null = nunca.
function ultimoRetornoCC(grupo) {
  const g = String(grupo || '').toUpperCase();
  let max = null;
  const considera = (s) => { const d = parseBR(s); if (d && (!max || d > max)) max = d; };
  for (const r of RETIRADAS) if (r.tipo === 'Devolução de capital' && String(r.grupo || '').toUpperCase() === g) considera(r.data);
  for (const a of APORTES) if (dataQuitacaoAporteValida(a) && String(a.grupo || '').toUpperCase() === g) considera(a.dataQuitacao);
  return max;
}
// Dias corridos desde o último retorno (Infinity = nunca retornou).
function diasSemRetorno(grupo) {
  const last = ultimoRetornoCC(grupo);
  if (!last) return Infinity;
  const hoje = new Date(); hoje.setHours(0, 0, 0, 0);
  return Math.floor((hoje - last) / 86400000);
}
// Lista oficial de centros de custo da Frota (fonte da verdade compartilhada): o que está
// no cadastro + o que está em uso nos veículos. Usada como sugestão no campo do aporte.
function centrosCustoFrota() {
  const set = new Set();
  for (const c of (CADASTROS.centrosCusto || [])) if (c && String(c).trim()) set.add(String(c).trim());
  for (const v of VEICULOS) if (v.centroCusto && String(v.centroCusto).trim()) set.add(String(v.centroCusto).trim());
  return [...set].sort((a, b) => a.localeCompare(b, 'pt-BR'));
}
function renderDashboardApt() {
  const lista = APORTES;
  const soma = (arr, f) => arr.reduce((s, a) => s + (f ? Number(f(a)) || 0 : Number(a.valor) || 0), 0);
  // agrega por carteira
  const grupos = {};
  for (const a of lista) {
    const g = grupos[a.grupo] || (grupos[a.grupo] = { n: 0, aportado: 0, ativo: 0, quitado: 0, rend: 0 });
    g.n++; g.aportado += Number(a.valor) || 0; g.rend += calcApt(a).rend;
    if (dataQuitacaoAporteValida(a)) g.quitado += Number(a.valor) || 0; else g.ativo += Number(a.valor) || 0;
  }
  // devoluções de capital (retiradas) por carteira — abatem o aporte (mostra o LÍQUIDO investido)
  const devCap = {};
  for (const r of RETIRADAS) { if (r.tipo === 'Devolução de capital') { const g = (r.grupo || '—').toUpperCase(); devCap[g] = (devCap[g] || 0) + (Number(r.valor) || 0); } }
  // carteiras que só aparecem em devoluções (sem aporte) também viram linha própria — senão o
  // TOTAL contaria a devolução mas nenhuma linha a mostraria (números que não fechavam).
  for (const g of Object.keys(devCap)) { if (!grupos[g]) grupos[g] = { n: 0, aportado: 0, ativo: 0, quitado: 0, rend: 0 }; }
  // líquido nunca negativo: devolução só abate o capital AINDA ativo (capital já quitado não vira
  // líquido investido negativo). Clampa por carteira; o TOTAL é a soma desses líquidos (fecha com as linhas).
  for (const g of Object.keys(grupos)) { grupos[g].devolucao = devCap[g] || 0; grupos[g].liquido = Math.max(0, grupos[g].ativo - grupos[g].devolucao); }
  const devTotal = Object.values(devCap).reduce((s, v) => s + v, 0);
  const gk = Object.keys(grupos).sort((a, b) => grupos[b].liquido - grupos[a].liquido);
  const quitados = lista.filter(dataQuitacaoAporteValida);
  const ativoLiq = gk.reduce((s, k) => s + grupos[k].liquido, 0);
  const socios = aptSociosUsados();
  const rendTotal = soma(lista, a => calcApt(a).rend);
  // KPIs (já descontando as devoluções de capital)
  const host = document.getElementById('cardsDashApt');
  if (host) host.innerHTML = `
    ${cardV2('Centros de custo', gk.length)}
    ${cardV2('Capital investido (líquido)', fmtMoneyDec(ativoLiq), 'amber', true)}
    ${cardV2('Devoluções de capital', fmtMoneyDec(devTotal), devTotal ? 'red' : '', true)}
    ${cardV2('Já quitado', fmtMoneyDec(soma(quitados)), 'green', true)}
    ${cardV2('Rendimentos acumulados', fmtMoneyDec(rendTotal), '', true)}`;
  // gráficos
  desenhar('chartAptGrupo', 'bar',
    { labels: gk, datasets: [{ label: 'Líquido', data: gk.map(k => grupos[k].liquido), backgroundColor: '#1b56ff' }] },
    { plugins: { legend: { display: false }, tooltip: { callbacks: { label: (c) => fmtMoneyDec(c.parsed.y) } } }, scales: { y: { beginAtZero: true } } });
  desenhar('chartAptSocio', 'doughnut',
    { labels: socios.map(s => s.rotulo), datasets: [{ data: socios.map(s => soma(lista, a => a[s.campo])), backgroundColor: ['#1d4ed8', '#16a34a', '#d97706', '#7c3aed'] }] },
    { plugins: { tooltip: { callbacks: { label: (c) => `${c.label}: ${fmtMoneyDec(c.parsed)}` } } } });
  desenhar('chartAptRend', 'bar',
    { labels: gk, datasets: [{ label: 'Rendimentos', data: gk.map(k => grupos[k].rend), backgroundColor: '#16a34a' }] },
    { plugins: { legend: { display: false }, tooltip: { callbacks: { label: (c) => fmtMoneyDec(c.parsed.y) } } }, scales: { y: { beginAtZero: true } } });
  // por mês
  const meses = {};
  for (const a of lista) { const d = parseBR(a.data); if (!d) continue; const k = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`; meses[k] = (meses[k] || 0) + (Number(a.valor) || 0); }
  const mk = Object.keys(meses).sort();
  desenhar('chartAptMes', 'bar',
    { labels: mk.map(aptMesLabel), datasets: [{ label: 'Aportado no mês', data: mk.map(k => meses[k]), backgroundColor: '#6e7780' }] },
    { plugins: { legend: { display: false }, tooltip: { callbacks: { label: (c) => fmtMoneyDec(c.parsed.y) } } }, scales: { y: { beginAtZero: true } } });
  // resumo por carteira
  const tab = document.getElementById('tabelaAptResumo');
  if (tab) {
    const head = `<thead><tr><th>Centro de Custo</th><th class="num">Aportes</th><th class="num">Aportado</th><th class="num">Devoluções</th><th class="num">Líquido ativo</th><th class="num">Quitado</th><th class="num">Rendimentos</th></tr></thead>`;
    const linhas = gk.map(k => {
      const g = grupos[k];
      // Alerta dos 60 dias: só para CC com capital ainda ativo (líquido > 0); quitados não precisam retornar.
      const dias = g.liquido > 0 ? diasSemRetorno(k) : null;
      const atrasado = dias !== null && dias > ALERTA_RETORNO_DIAS;
      const badge = atrasado ? ` <span class="cc-badge-atraso" title="Sem retorno de capital há ${dias === Infinity ? 'mais de ' + ALERTA_RETORNO_DIAS : dias} dias (limite ${ALERTA_RETORNO_DIAS} dias)">⚠ ${dias === Infinity ? 'sem retorno' : dias + 'd'}</span>` : '';
      return `<tr class="${atrasado ? 'cc-atrasado' : ''}"><td>${esc(k)}${badge}</td><td class="num">${g.n}</td><td class="num">${fmtMoneyDec(g.aportado)}</td><td class="num">${g.devolucao ? '−' + fmtMoneyDec(g.devolucao) : '<span class="apt-zero">—</span>'}</td><td class="num">${fmtMoneyDec(g.liquido)}</td><td class="num">${fmtMoneyDec(g.quitado)}</td><td class="num">${fmtMoneyDec(g.rend)}</td></tr>`;
    }).join('');
    const tot = `<tr class="total"><td>TOTAL</td><td class="num">${lista.length}</td><td class="num">${fmtMoneyDec(soma(lista))}</td><td class="num">${devTotal ? '−' + fmtMoneyDec(devTotal) : '—'}</td><td class="num">${fmtMoneyDec(ativoLiq)}</td><td class="num">${fmtMoneyDec(soma(quitados))}</td><td class="num">${fmtMoneyDec(rendTotal)}</td></tr>`;
    tab.innerHTML = head + `<tbody>${linhas}${tot}</tbody>`;
  }
  // painéis consolidados (cruzam Aportes + Percentuais + Retiradas + Empréstimos)
  renderPosicaoSocios();
  renderDashEmprestimos();
  renderDashEmpDeveQuem();
  renderDashPctSocio();
}

// ---- Dashboard consolidado: Posição por sócio ----
// Cruza as 4 áreas por sócio: capital aportado/ativo, rendimentos (rateados pela fatia de cada
// sócio no aporte), lucro distribuído por NF, e retiradas (lucro × devolução de capital).
const APT_SOCIOS_NORM = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
function renderPosicaoSocios() {
  const tab = document.getElementById('tabelaSocios'); if (!tab) return;
  const base = APT_SOCIOS.slice(); // marcelo, ricardo, fernando, tiago
  const porChave = {}; base.forEach(s => porChave[APT_SOCIOS_NORM(s.rotulo)] = s.campo);
  const lin = {};
  const linha = (chave, rotulo) => lin[chave] || (lin[chave] = { rotulo, aportado: 0, ativo: 0, rend: 0, lucroNF: 0, retLucro: 0, devCap: 0 });
  base.forEach(s => linha(s.campo, s.rotulo));
  // aportes: capital de cada sócio + rendimento rateado pela fatia no aporte
  for (const a of APORTES) {
    const val = Number(a.valor) || 0; const rendA = calcApt(a).rend;
    for (const s of base) {
      const v = Number(a[s.campo]) || 0; if (!v) continue;
      const L = linha(s.campo, s.rotulo);
      L.aportado += v; if (!dataQuitacaoAporteValida(a)) L.ativo += v;
      if (val > 0) L.rend += rendA * (v / val);
    }
  }
  // percentuais: lucro por NF (campos ricardo/marcelo/fernando)
  for (const p of PERCENTUAIS) {
    for (const s of base) { const v = Number(p[s.campo]) || 0; if (v) linha(s.campo, s.rotulo).lucroNF += v; }
  }
  // retiradas: por nome do sócio (casa pelo rótulo; nomes desconhecidos viram linha própria)
  for (const r of RETIRADAS) {
    const v = Number(r.valor) || 0; if (!v) continue;
    const campo = porChave[APT_SOCIOS_NORM(r.socio)];
    const L = campo ? linha(campo, base.find(b => b.campo === campo).rotulo) : linha('x_' + APT_SOCIOS_NORM(r.socio), r.socio || '—');
    if (r.tipo === 'Devolução de capital') L.devCap += v; else L.retLucro += v;
  }
  const linhas = Object.values(lin).filter(L => L.aportado || L.ativo || L.rend || L.lucroNF || L.retLucro || L.devCap)
    .sort((a, b) => b.ativo - a.ativo);
  const head = `<thead><tr><th>Sócio</th><th class="num">Capital aportado</th><th class="num">Capital ativo</th><th class="num">Rendimentos</th><th class="num">Lucro (NF)</th><th class="num">Retiradas (lucro)</th><th class="num">Devoluções</th></tr></thead>`;
  if (!linhas.length) { tab.innerHTML = head + `<tbody><tr><td colspan="7" class="vazio-cel">Sem dados de sócios ainda.</td></tr></tbody>`; return; }
  const cel = (v) => `<td class="num">${v ? fmtMoneyDec(v) : '<span class="apt-zero">—</span>'}</td>`;
  const corpo = linhas.map(L => `<tr><td>${esc(L.rotulo)}</td>${cel(L.aportado)}${cel(L.ativo)}${cel(L.rend)}${cel(L.lucroNF)}${cel(L.retLucro)}${cel(L.devCap)}</tr>`).join('');
  const T = (k) => linhas.reduce((s, L) => s + L[k], 0);
  const tot = `<tr class="total"><td>TOTAL</td><td class="num">${fmtMoneyDec(T('aportado'))}</td><td class="num">${fmtMoneyDec(T('ativo'))}</td><td class="num">${fmtMoneyDec(T('rend'))}</td><td class="num">${fmtMoneyDec(T('lucroNF'))}</td><td class="num">${fmtMoneyDec(T('retLucro'))}</td><td class="num">${fmtMoneyDec(T('devCap'))}</td></tr>`;
  tab.innerHTML = head + `<tbody>${corpo}${tot}</tbody>`;
}

// ---- Dashboard consolidado: Empréstimos — saldo por contrato (quem deve a quem, em aberto) ----
function renderDashEmprestimos() {
  const tab = document.getElementById('tabelaEmpSaldo'); if (!tab) return;
  const saldoAb = (e) => Math.max(0, (Number(e.valor) || 0) - (Number(e.valorPago) || 0));
  const cont = {};
  const get = (nome) => cont[nome] || (cont[nome] = { nome, recebe: 0, paga: 0 });
  for (const e of EMPRESTIMOS) {
    if (empQuitado(e)) continue;
    const s = saldoAb(e); if (!s) continue;
    if (e.origem) get(e.origem).recebe += s; // emprestou → tem a receber
    if (e.destino) get(e.destino).paga += s; // tomou → tem a pagar
  }
  const linhas = Object.values(cont).map(c => ({ ...c, saldo: c.recebe - c.paga }))
    .filter(c => c.recebe || c.paga).sort((a, b) => b.saldo - a.saldo);
  const head = `<thead><tr><th>Contrato</th><th class="num">A receber</th><th class="num">A pagar</th><th class="num">Saldo líquido</th></tr></thead>`;
  if (!linhas.length) { tab.innerHTML = head + `<tbody><tr><td colspan="4" class="vazio-cel">Nenhum empréstimo em aberto.</td></tr></tbody>`; return; }
  const cel = (v) => `<td class="num">${v ? fmtMoneyDec(v) : '<span class="apt-zero">—</span>'}</td>`;
  const corpo = linhas.map(c => {
    const cor = c.saldo > 0 ? 'apt-quitado' : (c.saldo < 0 ? 'apt-aberto' : '');
    const saldo = `<td class="num"><span class="apt-pill ${cor}">${c.saldo >= 0 ? '' : '−'}${fmtMoneyDec(Math.abs(c.saldo))}</span></td>`;
    return `<tr><td>${esc(c.nome)}</td>${cel(c.recebe)}${cel(c.paga)}${saldo}</tr>`;
  }).join('');
  const tr = linhas.reduce((s, c) => s + c.recebe, 0), tp = linhas.reduce((s, c) => s + c.paga, 0);
  const tot = `<tr class="total"><td>TOTAL</td><td class="num">${fmtMoneyDec(tr)}</td><td class="num">${fmtMoneyDec(tp)}</td><td class="num">${fmtMoneyDec(tr - tp)}</td></tr>`;
  tab.innerHTML = head + `<tbody>${corpo}${tot}</tbody>`;
}

// ---- Resumo legível "quem deve a quem" (a partir dos empréstimos em aberto) ----
// Agrega o saldo em aberto por par devedor→credor (destino tomou de origem) e monta frases.
function renderDashEmpDeveQuem() {
  const host = document.getElementById('empResumoDeveQuem'); if (!host) return;
  const saldoAb = (e) => Math.max(0, (Number(e.valor) || 0) - (Number(e.valorPago) || 0));
  const pares = {};
  for (const e of EMPRESTIMOS) {
    if (empQuitado(e)) continue;
    const s = saldoAb(e); if (!s || !e.origem || !e.destino) continue;
    const k = e.destino + '' + e.origem; // destino DEVE a origem
    pares[k] = (pares[k] || 0) + s;
  }
  const frases = Object.entries(pares)
    .map(([k, v]) => { const [devedor, credor] = k.split(''); return { devedor, credor, v }; })
    .sort((a, b) => b.v - a.v);
  if (!frases.length) { host.innerHTML = ''; return; }
  host.innerHTML = `<div class="emp-resumo-tit">Quem deve a quem (em aberto)</div>` +
    frases.map(f => `<div class="emp-deve-linha"><b>${esc(f.devedor)}</b> está devendo ao contrato <b>${esc(f.credor)}</b> o valor de <b>${fmtMoneyDec(f.v)}</b></div>`).join('');
}

