      formApt.elements['taxaMes'].value = a.taxaJuros ? +diaParaMesPct(a.taxaJuros).toFixed(4) : '';
      APT_SOCIOS.forEach(s => { formApt.elements[s.campo].value = valorParaCampo(a[s.campo]); });
      formApt.elements['dataQuitacao'].value = a.dataQuitacao || '';
