if (formApt) formApt.addEventListener('submit', async (e) => {
  e.preventDefault();
  const dados = {
    data: formApt.elements['data'].value.trim(),
    grupo: formApt.elements['grupo'].value.trim(),
    contrato: formApt.elements['contrato'].value.trim(),
    valor: numBR(formApt.elements['valor'].value) || 0,
    taxaJuros: mesPctParaDia(formApt.elements['taxaMes'].value),
    dataQuitacao: formApt.elements['dataQuitacao'].value.trim(),
    obs: formApt.elements['obs'].value.trim(),
  };
  APT_SOCIOS.forEach(s => { dados[s.campo] = numBR(formApt.elements[s.campo].value) || 0; });
  if (!dados.data || !dados.valor) { toast('Informe pelo menos a data e o valor do aporte.', 'erro'); return; }
  if (!parseBR(dados.data)) { formApt.elements['data'].focus(); toast(erroDataBR(dados.data), 'erro'); return; }
  if (dados.dataQuitacao) {
    const dtQuit = parseBR(dados.dataQuitacao);
    if (!dtQuit || dtQuit.getFullYear() < 2020) { formApt.elements['dataQuitacao'].focus(); toast('Data de quitação inválida · use dd/mm/aaaa.', 'erro'); return; }
  }
  const url = editandoAporteId ? '/api/aportes/' + encodeURIComponent(editandoAporteId) : '/api/aportes';
  const btn = formApt.querySelector('button[type="submit"]'); if (btn.disabled) return; btn.disabled = true;
  try {
    const r = await fetch(url, { method: editandoAporteId ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(dados) });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) { toast(j.erro || 'Erro ao salvar.', 'erro'); return; }
    fecharAporteModal();
    await carregarAportes();
    toast(editandoAporteId ? 'Aporte atualizado.' : 'Aporte adicionado!', 'ok');
  } finally { btn.disabled = false; }
});
async function importarPlanilhasControle({ botao, input, url, recarregar, rotulo }) {
  botao.onclick = () => input.click();
  input.onchange = async () => {
    const files = Array.from(input.files || []); input.value = '';
    if (!files.length) return;
    const fd = new FormData();
    files.forEach(file => fd.append('arquivos', file));
    botao.disabled = true; const txt = botao.textContent; botao.textContent = 'Importando...';
    try {
      const r = await fetch(url, { method: 'POST', body: fd });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) { toast(j.erro || `Erro ao importar ${rotulo}.`, 'erro'); return; }
      await recarregar();
      const extra = j.arquivos ? ` em ${j.arquivos} arquivo(s)` : '';
      toast(`${rotulo}: ${j.criados || 0} novo(s), ${j.atualizados || 0} atualizado(s)${extra}.`, 'ok');
    } catch (err) {
      toast(`Falha de conexão ao importar ${rotulo}.`, 'erro');
    } finally {
      botao.disabled = false; botao.textContent = txt;
    }
  };
}
