/* ============================================================
   CONTROLES › RETIRADAS (lucro / devolução de capital)
   ============================================================ */
const filtroCardRet = { v: '' }; // '' | 'Lucro' | 'Devolução de capital'
async function carregarRetiradas() {
  try { const r = await fetch('/api/retiradas', { cache: 'no-store' }); if (r.status === 401) { window.location = '/login'; return; } if (r.ok) RETIRADAS = await r.json(); }
  catch (e) { /* mantém */ }
  renderRetiradas();
}
function popularFiltrosRet() {
  if (MSEL.frSocio) MSEL.frSocio.setOpcoes([...new Set(RETIRADAS.map(r => r.socio).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'pt-BR')));
  if (MSEL.frTipo) MSEL.frTipo.setOpcoes(['Lucro', 'Devolução de capital']);
}
function retFiltradas() {
  const q = (document.getElementById('buscaRet')?.value || '').trim().toLowerCase();
  const fS = getSel('frSocio'), fT = getSel('frTipo');
  return RETIRADAS.filter(r => {
    if (fS.length && !fS.includes(r.socio)) return false;
    if (fT.length && !fT.includes(r.tipo)) return false;
    if (filtroCardRet.v && r.tipo !== filtroCardRet.v) return false;
    if (q && ![r.socio, r.tipo, r.grupo, r.data, r.valor, r.obs].join(' ').toLowerCase().includes(q)) return false;
    return true;
  });
}
function renderCardsRet() {
  const cont = document.getElementById('cardsRet'); if (!cont) return;
  const soma = (arr) => arr.reduce((s, r) => s + (Number(r.valor) || 0), 0);
  const lucro = RETIRADAS.filter(r => r.tipo === 'Lucro');
  const devol = RETIRADAS.filter(r => r.tipo === 'Devolução de capital');
  const at = (alvo) => filtroCardRet.v === alvo ? ' card-ativo' : '';
  cont.innerHTML = `
    ${cardV2('Retiradas', RETIRADAS.length, 'card-clic' + at(''), false, 'data-card="TODAS"')}
    ${cardV2('Total retirado', fmtMoneyDec(soma(RETIRADAS)), '', true)}
    ${cardV2('Lucro', `${lucro.length} • ${fmtMoneyDec(soma(lucro))}`, 'green card-clic' + at('Lucro'), false, 'data-card="Lucro"')}
    ${cardV2('Devolução de capital', `${devol.length} • ${fmtMoneyDec(soma(devol))}`, 'amber card-clic' + at('Devolução de capital'), false, 'data-card="Devolução de capital"')}`;
  cont.querySelectorAll('.v2-kpi[data-card]').forEach(c => {
    c.setAttribute('role', 'button'); c.tabIndex = 0;
    const aplicar = () => { const a = c.dataset.card; filtroCardRet.v = (a === 'TODAS' || filtroCardRet.v === a) ? '' : a; renderRetiradas(); };
    c.onclick = aplicar; c.onkeydown = (ev) => { if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); aplicar(); } };
  });
}
function renderRetiradas() {
  popularFiltrosRet(); renderCardsRet();
  const lista = retFiltradas().slice().sort((a, b) => (parseBR(b.data)?.getTime() || 0) - (parseBR(a.data)?.getTime() || 0));
  const podeExcluir = permissaoAtual('controles') === 'editar';
  const cab = document.getElementById('cabecalhoRet');
  if (cab) cab.innerHTML = [
    { h: 'Ações', acoes: true }, { h: 'Data' }, { h: 'Sócio' }, { h: 'Tipo' },
    { h: 'Valor', num: true }, { h: 'Centro de Custo' },
  ].map(c => `<th${c.acoes ? ' class="col-acoes"' : (c.num ? ' class="num"' : '')}>${esc(c.h)}</th>`).join('');
  estadoVazio('retVazio', RETIRADAS.length, lista.length, 'Nenhuma retirada cadastrada ainda.', () => limparFiltrosRet());
  const corpo = document.getElementById('corpoRet');
  if (corpo) corpo.innerHTML = lista.map(r => {
    const pill = r.tipo === 'Lucro' ? '<span class="apt-pill ret-lucro">Lucro</span>' : '<span class="apt-pill ret-devolucao">Devolução de capital</span>';
    return `<tr data-id="${esc(r.id)}">
      <td class="acoes"><button class="edit edit-ret" data-id="${esc(r.id)}" title="Editar" aria-label="Editar">${ICONE_LAPIS}</button>${podeExcluir ? `<button class="del del-ret" data-id="${esc(r.id)}" title="Excluir" aria-label="Excluir">${ICONE_LIXEIRA}</button>` : ''}</td>
      <td>${esc(fmtData(r.data))}</td>
      <td>${esc(r.socio) || '<span class="apt-zero">—</span>'}</td>
      <td>${pill}</td>
      <td class="num">${fmtMoneyDec(r.valor)}</td>
      <td>${esc(r.grupo) || '<span class="apt-zero">—</span>'}</td>
    </tr>`;
  }).join('');
  const host = document.getElementById('resumoRet');
  if (host) {
    const soma = (arr) => arr.reduce((s, r) => s + (Number(r.valor) || 0), 0);
    const lucro = lista.filter(r => r.tipo === 'Lucro'), devol = lista.filter(r => r.tipo === 'Devolução de capital');
    host.innerHTML = `Exibindo <b>${lista.length}</b> de <b>${RETIRADAS.length}</b> &nbsp;•&nbsp; Total (filtro): <b>${fmtMoneyDec(soma(lista))}</b> &nbsp;•&nbsp; Lucro: <b>${fmtMoneyDec(soma(lucro))}</b> &nbsp; Devolução: <b>${fmtMoneyDec(soma(devol))}</b>`;
  }
}
function limparFiltrosRet() {
  filtroCardRet.v = ''; const b = document.getElementById('buscaRet'); if (b) b.value = '';
  ['frSocio', 'frTipo'].forEach(id => MSEL[id] && MSEL[id].limpar());
  renderRetiradas();
}
