function rotuloContrato(c) {
  return [c && c.nome, (c && c.numero) ? ('Nº ' + c.numero) : '', c && c.local].filter(Boolean).join(' · ');
}
// Um rótulo por contrato vinculado (p/ o filtro casar cada contrato separadamente).
function contratosRotulos(f) { const rs = contratosDoFunc(f).map(rotuloContrato).filter(Boolean); return rs.length ? rs : ['Sem contrato']; }
// Rótulo de EXIBIÇÃO/ordenação: contrato principal + "(+N)" quando há vínculos extras.
function contratoRotulo(f) {
  const rs = contratosDoFunc(f).map(rotuloContrato).filter(Boolean);
  if (!rs.length) return 'Sem contrato';
  return rs.length === 1 ? rs[0] : `${rs[0]} (+${rs.length - 1})`;
}
function funcTemFiltro() {
  return !!(funcEstado.busca || rapidoFuncAtivo() || funcEstado.admDe || funcEstado.admAte || getSel('ffEmpresa').length || getSel('ffContrato').length || getSel('ffSituacao').length);
}
function funcFiltrados(comRapido = true) {
  const termo = funcEstado.busca.trim().toLowerCase();
  const empresas = getSel('ffEmpresa'), contratos = getSel('ffContrato'), situacoes = getSel('ffSituacao');
  return FUNCIONARIOS.filter(f => {
    if (!podeVerFuncEu(f)) return false; // acesso por empresa (defesa em profundidade; a API já filtra)
    if (funcEstado.drill) { // drill-down de uma frente específica (contrato + local)
      if (funcEstado.contrato === ESC_SENTINEL) { // cartão Escritório: empresa (local=sigla) + setor Escritório
        if (empresaSiglaFunc(f.empresa) !== (funcEstado.local || '')) return false;
        if (!ehFuncEscritorio(f)) return false;
      } else {
        // Só aparece no drill do seu contrato PRINCIPAL (secundários não listam a pessoa).
        if (!ehContratoPrincipal(f, funcEstado.contrato, funcEstado.local || '')) return false;
      }
    }
    // O filtro rápido (chip) só faz sentido nas listas de pessoas (Cartões/Detalhes). Os cartões de
    // indicadores (statsFunc) chamam com comRapido=false p/ refletir só empresa/contrato/situação.
    if (comRapido && rapidoFuncAtivo() && !passaRapidoFunc(f, funcEstado.rapido)) return false;
    if (empresas.length && !empresas.includes(f.empresa || '')) return false;
    if (situacoes.length && !situacoes.includes(f.status || 'Ativo')) return false;
    if (contratos.length && !contratosRotulos(f).some(r => contratos.includes(r))) return false;
    // Período de admissão (mês/ano AAAA-MM): compara pelo prefixo do admissao (AAAA-MM-DD → AAAA-MM),
    // p/ o "até" incluir quem entrou no próprio mês. Sem data de admissão fica de fora quando há limite.
    if (funcEstado.admDe || funcEstado.admAte) {
      const admMes = (f.admissao || '').slice(0, 7);
      if (!admMes) return false;
      if (funcEstado.admDe && admMes < funcEstado.admDe) return false;
      if (funcEstado.admAte && admMes > funcEstado.admAte) return false;
    }
    if (!termo) return true;
    // busca inclui TODOS os contratos vinculados (não só o principal), p/ achar por contrato secundário
    const campos = [f.nome, f.cargo, f.empresa, f.cpf, f.matricula, f.telefone, ...contratosDoFunc(f).flatMap(c => [c.numero, c.nome, c.local])];
    return campos.some(c => (c || '').toLowerCase().includes(termo));
  });
}
// Popula as opções dos multi-selects (Empresa, Contrato, Situação) a partir dos dados atuais.
function popularFiltrosFunc() {
  // Acesso por empresa: o filtro de empresa só aparece para quem vê mais de uma; opções limitadas ao que ele pode ver.
  const setEmp = empresasFuncEu();
  const ffEl = document.getElementById('ffEmpresa');
  if (ffEl) ffEl.hidden = (setEmp !== null && setEmp.size <= 1);
  if (MSEL.ffEmpresa) MSEL.ffEmpresa.setOpcoes(
    [...new Set([...empresasCatalogoFunc(), ...FUNCIONARIOS.map(f => f.empresa).filter(Boolean)])]
      .filter(e => setEmp === null || setEmp.has(empresaSiglaFunc(e)))
  );
  if (MSEL.ffContrato) MSEL.ffContrato.setOpcoes([...new Set(FUNCIONARIOS.flatMap(contratosRotulos))].sort((a, b) => a.localeCompare(b, 'pt-BR')));
  if (MSEL.ffSituacao) MSEL.ffSituacao.setOpcoes(['Ativo', 'Afastado', 'Férias']); // "Desligado" tem aba própria (Desmobilizados)
}
