function mascararCPF(v) { v = String(v).replace(/\D/g, '').slice(0, 11); return v.replace(/(\d{3})(\d)/, '$1.$2').replace(/(\d{3})(\d)/, '$1.$2').replace(/(\d{3})(\d{1,2})$/, '$1-$2'); }
function mascararTelefone(v) { v = String(v).replace(/\D/g, '').slice(0, 11); if (v.length <= 10) return v.replace(/(\d{2})(\d)/, '($1) $2').replace(/(\d{4})(\d)/, '$1-$2'); return v.replace(/(\d{2})(\d)/, '($1) $2').replace(/(\d{5})(\d)/, '$1-$2'); }
function mascararCEP(v) { v = String(v).replace(/\D/g, '').slice(0, 8); return v.replace(/(\d{5})(\d)/, '$1-$2'); }
// 11 dígitos + dígitos verificadores válidos.
function cpfValido(cpf) {
  cpf = String(cpf).replace(/\D/g, '');
  if (cpf.length !== 11 || /^(\d)\1{10}$/.test(cpf)) return false;
  const dv = (base) => { let s = 0; for (let i = 0; i < base.length; i++) s += +base[i] * (base.length + 1 - i); const r = (s * 10) % 11; return r === 10 ? 0 : r; };
  return dv(cpf.slice(0, 9)) === +cpf[9] && dv(cpf.slice(0, 10)) === +cpf[10];
}
