async function renderFuncAdmFicha(id) {
  const box = document.getElementById('funcAdmFichaBox');
  if (!box) return;
  box.hidden = true;
  if (!id) return;
  let info = null;
  try {
    const r = await fetch('/api/funcionarios/' + encodeURIComponent(id) + '/admissao', { cache: 'no-store' });
    if (r.ok) info = await r.json();
  } catch (e) { /* sem rede: não mostra o bloco */ }
  if (!info || !info.temFicha) return;
  const meta = document.getElementById('funcAdmFichaMeta');
  if (meta) meta.textContent = info.preenchidoTs ? ` · enviado em ${new Date(info.preenchidoTs).toLocaleDateString('pt-BR')}${info.qtdDocs ? ' · ' + info.qtdDocs + ' doc(s)' : ''}` : '';
  const base = '/api/funcionarios/' + encodeURIComponent(id) + '/admissao/ficha.pdf';
  const bVer = document.getElementById('btnFuncAdmVer');
  if (bVer) bVer.onclick = () => { const w = window.open(base + '?ver=1', '_blank', 'noopener'); if (!w) toast('Seu navegador bloqueou a aba. Libere o pop-up para ver o formulário.', 'erro'); };
  const bBx = document.getElementById('btnFuncAdmBaixar');
  if (bBx) bBx.onclick = () => baixarArquivoServidor(base, 'FICHA_ADMISSAO_' + (((info.nome || 'funcionario').replace(/[^\w\s.-]/g, '').trim().replace(/\s+/g, '_')) || 'funcionario') + '.pdf', 'Gerando o formulário preenchido em PDF…');
  box.hidden = false;
}
