  // permitindo trocar OU remover (o ✕ no documento) sem ficar travado. Obrigatórios só
  // valem ao CONCLUIR a demissão (Ativo → Desligado).
  const jaDesligado = (f.status === 'Desligado');
  formDesmob.classList.toggle('modo-atualizar', jaDesligado);
  document.getElementById('desmobTitulo').textContent = jaDesligado ? 'Atualizar desmobilização' : 'Desmobilizar colaborador';
  const aviso = document.getElementById('desmobAviso');
