  document.getElementById('documentoModalTitulo').textContent = editando ? 'Editar documento' : 'Enviar arquivos';
  document.getElementById('documentoModalAjuda').textContent = editando ? 'Atualize os dados ou substitua o arquivo.' : 'Selecione um ou mais arquivos; PDF, imagem, Word, Excel, PowerPoint, CSV, TXT ou ZIP.';
  document.getElementById('documentoTituloCampo').hidden = !editando;
  f.elements.titulo.required = editando;
  f.elements.arquivo.multiple = !editando;
  f.elements.arquivo.required = !editando;
  document.getElementById('documentoArquivoRotulo').textContent = editando ? 'Substituir arquivo (opcional)' : 'Arquivo(s) (máx. 9 MB cada)';
  if (item) ['titulo', 'categoria', 'validade', 'descricao'].forEach(k => { f.elements[k].value = item[k] || ''; });
  document.getElementById('documentoDestino').textContent = `Salvar em: ${rotuloCaminhoPastaDocumento(pastaDocumentoAtualId)}`;
  const atualP = document.getElementById('documentoArquivoAtual');
