document.getElementById('documentoPastas').onclick = async (e) => {
  const card = e.target.closest('[data-pasta-id]'); if (!card) return;
  const pasta = pastaDocumentoPorId(card.dataset.pastaId); if (!pasta) return;
  const acao = e.target.closest('[data-pasta-acao]');
  if (acao?.dataset.pastaAcao === 'renomear') return abrirPastaDocumentoModal(pasta);
  if (acao?.dataset.pastaAcao === 'excluir') {
    if (!(await confirmar(`Excluir a pasta “${pasta.nome}”? Ela precisa estar vazia.`, { perigo: true, okTexto: 'Excluir' }))) return;
    const r = await fetch(`/api/documentos/pastas/${encodeURIComponent(pasta.id)}`, { method: 'DELETE' });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) return toast(j.erro || 'Não foi possível excluir a pasta.', 'erro');
    await carregarDocumentosEmpresa(); toast('Pasta excluída.', 'ok'); return;
  }
  if (e.target.closest('[data-abrir-pasta]')) {
    CAMINHO_DOCUMENTOS.push(pasta.id);
    document.getElementById('documentoBusca').value = '';
    renderDocumentosEmpresa();
  }
};
document.getElementById('documentoCards').onclick = async (e) => {
  const b = e.target.closest('[data-acao]'), card = e.target.closest('[data-id]'); if (!b || !card) return;
  const item = DOCUMENTOS_EMPRESA.find(d => d.id === card.dataset.id); if (!item) return;
  if (b.dataset.acao === 'mover') return abrirMoverDocumentoModal(item);
  if (b.dataset.acao === 'editar') return abrirDocumentoModal(item);
  if (!(await confirmar(`Excluir “${item.titulo}” e o arquivo anexado?`, { perigo: true, okTexto: 'Excluir' }))) return;
  const r = await fetch(`/api/documentos/${encodeURIComponent(item.id)}`, { method: 'DELETE' });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) return toast(j.erro || 'Não foi possível excluir o documento.', 'erro');
  await carregarDocumentosEmpresa();
  toast('Documento excluído.', 'ok');
};
document.getElementById('formPastaDocumento').onsubmit = async (e) => {
  e.preventDefault();
  const f = e.currentTarget, nome = f.elements.nome.value.trim();
  const editando = !!editandoPastaDocumentoId;
  const url = editandoPastaDocumentoId ? `/api/documentos/pastas/${encodeURIComponent(editandoPastaDocumentoId)}` : '/api/documentos/pastas';
  const body = editandoPastaDocumentoId ? { nome } : { nome, pastaPaiId: pastaDocumentoAtualIdAberta() };
  const r = await fetch(url, { method: editandoPastaDocumentoId ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) return toast(j.erro || 'Não foi possível salvar a pasta.', 'erro');
  fecharPastaDocumentoModal(); await carregarDocumentosEmpresa(); toast(editando ? 'Pasta renomeada.' : 'Pasta criada!', 'ok');
};
document.getElementById('formMoverDocumento').onsubmit = async (e) => {
  e.preventDefault();
  const f = e.currentTarget;
  const r = await fetch(`/api/documentos/${encodeURIComponent(movendoDocumentoId)}/mover`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ pastaId: f.elements.pastaId.value }) });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) return toast(j.erro || 'Não foi possível mover o arquivo.', 'erro');
  fecharMoverDocumentoModal(); await carregarDocumentosEmpresa(); toast('Arquivo movido.', 'ok');
};
document.getElementById('formDocumento').onsubmit = async (e) => {
  e.preventDefault();
  const f = e.currentTarget, files = [...f.elements.arquivo.files], editando = !!editandoDocumentoId;
  if (!files.length && !arquivoDocumentoAtual) return toast('Selecione ao menos um arquivo.', 'erro');
  for (const file of files) if (file.size > 9 * 1024 * 1024) return toast(`${file.name}: arquivo muito grande (máx. 9 MB).`, 'erro');
  const btn = f.querySelector('button[type="submit"]'), textoBtn = btn.textContent;
  btn.disabled = true; btn.textContent = 'Salvando...';
  try {
    if (editando) {
      let arquivo = arquivoDocumentoAtual;
      if (files[0]) {
        const fd = new FormData(); fd.append('arquivos', files[0]);
        const ur = await fetch('/api/documentos/midia', { method: 'POST', body: fd });
        const uj = await ur.json().catch(() => ({}));
        if (!ur.ok) throw new Error(uj.erro || 'Não foi possível enviar o arquivo.');
        arquivo = uj.enviados[0];
      }
      const body = { pastaId: pastaDocumentoAtualId, titulo: f.elements.titulo.value.trim(), categoria: f.elements.categoria.value.trim(), validade: f.elements.validade.value, descricao: f.elements.descricao.value.trim(), arquivo };
      const r = await fetch(`/api/documentos/${encodeURIComponent(editandoDocumentoId)}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.erro || 'Não foi possível salvar o documento.');
      toast('Documento atualizado.', 'ok');
    } else {
      const fd = new FormData();
      for (const file of files) fd.append('arquivos', file);
      const ur = await fetch('/api/documentos/midia', { method: 'POST', body: fd });
      const uj = await ur.json().catch(() => ({}));
      if (!ur.ok) throw new Error(uj.erro || 'Não foi possível enviar os arquivos.');
      const itens = uj.enviados.map(arq => ({ titulo: nomeSemExtensao(arq.nome), arquivo: arq }));
      const body = { pastaId: pastaDocumentoAtualId, categoria: f.elements.categoria.value.trim(), validade: f.elements.validade.value, descricao: f.elements.descricao.value.trim(), itens };
      const r = await fetch('/api/documentos/lote', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.erro || 'Não foi possível salvar os documentos.');
      const falhas = uj.erros && uj.erros.length ? ` (${uj.erros.length} arquivo(s) recusado(s): ${uj.erros[0]})` : '';
      toast(`${j.length} arquivo(s) adicionado(s)!${falhas}`, uj.erros && uj.erros.length ? 'erro' : 'ok');
    }
    fecharDocumentoModal();
    await carregarDocumentosEmpresa();
  } catch (err) { toast(err.message || 'Erro ao salvar.', 'erro'); }
  finally { btn.disabled = false; btn.textContent = textoBtn; }
};

/* ============================================================
   PERMISSÕES DE ABAS (por usuário comum); definidas pelo admin.
   Admin e modo local (sem login) têm acesso total. Áreas: ver o servidor.
   'inicio' é sempre visível; 'usuarios' é sempre só admin → não entram aqui.
   ============================================================ */
const AREA_ROTULOS = {
  frota: 'Frota', multas: 'Multas', rastreadores: 'Rastreadores', instalacoes: 'Instalações',
  manutencao: 'Manutenção', abastecimento: 'Abastecimento', fornecedores: 'Fornecedores', locacoes: 'Locações',
  funcionarios: 'Funcionários', almoxarifado: 'Almoxarifado', epi: 'EPI - Controle', admissao: 'Form. Admissão', integracao: 'Integração', programas: 'Programas SST', acoesSst: 'Ações de Segurança',
  simulador: 'Simulador', contratos: 'Contratos', cartoes: 'Cartões', controles: 'Controles', contabilidade: 'Contabilidade', investimentos: 'Investimentos', custos: 'Custos',
  senhas: 'Senhas', documentos: 'Documentos', ti: 'Inventário de TI', feedback: 'Feedback', cadastros: 'Cadastros',
};
// Grupos das abas no painel de Permissões — MESMA organização da sidebar (Operação/Pessoal/
// Financeiro/Comunidade/Cadastros), pra ficar fácil de achar. Cobre todas as chaves de AREA_ROTULOS.
const GRUPOS_PERM = [
  { titulo: 'Operação', areas: ['frota', 'multas', 'rastreadores', 'instalacoes', 'manutencao', 'abastecimento', 'fornecedores', 'locacoes'] },
  { titulo: 'Segurança do Trabalho', areas: ['funcionarios', 'almoxarifado', 'epi', 'admissao', 'integracao', 'programas', 'acoesSst'] },
  { titulo: 'Financeiro', areas: ['simulador', 'contratos', 'cartoes', 'controles', 'contabilidade', 'investimentos', 'custos'] },
  { titulo: 'Administração', areas: ['senhas', 'documentos', 'ti'] },
  { titulo: 'Comunidade', areas: ['feedback'] },
  { titulo: 'Cadastros', areas: ['cadastros'] },
];
// Permissão do usuário atual numa área ('editar' | 'ver' | 'nenhum'). Admin/local → 'editar'.
function permissaoAtual(area) {
  if (!EU || !EU.loginAtivo || ehNivelAdmin(EU.nivel)) return 'editar';
  const p = EU.permissoes && EU.permissoes[area];
  if ((area === 'senhas' || area === 'documentos') && p === undefined) return 'nenhum';
  return (p === 'ver' || p === 'nenhum') ? p : 'editar';
}

// Sigla canônica da empresa de um colaborador ('NTE' | 'SUL' | outro). Espelha empresaSigla() do server.
function empresaSiglaFunc(s) {
  const t = String(s == null ? '' : s).trim().toUpperCase();
  if (t.startsWith('NTE') || t.startsWith('NORTE')) return 'NTE';
  if (t.startsWith('SUL')) return 'SUL';
  return t;
}
// Empresas que o usuário atual pode ver na aba Funcionários (espelha empresasFuncPermitidas do server).
//   null = todas (admin/local) · Set([]) = nenhuma · Set(['NTE'|'SUL']) = só aquela.
function empresasFuncEu() {
  // try/catch: esta função é chamada por opcoesContratoHTML()/montarOpcoesContratoMsel() já no
  // carregamento do script, ANTES de `let EU` ser inicializado — ler EU aí lança ReferenceError
  // (TDZ). Nesse momento tratamos como acesso total (null); abrirFuncModal reaplica o filtro depois.
  let eu; try { eu = EU; } catch (e) { return null; }
  if (!eu || !eu.loginAtivo || ehNivelAdmin(eu.nivel)) return null;
  const v = eu.empresasFunc;
  if (v === 'ambas') return null;
  if (v === 'NTE' || v === 'SUL') return new Set([v]);
  return new Set();
}
// Contratos que o usuário atual pode ver (espelha contratosFuncPermitidos do server).
//   null = sem restrição de contrato (todos os da empresa) · Set([...]) = só esses números.
function contratosFuncEu() {
  let eu; try { eu = EU; } catch (e) { return null; } // TDZ-safe (ver empresasFuncEu)
  if (!eu || !eu.loginAtivo || ehNivelAdmin(eu.nivel)) return null;
  const arr = Array.isArray(eu.contratosFunc) ? eu.contratosFunc.map(String).filter(Boolean) : [];
  return arr.length ? new Set(arr) : null;
}
// O usuário atual pode ver ESTE colaborador? Combina empresa + contrato (espelha podeVerFunc do server).
// Sem empresa: aparece p/ quem tem acesso a alguma empresa (não p/ "Nenhuma"). Sem contrato: aparece sempre.
function podeVerFuncEu(f) {
  const setE = empresasFuncEu();
  if (setE !== null) {
    if (setE.size === 0) return false;                 // "Nenhuma": não vê nada
    const e = empresaSiglaFunc(f && f.empresa);
    if (e && !setE.has(e)) return false;               // tem empresa não permitida (sem empresa passa)
  }
  const setC = contratosFuncEu();
  if (setC !== null) {
    // Vê se QUALQUER vínculo for permitido. Setor Escritório equivale ao contrato administrativo
    // da empresa, inclusive nos cadastros antigos sem vínculo explícito.
    const nums = contratosDoFunc(f).map(c => String(c.numero || '')).filter(Boolean);
    const empresa = empresaSiglaFunc(f && f.empresa);
    if (ehFuncEscritorio(f) && empresa) nums.push(`ESCRITORIO-${empresa}`);
    if (nums.length && !nums.some(n => setC.has(n))) return false;
  }
  return true;
}

// Marca/desmarca uma aba (view) como somente-leitura. O modo é dirigido por CSS na
// própria <div class="view"> (sobrevive a re-render do conteúdo) + um aviso no topo.
function definirViewSomenteLeitura(area, ro) {
  const view = document.getElementById(area);
  if (!view) return;
  view.classList.toggle('somente-leitura', !!ro);
  let banner = view.querySelector(':scope > .ro-banner');
  if (ro && !banner) {
    banner = document.createElement('div');
    banner.className = 'ro-banner';
    banner.innerHTML = '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z"/><circle cx="12" cy="12" r="3"/></svg><span>Modo somente leitura; você pode visualizar, mas não editar esta aba.</span>';
    view.insertBefore(banner, view.firstChild);
  } else if (!ro && banner) {
    banner.remove();
  }
}

// Aplica as permissões à navegação e às telas. Admin (e modo local) têm ACESSO TOTAL:
// todas as abas ficam visíveis e sem somente-leitura — isso desfaz qualquer restrição
// que a pessoa tinha antes de ser promovida a admin (sem precisar de F5).
function aplicarPermissoesAbas() {
  const acessoTotal = !EU || !EU.loginAtivo || ehNivelAdmin(EU.nivel);
  const perm = (EU && EU.permissoes) || {};
  // Acesso por empresa: sem nenhuma empresa liberada, a aba Funcionários (e a Admissão, que a
  // acompanha) não aparece — em vez de mostrar uma lista vazia. empresasFuncEu()===Set vazio = nenhuma.
  const setEmpFunc = empresasFuncEu();
  const semEmpresaFunc = !!(setEmpFunc && setEmpFunc.size === 0);
  Object.keys(AREA_ROTULOS).forEach(area => {
    let p = acessoTotal ? 'editar' : ((perm[area] === 'ver' || perm[area] === 'nenhum') ? perm[area] : ((area === 'senhas' || area === 'documentos') ? 'nenhum' : 'editar'));
    // Sem nenhuma empresa liberada, Funcionários e a Admissão (que lida com fichas) somem.
    if ((area === 'funcionarios' || area === 'admissao') && semEmpresaFunc) p = 'nenhum';
    const tab = document.querySelector(`.tab[data-tab="${area}"]`);
    if (tab) tab.hidden = (p === 'nenhum');
    definirViewSomenteLeitura(area, p === 'ver');
  });
  // Esconde grupos da sidebar que ficaram sem nenhuma aba visível.
  document.querySelectorAll('.nav-group').forEach(g => {
    g.hidden = ![...g.querySelectorAll('.tab')].some(t => !t.hidden);
  });
  // Se a aba ativa virou oculta, vai para uma permitida (Início é sempre visível).
  const ativa = document.querySelector('.tab.active');
  if (ativa && ativa.hidden) {
    const destino = document.querySelector('.tab[data-tab="inicio"]:not([hidden])')
      || [...document.querySelectorAll('.tab')].find(t => !t.hidden);
    // replace (não push): substitui a URL da aba proibida em vez de empurrar entrada morta no histórico
    if (destino) { const m = _navModo; _navModo = 'replace'; try { destino.click(); } finally { _navModo = m; } }
  }
  aplicarPermissoesInicio(); // atualiza os cards/aviso da tela Início
  sincronizarKebabs(); // menus "⋯" podem ter ficado vazios (ou voltado a ter itens)
  // A ação central do celular depende da permissão, que só chega aqui (depois do boot):
  // sem isto, quem tem 'ver' continuaria vendo o botão de cadastro aceso.
  atualizarBotaoAdicionarMobile();
}

// Mostra/esconde os recursos exclusivos de admin/dev (ou modo local sem login) de forma
// centralizada. Chamada no boot (carregarEu) e ao entrar/sair do "Ver como usuário comum".
// Devolve `ehAdminOuLocal` para quem precisa decidir outras coisas (ex.: carregar manutenção).
function aplicarVisibilidadeAdmin() {
  const ehAdminOuLocal = !!(EU && (ehNivelAdmin(EU.nivel) || EU.loginAtivo === false));
  const ehAdminReal = !!(EU && ehNivelAdmin(EU.nivel)); // aba Usuários é só admin/dev (não vale "local")
  // A engrenagem só tem itens de administração (o grupo "Sistemas" saiu; a troca de
  // sistema vive no botão do hub na topbar) → usuário comum nem vê o botão.
  const setH = (id, h) => { const el = document.getElementById(id); if (el) el.hidden = h; };
  setH('ferramentasWrap', !ehAdminOuLocal);
  setH('ferramentasAdminTitulo', !ehAdminOuLocal);
  setH('btnBackup', !ehAdminOuLocal);
  setH('manutToggleWrap', !ehAdminOuLocal);
  setH('btnDevPainel', !ehAdminOuLocal);
  setH('tabUsuarios', !ehAdminReal);
  setH('tabSeguranca', !ehAdminOuLocal); // admin/dev ou modo local (como o painel do desenvolvedor)
  // Botões de ação destrutiva/admin: escondidos para o usuário comum (o servidor já bloqueia,
  // mas mostrar só pra dar 403 confunde). Reaplicados nos dois sentidos → o preview restaura certo.
  ['btnLimparMultas', 'btnImportRast', 'btnCobliSync', 'histLimpar', 'histVeiculoLimpar', 'btnImportContr', 'selBarContrExcluir', 'btnImportMnt', 'btnBackupsMnt', 'btnBackupsRast', 'btnImportAbt', 'btnBackupsAbt', 'btnImportForn'].forEach((id) => setH(id, !ehAdminOuLocal));
  return ehAdminOuLocal;
}

/* ============================================================
   SEGURANÇA (admin/dev); 7 telas: Visão geral, Logs, Sessões,
   Bloqueios, Endpoints, Segredos, Configuração.
   ============================================================ */
let _segCarregou = false;
function carregarSeguranca() {
  // Carrega a sub-aba ativa; a 1ª visita renderiza a Visão geral.
  const ativa = document.querySelector('#seguranca .subview.active');
  segRenderSub(ativa ? ativa.id : 'seg-geral');
  _segCarregou = true;
}
function segRenderSub(id) {
  if (id === 'seg-geral') segCarregarGeral();
  else if (id === 'seg-logs') segCarregarLogs();
  else if (id === 'seg-sessoes') segCarregarSessoes();
  else if (id === 'seg-bloqueios') segCarregarBloqueios();
  else if (id === 'seg-endpoints') segCarregarEndpoints();
  else if (id === 'seg-segredos') segCarregarSegredos();
  else if (id === 'seg-config') segCarregarConfig();
}
document.querySelectorAll('#segSubtabs .subtab').forEach(b => b.addEventListener('click', () => {
  document.querySelectorAll('#segSubtabs .subtab').forEach(x => x.classList.remove('active'));
  document.querySelectorAll('#seguranca .subview').forEach(x => x.classList.remove('active'));
  b.classList.add('active');
  const sub = document.getElementById(b.dataset.sub);
  if (sub) sub.classList.add('active');
  segRenderSub(b.dataset.sub);
}));
async function segGet(ep) {
  const r = await fetch('/api/seguranca/' + ep, { cache: 'no-store' });
  if (!r.ok) throw new Error((await r.json().catch(() => ({}))).erro || ('erro ' + r.status));
  return r.json();
}
async function segMut(ep, metodo, corpo) {
  const r = await fetch('/api/seguranca/' + ep, { method: metodo, headers: corpo ? { 'Content-Type': 'application/json' } : undefined, body: corpo ? JSON.stringify(corpo) : undefined });
  const j = await r.json().catch(() => ({}));
  if (!r.ok || j.ok === false) throw new Error(j.erro || ('erro ' + r.status));
  return j;
}
function segTsBR(ts) { if (!ts) return '—'; const d = new Date(ts); return `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`; }
const SEG_SEV = { alerta: ['Alerta', 'vencido'], aviso: ['Aviso', 'avencer'], info: ['Info', 'ok'] };
function segSevBadge(sev) { const m = SEG_SEV[sev] || ['—', '']; return `<span class="func-doc-venc ${m[1]}">${m[0]}</span>`; }

// ---- Ordenação clicável das tabelas de Segurança (mesmo padrão das demais abas) ----
// Estado por tabela: { campo, dir } (dir 1 asc / -1 desc). Clicar no cabeçalho ordena;
// clicar de novo inverte. `tipo` decide a comparação: 'num' | 'data' | 'texto'.
const _segOrd = {
  log: { campo: 'ts', dir: -1 }, sess: { campo: 'desde', dir: -1 },
  bloq: { campo: 'ts', dir: -1 }, ep: { campo: 'path', dir: 1 },
};
function segOrdenar(arr, ord, cols) {
  const col = cols.find(c => c.campo === ord.campo);
  if (!col) return arr;
  const val = (o) => (col.calc ? col.calc(o) : o[ord.campo]);
  return arr.slice().sort((a, b) => {
    let x = val(a), y = val(b);
    if (col.tipo === 'num' || col.tipo === 'data') { x = Number(x) || 0; y = Number(y) || 0; return (x - y) * ord.dir; }
    return String(x == null ? '' : x).localeCompare(String(y == null ? '' : y), 'pt-BR') * ord.dir;
  });
}
// Preenche o <tr> de cabeçalho com colunas ordenáveis + a seta, e liga o clique.
function segMontarCabecalho(headId, cols, ord, reRender) {
  const head = document.getElementById(headId);
  if (!head) return;
  head.innerHTML = cols.map(c => c.campo
    ? `<th data-campo="${c.campo}" class="seg-th-sort" title="Ordenar por ${esc(c.rot)}">${esc(c.rot)}${iconeOrd(ord.campo === c.campo, ord.dir)}</th>`
    : `<th>${esc(c.rot || '')}</th>`).join('');
  head.querySelectorAll('th[data-campo]').forEach(th => th.onclick = () => {
    const campo = th.dataset.campo;
    if (ord.campo === campo) ord.dir *= -1; else { ord.campo = campo; ord.dir = 1; }
    reRender();
  });
}

// ---- 1 · Visão geral ----
