document.getElementById('segConfigForm').addEventListener('submit', async (e) => {
  e.preventDefault();
  const form = e.target;
  const corpo = {};
  for (const k of ['inatividadeMin', 'absolutoH', 'loginMaxTentativas', 'loginJanelaMin']) corpo[k] = Number(form.elements[k].value);
  const msg = document.getElementById('segConfigMsg');
  try {
    const d = await segMut('config', 'PUT', corpo);
    for (const k of Object.keys(d.config)) form.elements[k].value = d.config[k]; // reflete o valor saneado
    msg.textContent = 'Salvo · valendo agora.'; msg.className = 'seg-config-msg ok';
    toast('Configuração de segurança salva.', 'ok');
    setTimeout(() => { msg.textContent = ''; }, 4000);
  } catch (err) { msg.textContent = err.message; msg.className = 'seg-config-msg erro'; }
});

/* ============================================================
   PAINEL DO DESENVOLVEDOR (só admin/dev): diagnóstico + "ver como comum".
   ============================================================ */
function abrirDevPainel() {
  const m = document.getElementById('devPainelModal');
  if (!m) return;
  m.hidden = false;
  carregarDiagnostico();
  carregarServicosDev();
}
function fecharDevPainel() { const m = document.getElementById('devPainelModal'); if (m) m.hidden = true; }

// Painel de deploy: cada subserviço com bolinha (verde = respondeu, vermelho = falhou,
// cinza = não configurado) + o que a checagem viu + latência.
async function carregarServicosDev() {
  const box = document.getElementById('devServicos');
  if (!box) return;
  box.textContent = 'Verificando…';
  try {
    const r = await fetch('/api/dev/servicos', { cache: 'no-store' });
    if (!r.ok) { box.textContent = 'Não foi possível verificar os serviços.'; return; }
    const d = await r.json();
    box.innerHTML = (d.servicos || []).map(s => `
      <div class="dev-serv-linha">
        <span class="dev-serv-dot ${s.ok === true ? 'on' : (s.ok === false ? 'off' : '')}" title="${s.ok === true ? 'No ar' : (s.ok === false ? 'Falhou' : 'Não configurado')}"></span>
        <span class="dev-serv-nome">${esc(s.nome)}</span>
        <span class="dev-serv-info" title="${esc(s.info || '')}">${esc(s.info || '')}</span>
        <span class="dev-serv-ms">${s.ok === null ? '' : s.ms + ' ms'}</span>
      </div>`).join('') +
      `<div class="dev-serv-linha">
        <span class="dev-serv-dot ${d.sse > 0 ? 'on' : ''}"></span>
        <span class="dev-serv-nome">Tempo real (SSE)</span>
        <span class="dev-serv-info">${d.sse} conexão(ões) ao vivo</span>
        <span class="dev-serv-ms"></span>
      </div>`;
  } catch (e) { box.textContent = 'Erro ao verificar os serviços.'; }
}

async function carregarDiagnostico() {
  const box = document.getElementById('devDiag');
  if (!box) return;
  box.textContent = 'Carregando…';
  try {
    const r = await fetch('/api/sistema/diagnostico', { cache: 'no-store' });
    if (!r.ok) { box.textContent = 'Não foi possível carregar o diagnóstico.'; return; }
    const d = await r.json();
    const up = (s) => { s = Math.max(0, Math.round(s)); const h = Math.floor(s / 3600), mi = Math.floor((s % 3600) / 60), se = s % 60; return (h ? h + 'h ' : '') + (h || mi ? mi + 'm ' : '') + se + 's'; };
    const linha = (rot, val) => `<div class="dev-diag-linha"><span class="dev-diag-rot">${esc(rot)}</span><span class="dev-diag-val">${val}</span></div>`;
    const modo = d.persistencia === 'mongo'
      ? `<b>MongoDB</b> (nuvem)${d.mongoConectado ? '' : ' <span class="dev-pill alerta">desconectado</span>'}`
      : '<b>Arquivos JSON</b> (local)';
    const colecoes = (d.colecoes || []).map(c => `<span class="dev-col"><b>${c.qtd == null ? '—' : c.qtd}</b> ${esc(c.nome)}</span>`).join('');
    box.innerHTML =
      linha('Persistência', modo) +
      linha('Versão', esc(d.versao || '—')) +
      linha('Build (deploy)', `<code>${esc(d.build || '—')}</code>`) +
      linha('No ar desde', esc(d.publicadoEm || '—')) +
      linha('Uptime', up(d.uptimeSegundos || 0)) +
      linha('Node', `${esc(d.node || '—')} · ${esc(d.plataforma || '')}`) +
      linha('Memória (RSS)', `${d.memoria ? d.memoria.rss : '—'} MB <span class="dev-sub">heap ${d.memoria ? d.memoria.heapUsado : '—'}/${d.memoria ? d.memoria.heapTotal : '—'} MB</span>`) +
      linha('Login', d.loginAtivo ? 'ativo' : 'desligado (local)') +
      linha('Conexões ao vivo', String(d.sseConectados ?? '—')) +
      `<div class="dev-diag-cols">${colecoes}</div>`;
  } catch (e) { box.textContent = 'Erro ao carregar o diagnóstico.'; }
}

// "Ver como usuário comum": troca o EU por um comum simulado (acesso total às abas) e
// reaplica visibilidade/permissões. Só visual — o servidor continua tratando você como
// admin/dev. loginAtivo:true força o caminho "comum" mesmo no localhost.
function entrarPreviewComum() {
  if (PREVIEW_COMUM || !EU) return;
  EU_REAL = EU;
  const perms = {};
  Object.keys(AREA_ROTULOS).forEach((a) => { perms[a] = 'editar'; });
  EU = { logado: true, loginAtivo: true, nivel: 'comum', nome: EU_REAL.nome, usuario: EU_REAL.usuario, id: EU_REAL.id, avatar: EU_REAL.avatar || null, permissoes: perms, empresasFunc: 'ambas', contratosFunc: [] };
  PREVIEW_COMUM = true;
  fecharDevPainel();
  aplicarVisibilidadeAdmin();
  aplicarPermissoesAbas();
  atualizarBotoesPlanilhaFrota();
  try { if (typeof BackupUI !== 'undefined') BackupUI.atualizarCard(); } catch (e) {} // esconde o card de backup do Início
  const b = document.getElementById('previewComumBanner'); if (b) b.hidden = false;
}
function sairPreviewComum() {
  if (!PREVIEW_COMUM || !EU_REAL) return;
  EU = EU_REAL; EU_REAL = null; PREVIEW_COMUM = false;
  aplicarVisibilidadeAdmin();
  aplicarPermissoesAbas();
  atualizarBotoesPlanilhaFrota();
  const b = document.getElementById('previewComumBanner'); if (b) b.hidden = true;
  if (ehAdminLocal()) carregarModoManut(); // reacende o toggle de manutenção
  try { if (typeof BackupUI !== 'undefined') BackupUI.atualizarCard(); } catch (e) {} // reexibe o card de backup do Início
}

