// Chip do usuário na topbar: avatar redondo (visual do componente Avatar do Flowbite —
// círculo com silhueta quando não há foto; a biblioteca em si é React e NÃO entra: projeto
// sem framework/build) + nome. Clique no AVATAR troca a foto; clique no NOME mantém o
// comportamento de sempre (meus dados / feedback).
const AVATAR_PLACEHOLDER_SVG = '<svg viewBox="0 0 20 20" fill="currentColor" aria-hidden="true"><path fill-rule="evenodd" d="M10 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm-8 9a8 8 0 1 1 16 0H2Z" clip-rule="evenodd"/></svg>';
/* ============================================================
   Foto de perfil: prévia, enquadramento e exclusão (1.52.4)
   Até a 1.52.3 escolher o arquivo JÁ enviava a foto, sem prévia e sem volta. Agora a escolha
   abre o #avatarModal: arrasta e amplia no canvas até enquadrar, e só o "Confirmar foto" envia.
   O canvas manda no ENQUADRAMENTO (sai um PNG quadrado já recortado); o arquivo final continua
   saindo do sharp no servidor — cliente escolhe o quadro, servidor decide o arquivo.
   Sobre EXIF: o navegador já aplica a orientação ao desenhar a imagem no canvas, e o PNG que
   sai dele não tem EXIF, então o .rotate() do servidor vira no-op e a prévia bate com o salvo.
   ============================================================ */
const AVATAR_LADO = 264;   // lado do canvas de enquadramento (o servidor ainda reduz para 96)
const avatarCtx = { img: null, arquivoAnimado: null, url: '', escala: 1, escalaMin: 1, x: 0, y: 0, ponteiros: new Map(), pinca: 0, enviando: false };

// Solta a imagem escolhida. O revoke é obrigatório: sem ele cada troca de foto deixa um
// object URL vivo com a imagem inteira presa na memória do navegador.
function descartarEscolhaAvatar() {
  if (avatarCtx.url) { URL.revokeObjectURL(avatarCtx.url); avatarCtx.url = ''; }
  avatarCtx.img = null; avatarCtx.arquivoAnimado = null; avatarCtx.escala = 1; avatarCtx.escalaMin = 1;
  avatarCtx.x = 0; avatarCtx.y = 0; avatarCtx.ponteiros.clear(); avatarCtx.pinca = 0;
  const prev = document.getElementById('avatarAnimPrev'); if (prev) { prev.hidden = true; prev.removeAttribute('src'); }
}
// Impede que o arraste/zoom deixe buraco no círculo: a imagem nunca é menor que o quadro.
function limitarAvatar() {
  if (!avatarCtx.img) return;
  const e = avatarCtx.escalaMin * avatarCtx.escala;
  const maxX = Math.max(0, (avatarCtx.img.naturalWidth * e - AVATAR_LADO) / 2);
  const maxY = Math.max(0, (avatarCtx.img.naturalHeight * e - AVATAR_LADO) / 2);
  avatarCtx.x = Math.min(maxX, Math.max(-maxX, avatarCtx.x));
  avatarCtx.y = Math.min(maxY, Math.max(-maxY, avatarCtx.y));
}
function desenharAvatar() {
  const c = document.getElementById('avatarCanvas');
  if (!c) return;
  const ctx = c.getContext('2d');
  ctx.clearRect(0, 0, AVATAR_LADO, AVATAR_LADO);
  if (!avatarCtx.img) return;
  const e = avatarCtx.escalaMin * avatarCtx.escala;
  const w = avatarCtx.img.naturalWidth * e, h = avatarCtx.img.naturalHeight * e;
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  ctx.drawImage(avatarCtx.img, (AVATAR_LADO - w) / 2 + avatarCtx.x, (AVATAR_LADO - h) / 2 + avatarCtx.y, w, h);
}
function aplicarZoomAvatar(valor) {
  avatarCtx.escala = Math.min(4, Math.max(1, valor));
  const sl = document.getElementById('avatarZoom'); if (sl) sl.value = String(avatarCtx.escala);
  limitarAvatar();
  desenharAvatar();
}
// Liga/desliga o que aparece conforme o estado: enquadrando / prévia animada / foto salva / sem foto.
function estadoAvatarModal() {
  const gif = !!avatarCtx.arquivoAnimado;
  const escolhendo = !!avatarCtx.img || gif;
  const temFoto = !!(EU && EU.avatar);
  const el = (id) => document.getElementById(id);
  const canvas = el('avatarCanvas'), atual = el('avatarAtual'), vazio = el('avatarVazio'), prev = el('avatarAnimPrev');
  if (canvas) canvas.hidden = !avatarCtx.img || gif;
  if (prev) { prev.hidden = !gif; if (gif && prev.src !== avatarCtx.url) prev.src = avatarCtx.url; }
  if (atual) { atual.hidden = escolhendo || !temFoto; if (!atual.hidden) atual.src = fotoAtualDeEu(); }
  if (vazio) {
    vazio.hidden = escolhendo || temFoto;
    if (!vazio.hidden) montarAvatarEm(vazio, (EU && (EU.nome || EU.usuario)) || '');
  }
  // A moldura escolhida aparece já no palco, em volta da prévia.
  aplicarMolduraEm(el('avatarPalcoWrap'), EU && EU.moldura);
  const zoom = el('avatarZoomWrap'); if (zoom) zoom.hidden = !avatarCtx.img || gif;
  const rem = el('avatarRemover'); if (rem) { rem.hidden = !temFoto; rem.disabled = avatarCtx.enviando; }
  const ok = el('avatarConfirmar'); if (ok) { ok.disabled = !escolhendo || avatarCtx.enviando; ok.textContent = avatarCtx.enviando ? 'Enviando...' : 'Confirmar foto'; }
  const esc2 = el('avatarEscolher'); if (esc2) esc2.textContent = temFoto || escolhendo ? 'Escolher outra' : 'Escolher foto';
  const dica = el('avatarDica');
  if (dica) dica.textContent = gif
    ? 'Foto animada: ela entra centralizada, sem enquadrar.'
    : (avatarCtx.img ? 'Arraste para posicionar e use a barra para aproximar.'
      : (temFoto ? 'Esta é a sua foto de perfil hoje.' : 'Escolha uma foto, GIF ou WebP animado.'));
  renderMoldurasEscolha();
}
// A foto grande do modal: a animada quando existe (é o lugar onde o movimento foi pedido).
function fotoAtualDeEu() {
  if (EU && EU.avatarAnim && EU.id) return urlAvatarPerfil({ id: EU.id, temFoto: true, v: EU.avatarV }, true);
  return (EU && EU.avatar) || '';
}
// Fileira de molduras: cada opção mostra a própria arte em volta de um círculo de exemplo.
function renderMoldurasEscolha() {
  const box = document.getElementById('avatarMolduras');
  if (!box) return;
  const atual = moldValida(EU && EU.moldura);
  box.innerHTML = MOLDURAS_UI.map(m => `
    <button type="button" class="mold-op${m.chave === atual ? ' ativa' : ''}" data-mold="${esc(m.chave)}" title="${esc(m.rotulo)}" aria-pressed="${m.chave === atual}">
      ${comMoldura(`<span class="avatar-user mold-exemplo"></span>`, m.chave, 'sempre-anima')}
      <span class="mold-op-txt">${esc(m.rotulo)}</span>
    </button>`).join('');
}
async function escolherMoldura(chave) {
  const anterior = (EU && EU.moldura) || '';
  if (moldValida(chave) === moldValida(anterior)) return;
  if (EU) EU.moldura = moldValida(chave);
  estadoAvatarModal();
  aplicarAvatarNaTela(EU && EU.avatar);   // repinta sidebar e menu com a moldura nova
  try {
    const r = await fetch('/api/eu/moldura', {
      method: 'PUT', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ moldura: moldValida(chave) }),
    });
    if (!r.ok) throw new Error('falhou');
    toast(moldValida(chave) ? 'Moldura aplicada.' : 'Moldura removida.');
  } catch (e) {
    if (EU) EU.moldura = anterior;        // desfaz na tela: o servidor não aceitou
    estadoAvatarModal();
    aplicarAvatarNaTela(EU && EU.avatar);
    toast('Não consegui salvar a moldura.', 'erro');
  }
}
async function carregarAvatarArquivo(file) {
  if (!/^image\//.test(file.type || '')) { toast('Escolha uma imagem (JPG, PNG, WebP ou GIF).', 'erro'); return; }
  // Animação: o arquivo sobe INTEIRO e original. Passar por canvas ou por comprimirImagem()
  // devolveria um quadro só — era o que achatava o GIF duas vezes no caminho antigo.
  const animado = /gif|webp/.test(file.type || '') || /\.(gif|webp)$/i.test(file.name || '');
  if (animado) {
    descartarEscolhaAvatar();
    avatarCtx.arquivoAnimado = file;
    avatarCtx.url = URL.createObjectURL(file);
    estadoAvatarModal();
    return;
  }
  // Reduz antes de desenhar: uma foto de celular de 12 MP no canvas gasta memória à toa e o
  // quadro final tem 264px. comprimirImagem() é a mesma usada nos anexos.
  const menor = await comprimirImagem(file);
  const url = URL.createObjectURL(menor);
  const img = new Image();
  img.onload = () => {
    descartarEscolhaAvatar();
    avatarCtx.img = img; avatarCtx.url = url;
    avatarCtx.escalaMin = Math.max(AVATAR_LADO / img.naturalWidth, AVATAR_LADO / img.naturalHeight);
    aplicarZoomAvatar(1);
    estadoAvatarModal();
  };
  img.onerror = () => { URL.revokeObjectURL(url); toast('Não consegui abrir essa imagem.', 'erro'); };
  img.src = url;
}
/* Aviso ÚNICO da foto de perfil, só para usuário NOVO: quem já usava o sistema quando o
   recurso subiu não é avisado. Quem decide é o servidor (`EU.avisoFoto`, ver /api/eu), e a
   marca de "já vi" fica no cadastro, não no navegador — assim o aviso não volta quando a
   pessoa entra de outro computador ou celular. */
function talvezMostrarAvisoFoto() {
  const m = document.getElementById('avisoFotoModal');
  if (!m || !EU || !EU.logado || EU.loginAtivo === false) return; // no acesso local não existe menu de conta
  if (!EU.avisoFoto || EU.avatar) return;
  const ex = document.getElementById('avisoFotoExemplo');
  if (ex) ex.innerHTML = `<span class="avatar-user aviso-foto-bola">${AVATAR_PLACEHOLDER_SVG}</span><span class="av-moldura" aria-hidden="true"></span>`;
  m.hidden = false;
}
function fecharAvisoFoto(abrirDepois) {
  if (EU) EU.avisoFoto = false;
  fetch('/api/eu/aviso-foto', { method: 'POST' }).catch(() => { /* volta no próximo acesso */ });
  const m = document.getElementById('avisoFotoModal');
  if (m) m.hidden = true;
  if (abrirDepois) abrirAvatarModal();
}
(function ligarAvisoFoto() {
  const m = document.getElementById('avisoFotoModal');
  if (!m) return;
  document.getElementById('fecharAvisoFoto').onclick = () => fecharAvisoFoto(false);
  document.getElementById('avisoFotoDepois').onclick = () => fecharAvisoFoto(false);
  document.getElementById('avisoFotoAbrir').onclick = () => fecharAvisoFoto(true);
  fecharAoClicarNoFundo('avisoFotoModal', () => fecharAvisoFoto(false));
})();
function abrirAvatarModal() {
  const m = document.getElementById('avatarModal');
  if (!m) return;
  descartarEscolhaAvatar();
  avatarCtx.enviando = false;
  estadoAvatarModal();
  m.hidden = false;
  document.getElementById('avatarEscolher')?.focus();
}
function fecharAvatarModal() {
  if (avatarCtx.enviando) return;   // não some no meio do envio
  const m = document.getElementById('avatarModal');
  if (m) m.hidden = true;
  descartarEscolhaAvatar();
  const at = document.getElementById('avatarAtual'); if (at) { at.hidden = true; at.removeAttribute('src'); }
}
// Grava a foto nova em todos os lugares que a mostram, sem recarregar a página.
function aplicarAvatarNaTela(valor, extra) {
  if (EU) {
    EU.avatar = valor || null;
    if (extra) { EU.avatarAnim = !!extra.avatarAnim; EU.avatarV = extra.avatarV || ''; }
    else if (!valor) { EU.avatarAnim = false; EU.avatarV = ''; }
  }
  // No "ver como usuário comum" o EU é uma CÓPIA; sem escrever no EU_REAL, sair do preview
  // traria de volta a foto antiga (ou nenhuma).
  if (typeof EU_REAL !== 'undefined' && EU_REAL) {
    EU_REAL.avatar = valor || null;
    if (extra) { EU_REAL.avatarAnim = !!extra.avatarAnim; EU_REAL.avatarV = extra.avatarV || ''; }
    if (EU) EU_REAL.moldura = EU.moldura || '';
  }
  montarAvatarEm(document.getElementById('sidebarPerfilAvatar'));
  const um = document.getElementById('umAvatar'); if (um) montarAvatarEm(um);
  // No celular a troca de foto começa e termina na tela de Perfil, e o avatar que o usuário
  // está olhando é o da barra inferior — sem esta linha ele só mudava depois de um F5.
  const nav = document.getElementById('mnavPerfilAvatar'); if (nav) montarAvatarEm(nav);
  // A minha bolinha também aparece nos meus feedbacks e nas minhas alterações.
  carregarPerfis().then(() => { if (typeof renderFeedbacks === 'function' && document.getElementById('feedback')?.classList.contains('ativa')) renderFeedbacks(); });
}
async function enviarAvatar() {
  if ((!avatarCtx.img && !avatarCtx.arquivoAnimado) || avatarCtx.enviando) return;
  let blob, nome;
  if (avatarCtx.arquivoAnimado) {
    blob = avatarCtx.arquivoAnimado;
    nome = /\.(gif|webp)$/i.test(blob.name || '') ? blob.name : ((blob.type === 'image/gif') ? 'foto-perfil.gif' : 'foto-perfil.webp');
  } else {
    const canvas = document.getElementById('avatarCanvas');
    blob = await new Promise((ok) => canvas.toBlob(ok, 'image/png'));
    // O nome PRECISA terminar em .png: a allowlist do servidor decide pela extensão, não pelo MIME.
    nome = 'foto-perfil.png';
  }
  if (!blob) { toast('Não consegui preparar a imagem.', 'erro'); return; }
  avatarCtx.enviando = true; estadoAvatarModal();
  const fd = new FormData();
  fd.append('foto', blob, nome);
  try {
    const r = await fetch('/api/eu/avatar', { method: 'POST', body: fd });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) { toast(j.erro || 'Não consegui salvar a foto.', 'erro'); return; }
    aplicarAvatarNaTela(j.avatar, j);
    avatarCtx.enviando = false;
    fecharAvatarModal();
    toast('Foto atualizada.');
  } catch (err) {
    toast('Erro de conexão ao enviar a foto.', 'erro');
  } finally {
    avatarCtx.enviando = false;
    estadoAvatarModal();
  }
}
async function removerAvatar() {
  if (avatarCtx.enviando) return;
  if (!(await confirmar('Remover sua foto de perfil? No lugar dela voltam as suas iniciais.', { perigo: true, okTexto: 'Remover' }))) return;
  try {
    const r = await fetch('/api/eu/avatar', { method: 'DELETE' });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) { toast(j.erro || 'Não consegui remover a foto.', 'erro'); return; }
    aplicarAvatarNaTela(null);
    fecharAvatarModal();
    toast('Foto removida.');
  } catch (err) { toast('Erro de conexão ao remover a foto.', 'erro'); }
}
document.getElementById('avatarFileInput')?.addEventListener('change', async (e) => {
  const f = e.target.files && e.target.files[0];
  e.target.value = ''; // permite escolher o MESMO arquivo de novo
  if (f) await carregarAvatarArquivo(f);
});
(function ligarAvatarModal() {
  const canvas = document.getElementById('avatarCanvas');
  if (!canvas) return;
  document.getElementById('avatarEscolher').onclick = () => document.getElementById('avatarFileInput')?.click();
  document.getElementById('avatarCancelar').onclick = fecharAvatarModal;
  document.getElementById('fecharAvatarModal').onclick = fecharAvatarModal;
  document.getElementById('avatarConfirmar').onclick = enviarAvatar;
  document.getElementById('avatarRemover').onclick = removerAvatar;
  document.getElementById('avatarMolduras')?.addEventListener('click', (e) => {
    const b = e.target.closest('.mold-op');
    if (b) escolherMoldura(b.dataset.mold || '');
  });
  document.getElementById('avatarZoom').oninput = (e) => aplicarZoomAvatar(parseFloat(e.target.value) || 1);
  fecharAoClicarNoFundo('avatarModal', fecharAvatarModal);
  // Arrastar (1 dedo/mouse) e pinça (2 dedos). Pointer Events cobre mouse, toque e caneta
  // com um caminho só — mesmo padrão do quadro de assinatura.
  canvas.addEventListener('pointerdown', (e) => {
    if (!avatarCtx.img) return;
    canvas.setPointerCapture(e.pointerId);
    avatarCtx.ponteiros.set(e.pointerId, { x: e.clientX, y: e.clientY });
    avatarCtx.pinca = 0;
  });
  canvas.addEventListener('pointermove', (e) => {
    const p = avatarCtx.ponteiros.get(e.pointerId);
    if (!p || !avatarCtx.img) return;
    const dx = e.clientX - p.x, dy = e.clientY - p.y;
    p.x = e.clientX; p.y = e.clientY;
    if (avatarCtx.ponteiros.size >= 2) {
      const [a, b] = [...avatarCtx.ponteiros.values()];
      const dist = Math.hypot(a.x - b.x, a.y - b.y);
      if (avatarCtx.pinca) aplicarZoomAvatar(avatarCtx.escala * (dist / avatarCtx.pinca));
      avatarCtx.pinca = dist;
      return;
    }
    // O canvas é exibido em CSS possivelmente menor que 264: converte o movimento na mesma escala.
    const k = AVATAR_LADO / (canvas.getBoundingClientRect().width || AVATAR_LADO);
    avatarCtx.x += dx * k; avatarCtx.y += dy * k;
    limitarAvatar(); desenharAvatar();
  });
  const soltar = (e) => { avatarCtx.ponteiros.delete(e.pointerId); if (avatarCtx.ponteiros.size < 2) avatarCtx.pinca = 0; };
  canvas.addEventListener('pointerup', soltar);
  canvas.addEventListener('pointercancel', soltar);
  canvas.addEventListener('wheel', (e) => {
    if (!avatarCtx.img) return;
    e.preventDefault();
    aplicarZoomAvatar(avatarCtx.escala * (e.deltaY < 0 ? 1.1 : 1 / 1.1));
  }, { passive: false });
})();
document.addEventListener('keydown', (e) => {
  if (e.key !== 'Escape') return;
  const m = document.getElementById('avatarModal');
  if (m && !m.hidden) fecharAvatarModal();
});

