  menu.innerHTML = _userMenuPagina === 'tema' ? htmlUserMenuTema() : htmlUserMenuRaiz();
  montarAvatarEm(document.getElementById('umAvatar'), (!EU || EU.loginAtivo === false) ? 'Acesso Local' : '');
