function alternarUserMenu(forcar, ancora) {
  const menu = document.getElementById('userMenu');
  if (!menu) return;
  const abrir = forcar !== undefined ? forcar : menu.hidden;
  if (!abrir) { menu.hidden = true; menu.classList.remove('fixado', 'tela-perfil'); marcarPerfilAberto(false); return; }
  _userMenuPagina = 'raiz';
  if (ancora && ancora.id === 'mnavPerfil') {
    // No celular o Perfil abre como TELA cheia (classe estilizada só no design-mobile.css),
    // não como balão ancorado — por isso os estilos inline de posição são zerados.
    menu.classList.add('fixado', 'tela-perfil');
    menu.style.left = ''; menu.style.bottom = ''; menu.style.top = ''; menu.style.right = ''; menu.style.maxHeight = '';
  } else if (ancora && ancora.getBoundingClientRect) {
    menu.classList.remove('tela-perfil');
    const r = ancora.getBoundingClientRect();
    menu.classList.add('fixado');
    // Âncora perto da borda direita (ex.: Perfil da barra inferior do celular):
    // fixar pela direita para o menu não vazar da tela.
    const largura = menu.offsetWidth || 260;
    if (r.left + largura > window.innerWidth - 8) {
      menu.style.left = 'auto'; menu.style.right = '8px';
    } else {
      menu.style.left = Math.max(8, r.left) + 'px'; menu.style.right = 'auto';
    }
    menu.style.bottom = (window.innerHeight - r.top + 8) + 'px';
    menu.style.top = 'auto';
    // O menu cresce para cima; sem teto ele passaria do topo da tela nos itens de admin.
    menu.style.maxHeight = Math.max(200, r.top - 16) + 'px';
  } else {
    menu.classList.remove('fixado', 'tela-perfil');
    menu.style.left = ''; menu.style.bottom = ''; menu.style.top = ''; menu.style.right = ''; menu.style.maxHeight = '';
  }
  renderUserMenu();
  menu.hidden = false;
  marcarPerfilAberto(true);
}
document.addEventListener('click', (e) => {
  const menu = document.getElementById('userMenu');
  if (!menu || menu.hidden) return;
  const item = e.target.closest('#userMenu button');
  if (item) {
    const acao = item.dataset.acao;
    // Navegar entre as páginas do menu não pode fechá-lo.
    if (acao === 'tema') { _userMenuPagina = 'tema'; renderUserMenu(); return; }
    // Alto contraste é camada sobre o tema: alterna e fica, sem fechar a tela
    if (acao === 'contraste') { alternarAltoContraste(!altoContrasteAtivo); renderUserMenu(); return; }
    if (acao === 'tema-voltar') { _userMenuPagina = 'raiz'; renderUserMenu(); return; }
    if (acao === 'tema-set') { aplicarTema(item.dataset.tema); renderUserMenu(); return; }
    menu.hidden = true; marcarPerfilAberto(false);
    if (acao === 'verfoto') verFotoUsuario(EU);
    if (acao === 'dados') abrirInfoUsuario(EU);
    if (acao === 'foto') abrirAvatarModal();
    if (acao === 'feedback') { const b = document.querySelector('.tab[data-tab="feedback"]'); if (b) { b.click(); marcarFeedbacksVistos(); } }
    if (acao === 'historico') {
      // Com a topbar escondida no desktop, o painel precisa sair dela (display:none não
      // renderiza descendentes, nem fixed) e ancorar no cartão de perfil da sidebar.
      const hp = document.getElementById('histPanel');
      if (hp && hp.parentElement !== document.body) document.body.appendChild(hp);
      if (hp) hp._ancora = document.getElementById('sidebarPerfil');
      document.getElementById('btnHistorico')?.click();
    }
    if (acao === 'novidades') document.getElementById('btnChangelog')?.click();
    if (acao === 'backup') document.getElementById('btnBackup')?.click();
    if (acao === 'manutencao') alternarModoManut(!(MANUT && MANUT.ativo));
    if (acao === 'dev') document.getElementById('btnDevPainel')?.click();
    // Volta ao hub: navegação direta (sem a animação de tela cheia desde a 1.55.45).
    if (acao === 'hub') transicaoParaSistema('hub');
    if (acao === 'sair') document.getElementById('btnSair')?.click();
    return;
  }
  if (!e.target.closest('#sidebarPerfil') && !e.target.closest('#mnavPerfil')) { menu.hidden = true; marcarPerfilAberto(false); }
});
document.addEventListener('keydown', (e) => {
  const menu = document.getElementById('userMenu');
  if (e.key !== 'Escape' || !menu || menu.hidden) return;
  if (_userMenuPagina === 'tema') { _userMenuPagina = 'raiz'; renderUserMenu(); return; }
  menu.hidden = true;
  marcarPerfilAberto(false);
  // No celular a sidebar está display:none (offsetParent nulo) — o foco volta ao Perfil da barra.
  const sp = document.getElementById('sidebarPerfil');
  (sp && sp.offsetParent ? sp : document.getElementById('mnavPerfil'))?.focus();
});

async function carregarEu() {
  try {
    const r = await fetch('/api/eu', { cache: 'no-store' });
    if (!r.ok) return;
    EU = await r.json();
    carregarPerfis();      // foto e moldura de quem assina feedback e alteração (não bloqueia o boot)
    montarPerfilSidebar(); // único lugar do usuário: cartão no rodapé da sidebar (local também)
    montarPerfilNavMobile(); // espelho do perfil no botão da barra inferior do celular
    setTimeout(talvezMostrarAvisoFoto, 1200); // deixa a tela assentar antes de avisar da novidade
    // Recursos só de admin/dev (ou modo local sem login). Centralizado em aplicarVisibilidadeAdmin()
    // para que o "Ver como usuário comum" (painel dev) consiga reaplicar a visibilidade ao alternar.
    const ehAdminOuLocal = aplicarVisibilidadeAdmin();
    if (ehAdminOuLocal) carregarModoManut();
    atualizarBotoesPlanilhaFrota(); // ações da Frota dependem da aba ativa + nível
    // Aba "Contratos" e "Controles" (financeiro): visíveis para todos os usuários logados
    { const tc = document.getElementById('tabContratos'); if (tc) tc.hidden = false; }
    { const ta = document.getElementById('tabControles'); if (ta) ta.hidden = false; }
    { const gf = document.getElementById('grupoFinanceiro'); if (gf) gf.hidden = false; }
    // Poll de novos pedidos de cadastro: só para admin/dev de verdade.
    if (EU && ehNivelAdmin(EU.nivel)) iniciarPollUsuarios();
    // Restrições por usuário comum: esconde abas sem acesso e marca as "só ver".
    // Roda ANTES do deep-link abaixo para não navegar a uma aba proibida.
    aplicarPermissoesAbas();
    // Deep-link/reload numa aba revelada só agora (/contratos p/ todos, /usuarios p/ admin):
    // restaurarAbaAtiva() rodou no boot ANTES de /api/eu liberar a aba (ainda hidden → abaExiste
    // devolveu null), então a rota da URL não foi aplicada e ficamos na Frota. Reaplica a rota aqui,
    // agora que a aba existe — capturando o segmento da SUB-aba ANTES do clique (que reescreve a
    // URL p/ só /aba) e reaplicando-o em seguida, sem criar entrada no histórico (modo replace).
    { const rota = rotaDaPath(); if (rota) { const t = abaExiste(rota); if (t && !t.classList.contains('active')) {
      const seg = subDaPath();
      _navModo = 'replace';
      try { t.click(); aplicarSubDaUrl(rota, seg); } finally { _navModo = 'push'; }
    } } }
    // Agora que sabemos o nível, ajusta a aba Feedback (admin vê a lista; comum só envia)
    if (typeof carregarFeedbacks === 'function') carregarFeedbacks();
    // Carrega os funcionários em segundo plano p/ já acender o selo de documentos a vencer
    if (typeof carregarFuncionarios === 'function') carregarFuncionarios();
    // Idem para os programas de SST (selo de vencimento na lateral)
    if (typeof carregarProgramas === 'function') carregarProgramas();
    // Todo usuário logado: tempo real (SSE) + poll de fallback do próprio nível
    if (EU && EU.logado) { conectarEventos(); iniciarPollEu(); }
  } catch (e) { /* ignora */ }
}

// Selo com a contagem de pedidos pendentes na aba "Usuários"
function atualizarBadgePendentes(n) {
  const b = document.getElementById('badgePendentes');
  if (!b) return;
  if (n > 0) { b.textContent = n > 99 ? '99+' : n; b.hidden = false; }
  else b.hidden = true;
}

// Verificação periódica de novos pedidos (só para admin). Se a aba estiver
// aberta, recarrega tudo; senão, atualiza apenas o selo da aba.
let _pollUsuariosLigado = false;
async function pollUsuarios() {
  if (!EU || !ehNivelAdmin(EU.nivel)) return;
  // Não atrapalha uma edição inline de senha em andamento
  if (document.querySelector('.usr-senha-input')) return;
  const abaAberta = document.getElementById('usuarios')?.classList.contains('active');
  if (abaAberta) { carregarUsuarios(); return; }
  try {
    const r = await fetch('/api/usuarios', { cache: 'no-store' });
    if (!r.ok) return;
    const j = await r.json();
    atualizarBadgePendentes(j.usuarios.filter(u => u.status === 'pendente').length);
  } catch (e) { /* ignora */ }
}
function iniciarPollUsuarios() {
  if (_pollUsuariosLigado || !EU || !ehNivelAdmin(EU.nivel)) return;
  _pollUsuariosLigado = true;
  pollUsuarios(); // já mostra o selo logo ao entrar
  // Atualização agora é em tempo real via SSE (evento 'atualizar-usuarios'),
  // então não há mais polling periódico. Mantém só a rede de segurança ao
  // voltar para a aba (caso o SSE tenha caído enquanto estava em background).
  document.addEventListener('visibilitychange', () => { if (!document.hidden) pollUsuarios(); });
}

// Tempo real (SSE): o servidor empurra avisos e a tela reage na hora.
let _es = null;
let _dadosTimer = null;
const _tiposPendentes = new Set();
// Junta vários avisos próximos num só refresh (evita rajada de buscas) e atualiza
// SÓ os tipos que mudaram (o servidor manda o tipo no evento SSE). Tipo desconhecido
// ou ausente → atualiza tudo (rede de segurança).
function agendarProcessamentoRefreshDados(delay = 350) {
  if (_dadosTimer) return;
  _dadosTimer = setTimeout(async () => {
    _dadosTimer = null;
    const tipos = [..._tiposPendentes]; _tiposPendentes.clear();
    const atualizarTudo = tipos.some(t => !t || !REFRESCOS[t]);
    const ok = atualizarTudo
      ? await verificarAtualizacoes()
      : (await Promise.all(tipos.map(t => verificarAtualizacoes(t)))).every(Boolean);
    if (!ok) {
      tipos.forEach(t => _tiposPendentes.add(t));
      agendarProcessamentoRefreshDados(document.hidden ? 5000 : 1200);
    }
  }, delay);
}
function agendarRefreshDados(ev) {
  let tipo = '';
  try { tipo = (JSON.parse((ev && ev.data) || '{}').tipo) || ''; } catch (e) { /* sem tipo */ }
  _tiposPendentes.add(tipo);
  agendarProcessamentoRefreshDados();
}
function conectarEventos() {
  if (_es || typeof EventSource === 'undefined') return;
  try {
    _es = new EventSource('/api/eventos');
    // Novo cadastro / mudança na lista → atualiza painel e selo na hora (se admin)
    _es.addEventListener('atualizar-usuarios', () => { if (EU && ehNivelAdmin(EU.nivel)) pollUsuarios(); });
    // Alguém trocou a foto ou a moldura → recarrega só os perfis (evento próprio de propósito:
    // 'dados' sem tipo conhecido dispararia uma varredura completa das abas).
    _es.addEventListener('perfis-mudou', () => {
      carregarPerfis().then(() => {
        if (typeof renderFeedbacks === 'function' && FEEDBACKS && FEEDBACKS.length) renderFeedbacks();
      });
    });
    // Fui promovido/rebaixado → ajusta a interface imediatamente
    _es.addEventListener('nivel-mudou', () => verificarMeuNivel());
    // Modo manutenção mudou (outro admin/dev ligou/desligou) → atualiza o aviso na hora
    _es.addEventListener('manutencao-mudou', (ev) => {
      try { MANUT = Object.assign({}, MANUT, JSON.parse((ev && ev.data) || '{}')); } catch (e) { /* ignora */ }
      renderModoManut();
    });
    // Minhas permissões de abas mudaram → reaplica na hora (sem F5)
    _es.addEventListener('permissoes-mudou', (ev) => {
      try {
        const d = JSON.parse((ev && ev.data) || '{}');
        if (PREVIEW_COMUM) { if (EU_REAL) { if (d.permissoes) EU_REAL.permissoes = d.permissoes; if ('empresasFunc' in d) EU_REAL.empresasFunc = d.empresasFunc; if ('contratosFunc' in d) EU_REAL.contratosFunc = d.contratosFunc; } return; } // não mexe no preview
        if (EU && (d.permissoes || 'empresasFunc' in d || 'contratosFunc' in d)) {
          if (d.permissoes) EU.permissoes = d.permissoes;
          if ('empresasFunc' in d) EU.empresasFunc = d.empresasFunc;
          if ('contratosFunc' in d) EU.contratosFunc = d.contratosFunc;
          aplicarPermissoesAbas();
          aplicarVisibilidadeAdmin();
          // Acesso por empresa mudou → recarrega a lista de funcionários (vem refiltrada do servidor).
          if (typeof carregarFuncionarios === 'function') { try { carregarFuncionarios(); } catch (e) {} }
          toast('Suas permissões de acesso foram atualizadas.', 'ok');
        }
      } catch (e) { verificarMeuNivel(); }
    });
    // Um feedback MEU foi respondido/teve o status mudado → avisa (toast) e acende o selo no chip do nome.
    _es.addEventListener('feedback-atualizado', (ev) => {
      let d = {}; try { d = JSON.parse((ev && ev.data) || '{}'); } catch (e) { /* ignora */ }
      carregarFeedbacks().then(() => {
        // Se o usuário já está na aba Feedback, ele está vendo → marca como visto (não acumula selo).
        if (document.getElementById('feedback') && document.getElementById('feedback').classList.contains('active')) marcarFeedbacksVistos();
        const st = d.status ? ` (${d.status})` : '';
        toast(`Seu feedback "${d.titulo || ''}" foi atualizado${st}.`, 'ok');
      });
    });
    // Minha sessão caiu (senha trocada ou usuário removido) → volta ao login
    _es.addEventListener('sessao-encerrada', () => { window.location = '/login'; });
    // Dados mudaram (veículos, multas, rastreadores, instalações, envios, cadastros) → atualiza na hora
    _es.addEventListener('dados', agendarRefreshDados);
    _es.addEventListener('undo-status', (ev) => {
      let area = ''; try { area = JSON.parse((ev && ev.data) || '{}').area || ''; } catch (e) { /* ignora */ }
      if (!area || area === areaUndoAtiva()) atualizarUndoStatus();
    });
    // Queda transitória: o próprio EventSource reconecta. Fechamento DEFINITIVO (ex.: 401 por
    // sessão perdida após deploy sem SESSION_SECRET) não reconecta sozinho → confirma a sessão
    // e ou volta ao login, ou recria o canal com backoff (sem loop quente contra um 401 fixo).
    _es.onerror = () => {
      if (!_es || _es.readyState !== EventSource.CLOSED) return;
      _es.close(); _es = null;
      fetch('/api/eu', { cache: 'no-store' })
        .then(r => r.ok ? r.json() : null)
        .then(d => {
          if (d && d.loginAtivo && !d.logado) { window.location = '/login'; return; }
          if (EU && EU.logado) setTimeout(conectarEventos, 5000);
        })
        .catch(() => { if (EU && EU.logado) setTimeout(conectarEventos, 5000); });
    };
  } catch (e) { /* sem tempo real; os polls de fallback cobrem */ }
}

// Verifica periodicamente o PRÓPRIO nível do usuário logado. Se ele for
// promovido a admin (ou rebaixado), a interface se ajusta SEM precisar de F5.
// (Fallback caso o tempo real (SSE) não esteja disponível.)
let _pollEuLigado = false;
function iniciarPollEu() {
  if (_pollEuLigado || !EU || !EU.logado) return;
  _pollEuLigado = true;
  // Nível/permissões agora chegam em tempo real via SSE ('nivel-mudou' e
  // 'permissoes-mudou'), então sem polling periódico. Mantém só a rede de
  // segurança ao voltar para a aba (caso o SSE tenha caído em background).
  document.addEventListener('visibilitychange', () => { if (!document.hidden) verificarMeuNivel(); });
}
async function verificarMeuNivel() {
  try {
    const r = await fetch('/api/eu', { cache: 'no-store' });
    if (!r.ok) return;
    const novo = await r.json();
    if (!novo || !novo.loginAtivo || !novo.logado) return;
    // Pré-visualizando como comum: não mexe na interface simulada — só atualiza o
    // usuário real guardado, para que ao "voltar ao normal" reflita o estado novo.
    if (PREVIEW_COMUM) { EU_REAL = novo; return; }
    const antes = EU ? EU.nivel : null;
    const permAntes = JSON.stringify((EU && EU.permissoes) || {});
    EU = novo;
    aplicarVisibilidadeAdmin();
    const tab = document.getElementById('tabUsuarios');
    const eraAdmin = ehNivelAdmin(antes), agoraAdmin = ehNivelAdmin(novo.nivel);
    const wrapMan = document.getElementById('manutToggleWrap');
    if (agoraAdmin && !eraAdmin) {
      // Acabou de virar admin/dev → libera o painel e o toggle de manutenção na hora
      if (tab) tab.hidden = false;
      if (wrapMan) wrapMan.hidden = false;
      iniciarPollUsuarios();
      carregarModoManut();
      toast(novo.nivel === 'dev' ? 'Você agora é desenvolvedor! Acesso total liberado.' : 'Você agora é administrador! O painel de Usuários foi liberado.', 'ok');
    } else if (!agoraAdmin && eraAdmin) {
      // Foi rebaixado → esconde a aba/toggle e sai dela se estiver aberta
      if (tab) tab.hidden = true;
      if (wrapMan) wrapMan.hidden = true;
      atualizarBadgePendentes(0);
      if (document.getElementById('usuarios')?.classList.contains('active')) {
        document.querySelector('.tab[data-tab="frota"]')?.click();
      }
      toast('Seu acesso de administrador foi alterado.', 'erro');
    }
    // Reaplica restrições de abas (caso o admin tenha mudado minhas permissões).
    aplicarPermissoesAbas();
    if (!ehNivelAdmin(novo.nivel) && JSON.stringify(novo.permissoes || {}) !== permAntes && antes === novo.nivel) {
      toast('Suas permissões de acesso foram atualizadas.', 'ok');
    }
  } catch (e) { /* ignora */ }
}

/* ============================================================
   MODO MANUTENÇÃO; aviso entre admins/devs durante edições simultâneas.
   NÃO bloqueia nada: só sinaliza que alguém está mexendo no sistema (pair
   programming). Visível só para admin/dev. Estado em tempo real via SSE.
   ============================================================ */
// NOMES com sufixo "ModoManut" para NÃO colidir com a aba Manutenção de veículos
// (que já tem carregarManutencao/renderManutencao — outra coisa completamente).
async function carregarModoManut() {
  if (!ehAdminLocal()) return;
  try {
    const r = await fetch('/api/sistema/manutencao', { cache: 'no-store' });
    if (!r.ok) return;
    MANUT = Object.assign({ ativo: false, por: '', porUsuario: '', mensagem: '', desde: 0 }, await r.json());
    renderModoManut();
  } catch (e) { /* ignora */ }
}
function renderModoManut() {
  const banner = document.getElementById('manutencaoBanner');
  const wrap = document.getElementById('manutToggleWrap');
  const toggle = document.getElementById('manutToggle');
  const btnFerramentas = document.getElementById('btnFerramentas');
  // Só admin/dev (e modo local) enxergam o toggle e o aviso.
  if (!ehAdminLocal()) { if (banner) banner.hidden = true; if (wrap) wrap.hidden = true; return; }
  const eu = MANUT.porUsuario && EU && MANUT.porUsuario === EU.usuario;
  if (wrap) {
    wrap.hidden = false;
    wrap.classList.toggle('on', !!MANUT.ativo);
    wrap.title = MANUT.ativo
      ? 'Manutenção ATIVA; desligue o toggle para encerrar o aviso'
      : 'Sinalizar que você está mexendo no sistema (avisa os outros admins/devs)';
  }
  if (toggle) toggle.checked = !!MANUT.ativo;
  // O menu do usuário mostra "ligado/desligado": se estiver aberto, acompanha a mudança
  // (inclusive a que chega por SSE de outro admin).
  { const um = document.getElementById('userMenu'); if (um && !um.hidden && typeof renderUserMenu === 'function') renderUserMenu(); }
  if (btnFerramentas) {
    btnFerramentas.classList.toggle('manut-ativa', !!MANUT.ativo);
    btnFerramentas.title = MANUT.ativo ? 'Sistemas e ferramentas · manutenção ativa' : 'Sistemas e ferramentas';
    btnFerramentas.setAttribute('aria-label', MANUT.ativo
      ? 'Sistemas e ferramentas; manutenção ativa'
      : 'Sistemas e ferramentas');
  }
  if (!banner) return;
  if (MANUT.ativo) {
    let hora = '';
    try { hora = MANUT.desde ? new Date(MANUT.desde).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) : ''; } catch (e) { /* ignora */ }
    const quem = eu ? 'Você' : esc(MANUT.por || 'Alguém');
    const verbo = eu ? 'está sinalizando manutenção' : 'está mexendo no sistema';
    const msg = MANUT.mensagem ? ` · “${esc(MANUT.mensagem)}”` : '';
    banner.innerHTML = `<span class="manut-ico" aria-hidden="true">🛠️</span>
      <span class="manut-txt"><strong>${quem}</strong> ${verbo}${hora ? ` desde as ${hora}` : ''}.${msg} Cuidado ao editar para não conflitar.</span>
      <button type="button" class="manut-encerrar" id="manutEncerrar">Encerrar</button>`;
    banner.classList.toggle('eu', !!eu);
    banner.hidden = false;
    const enc = document.getElementById('manutEncerrar');
    if (enc) enc.onclick = () => alternarModoManut(false);
  } else {
    banner.hidden = true;
    banner.innerHTML = '';
  }
}
async function alternarModoManut(ativar) {
  try {
    const r = await fetch('/api/sistema/manutencao', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ativo: !!ativar }),
    });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) { toast(j.erro || 'Erro ao alterar manutenção.', 'erro'); renderModoManut(); return; }
    MANUT = Object.assign({}, MANUT, j);
    renderModoManut();
    toast(ativar ? 'Manutenção sinalizada; os outros admins/devs já foram avisados.' : 'Aviso de manutenção encerrado.', 'ok');
  } catch (e) { toast('Erro de conexão.', 'erro'); renderModoManut(); }
}
{
  const toggle = document.getElementById('manutToggle');
  if (toggle) toggle.onchange = () => alternarModoManut(toggle.checked);
}

function rotuloStatus(s) {
  if (s === 'aprovado') return '<span class="usr-badge ok">ativo</span>';
  if (s === 'pendente') return '<span class="usr-badge pend">pendente</span>';
  if (s === 'recusado') return '<span class="usr-badge rec">recusado</span>';
  return '';
}

async function carregarUsuarios() {
  const pend = document.getElementById('listaPendentes');
  const ativos = document.getElementById('listaAtivos');
  if (!pend || !ativos) return;
  pend.innerHTML = '<li class="cad-vazio">Carregando...</li>';
  ativos.innerHTML = '';
  try {
    const r = await fetch('/api/usuarios', { cache: 'no-store' });
    if (!r.ok) { pend.innerHTML = '<li class="cad-vazio">Sem permissão.</li>'; return; }
    const j = await r.json();
    // Toggle de cadastros
    const tg = document.getElementById('toggleCadastros');
    if (tg) tg.checked = !!j.cadastrosAbertos;
    const hint = document.getElementById('usrToggleHint');
    if (hint) hint.title = j.cadastrosAbertos
      ? 'O site está aceitando novos pedidos de cadastro.'
      : 'Desligado: ninguém consegue solicitar acesso ao site.';

    USUARIOS_MAP = {};
    j.usuarios.forEach(u => { USUARIOS_MAP[u.usuario] = u; });
    // Fotos numa chamada à parte (só aqui, com a aba aberta). Se falhar, a lista sai com iniciais.
    try {
      const ra = await fetch('/api/usuarios/avatares', { cache: 'no-store' });
      if (ra.ok) AVATARES_USR = (await ra.json()).avatares || {};
    } catch (e) { /* segue com iniciais */ }
    const pendentes = j.usuarios.filter(u => u.status === 'pendente');
    USUARIOS_ATIVOS = j.usuarios.filter(u => u.status !== 'pendente');
    atualizarBadgePendentes(pendentes.length);
    // Antes das listas: a linha do pedido pendente mostra o IP de quem pediu, e ele vem daqui.
    await carregarLogsAcesso();
    const banner = document.getElementById('usrBannerPend');
    const bannerTit = document.getElementById('usrBannerPendTit');
    if (banner) banner.hidden = !pendentes.length;
    if (bannerTit) bannerTit.textContent = pendentes.length === 1
      ? '1 pedido de acesso aguardando aprovação'
      : `${pendentes.length} pedidos de acesso aguardando aprovação`;

    // Meta do pedido: "@usuario · pedido em DD/MM/AA · IP". O IP sai da trilha de acesso do
    // próprio candidato (ele bate na porta e leva 'bloqueado' por estar pendente), então os logs
    // são carregados ANTES desta lista — ver a ordem em carregarUsuarios.
    const ipDoPedido = (usuario) => (LOGS_ACESSO.find(l => l.usuario === usuario && l.ip) || {}).ip || '';
    pend.innerHTML = pendentes.length ? pendentes.map(u => `
      <li class="usr-item">
        ${htmlAvatarUsr(u)}
        <div class="usr-info">
          <div class="usr-nome usr-clicavel" data-info="${esc(u.usuario)}" title="Ver dados / ID">${esc(u.nome)}</div>
          <div class="usr-sub">@${esc(u.usuario)}${u.criadoEm ? ' · pedido em ' + esc(new Date(u.criadoEm).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: '2-digit' })) : ''}${ipDoPedido(u.usuario) ? ' · ' + esc(ipDoPedido(u.usuario)) : ''}</div>
        </div>
        <div class="usr-acoes">
          <button class="btn btn-primary small" data-aprovar="${esc(u.usuario)}">Aprovar</button>
          <button class="btn btn-ghost small" data-recusar="${esc(u.usuario)}">Recusar</button>
        </div>
      </li>`).join('') : '<li class="cad-vazio">Nenhum pedido pendente.</li>';
    pend.querySelectorAll('[data-aprovar]').forEach(b => b.onclick = () => acaoUsuario(b.dataset.aprovar, 'aprovar'));
    pend.querySelectorAll('[data-recusar]').forEach(b => b.onclick = () => acaoUsuario(b.dataset.recusar, 'recusar'));
    pend.querySelectorAll('[data-info]').forEach(b => b.onclick = () => abrirInfoUsuario(USUARIOS_MAP[b.dataset.info]));
    pend.querySelectorAll('[data-verfoto]').forEach(b => b.onclick = () => verFotoUsuario(USUARIOS_MAP[b.dataset.verfoto]));

    popularFiltroAtivUsuario();
    renderAtivos();
    atualizarAdmStats();
    carregarAtividade();
  } catch (e) {
    pend.innerHTML = '<li class="cad-vazio">Erro ao carregar.</li>';
  }
}

/* ---------- Faixa de estatísticas do painel administrativo ----------
   Cada célula é rótulo + número + uma 3ª linha de CONTEXTO (quem são, desde quando, onde
   se concentra) — o número sozinho não diz se 12 alterações é muito, nem onde olhar.
   Tudo sai do que a aba já carregou (USUARIOS_MAP/LOGS_ACESSO/ATIVIDADE_EDICOES); sem chamada nova.
   Ex.: 3 falhas de 2 contas distintas nas últimas 24 h → "últimas 24 h, 2 contas". */
function atualizarAdmStats() {
  const box = document.getElementById('admStats');
  if (!box) return;
  const todos = Object.values(USUARIOS_MAP);
  const ativos = USUARIOS_ATIVOS.length;
  const admins = USUARIOS_ATIVOS.filter(u => ehNivelAdmin(u.nivel) || u.ehAdminMestre).length;
  const listaPend = todos.filter(u => u.status === 'pendente');
  const ini = new Date(); ini.setHours(0, 0, 0, 0); const hoje0 = ini.getTime();
  const ha24h = Date.now() - 86400000;

  const entrouHoje = LOGS_ACESSO.filter(l => l.evento === 'entrou' && (l.ts || 0) >= hoje0);
  const pessoasHoje = new Set(entrouHoje.map(l => l.usuario || l.nome)).size;
  const edicoesHoje = ATIVIDADE_EDICOES.filter(e => (e.ts || 0) >= hoje0);
  const falhas24h = LOGS_ACESSO.filter(l => l.evento === 'falhou' && (l.ts || 0) >= ha24h);
  const contasFalha = new Set(falhas24h.map(l => l.usuario || l.nome)).size;

  // Em que aba as alterações de hoje se concentram (a aba sai de abaDaEdicao, a mesma da lista).
  const porAba = {};
  edicoesHoje.forEach(e => { const a = abaDaEdicao(e); if (a) porAba[a] = (porAba[a] || 0) + 1; });
  const topAba = Object.entries(porAba).sort((a, b) => b[1] - a[1])[0];

  // Espera do pedido mais antigo ainda sem resposta.
  const maisAntigo = listaPend.reduce((min, u) => (u.criadoEm && (!min || u.criadoEm < min) ? u.criadoEm : min), 0);
  const diasEspera = maisAntigo ? Math.floor((Date.now() - maisAntigo) / 86400000) : 0;

  const cards = [
    { n: ativos, r: 'Usuários ativos', estado: '', sub: `${admins} ${plural(admins, 'administrador', 'administradores')}` },
    {
      n: listaPend.length, r: 'Aguardando aprovação', estado: listaPend.length ? 'aviso' : '',
      sub: !listaPend.length ? 'nenhum pedido na fila'
        : (diasEspera >= 1 ? `há ${diasEspera} ${plural(diasEspera, 'dia', 'dias')}, sem resposta` : 'pedido de hoje'),
    },
    { n: entrouHoje.length, r: 'Acessos hoje', estado: '', sub: `${pessoasHoje} ${plural(pessoasHoje, 'pessoa distinta', 'pessoas distintas')}` },
    {
      n: edicoesHoje.length, r: 'Alterações hoje', estado: '',
      sub: topAba ? `${topAba[0]} concentra ${topAba[1]}` : 'nada alterado ainda',
    },
    {
      n: falhas24h.length, r: 'Falhas de login', estado: falhas24h.length ? 'risco' : '',
      sub: falhas24h.length ? `últimas 24 h, ${contasFalha} ${plural(contasFalha, 'conta', 'contas')}` : 'últimas 24 h, nenhuma',
    },
  ];
  box.innerHTML = cards.map(c => kpiV2(c.r, String(c.n), { estado: c.estado, nota: c.sub })).join('');
}

// Resumo textual do acesso de um usuário, exibido inline na lista (mesma lógica do
// modal de Permissões, condensada: quem edita cada área vs. quem só vê).
function resumoPermissoesUsr(u) {
  if (u.ehAdminMestre || ehNivelAdmin(u.nivel)) {
    return '<div class="usr-perm-resumo"><span class="usr-perm-rot">Acesso:</span><span class="usr-perm-chip">todas as abas</span></div>';
  }
  const todasAreas = GRUPOS_PERM.flatMap(g => g.areas).filter(a => AREA_ROTULOS[a]);
  const perm = u.permissoes || {};
  const valorArea = (a) => (perm[a] === 'ver' || perm[a] === 'nenhum') ? perm[a] : 'editar';
  const editList = todasAreas.filter(a => valorArea(a) === 'editar').map(a => AREA_ROTULOS[a]);
  const verList = todasAreas.filter(a => valorArea(a) === 'ver').map(a => AREA_ROTULOS[a]);
  if (!editList.length && verList.length === todasAreas.length) {
    return '<div class="usr-perm-resumo"><span class="usr-perm-rot">Só vê:</span><span class="usr-perm-chip">todas as abas liberadas</span><span class="usr-perm-chip">sem edição</span></div>';
  }
  // `cls` separa os dois tons do desenho: quem EDITA puxa para o azul da marca, quem só vê fica
  // no cinza neutro — dá para ler o alcance de cada pessoa sem comparar rótulo por rótulo.
  const grupoChips = (rotulo, lista, max, cls) => {
    if (!lista.length) return '';
    const visiveis = lista.slice(0, max);
    const resto = lista.length - visiveis.length;
    const chips = visiveis.map(n => `<span class="usr-perm-chip ${cls}">${esc(n)}</span>`).join('') +
      (resto > 0 ? `<span class="usr-perm-chip ${cls} usr-perm-mais">+${resto}</span>` : '');
    return `<span class="usr-perm-rot">${esc(rotulo)}:</span>${chips}`;
  };
  const partes = [grupoChips('Edita', editList, 3, 'edita'), grupoChips('só vê', verList, 1, '')].filter(Boolean);
  return partes.length ? `<div class="usr-perm-resumo">${partes.join(' ')}</div>` : '';
}

// Renderiza a lista de usuários ativos aplicando o filtro da caixa de busca.
function renderAtivos() {
  const ativos = document.getElementById('listaAtivos');
  if (!ativos) return;
  const termo = (document.getElementById('buscaUsuarios')?.value || '').trim().toLowerCase();
  const nivelFiltro = document.querySelector('#segNivelUsr .usr-seg-btn.ativ')?.dataset.nivel || '';
  const lista = USUARIOS_ATIVOS.filter(u => {
    if (termo && !(u.nome + ' @' + u.usuario).toLowerCase().includes(termo)) return false;
    if (nivelFiltro === 'dev' && u.nivel !== 'dev') return false;
    if (nivelFiltro === 'admin' && !(u.nivel === 'admin' || u.ehAdminMestre)) return false;
    if (nivelFiltro === 'comum' && (ehNivelAdmin(u.nivel) || u.ehAdminMestre)) return false;
    return true;
  });
  document.getElementById('usrAtivosContagem').textContent =
    (termo || nivelFiltro) ? `${lista.length} de ${USUARIOS_ATIVOS.length}` : `${USUARIOS_ATIVOS.length} usuário(s)`;

  ativos.innerHTML = lista.length ? lista.map(u => `
    <li class="usr-item">
      ${htmlAvatarUsr(u)}
      <div class="usr-info">
        <div class="usr-nome"><span class="usr-clicavel" data-info="${esc(u.usuario)}" title="Ver dados / ID">${esc(u.nome)}</span> ${u.ehAdminMestre ? '<span class="usr-badge adm">admin mestre</span>' : (u.nivel === 'dev' ? '<span class="usr-badge dev">dev</span>' : (u.nivel === 'admin' ? '<span class="usr-badge adm">admin</span>' : ''))} ${(u.status === 'aprovado' && !u.ehAdminMestre && !ehNivelAdmin(u.nivel)) ? `<span class="usr-badge emp" title="Acesso por empresa/contrato na aba Funcionários">${u.empresasFunc === 'ambas' ? 'Ambas' : (u.empresasFunc === 'NTE' ? 'NTE' : (u.empresasFunc === 'SUL' ? 'SUL' : 'sem empresa'))}${(Array.isArray(u.contratosFunc) && u.contratosFunc.length) ? ` · ${u.contratosFunc.length} contrato${u.contratosFunc.length > 1 ? 's' : ''}` : ''}</span>` : ''} ${u.status === 'aprovado' ? '' : rotuloStatus(u.status)}<span class="usr-sub">@${esc(u.usuario)} · <span class="usr-id-mini">${esc(u.id || '')}</span></span></div>
        ${resumoPermissoesUsr(u)}
      </div>
      <div class="usr-acoes">
        <button class="btn btn-ghost small" data-atividade="${esc(u.usuario)}">Atividade</button>
        ${u.ehAdminMestre ? '' : `${u.status === 'aprovado' ? `<select class="usr-nivel-sel" data-nivelsel="${esc(u.usuario)}" title="Nível de acesso"><option value="comum"${!ehNivelAdmin(u.nivel) ? ' selected' : ''}>Comum</option><option value="admin"${u.nivel === 'admin' ? ' selected' : ''}>Admin</option><option value="dev"${u.nivel === 'dev' ? ' selected' : ''}>Dev</option></select>` : ''}${(u.status === 'aprovado' && !ehNivelAdmin(u.nivel)) ? `<button class="btn btn-ghost small" data-permissoes="${esc(u.usuario)}">Permissões</button>` : ''}<button class="btn btn-ghost small" data-senha="${esc(u.usuario)}" data-nome="${esc(u.nome)}">Senha</button><button class="btn btn-ghost small perigo" data-remover="${esc(u.usuario)}" data-nome="${esc(u.nome)}">Remover</button>`}
      </div>
    </li>`).join('') : `<li class="cad-vazio">${(termo || nivelFiltro) ? 'Nenhum usuário encontrado.' : 'Nenhum usuário ativo.'}</li>`;

  ativos.querySelectorAll('[data-remover]').forEach(b => b.onclick = () => removerUsuario(b.dataset.remover, b.dataset.nome));
  ativos.querySelectorAll('[data-senha]').forEach(b => b.onclick = () => abrirResetSenha(b.closest('.usr-item'), b.dataset.senha, b.dataset.nome));
  ativos.querySelectorAll('[data-info]').forEach(b => b.onclick = () => abrirInfoUsuario(USUARIOS_MAP[b.dataset.info]));
  ativos.querySelectorAll('[data-verfoto]').forEach(b => b.onclick = () => verFotoUsuario(USUARIOS_MAP[b.dataset.verfoto]));
  ativos.querySelectorAll('[data-nivelsel]').forEach(sel => sel.onchange = () => { const usuario = sel.dataset.nivelsel; mudarNivel(usuario, sel.value, USUARIOS_MAP[usuario]); });
  ativos.querySelectorAll('[data-permissoes]').forEach(b => b.onclick = () => abrirPermissoes(USUARIOS_MAP[b.dataset.permissoes]));
  ativos.querySelectorAll('[data-atividade]').forEach(b => b.onclick = () => abrirAtividadeUsuario(USUARIOS_MAP[b.dataset.atividade]));
}

/* ----- Modal de permissões de abas (admin define o que o usuário comum vê/edita) ----- */
let _permUsuarioAlvo = null;
function atualizarVisualPermissao(sel) {
  const linha = sel && sel.closest ? sel.closest('.perm-linha') : null;
  if (linha) linha.dataset.permissao = sel.value || 'editar';
}
async function abrirPermissoes(u) {
  if (!u) return;
  await carregarContratosFuncionarios();
  _permUsuarioAlvo = u;
  document.getElementById('permUsuarioNome').textContent = u.nome || ('@' + u.usuario);
  const lista = document.getElementById('permLista');
  const perm = u.permissoes || {}; // só guarda o que difere de 'editar'
  // reaproveita o MESMO ícone da sidebar (fonte única): pega o <svg> do botão daquela aba
  const iconeDe = (area) => { const svg = document.querySelector(`.side-nav .tab[data-tab="${area}"] svg`); return svg ? svg.outerHTML : ''; };
  const linha = (area, gi) => {
    const atual = (perm[area] === 'ver' || perm[area] === 'nenhum') ? perm[area] : 'editar';
    return `
      <div class="perm-linha" data-permissao="${atual}">
        <span class="perm-area">${iconeDe(area)}<span class="perm-area-nome">${esc(AREA_ROTULOS[area])}</span></span>
        <select class="perm-sel" data-area="${esc(area)}" data-grupo="${gi}">
          <option value="editar"${atual === 'editar' ? ' selected' : ''}>Ver e editar</option>
          <option value="ver"${atual === 'ver' ? ' selected' : ''}>Só ver</option>
          <option value="nenhum"${atual === 'nenhum' ? ' selected' : ''}>Sem acesso</option>
        </select>
      </div>`;
  };
  // agrupa igual à sidebar; cada grupo emite um título + "aplicar a todas" (por grupo) + suas abas
  lista.innerHTML = GRUPOS_PERM.map((g, gi) => {
    const linhas = g.areas.filter(a => AREA_ROTULOS[a]).map(a => linha(a, gi)).join('');
    if (!linhas) return '';
    const setTodas = `<select class="perm-grupo-set" data-grupo-set="${gi}" title="Aplicar a todas as abas deste grupo" aria-label="Aplicar a todas as abas de ${esc(g.titulo)}">
        <option value="">— aplicar a todas —</option>
        <option value="editar">Ver e editar</option>
        <option value="ver">Só ver</option>
        <option value="nenhum">Sem acesso</option>
      </select>`;
    return `<div class="perm-grupo-titulo"><span>${esc(g.titulo)}</span>${setTodas}</div>${linhas}`;
  }).join('');
  lista.querySelectorAll('.perm-sel').forEach(sel => {
    atualizarVisualPermissao(sel);
    sel.onchange = () => atualizarVisualPermissao(sel);
  });
  // "Aplicar a todas" por grupo: seta todas as linhas daquele grupo e volta ao placeholder.
  lista.querySelectorAll('.perm-grupo-set').forEach(sel => sel.onchange = () => {
    if (!sel.value) return;
    lista.querySelectorAll(`.perm-sel[data-grupo="${sel.dataset.grupoSet}"]`).forEach(s => { s.value = sel.value; atualizarVisualPermissao(s); });
    sel.value = '';
  });
  // Acesso por empresa (Funcionários): '' (nenhuma) | 'NTE' | 'SUL' | 'ambas'.
  { const se = document.getElementById('permEmpresaSel');
    if (se) {
      se.value = ['NTE', 'SUL', 'ambas'].includes(u.empresasFunc) ? u.empresasFunc : '';
      // Ao trocar a empresa, refaz a lista de contratos (mantendo os que continuam válidos).
      se.onchange = () => renderPermContratos(coletarContratosMarcados());
    }
  }
  // Acesso por contrato: marca os já liberados; lista depende da empresa selecionada.
  renderPermContratos(new Set((u.contratosFunc || []).map(String)));
  document.getElementById('permissoesModal').hidden = false;
}
// Monta os checkboxes de contratos no modal, conforme a empresa escolhida. `marcados` = Set de números.
function renderPermContratos(marcados) {
  const wrap = document.getElementById('permContratosWrap');
  if (!wrap) return;
  if (!EMPRESAS_CONTRATOS.length && !_contratosFuncCarregado) {
    wrap.hidden = false;
    wrap.innerHTML = '<p class="func-docs-vazio">Carregando contratos...</p>';
    carregarContratosFuncionarios().then(() => renderPermContratos(marcados));
    return;
  }
  const empresaVal = (document.getElementById('permEmpresaSel') || {}).value || '';
  const siglas = empresaVal === 'ambas' ? EMPRESAS_CONTRATOS.map(e => e.sigla) : (empresaVal ? [empresaVal] : []);
  if (!siglas.length) { wrap.hidden = true; wrap.innerHTML = ''; return; } // "Nenhuma" → sem contratos
  const blocos = EMPRESAS_CONTRATOS.filter(e => siglas.includes(e.sigla)).map(e => {
    const itens = e.contratos.map(c => {
      const ck = marcados.has(c.numero) ? ' checked' : '';
      const nome = ehContratoEscritorio(c) ? 'Escritório (Administrativo)' : c.nome;
      return `<label class="perm-ctr-item"><input type="checkbox" class="perm-ctr-chk" value="${esc(c.numero)}"${ck} />
        <span class="perm-ctr-nome">${esc(nome)} <small>Nº ${esc(c.numero)}</small></span></label>`;
    }).join('');
    return `<div class="perm-ctr-emp"><div class="perm-ctr-emp-tit">${esc(rotuloEmpresaContrato(e))}</div>${itens}</div>`;
  }).join('');
  wrap.hidden = false;
  wrap.innerHTML = `<div class="perm-ctr-cab">Contratos liberados <span class="perm-empresa-sub">— nenhum marcado = todos os contratos da empresa</span></div>${blocos}`;
}
function coletarContratosMarcados() {
  const s = new Set();
  document.querySelectorAll('#permContratosWrap .perm-ctr-chk:checked').forEach(c => s.add(c.value));
  return s;
}
function fecharPermissoes() { document.getElementById('permissoesModal').hidden = true; _permUsuarioAlvo = null; }
async function salvarPermissoes() {
  if (!_permUsuarioAlvo) return;
  const permissoes = {};
  document.querySelectorAll('#permLista .perm-sel').forEach(s => { permissoes[s.dataset.area] = s.value; });
  const empresasFunc = (document.getElementById('permEmpresaSel') || {}).value || '';
  const contratosFunc = [...coletarContratosMarcados()];
  // "Nenhuma empresa" anula a permissão de Funcionários/Admissão (a aba some mesmo com
  // 'ver'/'editar') — era o jeito de o admin conceder acesso que nunca aparecia.
  const precisaEmpresa = ['funcionarios', 'admissao'].some((a) => (permissoes[a] || 'editar') !== 'nenhum');
  if (precisaEmpresa && !empresasFunc) {
    const se = document.getElementById('permEmpresaSel');
    if (se) { se.classList.add('data-invalida'); se.focus(); se.onchange = () => { se.classList.remove('data-invalida'); renderPermContratos(coletarContratosMarcados()); }; }
    toast('Escolha NTE, SUL ou ambas em "Acesso por empresa" — sem empresa, Funcionários e Form. Admissão não aparecem. Ou deixe essas abas em "Não ver".', 'erro');
    return;
  }
  try {
    const r = await fetch(`/api/usuarios/${encodeURIComponent(_permUsuarioAlvo.usuario)}/permissoes`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ permissoes, empresasFunc, contratosFunc }),
    });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) return toast(j.erro || 'Erro ao salvar.', 'erro');
    toast('Permissões salvas.', 'ok');
    fecharPermissoes();
    carregarUsuarios();
  } catch (e) { toast('Erro de conexão.', 'erro'); }
}
// Atalhos "Tudo: ..." e botões do modal (ligados uma vez no carregamento).
document.querySelectorAll('#permissoesModal [data-perm-todos]').forEach(b => b.onclick = () => {
  document.querySelectorAll('#permLista .perm-sel').forEach(s => { s.value = b.dataset.permTodos; atualizarVisualPermissao(s); });
});
{ const x = document.getElementById('fecharPermissoes'); if (x) x.onclick = fecharPermissoes; }
{ const c = document.getElementById('permCancelar'); if (c) c.onclick = fecharPermissoes; }
{ const sv = document.getElementById('permSalvar'); if (sv) sv.onclick = salvarPermissoes; }
fecharAoClicarNoFundo('permissoesModal', fecharPermissoes);

async function acaoUsuario(usuario, acao) {
  try {
    const r = await fetch(`/api/usuarios/${encodeURIComponent(usuario)}/${acao}`, { method: 'POST' });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) return toast(j.erro || 'Erro.', 'erro');
    toast(acao === 'aprovar' ? 'Usuário aprovado!' : 'Pedido recusado.', 'ok');
    carregarUsuarios();
  } catch (e) { toast('Erro de conexão.', 'erro'); }
}

// Mostra um campo inline para definir uma nova senha do usuário.
function abrirResetSenha(li, usuario, nome) {
  if (!li) return;
  const acoes = li.querySelector('.usr-acoes');
  acoes.innerHTML = `
    <input type="text" class="usr-senha-input" placeholder="Nova senha (mín. 4)" maxlength="60" autocomplete="off" />
    <button class="btn btn-primary small reset-salvar">Salvar</button>
    <button class="btn btn-ghost small reset-cancelar">Cancelar</button>`;
  const inp = acoes.querySelector('.usr-senha-input');
  inp.focus();
  const salvar = async () => {
    const senha = inp.value;
    if (senha.length < 4) return toast('A senha precisa ter pelo menos 4 caracteres.', 'erro');
    try {
      const r = await fetch(`/api/usuarios/${encodeURIComponent(usuario)}/senha`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ senha }),
      });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) return toast(j.erro || 'Erro.', 'erro');
      toast(`Senha de ${nome} redefinida.`, 'ok');
      carregarUsuarios();
    } catch (e) { toast('Erro de conexão.', 'erro'); }
  };
  acoes.querySelector('.reset-salvar').onclick = salvar;
  acoes.querySelector('.reset-cancelar').onclick = () => carregarUsuarios();
  inp.onkeydown = (e) => { if (e.key === 'Enter') salvar(); else if (e.key === 'Escape') carregarUsuarios(); };
}

async function mudarNivel(usuario, para, dados) {
  const nome = (dados && dados.nome) || usuario;
  const rotulos = { dev: 'desenvolvedor (acesso total)', admin: 'administrador', comum: 'usuário comum' };
  const perguntas = {
    dev: `Promover "${nome}" a desenvolvedor? Ele terá acesso TOTAL a tudo (igual a um admin); use só para a equipe de desenvolvimento.`,
    admin: `Promover "${nome}" a administrador? Ele poderá aprovar cadastros e gerenciar usuários.`,
    comum: `Rebaixar "${nome}" para usuário comum? Ele perde o acesso ao painel de Usuários.`,
  };
  const okTexto = para === 'comum' ? 'Rebaixar' : 'Promover';
  if (!(await confirmar(perguntas[para] || `Alterar o nível de "${nome}"?`, { okTexto, perigo: para === 'dev' }))) {
    carregarUsuarios(); // cancelou → recarrega para reverter o seletor ao valor real
    return;
  }
  try {
    const r = await fetch(`/api/usuarios/${encodeURIComponent(usuario)}/nivel`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ nivel: para }),
    });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) { toast(j.erro || 'Erro.', 'erro'); carregarUsuarios(); return; }
    toast(`${nome} agora é ${rotulos[para] || para}.`, 'ok');
    carregarUsuarios();
  } catch (e) { toast('Erro de conexão.', 'erro'); carregarUsuarios(); }
}

async function removerUsuario(usuario, nome) {
  if (!(await confirmar(`Remover o usuário "${nome}" (@${usuario})? Ele perde o acesso imediatamente.`, { perigo: true, okTexto: 'Remover' }))) return;
  try {
    const r = await fetch('/api/usuarios/' + encodeURIComponent(usuario), { method: 'DELETE' });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) return toast(j.erro || 'Erro.', 'erro');
    toast('Usuário removido.', 'ok');
    carregarUsuarios();
  } catch (e) { toast('Erro de conexão.', 'erro'); }
}

// Busca de usuários ativos (filtra a lista já carregada, sem novo fetch)
(function ligarBuscaUsuarios() {
  const busca = document.getElementById('buscaUsuarios');
  if (busca) busca.oninput = () => renderAtivos();
})();

/* ============================================================
   ATIVIDADE NO SISTEMA (auditoria); quem alterou o quê e quando.
   Edições vêm do histórico (campo `por` = nome de quem fez).
   ============================================================ */
// Classifica a `acao` bruta do histórico em um grupo para o filtro/ícone.
function categoriaAcao(acao) {
  const a = (acao || '').toLowerCase();
  if (/(adicion|criou|registr|incluiu)/.test(a)) return 'adicionou';
  if (/(exclu|remov|apag|limp|zerad)/.test(a)) return 'excluiu';
  if (/(import|restaur)/.test(a)) return 'importou';
  if (/(edit|atualiz|troc|alter|marc)/.test(a)) return 'editou';
  return 'outros';
}
const ACAO_ICONE = { adicionou: '＋', editou: '✎', excluiu: '🗑', importou: '⇪', outros: '•', acesso: '🔑' };

// Popula o <select> de usuários do filtro de atividade a partir dos ativos.
function popularFiltroAtivUsuario() {
  const sel = document.getElementById('filtroAtivUsuario');
  if (!sel) return;
  const atual = sel.value;
  const nomes = [...new Set(USUARIOS_ATIVOS.map(u => u.nome).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'pt-BR'));
  sel.innerHTML = '<option value="">Todos os usuários</option>' +
    nomes.map(n => `<option value="${esc(n)}">${esc(n)}</option>`).join('');
  if (nomes.includes(atual)) sel.value = atual;
}

async function carregarAtividade() {
  const lista = document.getElementById('listaAtividade');
  if (!lista) return;
  lista.innerHTML = '<li class="cad-vazio">Carregando...</li>';
  try {
    const r = await fetch('/api/usuarios/atividade?limite=500', { cache: 'no-store' });
    if (!r.ok) { lista.innerHTML = '<li class="cad-vazio">Sem permissão.</li>'; return; }
    const j = await r.json();
    ATIVIDADE_EDICOES = Array.isArray(j.edicoes) ? j.edicoes : [];
    renderAtividade();
    atualizarAdmStats();
  } catch (e) { lista.innerHTML = '<li class="cad-vazio">Erro ao carregar.</li>'; }
}

// Filtra as edições por período (string do <select>: '', 'hoje', '7', '30').
function dentroDoPeriodo(ts, periodo) {
  if (!periodo) return true;
  const t = ts || 0;
  if (periodo === 'hoje') { const d = new Date(); d.setHours(0, 0, 0, 0); return t >= d.getTime(); }
  const dias = parseInt(periodo, 10);
  if (!dias) return true;
  return t >= Date.now() - dias * 86400000;
}

function fmtQuando(ts) {
  return ts ? new Date(ts).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', year: '2-digit', hour: '2-digit', minute: '2-digit' }) : '—';
}

// Deduz em QUAL ABA/seção a alteração foi feita, a partir dos sinais da entrada do histórico
// (o histórico não guarda a aba; inferimos por rast/funcId/placa e pelo prefixo do texto, que
// cada módulo grava de forma reconhecível). Mostra ao admin "onde o usuário mexeu nos dados".
function abaDaEdicao(e) {
  const t = e.texto || '';
  const acao = e.acao || '';
  if (e.rast) return 'Rastreadores';
  if (e.funcId) return 'Funcionários';
  // Entradas com placa: veículo (Frota), multa, manutenção, abastecimento ou instalação.
  if (e.placa) {
    if (/^Multa/i.test(t)) return 'Multas';
    if (/^Manuten/i.test(t) || acao === 'trocou o motorista') return 'Manutenção';
    if (/^Abastec/i.test(t)) return 'Abastecimento';
    if (/^Instala/i.test(t)) return 'Instalações';
    return 'Frota'; // add/excluir de veículo e diffs de campos (STATUS:, VALOR FIPE:, DOC: ...)
  }
  // Sem placa: identifica pelo prefixo do texto.
  if (/^Modo manuten[çc][ãa]o/i.test(t)) return 'Sistema';
  if (/funcion[áa]rio|controle de vencimentos/i.test(t)) return 'Funcionários';
  if (/^Programa SST/i.test(t)) return 'Programas SST';
  if (/^A[çc][ãa]o SST/i.test(t)) return 'Ações de Segurança';
  if (/^Fornecedor/i.test(t)) return 'Fornecedores';
  if (/^Manuten/i.test(t)) return 'Manutenção';
  if (/^Abastec/i.test(t)) return 'Abastecimento';
  if (/^Instala/i.test(t)) return 'Instalações';
  if (/^Envio/i.test(t)) return 'Envios';
  if (/multa/i.test(t)) return 'Multas';
  if (/^Ve[íi]culo|^Planilha importada/i.test(t)) return 'Frota';
  if (/^Rastreador/i.test(t)) return 'Rastreadores';
  if (/^Aporte|^Empr[ée]stimo|^NF |^Retirada/i.test(t)) return 'Aportes';
  if (/^Contrato|parcelas/i.test(t)) return 'Contratos';
  // Painel administrativo (usuários/acesso).
  if (/^Cadastro aprovado|^Cadastro recusado|^Cadastros de usu[áa]rio|^Usu[áa]rio removido|^N[íi]vel alterado|^Senha redefinida|^Permiss[õo]es de abas/i.test(t)) return 'Painel Administrativo';
  // Cadastros (centros de custo / responsáveis).
  if (/^Cadastro renomeado/i.test(t)) return 'Cadastros';
  return '';
}
// Monta o <li> de uma alteração do histórico.
// Identifica QUEM/o quê foi alterado: placa (Frota/Multas/...), código (Rastreadores) ou
// o nome do funcionário (salvo em e.func; fallback resolve pelo funcId na lista carregada).
function alvoDaEdicao(e) {
  if (e.placa) return e.placa;
  if (e.rast) return e.rast;
  if (e.func) return e.func;
  if (e.funcId && typeof FUNCIONARIOS !== 'undefined') { const f = FUNCIONARIOS.find(x => x.id === e.funcId); if (f) return f.nome || ''; }
  return '';
}
// A entrada se lê como uma frase — "<quem> <ação> <o quê>" — com o ponto colorido dando a
// natureza da ação e a linha de baixo dizendo onde e quando. As pílulas de aba/ação saíram do
// texto: repetiam em toda linha o que a cor do ponto e a meta já dizem, e nesta coluna estreita
// empurravam a frase para três linhas.
function liEdicao(e) {
  const cat = categoriaAcao(e.acao);
  const a = alvoDaEdicao(e);
  const alvo = a ? ` · ${esc(a)}` : '';
  const quem = e.por ? `<b class="atv-quem" data-quem="${esc(e.por)}">${esc(e.por)}</b>` : '<b>Sistema</b>';
  const aba = abaDaEdicao(e);
  return `
    <li class="usr-item">
      <div class="atv-linha">
        <span class="atv-dot ${cat}" title="${esc(e.acao || '')}"></span>
        <div class="atv-corpo">
          <div class="atv-texto">${quem} ${esc(e.acao || '—')} ${esc(e.texto || '')}</div>
          <div class="atv-meta">${aba ? esc(aba) + ' · ' : ''}${esc(fmtQuando(e.ts))}${alvo}</div>
        </div>
      </div>
    </li>`;
}

function renderAtividade() {
  const lista = document.getElementById('listaAtividade');
  if (!lista) return;
  const termo = (document.getElementById('buscaAtividade')?.value || '').trim().toLowerCase();
  const usuario = document.getElementById('filtroAtivUsuario')?.value || '';
  const periodo = document.getElementById('filtroAtivPeriodo')?.value || '';
  const filtrados = ATIVIDADE_EDICOES.filter(e => {
    if (usuario && (e.por || '') !== usuario) return false;
    if (!dentroDoPeriodo(e.ts, periodo)) return false;
    if (termo) {
      const txt = ((e.texto || '') + ' ' + (e.por || '') + ' ' + (e.acao || '') + ' ' + (e.placa || '') + ' ' + (e.rast || '') + ' ' + (e.func || '')).toLowerCase();
      if (!txt.includes(termo)) return false;
    }
    return true;
  });
  const cont = document.getElementById('atividadeContagem');
  const filtrando = termo || usuario || periodo;
  // Plural resolvido de verdade ("31 alterações", "1 alteração"): o "alteração(ões)" antigo era
  // longo e quebrava em duas linhas no canto do card, empilhando número e rótulo.
  const n = ATIVIDADE_EDICOES.length;
  if (cont) cont.textContent = n
    ? (filtrando ? `${filtrados.length} de ${n}` : `${n} ${n === 1 ? 'alteração' : 'alterações'}`)
    : '';
  lista.innerHTML = filtrados.length
    ? filtrados.map(liEdicao).join('')
    : `<li class="cad-vazio">${filtrando ? 'Nenhuma alteração encontrada.' : 'Nenhuma alteração registrada.'}</li>`;
  // Clicar no nome de quem fez abre a atividade individual daquele usuário.
  lista.querySelectorAll('.atv-quem').forEach(s => s.onclick = () => {
    const u = USUARIOS_ATIVOS.find(x => x.nome === s.dataset.quem);
    if (u) abrirAtividadeUsuario(u);
  });
}

(function ligarAtividade() {
  const busca = document.getElementById('buscaAtividade');
  if (busca) busca.oninput = () => renderAtividade();
  ['filtroAtivUsuario', 'filtroAtivPeriodo'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.onchange = () => renderAtividade();
  });
})();

/* ---------- Atividade individual do usuário (modal) ---------- */
let _atvUsuarioAlvo = null;
function abrirAtividadeUsuario(u) {
  if (!u) return;
  _atvUsuarioAlvo = u;
  document.getElementById('atvTitulo').textContent = 'Atividade de ' + (u.nome || ('@' + u.usuario));
  // reseta filtros do modal
  const b = document.getElementById('atvBusca'); if (b) b.value = '';
  const t = document.getElementById('atvFiltroTipo'); if (t) t.value = '';
  const p = document.getElementById('atvFiltroPeriodo'); if (p) p.value = '';
  renderAtividadeUsuario();
  document.getElementById('atividadeUsuarioModal').hidden = false;
}
function fecharAtividadeUsuario() { document.getElementById('atividadeUsuarioModal').hidden = true; _atvUsuarioAlvo = null; }

// Junta edições (histórico, por nome) + acessos (logs, por usuário) num só fluxo ordenado.
function eventosDoUsuario(u) {
  const edicoes = ATIVIDADE_EDICOES.filter(e => (e.por || '') === u.nome)
    .map(e => ({ tipo: 'edicao', ts: e.ts || 0, dados: e }));
  const acessos = LOGS_ACESSO.filter(l => (l.usuario || '') === u.usuario)
    .map(l => ({ tipo: 'acesso', ts: l.ts || 0, dados: l }));
  return edicoes.concat(acessos).sort((a, b) => (b.ts || 0) - (a.ts || 0));
}

function renderAtividadeUsuario() {
  const u = _atvUsuarioAlvo;
  if (!u) return;
  const eventos = eventosDoUsuario(u);
  const edicoes = eventos.filter(ev => ev.tipo === 'edicao');
  const acessos = eventos.filter(ev => ev.tipo === 'acesso');
  // Resumo
  const ultimoAcesso = acessos.find(a => a.dados.evento === 'entrou');
  const cont = {};
  edicoes.forEach(ev => { const c = categoriaAcao(ev.dados.acao); cont[c] = (cont[c] || 0) + 1; });
  const top = Object.entries(cont).sort((a, b) => b[1] - a[1])[0];
  const ROT_CAT = { adicionou: 'Adições', editou: 'Edições', excluiu: 'Exclusões', importou: 'Importações', outros: 'Outras' };
  const resumo = document.getElementById('atvResumo');
  if (resumo) resumo.innerHTML = `
    <div class="adm-stat brand"><span class="adm-stat-num">${edicoes.length}</span><span class="adm-stat-rot">Alterações</span></div>
    <div class="adm-stat green"><span class="adm-stat-num">${acessos.filter(a => a.dados.evento === 'entrou').length}</span><span class="adm-stat-rot">Acessos</span></div>
    <div class="adm-stat"><span class="adm-stat-num" style="font-size:14px">${top ? esc(ROT_CAT[top[0]] || top[0]) : '—'}</span><span class="adm-stat-rot">Ação mais comum</span></div>
    <div class="adm-stat"><span class="adm-stat-num" style="font-size:13px">${ultimoAcesso ? esc(fmtQuando(ultimoAcesso.ts)) : '—'}</span><span class="adm-stat-rot">Último acesso</span></div>`;
  // Lista filtrada
  const termo = (document.getElementById('atvBusca')?.value || '').trim().toLowerCase();
  const tipo = document.getElementById('atvFiltroTipo')?.value || '';
  const periodo = document.getElementById('atvFiltroPeriodo')?.value || '';
  const filtrados = eventos.filter(ev => {
    if (tipo && ev.tipo !== tipo) return false;
    if (!dentroDoPeriodo(ev.ts, periodo)) return false;
    if (termo) {
      const d = ev.dados;
      const txt = ev.tipo === 'edicao'
        ? ((d.texto || '') + ' ' + (d.acao || '') + ' ' + (d.placa || '') + ' ' + (d.rast || '') + ' ' + (d.func || '')).toLowerCase()
        : ((d.evento || '') + ' ' + (d.ip || '')).toLowerCase();
      if (!txt.includes(termo)) return false;
    }
    return true;
  });
  const lista = document.getElementById('atvLista');
  if (!lista) return;
  lista.innerHTML = filtrados.length ? filtrados.map(ev => {
    if (ev.tipo === 'edicao') return liEdicao(ev.dados);
    const info = LOG_EVENTO_INFO[ev.dados.evento] || { txt: esc(ev.dados.evento || ''), cls: 'pend' };
    return `
      <li class="usr-item">
        <div class="atv-linha">
          <div class="atv-ico">${ACAO_ICONE.acesso}</div>
          <div class="atv-corpo">
            <div class="atv-texto"><span class="acao-tag acesso">acesso</span> ${esc(info.txt)}</div>
            <div class="atv-meta">${esc(fmtQuando(ev.ts))}${ev.dados.ip ? ' · ' + esc(ev.dados.ip) : ''}</div>
          </div>
        </div>
      </li>`;
  }).join('') : `<li class="cad-vazio">${(termo || tipo || periodo) ? 'Nada encontrado com esses filtros.' : 'Nenhuma atividade registrada para este usuário.'}</li>`;
}

(function ligarAtividadeUsuario() {
  const x = document.getElementById('fecharAtividade');
  if (x) x.onclick = fecharAtividadeUsuario;
  const b = document.getElementById('atvBusca');
  if (b) b.oninput = () => renderAtividadeUsuario();
  ['atvFiltroTipo', 'atvFiltroPeriodo'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.onchange = () => renderAtividadeUsuario();
  });
  fecharAoClicarNoFundo('atividadeUsuarioModal', fecharAtividadeUsuario);
})();

/* ---------- Logs de acesso (admin vê quem logou e quando) ---------- */
let LOGS_ACESSO = []; // cache da última carga (para filtrar sem novo fetch)
const LOG_EVENTO_INFO = {
  entrou: { txt: 'entrou', cls: 'ok' },
  falhou: { txt: 'senha errada', cls: 'rec' },
  bloqueado: { txt: 'bloqueado', cls: 'pend' },
};
async function carregarLogsAcesso() {
  const lista = document.getElementById('listaLogsAcesso');
  if (!lista) return;
  lista.innerHTML = '<li class="cad-vazio">Carregando...</li>';
  try {
    const r = await fetch('/api/usuarios/logs?limite=200', { cache: 'no-store' });
    if (!r.ok) { lista.innerHTML = '<li class="cad-vazio">Sem permissão.</li>'; return; }
    const j = await r.json();
    LOGS_ACESSO = Array.isArray(j.logs) ? j.logs : [];
    renderLogsAcesso();
    atualizarAdmStats();
  } catch (e) { lista.innerHTML = '<li class="cad-vazio">Erro ao carregar.</li>'; }
}
function renderLogsAcesso() {
  const lista = document.getElementById('listaLogsAcesso');
  if (!lista) return;
  const termo = (document.getElementById('buscaLogs')?.value || '').trim().toLowerCase();
  const ev = document.getElementById('filtroLogEvento')?.value || '';
  const filtrados = LOGS_ACESSO.filter(l =>
    (!ev || l.evento === ev) &&
    (!termo || ((l.usuario || '') + ' ' + (l.nome || '')).toLowerCase().includes(termo)));
  const cont = document.getElementById('logsAcessoContagem');
  const nLogs = LOGS_ACESSO.length; // mesmo motivo da aba Alterações: rótulo curto, uma linha só
  if (cont) cont.textContent = filtrados.length
    ? (termo || ev ? `${filtrados.length} de ${nLogs}` : `${nLogs} ${nLogs === 1 ? 'acesso' : 'acessos'}`)
    : '';
  // Mesma anatomia da aba Alterações (ponto + frase + meta), para as duas listas do card
  // Auditoria se lerem como uma só: "<quem> entrou no sistema" / "· data · IP · navegador".
  lista.innerHTML = filtrados.length ? filtrados.map(l => {
    const info = LOG_EVENTO_INFO[l.evento] || { txt: esc(l.evento || ''), cls: 'pend' };
    const quando = l.ts ? new Date(l.ts).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', year: '2-digit', hour: '2-digit', minute: '2-digit' }) : '—';
    const quem = l.nome ? esc(l.nome) : '@' + esc(l.usuario || '?');
    const arroba = l.nome ? ` <span class="usr-sub">@${esc(l.usuario || '?')}</span>` : '';
    return `
      <li class="usr-item">
        <div class="atv-linha">
          <span class="atv-dot ${esc(l.evento || '')}"></span>
          <div class="atv-corpo">
            <div class="atv-texto"><b>${quem}</b>${arroba} ${info.txt}</div>
            <div class="atv-meta">${esc(quando)}${l.ip ? ' · ' + esc(l.ip) : ''}${l.dispositivo ? ' · ' + esc(l.dispositivo) : ''}</div>
          </div>
        </div>
      </li>`;
  }).join('') : '<li class="cad-vazio">Nenhum acesso registrado.</li>';
}
(function ligarLogsAcesso() {
  const busca = document.getElementById('buscaLogs');
  if (busca) busca.oninput = () => renderLogsAcesso();
  const filtro = document.getElementById('filtroLogEvento');
  if (filtro) filtro.onchange = () => renderLogsAcesso();
})();

