/* ---------- Exportar Excel das abas + Backup ---------- */
const _exporta = (id, url) => { const b = document.getElementById(id); if (b) b.onclick = () => { window.location = url; }; };
_exporta('btnExportMultas', '/api/multas/exportar');
_exporta('btnExportRast', '/api/rastreadores/exportar');
_exporta('btnExportInst', '/api/instalacoes/exportar');
_exporta('btnExportEnvios', '/api/envios/exportar');
// O botão "Backup" abre o módulo completo (gerar/restaurar/histórico/configurações) — ver BackupUI.

/* ============================================================
   SIMULADOR BANCÁRIO; Empréstimo · Financiamento · Consórcio
   Calculadora 100% no navegador. O CET (Custo Efetivo Total) é a
   TIR do fluxo de caixa com TODOS os custos. Sem backend.
   ============================================================ */

// Lê número aceitando formato BR ("1.180,00") ou simples ("1180.00" / "18").
function numBR(x) {
  let s = String(x == null ? '' : x).trim().replace(/[^\d.,-]/g, '');
  if (!s) return NaN;
  const temVirg = s.includes(','), temPonto = s.includes('.');
  if (temVirg && temPonto) {
    // o separador decimal é o último que aparece
    if (s.lastIndexOf(',') > s.lastIndexOf('.')) s = s.replace(/\./g, '').replace(',', '.'); // BR: 1.180,00
    else s = s.replace(/,/g, ''); // US: 1,180.00
  } else if (temVirg) {
    s = s.replace(',', '.'); // vírgula = decimal
  } else if (temPonto) {
    // só ponto: se parecer separador de milhar (grupos de 3) → remove; senão é decimal
    const partes = s.split('.');
    const ehMilhar = partes.length > 1 && partes[0].length <= 3 && partes.slice(1).every(p => p.length === 3);
    if (ehMilhar) s = s.replace(/\./g, '');
  }
  return Number(s);
}
// % com 2 casas (recebe FRAÇÃO, ex.: 0,0214 → "2,14%"). O fmtPct existente usa 1 casa.
function fmtPct2(frac) { return (Number(frac) * 100).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%'; }

// ---- Núcleo: VPL, derivada e TIR (taxa interna de retorno) mensal ----
function simVpl(cf, i) { let v = 0; for (let t = 0; t < cf.length; t++) v += cf[t] / Math.pow(1 + i, t); return v; }
function simDVpl(cf, i) { let d = 0; for (let t = 1; t < cf.length; t++) d += (-t * cf[t]) / Math.pow(1 + i, t + 1); return d; }
// Taxa mensal (decimal) que zera o VPL. Newton-Raphson + fallback bisseção. null se não houver solução.
function tirMensal(cf, chute = 0.01) {
  if (!cf || cf.length < 2) return null;
  if (!cf.some(x => x > 0) || !cf.some(x => x < 0)) return null; // sem entrada+saída não há TIR
  let i = chute;
  for (let k = 0; k < 60; k++) {
    const v = simVpl(cf, i), d = simDVpl(cf, i);
    if (!isFinite(v) || !isFinite(d) || Math.abs(d) < 1e-12) break;
    const ni = i - v / d;
    if (!isFinite(ni) || ni <= -0.9999 || ni > 10) break;
    i = ni;
    if (Math.abs(simVpl(cf, i)) < 1e-9) return i;
  }
  // Fallback: bisseção num bracket seguro exigindo troca de sinal do VPL
  let lo = -0.9999, hi = 10, flo = simVpl(cf, lo), fhi = simVpl(cf, hi);
  if (!isFinite(flo) || !isFinite(fhi) || flo * fhi > 0) return null;
  for (let k = 0; k < 300; k++) {
    const mid = (lo + hi) / 2, fm = simVpl(cf, mid);
    if (Math.abs(fm) < 1e-7) return mid;
    if (flo * fm < 0) { hi = mid; } else { lo = mid; flo = fm; }
  }
  return (lo + hi) / 2;
}
const anualizar = (im) => Math.pow(1 + im, 12) - 1; // CET_anual = (1+cet_mensal)^12 − 1

// ---- Cálculos por produto (retornam todos os números prontos) ----
// Carência = meses iniciais ANTES das parcelas. No fluxo de caixa vira uma sequência de
// meses pagando só `jurosCarencia` (R$/mês; 0 = nada) antes de as parcelas começarem.
// Como o grosso do pagamento é adiado, a TIR (CET) cai — você fica mais tempo com o dinheiro.
const fluxoComCarencia = (recebido, parcela, n, carencia, jurosCarencia = 0) =>
  [recebido, ...Array(Math.max(0, carencia || 0)).fill(-(jurosCarencia || 0)), ...Array(n).fill(-parcela)];
function calcFinanciamento({ valor, entrada, parcela, n, carencia = 0, custos = 0, jurosCarencia = 0 }) {
  const financiado = valor - entrada;                 // a entrada é recurso próprio
  const liquido = financiado - custos;                // o que o crédito entrega de fato (descontados IOF/taxas/seguro)
  const pago = parcela * n + jurosCarencia * carencia; // total pago ao banco (parcelas + juros da carência)
  const montante = entrada + pago;                    // desembolso total (entrada própria + pago ao banco)
  const juros = pago - liquido;                       // custo do crédito sobre o líquido recebido
  const im = tirMensal(fluxoComCarencia(liquido, parcela, n, carencia, jurosCarencia)); // entrada NÃO entra na TIR do crédito
  return { financiado, liquido, custos, montante, juros, pctJuros: liquido > 0 ? juros / liquido : null,
    cetMensal: im, cetAnual: im == null ? null : anualizar(im), semJuros: pago <= liquido + 1e-6 };
}
function calcEmprestimo({ valor, parcela, n, garantia, carencia = 0, custos = 0, jurosCarencia = 0 }) {
  const liquido = valor - custos;                     // o que realmente entra no bolso (valor − IOF/taxas/seguro)
  const montante = parcela * n + jurosCarencia * carencia; // total desembolsado (juros da carência + parcelas)
  const juros = montante - liquido;                   // custo total sobre o líquido recebido
  const im = tirMensal(fluxoComCarencia(liquido, parcela, n, carencia, jurosCarencia)); // CET sobre o líquido
  return { montante, liquido, custos, juros, pctJuros: liquido > 0 ? juros / liquido : null,
    cetMensal: im, cetAnual: im == null ? null : anualizar(im), semJuros: montante <= liquido + 1e-6, garantia };
}
function calcConsorcio({ carta, parcela, n, txadm, fundo, seguro, l1, l2, l3, embutido, carencia = 0, custos = 0, jurosCarencia = 0 }) {
  const carenciaPago = (jurosCarencia || 0) * (carencia || 0);          // pagamentos feitos durante a carência
  const parcelasTotal = parcela * n;
  const txadmRS = carta * (txadm / 100), fundoRS = carta * (fundo / 100);
  const custoTaxas = parcelasTotal - carta;                             // taxas embutidas nas parcelas (acima da carta)
  const seguroRS = seguro ? Math.max(0, custoTaxas - txadmRS - fundoRS) : 0; // resíduo (sobre as parcelas, não a carência)
  const montante = parcelasTotal + carenciaPago;                        // total efetivamente pago = parcelas + carência (coerente c/ o CET)
  const custoTotal = custoTaxas + carenciaPago;                         // tudo acima da carta
  const liquido = carta - custos;                                       // carta menos custos iniciais pagos à parte
  const im = tirMensal(fluxoComCarencia(liquido, parcela, n, carencia, jurosCarencia)); // "carta líquida agora, paga em parcelas"
  const lanceMediaPct = (l1 + l2 + l3) / 3;
  const lanceTotalRS = carta * (lanceMediaPct / 100), embutidoRS = carta * (embutido / 100);
  return { montante, liquido, custos, carenciaPago, txadmRS, fundoRS, seguroRS, custoTotal, pctCusto: carta > 0 ? custoTotal / carta : null,
    cetMensal: im, cetAnual: im == null ? null : anualizar(im),
    lanceMediaPct, lanceTotalRS, embutidoRS, recursoProprio: Math.max(0, lanceTotalRS - embutidoRS),
    componentesFecham: Math.abs((carta + txadmRS + fundoRS + seguroRS + carenciaPago) - montante) < 1,
    seguroNegativo: seguro && (custoTaxas - txadmRS - fundoRS) < 0, embutidoExcede: embutidoRS > lanceTotalRS };
}

// ---- Veredito (compara a CET anual a uma banda; aceita taxa de referência informada) ----
function bandasVeredito(prod, garantia, refPct) {
  if (refPct > 0) return { bom: refPct, ok: refPct * 1.3, ctx: `a sua referência de ${fmtPct2(refPct / 100)} a.a.` };
  if (prod === 'financiamento') return { bom: 22, ok: 30, ctx: 'financiamento de veículo' };
  if (prod === 'emprestimo') return garantia ? { bom: 25, ok: 40, ctx: 'empréstimo COM garantia' } : { bom: 45, ok: 70, ctx: 'empréstimo SEM garantia' };
  return { bom: 12, ok: 18, ctx: 'consórcio (CET equivalente)' };
}
function vereditoCET(cetAnual, bom, ok, ctx) {
  if (cetAnual == null) return { classe: 'sim-v-neutro', texto: 'Não foi possível calcular o CET com estes números.' };
  const aa = cetAnual * 100;
  // CET negativo = input incoerente (as parcelas somam MENOS que o valor tomado). Não é
  // "bom negócio" — sinaliza para revisar os números em vez de exibir o balão verde.
  if (aa < 0) return { classe: 'sim-v-neutro', texto: `⚠️ Verifique os números; a CET ficou negativa (${fmtPct2(cetAnual)} a.a.): as parcelas somam menos que o valor tomado.` };
  if (aa <= bom) return { classe: 'sim-v-bom', texto: `✅ BOM NEGÓCIO; CET de ${fmtPct2(cetAnual)} a.a. está dentro/abaixo do esperado para ${ctx} (até ${bom}% a.a.).` };
  if (aa <= ok) return { classe: 'sim-v-ok', texto: `⚠ ACEITÁVEL; CET de ${fmtPct2(cetAnual)} a.a. é mediano para ${ctx} (faixa ${bom}–${ok}% a.a.). Dá para tentar negociar.` };
  return { classe: 'sim-v-ruim', texto: `❌ RUIM; CET de ${fmtPct2(cetAnual)} a.a. está ACIMA do esperado para ${ctx} (acima de ${ok}% a.a.). Caro.` };
}
const vHTML = (v) => `<div class="sim-veredito ${v.classe}">${v.texto}</div>`;
const cetTxt = (im) => im == null ? '—' : fmtPct2(im);
// Bloco "Fluxo considerado": descreve líquido (quando há custos) + carência (com/sem juros) + parcelas.
// Vale para os 3 produtos; `labelBase` é o nome do valor de origem (financiado/contratado/carta).
function blocoFluxoSim(inp, r, valorBase, labelBase) {
  const temCustos = r.custos > 0, temCar = inp.carencia > 0;
  if (!temCustos && !temCar) return ''; // nada de especial → sem bloco
  const partes = [];
  if (temCustos) partes.push(`recebe líquido <b>${fmtMoneyDec(r.liquido)}</b> (${labelBase} ${fmtMoneyDec(valorBase)} − custos ${fmtMoneyDec(r.custos)})`);
  if (temCar) partes.push(inp.jurosCarencia > 0
    ? `<b>${inp.carencia}</b> ${inp.carencia === 1 ? 'mês' : 'meses'} de carência pagando só <b>${fmtMoneyDec(inp.jurosCarencia)}</b>/mês`
    : `<b>${inp.carencia}</b> ${inp.carencia === 1 ? 'mês' : 'meses'} de carência sem pagar`);
  partes.push(`depois <b>${inp.n}</b> ${inp.n === 1 ? 'parcela' : 'parcelas'} de <b>${fmtMoneyDec(inp.parcela)}</b>`);
  const cetNota = (temCustos || inp.jurosCarencia > 0) ? ' O CET é calculado sobre o valor líquido, com os pagamentos da carência no fluxo.' : ' Adiar o pagamento já está refletido no CET.';
  return `<div class="sim-bloco"><b>Fluxo considerado:</b> ${partes.join('; ')}.${cetNota}</div>`;
}

// ---- Render por produto ----
function renderFinanciamento(r, inp) {
  document.getElementById('finCards').innerHTML =
    card('Valor financiado', fmtMoneyDec(r.financiado), '', true) +
    ((r.custos > 0) ? card('Valor líquido recebido', fmtMoneyDec(r.liquido), 'green', true, 'title="Valor financiado − custos do contrato (IOF, taxas, seguro). É a base do CET."') : '') +
    card('Montante total pago', fmtMoneyDec(r.montante), 'amber', true) +
    card('Total de juros', `${fmtMoneyDec(r.juros)}${r.pctJuros != null ? ' · ' + fmtPct2(r.pctJuros) : ''}`, 'red') +
    card('CET mensal', cetTxt(r.cetMensal), 'red') +
    card('CET anual', cetTxt(r.cetAnual), 'red');
  const b = bandasVeredito('financiamento', false, inp.ref);
  const vd = r.semJuros ? { classe: 'sim-v-bom', texto: '✅ Sem juros embutidos; as parcelas somam ≤ o valor financiado.' } : vereditoCET(r.cetAnual, b.bom, b.ok, b.ctx);
  const det = document.getElementById('finDetalhe');
  det.innerHTML = blocoFluxoSim(inp, r, r.financiado, 'financiado') + vHTML(vd) + `<button class="btn btn-ghost small sim-add">+ Adicionar à comparação</button>`;
  det.querySelector('.sim-add').onclick = () => adicionarComparacao({ banco: inp.banco, rotulo: `Financiamento ${inp.n}x`, montante: r.montante, custoRS: r.juros, cetAnual: r.cetAnual, prazo: (inp.carencia || 0) + inp.n, posseImediata: true });
}
function renderEmprestimo(r, inp) {
  document.getElementById('empCards').innerHTML =
    ((r.custos > 0) ? card('Valor líquido recebido', fmtMoneyDec(r.liquido), 'green', true, 'title="Valor contratado − custos do contrato (IOF, taxas, seguro). É a base do CET."') : '') +
    card('Montante total pago', fmtMoneyDec(r.montante), 'amber', true) +
    card('Total de juros', `${fmtMoneyDec(r.juros)}${r.pctJuros != null ? ' · ' + fmtPct2(r.pctJuros) : ''}`, 'red') +
    card('CET mensal', cetTxt(r.cetMensal), 'red') +
    card('CET anual', cetTxt(r.cetAnual), 'red');
  const b = bandasVeredito('emprestimo', inp.garantia, inp.ref);
  const vd = r.semJuros ? { classe: 'sim-v-bom', texto: '✅ Sem juros embutidos; as parcelas somam ≤ o valor contratado.' } : vereditoCET(r.cetAnual, b.bom, b.ok, b.ctx);
  const obs = inp.garantia
    ? `<div class="sim-bloco"><b>Garantia:</b> ${esc(inp.tipoGarantia || 'informada')}. Empréstimo com garantia normalmente tem CET menor.${r.cetAnual != null && r.cetAnual * 100 > b.ok ? ' <b>Atenção:</b> mesmo com garantia, a CET está alta; dá para negociar.' : ''}</div>`
    : `<div class="sim-bloco"><b>Sem garantia:</b> as taxas costumam ser bem mais altas. Oferecer uma garantia (imóvel/veículo) tende a reduzir bastante o CET.</div>`;
  const det = document.getElementById('empDetalhe');
  det.innerHTML = blocoFluxoSim(inp, r, inp.valor, 'contratado') + obs + vHTML(vd) + `<button class="btn btn-ghost small sim-add">+ Adicionar à comparação</button>`;
  det.querySelector('.sim-add').onclick = () => adicionarComparacao({ banco: inp.banco, rotulo: `Empréstimo ${inp.n}x`, montante: r.montante, custoRS: r.juros, cetAnual: r.cetAnual, prazo: (inp.carencia || 0) + inp.n, posseImediata: true });
}
function renderConsorcio(r, inp) {
  document.getElementById('conCards').innerHTML =
    card('Montante total a pagar', fmtMoneyDec(r.montante), 'amber', true) +
    card('Custo total (taxas)', `${fmtMoneyDec(r.custoTotal)}${r.pctCusto != null ? ' · ' + fmtPct2(r.pctCusto) + ' da carta' : ''}`, 'red') +
    ((r.custos > 0) ? card('Carta líquida recebida', fmtMoneyDec(r.liquido), 'green', true, 'title="Carta de crédito − custos iniciais pagos à parte. É a base do CET."') : '') +
    card('CET equiv. (mês)', cetTxt(r.cetMensal), 'red') +
    card('CET equiv. (ano)', cetTxt(r.cetAnual), 'red') +
    card('Lance médio sugerido', `${fmtPct2(r.lanceMediaPct / 100)} · ${fmtMoneyDec(r.lanceTotalRS)}`, '');
  const comp = `<div class="sim-bloco"><b>Componentes do total:</b> Carta ${fmtMoneyDec(inp.carta)} + Tx adm ${fmtMoneyDec(r.txadmRS)} + Fundo ${fmtMoneyDec(r.fundoRS)}${inp.seguro ? ' + Seguro ' + fmtMoneyDec(r.seguroRS) : ''}${r.carenciaPago > 0 ? ' + Carência ' + fmtMoneyDec(r.carenciaPago) : ''} ≈ ${fmtMoneyDec(inp.carta + r.txadmRS + r.fundoRS + r.seguroRS + r.carenciaPago)}</div>`;
  const lance = `<div class="sim-bloco"><b>Lance:</b> embutido ${fmtMoneyDec(r.embutidoRS)} (${fmtPct2(inp.embutido / 100)} da carta) · do seu bolso (lance − embutido): <b>${fmtMoneyDec(r.recursoProprio)}</b></div>`;
  const contempl = `<div class="sim-bloco"><b>Contemplação (estimativa):</b> por <b>lance</b>; ofertando ~${fmtPct2(r.lanceMediaPct / 100)} (média dos 3 vencedores) você tem boa chance nas próximas 1–2 assembleias. Por <b>sorteio</b>; sem saber o tamanho do grupo, espere algo em torno da metade do prazo (~mês ${Math.round(inp.n / 2)}). <i>É estimativa, não garantia.</i></div>`;
  const al = [];
  if (!r.componentesFecham) al.push('Os componentes (carta + taxas) não fecham com a soma das parcelas; confira os valores informados.');
  if (r.seguroNegativo) al.push('Taxa de adm + fundo já passam do custo total; o seguro ficou negativo (tratado como zero).');
  if (r.embutidoExcede) al.push('O lance embutido é maior que o lance sugerido; recurso próprio considerado zero.');
  const b = bandasVeredito('consorcio', false, inp.ref);
  const vd = vereditoCET(r.cetAnual, b.bom, b.ok, b.ctx);
  const det = document.getElementById('conDetalhe');
  det.innerHTML = comp + lance + contempl + blocoFluxoSim(inp, r, inp.carta, 'carta') + al.map(a => `<p class="sim-alerta">⚠ ${esc(a)}</p>`).join('') +
    vHTML(vd) + `<p class="sim-alerta">Premissa do CET: assume contemplação imediata (via lance) · é o <b>piso</b> do custo. Esperar o sorteio piora o custo no tempo. Consórcio só compensa se você não tiver pressa pelo bem.</p>` +
    `<button class="btn btn-ghost small sim-add">+ Adicionar à comparação</button>`;
  det.querySelector('.sim-add').onclick = () => adicionarComparacao({ banco: inp.banco, rotulo: `Consórcio ${inp.n}x`, montante: r.montante, custoRS: r.custoTotal, cetAnual: r.cetAnual, prazo: (inp.carencia || 0) + inp.n, posseImediata: false });
}

// ---- Comparador (lista INDIVIDUAL por usuário, persistida no servidor: /api/simulacoes) ----
const simComparacoes = [];
const nomeComp = (c) => c.banco ? c.banco : c.rotulo; // nome amigável: o banco, ou o produto se não informado
const dataSim = (ts) => ts ? new Date(ts).toLocaleDateString('pt-BR') : '—'; // dia em que a simulação foi salva
async function carregarComparacoes() {
  try {
    const r = await fetch('/api/simulacoes', { cache: 'no-store' });
    if (!r.ok) return;
    const d = await r.json();
    if (Array.isArray(d)) { simComparacoes.length = 0; simComparacoes.push(...d); renderComparacao(); }
  } catch (e) { /* offline: mantém o que já está na tela */ }
}
async function adicionarComparacao(item) {
  try {
    const r = await fetch('/api/simulacoes', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(item) });
    if (!r.ok) throw 0;
    const { item: salvo } = await r.json();
    simComparacoes.push(salvo); renderComparacao(); toast('Adicionado à comparação (salvo).', 'ok');
  } catch (e) { toast('Não consegui salvar a comparação. Tente de novo.', 'erro'); }
}
async function removerComparacao(id) {
  try {
    const r = await fetch('/api/simulacoes/' + encodeURIComponent(id), { method: 'DELETE' });
    if (!r.ok) throw 0;
    const i = simComparacoes.findIndex(c => c.id === id);
    if (i >= 0) { simComparacoes.splice(i, 1); renderComparacao(); }
  } catch (e) { toast('Não consegui remover. Tente de novo.', 'erro'); }
}
async function limparComparacoes() {
  if (!simComparacoes.length) return;
  if (!(await confirmar('Limpar todas as suas comparações salvas? Só afeta as suas; as de outros usuários não mudam.', { perigo: true, okTexto: 'Limpar' }))) return;
  try {
    const r = await fetch('/api/simulacoes', { method: 'DELETE' });
    if (!r.ok) throw 0;
    simComparacoes.length = 0; renderComparacao();
  } catch (e) { toast('Não consegui limpar. Tente de novo.', 'erro'); }
}
function renderComparacao() {
  const wrap = document.getElementById('simComparador');
  if (!wrap) return;
  if (!simComparacoes.length) { wrap.hidden = true; return; }
  wrap.hidden = false;
  // ordena pelo melhor negócio (menor CET no topo); sem CET vai pro fim, mantendo a ordem de entrada
  const ordenadas = simComparacoes.map((c, i) => ({ c, i })).sort((a, b) => {
    const ca = a.c.cetAnual, cb = b.c.cetAnual;
    if (ca == null && cb == null) return a.i - b.i;
    if (ca == null) return 1;
    if (cb == null) return -1;
    return ca - cb;
  }).map(x => x.c);
  const comCet = ordenadas.filter(c => c.cetAnual != null);
  const minCet = comCet.length ? comCet[0].cetAnual : null;

  // ---- Veredito amigável (precisa de 2+ propostas com CET) ----
  const vd = document.getElementById('simCompVeredito');
  if (vd) {
    vd.hidden = false;
    if (comCet.length >= 2) {
      const venc = comCet[0], seg = comCet[1];
      const deltaPP = ((seg.cetAnual - venc.cetAnual) * 100).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      // só compara custo em R$ quando o prazo é igual (mesma base de comparação)
      const economia = (seg.custoRS != null && venc.custoRS != null && seg.prazo === venc.prazo && seg.custoRS > venc.custoRS)
        ? ` Sai <b>${fmtMoneyDec(seg.custoRS - venc.custoRS)}</b> mais barato em custo total que <b>${esc(nomeComp(seg))}</b>.` : '';
      vd.className = 'sim-veredito sim-v-bom';
      vd.innerHTML = `🏆 <b>${esc(nomeComp(venc))}</b> é o melhor negócio · CET de <b>${fmtPct2(venc.cetAnual)} a.a.</b>, ${deltaPP} p.p. abaixo do 2º colocado (${esc(nomeComp(seg))}).${economia}`;
    } else {
      vd.className = 'sim-veredito sim-v-neutro';
      vd.innerHTML = `💡 Adicione <b>2 ou mais</b> propostas (ex.: Itaú e Bradesco) para ver qual é o melhor negócio.`;
    }
  }

  wrap.querySelector('thead').innerHTML = '<tr><th>Banco</th><th>Produto</th><th>Montante total</th><th>Custo total (R$)</th><th>CET anual equiv.</th><th>Prazo</th><th>Posse do bem</th><th>Data</th><th aria-label="Remover"></th></tr>';
  wrap.querySelector('tbody').innerHTML = ordenadas.map(c => {
    const melhor = c.cetAnual != null && c.cetAnual === minCet;
    return `<tr${melhor ? ' class="sim-melhor"' : ''}>
      <td>${c.banco ? esc(c.banco) : '—'}${melhor ? ' <span class="sim-tag">melhor</span>' : ''}</td>
      <td>${esc(c.rotulo)}</td>
      <td>${fmtMoneyDec(c.montante)}</td>
      <td>${fmtMoneyDec(c.custoRS)}</td>
      <td>${c.cetAnual == null ? '—' : fmtPct2(c.cetAnual)}</td>
      <td>${c.prazo}x</td>
      <td>${c.posseImediata ? 'imediata' : 'na contemplação'}</td>
      <td>${dataSim(c.ts)}</td>
      <td><button class="sim-rm" data-rm="${esc(c.id)}" title="Remover esta proposta" aria-label="Remover esta proposta">✕</button></td>
    </tr>`;
  }).join('');
  wrap.querySelectorAll('.sim-rm').forEach(b => b.onclick = () => removerComparacao(b.dataset.rm));
  document.getElementById('simCompRessalva').textContent = 'Menor CET = melhor custo. Mas o consórcio só ganha de fato se você NÃO tiver pressa pelo bem (a posse vem só na contemplação). Precisando do bem já, o financiamento entrega na hora.';
}

// ---- Validação + cálculo a partir do formulário ----
function calcularSimulador(prod, form) {
  const v = (nome) => numBR(form.elements[nome] ? form.elements[nome].value : '');
  const banco = (form.elements['banco'] && form.elements['banco'].value || '').trim();
  const carencia = Math.max(0, Math.round(v('carencia') || 0)); // meses sem pagar parcela (opcional)
  if (prod === 'financiamento') {
    const valor = v('valor'), entrada = v('entrada') || 0, parcela = v('parcela'), n = Math.round(v('n'));
    if (!(valor > 0) || !(parcela > 0) || !(n > 0)) return toast('Preencha valor do bem, parcela e nº de parcelas (positivos).', 'erro');
    if (entrada < 0) return toast('Entrada inválida.', 'erro');
    if (entrada >= valor) return toast('A entrada não pode ser maior ou igual ao valor do bem (nada a financiar).', 'erro');
    const custos = v('custos') || 0, jurosCarencia = v('jurosCarencia') || 0;
    if (custos < 0 || jurosCarencia < 0) return toast('Custos e juros da carência não podem ser negativos.', 'erro');
    if (custos >= valor - entrada) return toast('Os custos do contrato não podem ser maiores ou iguais ao valor financiado.', 'erro');
    renderFinanciamento(calcFinanciamento({ valor, entrada, parcela, n, carencia, custos, jurosCarencia }), { banco, valor, entrada, parcela, n, carencia, custos, jurosCarencia, ref: v('ref') || 0 });
  } else if (prod === 'emprestimo') {
    const valor = v('valor'), parcela = v('parcela'), n = Math.round(v('n'));
    if (!(valor > 0) || !(parcela > 0) || !(n > 0)) return toast('Preencha valor, parcela e nº de parcelas (positivos).', 'erro');
    if (!form.elements['garantia'].value) return toast('Escolha se o empréstimo possui garantia.', 'erro');
    const garantia = form.elements['garantia'].value === 'sim';
    const custos = v('custos') || 0, jurosCarencia = v('jurosCarencia') || 0;
    if (custos < 0 || jurosCarencia < 0) return toast('Custos e juros da carência não podem ser negativos.', 'erro');
    if (custos >= valor) return toast('Os custos do contrato não podem ser maiores ou iguais ao valor contratado.', 'erro');
    renderEmprestimo(calcEmprestimo({ valor, parcela, n, garantia, carencia, custos, jurosCarencia }), { banco, valor, parcela, n, garantia, carencia, custos, jurosCarencia, tipoGarantia: (form.elements['tipoGarantia'].value || '').trim(), ref: v('ref') || 0 });
  } else {
    const carta = v('carta'), parcela = v('parcela'), n = Math.round(v('n'));
    if (!(carta > 0) || !(parcela > 0) || !(n > 0)) return toast('Preencha carta, parcela e nº de parcelas (positivos).', 'erro');
    if (!form.elements['seguro'].value) return toast('Escolha se a parcela tem seguro.', 'erro');
    const seguro = form.elements['seguro'].value === 'sim';
    const custos = v('custos') || 0, jurosCarencia = v('jurosCarencia') || 0;
    if (custos < 0 || jurosCarencia < 0) return toast('Custos e pagamento na carência não podem ser negativos.', 'erro');
    if (custos >= carta) return toast('Os custos iniciais não podem ser maiores ou iguais ao valor da carta.', 'erro');
    renderConsorcio(calcConsorcio({ carta, parcela, n, txadm: v('txadm') || 0, fundo: v('fundo') || 0, seguro, l1: v('l1') || 0, l2: v('l2') || 0, l3: v('l3') || 0, embutido: v('embutido') || 0, carencia, custos, jurosCarencia }),
      { banco, carta, parcela, n, txadm: v('txadm') || 0, fundo: v('fundo') || 0, seguro, l1: v('l1') || 0, l2: v('l2') || 0, l3: v('l3') || 0, embutido: v('embutido') || 0, carencia, custos, jurosCarencia, ref: v('ref') || 0 });
  }
}

// ---- Inicialização da aba (idempotente) ----
let _simInit = false;
function carregarSimulador() {
  if (_simInit) return;
  _simInit = true;
  document.querySelectorAll('#simSubtabs .subtab').forEach(b => b.onclick = () => {
    if (b.classList.contains('active')) return;
    document.querySelectorAll('#simSubtabs .subtab').forEach(x => x.classList.remove('active'));
    document.querySelectorAll('#simulador .subview').forEach(x => x.classList.remove('active'));
    b.classList.add('active');
    document.getElementById(b.dataset.sub).classList.add('active');
    const pt = document.getElementById('pageTitle'); if (pt) pt.textContent = 'Simulador › ' + b.textContent.trim();
  });
  document.querySelectorAll('#simulador .sim-form').forEach(f => f.addEventListener('submit', (e) => { e.preventDefault(); calcularSimulador(f.dataset.prod, f); }));
  const limpar = document.getElementById('simLimparComp');
  if (limpar) limpar.onclick = limparComparacoes;
  carregarComparacoes(); // traz as comparações salvas (compartilhadas) ao abrir a aba
}

/* ============================================================
   MANUTENÇÃO; eventos, dashboards e alertas
   Base bruta = lista de eventos importada do "Relatório de
   Manutenção". Todos os números/gráficos são recalculados aqui
   no cliente (os gráficos do Excel não são importáveis; são
   reproduzidos em Chart.js sobre os mesmos dados).
   ============================================================ */
let MANUTENCAO = [];
const SELECAO_MNT = new Set(); // ids de eventos selecionados (declarado aqui p/ evitar TDZ se renderMnt rodar cedo)
let editandoMntId = null;
let mntPagina = 1;
let subMntAtiva = 'mnt-eventos';
let ordemMnt = { campo: 'data', dir: -1 }; // tabela de eventos: padrão data (mais recente primeiro)

const CORES_MNT = ['#1b56ff', '#dc2626', '#16a34a', '#b45309', '#0369a1', '#7c3aed', '#0ea5e9', '#db2777', '#65a30d', '#475569'];
const ehCorretiva = (e) => String(e.tipo || '').toLowerCase().startsWith('corr');
const custoEv = (e) => Number(e.custo) || 0;

// "dd/mm/aaaa" → "aaaa-mm" (chave de mês, ordenável). '' se não der pra ler.
function mesDeMnt(data) {
  const m = String(data || '').match(/(\d{2})\/(\d{2})\/(\d{4})/);
  return m ? `${m[3]}-${m[2]}` : '';
}
function rotuloMes(chave) {
  const [a, m] = chave.split('-');
  const meses = ['jan', 'fev', 'mar', 'abr', 'mai', 'jun', 'jul', 'ago', 'set', 'out', 'nov', 'dez'];
  return `${meses[+m - 1] || m}/${a.slice(2)}`;
}
// "dd/mm/aaaa" → número aaaammdd (ordena por data completa). 0 se ilegível.
function dataOrdMnt(data) {
  const m = String(data || '').match(/(\d{2})\/(\d{2})\/(\d{4})/);
  return m ? Number(m[3] + m[2] + m[1]) : 0;
}
// Normaliza o modelo em "família" para agrupar variantes ("L-200 Cd Triton",
// "L200 Triton Spo Gl" → L200; "F4000 4x4", "F 4000 4x4 P", "F-4000" → F4000).
function familiaModelo(modelo) {
  const bruto = String(modelo || '').trim();
  const n = bruto.toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (n.includes('L200')) return 'L200';
  if (n.includes('F4000')) return 'F4000';
  if (n.includes('HILUX')) return 'Hilux';
  if (n.includes('RANGER')) return 'Ranger';
  if (n.includes('SAVEIRO')) return 'Saveiro';
  if (n.includes('TORO')) return 'Toro';
  if (n.includes('DAILY')) return 'Daily';
  if (n.includes('S10')) return 'S10';
  if (n.includes('15190')) return '15.190';
  return bruto || '—';
}

// ----- Edição inline na tabela de eventos (mesmo estilo da aba Frota) -----
// Pílulas editáveis keyed por id do evento; reaproveitam o CSS e os menus
// (abrir/fechar/posicionar) já usados pelas pílulas da Frota.
const CONFIG_PILL_MNT = {
  tipo: {
    opcoes: [
      { valor: 'Corretiva', classe: 'p-vermelho' },
      { valor: 'Preventiva', classe: 'p-verde' },
    ],
    classe: (v) => (String(v).toLowerCase().startsWith('corr') ? 'p-vermelho' : 'p-verde'),
    rotulo: (v) => (String(v).toLowerCase().startsWith('corr') ? 'Corretiva' : 'Preventiva'),
  },
  centroCusto: {
    opcoesDinamicas: () => [...new Set([...MANUTENCAO.map(e => e.centroCusto).filter(Boolean), ...(CADASTROS.centrosCusto || [])])]
      .sort((a, b) => String(a).localeCompare(String(b), 'pt-BR')).map(x => ({ valor: x, classe: 'cc' })),
    classe: () => 'cc',
    rotulo: (s) => s || '—',
    busca: true,
    placeholder: 'Pesquisar centro de custo...',
  },
  // Motorista é por lançamento: trocar aqui altera somente o evento editado.
  // Opções = motoristas já em uso + os cadastrados (aba Cadastros › Motoristas). O botão "Adicionar
  // motorista" cadastra um novo na hora (entra na lista) e já o atribui a este evento.
  motorista: {
    opcoesDinamicas: () => [...new Set([...MANUTENCAO.map(e => e.motorista).filter(m => m && m !== '—'), ...(CADASTROS.motoristas || [])])]
      .sort((a, b) => String(a).localeCompare(String(b), 'pt-BR')).map(x => ({ valor: x, classe: 'cc' })),
    classe: () => 'cc',
    rotulo: (s) => (s && s !== '—') ? s : '—',
    busca: true,
    placeholder: 'Pesquisar motorista...',
    editavel: true,
    adicionar: true,
    placeholderEdit: 'Nome do novo motorista…',
  },
};
function pillSelectMnt(e, campo) {
  const cfg = CONFIG_PILL_MNT[campo];
  const valAtual = e[campo] || '';
  const lista = cfg.opcoesDinamicas ? cfg.opcoesDinamicas() : cfg.opcoes;
  const itens = lista.map(o =>
    `<button type="button" class="pill-item ${o.classe}" data-valor="${esc(o.valor)}">${esc(o.rotulo || o.valor)}</button>`
  ).join('');
  const busca = cfg.busca ? `<input type="text" class="pill-busca" placeholder="${esc(cfg.placeholder || 'Pesquisar...')}" />` : '';
  const editorVal = cfg.adicionar ? '' : ((valAtual && valAtual !== '—') ? valAtual : '');
  const editor = cfg.editavel ? `<div class="pill-add-wrap"><input type="text" class="pill-edit" placeholder="${esc(cfg.placeholderEdit || 'Digite e tecle Enter…')}" value="${esc(editorVal)}" />${cfg.adicionar ? '<button type="button" class="pill-add-mot">➕ Adicionar motorista</button>' : ''}</div>` : '';
  const largo = (cfg.busca || cfg.editavel) ? ' com-busca' : '';
  return `<div class="pill-select" data-id="${esc(e.id)}" data-placa="${esc(e.placa)}" data-campo="${campo}">
      <button type="button" class="pill-trigger ${cfg.classe(valAtual)}" title="Clique para alterar">
        <span>${esc(cfg.rotulo(valAtual))}</span>${CHEVRON}
      </button>
      <div class="pill-menu${largo}" hidden>${busca}<div class="pill-itens">${itens}</div>${editor}</div>
    </div>`;
}
// "Adicionar motorista" no popup: cadastra o nome na lista de Motoristas (aba Cadastros) e já o
// atribui a este evento. Se já existir no cadastro (409), segue e só atribui.
// USO: await adicionarMotoristaMnt('MNT123', 'João Silva') → cadastra o nome e altera só MNT123.
async function adicionarMotoristaMnt(id, nome) {
  nome = (nome || '').trim();
  if (!nome) { toast('Digite o nome do motorista.', 'erro'); return; }
  try {
    const r = await fetch('/api/cadastros/motoristas', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ nome }),
    });
    const j = await r.json().catch(() => ({}));
    if (r.ok && Array.isArray(j.lista)) CADASTROS.motoristas = j.lista; // já existia (409) → mantém a lista atual
  } catch (e) { /* offline: ainda assim tenta atribuir abaixo */ }
  await alterarCampoMnt(id, 'motorista', nome);
}
// Salva alteração inline de um evento (tipo/centroCusto/custo/motorista) — PUT por id, com desfazer.
// USO: await alterarCampoMnt('MNT123', 'motorista', 'Maria Silva') → altera só MNT123;
// "Desfazer" restaura o motorista anterior desse lançamento, inclusive quando estava vazio.
async function alterarCampoMnt(id, campo, valor, comDesfazer = true) {
  const e = MANUTENCAO.find(x => x.id === id);
  if (!e) return;
  if (campo === 'custo') valor = Number(valor) || 0;
  if (e[campo] === valor) return;
  const anterior = e[campo];
  const atualizado = Object.assign({}, e, { [campo]: valor });
  const r = await fetch('/api/manutencao/' + encodeURIComponent(id), {
    method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(atualizado),
  });
  if (!r.ok) { toast('Erro ao alterar.', 'erro'); return; }
  Object.assign(e, atualizado);
  if (campo === 'centroCusto') await garantirCadastrado('centrosCusto', valor);
  popularFiltrosMnt();
  renderManutencao();
  const desfazer = comDesfazer ? { texto: 'Desfazer', fn: () => alterarCampoMnt(id, campo, anterior, false) } : null;
  toast(`Evento de ${e.placa} atualizado.`, 'ok', desfazer);
}

async function carregarManutencao() {
  try {
    const r = await fetch('/api/manutencao', { cache: 'no-store' });
    if (r.status === 401) { window.location = '/login'; return; }
    if (r.status === 403) { MANUTENCAO = []; popularFiltrosMnt(); renderManutencao(); toast('Você não tem acesso a esta área.', 'erro'); return; }
    const d = r.ok ? await r.json() : [];
    MANUTENCAO = Array.isArray(d) ? d : [];
  } catch (e) {
    MANUTENCAO = [];
    toast('Erro ao carregar a manutenção. Verifique a conexão.', 'erro');
  }
  popularFiltrosMnt();
  renderManutencao();
}

// Datalists do modal + opções dos filtros multi-seleção.
function popularFiltrosMnt() {
  const unicos = (campo) => [...new Set(MANUTENCAO.map(e => e[campo]).filter(x => x !== '' && x != null))]
    .sort((a, b) => String(a).localeCompare(String(b), 'pt-BR'));
  if (MSEL.fmntPlaca) MSEL.fmntPlaca.setOpcoes(unicos('placa'));
  if (MSEL.fmntCentro) MSEL.fmntCentro.setOpcoes([...new Set([...unicos('centroCusto'), ...(CADASTROS.centrosCusto || [])])].sort((a, b) => String(a).localeCompare(String(b), 'pt-BR')));
  if (MSEL.fmntTipo) MSEL.fmntTipo.setOpcoes(unicos('tipo'));
  if (MSEL.fmntMontadora) MSEL.fmntMontadora.setOpcoes(unicos('montadora'));
  // Período: meses presentes nos dados, do mais recente p/ o mais antigo (rótulo "abr/25").
  if (MSEL.fmntPeriodo) {
    const meses = [...new Set(MANUTENCAO.map(e => mesDeMnt(e.data)).filter(Boolean))].sort().reverse();
    MSEL.fmntPeriodo.setOpcoes(meses.map(rotuloMes));
  }
  const dPlacas = document.getElementById('listaPlacasMnt');
  if (dPlacas) dPlacas.innerHTML = [...new Set([...unicos('placa'), ...VEICULOS.map(v => v.placa)])].sort().map(x => `<option value="${esc(x)}">`).join('');
  const dMont = document.getElementById('listaMontadorasMnt');
  if (dMont) dMont.innerHTML = unicos('montadora').map(x => `<option value="${esc(x)}">`).join('');
  // Modelo/motorista/item: sugerem o que já existe (frota, cadastros e eventos anteriores).
  const dModelos = document.getElementById('listaModelosMnt');
  if (dModelos) dModelos.innerHTML = [...new Set([...unicos('modelo'), ...VEICULOS.map(v => v.modelo).filter(Boolean)])]
    .sort((a, b) => String(a).localeCompare(String(b), 'pt-BR')).map(x => `<option value="${esc(x)}">`).join('');
  const dMot = document.getElementById('listaMotoristasMnt');
  if (dMot) dMot.innerHTML = [...new Set([...unicos('motorista'), ...(CADASTROS.motoristas || []), ...ABASTECIMENTO.map(t => t.motorista)])]
    .filter(m => m && m !== '—')
    .sort((a, b) => String(a).localeCompare(String(b), 'pt-BR')).map(x => `<option value="${esc(x)}">`).join('');
  const dItens = document.getElementById('listaItensMnt');
  if (dItens) dItens.innerHTML = unicos('item').map(x => `<option value="${esc(x)}">`).join('');
}

// Aplica busca textual + filtros multi-seleção.
function mntFiltrados() {
  const q = (document.getElementById('buscaMnt').value || '').trim().toLowerCase();
  const fPl = getSel('fmntPlaca'), fCe = getSel('fmntCentro'), fTi = getSel('fmntTipo'), fMo = getSel('fmntMontadora'), fPe = getSel('fmntPeriodo');
  return MANUTENCAO.filter(e => {
    if (fPl.length && !fPl.includes(e.placa)) return false;
    if (fCe.length && !fCe.includes(e.centroCusto)) return false;
    if (fTi.length && !fTi.includes(e.tipo)) return false;
    if (fMo.length && !fMo.includes(e.montadora)) return false;
    if (fPe.length && !fPe.includes(rotuloMes(mesDeMnt(e.data)))) return false;
    if (q) {
      const alvo = `${e.placa} ${e.item} ${e.modelo} ${e.montadora} ${e.motorista} ${e.centroCusto} ${e.fornecedor || ''}`.toLowerCase();
      if (!alvo.includes(q)) return false;
    }
    return true;
  });
}

function renderManutencao() {
  renderCardsMnt();
  if (subMntAtiva === 'mnt-eventos') renderEventosMnt();
  else if (subMntAtiva === 'mnt-dashboards') renderDashboardsMnt();
  else if (subMntAtiva === 'mnt-alertas') renderAlertasMnt();
  else if (subMntAtiva === 'mnt-notas') renderOficina();
  else if (subMntAtiva === 'mnt-odometro') renderOdometro();
  else if (subMntAtiva === 'mnt-relatorios') renderRelatoriosMnt();
}

// ----- Agregações -----
function agruparPorVeiculo(lista) {
  const map = new Map();
  for (const e of lista) {
    let v = map.get(e.placa);
    if (!v) { v = { placa: e.placa, modelo: e.modelo, montadora: e.montadora, ano: e.ano, motorista: e.motorista, centroCusto: e.centroCusto, total: 0, itens: 0, corretiva: 0, preventiva: 0, qtdCorretiva: 0 }; map.set(e.placa, v); }
    const c = custoEv(e);
    v.total += c; v.itens++;
    if (ehCorretiva(e)) { v.corretiva += c; v.qtdCorretiva++; } else { v.preventiva += c; }
    if (!v.motorista && e.motorista) v.motorista = e.motorista;
  }
  return [...map.values()];
}

// ----- Cards de resumo (sempre visíveis no topo da aba) -----
function renderCardsMnt() {
  const lista = mntFiltrados();
  const total = lista.reduce((s, e) => s + custoEv(e), 0);
  const placas = new Set(lista.map(e => e.placa));
  const nVeic = placas.size;
  const corretiva = lista.filter(ehCorretiva).reduce((s, e) => s + custoEv(e), 0);
  const pctCor = total ? Math.round((corretiva / total) * 100) : 0;
  // Padrão .v2-kpi: o link de navegação ("Ver eventos →") vira a nota do cartão.
  const stat = (valor, rotulo, linkTxt, linkAttr) => kpiV2(rotulo, valor, {
    notaHtml: `<a class="ndj-link" ${linkAttr}>${esc(linkTxt)} <span aria-hidden="true">→</span></a>`,
  });
  document.getElementById('cardsManutencao').innerHTML =
    stat(nVeic, 'Veículos', 'Ver frota', 'href="/painel/frota"') +
    stat(lista.length, 'Eventos', 'Ver eventos', 'href="#" data-mnt-sub="mnt-eventos"') +
    stat(fmtMoneyDec(total), 'Custo total', 'Ver custos', 'href="#" data-mnt-sub="mnt-dashboards"') +
    stat(fmtMoneyDec(nVeic ? total / nVeic : 0), 'Custo médio/veículo', 'Ver análise', 'href="#" data-mnt-sub="mnt-dashboards"') +
    stat(pctCor + '%', '% corretiva', 'Ver desempenho', 'href="#" data-mnt-sub="mnt-alertas"');
  document.getElementById('cardsManutencao').querySelectorAll('[data-mnt-sub]').forEach((a) => {
    a.onclick = (e) => { e.preventDefault(); const b = document.querySelector(`#manutencaoSubtabs .subtab[data-sub="${a.dataset.mntSub}"]`); if (b) b.click(); };
  });
}

// ----- Sub-aba Eventos: tabela paginada, editável inline e ordenável -----
// Colunas da tabela de eventos (dirigem cabeçalho clicável + ordenação).
const COLS_MNT = [
  { campo: 'data', titulo: 'Data', ord: e => dataOrdMnt(e.data), num: true },
  { campo: 'placa', titulo: 'Placa' },
  { campo: 'tipo', titulo: 'Tipo' },
  { campo: 'item', titulo: 'Item' },
  { campo: 'fornecedor', titulo: 'Fornecedor / oficina' },
  { campo: 'custo', titulo: 'Custo', classe: 'num', ord: e => custoEv(e), num: true },
  { campo: 'centroCusto', titulo: 'Centro de custo' },
  { campo: 'motorista', titulo: 'Motorista' },
];
let mntTipoTab = 'all'; // aba sobre a tabela: Todos | Corretiva | Preventiva
// TODO(padrão v2): quando os eventos ganharem um campo de STATUS (Aberto/Em andamento/
// Concluído/Cancelado), as abas passam a refletir status — hoje o dado real é o TIPO.
function renderTabsMnt(base) {
  const host = document.getElementById('mntTabs');
  if (!host) return;
  const cont = (f) => base.filter(f).length;
  const abas = [
    ['all', 'Todos', base.length],
    ['Corretiva', 'Corretiva', cont(ehCorretiva)],
    ['Preventiva', 'Preventiva', cont((e) => !ehCorretiva(e))],
  ];
  host.innerHTML = abas.map(([val, rot, n]) =>
    `<button type="button" class="ndj-tab${mntTipoTab === val ? ' on' : ''}" data-tab-mnt="${val}">${rot} <span class="ndj-tab-chip">${n}</span></button>`).join('');
  host.querySelectorAll('[data-tab-mnt]').forEach((b) => {
    b.onclick = () => { mntTipoTab = b.dataset.tabMnt; mntPagina = 1; renderEventosMnt(); };
  });
}
function renderEventosMnt() {
  // Tira da seleção ids que não existem mais (após excluir/importar).
  if (SELECAO_MNT.size) { const vivos = new Set(MANUTENCAO.map(e => e.id)); for (const id of [...SELECAO_MNT]) if (!vivos.has(id)) SELECAO_MNT.delete(id); }
  const col = COLS_MNT.find(c => c.campo === ordemMnt.campo) || COLS_MNT[0];
  const baseTabs = mntFiltrados();
  renderTabsMnt(baseTabs);
  const lista = (mntTipoTab === 'all' ? baseTabs : baseTabs.filter((e) => (mntTipoTab === 'Corretiva') === ehCorretiva(e))).slice().sort((a, b) => {
    let x = col.ord ? col.ord(a) : a[col.campo];
    let y = col.ord ? col.ord(b) : b[col.campo];
    if (col.num) { x = Number(x) || 0; y = Number(y) || 0; return (x - y) * ordemMnt.dir; }
    return String(x ?? '').localeCompare(String(y ?? ''), 'pt-BR') * ordemMnt.dir;
  });
  const vazio = document.getElementById('mntVazio');
  const corpo = document.getElementById('corpoMnt');
  const thead = document.getElementById('cabecalhoMnt');
  thead.innerHTML = '<th class="col-acoes">Ações</th>' + COLS_MNT.map(c =>
    `<th data-campo="${c.campo}" class="${c.classe || ''}" title="Clique para ordenar">${c.titulo}${iconeOrd(ordemMnt.campo === c.campo, ordemMnt.dir)}</th>`
  ).join('');
  thead.querySelectorAll('th[data-campo]').forEach(th => {
    th.onclick = () => {
      const campo = th.dataset.campo;
      if (ordemMnt.campo === campo) ordemMnt.dir *= -1;
      else { ordemMnt.campo = campo; ordemMnt.dir = campo === 'data' || campo === 'custo' ? -1 : 1; }
      renderEventosMnt();
    };
  });
  // resumo
  const totFiltro = lista.reduce((s, e) => s + custoEv(e), 0);
  document.getElementById('resumoMnt').innerHTML = `${lista.length} evento(s) · soma: <b>${fmtMoneyDec(totFiltro)}</b>`;
  if (!lista.length) { corpo.innerHTML = ''; vazio.hidden = false; document.getElementById('mntPagInfo').textContent = ''; return; }
  vazio.hidden = true;
  // paginação
  const sel = document.getElementById('mntPorPagina').value;
  const porPag = sel === 'all' ? lista.length : Number(sel);
  const totalPaginas = Math.max(1, Math.ceil(lista.length / porPag));
  if (mntPagina > totalPaginas) mntPagina = totalPaginas;
  const ini = (mntPagina - 1) * porPag;
  const pag = lista.slice(ini, ini + porPag);
  corpo.innerHTML = pag.map(e => {
    const item = e.item || '—';
    const selOn = SELECAO_MNT.has(e.id) ? ' sel-on' : '';
    return `<tr data-id="${esc(e.id)}" class="${selOn}">
      <td class="acoes">
        <button class="edit edit-mnt" data-id="${esc(e.id)}" title="Editar" aria-label="Editar">${ICONE_LAPIS}</button>
        <button class="del del-mnt" data-id="${esc(e.id)}" title="Excluir" aria-label="Excluir">${ICONE_LIXEIRA}</button>
      </td>
      <td>${esc(fmtData(e.data) || '—')}</td>
      <td><button class="placa-btn placa-chip" data-placa="${esc(e.placa)}" title="Ver detalhes de manutenção deste veículo">${esc(e.placa)}</button></td>
      <td>${pillSelectMnt(e, 'tipo')}</td>
      <td class="cel-trunc"><span class="mnt-item editavel-item" data-id="${esc(e.id)}" title="Clique para editar · ${esc(item)}" role="button" tabindex="0">${esc(item)}</span></td>
      <td>${esc(e.fornecedor || '—')}</td>
      <td class="num">${fmtMoneyDec(custoEv(e))}</td>
      <td>${pillSelectMnt(e, 'centroCusto')}</td>
      <td>${pillSelectMnt(e, 'motorista')}</td>
    </tr>`;
  }).join('');
  rotularCelulasMobile('cabecalhoMnt', 'corpoMnt'); // celular: tabela vira cartões
  renderNavPaginacao('mnt', { de: lista.length ? ini + 1 : 0, ate: Math.min(ini + porPag, lista.length), total: lista.length, totalPaginas, pagina: mntPagina });

  // ----- Edição inline (pílulas Tipo/Centro/Motorista + campo de custo) -----
  corpo.querySelectorAll('.pill-trigger').forEach(t => t.onclick = (ev) => {
    ev.stopPropagation();
    const sel = t.closest('.pill-select');
    const jaAberto = sel.classList.contains('aberto');
    fecharPillMenus();
    if (!jaAberto) abrirPillMenu(sel);
  });
  corpo.querySelectorAll('.pill-item').forEach(it => it.onclick = (ev) => {
    ev.stopPropagation();
    const sel = donoPillMenu(it);
    if (!sel) return;
    fecharPillMenus();
    alterarCampoMnt(sel.dataset.id, sel.dataset.campo, it.dataset.valor);
  });
  corpo.querySelectorAll('.pill-busca').forEach(inp => {
    inp.onclick = (ev) => ev.stopPropagation();
    inp.oninput = () => {
      const q = inp.value.trim().toLowerCase();
      inp.closest('.pill-menu').querySelectorAll('.pill-item').forEach(it => {
        it.hidden = q && !it.textContent.toLowerCase().includes(q);
      });
    };
  });
  // Motorista: digitar um nome novo + Enter (ou o botão "Adicionar motorista") cadastra na lista de
  // Motoristas e já atribui somente ao lançamento editado.
  corpo.querySelectorAll('.pill-edit').forEach(inp => {
    inp.onclick = (ev) => ev.stopPropagation();
    inp.onkeydown = (ev) => {
      if (ev.key === 'Enter') {
        ev.preventDefault();
        const sel = donoPillMenu(inp);
        if (!sel) return;
        const nome = inp.value.trim();
        fecharPillMenus();
        adicionarMotoristaMnt(sel.dataset.id, nome);
      }
    };
  });
  corpo.querySelectorAll('.pill-add-mot').forEach(btn => {
    btn.onclick = (ev) => {
      ev.stopPropagation();
      const sel = donoPillMenu(btn);
      if (!sel) return;
      const menu = btn.closest('.pill-menu');
      const inp = (menu || sel).querySelector('.pill-edit');
      const nome = inp ? inp.value.trim() : '';
      fecharPillMenus();
      adicionarMotoristaMnt(sel.dataset.id, nome);
    };
  });
  // Seleção agora é por clique na linha (ver DELEGAÇÃO em #manutencao).
  SEL_TODOS_MNT.sincronizar(lista); // alimenta o cache de chaves com a lista filtrada recém-calculada
  atualizarBarraSelMnt();
}

// ----- Barra de seleção da Manutenção (exportar selecionados / limpar) -----
// (SELECAO_MNT é declarado junto do estado de MANUTENCAO, lá em cima.)
function atualizarBarraSelMnt() {
  const bar = document.getElementById('selBarMnt');
  if (!bar) return;
  SEL_TODOS_MNT.sincronizar(); // antes do return de "nada selecionado": o (N) do rótulo tem de seguir certo
  if (!SELECAO_MNT.size) { bar.hidden = true; return; }
  const sel = MANUTENCAO.filter(e => SELECAO_MNT.has(e.id));
  const total = sel.reduce((s, e) => s + custoEv(e), 0);
  document.getElementById('selBarMntInfo').innerHTML =
    `<span class="sb-item"><b>${sel.length}</b> selecionado(s)</span>` +
    `<span class="sb-item">Soma: <b>${fmtMoneyDec(total)}</b></span>`;
  bar.hidden = false;
}

// ----- Detalhes de manutenção por veículo (clique na placa, como na Frota) -----
function abrirMntVeiculo(placa) {
  const p = (placa || '').trim();
  if (!p) return;
  const chave = p.toUpperCase();
  const eventos = MANUTENCAO.filter(e => (e.placa || '').trim().toUpperCase() === chave)
    .slice().sort((a, b) => dataOrdMnt(b.data) - dataOrdMnt(a.data));
  const v = VEICULOS.find(x => (x.placa || '').toUpperCase() === chave);
  const total = eventos.reduce((s, e) => s + custoEv(e), 0);
  const corretiva = eventos.filter(ehCorretiva).reduce((s, e) => s + custoEv(e), 0);
  const preventiva = total - corretiva;
  const pctCor = total ? Math.round((corretiva / total) * 100) : 0;
  document.getElementById('mntVeiculoTitulo').textContent = `Manutenção · ${p}`;
  const dados = v
    ? `<div class="mntv-veic">${[v.modelo, v.versao].filter(Boolean).map(esc).join(' ') || '—'}${v.centroCusto ? ` · <span class="mntv-cc">${esc(v.centroCusto)}</span>` : ''}</div>`
    : `<div class="mntv-veic mntv-fora">Placa não está na Frota atual (ou foi vendida); exibindo só o histórico de manutenção.</div>`;
  const stat = (rot, val, cls = '') => `<div class="mntv-stat ${cls}"><span class="mntv-stat-n">${val}</span><span class="mntv-stat-l">${rot}</span></div>`;
  const stats = `<div class="mntv-stats">
    ${stat('eventos', eventos.length)}
    ${stat('custo total', fmtMoneyDec(total), 'red')}
    ${stat('corretiva', fmtMoneyDec(corretiva), 'amber')}
    ${stat('preventiva', fmtMoneyDec(preventiva), 'green')}
    ${stat('% corretiva', pctCor + '%')}
  </div>`;
  const lista = eventos.length
    ? `<table class="mntv-tabela">
        <thead><tr><th>Data</th><th>Tipo</th><th>Item</th><th class="num">Custo</th></tr></thead>
        <tbody>${eventos.map(e => `<tr>
          <td>${esc(fmtData(e.data) || '—')}</td>
          <td><span class="mntv-tipo ${ehCorretiva(e) ? 'cor' : 'prev'}">${ehCorretiva(e) ? 'Corretiva' : 'Preventiva'}</span></td>
          <td title="${esc(e.item || '')}">${esc(e.item || '—')}</td>
          <td class="num">${fmtMoneyDec(custoEv(e))}</td>
        </tr>`).join('')}</tbody>
      </table>`
    : `<p class="vazio" style="margin:18px 4px;">Nenhum evento de manutenção registrado para esta placa.</p>`;
  // Ponte com a sub-aba Notas fiscais: mostra as NFs desta placa junto dos eventos.
  const notas = OFICINA.filter(o => (o.placa || '').trim().toUpperCase() === chave)
    .slice().sort((a, b) => String(b.data || '').localeCompare(String(a.data || '')));
  const notasHtml = notas.length
    ? `<h4 class="mntv-sec">Notas fiscais (${notas.length})</h4>
      <table class="mntv-tabela">
        <thead><tr><th>Data</th><th>Nº NF</th><th>Fornecedor</th><th class="num">Valor</th><th>NF</th></tr></thead>
        <tbody>${notas.map(o => `<tr>
          <td>${esc(oficDataBR(o.data) || '—')}</td>
          <td>${esc(o.numeroNF || '—')}</td>
          <td title="${esc(o.descricao || '')}">${esc(o.fornecedor || '—')}</td>
          <td class="num">${fmtMoneyDec(o.valor)}</td>
          <td>${o.anexo && o.anexo.id ? `<a class="ofic-anexo" href="${esc(urlMidia(o.anexo))}" target="_blank" rel="noopener" title="Abrir a NF (${esc(o.anexo.nome || 'arquivo')})">📎</a>` : '—'}</td>
        </tr>`).join('')}</tbody>
      </table>`
    : '';
  document.getElementById('mntVeiculoCorpo').innerHTML = dados + stats + lista + notasHtml;
  document.getElementById('mntVeiculoModal').hidden = false;
}
function fecharMntVeiculo() { document.getElementById('mntVeiculoModal').hidden = true; }
document.getElementById('fecharMntVeiculo').onclick = fecharMntVeiculo;
fecharAoClicarNoFundo('mntVeiculoModal', fecharMntVeiculo);
// Clique na placa, em qualquer sub-aba da Manutenção, abre os detalhes do veículo. Na sub-aba
// Odômetro abre a linha do tempo do odômetro, que é o assunto dali.
document.getElementById('manutencao').addEventListener('click', (e) => {
  const pb = e.target.closest('.placa-btn');
  if (!pb) return;
  e.stopPropagation();
  if (pb.closest('#mnt-odometro')) abrirOdoVeiculo(pb.dataset.placa);
  else abrirMntVeiculo(pb.dataset.placa);
});

// ----- Detalhes de abastecimento por veículo (clique na placa) -----
function abrirAbtVeiculo(placa) {
  const p = (placa || '').trim();
  if (!p) return;
  const chave = p.toUpperCase();
  const transacoes = ABASTECIMENTO.filter(t => (t.placa || '').trim().toUpperCase() === chave)
    .slice().sort((a, b) => dataOrdAbt(b.dataHora) - dataOrdAbt(a.dataHora));
  const v = VEICULOS.find(x => (x.placa || '').toUpperCase() === chave);
  const totGasto = transacoes.reduce((s, t) => s + numAbt(t.valor), 0);
  const totLitros = transacoes.reduce((s, t) => s + numAbt(t.litros), 0);
  const kmLs = transacoes.map(t => numAbt(t.kmL)).filter(k => k > 0);
  const kmLsSorted = kmLs.slice().sort((a, b) => a - b);
  const mid = Math.floor(kmLsSorted.length / 2);
  const kmLMed = kmLs.length ? (kmLsSorted.length % 2 ? kmLsSorted[mid] : (kmLsSorted[mid - 1] + kmLsSorted[mid]) / 2) : 0;
  document.getElementById('abtVeiculoTitulo').textContent = `Abastecimento · ${p}`;
  const dados = v
    ? `<div class="mntv-veic">${[v.modelo, v.versao].filter(Boolean).map(esc).join(' ') || '—'}${v.centroCusto ? ` · <span class="mntv-cc">${esc(v.centroCusto)}</span>` : ''}</div>`
    : `<div class="mntv-veic mntv-fora">Placa não está na Frota atual (ou foi vendida); exibindo só o histórico de abastecimento.</div>`;
  const stat = (rot, val, cls = '') => `<div class="mntv-stat ${cls}"><span class="mntv-stat-n">${val}</span><span class="mntv-stat-l">${rot}</span></div>`;
  const stats = `<div class="mntv-stats">
    ${stat('transações', transacoes.length)}
    ${stat('gasto total', fmtMoneyDec(totGasto), 'red')}
    ${stat('litros', fmtLitros(totLitros))}
    ${stat('km/L mediano', fmtKmL(kmLMed))}
  </div>`;
  const lista = transacoes.length
    ? `<table class="mntv-tabela">
        <thead><tr><th>Data/Hora</th><th>Motorista</th><th>Combustível</th><th class="num">Litros</th><th class="num">R$/L</th><th class="num">Km rod.</th><th class="num">Km/L</th><th class="num">Total R$</th></tr></thead>
        <tbody>${transacoes.map(t => `<tr>
          <td>${esc(t.dataHora || '—')}</td>
          <td>${esc(t.motorista || '—')}</td>
          <td>${esc(t.combustivel || '—')}</td>
          <td class="num">${fmtLitros(t.litros)}</td>
          <td class="num">${fmtRSL(t.precoLitro)}</td>
          <td class="num">${fmtKm(t.kmRod)}</td>
          <td class="num">${fmtKmL(t.kmL)}</td>
          <td class="num">${fmtMoneyDec(t.valor)}</td>
        </tr>`).join('')}</tbody>
      </table>`
    : `<p class="vazio" style="margin:18px 4px;">Nenhuma transação de abastecimento registrada para esta placa.</p>`;
  document.getElementById('abtVeiculoCorpo').innerHTML = dados + stats + lista;
  document.getElementById('abtVeiculoModal').hidden = false;
}
function fecharAbtVeiculo() { document.getElementById('abtVeiculoModal').hidden = true; }
document.getElementById('fecharAbtVeiculo').onclick = fecharAbtVeiculo;
fecharAoClicarNoFundo('abtVeiculoModal', fecharAbtVeiculo);

/* ============================================================
   ODÔMETRO (sub-aba da Manutenção; coleção `odometros`)
   Leituras do painel por veículo → linha do tempo. Km rodados, trechos, médias e
   alertas saem de OdometroCalc (frontend/odometro-calc.js), o MESMO cálculo que o
   servidor usa no Excel exportado. Permissão: a da área 'manutencao'.
   Importar SOMA leituras (a repetida é ignorada); o "Desfazer" da aba desfaz a
   importação inteira (UNDO_ROTAS no servidor).
   ============================================================ */
const odoEstado = { busca: '', ordem: 'km', card: '', modalPlaca: '', importacao: null, painel: null };
// Número de km em pt-BR ('—' quando não há número).
//   odoKm(46850) // => '46.850'  ·  odoKm(null) // => '—'
const odoKm = (n) => (n === null || n === undefined || !Number.isFinite(Number(n))) ? '—' : (Math.round(Number(n) * 10) / 10).toLocaleString('pt-BR');
// Placa comparável: sem traço/espaço, maiúscula (as leituras são gravadas assim).
const odoPlaca = (p) => String(p || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const odoIso = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const odoHoje = () => odoIso(new Date());
function odoVeiculo(placa) { return VEICULOS.find(v => odoPlaca(v.placa) === placa) || null; }
function odoPodeEditar() { return permissaoAtual('manutencao') === 'editar'; }

async function carregarOdometros() {
  try {
    const r = await fetch('/api/odometros', { cache: 'no-store' });
    if (r.status === 401) { window.location = '/login'; return; }
    if (r.ok) { const d = await r.json(); ODOMETROS = Array.isArray(d) ? d : []; }
  } catch (e) { /* mantém o que tem: falha depois de carregado não apaga a tela */ }
  if (subMntAtiva === 'mnt-odometro') renderOdometro();
  if (odoEstado.modalPlaca && !document.getElementById('odoVeiculoModal').hidden) abrirOdoVeiculo(odoEstado.modalPlaca);
}

// Período aplicado no filtro, em ISO inclusivo ('' = aberto daquele lado).
function odoPeriodo() {
  const per = MSEL.fodoPeriodo && MSEL.fodoPeriodo.getPeriodo();
  if (!per) return { de: '', ate: '', texto: '' };
  return { de: per.ini == null ? '' : odoIso(new Date(per.ini)), ate: per.fim == null ? '' : odoIso(new Date(per.fim)), texto: per.texto };
}
function odoFiltrando() { return !!(odoEstado.busca.trim() || getSel('fodoPlaca').length || getSel('fodoPeriodo').length); }

// Recorte da tela: filtros (placa, período) + busca. Os KPIs contam ESTE recorte; o
// cartão-filtro (conferir / sem leitura recente) só recorta a tabela.
function odoRecorte() {
  const { de, ate } = odoPeriodo();
  const selPlacas = getSel('fodoPlaca');
  const q = odoEstado.busca.trim().toLowerCase();
  let placas = [...new Set(ODOMETROS.map(l => l.placa))];
  if (selPlacas.length) placas = placas.filter(p => selPlacas.includes(p));
  if (q) placas = placas.filter(p => `${p} ${(odoVeiculo(p) || {}).modelo || ''}`.toLowerCase().includes(q));
  if (!placas.length) return OdometroCalc.resumoFrota([], {});
  return OdometroCalc.resumoFrota(ODOMETROS, { de, ate, hoje: odoHoje(), placas });
}

const ORDENS_ODO = {
  km: (a, b) => b.km - a.km || a.placa.localeCompare(b.placa),
  placa: (a, b) => a.placa.localeCompare(b.placa),
  media: (a, b) => (b.kmMes ?? -1) - (a.kmMes ?? -1) || a.placa.localeCompare(b.placa),
  antiga: (a, b) => a.ultima.data.localeCompare(b.ultima.data) || a.placa.localeCompare(b.placa),
};

function renderOdometro() {
  const corpo = document.getElementById('corpoOdo');
  if (!corpo) return;
  if (MSEL.fodoPlaca) MSEL.fodoPlaca.setOpcoes([...new Set(ODOMETROS.map(l => l.placa))].sort());
  const r = odoRecorte();
  const per = odoPeriodo();
  const filtrando = odoFiltrando();
  const DIAS = OdometroCalc.DIAS_SEM_LEITURA;
  // ----- KPIs (contam o recorte; o rótulo diz qual é) -----
  const kpis = document.getElementById('cardsOdo');
  if (kpis) {
    const n = r.veiculos.length;
    kpis.innerHTML =
      kpiV2(filtrando ? 'Veículos no recorte' : 'Veículos com leitura', n, { nota: `${r.leituras} ${plural(r.leituras, 'leitura', 'leituras')}` }) +
      kpiV2('Km rodados', odoKm(r.km), { nota: per.texto ? `no período ${per.texto}` : 'da 1ª à última leitura de cada veículo' }) +
      kpiV2('Média por veículo', r.kmDiaMedio === null ? '' : `${odoKm(Math.round(r.kmDiaMedio * OdometroCalc.DIAS_MES))} km/mês`,
        { nota: r.kmDiaMedio === null ? 'precisa de 2 leituras em dias diferentes' : `${odoKm(r.kmDiaMedio)} km por dia` }) +
      kpiV2('Leituras a conferir', r.alertas, { estado: r.alertas ? 'risco' : '', clicavel: true, ativo: odoEstado.card === 'conferir',
        attrs: { 'data-card': 'conferir' }, nota: 'odômetro voltou ou saltou' }) +
      kpiV2('Sem leitura recente', r.semLeituraRecente, { estado: r.semLeituraRecente ? 'aviso' : '', clicavel: true, ativo: odoEstado.card === 'semLeitura',
        attrs: { 'data-card': 'semLeitura' }, nota: `última há mais de ${DIAS} dias` });
  }
  // ----- Tabela (um veículo por linha) -----
  let lista = r.veiculos;
  if (odoEstado.card === 'conferir') lista = lista.filter(v => v.alertas);
  if (odoEstado.card === 'semLeitura') lista = lista.filter(v => v.semLeituraRecente);
  lista = lista.slice().sort(ORDENS_ODO[odoEstado.ordem] || ORDENS_ODO.km);
  const situacao = (v) => v.alertas
    ? `<span class="mntv-tipo cor" title="Abra a linha do tempo para ver qual leitura">${v.alertas} a conferir</span>`
    : v.semLeituraRecente ? `<span class="mntv-tipo aviso">Sem leitura há ${v.diasSemLeitura} dias</span>`
      : '<span class="mntv-tipo prev">Em dia</span>';
  corpo.innerHTML = lista.map(v => {
    const veic = odoVeiculo(v.placa);
    return `<tr>
      <td><button type="button" class="placa-btn placa-chip" data-placa="${esc(v.placa)}" title="Ver a linha do tempo do odômetro">${esc(v.placa)}</button></td>
      <td>${esc((veic && veic.modelo) || '—')}</td>
      <td>${esc(oficDataBR(v.primeira.data))}</td>
      <td class="num">${odoKm(v.primeira.km)}</td>
      <td>${esc(oficDataBR(v.ultima.data))}</td>
      <td class="num">${odoKm(v.ultima.km)}</td>
      <td class="num"><b>${odoKm(v.km)}</b></td>
      <td class="num">${v.dias}</td>
      <td class="num"${v.kmMes === null ? ' title="Precisa de 2 leituras em dias diferentes"' : ''}>${v.kmMes === null ? '—' : odoKm(Math.round(v.kmMes))}</td>
      <td class="num">${v.qtd}</td>
      <td>${situacao(v)}</td>
    </tr>`;
  }).join('');
  estadoVazio('odoVazio', ODOMETROS.length ? 1 : 0, lista.length,
    'Nenhuma leitura de odômetro ainda. Baixe a planilha modelo no menu ⋯, preencha e importe; ou use "+ Leitura".',
    limparFiltrosOdo);
  const resumo = document.getElementById('resumoOdo');
  if (resumo) {
    const rot = lista.length === r.veiculos.length ? `${lista.length} ${plural(lista.length, 'veículo', 'veículos')}` : `${lista.length} de ${r.veiculos.length} veículos`;
    resumo.innerHTML = `<span>${rot}</span>${per.texto ? ` <span>· período ${esc(per.texto)}</span>` : ''}`;
  }
  const btnAdd = document.getElementById('btnAddOdo');
  if (btnAdd) btnAdd.hidden = !odoPodeEditar();
  const btnImp = document.getElementById('btnImportOdo');
  if (btnImp) btnImp.hidden = !odoPodeEditar();
  renderImportacaoOdo();
  if (odoEstado.painel) odoEstado.painel.atualizar(); // contador do botão "Filtros"
}
function limparFiltrosOdo() {
  odoEstado.busca = ''; odoEstado.card = '';
  const b = document.getElementById('buscaOdo'); if (b) b.value = '';
  ['fodoPlaca', 'fodoPeriodo'].forEach(f => MSEL[f] && MSEL[f].limpar());
  renderOdometro();
}

// Faixa com o resultado da última importação, SÓ quando alguma linha não entrou (o
// resto cabe no toast). Some ao importar de novo sem erro ou ao recarregar a página.
function renderImportacaoOdo() {
  const host = document.getElementById('odoImportErros');
  if (!host) return;
  const imp = odoEstado.importacao;
  if (!imp || !imp.totalErros) { host.hidden = true; host.innerHTML = ''; return; }
  const n = imp.totalErros;
  const sub = `${imp.novas} ${plural(imp.novas, 'leitura nova gravada', 'leituras novas gravadas')} · ${imp.repetidas} já ${plural(imp.repetidas, 'existia', 'existiam')}`;
  const extra = n > imp.erros.length ? `<li class="ds-alert-item"><div class="ds-alert-linha ds-alert-error"><span class="ds-alert-linha-desc">e mais ${n - imp.erros.length} linhas</span></div></li>` : '';
  host.hidden = false;
  host.classList.add('ds-alert-faixa');
  host.innerHTML = `<div class="ds-alert ds-alert-error">
      <div class="ds-alert-icon">${ICONE_DS_ALERT_AVISO}</div>
      <div class="ds-alert-content">
        <div class="ds-alert-cab"><span class="ds-alert-title">${esc(`${n} ${plural(n, 'linha da planilha não entrou', 'linhas da planilha não entraram')}`)}</span>
          <span class="ds-alert-subtitle">${esc(sub)}</span></div>
        <ul class="ds-alert-lista" id="odoImportErrosLista" aria-label="Linhas que não entraram" hidden>${imp.erros.map(e => `
          <li class="ds-alert-item"><div class="ds-alert-linha ds-alert-error">
            <span class="ds-alert-linha-id">Linha ${esc(e.linha)}</span>
            <span class="ds-alert-linha-desc">${esc(e.motivo)}</span>
          </div></li>`).join('')}${extra}</ul>
      </div>
      <button type="button" class="ds-alert-action" id="odoImportErrosVer" aria-expanded="false" aria-controls="odoImportErrosLista">Ver ${n} ${plural(n, 'linha', 'linhas')}</button>
    </div>`;
  const btn = host.querySelector('#odoImportErrosVer'), lista = host.querySelector('#odoImportErrosLista');
  btn.onclick = () => { const abrir = lista.hidden; lista.hidden = !abrir; btn.setAttribute('aria-expanded', String(abrir)); };
}

// ----- Linha do tempo de um veículo (clique na placa) -----
function abrirOdoVeiculo(placa) {
  const p = odoPlaca(placa);
  if (!p) return;
  odoEstado.modalPlaca = p;
  const per = odoPeriodo();
  const r = OdometroCalc.resumoVeiculo(p, ODOMETROS.filter(l => l.placa === p), { de: per.de, ate: per.ate, hoje: odoHoje() });
  const v = odoVeiculo(p);
  document.getElementById('odoVeiculoTitulo').textContent = `Odômetro · ${p}`;
  const dados = v
    ? `<div class="mntv-veic">${[v.modelo, v.versao].filter(Boolean).map(esc).join(' ') || '—'}${v.centroCusto ? ` · <span class="mntv-cc">${esc(v.centroCusto)}</span>` : ''}</div>`
    : '<div class="mntv-veic mntv-fora">Placa não está na Frota atual (ou foi vendida); exibindo só as leituras de odômetro.</div>';
  const corpo = document.getElementById('odoVeiculoCorpo');
  if (!r) {
    corpo.innerHTML = dados + `<p class="vazio" style="margin:18px 4px;">Nenhuma leitura desta placa${per.texto ? ` no período ${esc(per.texto)}` : ''}.</p>`;
    document.getElementById('odoVeiculoModal').hidden = false;
    return;
  }
  const stat = (rot, val, cls = '') => `<div class="mntv-stat ${cls}"><span class="mntv-stat-n">${val}</span><span class="mntv-stat-l">${rot}</span></div>`;
  const stats = `<div class="mntv-stats">
    ${stat('km rodados', odoKm(r.km))}
    ${stat(plural(r.dias, 'dia', 'dias'), r.dias)}
    ${stat('média por dia', r.kmDia === null ? '—' : odoKm(r.kmDia))}
    ${stat('média por mês', r.kmMes === null ? '—' : odoKm(Math.round(r.kmMes)))}
    ${stat(plural(r.qtd, 'leitura', 'leituras'), r.qtd)}
    ${r.alertas ? stat('a conferir', r.alertas, 'red') : ''}
  </div>`;
  const faixa = `<p class="mntv-veic mntv-fora">De ${esc(oficDataBR(r.primeira.data))} (${odoKm(r.primeira.km)} km) até ${esc(oficDataBR(r.ultima.data))} (${odoKm(r.ultima.km)} km)${per.texto ? `, só leituras do período ${esc(per.texto)}` : ''}.</p>`;
  const grafico = r.qtd > 1 ? '<div class="chart-box compacta"><canvas id="chartOdoVeiculo" aria-label="Gráfico da quilometragem ao longo do tempo"></canvas></div>' : '';
  const podeEditar = odoPodeEditar();
  const origem = (l) => l.origem === 'manual' ? `Digitada${l.por ? ' por ' + l.por : ''}` : `Planilha ${l.arquivo || ''}${l.por ? ' · ' + l.por : ''}`;
  const linhas = r.linha.slice().reverse(); // a mais recente em cima
  const tabela = `<h4 class="mntv-sec">Leituras</h4>
    <table class="mntv-tabela">
      <thead><tr><th>Data</th><th class="num">Odômetro</th><th class="num">Desde a anterior</th><th class="num">Dias</th><th class="num">Km por dia</th><th class="num">Desde a 1ª</th><th>Observação</th>${podeEditar ? '<th><span class="sr-only">Ações</span></th>' : ''}</tr></thead>
      <tbody>${linhas.map(l => `<tr>
        <td title="${esc(origem(l))}">${esc(oficDataBR(l.data))}</td>
        <td class="num">${odoKm(l.km)}</td>
        <td class="num">${l.delta === null ? '—' : (l.delta > 0 ? '+' : '') + odoKm(l.delta)}</td>
        <td class="num">${l.dias === null ? '—' : l.dias}</td>
        <td class="num">${l.kmDia === null ? '—' : odoKm(l.kmDia)}</td>
        <td class="num">${odoKm(l.desdeInicio)}</td>
        <td>${l.alerta ? `<span class="mntv-tipo cor">${esc(OdometroCalc.textoAlerta(l))}</span> ` : ''}${esc(l.obs || '')}</td>
        ${podeEditar ? `<td class="num"><button type="button" class="icon-btn odo-del" data-id="${esc(l.id)}" title="Excluir esta leitura" aria-label="Excluir a leitura de ${esc(oficDataBR(l.data))}">${ICONE_LIXEIRA}</button></td>` : ''}
      </tr>`).join('')}</tbody>
    </table>`;
  corpo.innerHTML = dados + faixa + stats + grafico + tabela;
  document.getElementById('odoVeiculoModal').hidden = false;
  if (r.qtd > 1) {
    desenhar('chartOdoVeiculo', 'line', {
      labels: r.linha.map(l => oficDataBR(l.data)),
      datasets: [{
        label: 'Odômetro (km)', data: r.linha.map(l => l.km), borderColor: '#3f464e', backgroundColor: 'rgba(27,86,255,.12)',
        fill: true, tension: 0.15, pointRadius: 3,
        pointBackgroundColor: r.linha.map(l => (l.alerta ? '#dc2626' : '#3f464e')),
      }],
    }, {
      plugins: { legend: { display: false }, tooltip: { callbacks: { label: (ctx) => `${odoKm(ctx.parsed.y)} km` } } },
      scales: { y: { ticks: { callback: (val) => odoKm(val) } } },
    });
  }
}
function fecharOdoVeiculo() { document.getElementById('odoVeiculoModal').hidden = true; odoEstado.modalPlaca = ''; }

// ----- Nova leitura ("+ Leitura") -----
// Km digitado → número (aceita "46.850" e "46850,5"); null se ilegível. Espelha lerKm do servidor
// só para o aviso de "menor que a anterior" (quem decide o que grava é o servidor).
//   odoLerKm('46.850') // => 46850
function odoLerKm(v) {
  const s = String(v || '').trim().toLowerCase().replace(/km/g, '').replace(/\s+/g, '');
  if (!s) return null;
  const n = /^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s) ? Number(s.replace(/\./g, '').replace(',', '.')) : Number(s.replace(',', '.'));
  return Number.isFinite(n) && n >= 0 ? n : null;
}
function abrirOdoModal(placa = '') {
  const form = document.getElementById('formOdo');
  form.reset();
  form.elements.placa.value = placa;
  form.elements.data.value = odoHoje();
  document.getElementById('odoFormAviso').hidden = true;
  const dl = document.getElementById('listaPlacasOdo');
  if (dl) dl.innerHTML = [...new Set([...VEICULOS.map(v => odoPlaca(v.placa)), ...ODOMETROS.map(l => l.placa)].filter(Boolean))].sort().map(p => `<option value="${esc(p)}">`).join('');
  document.getElementById('odoModal').hidden = false;
  setTimeout(() => (placa ? form.elements.km : form.elements.placa).focus(), 30);
}
function fecharOdoModal() { document.getElementById('odoModal').hidden = true; }
function avisoFormOdo(msg) { const el = document.getElementById('odoFormAviso'); el.textContent = msg; el.hidden = !msg; }

(() => {
  const busca = document.getElementById('buscaOdo');
  if (busca) busca.addEventListener('input', debounce(() => { odoEstado.busca = busca.value; renderOdometro(); }, 120));
  criarMultiSelect('fodoPlaca', 'Placa', renderOdometro);
  criarFiltroPeriodo('fodoPeriodo', 'Período', renderOdometro, {
    prefixo: 'Período',
    anos: () => [...new Set(ODOMETROS.map(l => Number(String(l.data).slice(0, 4))).filter(Boolean))],
  });
  odoEstado.painel = criarPainelFiltros({
    btnId: 'odoFiltrosBtn', painelId: 'odoFiltrosPainel', contId: 'odoFiltrosCont', titId: 'odoFiltrosTit',
    contarAtivos: () => contaMsels(['fodoPlaca', 'fodoPeriodo']),
  });
  document.getElementById('btnLimparOdo').onclick = limparFiltrosOdo;
  document.getElementById('odoOrdem').onchange = (e) => { odoEstado.ordem = e.target.value; renderOdometro(); };
  // Cartões-filtro: clicar de novo no aceso desliga.
  const cards = document.getElementById('cardsOdo');
  const alternarCard = (el) => { const c = el.dataset.card; odoEstado.card = odoEstado.card === c ? '' : c; renderOdometro(); };
  cards.addEventListener('click', (e) => { const el = e.target.closest('.v2-kpi[data-card]'); if (el) alternarCard(el); });
  cards.addEventListener('keydown', (e) => {
    const el = e.target.closest('.v2-kpi[data-card]');
    if (el && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); alternarCard(el); }
  });
  // Planilha modelo / exportar (o Excel leva o recorte que está na tela) / importar.
  document.getElementById('btnModeloOdo').onclick = () => { window.location = '/api/odometros/modelo'; };
  document.getElementById('btnExportOdo').onclick = () => {
    const per = odoPeriodo();
    const q = new URLSearchParams();
    if (per.de) q.set('de', per.de);
    if (per.ate) q.set('ate', per.ate);
    if (odoFiltrando()) {
      const placas = odoRecorte().veiculos.map(v => v.placa);
      if (!placas.length) { toast('Nenhuma leitura no recorte atual para exportar.', 'erro'); return; }
      q.set('placas', placas.join(','));
    }
    window.location = '/api/odometros/exportar' + (q.toString() ? '?' + q : '');
  };
  document.getElementById('btnImportOdo').onclick = () => document.getElementById('inputImportOdo').click();
  document.getElementById('inputImportOdo').onchange = async (e) => {
    const file = e.target.files[0]; e.target.value = '';
    if (!file) return;
    const btn = document.getElementById('btnImportOdo');
    const fd = new FormData(); fd.append('arquivo', file);
    btn.disabled = true; btn.setAttribute('aria-busy', 'true');
    toast('Importando leituras...', '');
    try {
      const r = await fetch('/api/odometros/importar', { method: 'POST', body: fd });
      const j = await r.json().catch(() => ({}));
      odoEstado.importacao = j && Array.isArray(j.erros) ? j : null;
      if (!r.ok) { renderImportacaoOdo(); toast(j.erro || 'Erro ao importar.', 'erro'); return; }
      await carregarOdometros();
      const partes = [`${j.novas} ${plural(j.novas, 'leitura nova', 'leituras novas')}`];
      if (j.repetidas) partes.push(`${j.repetidas} já ${plural(j.repetidas, 'existia', 'existiam')}`);
      if (j.exemplos) partes.push(`${j.exemplos} de exemplo ${plural(j.exemplos, 'ignorada', 'ignoradas')}`);
      if (j.totalErros) partes.push(`${j.totalErros} com erro`);
      toast(`Importado: ${partes.join(' · ')}.`, j.totalErros ? '' : 'ok');
      if (j.placasForaDaFrota && j.placasForaDaFrota.length) {
        setTimeout(() => toast(`Placas fora da Frota: ${j.placasForaDaFrota.slice(0, 6).join(', ')}${j.placasForaDaFrota.length > 6 ? '...' : ''}. As leituras entraram mesmo assim.`, ''), 2600);
      }
      atualizarUndoStatus();
    } catch (err) {
      toast('Falha de conexão ao importar. Tente novamente.', 'erro');
    } finally {
      btn.disabled = false; btn.removeAttribute('aria-busy');
    }
  };
  // "+ Leitura" e o formulário.
  document.getElementById('btnAddOdo').onclick = () => abrirOdoModal('');
  document.getElementById('fecharOdo').onclick = fecharOdoModal;
  document.getElementById('cancelarOdo').onclick = fecharOdoModal;
  fecharAoClicarNoFundo('odoModal', fecharOdoModal);
  document.getElementById('formOdo').addEventListener('submit', async (e) => {
    e.preventDefault();
    const f = e.target.elements;
    const placa = odoPlaca(f.placa.value), data = f.data.value, km = odoLerKm(f.km.value);
    if (!/^[A-Z]{3}\d[A-Z0-9]\d{2}$/.test(placa)) return avisoFormOdo('Placa inválida. Use o formato ABC1234 ou ABC1D23.');
    if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) return avisoFormOdo('Informe a data da leitura.');
    if (data > odoHoje()) return avisoFormOdo('A data da leitura não pode ser no futuro.');
    if (km === null) return avisoFormOdo('Informe o número do odômetro, em km.');
    avisoFormOdo('');
    // Menor que a leitura anterior do mesmo veículo? Entra, mas o usuário decide sabendo.
    const anterior = OdometroCalc.ordenarLeituras(ODOMETROS.filter(l => l.placa === placa && l.data <= data)).pop();
    if (anterior && km < anterior.km && !(await confirmar(`${odoKm(km)} km é menor que a leitura de ${oficDataBR(anterior.data)} (${odoKm(anterior.km)} km). Salvar mesmo assim? Ela fica marcada para conferir.`, { okTexto: 'Salvar' }))) return;
    const btn = document.getElementById('salvarOdo');
    btn.disabled = true; btn.textContent = 'Salvando...';
    try {
      const r = await fetch('/api/odometros', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ placa, data, km, obs: f.obs.value }),
      });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) { avisoFormOdo(j.erro || 'Não foi possível salvar.'); return; }
      fecharOdoModal();
      await carregarOdometros();
      toast(`Leitura de ${placa} salva: ${odoKm(j.km)} km.`, 'ok');
      atualizarUndoStatus();
    } catch (err) {
      avisoFormOdo('Falha de conexão. Tente novamente.');
    } finally {
      btn.disabled = false; btn.textContent = 'Salvar';
    }
  });
  // Modal da linha do tempo: fechar, excluir leitura, "+ Leitura" já com a placa.
  document.getElementById('fecharOdoVeiculo').onclick = fecharOdoVeiculo;
  fecharAoClicarNoFundo('odoVeiculoModal', fecharOdoVeiculo);
  document.getElementById('odoVeiculoCorpo').addEventListener('click', async (e) => {
    const del = e.target.closest('.odo-del');
    if (!del) return;
    const l = ODOMETROS.find(x => x.id === del.dataset.id);
    if (!l) return;
    if (!(await confirmar(`Excluir a leitura de ${l.placa} em ${oficDataBR(l.data)} (${odoKm(l.km)} km)?`, { perigo: true, okTexto: 'Excluir' }))) return;
    del.disabled = true;
    const r = await fetch('/api/odometros/' + encodeURIComponent(l.id), { method: 'DELETE' });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) { del.disabled = false; toast(j.erro || 'Erro ao excluir.', 'erro'); return; }
    await carregarOdometros();
    toast('Leitura excluída. Use "Desfazer" na aba se foi engano.', 'ok');
    atualizarUndoStatus();
  });
})();

// ----- Sub-aba Dashboards: gráficos Chart.js -----
function renderDashboardsMnt() {
  const lista = mntFiltrados();
  const porVeic = agruparPorVeiculo(lista).sort((a, b) => b.total - a.total);
  // KPIs do topo dos dashboards
  const total = lista.reduce((s, e) => s + custoEv(e), 0);
  const corr = lista.filter(ehCorretiva).reduce((s, e) => s + custoEv(e), 0);
  document.getElementById('cardsDashMnt').innerHTML = `
    ${cardV2('Custo total', fmtMoneyDec(total), 'red', true)}
    ${cardV2('Corretiva', fmtMoneyDec(corr), '', true)}
    ${cardV2('Preventiva', fmtMoneyDec(total - corr), 'green', true)}
    ${cardV2('Veículos', porVeic.length, '')}
  `;
  // 1) Custo total por veículo (top 20)
  const top = porVeic.slice(0, 20);
  desenhar('chartMntVeiculo', 'bar', {
    labels: top.map(v => v.placa),
    datasets: [{ label: 'Custo total', data: top.map(v => Math.round(v.total)), backgroundColor: '#1b56ff' }],
  }, { plugins: { legend: { display: false } }, scales: { y: { beginAtZero: true } } });
  // 2) Corretiva × Preventiva (frota toda)
  desenhar('chartMntTipo', 'doughnut', {
    labels: ['Corretiva', 'Preventiva'],
    datasets: [{ data: [Math.round(corr), Math.round(total - corr)], backgroundColor: ['#dc2626', '#16a34a'] }],
  });
  // 3) Custo por centro de custo
  const porCentro = new Map();
  for (const e of lista) porCentro.set(e.centroCusto || '—', (porCentro.get(e.centroCusto || '—') || 0) + custoEv(e));
  const centroArr = [...porCentro.entries()].sort((a, b) => b[1] - a[1]);
  desenhar('chartMntCentro', 'bar', {
    labels: centroArr.map(x => trunc(x[0], 18)),
    datasets: [{ label: 'Custo', data: centroArr.map(x => Math.round(x[1])), backgroundColor: centroArr.map((_, i) => CORES_MNT[i % CORES_MNT.length]) }],
  }, { plugins: { legend: { display: false } }, scales: { y: { beginAtZero: true } } });
  // 4) Evolução mensal
  const porMes = new Map();
  for (const e of lista) { const k = mesDeMnt(e.data); if (k) porMes.set(k, (porMes.get(k) || 0) + custoEv(e)); }
  const mesesArr = [...porMes.entries()].sort((a, b) => a[0].localeCompare(b[0]));
  desenhar('chartMntMensal', 'bar', {
    labels: mesesArr.map(x => rotuloMes(x[0])),
    datasets: [{ label: 'Custo no mês', data: mesesArr.map(x => Math.round(x[1])), backgroundColor: '#0369a1' }],
  }, { plugins: { legend: { display: false } }, scales: { y: { beginAtZero: true } } });

  // ===== Comparativos (reproduzem os gráficos da planilha) =====
  const moedaTooltip = { plugins: { tooltip: { callbacks: { label: (ctx) => `${ctx.dataset.label}: ${fmtMoneyDec(ctx.parsed.y ?? ctx.parsed)}` } } } };

  // 5) Comparativo POR MODELO — um gráfico por modelo, comparando os veículos
  //    daquele modelo entre si (L200 × L200, F4000 × F4000...). Inspirado nos
  //    gráficos por mês da planilha, mas quebrado por modelo (família).
  const porFamilia = new Map();
  for (const e of lista) {
    const fam = familiaModelo(e.modelo);
    let g = porFamilia.get(fam); if (!g) { g = { veics: new Map(), total: 0 }; porFamilia.set(fam, g); }
    let v = g.veics.get(e.placa); if (!v) { v = { corretiva: 0, preventiva: 0, total: 0 }; g.veics.set(e.placa, v); }
    const c = custoEv(e); g.total += c; v.total += c;
    if (ehCorretiva(e)) v.corretiva += c; else v.preventiva += c;
  }
  // Overview modelo × modelo: custo total por família (todos os modelos), do maior p/ o menor.
  const familiasTodas = [...porFamilia.entries()].sort((a, b) => b[1].total - a[1].total);
  const somaFam = (g, tipo) => [...g.veics.values()].reduce((s, v) => s + v[tipo], 0);
  desenhar('chartMntModeloTotal', 'bar', {
    labels: familiasTodas.map(x => x[0]),
    datasets: [
      { label: 'Corretiva', data: familiasTodas.map(x => Math.round(somaFam(x[1], 'corretiva'))), backgroundColor: '#dc2626' },
      { label: 'Preventiva', data: familiasTodas.map(x => Math.round(somaFam(x[1], 'preventiva'))), backgroundColor: '#16a34a' },
    ],
  }, { plugins: { legend: { position: 'bottom' }, tooltip: moedaTooltip.plugins.tooltip }, scales: { x: { stacked: true }, y: { stacked: true, beginAtZero: true } } });

  // Só modelos com 2+ veículos (onde "x" faz sentido), do mais caro p/ o mais barato.
  const familias = familiasTodas.filter(([, g]) => g.veics.size >= 2);
  // Descarta instâncias antigas dos gráficos por modelo antes de recriar.
  Object.keys(charts).filter(k => k.startsWith('chartMntFam')).forEach(k => { charts[k].destroy(); delete charts[k]; });
  const cont = document.getElementById('mntModeloCharts');
  if (cont) {
    if (!familias.length) {
      cont.innerHTML = '<p class="vazio">Nenhum modelo com 2 ou mais veículos no filtro atual.</p>';
    } else {
      cont.innerHTML = familias.map(([fam, g], i) =>
        `<div class="modelo-card">
           <h4>${esc(fam)} · ${g.veics.size} veículos · ${fmtMoneyDec(g.total)}</h4>
           <div class="chart-box"><canvas id="chartMntFam${i}"></canvas></div>
         </div>`).join('');
      familias.forEach(([, g], i) => {
        const veics = [...g.veics.entries()].sort((a, b) => b[1].total - a[1].total);
        desenhar(`chartMntFam${i}`, 'bar', {
          labels: veics.map(x => x[0]),
          datasets: [
            { label: 'Corretiva', data: veics.map(x => Math.round(x[1].corretiva)), backgroundColor: '#dc2626' },
            { label: 'Preventiva', data: veics.map(x => Math.round(x[1].preventiva)), backgroundColor: '#16a34a' },
          ],
        }, { plugins: { legend: { position: 'bottom' }, tooltip: moedaTooltip.plugins.tooltip }, scales: { x: { stacked: true }, y: { stacked: true, beginAtZero: true } } });
      });
    }
  }

  // 6) Custo por ANO do veículo (compara ano por ano)
  const porAno = new Map();
  for (const e of lista) { const k = String(e.ano || '—').trim() || '—'; porAno.set(k, (porAno.get(k) || 0) + custoEv(e)); }
  const anoArr = [...porAno.entries()].sort((a, b) => {
    const na = Number(a[0]), nb = Number(b[0]);
    if (isNaN(na)) return 1; if (isNaN(nb)) return -1; return na - nb;
  });
  desenhar('chartMntAno', 'bar', {
    labels: anoArr.map(x => x[0]),
    datasets: [{ label: 'Custo total', data: anoArr.map(x => Math.round(x[1])), backgroundColor: '#7c3aed' }],
  }, { plugins: { legend: { display: false }, tooltip: moedaTooltip.plugins.tooltip }, scales: { y: { beginAtZero: true } } });

  // 7) Centros de custo POR MÊS (barras empilhadas: X = mês, uma série por centro)
  const centros = [...new Set(lista.map(e => e.centroCusto || '—'))]
    .sort((a, b) => (porCentro.get(b) || 0) - (porCentro.get(a) || 0));
  const mesesCM = [...new Set(lista.map(e => mesDeMnt(e.data)).filter(Boolean))].sort();
  const matriz = new Map(); // `${mes}|${centro}` -> soma
  for (const e of lista) { const m = mesDeMnt(e.data); if (!m) continue; const k = m + '|' + (e.centroCusto || '—'); matriz.set(k, (matriz.get(k) || 0) + custoEv(e)); }
  desenhar('chartMntCentroMes', 'bar', {
    labels: mesesCM.map(rotuloMes),
    datasets: centros.map((c, i) => ({
      label: trunc(c, 18),
      data: mesesCM.map(m => Math.round(matriz.get(m + '|' + c) || 0)),
      backgroundColor: CORES_MNT[i % CORES_MNT.length],
    })),
  }, { plugins: { legend: { position: 'bottom' }, tooltip: moedaTooltip.plugins.tooltip }, scales: { x: { stacked: true }, y: { stacked: true, beginAtZero: true } } });
}

// ----- Sub-aba Alertas: risco por veículo (reproduz a aba "Alertas" da planilha) -----
function classificarRisco(porVeic) {
  const n = porVeic.length || 1;
  const mediaCusto = porVeic.reduce((s, v) => s + v.total, 0) / n;
  const mediaCorr = porVeic.reduce((s, v) => s + v.qtdCorretiva, 0) / n;
  // A planilha classifica o RISCO pela recorrência (qtd. de corretivas) em faixas
  // relativas à média da frota — NÃO pelo custo (veículos caros mas com poucas
  // corretivas ficam "Normal" lá). Faixas calibradas p/ reproduzir a planilha:
  // 🔴 Crítico ≥ 1,15× a média de corretivas · 🟡 Atenção ≥ 0,85× a média.
  // O custo entra como CONTEXTO no texto do alerta, não na classificação.
  const limCrit = 1.15 * mediaCorr;
  const limAten = 0.85 * mediaCorr;
  return porVeic.map(v => {
    let risco = '🟢 Normal';
    if (v.qtdCorretiva >= limCrit) risco = '🔴 Crítico';
    else if (v.qtdCorretiva >= limAten) risco = '🟡 Atenção';
    const alertas = [];
    if (v.total >= 2 * mediaCusto) alertas.push(`Custo ${fmtMoney(v.total)} – acima de 2× a média`);
    else if (v.total >= mediaCusto) alertas.push(`Custo ${fmtMoney(v.total)} – acima da média`);
    if (v.qtdCorretiva >= limCrit) alertas.push(`${v.qtdCorretiva} corretivas – recorrência alta`);
    else if (v.qtdCorretiva >= limAten) alertas.push(`${v.qtdCorretiva} corretivas – recorrência acima da média`);
    return Object.assign({}, v, { risco, alerta: alertas.join(' | ') || 'Dentro da média' });
  });
}
function renderAlertasMnt() {
  const porVeic = classificarRisco(agruparPorVeiculo(mntFiltrados()));
  const ordem = { '🔴 Crítico': 0, '🟡 Atenção': 1, '🟢 Normal': 2 };
  porVeic.sort((a, b) => (ordem[a.risco] - ordem[b.risco]) || b.total - a.total);
  const crit = porVeic.filter(v => v.risco.includes('🔴')).length;
  const aten = porVeic.filter(v => v.risco.includes('🟡')).length;
  const norm = porVeic.length - crit - aten;
  document.getElementById('cardsAlertaMnt').innerHTML = `
    ${cardV2('🔴 Críticos', crit, 'red')}
    ${cardV2('🟡 Atenção', aten, 'amber')}
    ${cardV2('🟢 Normais', norm, 'green')}
    ${cardV2('Veículos', porVeic.length, '')}
  `;
  const vazio = document.getElementById('alertaMntVazio');
  const corpo = document.getElementById('corpoAlertaMnt');
  if (!porVeic.length) { corpo.innerHTML = ''; document.getElementById('cabecalhoAlertaMnt').innerHTML = ''; vazio.hidden = false; return; }
  vazio.hidden = true;
  document.getElementById('cabecalhoAlertaMnt').innerHTML =
    '<th>Risco</th><th data-campo="placa">Placa</th><th>Modelo</th><th>Motorista</th><th class="num">Custo total</th><th class="num">Itens</th><th class="num">Corretivas</th><th>Centro de custo</th><th>Alerta principal</th>';
  corpo.innerHTML = porVeic.map(v => `<tr>
    <td><b>${esc(v.risco)}</b></td>
    <td><button class="placa-btn placa-chip" data-placa="${esc(v.placa)}" title="Filtrar por esta placa">${esc(v.placa)}</button></td>
    <td>${esc(v.modelo || '—')}</td>
    <td>${esc(v.motorista || '—')}</td>
    <td class="num">${fmtMoneyDec(v.total)}</td>
    <td class="num">${v.itens}</td>
    <td class="num">${v.qtdCorretiva}</td>
    <td>${esc(v.centroCusto || '—')}</td>
    <td>${esc(v.alerta)}</td>
  </tr>`).join('');
}

/* ----- Sub-aba Relatórios: um cartão por veículo → PDF do histórico completo -----
   A lista vem pronta do servidor (`/api/manutencao/relatorios`), que junta pela PLACA o
   cadastro da frota + os eventos + as notas fiscais. É de propósito: quem tem acesso só
   à Manutenção não carrega VEICULOS (a aba Frota tem permissão própria) e ficaria sem
   modelo/chassi/renavam nos cartões. O PDF sai de `/api/manutencao/relatorio/<placa>`. */
let REL_MNT = [];                                    // agregados por veículo (do servidor)
let relMntPlaca = '';                                // placa aberta no modal
const relMntEstado = { busca: '', filtro: 'todos', ordem: 'placa' };

// A sub-aba está na tela? (usado pelo tempo real: só rebusca os agregados se alguém está vendo)
function relatoriosMntVisiveis() {
  const el = document.getElementById('mnt-relatorios');
  return !!el && el.classList.contains('active');
}
async function atualizarRelatoriosMnt() {
  try {
    const r = await fetch('/api/manutencao/relatorios', { cache: 'no-store' });
    if (r.ok) { const d = await r.json(); REL_MNT = (d && d.veiculos) || []; }
  } catch (e) { /* offline: mantém o que já estava na tela */ }
  renderRelatoriosMnt();
}
function relMntFiltrados() {
  const termo = relMntEstado.busca.trim().toLowerCase();
  return REL_MNT.filter(v => {
    if (relMntEstado.filtro === 'com' && !v.eventos) return false;
    if (relMntEstado.filtro === 'sem' && v.eventos) return false;
    if (!termo) return true;
    return [v.placa, v.modelo, v.versao, v.montadora, v.centroCusto, v.dono, v.motorista, v.status]
      .some(x => String(x || '').toLowerCase().includes(termo));
  });
}
function renderRelatoriosMnt() {
  const cont = document.getElementById('relMntCards');
  if (!cont) return;
  // Chips de filtro (contagens ao vivo)
  const chips = document.getElementById('relMntChips');
  if (chips) {
    const com = REL_MNT.filter(v => v.eventos).length;
    const chip = (val, rot) => `<button type="button" class="forn-chip${relMntEstado.filtro === val ? ' on' : ''}" data-rel="${val}">${esc(rot)}</button>`;
    chips.innerHTML = chip('todos', `Todos (${REL_MNT.length})`) + chip('com', `Com manutenções (${com})`) + chip('sem', `Sem manutenções (${REL_MNT.length - com})`);
  }
  const lista = relMntFiltrados().slice().sort((a, b) => {
    if (relMntEstado.ordem === 'custo') return b.custoTotal - a.custoTotal || a.placa.localeCompare(b.placa, 'pt-BR');
    if (relMntEstado.ordem === 'qtd') return b.eventos - a.eventos || a.placa.localeCompare(b.placa, 'pt-BR');
    if (relMntEstado.ordem === 'recente') return dataOrdMnt(b.ultima) - dataOrdMnt(a.ultima) || a.placa.localeCompare(b.placa, 'pt-BR');
    return a.placa.localeCompare(b.placa, 'pt-BR');
  });
  const resumo = document.getElementById('relMntResumo');
  if (resumo) {
    const gasto = lista.reduce((s, v) => s + v.custoTotal, 0);
    const filtrando = relMntEstado.busca || relMntEstado.filtro !== 'todos';
    resumo.textContent = `${filtrando ? `${lista.length} de ${REL_MNT.length}` : `${REL_MNT.length}`} veículo(s)`
      + (gasto ? ` · ${fmtMoneyDec(gasto)} em manutenção` : '');
  }
  estadoVazio('relMntVazio', REL_MNT.length, lista.length,
    'Nenhum veículo para relatar ainda. Cadastre veículos na aba Frota ou importe o Relatório de Manutenção.',
    () => { relMntEstado.busca = ''; relMntEstado.filtro = 'todos'; const b = document.getElementById('relMntBusca'); if (b) b.value = ''; renderRelatoriosMnt(); });
  cont.innerHTML = lista.map(v => {
    const sub = [v.montadora, v.ano ? 'Ano ' + v.ano : '', v.centroCusto].filter(Boolean).join(' · ');
    const pctCorr = v.custoTotal ? Math.round((v.custoCorretiva / v.custoTotal) * 100) : 0;
    return `<article class="rel-card" data-placa="${esc(v.placa)}" role="button" tabindex="0" title="Ver detalhes e gerar o relatório de ${esc(v.placa)}">
      <header class="rel-card-top">
        <span class="rel-placa">${esc(v.placa)}</span>
        <div class="rel-card-titwrap">
          <h3 class="rel-card-nome" title="${esc([v.modelo, v.versao].filter(Boolean).join(' '))}">${esc([v.modelo, v.versao].filter(Boolean).join(' ') || 'Sem modelo informado')}</h3>
          ${sub ? `<span class="rel-card-sub">${esc(sub)}</span>` : ''}
        </div>
      </header>
      <div class="rel-nums">
        <div><span class="rel-num-rot">Manutenções</span><b>${v.eventos}</b></div>
        <div><span class="rel-num-rot">Custo total</span><b class="rel-num-red">${fmtMoneyDec(v.custoTotal)}</b></div>
        <div><span class="rel-num-rot">Última</span><b>${esc(fmtData(v.ultima) || '—')}</b></div>
      </div>
      <div class="rel-tags">
        <span class="rel-tag rel-tag-vermelho" title="Manutenções corretivas">🔧 ${v.corretivas} corretiva(s)${v.eventos ? ` · ${pctCorr}% do custo` : ''}</span>
        <span class="rel-tag rel-tag-verde" title="Manutenções preventivas">🛡 ${v.preventivas} preventiva(s)</span>
        ${v.notas ? `<span class="rel-tag" title="Notas fiscais arquivadas">🧾 ${v.notas} nota(s) · ${fmtMoneyDec(v.custoNotas)}</span>` : ''}
        ${v.noCadastro ? '' : '<span class="rel-tag rel-tag-alerta" title="A placa aparece na manutenção, mas não está cadastrada na aba Frota">⚠ Fora do cadastro da frota</span>'}
      </div>
      <footer class="rel-card-pe">
        <button type="button" class="btn btn-primary small rel-gerar" data-placa="${esc(v.placa)}" title="Baixar o PDF com o histórico completo deste veículo">⬇ Gerar relatório</button>
      </footer>
    </article>`;
  }).join('');
}
// Modal de detalhes: prévia do que vai sair no PDF + os dois botões (visualizar / gerar).
function abrirRelMntModal(placa) {
  const v = REL_MNT.find(x => x.placa === placa);
  if (!v) return;
  relMntPlaca = placa;
  const eventos = MANUTENCAO.filter(e => e.placa === placa).slice().sort((a, b) => dataOrdMnt(b.data) - dataOrdMnt(a.data));
  const notas = OFICINA.filter(o => String(o.placa || '').toUpperCase() === placa).slice().sort((a, b) => String(b.data || '').localeCompare(String(a.data || '')));
  const datas = eventos.map(e => e.data).filter(d => dataOrdMnt(d)).sort((a, b) => dataOrdMnt(a) - dataOrdMnt(b));
  document.getElementById('relMntTitulo').textContent = `Relatório · ${placa}`;
  const campo = (rot, val) => val ? `<div class="rel-campo"><span class="rel-campo-rot">${esc(rot)}</span><span class="rel-campo-val">${esc(val)}</span></div>` : '';
  const MAX = 8;
  const linhas = eventos.slice(0, MAX).map(e => `<tr>
    <td>${esc(fmtData(e.data) || '—')}</td>
    <td>${String(e.tipo || '').toLowerCase().startsWith('corr') ? 'Corretiva' : 'Preventiva'}</td>
    <td class="rel-prev-item" title="${esc(e.item || '')}">${esc(e.item || '—')}</td>
    <td class="num">${fmtMoneyDec(custoEv(e))}</td>
  </tr>`).join('');
  document.getElementById('relMntCorpo').innerHTML = `
    <div class="rel-modal-sec">Identificação do veículo</div>
    <div class="rel-campos">
      ${campo('Placa', v.placa)}
      ${campo('Modelo', [v.modelo, v.versao].filter(Boolean).join(' '))}
      ${campo('Montadora', v.montadora)}
      ${campo('Ano', v.ano)}
      ${campo('Cor', v.cor)}
      ${campo('Chassi', v.chassi)}
      ${campo('Renavam', v.renavam)}
      ${campo('Centro de custo', v.centroCusto)}
      ${campo('Proprietário', v.dono)}
      ${campo('Situação', v.status)}
      ${campo('Motorista', v.motorista && v.motorista !== '—' ? v.motorista : '')}
    </div>
    ${v.noCadastro ? '' : '<p class="rel-aviso">⚠ Esta placa não está cadastrada na aba Frota; o relatório usa os dados dos próprios registros de manutenção.</p>'}
    <div class="rel-modal-sec">Resumo das manutenções${datas.length ? ` <span class="rel-modal-sec-sub">${esc(datas[0])} a ${esc(datas[datas.length - 1])}</span>` : ''}</div>
    <div class="rel-kpis">
      <div class="rel-kpi"><span>Custo total</span><b class="rel-num-red">${fmtMoneyDec(v.custoTotal)}</b><i>${v.eventos} manutenção(ões)</i></div>
      <div class="rel-kpi"><span>Corretiva</span><b class="rel-num-red">${fmtMoneyDec(v.custoCorretiva)}</b><i>${v.corretivas} evento(s)</i></div>
      <div class="rel-kpi"><span>Preventiva</span><b class="rel-num-verde">${fmtMoneyDec(v.custoPreventiva)}</b><i>${v.preventivas} evento(s)</i></div>
      <div class="rel-kpi"><span>Notas fiscais</span><b>${fmtMoneyDec(v.custoNotas)}</b><i>${notas.length} nota(s)</i></div>
    </div>
    <div class="rel-modal-sec">Manutenções realizadas${eventos.length > MAX ? ` <span class="rel-modal-sec-sub">mostrando ${MAX} de ${eventos.length}; o PDF traz todas</span>` : ''}</div>
    ${eventos.length ? `<div class="tabela-wrap rel-prev-wrap"><table class="rel-prev"><thead><tr><th>Data</th><th>Tipo</th><th>Item / serviço</th><th class="num">Valor</th></tr></thead><tbody>${linhas}</tbody></table></div>`
      : '<p class="rel-aviso">Nenhuma manutenção registrada para este veículo. O relatório sai só com a identificação.</p>'}
    <p class="rel-rodape">O PDF traz todas as manutenções detalhadas, os gastos por ano, as notas fiscais e o consolidado por oficina.</p>`;
  document.getElementById('relMntModal').hidden = false;
}
function fecharRelMntModal() { document.getElementById('relMntModal').hidden = true; relMntPlaca = ''; }

/* ----- Popup "quem assina" (passo obrigatório antes de gerar/visualizar o PDF) -----
   A lista são os usuários ATIVOS do sistema (`/api/usuarios/ativos`), que já vêm marcados
   como pré-seleção. O cliente manda só os IDs; o servidor resolve os nomes no cadastro,
   para que ninguém consiga imprimir texto arbitrário na linha de assinatura. */
// (nome distinto de USUARIOS_ATIVOS, o cache do painel de Usuários — aquele só o admin
// consegue carregar; este vem da rota enxuta e serve para qualquer um escolher assinantes)
let ASSINANTES_ATIVOS = [];                // [{id, nome}] — carregado sob demanda
let relAssinaSel = null;                   // Set de ids; null = ainda não escolhido nesta sessão
let relAssinaAlvo = { placa: '', modo: 'baixar' };

// Rebusca a cada abertura (payload minúsculo): assim quem foi aprovado agora já aparece,
// sem depender de F5. Em falha de rede mantém a lista anterior.
async function carregarAssinantesAtivos() {
  try {
    const r = await fetch('/api/usuarios/ativos', { cache: 'no-store' });
    if (r.ok) { const d = await r.json(); if (Array.isArray(d && d.usuarios)) ASSINANTES_ATIVOS = d.usuarios; }
  } catch (e) { /* offline: segue com o que tinha — dá para gerar sem assinatura */ }
  return ASSINANTES_ATIVOS;
}
async function abrirRelAssinaModal(placa, modo) {
  relAssinaAlvo = { placa, modo: modo === 'ver' ? 'ver' : 'baixar' };
  document.getElementById('relAssinaPlaca').textContent = placa;
  document.getElementById('relAssinaOk').textContent = relAssinaAlvo.modo === 'ver' ? '👁 Visualizar' : '⬇ Gerar relatório (PDF)';
  const lista = document.getElementById('relAssinaLista');
  lista.innerHTML = '<p class="rel-assina-vazio">Carregando…</p>';
  document.getElementById('relAssinaResumo').textContent = '';
  document.getElementById('relAssinaModal').hidden = false;
  const usuarios = await carregarAssinantesAtivos();
  // Pré-seleção: todos os usuários ativos (o que o RH pediu). A escolha do usuário
  // sobrevive dentro da sessão, para não ter que remarcar a cada relatório.
  if (!relAssinaSel) relAssinaSel = new Set(usuarios.map(u => u.id));
  if (!usuarios.length) {
    lista.innerHTML = '<p class="rel-assina-vazio">Nenhum usuário ativo encontrado. O relatório sai sem linha de assinatura.</p>';
    atualizarRelAssinaResumo();
    return;
  }
  lista.innerHTML = usuarios.map(u => `<label class="rel-assina-item">
    <input type="checkbox" value="${esc(u.id)}"${relAssinaSel.has(u.id) ? ' checked' : ''} />
    <span class="rel-assina-nome">${esc(u.nome)}</span>
  </label>`).join('');
  atualizarRelAssinaResumo();
}
function atualizarRelAssinaResumo() {
  const n = relAssinaSel ? relAssinaSel.size : 0;
  const total = ASSINANTES_ATIVOS.length;
  const cont = document.getElementById('relAssinaContagem');
  if (cont) cont.textContent = total ? `${n} de ${total} marcado(s)` : '';
  document.getElementById('relAssinaResumo').textContent = n
    ? `${n} linha(s) de assinatura no fim do relatório.`
    : 'Ninguém marcado; o relatório sai sem linha de assinatura.';
}
// Marca/desmarca a lista inteira (com 10+ usuários ativos, tirar um a um é penoso).
function marcarTodosRelAssina(marcar) {
  relAssinaSel = new Set(marcar ? ASSINANTES_ATIVOS.map(u => u.id) : []);
  document.querySelectorAll('#relAssinaLista input[type="checkbox"]').forEach(cb => { cb.checked = marcar; });
  atualizarRelAssinaResumo();
}
function fecharRelAssinaModal() { document.getElementById('relAssinaModal').hidden = true; }
// Monta a URL do PDF já com os assinantes escolhidos (ids).
function urlRelatorioMnt(placa, inline) {
  // Mantém a ordem alfabética da lista (e não a ordem de clique) — é como saem no PDF.
  const ids = relAssinaSel ? ASSINANTES_ATIVOS.filter(u => relAssinaSel.has(u.id)).map(u => u.id) : [];
  const qs = [];
  if (inline) qs.push('ver=1');
  if (ids.length) qs.push('assinantes=' + encodeURIComponent(ids.join(',')));
  return '/api/manutencao/relatorio/' + encodeURIComponent(placa) + (qs.length ? '?' + qs.join('&') : '');
}
function baixarRelatorioMnt(placa) {
  baixarArquivoServidor(urlRelatorioMnt(placa, false),
    'RELATORIO_MANUTENCAO_' + placa + '.pdf', `Gerando o relatório de ${placa} em PDF…`);
}
(() => {
  const lista = document.getElementById('relAssinaLista');
  if (lista) lista.addEventListener('change', (e) => {
    const cb = e.target.closest('input[type="checkbox"]'); if (!cb) return;
    if (!relAssinaSel) relAssinaSel = new Set();
    if (cb.checked) relAssinaSel.add(cb.value); else relAssinaSel.delete(cb.value);
    atualizarRelAssinaResumo();
  });
  document.getElementById('relAssinaTodos').onclick = () => marcarTodosRelAssina(true);
  document.getElementById('relAssinaNenhum').onclick = () => marcarTodosRelAssina(false);
  document.getElementById('fecharRelAssina').onclick = fecharRelAssinaModal;
  document.getElementById('relAssinaCancelar').onclick = fecharRelAssinaModal;
  fecharAoClicarNoFundo('relAssinaModal', fecharRelAssinaModal);
  document.getElementById('relAssinaOk').onclick = () => {
    const { placa, modo } = relAssinaAlvo;
    fecharRelAssinaModal();
    if (!placa) return;
    if (modo === 'ver') window.open(urlRelatorioMnt(placa, true), '_blank', 'noopener');
    else baixarRelatorioMnt(placa);
  };
})();
(() => {
  const busca = document.getElementById('relMntBusca');
  if (busca) busca.addEventListener('input', debounce(() => { relMntEstado.busca = busca.value; renderRelatoriosMnt(); }, 120));
  const ordem = document.getElementById('relMntOrdem');
  if (ordem) ordem.onchange = () => { relMntEstado.ordem = ordem.value; renderRelatoriosMnt(); };
  const chips = document.getElementById('relMntChips');
  if (chips) chips.addEventListener('click', (e) => {
    const c = e.target.closest('.forn-chip'); if (!c) return;
    relMntEstado.filtro = c.dataset.rel; renderRelatoriosMnt();
  });
  const cards = document.getElementById('relMntCards');
  if (cards) {
    cards.addEventListener('click', (e) => {
      const g = e.target.closest('.rel-gerar');
      if (g) { e.stopPropagation(); abrirRelAssinaModal(g.dataset.placa, 'baixar'); return; }
      const card = e.target.closest('.rel-card');
      if (card) abrirRelMntModal(card.dataset.placa);
    });
    cards.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      if (e.target.closest('button')) return; // o botão "Gerar relatório" cuida do próprio teclado
      const card = e.target.closest('.rel-card'); if (!card) return;
      e.preventDefault(); abrirRelMntModal(card.dataset.placa);
    });
  }
  document.getElementById('fecharRelMnt').onclick = fecharRelMntModal;
  fecharAoClicarNoFundo('relMntModal', fecharRelMntModal);
  // Os dois caminhos passam pelo popup de assinatura para que a prévia e o arquivo baixado
  // saiam idênticos (a placa fica guardada porque o popup abre POR CIMA da ficha do veículo).
  document.getElementById('relMntGerar').onclick = () => { if (relMntPlaca) abrirRelAssinaModal(relMntPlaca, 'baixar'); };
  document.getElementById('relMntVer').onclick = () => { if (relMntPlaca) abrirRelAssinaModal(relMntPlaca, 'ver'); };
})();

// ----- Sub-abas (Eventos | Dashboards | Alertas | Notas fiscais | Odômetro | Relatórios) -----
function trocarSubMnt(sub) {
  const alvo = document.querySelector(`#manutencaoSubtabs .subtab[data-sub="${sub}"]`);
  if (!alvo) return;
  subMntAtiva = sub;
  document.querySelectorAll('#manutencaoSubtabs .subtab').forEach(x => x.classList.remove('active'));
  document.querySelectorAll('#manutencao .subview').forEach(x => x.classList.remove('active'));
  alvo.classList.add('active');
  document.getElementById(sub).classList.add('active');
  // Relatórios têm fonte própria (agregados do servidor) → busca sempre ao entrar na sub-aba.
  if (sub === 'mnt-relatorios') { atualizarRelatoriosMnt(); return; }
  renderManutencao(); // gráficos/tabelas só dimensionam com o container visível
}
document.querySelectorAll('#manutencaoSubtabs .subtab').forEach(b => b.onclick = () => { if (!b.classList.contains('active')) trocarSubMnt(b.dataset.sub); });

// ----- Filtros -----
function filtrarMnt() { mntPagina = 1; renderManutencao(); }
document.getElementById('buscaMnt').addEventListener('input', debounce(filtrarMnt));
[['fmntPlaca', 'Placa'], ['fmntPeriodo', 'Período'], ['fmntCentro', 'Centro de custo'], ['fmntTipo', 'Tipo'], ['fmntMontadora', 'Montadora']]
  .forEach(([fid, rot]) => criarMultiSelect(fid, rot, filtrarMnt));
document.getElementById('btnLimparMnt').onclick = () => {
  document.getElementById('buscaMnt').value = '';
  ['fmntPlaca', 'fmntPeriodo', 'fmntCentro', 'fmntTipo', 'fmntMontadora'].forEach(fid => MSEL[fid] && MSEL[fid].limpar());
  filtrarMnt();
};
document.getElementById('mntPorPagina').onchange = () => { mntPagina = 1; renderEventosMnt(); };
document.getElementById('mntPagPrev').onclick = () => { if (mntPagina > 1) { mntPagina--; renderEventosMnt(); } };
_pagCtl.mnt = { irPara: (n) => { mntPagina = n; renderEventosMnt(); } };
document.getElementById('mntPagNext').onclick = () => { mntPagina++; renderEventosMnt(); };
// Barra de seleção: exportar selecionados / limpar seleção
document.getElementById('selBarMntLimpar').onclick = () => { SELECAO_MNT.clear(); renderEventosMnt(); };
document.getElementById('selBarMntExportar').onclick = () => {
  const ids = [...SELECAO_MNT];
  if (!ids.length) return;
  window.location = '/api/manutencao/exportar?ids=' + encodeURIComponent(ids.join(','));
};
document.getElementById('selBarMntExcluir').onclick = () => { if (SELECAO_MNT.size) excluirManutencaoLote([...SELECAO_MNT]); };
async function excluirManutencaoLote(ids) {
  if (!ids.length) return;
  if (!(await confirmar(`Excluir ${ids.length} evento(s) de manutenção? Esta ação não pode ser desfeita.`, { perigo: true, okTexto: 'Excluir' }))) return;
  const r = await fetch('/api/manutencao/lote-excluir', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ids }) });
  if (!r.ok) { const j = await r.json().catch(() => ({})); return toast(j.erro || 'Erro ao excluir.', 'erro'); }
  const j = await r.json().catch(() => ({}));
  ids.forEach(id => SELECAO_MNT.delete(id));
  await carregarManutencao();
  toast(`${j.excluidos || 0} evento(s) excluído(s).`, 'ok');
}

// Clique na placa (tabela ou alertas) = filtra por aquela placa. Editar/excluir evento.
document.getElementById('manutencao').addEventListener('click', (e) => {
  const pb = e.target.closest('.placa-btn');
  if (pb && pb.closest('#mnt-odometro')) return; // no Odômetro a placa só abre a linha do tempo
  if (pb) {
    document.getElementById('buscaMnt').value = pb.dataset.placa; // filtra rápido por essa placa
    trocarSubMnt('mnt-eventos'); filtrarMnt(); return;
  }
  const ed = e.target.closest('.edit-mnt'); if (ed) { abrirMntModal(ed.dataset.id); return; }
  const del = e.target.closest('.del-mnt'); if (del) { excluirMnt(del.dataset.id); return; }
  const it = e.target.closest('.editavel-item'); if (it) { abrirMntModal(it.dataset.id); return; } // clicar no item abre a edição (foca o campo)
  const pTrig = e.target.closest('.pill-trigger'); if (pTrig) return; // já tratado (onclick próprio)
  // Toque/clique na área livre da linha (tabela de eventos) seleciona/deseleciona.
  if (e.target.closest('button, input, select, textarea, a, .pill-select')) return;
  const tr = e.target.closest('#corpoMnt tr'); if (!tr || !tr.dataset.id) return;
  const id = tr.dataset.id;
  if (SELECAO_MNT.has(id)) SELECAO_MNT.delete(id); else SELECAO_MNT.add(id);
  tr.classList.toggle('sel-on', SELECAO_MNT.has(id));
  atualizarBarraSelMnt();
});

// ----- Modal de evento (add/editar) -----
const formMnt = document.getElementById('formMnt');
let mntFornecedorCarga = 0;
// USO: abrirMntModal('MNT123') abre o evento com o fornecedor salvo, inclusive inativo;
// abrirMntModal(null) permite escolher um fornecedor ativo sem visitar a aba Fornecedores.
async function abrirMntModal(id) {
  const carga = ++mntFornecedorCarga;
  editandoMntId = id || null;
  formMnt.reset();
  const evento = MANUTENCAO.find(x => x.id === id);
  const fornecedorSel = formMnt.elements.fornecedorId;
  const fornecedorBtn = fornecedorSel.closest('.cs')?.querySelector('.cs-btn');
  const ajuda = document.getElementById('mntFornecedorAjuda');
  fornecedorSel.innerHTML = '<option value="">Sem fornecedor</option>' + (evento?.fornecedorId
    ? `<option value="${esc(evento.fornecedorId)}">${esc(evento.fornecedor || 'Fornecedor vinculado')}</option>` : '');
  fornecedorSel.value = evento?.fornecedorId || '';
  fornecedorSel.disabled = true;
  if (fornecedorBtn) fornecedorBtn.disabled = true;
  ajuda.textContent = 'Carregando fornecedores…';
  document.getElementById('mntTitulo').textContent = id ? 'Editar evento' : 'Novo evento';
  if (id) {
    const e = MANUTENCAO.find(x => x.id === id);
    // namedItem() em vez de elements[campo]: o campo "item" colide com o método nativo
    // HTMLFormControlsCollection.prototype.item — elements['item'] retornava a FUNÇÃO (não o
    // <input>), então o valor nunca era preenchido e o campo "Item" abria VAZIO na edição.
    if (e) for (const campo of Object.keys(e)) { const el = formMnt.elements.namedItem(campo); if (el && 'value' in el) el.value = e[campo] ?? ''; }
  }
  document.getElementById('mntModal').hidden = false;
  formMnt.elements['placa'].focus();
  try {
    const r = await fetch('/api/manutencao/fornecedores', { cache: 'no-store' });
    if (!r.ok) throw new Error('Não foi possível carregar os fornecedores.');
    const fornecedores = await r.json();
    if (carga !== mntFornecedorCarga) return;
    const opcoes = fornecedores.filter(f => f.ativo !== false || f.id === evento?.fornecedorId)
      .sort((a, b) => a.nome.localeCompare(b.nome, 'pt-BR'));
    fornecedorSel.innerHTML = '<option value="">Sem fornecedor</option>' + opcoes.map(f =>
      `<option value="${esc(f.id)}">${esc(f.nome)}${f.ativo === false ? ' (inativo)' : ''}</option>`).join('');
    if (evento?.fornecedorId && !opcoes.some(f => f.id === evento.fornecedorId)) {
      fornecedorSel.add(new Option(`${evento.fornecedor || 'Fornecedor vinculado'} (fora do cadastro)`, evento.fornecedorId));
    }
    fornecedorSel.value = evento?.fornecedorId || '';
    fornecedorSel.disabled = false;
    if (fornecedorBtn) fornecedorBtn.disabled = false;
    ajuda.textContent = 'Opcional. Escolha um fornecedor cadastrado na aba Fornecedores.';
  } catch (erro) {
    if (carga !== mntFornecedorCarga) return;
    ajuda.textContent = 'Não foi possível carregar os fornecedores. Reabra o evento para tentar novamente. O vínculo atual será mantido ao salvar.';
  }
}
function fecharMntModal() { mntFornecedorCarga++; document.getElementById('mntModal').hidden = true; }
document.getElementById('btnAddMnt').onclick = () => abrirMntModal(null);
document.getElementById('fecharMnt').onclick = fecharMntModal;
document.getElementById('cancelarMnt').onclick = fecharMntModal;
fecharAoClicarNoFundo('mntModal', fecharMntModal);
// Ao escolher a placa, puxa os dados do veículo (frota) e do último evento daquela placa.
// Só preenche campo VAZIO — nunca sobrescreve o que o usuário já digitou/editou.
formMnt.elements['placa'].addEventListener('change', () => {
  const chave = (formMnt.elements['placa'].value || '').replace(/[^A-Za-z0-9]/g, '').toUpperCase();
  if (!chave) return;
  const soVazio = (nome, valor) => {
    const el = formMnt.elements.namedItem(nome); // namedItem: "item" colide com o método nativo
    if (el && 'value' in el && !el.value.trim() && valor != null && String(valor).trim() !== '') el.value = valor;
  };
  const v = VEICULOS.find(x => (x.placa || '').replace(/[^A-Za-z0-9]/g, '').toUpperCase() === chave);
  if (v) {
    soVazio('modelo', v.modelo);
    soVazio('ano', v.anoMod || v.anoFab || '');
    soVazio('centroCusto', v.centroCusto);
  }
  // Montadora/motorista não existem na frota: herda do evento mais recente da mesma placa.
  const ult = MANUTENCAO.filter(e => (e.placa || '').replace(/[^A-Za-z0-9]/g, '').toUpperCase() === chave)
    .sort((a, b) => (b.ts || 0) - (a.ts || 0))[0];
  if (ult) {
    soVazio('montadora', ult.montadora);
    soVazio('motorista', ult.motorista === '—' ? '' : ult.motorista);
    soVazio('modelo', ult.modelo);
    soVazio('ano', ult.ano);
    soVazio('centroCusto', ult.centroCusto);
  }
});
formMnt.addEventListener('submit', async (e) => {
  e.preventDefault();
  const dados = {};
  for (const el of formMnt.elements) if (el.name) dados[el.name] = el.value;
  // Falha/carga pendente do catálogo não pode apagar o vínculo ao editar os demais campos.
  if (formMnt.elements.fornecedorId.disabled) delete dados.fornecedorId;
  if (dados.data) dados.data = normData(dados.data); // grava sempre em dd/mm/aaaa (ordenação consistente)
  if (editandoMntId) dados.id = editandoMntId;
  const url = editandoMntId ? '/api/manutencao/' + encodeURIComponent(editandoMntId) : '/api/manutencao';
  const r = await fetch(url, { method: editandoMntId ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(dados) });
  if (!r.ok) { const j = await r.json().catch(() => ({})); return toast(j.erro || 'Erro ao salvar.', 'erro'); }
  fecharMntModal();
  await carregarManutencao();
  toast(editandoMntId ? 'Evento atualizado!' : 'Evento adicionado!', 'ok');
});
async function excluirMnt(id) {
  const e = MANUTENCAO.find(x => x.id === id);
  if (!(await confirmar(`Excluir este evento de manutenção${e ? ` (${esc(e.placa)})` : ''}?`, { perigo: true, okTexto: 'Excluir' }))) return;
  const r = await fetch('/api/manutencao/' + encodeURIComponent(id), { method: 'DELETE' });
  if (!r.ok) { const j = await r.json().catch(() => ({})); return toast(j.erro || 'Erro ao excluir.', 'erro'); }
  await carregarManutencao();
  toast('Evento excluído.', 'ok');
}

// ----- Importar / exportar -----
// Botão "Excel" da Manutenção: abre um modal pra escolher entre a planilha ORIGINAL
// (o arquivo cru que o usuário subiu) e EXPORTAR (os dados atuais já editados no sistema).
document.getElementById('btnExportMnt').onclick = () => abrirEscolhaExcelMnt();
function abrirEscolhaExcelMnt() {
  const ov = document.createElement('div');
  ov.className = 'modal-overlay';
  ov.innerHTML = `
    <div class="modal" style="max-width: 460px;">
      <div class="modal-head">
        <h2>Baixar Excel da Manutenção</h2>
        <button class="icon-btn" data-fechar aria-label="Fechar">✕</button>
      </div>
      <div class="modal-body" style="display:flex; flex-direction:column; gap:10px;">
        <button class="btn btn-ghost" data-opc="original" style="text-align:left; display:flex; flex-direction:column; align-items:flex-start; gap:2px; height:auto; padding:12px 14px; white-space:normal;">
          <strong>📄 Excel Original</strong>
          <span style="font-size:.85em; opacity:.75;">A planilha que você subiu na última atualização (terça/quinta), exatamente como enviou; sem nenhuma edição.</span>
        </button>
        <button class="btn btn-ghost" data-opc="exportar" style="text-align:left; display:flex; flex-direction:column; align-items:flex-start; gap:2px; height:auto; padding:12px 14px; white-space:normal;">
          <strong>⬇ Exportar (atual)</strong>
          <span style="font-size:.85em; opacity:.75;">Os dados de agora no sistema; já com as edições e exclusões feitas aqui; gerados na hora.</span>
        </button>
      </div>
    </div>`;
  document.body.appendChild(ov);
  const fechar = () => ov.remove();
  ov.querySelector('[data-fechar]').onclick = fechar;
  ov.addEventListener('click', (e) => { if (e.target === ov) fechar(); });
  ov.querySelector('[data-opc="exportar"]').onclick = () => { fechar(); window.location = '/api/manutencao/exportar'; };
  ov.querySelector('[data-opc="original"]').onclick = async () => {
    fechar();
    try {
      const r = await fetch('/api/manutencao/original', { cache: 'no-store' });
      if (!r.ok) { const j = await r.json().catch(() => ({})); return toast(j.erro || 'Nenhuma planilha original disponível.', 'erro'); }
      const blob = await r.blob();
      const cd = r.headers.get('Content-Disposition') || '';
      const mm = /filename="([^"]+)"/.exec(cd);
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = mm ? mm[1] : 'manutencao-original.xlsx';
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(a.href), 4000);
    } catch (e) { toast('Falha ao baixar a planilha original.', 'erro'); }
  };
}
document.getElementById('btnImportMnt').onclick = () => document.getElementById('inputImportMnt').click();
document.getElementById('inputImportMnt').onchange = async (e) => {
  const file = e.target.files[0]; e.target.value = '';
  if (!file) return;
  if (!(await confirmar('Importar o Relatório de Manutenção SUBSTITUI todos os eventos atuais (um backup é feito antes). Continuar?', { perigo: true, okTexto: 'Importar' }))) return;
  const fd = new FormData(); fd.append('arquivo', file);
  toast('Importando planilha...', '');
  try {
    const r = await fetch('/api/manutencao/importar', { method: 'POST', body: fd });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) { toast(j.erro || 'Erro ao importar.', 'erro'); return; }
    await carregarManutencao();
    toast(`Importado: ${j.eventos} eventos · ${j.veiculos} veículos${j.motoristas ? ` · ${j.motoristas} motoristas` : ''}.`, 'ok');
  } catch (err) {
    toast('Falha de conexão ao importar. Tente novamente.', 'erro');
  }
};

/* ============================================================
   BACKUPS (pontos de restauração); modal compartilhado por
   Manutenção e Rastreadores. Linha do tempo com o que mudou
   entre um ponto e outro (novos / removidos).
   ============================================================ */
const BACKUP_CFG = {
  manutencao: { titulo: 'Manutenção', recarregar: () => carregarManutencao() },
  rastreadores: { titulo: 'Rastreadores', recarregar: () => carregarRastreadores() },
  abastecimento: { titulo: 'Abastecimento', recarregar: () => carregarAbastecimento() },
};
let backupsTipo = null;
function fecharBackupsModal() { document.getElementById('backupsModal').hidden = true; }
async function abrirBackups(tipo) {
  backupsTipo = tipo;
  const cfg = BACKUP_CFG[tipo];
  document.getElementById('backupsTitulo').textContent = `Pontos de restauração · ${cfg.titulo}`;
  document.getElementById('backupsModal').hidden = false;
  const lista = document.getElementById('backupsLista');
  const vazio = document.getElementById('backupsVazio');
  vazio.hidden = true;
  lista.innerHTML = '<li class="bak2-load">Carregando…</li>';
  try {
    const r = await fetch(`/api/${tipo}/backups`, { cache: 'no-store' });
    if (!r.ok) { lista.innerHTML = ''; vazio.hidden = false; return; }
    const baks = await r.json();
    if (!baks.length) { lista.innerHTML = ''; vazio.hidden = false; return; }
    lista.innerHTML = baks.map(backupItemHTML).join('');
  } catch (e) { lista.innerHTML = ''; vazio.hidden = false; }
}
function backupItemHTML(b) {
  const d = new Date(b.ts);
  const quando = d.toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', year: '2-digit', hour: '2-digit', minute: '2-digit' });
  let tags;
  if (b.primeiro) tags = `<span class="bak-tag base">1º ponto · ${b.total} itens</span>`;
  else if (!b.novos && !b.removidos) tags = `<span class="bak-tag igual">sem mudanças</span>`;
  else {
    const p = [];
    if (b.novos) p.push(`<span class="bak-tag add">+${b.novos} ${b.novos > 1 ? 'novos' : 'novo'}</span>`);
    if (b.removidos) p.push(`<span class="bak-tag rem">−${b.removidos} ${b.removidos > 1 ? 'removidos' : 'removido'}</span>`);
    tags = p.join(' ');
  }
  return `<li class="bak2-item">
    <span class="bak2-dot${b.primeiro ? ' base' : ''}"></span>
    <div class="bak2-card">
      <div class="bak2-top">
        <span class="bak2-quando">${esc(quando)}</span>
        <span class="bak2-acoes">
          <button class="icon-btn bak-baixar" data-ts="${b.ts}" title="Baixar uma cópia (.json)">⬇</button>
          <button class="icon-btn bak-restaurar" data-ts="${b.ts}" title="Restaurar este ponto">↩</button>
        </span>
      </div>
      <div class="bak2-tags">${tags}<span class="bak2-total">${b.total} itens no total</span></div>
      ${b.motivo ? `<div class="bak2-motivo">${esc(b.motivo)}</div>` : ''}
    </div>
  </li>`;
}
document.getElementById('fecharBackups').onclick = fecharBackupsModal;
fecharAoClicarNoFundo('backupsModal', fecharBackupsModal);
document.getElementById('btnBackupsMnt').onclick = () => abrirBackups('manutencao');
{ const b = document.getElementById('btnBackupsRast'); if (b) b.onclick = () => abrirBackups('rastreadores'); }
document.getElementById('backupsLista').addEventListener('click', async (e) => {
  const tipo = backupsTipo;
  const baixar = e.target.closest('.bak-baixar');
  if (baixar) { window.location = `/api/${tipo}/backups/${baixar.dataset.ts}/baixar`; return; }
  const rest = e.target.closest('.bak-restaurar');
  if (rest) {
    if (!(await confirmar('Restaurar este ponto vai SUBSTITUIR os dados atuais (o estado de agora também é salvo antes). Continuar?', { perigo: true, okTexto: 'Restaurar' }))) return;
    const r = await fetch(`/api/${tipo}/backups/${rest.dataset.ts}/restaurar`, { method: 'POST' });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) { toast(j.erro || 'Erro ao restaurar.', 'erro'); return; }
    fecharBackupsModal();
    await BACKUP_CFG[tipo].recarregar();
    toast('Ponto restaurado com sucesso.', 'ok');
  }
});

/* ===================== MÓDULO BACKUP (UI): gerar / restaurar / histórico / config ===================== */
const BackupUI = (() => {
  const $ = (id) => document.getElementById(id);
  let arquivo = null;
  function abrir() { const m = $('backupModal'); if (!m) return; m.hidden = false; trocarTab('gerar'); carregarStatus(); carregarHistorico(); carregarConfig(); }
  function fechar() { $('backupModal').hidden = true; }
  function trocarTab(nome) {
    document.querySelectorAll('#backupModal .bkp-tab').forEach((t) => t.classList.toggle('is-active', t.dataset.tab === nome));
    document.querySelectorAll('#backupModal .bkp-panel').forEach((p) => { p.hidden = p.dataset.panel !== nome; });
    if (nome === 'historico') carregarHistorico();
    if (nome === 'config') carregarConfig();
  }
  // ----- Gerar -----
  async function gerar() {
    const grupo = (document.querySelector('input[name=bkpGrupo]:checked') || {}).value || 'completo';
    const incluirAnexos = $('bkpAnexos').checked;
    const btn = $('bkpGerarBtn'); btn.disabled = true; const t = btn.textContent; btn.textContent = 'Gerando…';
    try {
      const r = await fetch('/api/backup/gerar', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ grupos: [grupo], incluirAnexos }) });
      if (!r.ok) { let j = {}; try { j = await r.json(); } catch (_) {} throw new Error(j.erro || 'Falha ao gerar backup.'); }
      const blob = await r.blob();
      const cd = r.headers.get('Content-Disposition') || ''; const mm = cd.match(/filename="([^"]+)"/);
      const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = mm ? mm[1] : 'gestao-rm-backup.zip';
      document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(a.href), 10000);
      toast('Backup gerado e baixado.', 'ok'); carregarStatus(); carregarHistorico();
    } catch (e) { toast(e.message, 'erro'); } finally { btn.disabled = false; btn.textContent = t; }
  }
  // ----- Restaurar -----
  function escolherArquivo(e) {
    arquivo = (e.target.files && e.target.files[0]) || null;
    $('bkpFileNome').textContent = arquivo ? arquivo.name : 'Escolher arquivo .zip…';
    $('bkpValidarBtn').disabled = !arquivo;
    ['bkpValidacao', 'bkpRestauraOpcoes', 'bkpDryResultado', 'bkpAplicarBox'].forEach((id) => { $(id).hidden = true; });
  }
  async function validar() {
    if (!arquivo) return;
    const fd = new FormData(); fd.append('arquivo', arquivo);
    const btn = $('bkpValidarBtn'); btn.disabled = true; const t = btn.textContent; btn.textContent = 'Validando…';
    try {
      const r = await fetch('/api/backup/validar', { method: 'POST', body: fd });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.erro || 'Backup inválido.');
      const ok = j.integridade && j.integridade.ok;
      $('bkpValidacao').hidden = false; $('bkpValidacao').innerHTML = htmlValidacao(j);
      $('bkpRestauraOpcoes').hidden = !ok;
      if (!ok) toast('Integridade do backup falhou · restauração bloqueada.', 'erro');
    } catch (e) {
      $('bkpValidacao').hidden = false; $('bkpValidacao').innerHTML = `<p class="bkp-erro">${esc(e.message)}</p>`;
      $('bkpRestauraOpcoes').hidden = true; toast(e.message, 'erro');
    } finally { btn.disabled = false; btn.textContent = t; }
  }
  function htmlValidacao(j) {
    const m = j.manifest || {}; const ig = j.integridade || {};
    const linhas = (m.modulos || []).map((x) => `<tr><td>${esc(x.label || x.modulo)}</td><td class="num">${x.registros}</td><td>${x.restauravel ? '✓' : '<span class="bkp-mut">auditoria</span>'}</td></tr>`).join('');
    return `<div class="bkp-card ${ig.ok ? 'ok' : 'erro'}">
      <p><b>${ig.ok ? '✓ Integridade conferida' : '✗ Integridade falhou'}</b> · v${esc(m.versao || '?')} · ${esc(m.ambiente || '')} · ${esc(m.geradoEm || '')}</p>
      ${ig.problemas && ig.problemas.length ? `<p class="bkp-erro">${ig.problemas.length} arquivo(s) com hash divergente/ausente.</p>` : ''}
      ${m.completo === false ? `<p class="bkp-erro"><b>⚠ BACKUP INCOMPLETO</b> — ${m.falhas || 0} anexo(s) não entraram na origem. Os dados estão aqui, os arquivos não: este .zip não restaura fotos e documentos por inteiro.</p>` : ''}
      <table class="bkp-tab-mod"><thead><tr><th>Área</th><th class="num">Registros</th><th>Restaurável</th></tr></thead><tbody>${linhas}</tbody></table>
      <p class="bkp-mut">Anexos no backup: ${m.anexos || 0}${m.esperados ? ` de ${m.esperados}` : ''}</p></div>`;
  }
  async function restaurar(dryRun) {
    if (!arquivo) return;
    const modo = (document.querySelector('input[name=bkpModo]:checked') || {}).value || 'mesclar';
    const fd = new FormData(); fd.append('arquivo', arquivo); fd.append('modo', modo);
    if (!dryRun) { fd.append('aplicar', '1'); fd.append('frase', $('bkpFrase').value.trim()); }
    const btn = dryRun ? $('bkpDryBtn') : $('bkpAplicarBtn'); btn.disabled = true; const t = btn.textContent; btn.textContent = dryRun ? 'Pré-visualizando…' : 'Aplicando…';
    try {
      const r = await fetch('/api/backup/restaurar', { method: 'POST', body: fd });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.erro || 'Falha na restauração.');
      $('bkpDryResultado').hidden = false; $('bkpDryResultado').innerHTML = htmlDiff(j);
      if (dryRun) { $('bkpAplicarBox').hidden = false; sincronizarAplicar(); }
      else { toast('Restauração aplicada com sucesso.', 'ok'); $('bkpAplicarBox').hidden = true; $('bkpFrase').value = ''; carregarStatus(); carregarHistorico(); setTimeout(() => location.reload(), 1600); }
    } catch (e) { toast(e.message, 'erro'); } finally { btn.disabled = false; btn.textContent = t; sincronizarAplicar(); }
  }
  function htmlDiff(j) {
    const sub = j.modo === 'substituir';
    const linhas = (j.modulos || []).map((m) => {
      if (m.tipo === 'objeto') return `<tr><td>${esc(m.label || m.modulo)}</td><td colspan="4" class="bkp-mut">objeto; ${m.itensBackup} item(ns) no backup</td></tr>`;
      return `<tr><td>${esc(m.label || m.modulo)}</td><td class="num add">+${m.criados || 0}</td><td class="num upd">~${m.atualizados || 0}</td><td class="num">${m.iguais || 0}</td><td class="num rem">${sub ? '−' + (m.removidos || 0) : '·'}</td></tr>`;
    }).join('');
    const ign = (j.ignorados || []).map((i) => esc(i.modulo)).join(', ');
    const anex = j.anexos ? (j.dryRun ? `${j.anexos.aRestaurar || 0} a restaurar, ${j.anexos.ausentes || 0} ausentes` : `${j.anexos.restaurados || 0} restaurados, ${j.anexos.pendentes || 0} pendentes`) : '—';
    return `<div class="bkp-card">
      <p><b>${j.dryRun ? 'Prévia; nada foi gravado' : 'Restauração aplicada'}</b> · modo <b>${esc(j.modo)}</b></p>
      <table class="bkp-tab-mod"><thead><tr><th>Área</th><th class="num">Novos</th><th class="num">Atualiz.</th><th class="num">Iguais</th><th class="num">Removidos</th></tr></thead><tbody>${linhas}</tbody></table>
      <p class="bkp-mut">Anexos: ${anex}${ign ? ` · Não restaurados: ${ign}` : ''}</p>
      ${(j.avisos || []).map((a) => `<p class="bkp-aviso">⚠ ${esc(a)}</p>`).join('')}</div>`;
  }
  function sincronizarAplicar() { const ok = $('bkpFrase') && $('bkpFrase').value.trim() === 'RESTAURAR BACKUP'; if ($('bkpAplicarBtn')) $('bkpAplicarBtn').disabled = !ok; }
  // ----- Histórico -----
  async function carregarHistorico() {
    try {
      const itens = await (await fetch('/api/backup/historico', { cache: 'no-store' })).json();
      const cont = $('bkpHistLista'); const vazio = $('bkpHistVazio');
      if (!Array.isArray(itens) || !itens.length) { cont.innerHTML = ''; vazio.hidden = false; return; }
      vazio.hidden = true;
      cont.innerHTML = itens.map((h) => {
        const d = new Date(h.ts).toLocaleString('pt-BR');
        const cls = h.status === 'sucesso' ? 'ok' : (h.status === 'erro' ? 'erro' : '');
        const tipo = h.tipo === 'restauração' ? `restauração (${esc(h.modo || '')})` : 'geração';
        return `<div class="bkp-hrow ${cls}"><div class="bkp-hmain"><b>${esc(tipo)}</b> · ${esc((h.grupos || []).join(', '))}<span class="bkp-mut"> · ${d}</span></div>
          <div class="bkp-hmeta">${esc(h.usuario || '—')} · ${h.registros || 0} reg · ${h.contemAnexos ? 'com anexos' : 'sem anexos'} · <span class="bkp-badge ${cls}">${esc(h.status)}</span></div>
          ${h.erro ? `<div class="bkp-erro">${esc(h.erro)}</div>` : ''}</div>`;
      }).join('');
    } catch (e) { /* silencioso */ }
  }
  // ----- Status (aba Gerar) -----
  async function carregarStatus() {
    try {
      const s = await (await fetch('/api/backup/status', { cache: 'no-store' })).json();
      const box = $('bkpStatusBox'); if (!box) return; const u = s.ultimo;
      const ult = u ? `Último backup: <b>${new Date(u.ts).toLocaleString('pt-BR')}</b> por ${esc(u.usuario || '—')}` : 'Nenhum backup gerado ainda.';
      box.innerHTML = `<p class="bkp-mut">${ult}</p>${(s.alertas || []).map((a) => `<p class="bkp-aviso ${a.nivel}">${esc(a.msg)}</p>`).join('')}`;
    } catch (e) {}
  }
  // ----- Configurações -----
  async function carregarConfig() {
    try {
      const c = await (await fetch('/api/backup/config', { cache: 'no-store' })).json();
      $('cfgRetencao').value = c.retencaoDias; $('cfgTamanho').value = c.tamanhoMaxMB; $('cfgDesatualizado').value = c.diasDesatualizado;
      $('cfgAnexos').checked = c.incluirAnexosPadrao !== false; $('cfgLogs').checked = c.incluirLogsPadrao !== false;
    } catch (e) {}
  }
  async function salvarConfig() {
    const body = { retencaoDias: +$('cfgRetencao').value, tamanhoMaxMB: +$('cfgTamanho').value, diasDesatualizado: +$('cfgDesatualizado').value, incluirAnexosPadrao: $('cfgAnexos').checked, incluirLogsPadrao: $('cfgLogs').checked };
    const btn = $('bkpCfgSalvar'); btn.disabled = true;
    try { const r = await fetch('/api/backup/config', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }); if (!r.ok) throw 0; toast('Configurações salvas.', 'ok'); atualizarCard(); }
    catch (e) { toast('Erro ao salvar configurações.', 'erro'); } finally { btn.disabled = false; }
  }
  // ----- Card de status no Início -----
  async function atualizarCard() {
    const card = $('inicioBackupCard'); if (!card) return;
    if (PREVIEW_COMUM) { card.hidden = true; return; } // "ver como comum": some o card (é só de admin)
    try {
      const r = await fetch('/api/backup/status', { cache: 'no-store' });
      if (!r.ok) { card.hidden = true; return; } // sem permissão admin → não mostra
      const s = await r.json(); card.hidden = false;
      const u = s.ultimo; const grave = (s.alertas || []).some((a) => a.nivel === 'erro' || a.nivel === 'alerta');
      card.classList.toggle('ds-alert-warning', grave);
      const elQ = card.querySelector('.ib-quando'); if (elQ) elQ.textContent = u ? new Date(u.ts).toLocaleDateString('pt-BR') : 'nunca';
      const al = (s.alertas || [])[0]; const elA = card.querySelector('.ib-alerta'); if (elA) elA.textContent = al ? al.msg : 'Backup em dia.';
    } catch (e) { card.hidden = true; }
  }
  function init() {
    const btn = $('btnBackup'); if (btn) btn.onclick = abrir;
    if ($('inicioBackupCard')) $('inicioBackupCard').onclick = abrir;
    if ($('fecharBackup')) $('fecharBackup').onclick = fechar;
    if (typeof fecharAoClicarNoFundo === 'function') fecharAoClicarNoFundo('backupModal', fechar);
    document.querySelectorAll('#backupModal .bkp-tab').forEach((t) => { t.onclick = () => trocarTab(t.dataset.tab); });
    if ($('bkpGerarBtn')) $('bkpGerarBtn').onclick = gerar;
    if ($('bkpFile')) $('bkpFile').onchange = escolherArquivo;
    if ($('bkpValidarBtn')) $('bkpValidarBtn').onclick = validar;
    if ($('bkpDryBtn')) $('bkpDryBtn').onclick = () => restaurar(true);
    if ($('bkpAplicarBtn')) $('bkpAplicarBtn').onclick = () => restaurar(false);
    if ($('bkpFrase')) $('bkpFrase').oninput = sincronizarAplicar;
    if ($('bkpCfgSalvar')) $('bkpCfgSalvar').onclick = salvarConfig;
  }
  init();
  return { abrir, atualizarCard };
})();

/* ============================================================
   ABASTECIMENTO (combustível); espelha a Manutenção: base bruta
   de transações (importada da Auditoria de Frota), com 4 sub-abas:
   Por veículo (km + motorista + métricas), Transações (editável),
   Dashboards e Alertas. Tudo recalculado no cliente sobre a lista.
   ============================================================ */
let ABASTECIMENTO = [];
let editandoAbtId = null;
let abtPagina = 1;
let subAbtAtiva = 'abt-veiculo';
let ordemAbt = { campo: 'dataHora', dir: -1 };       // tabela de transações
let ordemAbtVeic = { campo: 'gasto', dir: -1 };       // tabela por veículo
let abtVeicBusca = '';
const SELECAO_ABT = new Set();
const CORES_ABT = ['#1b56ff', '#dc2626', '#16a34a', '#b45309', '#0369a1', '#7c3aed', '#0ea5e9', '#db2777', '#65a30d', '#475569'];

const numAbt = (x) => Number(x) || 0;
const fmtLitros = (n) => numAbt(n).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const fmtKm = (n) => Math.round(numAbt(n)).toLocaleString('pt-BR');
const fmtKmL = (n) => numAbt(n).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const fmtRSL = (n) => 'R$ ' + numAbt(n).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 3 });
// "dd/mm/aaaa hh:mm" → número ordenável aaaammddhhmm (0 se ilegível).
function dataOrdAbt(dh) {
  const m = String(dh || '').match(/(\d{2})\/(\d{2})\/(\d{4})(?:[ T](\d{2}):(\d{2}))?/);
  return m ? Number(m[3] + m[2] + m[1] + (m[4] || '00') + (m[5] || '00')) : 0;
}
// Os lançamentos financeiros (Conta Azul) NÃO trazem litros/km/L/preço/alerta. Quando é esse o caso,
// escondemos os cards/colunas/gráficos de combustível e focamos no gasto. Se um dia entrar uma
// planilha com litros (formato antigo "Auditoria"), tudo volta a aparecer sozinho.
function abtTemFuel(lista) {
  return (lista || ABASTECIMENTO).some(t => numAbt(t.litros) > 0 || numAbt(t.kmL) > 0 || numAbt(t.kmRod) > 0 || numAbt(t.precoLitro) > 0);
}

const DIAS_SEM_ABASTECIMENTO_ABT = 30;
const placaAbt = (p) => String(p || '').trim().toUpperCase();
function dataObjAbt(dh) {
  const m = String(dh || '').match(/(\d{2})\/(\d{2})\/(\d{4})/);
  if (!m) return null;
  const d = new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1]));
  return Number.isNaN(d.getTime()) ? null : d;
}
function dataKeyAbt(dh) {
  const m = String(dh || '').match(/(\d{2})\/(\d{2})\/(\d{4})/);
  return m ? `${m[3]}-${m[2]}-${m[1]}` : String(dh || '').trim();
}
function mesAnteriorAbt(chave) {
  const m = String(chave || '').match(/^(\d{4})-(\d{2})$/);
  if (!m) return '';
  const d = new Date(Number(m[1]), Number(m[2]) - 2, 1);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}
function medianaAbt(vals) {
  const arr = vals.map(Number).filter(n => Number.isFinite(n) && n > 0).sort((a, b) => a - b);
  if (!arr.length) return 0;
  const m = arr.length >> 1;
  return arr.length % 2 ? arr[m] : (arr[m - 1] + arr[m]) / 2;
}
function veiculoAbt(placa) {
  const p = placaAbt(placa);
  return VEICULOS.find(v => placaAbt(v.placa) === p) || null;
}
function modeloAbt(t) {
  const v = veiculoAbt(t.placa);
  return t.modelo || (v && [v.modelo, v.versao].filter(Boolean).join(' ')) || '';
}
function anoVeiculoAbt(t) {
  const v = veiculoAbt(t.placa);
  return t.ano || (v && (v.anoMod || v.anoFab || v.ano)) || '';
}
function capacidadeTanqueAbt(t) {
  const v = veiculoAbt(t.placa);
  const tanque = numAbt(t.tanque || (v && v.tanque));
  if (tanque > 0) return tanque;
  const fam = familiaModelo(modeloAbt(t)).toUpperCase();
  if (/15\.?190|F4000|DAILY/.test(fam)) return 100;
  if (/L200|HILUX|RANGER|S10|TORO/.test(fam)) return 80;
  if (/SAVEIRO/.test(fam)) return 55;
  return 60;
}
function precoLitroAbt(t) {
  const p = numAbt(t.precoLitro);
  if (p > 0) return p;
  const v = numAbt(t.valor), l = numAbt(t.litros);
  return v > 0 && l > 0 ? v / l : 0;
}
function assinaturaDupAbt(t) {
  return `${dataKeyAbt(t.dataHora)}|${placaAbt(t.placa)}|${numAbt(t.valor).toFixed(2)}`;
}
function contextoAlertasAbt(base = ABASTECIMENTO) {
  const kmlPorPlaca = new Map();
  const precoPorComb = new Map();
  const dupCount = new Map();
  const porPlaca = new Map();
  const lastByPlaca = new Map();
  for (const t of base || []) {
    const p = placaAbt(t.placa);
    if (!p) continue;
    if (!porPlaca.has(p)) porPlaca.set(p, []);
    porPlaca.get(p).push(t);
    const d = dataObjAbt(t.dataHora);
    if (d && (!lastByPlaca.has(p) || d > lastByPlaca.get(p).data)) lastByPlaca.set(p, { data: d, dataHora: t.dataHora, t });
    const kml = numAbt(t.kmL);
    if (kml > 0) {
      if (!kmlPorPlaca.has(p)) kmlPorPlaca.set(p, []);
      kmlPorPlaca.get(p).push(kml);
    }
    const preco = precoLitroAbt(t);
    if (preco > 0) {
      const c = (t.combustivel || 'GERAL').toUpperCase();
      if (!precoPorComb.has(c)) precoPorComb.set(c, []);
      precoPorComb.get(c).push(preco);
      if (!precoPorComb.has('GERAL')) precoPorComb.set('GERAL', []);
      precoPorComb.get('GERAL').push(preco);
    }
    const dup = assinaturaDupAbt(t);
    dupCount.set(dup, (dupCount.get(dup) || 0) + 1);
  }
  const kmlMed = new Map([...kmlPorPlaca.entries()].map(([p, vals]) => [p, { med: medianaAbt(vals), n: vals.length }]));
  const precoMed = new Map([...precoPorComb.entries()].map(([c, vals]) => [c, { med: medianaAbt(vals), n: vals.length }]));
  const odometroMenor = new Set();
  for (const [, lista] of porPlaca) {
    let anterior = 0;
    lista.slice().sort((a, b) => dataOrdAbt(a.dataHora) - dataOrdAbt(b.dataHora)).forEach(t => {
      const od = numAbt(t.odometro);
      if (od > 0) {
        if (anterior > 0 && od < anterior) odometroMenor.add(t.id);
        anterior = Math.max(anterior, od);
      }
    });
  }
  return { kmlMed, precoMed, dupCount, odometroMenor, lastByPlaca };
}
function motivosAlertaTransacaoAbt(t, ctx = contextoAlertasAbt()) {
  const motivos = [];
  const add = (m) => { if (m && !motivos.includes(m)) motivos.push(m); };
  const baseMotivo = [t.motivos, t.statusKmL, t.statusPreco].filter(Boolean).join(' · ');
  if (t.alerta) add(baseMotivo || 'Alerta informado na planilha');
  else if (baseMotivo) add(baseMotivo);

  const p = placaAbt(t.placa);
  const kml = numAbt(t.kmL);
  const refKmL = ctx.kmlMed.get(p);
  if (kml > 0) {
    if (refKmL && refKmL.n >= 3 && refKmL.med > 0 && (kml < refKmL.med * 0.6 || kml > refKmL.med * 1.6)) {
      add(`Consumo fora do padrão (${fmtKmL(kml)} km/L vs mediana ${fmtKmL(refKmL.med)})`);
    } else if (kml < 3 || kml > 25) {
      add(`Consumo fora do padrão (${fmtKmL(kml)} km/L)`);
    }
  }

  if (ctx.odometroMenor.has(t.id)) add('Odômetro menor que o lançamento anterior');

  const preco = precoLitroAbt(t);
  const comb = (t.combustivel || 'GERAL').toUpperCase();
  const refPreco = ctx.precoMed.get(comb) || ctx.precoMed.get('GERAL');
  if (preco > 0 && refPreco && refPreco.n >= 3 && refPreco.med > 0 && preco > refPreco.med * 1.25 && preco - refPreco.med >= 0.5) {
    add(`Valor por litro acima da média (${fmtRSL(preco)} vs ${fmtRSL(refPreco.med)})`);
  }

  const litros = numAbt(t.litros);
  if (litros > 0) {
    const cap = capacidadeTanqueAbt(t);
    if (cap > 0 && litros > cap * 1.1) add(`Tanque acima da capacidade estimada (${fmtLitros(litros)} L vs ${fmtLitros(cap)} L)`);
  }

  if ((ctx.dupCount.get(assinaturaDupAbt(t)) || 0) > 1) add('Possível abastecimento duplicado (mesma data, placa e valor)');
  return motivos;
}
function alertasSemAbastecimentoAbt(ctx = contextoAlertasAbt()) {
  const hoje = new Date();
  hoje.setHours(0, 0, 0, 0);
  const fPl = getSel('fabtPlaca'), fCe = getSel('fabtCentro');
  const fMo = getSel('fabtMotorista'), fPo = getSel('fabtPosto'), fCo = getSel('fabtCombustivel'), fPe = getSel('fabtPeriodo');
  const q = (document.getElementById('buscaAbt').value || '').trim().toLowerCase();
  if (fMo.length || fPo.length || fCo.length || fPe.length) return [];
  return fleetAtiva().map(v => {
    const p = placaAbt(v.placa);
    if (!p) return null;
    if (fPl.length && !fPl.includes(p)) return null;
    if (fCe.length && !fCe.includes(v.centroCusto || '')) return null;
    if (q && !`${p} ${v.modelo || ''} ${v.versao || ''} ${v.centroCusto || ''} ${v.dono || ''}`.toLowerCase().includes(q)) return null;
    const ultimo = ctx.lastByPlaca.get(p);
    if (!ultimo) return { tipo: 'Veículo', placa: p, veiculo: v, dataHora: '', valor: 0, motivos: ['Veículo ativo sem abastecimento registrado'] };
    const dias = Math.floor((hoje - ultimo.data) / 86400000);
    if (dias > DIAS_SEM_ABASTECIMENTO_ABT) return { tipo: 'Veículo', placa: p, veiculo: v, dataHora: ultimo.dataHora, valor: 0, motivos: [`Sem abastecimento há ${dias} dias`] };
    return null;
  }).filter(Boolean);
}

// ----- Edição inline (pílulas Motorista/Centro de custo) — por TRANSAÇÃO (não cascateia) -----
const CONFIG_PILL_ABT = {
  centroCusto: {
    opcoesDinamicas: () => [...new Set([...ABASTECIMENTO.map(t => t.centroCusto).filter(Boolean), ...(CADASTROS.centrosCusto || [])])]
      .sort((a, b) => String(a).localeCompare(String(b), 'pt-BR')).map(x => ({ valor: x, classe: 'cc' })),
    classe: () => 'cc', rotulo: (s) => s || '—', busca: true, placeholder: 'Pesquisar centro de custo...',
  },
  motorista: {
    opcoesDinamicas: () => [...new Set([...ABASTECIMENTO.map(t => t.motorista).filter(Boolean), ...(CADASTROS.motoristas || [])])]
      .sort((a, b) => String(a).localeCompare(String(b), 'pt-BR')).map(x => ({ valor: x, classe: 'cc' })),
    classe: () => 'cc', rotulo: (s) => s || '—', editavel: true, busca: true,
    placeholder: 'Pesquisar motorista...', placeholderEdit: 'Nome do motorista (Enter salva)…',
  },
};
function pillSelectAbt(t, campo) {
  const cfg = CONFIG_PILL_ABT[campo];
  const valAtual = t[campo] || '';
  const lista = cfg.opcoesDinamicas ? cfg.opcoesDinamicas() : cfg.opcoes;
  const itens = lista.map(o => `<button type="button" class="pill-item ${o.classe}" data-valor="${esc(o.valor)}">${esc(o.rotulo || o.valor)}</button>`).join('');
  const busca = cfg.busca ? `<input type="text" class="pill-busca" placeholder="${esc(cfg.placeholder || 'Pesquisar...')}" />` : '';
  const editor = cfg.editavel ? `<input type="text" class="pill-edit" placeholder="${esc(cfg.placeholderEdit || 'Digite e tecle Enter…')}" value="${esc(valAtual || '')}" />` : '';
  const largo = (cfg.busca || cfg.editavel) ? ' com-busca' : '';
  return `<div class="pill-select" data-id="${esc(t.id)}" data-campo="${campo}">
      <button type="button" class="pill-trigger ${cfg.classe(valAtual)}" title="Clique para alterar"><span>${esc(cfg.rotulo(valAtual))}</span>${CHEVRON}</button>
      <div class="pill-menu${largo}" hidden>${busca}<div class="pill-itens">${itens}</div>${editor}</div>
    </div>`;
}
async function alterarCampoAbt(id, campo, valor, comDesfazer = true) {
  const t = ABASTECIMENTO.find(x => x.id === id);
  if (!t) return;
  valor = (valor || '').toString().trim();
  if ((t[campo] || '') === valor) return;
  const anterior = t[campo];
  const r = await fetch('/api/abastecimento/' + encodeURIComponent(id), {
    method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ [campo]: valor }),
  });
  if (!r.ok) { toast('Erro ao alterar.', 'erro'); return; }
  t[campo] = valor;
  if (campo === 'centroCusto') await garantirCadastrado('centrosCusto', valor);
  popularFiltrosAbt();
  renderAbastecimento();
  const desfazer = comDesfazer ? { texto: 'Desfazer', fn: () => alterarCampoAbt(id, campo, anterior, false) } : null;
  toast(`Transação de ${t.placa} atualizada.`, 'ok', desfazer);
}

async function carregarAbastecimento() {
  try {
    const r = await fetch('/api/abastecimento', { cache: 'no-store' });
    if (r.status === 401) { window.location = '/login'; return; }
    if (r.status === 403) { ABASTECIMENTO = []; popularFiltrosAbt(); renderAbastecimento(); toast('Você não tem acesso a esta área.', 'erro'); return; }
    const d = r.ok ? await r.json() : [];
    ABASTECIMENTO = Array.isArray(d) ? d : [];
  } catch (e) {
    ABASTECIMENTO = [];
    toast('Erro ao carregar o abastecimento. Verifique a conexão.', 'erro');
  }
  popularFiltrosAbt();
  renderAbastecimento();
}

function popularFiltrosAbt() {
  const unicos = (campo) => [...new Set(ABASTECIMENTO.map(t => t[campo]).filter(x => x !== '' && x != null))].sort((a, b) => String(a).localeCompare(String(b), 'pt-BR'));
  if (MSEL.fabtPlaca) MSEL.fabtPlaca.setOpcoes(unicos('placa'));
  if (MSEL.fabtCentro) MSEL.fabtCentro.setOpcoes([...new Set([...unicos('centroCusto'), ...(CADASTROS.centrosCusto || [])])].sort((a, b) => String(a).localeCompare(String(b), 'pt-BR')));
  if (MSEL.fabtMotorista) MSEL.fabtMotorista.setOpcoes([...new Set([...unicos('motorista'), ...(CADASTROS.motoristas || [])])].sort((a, b) => String(a).localeCompare(String(b), 'pt-BR')));
  if (MSEL.fabtPosto) MSEL.fabtPosto.setOpcoes(unicos('posto'));
  if (MSEL.fabtCombustivel) MSEL.fabtCombustivel.setOpcoes(unicos('combustivel'));
  if (MSEL.fabtAlerta) MSEL.fabtAlerta.setOpcoes(['Com alerta', 'Sem alerta']);
  if (MSEL.fabtPeriodo) {
    const meses = [...new Set(ABASTECIMENTO.map(t => mesDeMnt(t.dataHora)).filter(Boolean))].sort().reverse();
    MSEL.fabtPeriodo.setOpcoes(meses.map(rotuloMes));
  }
  const dPlacas = document.getElementById('listaPlacasAbt');
  if (dPlacas) dPlacas.innerHTML = [...new Set([...unicos('placa'), ...VEICULOS.map(v => v.placa)])].sort().map(x => `<option value="${esc(x)}">`).join('');
  // Filtros de combustível/alerta e a sub-aba Alertas só aparecem quando há dados de combustível.
  const temFuel = abtTemFuel();
  const elCo = document.getElementById('fabtCombustivel'); if (elCo) elCo.style.display = temFuel ? '' : 'none';
  // Some a coluna → limpa qualquer seleção pendente (senão o filtro escondido continuaria valendo e
  // esvaziaria a tabela sem chip visível para desmarcar — o de Alerta usa opções fixas e não se auto-limpa).
  if (!temFuel) { MSEL.fabtCombustivel && MSEL.fabtCombustivel.limpar(); }
}

function abtFiltrados(ctx = contextoAlertasAbt()) {
  const q = (document.getElementById('buscaAbt').value || '').trim().toLowerCase();
  const fPl = getSel('fabtPlaca'), fCe = getSel('fabtCentro'), fMo = getSel('fabtMotorista'), fPo = getSel('fabtPosto'), fCo = getSel('fabtCombustivel'), fAl = getSel('fabtAlerta'), fPe = getSel('fabtPeriodo');
  return ABASTECIMENTO.filter(t => {
    if (fPl.length && !fPl.includes(t.placa)) return false;
    if (fCe.length && !fCe.includes(t.centroCusto)) return false;
    if (fMo.length && !fMo.includes(t.motorista)) return false;
    if (fPo.length && !fPo.includes(t.posto)) return false;
    if (fCo.length && !fCo.includes(t.combustivel)) return false;
    if (fPe.length && !fPe.includes(rotuloMes(mesDeMnt(t.dataHora)))) return false;
    if (fAl.length === 1) {
      const temAlerta = motivosAlertaTransacaoAbt(t, ctx).length > 0;
      if (fAl[0] === 'Com alerta' && !temAlerta) return false;
      if (fAl[0] === 'Sem alerta' && temAlerta) return false;
    }
    if (q) {
      const alvo = `${t.placa} ${t.motorista} ${t.posto} ${t.cidade} ${t.uf} ${t.combustivel} ${t.modelo} ${t.centroCusto}`.toLowerCase();
      if (!alvo.includes(q)) return false;
    }
    return true;
  });
}

// ----- Agregação por veículo (entrega km, motorista responsável e métricas) -----
function agregarPorVeiculoAbt(lista, ctx = contextoAlertasAbt()) {
  const porPlaca = {};
  for (const t of lista) {
    const p = t.placa || '—';
    const g = porPlaca[p] || (porPlaca[p] = { placa: p, modelo: t.modelo || '', centros: {}, motoristas: {}, litros: 0, gasto: 0, kmPeriodo: 0, kmLs: [], nAbast: 0, alertas: 0, ultimoTs: 0, ultimoMot: '' });
    g.nAbast++; g.litros += numAbt(t.litros); g.gasto += numAbt(t.valor);
    if (numAbt(t.kmRod) > 0) g.kmPeriodo += numAbt(t.kmRod);   // ignora km zero/negativo/impossível
    if (numAbt(t.kmL) > 0) g.kmLs.push(numAbt(t.kmL));
    if (motivosAlertaTransacaoAbt(t, ctx).length) g.alertas++;
    if (t.motorista) g.motoristas[t.motorista] = (g.motoristas[t.motorista] || 0) + 1;
    if (t.centroCusto) g.centros[t.centroCusto] = (g.centros[t.centroCusto] || 0) + 1;
    const ts = numAbt(t.ts); if (ts >= g.ultimoTs) { g.ultimoTs = ts; if (t.motorista) g.ultimoMot = t.motorista; }
    if (!g.modelo) g.modelo = modeloAbt(t);
  }
  const maisFreq = (obj, fallback) => { let k = '', n = -1; for (const x in obj) if (obj[x] > n) { n = obj[x]; k = x; } return k || fallback; };
  const mediana = (a) => { if (!a.length) return 0; const s = [...a].sort((x, y) => x - y); const m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
  return Object.values(porPlaca).map(g => {
    const propAlerta = g.nAbast ? g.alertas / g.nAbast : 0;
    const risco = propAlerta >= 0.5 ? 'CRÍTICO' : propAlerta >= 0.3 ? 'ALTO' : propAlerta > 0 ? 'MÉDIO' : 'BAIXO';
    return {
      placa: g.placa, modelo: g.modelo,
      motorista: maisFreq(g.motoristas, g.ultimoMot || '—'),   // responsável = mais frequente (desempate: mais recente)
      centroCusto: maisFreq(g.centros, '—'),
      kmPeriodo: g.kmPeriodo, nAbast: g.nAbast, litros: g.litros, gasto: g.gasto,
      gastoMedio: g.nAbast ? g.gasto / g.nAbast : 0,
      precoMedio: g.litros ? g.gasto / g.litros : 0, kmLMediano: mediana(g.kmLs),
      alertas: g.alertas, propAlerta, risco,
    };
  });
}
const EMOJI_RISCO_ABT = { 'CRÍTICO': '🔴 Crítico', 'ALTO': '🟠 Alto', 'MÉDIO': '🟡 Médio', 'BAIXO': '🟢 Baixo' };

function resumoFinanceiroMensalAbt(lista) {
  const porMes = new Map();
  const porPlacaMes = new Map();
  for (const t of lista || []) {
    const mes = mesDeMnt(t.dataHora);
    if (!mes) continue;
    const valor = numAbt(t.valor);
    porMes.set(mes, (porMes.get(mes) || 0) + valor);
    const p = placaAbt(t.placa);
    if (p) porPlacaMes.set(`${p}|${mes}`, (porPlacaMes.get(`${p}|${mes}`) || 0) + valor);
  }
  const meses = [...porMes.keys()].sort();
  const atual = meses[meses.length - 1] || '';
  const anterior = mesAnteriorAbt(atual);
  const totalAtual = porMes.get(atual) || 0;
  const totalAnterior = porMes.get(anterior) || 0;
  const placas = new Set((lista || []).map(t => placaAbt(t.placa)).filter(Boolean));
  const ativosNoFiltro = fleetAtiva().filter(v => !placas.size || placas.has(placaAbt(v.placa))).length || placas.size;
  const centros = new Set((lista || []).map(t => t.centroCusto).filter(Boolean));
  let maiorAlta = null;
  for (const p of placas) {
    const atualPlaca = porPlacaMes.get(`${p}|${atual}`) || 0;
    const antPlaca = porPlacaMes.get(`${p}|${anterior}`) || 0;
    const diff = atualPlaca - antPlaca;
    if (diff > 0 && (!maiorAlta || diff > maiorAlta.diff)) maiorAlta = { placa: p, diff };
  }
  return {
    atual, anterior, totalAtual, totalAnterior,
    variacao: totalAnterior ? (totalAtual - totalAnterior) / totalAnterior : null,
    medioVeiculoAtivo: ativosNoFiltro ? (lista || []).reduce((s, t) => s + numAbt(t.valor), 0) / ativosNoFiltro : 0,
    medioCentro: centros.size ? (lista || []).reduce((s, t) => s + numAbt(t.valor), 0) / centros.size : 0,
    maiorAlta,
  };
}
function fmtVarAbt(v) {
  if (v === null || v === undefined || !Number.isFinite(v)) return '—';
  const sinal = v > 0 ? '+' : '';
  return sinal + (v * 100).toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + '%';
}
function cardsFinanceirosAbt(lista) {
  const r = resumoFinanceiroMensalAbt(lista);
  return `
    ${cardV2('Gasto mês atual', `${r.atual ? rotuloMes(r.atual) + ' · ' : ''}${fmtMoneyDec(r.totalAtual)}`, 'red', false, 'title="Mês mais recente dentro dos dados filtrados."')}
    ${cardV2('Mês anterior', `${r.anterior ? rotuloMes(r.anterior) + ' · ' : ''}${fmtMoneyDec(r.totalAnterior)}`, '', false, 'title="Mês calendário anterior ao mês mais recente filtrado."')}
    ${cardV2('Variação mensal', fmtVarAbt(r.variacao), r.variacao > 0 ? 'red' : (r.variacao < 0 ? 'green' : ''), false, 'title="Comparação do mês atual com o mês anterior."')}
    ${cardV2('Médio/veículo ativo', fmtMoneyDec(r.medioVeiculoAtivo), 'amber', true)}
    ${cardV2('Médio/centro', fmtMoneyDec(r.medioCentro), '', true)}
    ${cardV2('Maior alta por placa', r.maiorAlta ? `${r.maiorAlta.placa} · +${fmtMoneyDec(r.maiorAlta.diff)}` : '—', 'amber')}
  `;
}

function renderCardsAbt(pre, ctx = contextoAlertasAbt()) {
  const lista = pre || abtFiltrados(ctx);
  const totGasto = lista.reduce((s, t) => s + numAbt(t.valor), 0);
  const nVeic = new Set(lista.map(t => t.placa).filter(Boolean)).size;
  const comAlertaAuto = lista.filter(t => motivosAlertaTransacaoAbt(t, ctx).length).length;
  let html;
  if (abtTemFuel()) {
    const totLitros = lista.reduce((s, t) => s + numAbt(t.litros), 0);
    const kmValidos = lista.reduce((s, t) => s + (numAbt(t.kmRod) > 0 ? numAbt(t.kmRod) : 0), 0);
    // litros dos MESMOS registros que entram no numerador (km > 0), p/ o Km/L ponderado não subestimar
    const litrosValidos = lista.reduce((s, t) => s + (numAbt(t.kmRod) > 0 ? numAbt(t.litros) : 0), 0);
    const comAlerta = comAlertaAuto;
    const pctAlerta = lista.length ? Math.round((comAlerta / lista.length) * 100) : 0;
    const veicRisco = new Set(lista.filter(t => motivosAlertaTransacaoAbt(t, ctx).length).map(t => t.placa)).size;
    html = `
      ${cardV2('Total gasto', fmtMoneyDec(totGasto), 'red', true)}
      ${cardV2('Total litros', fmtLitros(totLitros) + ' L', '')}
      ${cardV2('Preço médio/L', fmtRSL(totLitros ? totGasto / totLitros : 0), 'amber')}
      ${cardV2('Km/L frota', fmtKmL(litrosValidos ? kmValidos / litrosValidos : 0), '', false, 'title="Km rodados válidos ÷ litros dos mesmos registros (ponderado)."')}
      ${cardV2('Trans. c/ alerta', `${comAlerta} (${pctAlerta}%)`, 'red')}
      ${cardV2('Veículos em risco', veicRisco, 'amber', false, 'title="Veículos com ao menos uma transação em alerta."')}
      ${cardsFinanceirosAbt(lista)}
    `;
  } else {
    // Lançamentos financeiros (sem litros/km): foco no gasto.
    const ticket = lista.length ? totGasto / lista.length : 0;
    const nCentros = new Set(lista.map(t => t.centroCusto).filter(Boolean)).size;
    const nPostos = new Set(lista.map(t => t.posto).filter(Boolean)).size;
    html = `
      ${cardV2('Total gasto', fmtMoneyDec(totGasto), 'red', true)}
      ${cardV2('Transações', lista.length, '')}
      ${cardV2('Veículos', nVeic, '')}
      ${cardV2('Ticket médio', fmtMoneyDec(ticket), 'amber', true, 'title="Gasto médio por abastecimento."')}
      ${cardV2('Centros de custo', nCentros, '')}
      ${cardV2('Postos', nPostos, '')}
      ${cardV2('Trans. c/ alerta', comAlertaAuto, comAlertaAuto ? 'red' : '')}
      ${cardsFinanceirosAbt(lista)}
    `;
  }
  const a = document.getElementById('cardsAbtVeiculo'); if (a) a.innerHTML = html;
  const b = document.getElementById('cardsAbastecimento'); if (b) b.innerHTML = html;
}

function renderAbastecimento() {
  const ctx = contextoAlertasAbt();
  const lista = abtFiltrados(ctx); // calcula 1x e repassa (evita filtrar de novo em cada sub-render)
  renderCardsAbt(lista, ctx);
  if (subAbtAtiva === 'abt-veiculo') renderPorVeiculoAbt(lista, ctx);
  else if (subAbtAtiva === 'abt-transacoes') renderTransacoesAbt(lista, ctx);
  else if (subAbtAtiva === 'abt-dashboards') renderDashboardsAbt(lista, ctx);
  else if (subAbtAtiva === 'abt-alertas') renderAlertasAbt(lista, ctx);
}

// ----- Sub-aba Por veículo (★ quilometragem + motorista responsável + métricas) -----
const COLS_ABT_VEIC = [
  { campo: 'placa', titulo: 'Placa', cell: v => `<td><button class="placa-btn placa-chip" data-placa="${esc(v.placa)}" title="Ver histórico desta placa">${esc(v.placa)}</button></td>` },
  { campo: 'modelo', titulo: 'Modelo', cell: v => `<td>${esc(v.modelo || '—')}</td>` },
  { campo: 'kmPeriodo', titulo: 'Km rodados (período)', classe: 'num', num: true, fuel: true, cell: v => `<td class="num">${fmtKm(v.kmPeriodo)} km</td>` },
  { campo: 'motorista', titulo: 'Motorista responsável', cell: v => `<td>${esc(v.motorista || '—')}</td>` },
  { campo: 'centroCusto', titulo: 'Centro de custo', cell: v => `<td>${esc(v.centroCusto || '—')}</td>` },
  { campo: 'nAbast', titulo: 'Abast.', classe: 'num', num: true, cell: v => `<td class="num">${v.nAbast}</td>` },
  { campo: 'litros', titulo: 'Litros', classe: 'num', num: true, fuel: true, cell: v => `<td class="num">${fmtLitros(v.litros)}</td>` },
  { campo: 'gasto', titulo: 'Gasto R$', classe: 'num', num: true, cell: v => `<td class="num">${fmtMoneyDec(v.gasto)}</td>` },
  { campo: 'gastoMedio', titulo: 'Gasto médio', classe: 'num', num: true, cell: v => `<td class="num">${fmtMoneyDec(v.gastoMedio)}</td>` },
  { campo: 'kmLMediano', titulo: 'Km/L mediano', classe: 'num', num: true, fuel: true, cell: v => `<td class="num">${fmtKmL(v.kmLMediano)}</td>` },
  { campo: 'precoMedio', titulo: 'R$/L médio', classe: 'num', num: true, fuel: true, cell: v => `<td class="num">${fmtRSL(v.precoMedio)}</td>` },
  { campo: 'alertas', titulo: 'Alertas', classe: 'num', num: true, fuel: true, cell: v => `<td class="num">${v.alertas}</td>` },
  { campo: 'risco', titulo: 'Risco', ord: (v) => v.propAlerta, num: true, fuel: true, cell: v => `<td><b>${esc(EMOJI_RISCO_ABT[v.risco] || v.risco)}</b></td>` },
];
function renderPorVeiculoAbt(pre, ctx = contextoAlertasAbt()) {
  const listaBase = pre || abtFiltrados(ctx);
  const temFuel = abtTemFuel();
  const cols = COLS_ABT_VEIC.filter(c => !c.fuel || temFuel);
  const dados = agregarPorVeiculoAbt(listaBase, ctx);
  const dadosFiltrados = abtVeicBusca
    ? dados.filter(v => `${v.placa} ${v.modelo} ${v.motorista} ${v.centroCusto}`.toLowerCase().includes(abtVeicBusca))
    : dados;
  // Se a coluna de ordenação sumiu (era de combustível e agora está oculta), cai no gasto.
  if (!cols.some(c => c.campo === ordemAbtVeic.campo)) ordemAbtVeic = { campo: 'gasto', dir: -1 };
  const col = cols.find(c => c.campo === ordemAbtVeic.campo) || cols[0];
  dadosFiltrados.sort((a, b) => {
    let x = col.ord ? col.ord(a) : a[col.campo];
    let y = col.ord ? col.ord(b) : b[col.campo];
    if (col.num) { x = Number(x) || 0; y = Number(y) || 0; return (x - y) * ordemAbtVeic.dir; }
    return String(x ?? '').localeCompare(String(y ?? ''), 'pt-BR') * ordemAbtVeic.dir;
  });
  const thead = document.getElementById('cabecalhoAbtVeic');
  const corpo = document.getElementById('corpoAbtVeic');
  const vazio = document.getElementById('abtVeicVazio');
  thead.innerHTML = cols.map(c => `<th data-campo="${c.campo}" class="${c.classe || ''}" title="Clique para ordenar">${c.titulo}${iconeOrd(ordemAbtVeic.campo === c.campo, ordemAbtVeic.dir)}</th>`).join('');
  thead.querySelectorAll('th[data-campo]').forEach(th => {
    th.onclick = () => {
      const campo = th.dataset.campo;
      if (ordemAbtVeic.campo === campo) ordemAbtVeic.dir *= -1;
      else { ordemAbtVeic.campo = campo; ordemAbtVeic.dir = (campo === 'placa' || campo === 'modelo' || campo === 'motorista' || campo === 'centroCusto') ? 1 : -1; }
      renderPorVeiculoAbt();
    };
  });
  document.getElementById('resumoAbtVeic').innerHTML = `${dadosFiltrados.length} veículo(s) · gasto total: <b>${fmtMoneyDec(dadosFiltrados.reduce((s, v) => s + v.gasto, 0))}</b>`;
  if (!dadosFiltrados.length) { corpo.innerHTML = ''; vazio.hidden = false; return; }
  vazio.hidden = true;
  corpo.innerHTML = dadosFiltrados.map(v => `<tr>${cols.map(c => c.cell(v)).join('')}</tr>`).join('');
}

// ----- Sub-aba Transações: tabela paginada, editável inline e ordenável -----
const COLS_ABT = [
  { campo: 'dataHora', titulo: 'Data/Hora', ord: t => dataOrdAbt(t.dataHora), num: true,
    cell: (t, ctx) => { const motivos = motivosAlertaTransacaoAbt(t, ctx).join(' · '); return `<td><span title="${esc(motivos)}"${motivos ? ' style="color:var(--red);font-weight:600"' : ''}>${esc(t.dataHora || '—')}</span></td>`; } },
  { campo: 'placa', titulo: 'Placa', cell: t => `<td><button class="placa-btn placa-chip" data-placa="${esc(t.placa)}" title="Ver histórico desta placa">${esc(t.placa)}</button></td>` },
  { campo: 'motorista', titulo: 'Motorista', cell: t => `<td>${pillSelectAbt(t, 'motorista')}</td>` },
  { campo: 'centroCusto', titulo: 'Centro de custo', cell: t => `<td>${pillSelectAbt(t, 'centroCusto')}</td>` },
  { campo: 'posto', titulo: 'Posto', cell: t => `<td>${esc(t.posto || '—')}</td>` },
  { campo: 'combustivel', titulo: 'Combustível', fuel: true, cell: t => `<td>${esc(t.combustivel || '—')}</td>` },
  { campo: 'litros', titulo: 'Litros', classe: 'num', num: true, fuel: true, cell: t => `<td class="num">${fmtLitros(t.litros)}</td>` },
  { campo: 'precoLitro', titulo: 'R$/L', classe: 'num', num: true, fuel: true, cell: t => `<td class="num">${fmtRSL(t.precoLitro)}</td>` },
  { campo: 'kmRod', titulo: 'Km rod.', classe: 'num', num: true, fuel: true, cell: t => `<td class="num">${fmtKm(t.kmRod)}</td>` },
  { campo: 'kmL', titulo: 'Km/L', classe: 'num', num: true, fuel: true, cell: t => `<td class="num">${fmtKmL(t.kmL)}</td>` },
  { campo: 'valor', titulo: 'Total R$', classe: 'num', num: true, cell: t => `<td class="num">${fmtMoneyDec(t.valor)}</td>` },
];
function renderTransacoesAbt(pre, ctx = contextoAlertasAbt()) {
  if (SELECAO_ABT.size) { const vivos = new Set(ABASTECIMENTO.map(t => t.id)); for (const id of [...SELECAO_ABT]) if (!vivos.has(id)) SELECAO_ABT.delete(id); }
  const listaBase = pre || abtFiltrados(ctx);
  const temFuel = abtTemFuel();
  const cols = COLS_ABT.filter(c => !c.fuel || temFuel);
  if (!cols.some(c => c.campo === ordemAbt.campo)) ordemAbt = { campo: 'dataHora', dir: -1 };
  const col = cols.find(c => c.campo === ordemAbt.campo) || cols[0];
  const lista = listaBase.slice().sort((a, b) => {
    let x = col.ord ? col.ord(a) : a[col.campo];
    let y = col.ord ? col.ord(b) : b[col.campo];
    if (col.num) { x = Number(x) || 0; y = Number(y) || 0; return (x - y) * ordemAbt.dir; }
    return String(x ?? '').localeCompare(String(y ?? ''), 'pt-BR') * ordemAbt.dir;
  });
  const vazio = document.getElementById('abtVazio');
  const corpo = document.getElementById('corpoAbt');
  const thead = document.getElementById('cabecalhoAbt');
  thead.innerHTML = '<th class="col-acoes">Ações</th>' + cols.map(c =>
    `<th data-campo="${c.campo}" class="${c.classe || ''}" title="Clique para ordenar">${c.titulo}${iconeOrd(ordemAbt.campo === c.campo, ordemAbt.dir)}</th>`).join('');
  thead.querySelectorAll('th[data-campo]').forEach(th => {
    th.onclick = () => {
      const campo = th.dataset.campo;
      if (ordemAbt.campo === campo) ordemAbt.dir *= -1;
      else { ordemAbt.campo = campo; ordemAbt.dir = (campo === 'placa' || campo === 'motorista' || campo === 'centroCusto' || campo === 'posto' || campo === 'combustivel') ? 1 : -1; }
      renderTransacoesAbt();
    };
  });
  document.getElementById('resumoAbt').innerHTML = `${lista.length} transação(ões) · soma: <b>${fmtMoneyDec(lista.reduce((s, t) => s + numAbt(t.valor), 0))}</b>`;
  if (!lista.length) { corpo.innerHTML = ''; vazio.hidden = false; document.getElementById('abtPagInfo').textContent = ''; return; }
  vazio.hidden = true;
  const selPag = document.getElementById('abtPorPagina').value;
  const porPag = selPag === 'all' ? lista.length : Number(selPag);
  const totalPaginas = Math.max(1, Math.ceil(lista.length / porPag));
  if (abtPagina > totalPaginas) abtPagina = totalPaginas;
  const ini = (abtPagina - 1) * porPag;
  const pag = lista.slice(ini, ini + porPag);
  corpo.innerHTML = pag.map(t => {
    const selOn = SELECAO_ABT.has(t.id) ? ' sel-on' : '';
    return `<tr data-id="${esc(t.id)}" class="${selOn}">
      <td class="acoes">
        <button class="edit edit-abt" data-id="${esc(t.id)}" title="Editar" aria-label="Editar">${ICONE_LAPIS}</button>
        <button class="del del-abt" data-id="${esc(t.id)}" title="Excluir" aria-label="Excluir">${ICONE_LIXEIRA}</button>
      </td>${cols.map(c => c.cell(t, ctx)).join('')}
    </tr>`;
  }).join('');
  rotularCelulasMobile('cabecalhoAbt', 'corpoAbt'); // celular: tabela vira cartões
  renderNavPaginacao('abt', { de: lista.length ? ini + 1 : 0, ate: Math.min(ini + porPag, lista.length), total: lista.length, totalPaginas, pagina: abtPagina });

  // Edição inline (pílulas) — mesmo mecanismo da Manutenção
  corpo.querySelectorAll('.pill-trigger').forEach(tr => tr.onclick = (ev) => {
    ev.stopPropagation();
    const sel = tr.closest('.pill-select');
    const jaAberto = sel.classList.contains('aberto');
    fecharPillMenus();
    if (!jaAberto) abrirPillMenu(sel);
  });
  corpo.querySelectorAll('.pill-item').forEach(it => it.onclick = (ev) => {
    ev.stopPropagation();
    const sel = donoPillMenu(it);
    if (!sel) return;
    fecharPillMenus();
    alterarCampoAbt(sel.dataset.id, sel.dataset.campo, it.dataset.valor);
  });
  corpo.querySelectorAll('.pill-busca').forEach(inp => {
    inp.onclick = (ev) => ev.stopPropagation();
    inp.oninput = () => {
      const q = inp.value.trim().toLowerCase();
      inp.closest('.pill-menu').querySelectorAll('.pill-item').forEach(it => { it.hidden = q && !it.textContent.toLowerCase().includes(q); });
    };
  });
  corpo.querySelectorAll('.pill-edit').forEach(inp => {
    inp.onclick = (ev) => ev.stopPropagation();
    inp.onkeydown = (ev) => {
      if (ev.key === 'Enter') { ev.preventDefault(); const sel = donoPillMenu(inp); if (!sel) return; fecharPillMenus(); alterarCampoAbt(sel.dataset.id, 'motorista', inp.value.trim()); }
    };
  });
  // Seleção agora é por clique na linha (ver DELEGAÇÃO em #abastecimento).
  SEL_TODOS_ABT.sincronizar(lista); // alimenta o cache de chaves com a lista filtrada recém-calculada
  atualizarBarraSelAbt();
}
function atualizarBarraSelAbt() {
  const bar = document.getElementById('selBarAbt');
  if (!bar) return;
  SEL_TODOS_ABT.sincronizar(); // antes do return de "nada selecionado": o (N) do rótulo tem de seguir certo
  if (!SELECAO_ABT.size) { bar.hidden = true; return; }
  const sel = ABASTECIMENTO.filter(t => SELECAO_ABT.has(t.id));
  const total = sel.reduce((s, t) => s + numAbt(t.valor), 0);
  document.getElementById('selBarAbtInfo').innerHTML =
    `<span class="sb-item"><b>${sel.length}</b> selecionada(s)</span><span class="sb-item">Soma: <b>${fmtMoneyDec(total)}</b></span>`;
  bar.hidden = false;
}

// ----- Sub-aba Dashboards -----
function renderDashboardsAbt(pre, ctx = contextoAlertasAbt()) {
  const lista = pre || abtFiltrados(ctx);
  const temFuel = abtTemFuel();
  const totGasto = lista.reduce((s, t) => s + numAbt(t.valor), 0);
  const totLitros = lista.reduce((s, t) => s + numAbt(t.litros), 0);
  const veics = agregarPorVeiculoAbt(lista, ctx).sort((a, b) => b.gasto - a.gasto);
  // Painéis que só fazem sentido com dados de combustível (litros/km/L/preço/alerta).
  const mostrar = (id, on) => { const el = document.getElementById(id); if (el) el.style.display = on ? '' : 'none'; };
  mostrar('painelAbtCombustivel', temFuel);
  mostrar('painelAbtEficiencia', temFuel);
  mostrar('painelAbtKmLModeloMes', temFuel);
  mostrar('painelAbtAlertaTipo', temFuel);
  document.getElementById('cardsDashAbt').innerHTML = temFuel ? `
    ${cardV2('Gasto total', fmtMoneyDec(totGasto), 'red', true)}
    ${cardV2('Litros', fmtLitros(totLitros) + ' L', '')}
    ${cardV2('Transações', lista.length, '')}
    ${cardV2('Veículos', veics.length, '')}
    ${cardsFinanceirosAbt(lista)}
  ` : `
    ${cardV2('Gasto total', fmtMoneyDec(totGasto), 'red', true)}
    ${cardV2('Transações', lista.length, '')}
    ${cardV2('Veículos', veics.length, '')}
    ${cardV2('Ticket médio', fmtMoneyDec(lista.length ? totGasto / lista.length : 0), 'amber', true, 'title="Gasto médio por abastecimento."')}
    ${cardsFinanceirosAbt(lista)}
  `;
  const moedaTooltip = { plugins: { tooltip: { callbacks: { label: (ctx) => `${ctx.dataset.label}: ${fmtMoneyDec(ctx.parsed.y ?? ctx.parsed)}` } } } };
  // 1) Gasto por veículo (top 20)
  const top = veics.slice(0, 20);
  desenhar('chartAbtVeiculo', 'bar', { labels: top.map(v => v.placa), datasets: [{ label: 'Gasto', data: top.map(v => Math.round(v.gasto)), backgroundColor: '#1b56ff' }] },
    { plugins: { legend: { display: false }, tooltip: moedaTooltip.plugins.tooltip }, scales: { y: { beginAtZero: true } } });
  // 2) Gasto por combustível (só quando há tipo de combustível na base)
  if (temFuel) {
    const porComb = new Map();
    for (const t of lista) porComb.set(t.combustivel || '—', (porComb.get(t.combustivel || '—') || 0) + numAbt(t.valor));
    const combArr = [...porComb.entries()].sort((a, b) => b[1] - a[1]);
    desenhar('chartAbtCombustivel', 'doughnut', { labels: combArr.map(x => x[0]), datasets: [{ data: combArr.map(x => Math.round(x[1])), backgroundColor: combArr.map((_, i) => CORES_ABT[i % CORES_ABT.length]) }] },
      { plugins: { tooltip: moedaTooltip.plugins.tooltip } });
  }
  // 3) Gasto por centro de custo
  const porCentro = new Map();
  for (const t of lista) porCentro.set(t.centroCusto || '—', (porCentro.get(t.centroCusto || '—') || 0) + numAbt(t.valor));
  const centroArr = [...porCentro.entries()].sort((a, b) => b[1] - a[1]);
  desenhar('chartAbtCentro', 'bar', { labels: centroArr.map(x => trunc(x[0], 18)), datasets: [{ label: 'Gasto', data: centroArr.map(x => Math.round(x[1])), backgroundColor: centroArr.map((_, i) => CORES_ABT[i % CORES_ABT.length]) }] },
    { plugins: { legend: { display: false }, tooltip: moedaTooltip.plugins.tooltip }, scales: { y: { beginAtZero: true } } });
  // 4) Gasto por motorista (top 20)
  const porMotorista = new Map();
  for (const t of lista) porMotorista.set(t.motorista || '—', (porMotorista.get(t.motorista || '—') || 0) + numAbt(t.valor));
  const motoristArr = [...porMotorista.entries()].sort((a, b) => b[1] - a[1]).slice(0, 20);
  desenhar('chartAbtMotorista', 'bar', { labels: motoristArr.map(x => trunc(x[0], 20)), datasets: [{ label: 'Gasto', data: motoristArr.map(x => Math.round(x[1])), backgroundColor: motoristArr.map((_, i) => CORES_ABT[i % CORES_ABT.length]) }] },
    { plugins: { legend: { display: false }, tooltip: moedaTooltip.plugins.tooltip }, scales: { y: { beginAtZero: true } } });
  // 5) Evolução mensal
  const porMes = new Map();
  for (const t of lista) { const k = mesDeMnt(t.dataHora); if (k) porMes.set(k, (porMes.get(k) || 0) + numAbt(t.valor)); }
  const mesesArr = [...porMes.entries()].sort((a, b) => a[0].localeCompare(b[0]));
  desenhar('chartAbtMensal', 'bar', { labels: mesesArr.map(x => rotuloMes(x[0])), datasets: [{ label: 'Gasto no mês', data: mesesArr.map(x => Math.round(x[1])), backgroundColor: '#0369a1' }] },
    { plugins: { legend: { display: false }, tooltip: moedaTooltip.plugins.tooltip }, scales: { y: { beginAtZero: true } } });
  // 6) Top postos por gasto
  const porPosto = new Map();
  for (const t of lista) { if (!t.posto) continue; porPosto.set(t.posto, (porPosto.get(t.posto) || 0) + numAbt(t.valor)); }
  const postoArr = [...porPosto.entries()].sort((a, b) => b[1] - a[1]).slice(0, 15);
  const tooltipHoriz = { callbacks: { label: (ctx) => `Gasto: ${fmtMoneyDec(ctx.parsed.x)}` } };
  desenhar('chartAbtPosto', 'bar', { labels: postoArr.map(x => trunc(x[0], 22)), datasets: [{ label: 'Gasto', data: postoArr.map(x => Math.round(x[1])), backgroundColor: '#7c3aed' }] },
    { indexAxis: 'y', plugins: { legend: { display: false }, tooltip: tooltipHoriz }, scales: { x: { beginAtZero: true } } });
  // 7) Km/L médio por combustível
  const kmLPorComb = new Map();
  for (const t of lista) {
    const kml = numAbt(t.kmL), kmr = numAbt(t.kmRod), sk = t.statusKmL || '';
    if (kml <= 0 || kmr <= 0 || /IMPOSS/i.test(sk) || /ZERO|NEGATIVO/i.test(sk)) continue;
    const c = t.combustivel || '—';
    const g = kmLPorComb.get(c) || { soma: 0, n: 0 };
    g.soma += kml; g.n++;
    kmLPorComb.set(c, g);
  }
  const kmLCombArr = [...kmLPorComb.entries()].map(([c, g]) => [c, g.n ? g.soma / g.n : 0]).sort((a, b) => b[1] - a[1]);
  if (kmLCombArr.length) {
    desenhar('chartAbtKmLComb', 'bar',
      { labels: kmLCombArr.map(x => x[0]), datasets: [{ label: 'Km/L médio', data: kmLCombArr.map(x => +x[1].toFixed(2)), backgroundColor: kmLCombArr.map((_, i) => CORES_ABT[i % CORES_ABT.length]) }] },
      { plugins: { legend: { display: false }, tooltip: { callbacks: { label: (ctx) => `${ctx.dataset.label}: ${numAbt(ctx.parsed.y).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} km/L` } } }, scales: { y: { beginAtZero: true } } });
  }
  // 8) Preço médio ponderado R$/L por combustível
  const precoPorComb = new Map();
  for (const t of lista) {
    const v = numAbt(t.valor), l = numAbt(t.litros);
    if (v <= 0 || l <= 0) continue;
    const c = t.combustivel || '—';
    const g = precoPorComb.get(c) || { somaV: 0, somaL: 0 };
    g.somaV += v; g.somaL += l;
    precoPorComb.set(c, g);
  }
  const precoCombArr = [...precoPorComb.entries()].map(([c, g]) => [c, g.somaL ? g.somaV / g.somaL : 0]).sort((a, b) => b[1] - a[1]);
  if (precoCombArr.length) {
    desenhar('chartAbtPrecoComb', 'bar',
      { labels: precoCombArr.map(x => x[0]), datasets: [{ label: 'R$/L médio', data: precoCombArr.map(x => +x[1].toFixed(3)), backgroundColor: precoCombArr.map((_, i) => CORES_ABT[i % CORES_ABT.length]) }] },
      { plugins: { legend: { display: false }, tooltip: { callbacks: { label: (ctx) => `${ctx.dataset.label}: ${fmtRSL(ctx.parsed.y)}` } } }, scales: { y: { beginAtZero: true } } });
  }
  // 9) Distribuição de tipos de alerta
  const alertaCont = { 'Consumo fora padrão': 0, 'Odômetro menor': 0, 'Tanque excedido': 0, 'Sobrepreço': 0, 'Duplicado': 0, 'Outros': 0 };
  for (const t of lista) {
    const m = motivosAlertaTransacaoAbt(t, ctx).join(' · ');
    if (!m) continue;
    const sk = t.statusKmL || '', sp = t.statusPreco || '';
    let matched = false;
    if (/CONSUMO FORA|KM\/L.*BAIXO|KM\/L.*ALTO|IMPOSS|ZERO|NEGATIVO/i.test(m) || /IMPOSS|ZERO|NEGATIVO/i.test(sk)) { alertaCont['Consumo fora padrão']++; matched = true; }
    if (/OD[ÔO]METRO/i.test(m))                                                          { alertaCont['Odômetro menor']++;   matched = true; }
    if (/TANQUE/i.test(m))                                                                { alertaCont['Tanque excedido']++;  matched = true; }
    if (/LITRO ACIMA|SOBREPRE|PRE[ÇC]O/i.test(m) || /SOBREPRE|ACIMA/i.test(sp))          { alertaCont['Sobrepreço']++;       matched = true; }
    if (/DUPLICADO/i.test(m))                                                            { alertaCont['Duplicado']++;        matched = true; }
    if (!matched)                                                                          { alertaCont['Outros']++; }
  }
  const alertaTipoArr = Object.entries(alertaCont).filter(x => x[1] > 0);
  if (alertaTipoArr.length) {
    desenhar('chartAbtAlertaTipo', 'doughnut',
      { labels: alertaTipoArr.map(x => x[0]), datasets: [{ data: alertaTipoArr.map(x => x[1]), backgroundColor: alertaTipoArr.map((_, i) => CORES_ABT[i % CORES_ABT.length]) }] },
      { plugins: { tooltip: { callbacks: { label: (ctx) => `${ctx.label}: ${ctx.parsed} ocorrência(s)` } } } });
  }

  // ===== Comparativos por modelo/ano/mês (espelham os dashboards da Manutenção, com gasto de combustível) =====
  // 10) Gasto total por MODELO — modelo × modelo (variantes de nome já padronizados por familiaModelo)
  const porFamilia = new Map();
  for (const t of lista) {
    const fam = familiaModelo(modeloAbt(t));
    let g = porFamilia.get(fam); if (!g) { g = { veics: new Map(), total: 0 }; porFamilia.set(fam, g); }
    let v = g.veics.get(t.placa || '—'); if (!v) { v = { gasto: 0 }; g.veics.set(t.placa || '—', v); }
    const c = numAbt(t.valor); g.total += c; v.gasto += c;
  }
  const familiasTodas = [...porFamilia.entries()].sort((a, b) => b[1].total - a[1].total);
  desenhar('chartAbtModeloTotal', 'bar', {
    labels: familiasTodas.map(x => x[0]),
    datasets: [{ label: 'Gasto', data: familiasTodas.map(x => Math.round(x[1].total)), backgroundColor: familiasTodas.map((_, i) => CORES_ABT[i % CORES_ABT.length]) }],
  }, { plugins: { legend: { display: false }, tooltip: moedaTooltip.plugins.tooltip }, scales: { y: { beginAtZero: true } } });

  // 11) Comparativo POR MODELO — um gráfico por modelo, comparando os veículos daquele modelo (só 2+ veículos)
  const familias = familiasTodas.filter(([, g]) => g.veics.size >= 2);
  Object.keys(charts).filter(k => k.startsWith('chartAbtFam')).forEach(k => { charts[k].destroy(); delete charts[k]; });
  const contFam = document.getElementById('abtModeloCharts');
  if (contFam) {
    if (!familias.length) {
      contFam.innerHTML = '<p class="vazio">Nenhum modelo com 2 ou mais veículos no filtro atual.</p>';
    } else {
      contFam.innerHTML = familias.map(([fam, g], i) =>
        `<div class="modelo-card">
           <h4>${esc(fam)} · ${g.veics.size} veículos · ${fmtMoneyDec(g.total)}</h4>
           <div class="chart-box"><canvas id="chartAbtFam${i}"></canvas></div>
         </div>`).join('');
      familias.forEach(([, g], i) => {
        const veics = [...g.veics.entries()].sort((a, b) => b[1].gasto - a[1].gasto);
        desenhar(`chartAbtFam${i}`, 'bar', {
          labels: veics.map(x => x[0]),
          datasets: [{ label: 'Gasto', data: veics.map(x => Math.round(x[1].gasto)), backgroundColor: veics.map((_, j) => CORES_ABT[j % CORES_ABT.length]) }],
        }, { plugins: { legend: { display: false }, tooltip: moedaTooltip.plugins.tooltip }, scales: { y: { beginAtZero: true } } });
      });
    }
  }

  // 12) Km/L POR MÊS dentro de cada modelo — uma linha por veículo.
  // Prioriza a média ponderada (km rodados ÷ litros); a média simples do Km/L
  // fica como fallback para bases antigas que não tenham litros preenchidos.
  const familiasKmLMes = new Map();
  for (const t of lista) {
    const kml = numAbt(t.kmL), kmr = numAbt(t.kmRod), litros = numAbt(t.litros);
    const status = String(t.statusKmL || '');
    const mes = mesDeMnt(t.dataHora), placa = placaAbt(t.placa);
    if (!mes || !placa || kml <= 0 || kmr <= 0 || /IMPOSS|ZERO|NEGATIVO/i.test(status)) continue;
    const fam = familiaModelo(modeloAbt(t));
    let g = familiasKmLMes.get(fam);
    if (!g) { g = { veics: new Set(), meses: new Set(), pontos: new Map(), n: 0 }; familiasKmLMes.set(fam, g); }
    g.veics.add(placa); g.meses.add(mes); g.n++;
    const chave = `${placa}|${mes}`;
    const ponto = g.pontos.get(chave) || { km: 0, litros: 0, somaKmL: 0, n: 0 };
    if (litros > 0) { ponto.km += kmr; ponto.litros += litros; }
    ponto.somaKmL += kml; ponto.n++;
    g.pontos.set(chave, ponto);
  }
  const familiasKmL = [...familiasKmLMes.entries()]
    .filter(([, g]) => g.veics.size >= 2)
    .sort((a, b) => b[1].n - a[1].n);
  Object.keys(charts).filter(k => k.startsWith('chartAbtKmLMesFam')).forEach(k => { charts[k].destroy(); delete charts[k]; });
  const contKmL = document.getElementById('abtKmLModeloMesCharts');
  if (contKmL) {
    if (!familiasKmL.length) {
      contKmL.innerHTML = '<p class="vazio">Nenhum modelo com 2 ou mais veículos e leituras válidas de Km/L no filtro atual.</p>';
    } else {
      contKmL.innerHTML = familiasKmL.map(([fam, g], i) =>
        `<div class="modelo-card modelo-card-kml">
           <h4>${esc(fam)} · ${g.veics.size} veículos · ${g.meses.size} ${g.meses.size === 1 ? 'mês' : 'meses'}</h4>
           <div class="chart-box"><canvas id="chartAbtKmLMesFam${i}"></canvas></div>
         </div>`).join('');
      familiasKmL.forEach(([, g], i) => {
        const meses = [...g.meses].sort();
        const veiculos = [...g.veics].sort((a, b) => a.localeCompare(b, 'pt-BR'));
        desenhar(`chartAbtKmLMesFam${i}`, 'line', {
          labels: meses.map(rotuloMes),
          datasets: veiculos.map((placa, j) => ({
            label: placa,
            data: meses.map(mes => {
              const ponto = g.pontos.get(`${placa}|${mes}`);
              if (!ponto) return null;
              const valor = ponto.litros > 0 ? ponto.km / ponto.litros : ponto.somaKmL / ponto.n;
              return +valor.toFixed(2);
            }),
            borderColor: CORES_ABT[j % CORES_ABT.length],
            backgroundColor: CORES_ABT[j % CORES_ABT.length],
            pointRadius: 3,
            pointHoverRadius: 5,
            borderWidth: 2,
            tension: 0.22,
            spanGaps: false,
          })),
        }, {
          interaction: { mode: 'nearest', intersect: false },
          plugins: {
            legend: { position: 'bottom' },
            tooltip: { callbacks: { label: (ctx) => `${ctx.dataset.label}: ${fmtKmL(ctx.parsed.y)} km/L` } },
          },
          scales: { y: { beginAtZero: true, title: { display: true, text: 'Km/L' } } },
        });
      });
    }
  }

  // 13) Gasto por ANO do veículo (compara ano por ano)
  const porAno = new Map();
  for (const t of lista) { const k = String(anoVeiculoAbt(t) || '—').trim() || '—'; porAno.set(k, (porAno.get(k) || 0) + numAbt(t.valor)); }
  const anoArr = [...porAno.entries()].sort((a, b) => {
    const na = Number(a[0]), nb = Number(b[0]);
    if (isNaN(na)) return 1; if (isNaN(nb)) return -1; return na - nb;
  });
  desenhar('chartAbtAno', 'bar', {
    labels: anoArr.map(x => x[0]),
    datasets: [{ label: 'Gasto', data: anoArr.map(x => Math.round(x[1])), backgroundColor: '#7c3aed' }],
  }, { plugins: { legend: { display: false }, tooltip: moedaTooltip.plugins.tooltip }, scales: { y: { beginAtZero: true } } });

  // 14) Centros de custo POR MÊS (barras empilhadas: X = mês, uma série por centro)
  const centros = [...new Set(lista.map(t => t.centroCusto || '—'))]
    .sort((a, b) => (porCentro.get(b) || 0) - (porCentro.get(a) || 0));
  const mesesCM = [...new Set(lista.map(t => mesDeMnt(t.dataHora)).filter(Boolean))].sort();
  const matriz = new Map(); // `${mes}|${centro}` -> soma
  for (const t of lista) { const m = mesDeMnt(t.dataHora); if (!m) continue; const k = m + '|' + (t.centroCusto || '—'); matriz.set(k, (matriz.get(k) || 0) + numAbt(t.valor)); }
  desenhar('chartAbtCentroMes', 'bar', {
    labels: mesesCM.map(rotuloMes),
    datasets: centros.map((c, i) => ({
      label: trunc(c, 18),
      data: mesesCM.map(m => Math.round(matriz.get(m + '|' + c) || 0)),
      backgroundColor: CORES_ABT[i % CORES_ABT.length],
    })),
  }, { plugins: { legend: { position: 'bottom' }, tooltip: moedaTooltip.plugins.tooltip }, scales: { x: { stacked: true }, y: { stacked: true, beginAtZero: true } } });
}

// ----- Sub-aba Alertas (transações suspeitas) -----
function renderAlertasAbt(pre, ctx = contextoAlertasAbt()) {
  const transacoes = (pre || abtFiltrados(ctx)).map(t => ({ tipo: 'Transação', t, motivos: motivosAlertaTransacaoAbt(t, ctx) }))
    .filter(a => a.motivos.length);
  const semAbastecimento = alertasSemAbastecimentoAbt(ctx);
  const lista = [...transacoes, ...semAbastecimento].sort((a, b) => numAbt(b.t && b.t.valor) - numAbt(a.t && a.t.valor));
  const totGasto = transacoes.reduce((s, a) => s + numAbt(a.t.valor), 0);
  const motivoTxt = (a) => a.motivos.join(' · ');
  const consumo = lista.filter(a => /CONSUMO FORA/i.test(motivoTxt(a))).length;
  const odometro = lista.filter(a => /OD[ÔO]METRO/i.test(motivoTxt(a))).length;
  const sobrepreco = lista.filter(a => /LITRO ACIMA|PRE[ÇC]O|SOBREPRE/i.test(motivoTxt(a))).length;
  const tanque = lista.filter(a => /TANQUE ACIMA/i.test(motivoTxt(a))).length;
  const semAbt = lista.filter(a => /SEM ABASTECIMENTO/i.test(motivoTxt(a))).length;
  const duplicados = lista.filter(a => /DUPLICADO/i.test(motivoTxt(a))).length;
  document.getElementById('cardsAlertaAbt').innerHTML = `
    ${cardV2('Alertas automáticos', lista.length, lista.length ? 'red' : '')}
    ${cardV2('Gasto em alertas', fmtMoneyDec(totGasto), 'amber', true)}
    ${cardV2('Consumo fora padrão', consumo, consumo ? 'red' : '')}
    ${cardV2('Odômetro menor', odometro, odometro ? 'red' : '')}
    ${cardV2('Sobrepreço', sobrepreco, '')}
    ${cardV2('Tanque excedido', tanque, '')}
    ${cardV2('Sem abastecimento', semAbt, semAbt ? 'amber' : '')}
    ${cardV2('Possíveis duplicados', duplicados, duplicados ? 'red' : '')}
  `;
  const vazio = document.getElementById('alertaAbtVazio');
  const corpo = document.getElementById('corpoAlertaAbt');
  if (!lista.length) { corpo.innerHTML = ''; document.getElementById('cabecalhoAlertaAbt').innerHTML = ''; vazio.hidden = false; return; }
  vazio.hidden = true;
  document.getElementById('cabecalhoAlertaAbt').innerHTML =
    '<th class="col-acoes">Ações</th><th>Tipo</th><th>Data/Hora</th><th data-campo="placa">Placa</th><th>Motorista/Centro</th><th>Posto</th><th>Combustível</th><th class="num">Litros</th><th class="num">R$/L</th><th class="num">Odômetro</th><th class="num">Km/L</th><th class="num">Valor</th><th>Motivos</th>';
  corpo.innerHTML = lista.map(a => {
    const t = a.t || {};
    const v = a.veiculo || veiculoAbt(a.placa);
    const placa = placaAbt(t.placa || a.placa);
    const acoes = `<button class="btn btn-ghost icone-only placa-btn" data-placa="${esc(placa)}" title="Ver histórico da placa" aria-label="Ver histórico da placa">${ICONE_OLHO}</button>` +
      (t.id ? `<button class="edit edit-abt" data-id="${esc(t.id)}" title="Editar transação" aria-label="Editar transação">${ICONE_LAPIS}</button>` +
        `<button class="del del-abt" data-id="${esc(t.id)}" title="Excluir transação" aria-label="Excluir transação">${ICONE_LIXEIRA}</button>` : '');
    return `<tr>
    <td class="acoes">${acoes}</td>
    <td>${esc(a.tipo)}</td>
    <td>${esc(t.dataHora || a.dataHora || '—')}</td>
    <td><button class="placa-btn placa-chip" data-placa="${esc(placa)}" title="Ver histórico desta placa">${esc(placa)}</button></td>
    <td>${esc(t.motorista || (v && v.centroCusto) || '—')}</td>
    <td>${esc(t.posto || '—')}</td>
    <td>${esc(t.combustivel || '—')}</td>
    <td class="num">${t.id ? fmtLitros(t.litros) : '—'}</td>
    <td class="num">${t.id ? fmtRSL(precoLitroAbt(t)) : '—'}</td>
    <td class="num">${numAbt(t.odometro) ? fmtKm(t.odometro) : '—'}</td>
    <td class="num">${t.id ? fmtKmL(t.kmL) : '—'}</td>
    <td class="num">${t.id ? fmtMoneyDec(t.valor) : '—'}</td>
    <td>${esc(motivoTxt(a) || '—')}</td>
  </tr>`;
  }).join('');
}

// ----- Sub-abas (Por veículo | Transações | Dashboards | Alertas) -----
function trocarSubAbt(sub) {
  const alvo = document.querySelector(`#abastecimentoSubtabs .subtab[data-sub="${sub}"]`);
  if (!alvo) return;
  subAbtAtiva = sub;
  document.querySelectorAll('#abastecimentoSubtabs .subtab').forEach(x => x.classList.remove('active'));
  document.querySelectorAll('#abastecimento .subview').forEach(x => x.classList.remove('active'));
  alvo.classList.add('active');
  document.getElementById(sub).classList.add('active');
  renderAbastecimento();
}
document.querySelectorAll('#abastecimentoSubtabs .subtab').forEach(b => b.onclick = () => { if (!b.classList.contains('active')) trocarSubAbt(b.dataset.sub); });

// ----- Filtros -----
function filtrarAbt() { abtPagina = 1; renderAbastecimento(); }
document.getElementById('buscaAbt').addEventListener('input', debounce(filtrarAbt));
document.getElementById('buscaAbtVeic').addEventListener('input', debounce(() => { abtVeicBusca = document.getElementById('buscaAbtVeic').value.trim().toLowerCase(); renderPorVeiculoAbt(); }));
[['fabtPlaca', 'Placa'], ['fabtPeriodo', 'Período'], ['fabtCentro', 'Centro de custo'], ['fabtMotorista', 'Motorista'], ['fabtPosto', 'Posto'], ['fabtCombustivel', 'Combustível'], ['fabtAlerta', 'Alerta']]
  .forEach(([fid, rot]) => criarMultiSelect(fid, rot, filtrarAbt));
document.getElementById('btnLimparAbt').onclick = () => {
  document.getElementById('buscaAbt').value = '';
  document.getElementById('buscaAbtVeic').value = '';
  abtVeicBusca = '';
  ['fabtPlaca', 'fabtPeriodo', 'fabtCentro', 'fabtMotorista', 'fabtPosto', 'fabtCombustivel', 'fabtAlerta'].forEach(fid => MSEL[fid] && MSEL[fid].limpar());
  filtrarAbt();
};
document.getElementById('abtPorPagina').onchange = () => { abtPagina = 1; renderTransacoesAbt(); };
document.getElementById('abtPagPrev').onclick = () => { if (abtPagina > 1) { abtPagina--; renderTransacoesAbt(); } };
_pagCtl.abt = { irPara: (n) => { abtPagina = n; renderTransacoesAbt(); } };
document.getElementById('abtPagNext').onclick = () => { abtPagina++; renderTransacoesAbt(); };
document.getElementById('selBarAbtLimpar').onclick = () => { SELECAO_ABT.clear(); renderTransacoesAbt(); };
document.getElementById('selBarAbtExportar').onclick = () => {
  const ids = [...SELECAO_ABT];
  if (!ids.length) return;
  window.location = '/api/abastecimento/exportar?ids=' + encodeURIComponent(ids.join(','));
};

// Clique na placa (qualquer sub-aba) = abre painel de histórico. Editar/excluir.
document.getElementById('abastecimento').addEventListener('click', (e) => {
  const pb = e.target.closest('.placa-btn');
  if (pb) { e.stopPropagation(); abrirAbtVeiculo(pb.dataset.placa); return; }
  const ed = e.target.closest('.edit-abt'); if (ed) { abrirAbtModal(ed.dataset.id); return; }
  const del = e.target.closest('.del-abt'); if (del) { excluirAbt(del.dataset.id); return; }
  // Toque/clique na área livre da linha (tabela de transações) seleciona/deseleciona.
  if (e.target.closest('button, input, select, textarea, a, .pill-select')) return;
  const tr = e.target.closest('#corpoAbt tr'); if (!tr || !tr.dataset.id) return;
  const id = tr.dataset.id;
  if (SELECAO_ABT.has(id)) SELECAO_ABT.delete(id); else SELECAO_ABT.add(id);
  tr.classList.toggle('sel-on', SELECAO_ABT.has(id));
  atualizarBarraSelAbt();
});

// ----- Modal de transação (add/editar) -----
const formAbt = document.getElementById('formAbt');
function abrirAbtModal(id) {
  editandoAbtId = id || null;
  formAbt.reset();
  document.getElementById('abtTitulo').textContent = id ? 'Editar transação' : 'Nova transação';
  if (id) {
    const t = ABASTECIMENTO.find(x => x.id === id);
    if (t) for (const campo of Object.keys(t)) { if (formAbt.elements[campo] !== undefined && formAbt.elements[campo]) formAbt.elements[campo].value = t[campo] ?? ''; }
  }
  document.getElementById('abtModal').hidden = false;
  formAbt.elements['placa'].focus();
}
function fecharAbtModal() { document.getElementById('abtModal').hidden = true; }
document.getElementById('btnAddAbt').onclick = () => abrirAbtModal(null);
document.getElementById('fecharAbt').onclick = fecharAbtModal;
document.getElementById('cancelarAbt').onclick = fecharAbtModal;
fecharAoClicarNoFundo('abtModal', fecharAbtModal);
formAbt.addEventListener('submit', async (e) => {
  e.preventDefault();
  const dados = {};
  for (const el of formAbt.elements) if (el.name) dados[el.name] = el.value;
  if (editandoAbtId) dados.id = editandoAbtId;
  const url = editandoAbtId ? '/api/abastecimento/' + encodeURIComponent(editandoAbtId) : '/api/abastecimento';
  const r = await fetch(url, { method: editandoAbtId ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(dados) });
  if (!r.ok) { const j = await r.json().catch(() => ({})); return toast(j.erro || 'Erro ao salvar.', 'erro'); }
  fecharAbtModal();
  await carregarAbastecimento();
  toast(editandoAbtId ? 'Transação atualizada!' : 'Transação adicionada!', 'ok');
});
async function excluirAbt(id) {
  const t = ABASTECIMENTO.find(x => x.id === id);
  if (!(await confirmar(`Excluir esta transação de abastecimento${t ? ` (${esc(t.placa)})` : ''}?`, { perigo: true, okTexto: 'Excluir' }))) return;
  const r = await fetch('/api/abastecimento/' + encodeURIComponent(id), { method: 'DELETE' });
  if (!r.ok) { const j = await r.json().catch(() => ({})); return toast(j.erro || 'Erro ao excluir.', 'erro'); }
  await carregarAbastecimento();
  toast('Transação excluída.', 'ok');
}

// ----- Importar / exportar / backups -----
_exporta('btnExportAbt', '/api/abastecimento/exportar');
document.getElementById('btnImportAbt').onclick = () => document.getElementById('inputImportAbt').click();
document.getElementById('inputImportAbt').onchange = async (e) => {
  const files = [...e.target.files]; e.target.value = '';
  if (!files.length) return;
  const nomes = files.length === 1 ? `“${files[0].name}”` : `${files.length} planilhas`;
  if (!(await confirmar(`Importar ${nomes}? As transações são somadas às existentes, sem duplicar (um backup é feito antes).`, { okTexto: 'Importar' }))) return;
  const fd = new FormData();
  for (const f of files) fd.append('arquivos', f);
  toast(files.length > 1 ? 'Importando planilhas...' : 'Importando planilha...', '');
  try {
    const r = await fetch('/api/abastecimento/importar', { method: 'POST', body: fd });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) { toast(j.erro || 'Erro ao importar.', 'erro'); return; }
    await carregarAbastecimento();
    let msg = `Importado: ${j.criados} nova(s)`;
    if (j.ignorados) msg += ` · ${j.ignorados} já existia(m)`;
    msg += ` · ${j.veiculos} veículos`;
    if (j.datasAjustadas) msg += ` · ${j.datasAjustadas} data(s) ajustada(s) pelo mês da aba`;
    toast(msg, j.criados ? 'ok' : '');
  } catch (err) {
    toast('Falha de conexão ao importar. Tente novamente.', 'erro');
  }
};
document.getElementById('btnBackupsAbt').onclick = () => abrirBackups('abastecimento');

/* ============================================================
   PWA; registra o service worker e oferece "Adicionar à tela inicial"
   (Android/Chrome via beforeinstallprompt; iOS Safari via instruções)
   ============================================================ */
(function () {
  if ('serviceWorker' in navigator) {
    window.addEventListener('load', () => navigator.serviceWorker.register('/sw.js').catch(() => {}));
  }
  const banner = document.getElementById('installBanner');
  if (!banner) return;
  const btnAdd = document.getElementById('btnInstalarAgora');
  const btnNao = document.getElementById('btnInstalarDispensar');
  const txt = document.getElementById('installTexto');
  const DISMISS_KEY = 'pwaInstalarAdiadoAte';

  const jaInstalado = () => window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;
  const adiado = () => { const t = Number(localStorage.getItem(DISMISS_KEY) || 0); return t && Date.now() < t; };
  const adiar = (dias) => { try { localStorage.setItem(DISMISS_KEY, String(Date.now() + dias * 864e5)); } catch (e) { /* ignora */ } };
  const ehIOS = () => /iphone|ipad|ipod/i.test(navigator.userAgent) && !window.MSStream;
  const ehSafari = () => /^((?!chrome|android|crios|fxios).)*safari/i.test(navigator.userAgent);
  // Só oferece a instalação no celular: tela estreita + ponteiro grosso (toque), ou UA mobile.
  const ehCelular = () => /android|iphone|ipad|ipod|mobile/i.test(navigator.userAgent)
    || (window.matchMedia('(max-width: 760px)').matches && window.matchMedia('(pointer: coarse)').matches);

  let deferredPrompt = null;
  const mostrar = () => { if (ehCelular() && !jaInstalado() && !adiado()) banner.hidden = false; };
  const esconder = () => { banner.hidden = true; };

  // Android/Chrome (e desktop): captura o evento para disparar o prompt nativo no clique.
  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredPrompt = e;
    btnAdd.hidden = false;
    txt.textContent = 'Instale o Gestão RM para abrir como um app, em tela cheia.';
    setTimeout(mostrar, 1500); // não atrapalha o login/carregamento
  });

  // iOS Safari: sem API de instalação → mostra o passo a passo manual.
  if (ehIOS() && ehSafari()) {
    btnAdd.hidden = true;
    txt.innerHTML = 'Para instalar: toque em <b>Compartilhar</b> e depois em <b>“Adicionar à Tela de Início”</b>.';
    setTimeout(mostrar, 2500);
  }

  btnAdd.onclick = async () => {
    if (!deferredPrompt) { esconder(); return; }
    deferredPrompt.prompt();
    try { await deferredPrompt.userChoice; } catch (e) { /* ignora */ }
    deferredPrompt = null;
    esconder();
  };
  btnNao.onclick = () => { adiar(14); esconder(); }; // não pergunta de novo por 14 dias
  window.addEventListener('appinstalled', () => { esconder(); adiar(3650); });
})();

// (ago/2026: os mecanismos mobile — topbar que se esconde ao rolar, tabelas→cards
// com rotularParaCards/TABELAS_COMPACTAS e rolagem de sub-aba — foram removidos a
// pedido do dono; o visual do celular será reconstruído do zero.)

// Acessibilidade: marca os modais como diálogos ARIA e nomeia os campos de busca/data (1x no boot).
(function a11yInit() {
  // Modais → role=dialog + aria-modal + aria-labelledby (título da .modal-head)
  document.querySelectorAll('.modal-overlay > .modal').forEach((m) => {
    m.setAttribute('role', 'dialog');
    m.setAttribute('aria-modal', 'true');
    const titulo = m.querySelector('.modal-head h2, .modal-head h3, h2, h3');
    if (titulo) {
      if (!titulo.id) { const ov = m.closest('.modal-overlay'); titulo.id = (ov && ov.id ? ov.id : 'modal') + 'Titulo'; }
      m.setAttribute('aria-labelledby', titulo.id);
    }
  });
  // Campos de busca (type=search) sem rótulo: usa o placeholder (sem o emoji) como aria-label
  document.querySelectorAll('input[type=search]').forEach((i) => {
    if (i.getAttribute('aria-label')) return;
    const t = (i.placeholder || '').replace(/^[\s\u{1F000}-\u{1FAFF}☀-➿️]+/u, '').trim();
    i.setAttribute('aria-label', t || 'Buscar');
  });
})();

