/* ============================================================
   DATE PICKER pt-BR; calendário próprio para TODOS os <input type="date">.
   Por que existe: o seletor nativo segue o locale do navegador (vira mm/dd/yyyy)
   e a navegação por ANO é ruim (péssimo p/ data de nascimento). Aqui mantemos o
   input nativo como fonte do valor (ISO yyyy-mm-dd); a lógica do sistema não muda —
   e só trocamos o seletor por um calendário em português, com pulo rápido de mês/ano,
   ícone de calendário ao lado e tema do app. Sem dependências. Pega inputs criados
   dinamicamente (linhas de EPI, validade de documentos, etc.) via MutationObserver.
   ============================================================ */
(function () {
  const MESES = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];
  const DOW = ['D', 'S', 'T', 'Q', 'Q', 'S', 'S'];
  let pop = null, alvo = null, ancora = null; // alvo = input nativo (valor ISO); ancora = elemento p/ posicionar (proxy ou o próprio)
  let view = { ano: 0, mes: 0, modo: 'dias' }; // modo: dias | meses | anos
  const pad = (n) => String(n).padStart(2, '0');
  const hojeISO = () => { const d = new Date(); return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`; };
  const parseISO = (v) => { const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(v || ''); return m ? { a: +m[1], me: +m[2] - 1, d: +m[3] } : null; };
  // ----- Conversões e validação no formato brasileiro (dd/mm/aaaa) -----
  const isoParaBR = (iso) => { const p = parseISO(iso); return p ? `${pad(p.d)}/${pad(p.me + 1)}/${p.a}` : ''; };
  const ehDataValida = (d, m, a) => { const dt = new Date(a, m - 1, d); return dt.getFullYear() === a && dt.getMonth() === m - 1 && dt.getDate() === d; };
  const brParaISO = (br) => { const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(br || ''); if (!m) return ''; const d = +m[1], mo = +m[2], a = +m[3]; return ehDataValida(d, mo, a) ? `${a}-${pad(mo)}-${pad(d)}` : ''; };
  // Vai formatando enquanto digita: só dígitos, insere as barras (dd/mm/aaaa), no máx. 8 dígitos.
  const mascararBR = (v) => { const n = String(v).replace(/\D/g, '').slice(0, 8); let o = n.slice(0, 2); if (n.length > 2) o += '/' + n.slice(2, 4); if (n.length > 4) o += '/' + n.slice(4, 8); return o; };
  // Lê o valor ISO "cru" do input nativo sem passar pelo getter sobrescrito.
  const descValue = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value');
  const isoCru = (nativo) => descValue.get.call(nativo);

  function garante() {
    if (pop) return;
    pop = document.createElement('div');
    pop.className = 'dp-cal'; pop.hidden = true;
    document.body.appendChild(pop);
    pop.addEventListener('mousedown', (e) => e.preventDefault()); // não rouba foco
    pop.addEventListener('click', onClick);
  }
  function abrir(nativo, anchor) {
    garante(); alvo = nativo; ancora = anchor || nativo;
    const p = parseISO(isoCru(nativo)) || parseISO(hojeISO());
    view = { ano: p.a, mes: p.me, modo: 'dias' };
    render(); posicionar(ancora); pop.hidden = false;
    document.addEventListener('mousedown', onForaDown, true);
    document.addEventListener('keydown', onKey, true);
  }
  function fechar() {
    if (!pop || pop.hidden) return;
    pop.hidden = true; alvo = null; ancora = null;
    document.removeEventListener('mousedown', onForaDown, true);
    document.removeEventListener('keydown', onKey, true);
  }
  function onForaDown(e) { if (pop && !pop.contains(e.target) && e.target !== alvo && e.target !== ancora) fechar(); }
  function onKey(e) { if (e.key === 'Escape') fechar(); }
  function posicionar(anchor) {
    ancorarMenuFixo(anchor.getBoundingClientRect(), pop, pop.offsetWidth || 268);
    pop.style.visibility = '';
  }
  // Grava o ISO no input nativo (o setter sobrescrito sincroniza o proxy) e avisa o app.
  function definir(iso) { alvo.value = iso; alvo.dispatchEvent(new Event('input', { bubbles: true })); alvo.dispatchEvent(new Event('change', { bubbles: true })); }
  function render() {
    if (view.modo === 'anos') return renderAnos();
    if (view.modo === 'meses') return renderMeses();
    renderDias();
  }
  function renderDias() {
    const { ano, mes } = view;
    const sel = parseISO(alvo ? isoCru(alvo) : ''), hoje = parseISO(hojeISO());
    const primeiro = new Date(ano, mes, 1).getDay(), nDias = new Date(ano, mes + 1, 0).getDate();
    let cels = '';
    for (let i = 0; i < primeiro; i++) cels += '<span class="dp-d dp-vazio"></span>';
    for (let d = 1; d <= nDias; d++) {
      const iso = `${ano}-${pad(mes + 1)}-${pad(d)}`;
      const s = sel && sel.a === ano && sel.me === mes && sel.d === d;
      const h = hoje.a === ano && hoje.me === mes && hoje.d === d;
      cels += `<button type="button" class="dp-d${s ? ' sel' : ''}${h ? ' hoje' : ''}" data-dia="${iso}">${d}</button>`;
    }
    pop.innerHTML = `
      <div class="dp-cab">
        <button type="button" class="dp-nav" data-nav="ma-" title="Ano anterior">«</button>
        <button type="button" class="dp-nav" data-nav="me-" title="Mês anterior">‹</button>
        <button type="button" class="dp-titulo" data-ver="meses" title="Escolher mês/ano">${MESES[mes]} ${ano}</button>
        <button type="button" class="dp-nav" data-nav="me+" title="Próximo mês">›</button>
        <button type="button" class="dp-nav" data-nav="ma+" title="Próximo ano">»</button>
      </div>
      <div class="dp-dow">${DOW.map((d) => `<span>${d}</span>`).join('')}</div>
      <div class="dp-grade">${cels}</div>
      <div class="dp-rod"><button type="button" class="dp-acao" data-hoje="1">Hoje</button><button type="button" class="dp-acao dp-mut" data-limpar="1">Limpar</button></div>`;
  }
  function renderMeses() {
    pop.innerHTML = `
      <div class="dp-cab">
        <button type="button" class="dp-nav" data-nav="ma-" title="Ano anterior">‹</button>
        <button type="button" class="dp-titulo" data-ver="anos">${view.ano}</button>
        <button type="button" class="dp-nav" data-nav="ma+" title="Próximo ano">›</button>
      </div>
      <div class="dp-meses">${MESES.map((m, i) => `<button type="button" class="dp-cel${i === view.mes ? ' sel' : ''}" data-mes="${i}">${m.slice(0, 3)}</button>`).join('')}</div>`;
  }
  function renderAnos() {
    const base = view.ano - (view.ano % 12); let cels = '';
    for (let i = 0; i < 12; i++) { const a = base + i; cels += `<button type="button" class="dp-cel${a === view.ano ? ' sel' : ''}" data-ano="${a}">${a}</button>`; }
    pop.innerHTML = `
      <div class="dp-cab">
        <button type="button" class="dp-nav" data-nav="dec-" title="Anteriores">‹</button>
        <button type="button" class="dp-titulo">${base}–${base + 11}</button>
        <button type="button" class="dp-nav" data-nav="dec+" title="Próximos">›</button>
      </div>
      <div class="dp-anos">${cels}</div>`;
  }
  function onClick(e) {
    const t = e.target.closest('button'); if (!t || !alvo) return;
    if (t.dataset.dia) { definir(t.dataset.dia); fechar(); return; }
    if (t.dataset.hoje) { definir(hojeISO()); fechar(); return; }
    if (t.dataset.limpar) { definir(''); fechar(); return; }
    if (t.dataset.ver) { view.modo = t.dataset.ver; render(); posicionar(ancora); return; }
    if (t.dataset.mes != null) { view.mes = +t.dataset.mes; view.modo = 'dias'; render(); posicionar(ancora); return; }
    if (t.dataset.ano != null) { view.ano = +t.dataset.ano; view.modo = 'meses'; render(); posicionar(ancora); return; }
    const nav = t.dataset.nav; if (!nav) return;
    if (nav === 'me-') { if (--view.mes < 0) { view.mes = 11; view.ano--; } }
    else if (nav === 'me+') { if (++view.mes > 11) { view.mes = 0; view.ano++; } }
    else if (nav === 'ma-') view.ano--;
    else if (nav === 'ma+') view.ano++;
    else if (nav === 'dec-') view.ano -= 12;
    else if (nav === 'dec+') view.ano += 12;
    render(); posicionar(ancora);
  }
  // Abre/fecha o calendário ao clicar no ÍCONE (faixa à direita). No resto do campo, clique normal.
  const cliqueNoIcone = (el, e) => { const r = el.getBoundingClientRect(); return e.clientX >= r.right - 34; };

  // Campos do FORMULÁRIO (têm name; o app lê o valor por name esperando ISO): troca o seletor
  // nativo por um campo de texto dd/mm/aaaa DIGITÁVEL. O input nativo continua existindo (oculto)
  // como fonte do valor ISO — então nada da lógica de salvar/validar muda.
  function criaProxyData(nativo, copiarClasses) {
    const proxy = document.createElement('input');
    proxy.type = 'text';
    proxy.className = copiarClasses && nativo.className ? `${nativo.className} dp-input` : 'dp-input';
    proxy.inputMode = 'numeric';
    proxy.maxLength = 10;
    proxy.placeholder = 'dd/mm/aaaa';
    proxy.autocomplete = 'off';
    proxy.value = isoParaBR(isoCru(nativo));
    if (nativo.disabled) proxy.disabled = true;
    const aria = nativo.getAttribute('aria-label');
    if (aria) proxy.setAttribute('aria-label', aria);
    if (nativo.title) proxy.title = nativo.title;
    nativo._dpProxy = proxy; proxy._dpNativo = nativo;
    nativo.after(proxy);
    return proxy;
  }
  function sincronizarProxyAoSetarValor(nativo) {
    Object.defineProperty(nativo, 'value', {
      configurable: true,
      get() { return descValue.get.call(this); },
      set(v) { descValue.set.call(this, v); if (this._dpProxy) this._dpProxy.value = isoParaBR(descValue.get.call(this)); },
    });
  }
  function preparaNomeado(nativo) {
    nativo.style.display = 'none';
    nativo.removeAttribute('required'); // a validação é feita em JS; evita "campo não focável" (oculto)
    const proxy = criaProxyData(nativo, false);
    // Setter sobrescrito: quando o app faz `input.value = '2020-03-10'`, o proxy reflete em dd/mm/aaaa.
    sincronizarProxyAoSetarValor(nativo);
    // Digitação: máscara dd/mm/aaaa + grava ISO no nativo (vazio se ainda inválido/incompleto).
    proxy.addEventListener('input', () => {
      proxy.value = mascararBR(proxy.value);
      descValue.set.call(nativo, brParaISO(proxy.value));
      nativo.dispatchEvent(new Event('change', { bubbles: true }));
    });
    // Ao sair do campo: normaliza para o valor válido do nativo (limpa o que ficou inválido/incompleto).
    proxy.addEventListener('blur', () => { proxy.value = isoParaBR(isoCru(nativo)); });
    proxy.addEventListener('mousedown', (e) => { if (cliqueNoIcone(proxy, e)) { e.preventDefault(); (pop && !pop.hidden && alvo === nativo) ? fechar() : abrir(nativo, proxy); } });
    proxy.addEventListener('keydown', (e) => { if (e.altKey && e.key === 'ArrowDown') { e.preventDefault(); abrir(nativo, proxy); } });
  }

  // Campos inline que salvam no onchange (Comprados/Vendidos): so avisa o app
  // quando a data estiver completa/valida ou quando o campo for limpo.
  function preparaInlineTexto(nativo) {
    nativo.style.display = 'none';
    const proxy = criaProxyData(nativo, true);
    sincronizarProxyAoSetarValor(nativo);
    const avisarSeMudou = (iso) => {
      if (isoCru(nativo) === iso) return;
      descValue.set.call(nativo, iso);
      nativo.dispatchEvent(new Event('input', { bubbles: true }));
      nativo.dispatchEvent(new Event('change', { bubbles: true }));
    };
    proxy.addEventListener('input', () => {
      proxy.value = mascararBR(proxy.value);
      const digitos = proxy.value.replace(/\D/g, '');
      const iso = brParaISO(proxy.value);
      if (iso) { avisarSeMudou(iso); return; }
      if (!digitos.length) avisarSeMudou('');
    });
    proxy.addEventListener('blur', () => { proxy.value = isoParaBR(isoCru(nativo)); });
    proxy.addEventListener('mousedown', (e) => { if (cliqueNoIcone(proxy, e)) { e.preventDefault(); (pop && !pop.hidden && alvo === nativo) ? fechar() : abrir(nativo, proxy); } });
    proxy.addEventListener('keydown', (e) => { if (e.altKey && e.key === 'ArrowDown') { e.preventDefault(); abrir(nativo, proxy); } });
  }

  // Demais campos inline sem name (lidos por classe com valor ISO, ex.: EPI):
  // mantem o input nativo e so adiciona o icone + calendario proprio.
  function preparaInline(input) {
    input.classList.add('dp-input');
    input.addEventListener('mousedown', (e) => { if (cliqueNoIcone(input, e)) { e.preventDefault(); (pop && !pop.hidden && alvo === input) ? fechar() : abrir(input, input); } });
    input.addEventListener('keydown', (e) => { if (e.altKey && e.key === 'ArrowDown') { e.preventDefault(); abrir(input, input); } });
  }
  // Filtros de data (barras de filtro, sem name): campo SEGMENTADO dd/mm/aaaa no padrão
  // HeroUI DateField — mesmo visual em qualquer navegador (o seletor nativo muda entre
  // Chrome e Firefox). Dígitos avançam sozinhos, setas incrementam, Backspace limpa,
  // e o ícone abre o MESMO calendário popover dos demais campos.
  function preparaSegmentado(nativo) {
    // type="date" → dd/mm/aaaa com calendário; type="month" → mm/aaaa sem calendário
    // (o popover dp escreve dia; e o Firefox nem renderiza month nativo, vira caixa de texto).
    // Checar pelo ATRIBUTO: no Firefox a propriedade .type de um month não suportado vira "text".
    const soMes = nativo.getAttribute('type') === 'month';
    nativo.style.display = 'none';
    const grupo = document.createElement('span');
    grupo.className = 'hdate' + (soMes ? ' so-mes' : '');
    const segHTML = (k, rot, min, max, place) =>
      `<span class="hdate-seg" data-seg="${k}" role="spinbutton" tabindex="0" aria-label="${rot}" aria-valuemin="${min}" aria-valuemax="${max}">${place}</span>`;
    grupo.innerHTML =
      (soMes ? '' :
        '<button type="button" class="hdate-ico" aria-label="Abrir calendário" tabindex="-1">' +
          '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 10h18"/></svg>' +
        '</button>' +
        segHTML('d', 'Dia', 1, 31, 'dd') + '<span class="hdate-sep" aria-hidden="true">/</span>') +
      segHTML('m', 'Mês', 1, 12, 'mm') + '<span class="hdate-sep" aria-hidden="true">/</span>' +
      segHTML('a', 'Ano', 1900, 2100, 'aaaa');
    nativo.after(grupo);
    const segs = { d: grupo.querySelector('[data-seg="d"]'), m: grupo.querySelector('[data-seg="m"]'), a: grupo.querySelector('[data-seg="a"]') };
    const LIM = { d: [1, 31], m: [1, 12], a: [1900, 2100] };
    const PLACE = { d: 'dd', m: 'mm', a: 'aaaa' };
    const ORDEM = soMes ? ['m', 'a'] : ['d', 'm', 'a'];
    const est = { d: null, m: null, a: null };
    let buf = '', bufSeg = '';

    function pintar() {
      for (const k of ORDEM) {
        const el = segs[k], v = est[k];
        if (v == null) { el.textContent = PLACE[k]; el.dataset.placeholder = '1'; el.removeAttribute('aria-valuenow'); }
        else { el.textContent = k === 'a' ? String(v).padStart(4, '0') : pad(v); delete el.dataset.placeholder; el.setAttribute('aria-valuenow', String(v)); }
      }
    }
    function lerDoNativo() {
      if (soMes) {
        const mm = /^(\d{4})-(\d{2})$/.exec(isoCru(nativo) || '');
        est.d = null; est.m = mm ? +mm[2] : null; est.a = mm ? +mm[1] : null;
      } else {
        const p = parseISO(isoCru(nativo));
        est.d = p ? p.d : null; est.m = p ? p.me + 1 : null; est.a = p ? p.a : null;
      }
      buf = ''; bufSeg = '';
      grupo.classList.remove('invalida');
      pintar();
    }
    // Só grava no nativo quando a data está completa e válida; parcial/limpa grava ''.
    function commit() {
      const { d, m, a } = est;
      const completo = (soMes || d != null) && m != null && a != null && a >= 1000;
      const valida = completo && (soMes || ehDataValida(d, m, a));
      grupo.classList.toggle('invalida', completo && !valida);
      const iso = valida ? (soMes ? `${a}-${pad(m)}` : `${a}-${pad(m)}-${pad(d)}`) : '';
      if (isoCru(nativo) === iso) return;
      descValue.set.call(nativo, iso);
      nativo.dispatchEvent(new Event('input', { bubbles: true }));
      nativo.dispatchEvent(new Event('change', { bubbles: true }));
    }
    function focoViz(k, passo) {
      const i = ORDEM.indexOf(k) + passo;
      if (i >= 0 && i < ORDEM.length) segs[ORDEM[i]].focus();
    }
    function aoDigito(k, dig) {
      if (bufSeg !== k) { buf = ''; bufSeg = k; }
      const hi = LIM[k][1];
      let novo = parseInt(buf + dig, 10);
      if (novo > hi) { buf = ''; novo = parseInt(dig, 10); }
      buf += dig;
      est[k] = novo;
      pintar(); commit();
      if (novo * 10 > hi || buf.length >= String(hi).length) { buf = ''; bufSeg = ''; focoViz(k, 1); }
    }
    function incrementa(k, delta) {
      const [lo, hi] = LIM[k];
      const agora = new Date();
      const padrao = k === 'a' ? agora.getFullYear() : (k === 'm' ? agora.getMonth() + 1 : agora.getDate());
      let v = est[k] == null ? padrao : est[k] + delta;
      if (v > hi) v = lo; if (v < lo) v = hi;
      est[k] = v; buf = ''; bufSeg = '';
      pintar(); commit();
    }
    grupo.addEventListener('keydown', (e) => {
      const seg = e.target.closest('.hdate-seg'); if (!seg) return;
      const k = seg.dataset.seg;
      if (e.altKey && e.key === 'ArrowDown') { e.preventDefault(); if (!soMes) abrir(nativo, grupo); return; }
      if (/^\d$/.test(e.key)) { e.preventDefault(); aoDigito(k, e.key); return; }
      if (e.key === 'ArrowUp') { e.preventDefault(); incrementa(k, 1); return; }
      if (e.key === 'ArrowDown') { e.preventDefault(); incrementa(k, -1); return; }
      if (e.key === 'ArrowLeft') { e.preventDefault(); focoViz(k, -1); return; }
      if (e.key === 'ArrowRight' || e.key === '/') { e.preventDefault(); focoViz(k, 1); return; }
      if (e.key === 'Backspace' || e.key === 'Delete') { e.preventDefault(); est[k] = null; buf = ''; bufSeg = ''; pintar(); commit(); }
    });
    grupo.addEventListener('mousedown', (e) => {
      if (e.target.closest('.hdate-ico')) {
        e.preventDefault();
        (pop && !pop.hidden && alvo === nativo) ? fechar() : abrir(nativo, grupo);
        return;
      }
      if (!e.target.closest('.hdate-seg')) {
        e.preventDefault();
        (ORDEM.map((k) => segs[k]).find((s) => s.dataset.placeholder) || segs[ORDEM[0]]).focus();
      }
    });
    grupo.addEventListener('focusout', () => { buf = ''; bufSeg = ''; });
    // `input.value = ...` por código (chips de período, limpar filtros) repinta os segmentos.
    Object.defineProperty(nativo, 'value', {
      configurable: true,
      get() { return descValue.get.call(this); },
      set(v) { descValue.set.call(this, v); lerDoNativo(); },
    });
    nativo._dpRepintar = lerDoNativo;
    lerDoNativo();
  }
  function prepara(input) {
    if (input.dataset.dp) return;
    input.dataset.dp = '1';
    if (input.getAttribute('type') === 'month' || input.closest('.almox-data')) return preparaSegmentado(input);
    input.name ? preparaNomeado(input) : (input.dataset.dpText === '1' ? preparaInlineTexto(input) : preparaInline(input));
  }
  // Além dos campos de data, os filtros de MÊS (De/Até do Custos) também viram segmentados —
  // o Firefox não desenha input[type="month"] (cai numa caixa de texto crua).
  const varrer = (root) => {
    const r = root || document;
    r.querySelectorAll('input[type="date"]:not([data-dp])').forEach(prepara);
    r.querySelectorAll('.cst-filtro-mes input[type="month"]:not([data-dp])').forEach(prepara);
  };
  varrer();
  new MutationObserver((muts) => { for (const m of muts) for (const n of m.addedNodes) { if (n.nodeType === 1) { (n.matches && n.matches('input[type="date"]')) ? prepara(n) : (n.querySelectorAll && varrer(n)); } } })
    .observe(document.documentElement, { childList: true, subtree: true });
  // form.reset() não passa pelo setter — re-sincroniza os proxies após o reset (evento borbulha).
  document.addEventListener('reset', (e) => {
    const f = e.target; if (!f || !f.querySelectorAll) return;
    setTimeout(() => f.querySelectorAll('input[type="date"][data-dp]').forEach((n) => { if (n._dpRepintar) n._dpRepintar(); else if (n._dpProxy) n._dpProxy.value = isoParaBR(isoCru(n)); }), 0);
  });
  window.addEventListener('resize', () => { if (pop && !pop.hidden && ancora) posicionar(ancora); });
})();

// ===================== LOCAÇÕES (veículos e equipamentos alugados) =====================
// Estado e ícones ficam lá no topo do arquivo: `restaurarAbaAtiva()` roda ANTES daqui e pode
// abrir a sub-aba Documentos (deep-link /locacoes/documentos), que já renderiza usando LOC_EST.

// Tipos de item locado (espelho de TIPOS_LOCACAO no servidor). Veículo tem placa; os demais têm
// `identificacao` (nº de série/patrimônio, opcional). Registro antigo sem `tipo` é veículo.
const TIPOS_LOC = { veiculo: 'Veículo', equipamento: 'Equipamento', ferramental: 'Ferramental', outro: 'Outro' };
const ehVeiculoLoc = (l) => !l || !l.tipo || l.tipo === 'veiculo';
const tipoRotuloLoc = (l) => TIPOS_LOC[(l && l.tipo) || 'veiculo'] || TIPOS_LOC.veiculo;
// Identificador mostrado na lista/cartão/detalhe: placa no veículo, identificação nos outros.
//   identificadorLoc({ placa: 'ABC1D23' })                              // => 'ABC1D23'
//   identificadorLoc({ tipo: 'ferramental', identificacao: 'PAT-0451' }) // => 'PAT-0451'
const identificadorLoc = (l) => ehVeiculoLoc(l) ? String((l && l.placa) || '') : String((l && l.identificacao) || '');
const rotuloLoc = (l) => [l && l.modelo, identificadorLoc(l)].filter(Boolean).join(' ');
// Chip clicável que abre o detalhe: placa Mercosul no veículo; nos demais um chip neutro (.id-chip)
// com a identificação ou, sem ela, o tipo ("Ferramental").
//   chipIdentificadorLoc({ id: 'loc-1', tipo: 'ferramental' })  // => <button class="placa-btn placa-chip id-chip" …>Ferramental</button>
function chipIdentificadorLoc(l, extra = '') {
  const veiculo = ehVeiculoLoc(l);
  const texto = identificadorLoc(l) || (veiculo ? '—' : tipoRotuloLoc(l));
  return '<button type="button" class="placa-btn placa-chip' + (veiculo ? '' : ' id-chip') + (extra ? ' ' + extra : '') +
    '" data-loc-det="' + esc(l.id) + '" title="Ver recebimento, IPCA aplicado e aniversário do contrato">' + esc(texto) + '</button>';
}
// Etiqueta discreta do tipo ao lado da descrição (só quando NÃO é veículo, que é o caso comum).
const tagTipoLoc = (l) => ehVeiculoLoc(l) ? '' : ' <span class="tipo-tag">' + esc(tipoRotuloLoc(l)) + '</span>';
// Reajuste anual por item (espelho de `reajusteIpca` no servidor): ausente = reajusta, como sempre.
const temReajusteLoc = (l) => !l || l.reajusteIpca !== false;
// Valor mensal de hoje: IPCA acumulado nos aniversários, ou o inicial quando o item é de valor fixo.
//   valorCorrigidoLoc({ valorInicial: 1000, dataChegada: '11/05/2025' }, { 2025: 4.5 })                        // => 1045 (após 11/05/2026)
//   valorCorrigidoLoc({ valorInicial: 1000, dataChegada: '11/05/2025', reajusteIpca: false }, { 2025: 4.5 })  // => 1000
const valorCorrigidoLoc = (l, ipca) => temReajusteLoc(l) ? ipcaAtualizado(l.valorInicial, l.dataChegada, ipca) : (Number(l.valorInicial) || 0);
const tagReajusteLoc = (l) => temReajusteLoc(l) ? '' : ' <span class="tipo-tag" title="Sem reajuste anual: o valor fica fixo">Fixo</span>';

function ipcaAtualizado(valorInicial, dataChegada, ipca) {
  if (!dataChegada || !valorInicial) return Number(valorInicial) || 0;
  const partes = dataChegada.split('/');
  if (partes.length !== 3) return Number(valorInicial) || 0;
  // dataChegada em formato BR (dd/mm/aaaa) ou ISO (aaaa-mm-dd)
  const base = new Date(partes.length === 3 && partes[2].length === 4 ? partes[2] + '-' + partes[1] + '-' + partes[0] : dataChegada);
  if (isNaN(base.getTime())) return Number(valorInicial) || 0;
  const hoje = new Date();
  let v = Number(valorInicial) || 0;
  for (const [anoStr, taxaStr] of Object.entries(ipca || {})) {
    const ano = Number(anoStr);
    const taxa = Number(taxaStr);
    if (!taxa || taxa <= 0 || !ano || isNaN(ano) || ano < base.getFullYear()) continue; // IPCA de anos anteriores à chegada não se aplica
    const aniversario = new Date(base);
    aniversario.setFullYear(ano + 1); // IPCA do ano Y é aplicado no aniversário em Y+1
    if (aniversario > hoje) continue;
    v *= (1 + taxa / 100);
  }
  return Math.round(v * 100) / 100;
}

function locDataParaIso(valor) {
  const s = String(valor || '').trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  return m ? `${m[3]}-${m[2]}-${m[1]}` : '';
}

function locDataParaBr(valor) {
  const iso = locDataParaIso(valor);
  if (!iso) return String(valor || '').trim() || '—';
  const [ano, mes, dia] = iso.split('-');
  return `${dia}/${mes}/${ano}`;
}

function locAcoesHtml(id) {
  const idSeguro = esc(id || '');
  return '<div class="loc-acoes-linha">' +
    '<button type="button" class="loc-acao" data-loc-action="editar" data-id="' + idSeguro + '" aria-label="Editar locação" title="Editar">' + LOC_ICON_EDITAR + '</button>' +
    '<button type="button" class="loc-acao loc-acao-perigo" data-loc-action="excluir" data-id="' + idSeguro + '" aria-label="Excluir locação" title="Excluir">' + LOC_ICON_EXCLUIR + '</button>' +
    '</div>';
}

function proximoReajusteLoc() {
  const agora = new Date();
  const hoje = new Date(agora.getFullYear(), agora.getMonth(), agora.getDate());
  let proximo = null;
  for (const locacao of LOCACOES) {
    if (!temReajusteLoc(locacao)) continue; // valor fixo: aniversário não reajusta nada
    const iso = locDataParaIso(locacao.dataChegada);
    if (!iso) continue;
    const [, mes, dia] = iso.split('-').map(Number);
    let data = new Date(hoje.getFullYear(), mes - 1, dia);
    if (data < hoje) data = new Date(hoje.getFullYear() + 1, mes - 1, dia);
    if (!proximo || data < proximo.data) proximo = { data, locacao };
  }
  return proximo;
}

function atualizarResumoLocacoes() {
  const ipca = LOCACOES_CONFIG.ipca || {};
  const totalMensal = LOCACOES.reduce((soma, locacao) =>
    soma + valorCorrigidoLoc(locacao, ipca), 0);
  const contratos = new Set(LOCACOES.map(locacao => locacao.contrato).filter(Boolean));
  const qtd = document.getElementById('locKpiVeiculos');
  const mensal = document.getElementById('locKpiMensal');
  const qtdContratos = document.getElementById('locKpiContratos');
  if (qtd) qtd.textContent = String(LOCACOES.length);
  const qtdInfo = document.getElementById('locKpiVeiculosInfo');
  if (qtdInfo) {
    const veiculos = LOCACOES.filter(ehVeiculoLoc).length;
    const outros = LOCACOES.length - veiculos;
    qtdInfo.textContent = outros
      ? `${veiculos} ${veiculos === 1 ? 'veículo' : 'veículos'} · ${outros} ${outros === 1 ? 'equipamento' : 'equipamentos'}`
      : 'cadastros na operação';
  }
  if (mensal) mensal.textContent = fmtMoneyDec(totalMensal);
  if (qtdContratos) qtdContratos.textContent = String(contratos.size);
  const proximo = proximoReajusteLoc();
  const dataEl = document.getElementById('locKpiReajuste');
  const infoEl = document.getElementById('locKpiReajusteInfo');
  if (!dataEl || !infoEl) return;
  if (!proximo) {
    dataEl.textContent = '—';
    infoEl.textContent = 'sem data-base cadastrada';
    return;
  }
  const d = proximo.data;
  dataEl.textContent = `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
  infoEl.textContent = [proximo.locacao.modelo, identificadorLoc(proximo.locacao)].filter(Boolean).join(' · ');
}

// Descrição de contrato SEM travessão na tela: dados antigos (e o exemplo antigo da config)
// gravaram "12 meses — Veículos"; normaliza só na exibição, sem reescrever o dado salvo.
const descContratoLoc = (s) => String(s || '').replace(/\s+—\s+/g, ' · ');

function preencherContratosLoc(valorSelecionado) {
  const select = document.getElementById('locContrato');
  if (!select) return;
  const contratos = LOCACOES_CONFIG.contratos || [];
  select.innerHTML = '<option value="">Sem vínculo</option>' + contratos.map(contrato => {
    const numero = String(contrato.numero || '');
    const rotulo = ['CT ' + numero, descContratoLoc(contrato.descricao)].filter(Boolean).join(' · ');
    return '<option value="' + esc(numero) + '"' + (numero === valorSelecionado ? ' selected' : '') + '>' + esc(rotulo) + '</option>';
  }).join('');
  if (select._syncCustom) select._syncCustom();
}

function mostrarErroLoc(id, mensagem) {
  const el = document.getElementById(id);
  if (!el) return;
  el.textContent = mensagem || '';
  el.hidden = !mensagem;
}

// ===================== LOCAÇÕES › DOCUMENTOS DOS CONTRATOS =====================
// Sub-aba própria: um cartão por contrato, com arrastar-e-soltar e envio em lote.
// Os arquivos ficam no cofre de mídia; a lista vive em LOCACOES_CONFIG.contratos[].documentos.
function documentosContratoLoc(contrato) {
  const docs = Array.isArray(contrato && contrato.documentos) ? contrato.documentos : [];
  const normalizados = docs
    .filter(doc => doc && doc.id)
    .map(doc => ({
      id: String(doc.id), nome: String(doc.nome || 'Documento do contrato'), tipo: String(doc.tipo || ''),
      tamanho: Number(doc.tamanho) || 0, ts: Number(doc.ts) || 0, por: String(doc.por || ''),
    }));
  if (contrato && contrato.arquivo && !normalizados.some(doc => doc.id === String(contrato.arquivo))) {
    normalizados.unshift({ id: String(contrato.arquivo), nome: 'Contrato ' + (contrato.numero || ''), tipo: 'application/pdf', tamanho: 0, ts: 0, por: '' });
  }
  return normalizados;
}

// Ícone por tipo de arquivo — ajuda a bater o olho e achar o contrato assinado no meio dos anexos.
function iconeDocLoc(doc) {
  const nome = String(doc.nome || '').toLowerCase();
  const tipo = String(doc.tipo || '').toLowerCase();
  let rotulo = 'ARQ', classe = 'ft-arq';
  if (tipo.startsWith('image/')) { rotulo = 'IMG'; classe = 'ft-img'; }
  else if (tipo === 'application/pdf' || nome.endsWith('.pdf')) { rotulo = 'PDF'; classe = 'ft-pdf'; }
  else if (/\.(docx?|odt)$/.test(nome) || tipo.includes('word')) { rotulo = 'DOC'; classe = 'ft-doc'; }
  else if (/\.(xlsx?|csv|ods)$/.test(nome) || tipo.includes('sheet') || tipo.includes('excel')) { rotulo = 'XLS'; classe = 'ft-xls'; }
  else if (/\.(pptx?|odp)$/.test(nome) || tipo.includes('presentation')) { rotulo = 'PPT'; classe = 'ft-ppt'; }
  else if (/\.zip$/.test(nome) || tipo.includes('zip')) { rotulo = 'ZIP'; classe = 'ft-zip'; }
  return '<span class="loc-doc-ftipo ' + classe + '">' + rotulo + '</span>';
}

function metaDocLoc(doc) {
  const partes = [];
  if (doc.tamanho) partes.push(fmtTamanho(doc.tamanho));
  if (doc.ts) partes.push(new Date(doc.ts).toLocaleDateString('pt-BR'));
  if (doc.por) partes.push(doc.por);
  return partes.join(' · ');
}

function renderDocsLoc() {
  const host = document.getElementById('locDocsPainel');
  if (!host) return;
  const podeEditar = permissaoAtual('locacoes') === 'editar';
  const contratos = Array.isArray(LOCACOES_CONFIG.contratos) ? LOCACOES_CONFIG.contratos : [];
  const contagem = document.getElementById('locDocContagem');
  const btnNovoCt = document.getElementById('btnAddContratoLoc');
  if (btnNovoCt) btnNovoCt.hidden = !podeEditar;
  if (!contratos.length) {
    host.innerHTML = '<div class="loc-vazio">' +
      '<svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 2h9l4 4v16H6z"/><path d="M14 2v5h5M9 13h6M9 17h6"/></svg>' +
      '<strong>Nenhum contrato cadastrado</strong>' +
      '<span>' + (podeEditar ? 'Clique em <strong>Novo contrato</strong> para cadastrar o primeiro e anexar os documentos.' : 'Peça a quem edita Locações para cadastrar os contratos.') + '</span>' +
      '</div>';
    if (contagem) contagem.textContent = '';
    return;
  }
  const termo = LOC_EST.buscaDoc.trim().toLowerCase();
  let totalDocs = 0, totalVisiveis = 0;
  const cartoes = contratos.map(contrato => {
    const numero = String(contrato.numero || '');
    const docs = documentosContratoLoc(contrato);
    totalDocs += docs.length;
    // A busca casa com o contrato inteiro (número/descrição/locatário) ou com o nome de um arquivo.
    const casaContrato = !termo || (numero + ' ' + (contrato.descricao || '') + ' ' + (contrato.locatario || '')).toLowerCase().includes(termo);
    const visiveis = casaContrato ? docs : docs.filter(doc => doc.nome.toLowerCase().includes(termo));
    if (termo && !casaContrato && !visiveis.length) return '';
    totalVisiveis += visiveis.length;
    const veiculos = LOCACOES.filter(l => String(l.contrato || '') === numero).length;
    const lista = visiveis.length
      ? '<ul class="loc-doc-lista">' + visiveis.map(doc =>
        '<li class="loc-doc-item">' +
          '<span class="loc-doc-icone" aria-hidden="true">' + iconeDocLoc(doc) + '</span>' +
          '<a class="loc-doc-nome" href="/api/midia/' + encodeURIComponent(doc.id) + '" target="_blank" rel="noopener" title="Abrir ' + esc(doc.nome) + '">' + esc(doc.nome) + '</a>' +
          '<span class="loc-doc-meta">' + esc(metaDocLoc(doc)) + '</span>' +
          (podeEditar ? '<button type="button" class="loc-acao loc-acao-perigo" data-loc-doc-rem="' + esc(doc.id) + '" data-numero="' + esc(numero) + '" aria-label="Excluir ' + esc(doc.nome) + '" title="Excluir">' + LOC_ICON_EXCLUIR + '</button>' : '') +
        '</li>'
      ).join('') + '</ul>'
      : (termo
        ? '<p class="loc-docs-vazio">Nenhum arquivo com esse nome.</p>'
        : (podeEditar ? '' : '<p class="loc-docs-vazio">Nenhum documento anexado ainda.</p>'));
    // A zona de soltar É o convite de envio (padrão das plataformas de documentos):
    // clicar nela abre o seletor (delegação por data-loc-doc-add) e soltar arquivos nela anexa.
    const zonaEnvio = podeEditar
      ? '<button type="button" class="loc-doc-drop' + (visiveis.length ? ' compacta' : '') + '" data-loc-doc-add="' + esc(numero) + '">' +
          '<span class="loc-doc-drop-ico" aria-hidden="true"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 16.2A4.5 4.5 0 0 1 6.6 8a6 6 0 0 1 11.7 1.9 3.9 3.9 0 0 1 1.7 7.6"/><path d="M12 12v9"/><path d="m8.5 15.5 3.5-3.5 3.5 3.5"/></svg></span>' +
          '<span class="loc-doc-drop-txt"><strong>Clique para enviar</strong> ou arraste e solte</span>' +
          '<small>PDF, imagem, Word ou Excel (até 9 MB por arquivo)</small>' +
        '</button>'
      : '';
    return '<article class="loc-doc-contrato' + (podeEditar ? ' pode-soltar' : '') + '" data-contrato="' + esc(numero) + '">' +
      '<header>' +
        '<div><strong>CT ' + esc(numero || '—') + '</strong><span>' + esc(descContratoLoc(contrato.descricao) || 'Sem descrição') + '</span>' +
          (contrato.locatario ? '<span class="loc-doc-locatario">Alugado para <b>' + esc(contrato.locatario) + '</b></span>' : '') +
          (contrato.assinadoEm ? '<span class="loc-doc-locatario">Assinado em <b>' + esc(locDataParaBr(contrato.assinadoEm)) + '</b></span>' : '') +
        '</div>' +
        '<div class="loc-doc-tags">' +
          '<span class="loc-doc-tag">' + docs.length + ' arquivo' + (docs.length === 1 ? '' : 's') + '</span>' +
          '<span class="loc-doc-tag">' + veiculos + ' veículo' + (veiculos === 1 ? '' : 's') + '</span>' +
          (podeEditar
            ? '<button type="button" class="loc-acao" data-loc-ct-edit="' + esc(numero) + '" aria-label="Editar contrato CT ' + esc(numero) + '" title="Editar contrato"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M17 3a2.8 2.8 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/></svg></button>' +
              '<button type="button" class="loc-acao loc-acao-perigo" data-loc-ct-del="' + esc(numero) + '" aria-label="Excluir contrato CT ' + esc(numero) + '" title="Excluir contrato">' + LOC_ICON_EXCLUIR + '</button>'
            : '') +
        '</div>' +
      '</header>' +
      lista +
      zonaEnvio +
      '</article>';
  }).join('');
  host.innerHTML = cartoes || '<p class="loc-docs-vazio">Nenhum contrato ou arquivo encontrado para essa busca.</p>';
  if (contagem) contagem.textContent = termo ? `${totalVisiveis} de ${totalDocs} arquivo(s)` : `${totalDocs} arquivo(s) em ${contratos.length} contrato(s)`;
}

async function anexarDocumentosContratoLoc(numero, arquivos) {
  const lista = [...(arquivos || [])];
  if (!numero || !lista.length) return;
  const fd = new FormData();
  lista.forEach(arquivo => fd.append('arquivos', arquivo));
  const cartao = document.querySelector(`.loc-doc-contrato[data-contrato="${CSS.escape(numero)}"]`);
  if (cartao) cartao.classList.add('enviando');
  try {
    const resposta = await fetch('/api/locacoes/contratos/' + encodeURIComponent(numero) + '/documentos', { method: 'POST', body: fd });
    const dados = await resposta.json().catch(() => ({}));
    if (!resposta.ok) throw new Error(dados.erro || 'Não foi possível anexar os documentos.');
    const contratos = [...(LOCACOES_CONFIG.contratos || [])];
    const idx = contratos.findIndex(contrato => String(contrato.numero || '') === String(numero));
    if (idx >= 0) contratos[idx] = dados.contrato; else contratos.push(dados.contrato);
    LOCACOES_CONFIG = { ...LOCACOES_CONFIG, contratos };
    renderDocsLoc();
    const enviados = (dados.enviados || []).length;
    const erros = dados.erros || [];
    if (erros.length) toast(`${enviados} anexado(s). ${erros[0]}`, 'aviso');
    else toast(enviados === 1 ? 'Documento anexado ao contrato.' : `${enviados} documentos anexados ao contrato.`, 'ok');
  } finally {
    if (cartao) cartao.classList.remove('enviando');
  }
}

async function removerDocumentoContratoLoc(numero, id) {
  const resposta = await fetch(`/api/locacoes/contratos/${encodeURIComponent(numero)}/documentos/${encodeURIComponent(id)}`, { method: 'DELETE' });
  const dados = await resposta.json().catch(() => ({}));
  if (!resposta.ok) throw new Error(dados.erro || 'Não foi possível remover o documento.');
  const contratos = (LOCACOES_CONFIG.contratos || []).map(contrato =>
    String(contrato.numero || '') === String(numero) ? dados.contrato : contrato);
  LOCACOES_CONFIG = { ...LOCACOES_CONFIG, contratos };
  renderDocsLoc();
}

async function carregarLocacoes() {
  const [r, rc, rf] = await Promise.all([
    fetch('/api/locacoes', { cache: 'no-store' }),
    fetch('/api/locacoes/config', { cache: 'no-store' }),
    fetch('/api/locacoes/faturas', { cache: 'no-store' }),
  ]);
  if (r.ok) { const d = await r.json(); if (JSON.stringify(d) !== JSON.stringify(LOCACOES)) LOCACOES = d; }
  if (rc.ok) LOCACOES_CONFIG = await rc.json();
  if (rf.ok) { const d = await rf.json(); if (Array.isArray(d)) LOCACOES_FATURAS = d; }
  renderLocacoes();
  renderDocsLoc();
  renderFaturasLoc();
}

// ----- Histórico de faturas (sub-aba Faturas) -----
// Uma linha por PDF gerado. O check "Enviada" marca a fatura que de fato foi ao cliente (grava
// quem e quando no servidor); o botão de PDF reabre o arquivo guardado; excluir tira só o registro.
//   renderFaturasLoc()  // lê LOCACOES_FATURAS + LOC_FAT_BUSCA e desenha #locFatTbody
function renderFaturasLoc() {
  const tbody = document.getElementById('locFatTbody');
  const vazio = document.getElementById('locFatVazio');
  const wrap = document.querySelector('.loc-fat-wrap');
  const contagem = document.getElementById('locFatContagem');
  if (!tbody || !vazio || !wrap) return;
  const podeEditar = permissaoAtual('locacoes') === 'editar';
  const termo = LOC_FAT_BUSCA.trim().toLowerCase();
  const lista = LOCACOES_FATURAS.filter(f => {
    if (!termo) return true;
    return [f.referencia, f.competencia, f.geradoPor, f.enviadaPor, f.emitente && f.emitente.apelido, f.emitente && f.emitente.razaoSocial,
      f.destinatario && f.destinatario.apelido, f.destinatario && f.destinatario.razaoSocial, f.obs]
      .some(campo => String(campo || '').toLowerCase().includes(termo));
  });
  if (contagem) contagem.textContent = termo
    ? `${lista.length} de ${LOCACOES_FATURAS.length} faturas`
    : `${LOCACOES_FATURAS.length} ${LOCACOES_FATURAS.length === 1 ? 'fatura' : 'faturas'}`;
  if (!lista.length) { tbody.innerHTML = ''; wrap.hidden = true; vazio.hidden = false; return; }
  wrap.hidden = false; vazio.hidden = true;
  const parte = (p) => esc((p && (p.apelido || p.razaoSocial)) || '—');
  tbody.innerHTML = lista.map(f => {
    const tituloEnviada = f.enviada
      ? 'Enviada em ' + fmtDataHoraTs(f.enviadaEm) + (f.enviadaPor ? ' por ' + f.enviadaPor : '')
      : 'Marcar como enviada ao cliente';
    return '<tr' + (f.enviada ? ' class="loc-fat-enviada"' : '') + '>' +
      '<td><strong>' + esc(f.referencia || f.competencia || '—') + '</strong>' +
        (f.apenasVeiculos === false ? ' <span class="tipo-tag">Com equipamentos</span>' : '') + '</td>' +
      '<td>' + esc(fmtDataHoraTs(f.geradoEm) || '—') + '</td>' +
      '<td>' + esc(f.geradoPor || '—') + '</td>' +
      '<td>' + parte(f.emitente) + '</td>' +
      '<td>' + parte(f.destinatario) + '</td>' +
      '<td class="num">' + esc(String(f.qtdItens ?? (f.itens ? f.itens.length : 0))) + '</td>' +
      '<td class="num"><span class="loc-table-valor-corrigido">' + fmtMoneyDec(f.totalLiquido) + '</span></td>' +
      '<td><label class="loc-fat-check" title="' + esc(tituloEnviada) + '">' +
        '<input type="checkbox" data-fat-enviada="' + esc(f.id) + '"' + (f.enviada ? ' checked' : '') + (podeEditar ? '' : ' disabled') + ' /> ' +
        '<span>' + (f.enviada ? 'Enviada' : 'Pendente') + '</span></label>' +
        (f.enviada ? '<small class="loc-fat-quando">' + esc(fmtDataHoraTs(f.enviadaEm)) + (f.enviadaPor ? ' · ' + esc(f.enviadaPor) : '') + '</small>' : '') +
      '</td>' +
      '<td class="loc-col-acoes"><div class="loc-acoes-linha">' +
        '<a class="loc-acao" href="/api/locacoes/faturas/' + encodeURIComponent(f.id) + '/pdf" target="_blank" rel="noopener" aria-label="Abrir PDF da fatura" title="Abrir PDF">' + LOC_ICON_PDF + '</a>' +
        (podeEditar ? '<button type="button" class="loc-acao loc-acao-perigo" data-fat-action="excluir" data-id="' + esc(f.id) + '" aria-label="Excluir registro da fatura" title="Excluir registro">' + LOC_ICON_EXCLUIR + '</button>' : '') +
      '</div></td>' +
      '</tr>';
  }).join('');
}
async function marcarFaturaEnviadaLoc(id, enviada, caixa) {
  const anterior = !enviada;
  try {
    const resposta = await fetch('/api/locacoes/faturas/' + encodeURIComponent(id), {
      method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ enviada }),
    });
    const dados = await resposta.json().catch(() => ({}));
    if (!resposta.ok) throw new Error(dados.erro || 'Não foi possível atualizar a fatura.');
    LOCACOES_FATURAS = LOCACOES_FATURAS.map(f => f.id === id ? dados : f);
    renderFaturasLoc();
    toast(enviada ? 'Fatura marcada como enviada.' : 'Fatura desmarcada.', 'ok');
  } catch (erro) {
    if (caixa) caixa.checked = anterior;
    toast(erro.message || 'Não foi possível atualizar a fatura.', 'erro');
  }
}
async function excluirFaturaLoc(id) {
  const f = LOCACOES_FATURAS.find(x => x.id === id);
  const nome = f ? 'a fatura de ' + (f.referencia || f.competencia) : 'este registro';
  if (!(await confirmar(`Excluir ${nome} do histórico? O PDF guardado também será descartado.`, { perigo: true, okTexto: 'Excluir' }))) return;
  const resposta = await fetch('/api/locacoes/faturas/' + encodeURIComponent(id), { method: 'DELETE' });
  const dados = await resposta.json().catch(() => ({}));
  if (!resposta.ok) return toast(dados.erro || 'Não foi possível excluir o registro.', 'erro');
  LOCACOES_FATURAS = LOCACOES_FATURAS.filter(x => x.id !== id);
  renderFaturasLoc();
  toast('Registro excluído.', 'ok');
}
// No modal de emissão: avisa se a competência escolhida já tem PDF no histórico (evita gerar em
// dobro sem querer e mostra se a anterior já foi marcada como enviada).
function notaHistoricoFaturaLoc(competencia) {
  const nota = document.getElementById('locFaturaHistNota');
  if (!nota) return;
  const anteriores = LOCACOES_FATURAS.filter(f => f.competencia === competencia);
  if (!anteriores.length) { nota.hidden = true; nota.textContent = ''; return; }
  const enviada = anteriores.find(f => f.enviada);
  const ultima = anteriores[0];
  nota.textContent = (anteriores.length === 1 ? 'Já existe 1 PDF desta competência no histórico' : `Já existem ${anteriores.length} PDFs desta competência no histórico`)
    + ' (último em ' + fmtDataHoraTs(ultima.geradoEm) + (ultima.geradoPor ? ' por ' + ultima.geradoPor : '') + ')'
    + (enviada ? '; a fatura marcada como enviada foi a de ' + fmtDataHoraTs(enviada.enviadaEm) + '.' : '; nenhuma marcada como enviada ainda.');
  nota.hidden = false;
}

// Contrato de um veículo locado (ou null): usado nos filtros, na busca e no detalhe.
function contratoDaLocacao(locacao) {
  return (LOCACOES_CONFIG.contratos || []).find(c => String(c.numero) === String(locacao.contrato || '')) || null;
}

// Colunas da tabela: clicar no título ordena, clicar de novo inverte (padrão das outras abas).
const COLS_LOC = [
  { campo: 'modelo', titulo: 'Item' },
  { campo: 'identificador', titulo: 'Placa / ID' },
  { campo: 'ano', titulo: 'Ano', tipo: 'num' },
  { campo: 'dataChegada', titulo: 'Data-base', tipo: 'data' },
  { campo: 'contrato', titulo: 'Contrato' },
  { campo: 'valorInicial', titulo: 'Valor inicial', tipo: 'num', classe: 'num' },
  { campo: 'corrigido', titulo: 'Valor corrigido', tipo: 'num', classe: 'num' },
];

function chaveOrdLoc(locacao, campo, ipca) {
  if (campo === 'identificador') return identificadorLoc(locacao);
  if (campo === 'ano') return Number(locacao.anoFabricacao || locacao.ano) || 0;
  if (campo === 'dataChegada') return locDataParaIso(locacao.dataChegada); // ISO ordena como texto
  if (campo === 'valorInicial') return Number(locacao.valorInicial) || 0;
  if (campo === 'corrigido') return valorCorrigidoLoc(locacao, ipca);
  return String(locacao[campo] || '');
}

function ordenarListaLoc(lista, ipca) {
  const campo = LOC_EST.ordCampo, dir = LOC_EST.ordDir;
  if (!campo) return lista;
  const col = COLS_LOC.find(c => c.campo === campo) || {};
  return lista.slice().sort((a, b) => {
    const x = chaveOrdLoc(a, campo, ipca), y = chaveOrdLoc(b, campo, ipca);
    if (col.tipo === 'num') return (x - y) * dir;
    if (!x && y) return 1; // sem valor vai para o fim nos dois sentidos
    if (x && !y) return -1;
    return String(x).localeCompare(String(y), 'pt-BR', { numeric: true }) * dir;
  });
}

function renderLocacoes() {
  const termo = LOC_EST.busca.trim().toLowerCase();
  const selTipo = new Set(getSel('flocTipo'));
  const selContrato = new Set(getSel('flocContrato').map(r => r.replace(/^CT\s+/, '')));
  const selLocatario = new Set(getSel('flocLocatario'));
  const selPolo = new Set(getSel('flocPolo'));
  const ipca = LOCACOES_CONFIG.ipca || {};
  const lista = ordenarListaLoc(LOCACOES.filter(locacao => {
    const ct = contratoDaLocacao(locacao);
    if (selTipo.size && !selTipo.has(tipoRotuloLoc(locacao))) return false;
    if (selContrato.size && !selContrato.has(String(locacao.contrato || ''))) return false;
    if (selLocatario.size && !selLocatario.has((ct && ct.locatario) || '(sem locatário)')) return false;
    if (selPolo.size && !selPolo.has(locacao.polo || '(sem polo)')) return false;
    if (!termo) return true;
    return [locacao.placa, locacao.identificacao, tipoRotuloLoc(locacao), locacao.modelo, locacao.polo, locacao.contrato, ct && ct.descricao, ct && ct.locatario]
      .some(campo => (campo || '').toLowerCase().includes(termo));
  }), ipca);
  const podeEditar = permissaoAtual('locacoes') === 'editar';
  const btnAdicionar = document.getElementById('btnAddLoc');
  const btnConfig = document.getElementById('btnConfigLoc');
  if (btnAdicionar) btnAdicionar.hidden = !podeEditar;
  if (btnConfig) btnConfig.hidden = !podeEditar;
  const cab = document.querySelector('#locTable thead tr');
  if (cab) {
    cab.innerHTML = COLS_LOC.map(c =>
      `<th scope="col"${c.classe ? ` class="${c.classe}"` : ''} data-campo="${c.campo}" title="Clique para ordenar">${c.titulo}${iconeOrd(LOC_EST.ordCampo === c.campo, LOC_EST.ordDir)}</th>`
    ).join('') + `<th scope="col" class="loc-col-acoes"${podeEditar ? '' : ' hidden'}><span class="sr-only">Ações</span></th>`;
    cab.querySelectorAll('th[data-campo]').forEach(th => th.onclick = () => {
      const campo = th.dataset.campo;
      if (LOC_EST.ordCampo === campo) LOC_EST.ordDir *= -1;
      else { LOC_EST.ordCampo = campo; LOC_EST.ordDir = 1; }
      renderLocacoes();
    });
  }

  const temFiltro = !!(termo || selTipo.size || selContrato.size || selLocatario.size || selPolo.size);
  const btnLimparF = document.getElementById('locLimparFiltros');
  if (btnLimparF) btnLimparF.hidden = !temFiltro;
  const contagem = document.getElementById('locContagem');
  if (contagem) contagem.textContent = temFiltro
    ? `${lista.length} de ${LOCACOES.length} locações`
    : `${LOCACOES.length} ${LOCACOES.length === 1 ? 'locação' : 'locações'}`;

  atualizarResumoLocacoes();
  popularFiltrosLoc();

  const tbody = document.getElementById('locTbody');
  const cards = document.getElementById('locCards');
  const tabela = document.querySelector('.loc-table-wrap');
  const vazio = document.getElementById('locVazio');
  if (!tbody || !cards || !tabela || !vazio) return;

  if (!lista.length) {
    tbody.innerHTML = '';
    cards.innerHTML = '';
    tabela.hidden = true;
    cards.hidden = true;
    vazio.hidden = false;
    return;
  }

  tabela.hidden = false;
  cards.hidden = false;
  vazio.hidden = true;

  tbody.innerHTML = lista.map(locacao => {
    const corrigido = valorCorrigidoLoc(locacao, ipca);
    const ano = !ehVeiculoLoc(locacao) ? '—' : locacao.anoFabricacao
      ? `${locacao.anoFabricacao}/${locacao.anoModelo || locacao.anoFabricacao}`
      : (locacao.ano || '—');
    const ct = contratoDaLocacao(locacao);
    const contratoRotulo = locacao.contrato ? `CT ${locacao.contrato}` : 'Sem vínculo';
    const contratoTitulo = ct ? [descContratoLoc(ct.descricao), ct.locatario ? 'Alugado para ' + ct.locatario : ''].filter(Boolean).join(' · ') : '';
    return '<tr>' +
      '<td><strong>' + esc(locacao.modelo || '—') + '</strong>' + tagTipoLoc(locacao) + '</td>' +
      '<td>' + chipIdentificadorLoc(locacao) + '</td>' +
      '<td>' + esc(ano) + '</td>' +
      '<td>' + esc(locDataParaBr(locacao.dataChegada)) + '</td>' +
      '<td><span class="loc-table-contrato" title="' + esc(contratoTitulo) + '">' + esc(contratoRotulo) + '</span></td>' +
      '<td class="num">' + fmtMoneyDec(locacao.valorInicial) + '</td>' +
      '<td class="num"><span class="loc-table-valor-corrigido">' + fmtMoneyDec(corrigido) + '</span>' + tagReajusteLoc(locacao) + '</td>' +
      '<td class="loc-col-acoes"' + (podeEditar ? '' : ' hidden') + '>' + (podeEditar ? locAcoesHtml(locacao.id) : '') + '</td>' +
      '</tr>';
  }).join('');

  cards.innerHTML = lista.map(locacao => {
    const corrigido = valorCorrigidoLoc(locacao, ipca);
    const ct = contratoDaLocacao(locacao);
    const contratoRotulo = locacao.contrato ? `CT ${locacao.contrato}` : 'Sem vínculo';
    return '<article class="loc-card">' +
      '<div class="loc-card-topo">' +
        '<div class="loc-card-identidade"><span class="loc-card-modelo">' + esc(locacao.modelo || tipoRotuloLoc(locacao)) + tagTipoLoc(locacao) + '</span>' + chipIdentificadorLoc(locacao, 'loc-card-placa') + '</div>' +
        (podeEditar ? locAcoesHtml(locacao.id) : '') +
      '</div>' +
      '<dl class="loc-card-dados">' +
        '<div><dt>Data-base</dt><dd>' + esc(locDataParaBr(locacao.dataChegada)) + '</dd></div>' +
        '<div><dt>Contrato</dt><dd>' + esc(contratoRotulo) + '</dd></div>' +
        (ct && ct.locatario ? '<div><dt>Alugado para</dt><dd>' + esc(ct.locatario) + '</dd></div>' : '') +
        '<div><dt>Valor inicial</dt><dd>' + fmtMoneyDec(locacao.valorInicial) + '</dd></div>' +
        '<div class="loc-card-valor"><dt>Valor corrigido</dt><dd>' + fmtMoneyDec(corrigido) + tagReajusteLoc(locacao) + '</dd></div>' +
      '</dl>' +
      '</article>';
  }).join('');
}

// Filtros no padrão do sistema (multi-seleção): opções vêm dos dados, seleção preservada.
function popularFiltrosLoc() {
  const tipos = [...new Set(LOCACOES.map(tipoRotuloLoc))].sort((a, b) => a.localeCompare(b, 'pt-BR'));
  if (MSEL.flocTipo) MSEL.flocTipo.setOpcoes(tipos);
  const contratos = [...new Set(LOCACOES.map(l => l.contrato).filter(Boolean))].sort();
  if (MSEL.flocContrato) MSEL.flocContrato.setOpcoes(contratos.map(n => 'CT ' + n));
  const locatarios = [...new Set(LOCACOES.map(l => { const ct = contratoDaLocacao(l); return (ct && ct.locatario) || '(sem locatário)'; }))].sort();
  if (MSEL.flocLocatario) MSEL.flocLocatario.setOpcoes(locatarios);
  const polos = [...new Set(LOCACOES.map(l => l.polo || '(sem polo)'))].sort();
  if (MSEL.flocPolo) MSEL.flocPolo.setOpcoes(polos);
}

// Helpers p/ abrir/fechar modais de locações (evita conflito com abrirModal da Frota)
function abrirModalLoc(id) {
  const modal = document.getElementById(id);
  if (!modal) return;
  LOC_FOCO_ANTERIOR = document.activeElement;
  modal.hidden = false;
  requestAnimationFrame(() => {
    let primeiro = modal.querySelector('[data-loc-autofocus]')
      || modal.querySelector('form input:not([type="hidden"]):not([disabled]), form select:not([disabled]), form textarea:not([disabled])')
      || modal.querySelector('button:not([disabled])');
    if (primeiro && primeiro.matches('select.cs-native')) primeiro = primeiro.nextElementSibling || primeiro;
    if (primeiro) primeiro.focus();
  });
}
function fecharModalLoc(id) {
  const modal = document.getElementById(id);
  if (!modal) return;
  modal.hidden = true;
  if (LOC_FOCO_ANTERIOR && document.contains(LOC_FOCO_ANTERIOR)) LOC_FOCO_ANTERIOR.focus();
  LOC_FOCO_ANTERIOR = null;
}

function editarLoc(id) {
  const locacao = LOCACOES.find(item => item.id === id);
  if (!locacao) return;
  document.getElementById('formLocacao').reset();
  document.getElementById('locId').value = locacao.id || '';
  document.getElementById('locTipo').value = ehVeiculoLoc(locacao) ? 'veiculo' : locacao.tipo;
  aplicarTipoLoc();
  document.getElementById('locPlaca').value = locacao.placa || '';
  document.getElementById('locIdentificacao').value = locacao.identificacao || '';
  document.getElementById('locModelo').value = locacao.modelo || '';
  document.getElementById('locAnoFab').value = locacao.anoFabricacao || '';
  document.getElementById('locAnoMod').value = locacao.anoModelo || '';
  document.getElementById('locDataChegada').value = locDataParaIso(locacao.dataChegada);
  document.getElementById('locValor').value = locacao.valorInicial || '';
  document.getElementById('locPolo').value = locacao.polo || '';
  document.getElementById('locObs').value = locacao.obs || '';
  document.getElementById('locReajuste').checked = temReajusteLoc(locacao);
  preencherContratosLoc(locacao.contrato || '');
  mostrarErroLoc('locFormErro', '');
  document.getElementById('locModalTitulo').textContent = 'Editar locação';
  abrirModalLoc('modalLocacao');
}

async function excluirLoc(id) {
  const locacao = LOCACOES.find(item => item.id === id);
  const nome = locacao ? rotuloLoc(locacao) : 'esta locação';
  if (!(await confirmar(`Excluir ${nome}? Esta ação não pode ser desfeita.`, { perigo: true, okTexto: 'Excluir' }))) return;
  const resposta = await fetch('/api/locacoes/' + encodeURIComponent(id), { method: 'DELETE' });
  const dados = await resposta.json().catch(() => ({}));
  if (!resposta.ok) return toast(dados.erro || 'Não foi possível excluir a locação.', 'erro');
  await carregarLocacoes();
  toast('Locação excluída.', 'ok');
}

async function salvarLoc() {
  const form = document.getElementById('formLocacao');
  if (!form.reportValidity()) return;
  const id = document.getElementById('locId').value;
  const tipo = document.getElementById('locTipo').value || 'veiculo';
  const veiculo = tipo === 'veiculo';
  const placa = veiculo ? document.getElementById('locPlaca').value.trim().toUpperCase() : '';
  const valorInicial = numBR(document.getElementById('locValor').value);
  if (!Number.isFinite(valorInicial) || valorInicial <= 0) {
    mostrarErroLoc('locFormErro', 'Informe um valor mensal maior que zero.');
    document.getElementById('locValor').focus();
    return;
  }
  const body = {
    tipo,
    placa,
    identificacao: veiculo ? '' : document.getElementById('locIdentificacao').value.trim(),
    modelo: document.getElementById('locModelo').value.trim(),
    anoFabricacao: veiculo ? document.getElementById('locAnoFab').value.trim() : '',
    anoModelo: veiculo ? document.getElementById('locAnoMod').value.trim() : '',
    dataChegada: locDataParaBr(document.getElementById('locDataChegada').value),
    valorInicial,
    contrato: document.getElementById('locContrato').value || '',
    polo: document.getElementById('locPolo').value.trim(),
    obs: document.getElementById('locObs').value.trim(),
    reajusteIpca: document.getElementById('locReajuste').checked,
  };
  const botao = document.getElementById('btnSalvarLoc');
  const rotulo = botao.textContent;
  botao.disabled = true;
  botao.textContent = 'Salvando…';
  mostrarErroLoc('locFormErro', '');
  try {
    const resposta = await fetch(id ? '/api/locacoes/' + encodeURIComponent(id) : '/api/locacoes', {
      method: id ? 'PUT' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    const dados = await resposta.json().catch(() => ({}));
    if (!resposta.ok) throw new Error(dados.erro || 'Não foi possível salvar a locação.');
    fecharModalLoc('modalLocacao');
    await carregarLocacoes();
    toast(id ? 'Locação atualizada.' : 'Locação adicionada.', 'ok');
  } catch (erro) {
    mostrarErroLoc('locFormErro', erro.message || 'Não foi possível salvar a locação.');
  } finally {
    botao.disabled = false;
    botao.textContent = rotulo;
  }
}

// Mostra os campos do tipo escolhido: placa + anos (veículo) ou identificação (demais). O
// `required` da placa só vale quando ela está visível — campo oculto com required trava o
// reportValidity() sem mostrar nada.
//   aplicarTipoLoc()  // lê #locTipo e ajusta [data-loc-so], o rótulo "Modelo"/"Descrição" e o placeholder
function aplicarTipoLoc() {
  const tipo = document.getElementById('locTipo').value || 'veiculo';
  const veiculo = tipo === 'veiculo';
  document.querySelectorAll('#formLocacao [data-loc-so]').forEach(el => { el.hidden = (el.dataset.locSo === 'veiculo') !== veiculo; });
  const placa = document.getElementById('locPlaca');
  placa.required = veiculo;
  if (!veiculo) placa.value = '';
  const rotulo = document.getElementById('locModeloRotulo');
  if (rotulo) rotulo.textContent = veiculo ? 'Modelo' : 'Descrição';
  document.getElementById('locModelo').placeholder = veiculo ? 'Ex.: L200 Triton' : 'Ex.: Ferramental de troca de peças (reisolamento)';
}

function abrirNovaLoc() {
  document.getElementById('formLocacao').reset();
  document.getElementById('locId').value = '';
  document.getElementById('locTipo').value = 'veiculo';
  if (document.getElementById('locTipo')._syncCustom) document.getElementById('locTipo')._syncCustom();
  aplicarTipoLoc();
  preencherContratosLoc('');
  mostrarErroLoc('locFormErro', '');
  document.getElementById('locModalTitulo').textContent = 'Nova locação';
  abrirModalLoc('modalLocacao');
}

// ----- Detalhe da locação (clique na placa): recebimento, IPCA aplicado e aniversário -----
// Espelha ipcaAtualizado(), mas devolvendo o PASSO A PASSO: qual taxa entrou, quando e o
// valor antes/depois — mais o próximo aniversário da data-base e a taxa que vai aplicar.
function correcaoIpcaDetalhada(valorInicial, dataChegada, ipca) {
  const iso = locDataParaIso(dataChegada);
  const base = iso ? new Date(iso + 'T00:00:00') : null;
  const v0 = Number(valorInicial) || 0;
  const det = { valorInicial: v0, corrigido: v0, passos: [], acumuladoPct: 0, proximoAniversario: null, anoIpcaProximo: null, taxaProxima: null };
  if (!base || isNaN(base.getTime())) return det;
  const hoje = new Date();
  let v = v0;
  const anos = Object.keys(ipca || {}).map(Number).filter(a => Number.isFinite(a) && a >= base.getFullYear()).sort((a, b) => a - b);
  for (const ano of anos) {
    const taxa = Number(ipca[ano]);
    if (!taxa || taxa <= 0) continue;
    const aniversario = new Date(base);
    aniversario.setFullYear(ano + 1); // IPCA do ano Y entra no aniversário em Y+1
    if (aniversario > hoje) continue;
    const antes = v;
    v = v * (1 + taxa / 100);
    det.passos.push({ ano, taxa, quando: aniversario, antes, depois: v });
  }
  det.corrigido = Math.round(v * 100) / 100;
  det.acumuladoPct = v0 > 0 ? (v / v0 - 1) : 0;
  const proximo = new Date(base);
  proximo.setFullYear(hoje.getFullYear());
  if (proximo <= hoje) proximo.setFullYear(hoje.getFullYear() + 1);
  det.proximoAniversario = proximo;
  det.anoIpcaProximo = proximo.getFullYear() - 1;
  det.taxaProxima = ipca && ipca[det.anoIpcaProximo] != null ? Number(ipca[det.anoIpcaProximo]) : null;
  return det;
}

// Placa no desenho Mercosul (faixa azul + letras pretas sobre fundo branco): a versão grande
// vive no detalhe; a mesma ideia, em miniatura, é a classe global .placa-chip (styles.css).
function placaVisuHtml(placa) {
  const txt = String(placa || '').trim().toUpperCase();
  return '<span class="placa-visu" aria-hidden="true">' +
    '<span class="placa-visu-topo">BRASIL</span>' +
    '<span class="placa-visu-num">' + esc(txt || 'SEM PLACA') + '</span>' +
  '</span>';
}

function abrirDetalheLoc(id) {
  const locacao = LOCACOES.find(item => item.id === id);
  if (!locacao) return;
  const ct = contratoDaLocacao(locacao);
  const reajusta = temReajusteLoc(locacao);
  const det = reajusta
    ? correcaoIpcaDetalhada(locacao.valorInicial, locacao.dataChegada, LOCACOES_CONFIG.ipca || {})
    : { valorInicial: Number(locacao.valorInicial) || 0, corrigido: Number(locacao.valorInicial) || 0, passos: [], acumuladoPct: 0, proximoAniversario: null, anoIpcaProximo: null, taxaProxima: null };
  const dataBR = (d) => d ? d.toLocaleDateString('pt-BR') : '—';
  const pct = (t) => Number(t).toLocaleString('pt-BR', { maximumFractionDigits: 2 }) + '%';
  const veiculo = ehVeiculoLoc(locacao);
  const ano = !veiculo ? '' : locacao.anoFabricacao
    ? `${locacao.anoFabricacao}/${locacao.anoModelo || locacao.anoFabricacao}`
    : (locacao.ano || '');
  document.getElementById('locDetTitulo').textContent = locacao.modelo || 'Locação';
  document.getElementById('locDetSub').textContent = ct
    ? ['CT ' + ct.numero, descContratoLoc(ct.descricao)].filter(Boolean).join(' · ')
    : 'Sem contrato vinculado';
  const linhasIpca = det.passos.map(p =>
    '<tr>' +
      '<td>IPCA ' + p.ano + '</td>' +
      '<td class="num">' + pct(p.taxa) + '</td>' +
      '<td>' + dataBR(p.quando) + '</td>' +
      '<td class="num">' + fmtMoneyDec(p.antes) + ' → <b>' + fmtMoneyDec(p.depois) + '</b></td>' +
    '</tr>').join('');
  document.getElementById('locDetCorpo').innerHTML =
    '<div class="loc-det-hero">' +
      // Só veículo ganha o desenho da placa; equipamento mostra tipo e identificação em texto.
      (veiculo ? placaVisuHtml(locacao.placa) : '') +
      '<div class="loc-det-hero-info">' +
        '<strong>' + esc(locacao.modelo || tipoRotuloLoc(locacao)) + '</strong>' +
        '<span>' + esc([veiculo ? '' : tipoRotuloLoc(locacao), veiculo ? '' : locacao.identificacao, ano, locacao.polo].filter(Boolean).join(' · ') || (veiculo ? 'Veículo locado' : 'Item locado')) + '</span>' +
      '</div>' +
      '<div class="loc-det-valor"><span>' + (reajusta ? 'Valor corrigido hoje' : 'Valor mensal (fixo)') + '</span><strong>' + fmtMoneyDec(det.corrigido) + '</strong></div>' +
    '</div>' +
    '<dl class="loc-det-grade">' +
      '<div><dt>Recebido em (data-base)</dt><dd>' + esc(locDataParaBr(locacao.dataChegada) || '—') + '</dd></div>' +
      '<div><dt>Alugado para</dt><dd>' + esc((ct && ct.locatario) || '—') + '</dd></div>' +
      '<div><dt>Contrato assinado em</dt><dd>' + esc(ct && ct.assinadoEm ? locDataParaBr(ct.assinadoEm) : '—') + '</dd></div>' +
      '<div><dt>Valor mensal inicial</dt><dd>' + fmtMoneyDec(det.valorInicial) + '</dd></div>' +
    '</dl>' +
    (!reajusta
      ? '<h3 class="loc-det-h">Reajuste anual</h3>' +
        '<p class="loc-det-acum">Este item não tem reajuste anual: o valor mensal fica fixo em <b>' + fmtMoneyDec(det.valorInicial) + '</b> até ser alterado no cadastro.</p>'
      : '<h3 class="loc-det-h">Reajustes de IPCA aplicados</h3>' +
    (det.passos.length
      ? '<div class="tabela-wrap loc-det-tabela"><table><thead><tr><th>Índice</th><th class="num">Taxa</th><th>Aplicado em</th><th class="num">Valor</th></tr></thead><tbody>' + linhasIpca + '</tbody></table></div>' +
        '<p class="loc-det-acum">Acumulado desde a chegada: <b>+' + pct(det.acumuladoPct * 100) + '</b></p>'
      : '<p class="loc-det-acum">Nenhum reajuste aplicado ainda: o valor segue o inicial.</p>') +
    '<div class="loc-det-rodape">' +
      '<div class="loc-det-anivers">' +
        '<dt>Próximo aniversário do contrato</dt>' +
        '<dd><b>' + dataBR(det.proximoAniversario) + '</b> · aplicará o IPCA de ' + det.anoIpcaProximo +
          (det.taxaProxima != null ? ' (' + pct(det.taxaProxima) + ')' : ' (taxa ainda não cadastrada em Configurar)') + '</dd>' +
      '</div>' +
    '</div>');
  abrirModalLoc('modalDetalheLoc');
}

// ----- CRUD de contratos (cartões da sub-aba Documentos; nada de lista fixa no código) -----
async function salvarContratosLoc(contratos) {
  const resposta = await fetch('/api/locacoes/config', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ ...LOCACOES_CONFIG, contratos }),
  });
  const dados = await resposta.json().catch(() => ({}));
  if (!resposta.ok) throw new Error(dados.erro || 'Não foi possível salvar os contratos.');
  LOCACOES_CONFIG = dados;
  renderLocacoes();
  renderDocsLoc();
}

function abrirContratoLocModal(numero) {
  const contrato = numero ? (LOCACOES_CONFIG.contratos || []).find(c => String(c.numero) === String(numero)) : null;
  document.getElementById('formContratoLoc').reset();
  document.getElementById('locCtOriginal').value = contrato ? contrato.numero : '';
  const campoNumero = document.getElementById('locCtNumero');
  campoNumero.value = contrato ? contrato.numero : '';
  // O número identifica o contrato no vínculo dos veículos e na guarda dos documentos:
  // em edição ele fica travado (renumerar soltaria veículos e anexos).
  campoNumero.disabled = !!contrato;
  document.getElementById('locCtDescricao').value = contrato ? contrato.descricao : '';
  document.getElementById('locCtLocatario').value = contrato ? (contrato.locatario || '') : '';
  document.getElementById('locCtAssinado').value = contrato ? locDataParaIso(contrato.assinadoEm || '') : '';
  mostrarErroLoc('locContratoErro', '');
  document.getElementById('locContratoTitulo').textContent = contrato ? 'Editar contrato' : 'Novo contrato';
  abrirModalLoc('modalContratoLoc');
}

async function salvarContratoLoc() {
  const original = document.getElementById('locCtOriginal').value;
  const numero = document.getElementById('locCtNumero').value.trim();
  const descricao = document.getElementById('locCtDescricao').value.trim();
  const locatario = document.getElementById('locCtLocatario').value.trim();
  const assinadoEm = document.getElementById('locCtAssinado').value || '';
  if (!numero || !descricao) { mostrarErroLoc('locContratoErro', 'Informe o número e a descrição do contrato.'); return; }
  const contratos = [...(LOCACOES_CONFIG.contratos || [])];
  if (!original && contratos.some(c => String(c.numero) === numero)) {
    mostrarErroLoc('locContratoErro', `Já existe um contrato com o número ${numero}.`);
    return;
  }
  const botao = document.getElementById('btnSalvarContratoLoc');
  const rotulo = botao.textContent;
  botao.disabled = true; botao.textContent = 'Salvando…';
  try {
    const novo = { numero: original || numero, descricao, locatario, assinadoEm };
    const idx = contratos.findIndex(c => String(c.numero) === String(original || numero));
    if (idx >= 0) contratos[idx] = { ...contratos[idx], ...novo }; else contratos.push(novo);
    await salvarContratosLoc(contratos);
    fecharModalLoc('modalContratoLoc');
    toast(original ? 'Contrato atualizado.' : 'Contrato criado. Anexe os documentos no cartão dele.', 'ok');
  } catch (erro) {
    mostrarErroLoc('locContratoErro', erro.message || 'Não foi possível salvar o contrato.');
  } finally {
    botao.disabled = false; botao.textContent = rotulo;
  }
}

async function excluirContratoLoc(numero) {
  const contrato = (LOCACOES_CONFIG.contratos || []).find(c => String(c.numero) === String(numero));
  if (!contrato) return;
  const veiculos = LOCACOES.filter(l => String(l.contrato || '') === String(numero)).length;
  const docs = documentosContratoLoc(contrato).length;
  const avisos = [
    veiculos ? `${veiculos} veículo(s) vinculados ficarão sem contrato.` : '',
    docs ? `${docs} arquivo(s) anexados serão APAGADOS do sistema.` : '',
  ].filter(Boolean).join(' ');
  if (!(await confirmar(`Excluir o contrato CT ${numero}? ${avisos}`.trim(), { perigo: true, okTexto: 'Excluir contrato' }))) return;
  try {
    await salvarContratosLoc((LOCACOES_CONFIG.contratos || []).filter(c => String(c.numero) !== String(numero)));
    toast('Contrato excluído.', 'ok');
  } catch (erro) {
    toast(erro.message || 'Não foi possível excluir o contrato.', 'erro');
  }
}

// ----- Fatura -----
// Razão social, CNPJ, endereço, e-mail e telefone das duas empresas são escolhidos AQUI, na hora
// de emitir: cada lado tem um seletor de modelos salvos (LOCACOES_CONFIG.fatura.partes) que
// preenche os campos. Editar um campo vale só para esta emissão; "Salvar modelo" guarda.
let LOC_FATURA_REQUISICAO = 0;
const LOC_PARTE_CAMPOS = ['apelido', 'razaoSocial', 'cnpj', 'endereco', 'email', 'telefone'];
const LOC_PARTE_NOVO = '__novo';

function faturaConfigLoc() {
  const fatura = (LOCACOES_CONFIG && LOCACOES_CONFIG.fatura) || {};
  return {
    partes: Array.isArray(fatura.partes) ? fatura.partes : [],
    emitentePadrao: fatura.emitentePadrao || '',
    destinatarioPadrao: fatura.destinatarioPadrao || '',
    diaEmissao: Number(fatura.diaEmissao) || 10,
    diaVencimento: Number(fatura.diaVencimento) || 15,
    observacoes: Array.isArray(fatura.observacoes) ? fatura.observacoes : [],
  };
}
function campoParteLoc(prefixo, campo) {
  return document.getElementById('locParte' + prefixo + campo.charAt(0).toUpperCase() + campo.slice(1));
}
function preencherModelosParteLoc(prefixo, selecionado) {
  const select = document.getElementById('locParte' + prefixo + 'Modelo');
  if (!select) return;
  const partes = faturaConfigLoc().partes;
  select.innerHTML = partes.map(parte =>
    '<option value="' + esc(parte.id) + '"' + (parte.id === selecionado ? ' selected' : '') + '>'
    + esc(parte.apelido || parte.razaoSocial) + '</option>').join('')
    + '<option value="' + LOC_PARTE_NOVO + '"' + (selecionado === LOC_PARTE_NOVO ? ' selected' : '') + '>+ Nova empresa</option>';
  if (select._syncCustom) select._syncCustom();
  const excluir = document.querySelector('[data-parte-excluir="' + prefixo + '"]');
  if (excluir) excluir.hidden = select.value === LOC_PARTE_NOVO || partes.length < 2;
}
function aplicarParteNosCamposLoc(prefixo, parte) {
  for (const campo of LOC_PARTE_CAMPOS) {
    const el = campoParteLoc(prefixo, campo);
    if (el) el.value = (parte && parte[campo]) || '';
  }
}
function lerParteDosCamposLoc(prefixo) {
  const dados = {};
  for (const campo of LOC_PARTE_CAMPOS) {
    const el = campoParteLoc(prefixo, campo);
    dados[campo] = el ? el.value.trim() : '';
  }
  return dados;
}
function idModeloParteLoc(prefixo) {
  const select = document.getElementById('locParte' + prefixo + 'Modelo');
  const valor = select ? select.value : '';
  return valor === LOC_PARTE_NOVO ? '' : valor;
}
// Troca de modelo: repõe os campos com o que está salvo (ou limpa, para cadastrar outra empresa).
function trocarModeloParteLoc(prefixo) {
  const select = document.getElementById('locParte' + prefixo + 'Modelo');
  if (!select) return;
  const parte = faturaConfigLoc().partes.find(p => p.id === select.value);
  aplicarParteNosCamposLoc(prefixo, parte || null);
  const excluir = document.querySelector('[data-parte-excluir="' + prefixo + '"]');
  if (excluir) excluir.hidden = select.value === LOC_PARTE_NOVO || faturaConfigLoc().partes.length < 2;
  carregarPreviewFaturaLoc();
}
async function salvarConfigFaturaLoc(fatura, mensagem) {
  const resposta = await fetch('/api/locacoes/config', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ ...LOCACOES_CONFIG, fatura }),
  });
  const dados = await resposta.json().catch(() => ({}));
  if (!resposta.ok) throw new Error(dados.erro || 'Não foi possível salvar.');
  LOCACOES_CONFIG = dados;
  if (mensagem) toast(mensagem, 'ok');
  return dados;
}
async function salvarModeloParteLoc(prefixo) {
  const dados = lerParteDosCamposLoc(prefixo);
  if (!dados.razaoSocial) { mostrarErroLoc('locFaturaErro', 'Informe a razão social antes de salvar o modelo.'); return; }
  const config = faturaConfigLoc();
  const id = idModeloParteLoc(prefixo);
  const partes = config.partes.map(p => ({ ...p }));
  const papel = prefixo === 'Emit' ? 'locadora' : 'locataria';
  let idFinal = id;
  const existente = partes.find(p => p.id === id);
  if (existente) Object.assign(existente, dados);
  else {
    idFinal = 'parte-' + Date.now().toString(36);
    partes.push({ id: idFinal, papel, ...dados });
  }
  try {
    await salvarConfigFaturaLoc({
      ...config,
      partes,
      emitentePadrao: prefixo === 'Emit' ? idFinal : config.emitentePadrao,
      destinatarioPadrao: prefixo === 'Dest' ? idFinal : config.destinatarioPadrao,
    }, 'Modelo salvo. Da próxima vez ele já vem preenchido.');
    preencherModelosParteLoc(prefixo, idFinal);
    mostrarErroLoc('locFaturaErro', '');
    carregarPreviewFaturaLoc();
  } catch (erro) {
    mostrarErroLoc('locFaturaErro', erro.message || 'Não foi possível salvar o modelo.');
  }
}
async function excluirModeloParteLoc(prefixo) {
  const id = idModeloParteLoc(prefixo);
  const config = faturaConfigLoc();
  const parte = config.partes.find(p => p.id === id);
  if (!parte) return;
  if (config.partes.length < 2) { mostrarErroLoc('locFaturaErro', 'É preciso manter ao menos uma empresa cadastrada.'); return; }
  if (!(await confirmar('Excluir o modelo "' + (parte.apelido || parte.razaoSocial) + '"? As faturas já geradas não mudam.'))) return;
  try {
    await salvarConfigFaturaLoc({ ...config, partes: config.partes.filter(p => p.id !== id) }, 'Modelo excluído.');
    const restante = faturaConfigLoc();
    const proximo = prefixo === 'Emit' ? restante.emitentePadrao : restante.destinatarioPadrao;
    preencherModelosParteLoc(prefixo, proximo);
    aplicarParteNosCamposLoc(prefixo, restante.partes.find(p => p.id === proximo) || null);
    carregarPreviewFaturaLoc();
  } catch (erro) {
    mostrarErroLoc('locFaturaErro', erro.message || 'Não foi possível excluir o modelo.');
  }
}
function corpoFaturaLoc() {
  return {
    mes: document.getElementById('faturaMes').value,
    ano: document.getElementById('faturaAno').value,
    emitente: idModeloParteLoc('Emit'),
    destinatario: idModeloParteLoc('Dest'),
    emitenteDados: lerParteDosCamposLoc('Emit'),
    destinatarioDados: lerParteDosCamposLoc('Dest'),
  };
}
async function carregarPreviewFaturaLoc() {
  const carregando = document.getElementById('locFaturaCarregando');
  const preview = document.getElementById('locFaturaPreview');
  const erroEl = document.getElementById('locFaturaErro');
  const botao = document.getElementById('btnGerarFaturaLoc');
  const requisicao = ++LOC_FATURA_REQUISICAO;
  carregando.hidden = false;
  preview.hidden = true;
  erroEl.hidden = true;
  botao.disabled = true;
  try {
    const resposta = await fetch('/api/locacoes/fatura', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      cache: 'no-store',
      body: JSON.stringify(corpoFaturaLoc()),
    });
    const dados = await resposta.json().catch(() => ({}));
    if (!resposta.ok) throw new Error(dados.erro || 'Não foi possível calcular a cobrança.');
    if (!(dados.schemaVersao >= 3)) {
      let versaoServidor = '';
      try {
        const info = await (await fetch('/api/versao', { cache: 'no-store' })).json();
        versaoServidor = info && info.versao ? ` v${info.versao}` : '';
      } catch (e) { /* diagnóstico opcional */ }
      throw new Error(`Servidor${versaoServidor} desatualizado. Reinicie o servidor ou conclua o deploy antes de gerar a fatura.`);
    }
    if (requisicao !== LOC_FATURA_REQUISICAO) return;
    document.getElementById('locFaturaEmitente').textContent = (dados.emitente && dados.emitente.razaoSocial) || '—';
    document.getElementById('locFaturaDestinatario').textContent = (dados.destinatario && dados.destinatario.razaoSocial) || '—';
    document.getElementById('locFaturaReferencia').textContent = 'Referente a ' + (dados.referencia || '—');
    document.getElementById('locFaturaPeriodo').textContent = 'Período: ' + (dados.periodoInicio || '') + ' a ' + (dados.periodoFim || '');
    document.getElementById('locFaturaDatas').textContent = 'Emissão ' + (dados.emissao || '—') + ' · vence ' + (dados.vencimento || '—');
    notaHistoricoFaturaLoc(dados.competencia);
    document.getElementById('locFaturaLinhas').innerHTML = dados.itens && dados.itens.length
      ? dados.itens.map(item => '<tr>'
        + '<td>' + esc(item.idx) + '</td>'
        + '<td>' + esc(item.modelo || '—') + (item.tipo && item.tipo !== 'veiculo' ? ' <span class="tipo-tag">' + esc(item.tipoRotulo || '') + '</span>' : '') + '</td>'
        + '<td class="loc-fatura-placa">' + esc(item.identificador || item.placa || '—') + '</td>'
        + '<td>' + esc(item.periodo) + '</td>'
        + '<td class="num">' + esc(item.dias) + '</td>'
        + '<td class="num">' + esc(fmtMoneyDec(item.valor)) + '</td>'
        + '</tr>').join('')
      : '<tr><td colspan="6" class="loc-fatura-sem-itens">Nenhuma locação ativa nesta competência.</td></tr>';
    document.getElementById('locFaturaSubtotal').textContent = fmtMoneyDec(dados.subtotal);
    const ajustesLinha = document.getElementById('locFaturaAjustesLinha');
    ajustesLinha.hidden = !dados.totalAjustes;
    document.getElementById('locFaturaAjustes').textContent = fmtMoneyDec(dados.totalAjustes);
    document.getElementById('locFaturaTotal').textContent = fmtMoneyDec(dados.totalLiquido);
    preview.hidden = false;
    botao.disabled = !dados.itens || !dados.itens.length;
  } catch (erro) {
    if (requisicao !== LOC_FATURA_REQUISICAO) return;
    erroEl.textContent = erro.message || 'Não foi possível calcular a cobrança.';
    erroEl.hidden = false;
  } finally {
    if (requisicao === LOC_FATURA_REQUISICAO) carregando.hidden = true;
  }
}
// A competência é o mês JÁ RODADO: o ciclo vai do dia 15 ao dia 14 e a fatura sai antes de ele
// fechar (em 10/08 cobra-se julho). Antes do dia 15, então, o mês em aberto é o anterior.
function competenciaVigenteLoc(hoje = new Date()) {
  const base = new Date(hoje.getFullYear(), hoje.getMonth(), 1);
  if (hoje.getDate() < 15) base.setMonth(base.getMonth() - 1);
  return { mes: String(base.getMonth() + 1).padStart(2, '0'), ano: String(base.getFullYear()) };
}
function atualizarCicloFaturaLoc() {
  const aviso = document.getElementById('locFaturaCiclo');
  if (!aviso) return;
  const mes = Number(document.getElementById('faturaMes').value);
  const ano = Number(document.getElementById('faturaAno').value);
  if (!mes || !ano) { aviso.textContent = ''; return; }
  const config = faturaConfigLoc();
  const dia = (numero, mesIndice) => new Date(ano, mesIndice, numero).toLocaleDateString('pt-BR');
  aviso.textContent = 'Cobra o período de ' + dia(15, mes - 1) + ' a ' + dia(14, mes)
    + ', com emissão em ' + dia(config.diaEmissao, mes) + ' e vencimento em ' + dia(config.diaVencimento, mes) + '.';
}
function abrirFaturaLoc() {
  const vigente = competenciaVigenteLoc();
  document.getElementById('faturaMes').value = vigente.mes;
  document.getElementById('faturaAno').value = vigente.ano;
  syncCustomSelects();
  const config = faturaConfigLoc();
  const emitente = config.partes.find(p => p.id === config.emitentePadrao) || config.partes[0] || null;
  const destinatario = config.partes.find(p => p.id === config.destinatarioPadrao) || config.partes[1] || null;
  preencherModelosParteLoc('Emit', emitente ? emitente.id : LOC_PARTE_NOVO);
  preencherModelosParteLoc('Dest', destinatario ? destinatario.id : LOC_PARTE_NOVO);
  aplicarParteNosCamposLoc('Emit', emitente);
  aplicarParteNosCamposLoc('Dest', destinatario);
  atualizarCicloFaturaLoc();
  abrirModalLoc('modalFaturaLoc');
  carregarPreviewFaturaLoc();
}
async function gerarFaturaLoc() {
  const corpo = corpoFaturaLoc();
  const botao = document.getElementById('btnGerarFaturaLoc');
  const erroEl = document.getElementById('locFaturaErro');
  const rotulo = botao.textContent;
  const novaAba = window.open('about:blank', '_blank');
  if (novaAba) novaAba.opener = null;
  botao.disabled = true;
  botao.textContent = 'Gerando PDF…';
  erroEl.hidden = true;
  try {
    const resposta = await fetch('/api/locacoes/fatura/pdf', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      cache: 'no-store',
      body: JSON.stringify(corpo),
    });
    if (!resposta.ok) {
      const dados = await resposta.json().catch(() => ({}));
      throw new Error(dados.erro || 'Não foi possível gerar o PDF.');
    }
    if (!(resposta.headers.get('content-type') || '').toLowerCase().startsWith('application/pdf')) {
      throw new Error('O servidor desatualizado não retornou um PDF. Reinicie o servidor ou conclua o deploy.');
    }
    const urlPdf = URL.createObjectURL(await resposta.blob());
    if (novaAba) novaAba.location.replace(urlPdf);
    else {
      const link = document.createElement('a');
      link.href = urlPdf;
      link.download = `cobranca-locacoes-${corpo.ano}-${corpo.mes}.pdf`;
      link.click();
    }
    setTimeout(() => URL.revokeObjectURL(urlPdf), 120000);
    fecharModalLoc('modalFaturaLoc');
    // O servidor guardou o PDF no histórico: recarrega para a sub-aba Faturas já mostrar a linha.
    await carregarLocacoes();
    toast('PDF gerado e guardado em Locações › Faturas. Marque "Enviada" quando mandar ao cliente.', 'ok');
  } catch (erro) {
    if (novaAba) novaAba.close();
    erroEl.textContent = erro.message || 'Não foi possível gerar o PDF.';
    erroEl.hidden = false;
  } finally {
    botao.disabled = false;
    botao.textContent = rotulo;
  }
}

// ----- Config -----
async function abrirConfigLoc() {
  mostrarErroLoc('locConfigErro', '');
  try {
    const resposta = await fetch('/api/locacoes/config', { cache: 'no-store' });
    const dados = await resposta.json().catch(() => ({}));
    if (!resposta.ok) throw new Error(dados.erro || 'Não foi possível carregar as configurações.');
    LOCACOES_CONFIG = dados;
    const ipca = LOCACOES_CONFIG.ipca || {};
    document.getElementById('locConfigIpca').value = Object.entries(ipca).sort(([a], [b]) => Number(a) - Number(b)).map(([ano, taxa]) => ano + '=' + taxa).join('\n');
    const fatura = faturaConfigLoc();
    document.getElementById('locConfigDiaEmissao').value = fatura.diaEmissao;
    document.getElementById('locConfigDiaVencimento').value = fatura.diaVencimento;
    document.getElementById('locConfigObs').value = fatura.observacoes.join('\n');
    abrirModalLoc('modalLocConfig');
  } catch (erro) {
    toast(erro.message || 'Não foi possível carregar as configurações.', 'erro');
  }
}
async function salvarConfigLoc() {
  const ipca = {};
  for (const linha of (document.getElementById('locConfigIpca').value || '').split('\n')) {
    if (!linha.trim()) continue;
    const [ano, taxa] = linha.split('=');
    const chave = (ano || '').trim();
    const valor = parseFloat((taxa || '').trim().replace(',', '.'));
    if (!/^\d{4}$/.test(chave) || !Number.isFinite(valor)) {
      mostrarErroLoc('locConfigErro', `Revise a linha de IPCA: “${linha}”. Use ano=taxa.`);
      return;
    }
    ipca[chave] = valor;
  }
  // Contratos são gerenciados pelos cartões da sub-aba Documentos: aqui só o IPCA muda,
  // e a lista atual segue no corpo para o servidor preservar tudo (inclusive locatário).
  const contratos = LOCACOES_CONFIG.contratos || [];
  // Os modelos de empresa não são editados aqui (ficam na tela de gerar fatura): seguem intactos.
  const diaEmissao = Number(document.getElementById('locConfigDiaEmissao').value);
  const diaVencimento = Number(document.getElementById('locConfigDiaVencimento').value);
  const diaValido = (numero) => Number.isInteger(numero) && numero >= 1 && numero <= 28;
  if (!diaValido(diaEmissao) || !diaValido(diaVencimento)) {
    mostrarErroLoc('locConfigErro', 'Os dias de emissão e vencimento devem ficar entre 1 e 28.');
    return;
  }
  const fatura = {
    ...faturaConfigLoc(),
    diaEmissao,
    diaVencimento,
    observacoes: (document.getElementById('locConfigObs').value || '').split('\n').map(l => l.trim()).filter(Boolean),
  };
  const botao = document.getElementById('btnSalvarConfigLoc');
  const rotulo = botao.textContent;
  botao.disabled = true;
  botao.textContent = 'Salvando…';
  mostrarErroLoc('locConfigErro', '');
  try {
    const resposta = await fetch('/api/locacoes/config', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...LOCACOES_CONFIG, ipca, contratos, fatura }),
    });
    const dados = await resposta.json().catch(() => ({}));
    if (!resposta.ok) throw new Error(dados.erro || 'Não foi possível salvar as configurações.');
    LOCACOES_CONFIG = dados;
    fecharModalLoc('modalLocConfig');
    await carregarLocacoes();
    toast('Configurações salvas.', 'ok');
  } catch (erro) {
    mostrarErroLoc('locConfigErro', erro.message || 'Não foi possível salvar as configurações.');
  } finally {
    botao.disabled = false;
    botao.textContent = rotulo;
  }
}


