async function enviarDocsLoc(numero, arquivos) {
  try {
    await anexarDocumentosContratoLoc(numero, arquivos);
  } catch (erro) {
    toast(erro.message || 'Não foi possível anexar os documentos.', 'erro');
  }
}
if (locDocsPainelEl) {
  locDocsPainelEl.addEventListener('click', async evento => {
    const ctEditar = evento.target.closest('[data-loc-ct-edit]');
    if (ctEditar) { abrirContratoLocModal(ctEditar.dataset.locCtEdit); return; }
    const ctExcluir = evento.target.closest('[data-loc-ct-del]');
    if (ctExcluir) { excluirContratoLoc(ctExcluir.dataset.locCtDel); return; }
    const anexar = evento.target.closest('[data-loc-doc-add]');
    if (anexar) {
      LOC_DOC_CONTRATO_ATUAL = anexar.dataset.locDocAdd || '';
      if (inputDocsLocEl) inputDocsLocEl.click();
      return;
    }
    const remover = evento.target.closest('[data-loc-doc-rem]');
    if (!remover) return;
    const numero = remover.dataset.numero || '';
    const id = remover.dataset.locDocRem || '';
    if (!(await confirmar('Excluir este documento do contrato? O arquivo é apagado do sistema.', { perigo: true, okTexto: 'Excluir' }))) return;
    try {
      await removerDocumentoContratoLoc(numero, id);
      toast('Documento excluído.', 'ok');
    } catch (erro) {
      toast(erro.message || 'Não foi possível remover o documento.', 'erro');
    }
  });
  // Arrastar-e-soltar direto no cartão do contrato.
  locDocsPainelEl.addEventListener('dragover', evento => {
    const cartao = evento.target.closest('.loc-doc-contrato.pode-soltar');
    if (!cartao) return;
    evento.preventDefault();
    cartao.classList.add('arrastando');
  });
  locDocsPainelEl.addEventListener('dragleave', evento => {
    const cartao = evento.target.closest('.loc-doc-contrato');
    if (cartao && !cartao.contains(evento.relatedTarget)) cartao.classList.remove('arrastando');
  });
  locDocsPainelEl.addEventListener('drop', evento => {
    const cartao = evento.target.closest('.loc-doc-contrato.pode-soltar');
    if (!cartao) return;
    evento.preventDefault();
    cartao.classList.remove('arrastando');
    const arquivos = evento.dataTransfer && evento.dataTransfer.files;
    if (arquivos && arquivos.length) enviarDocsLoc(cartao.dataset.contrato || '', arquivos);
  });
}
if (inputDocsLocEl) inputDocsLocEl.addEventListener('change', async () => {
  const arquivos = [...(inputDocsLocEl.files || [])];
  const numero = LOC_DOC_CONTRATO_ATUAL;
  inputDocsLocEl.value = '';
  LOC_DOC_CONTRATO_ATUAL = '';
  if (!arquivos.length || !numero) return;
  await enviarDocsLoc(numero, arquivos);
});
