// ===================== PWA NOTIFICAÇÕES =====================
// Registra o service worker p/ notificações push (funciona no PWA do celular)
(function registrarSW() {
  if (!('serviceWorker' in navigator) || !('Notification' in window)) return;
  navigator.serviceWorker.register('/sw.js').then(reg => {
    // Verifica notificações pendentes a cada 30 min
    verificarNotificacoes();
    setInterval(verificarNotificacoes, 30 * 60 * 1000);
    // Escuta mensagens do SW (ex: badge de notificação)
    navigator.serviceWorker.addEventListener('message', e => {
      if (e.data && e.data.tipo === 'notificacao') {
        mostrarNotificacao(e.data.titulo, e.data.mensagem);
      }
    });
  }).catch(() => {});
})();

async function verificarNotificacoes() {
  if (!('Notification' in window) || Notification.permission === 'denied') return;
  if (Notification.permission === 'default') {
    Notification.requestPermission();
    return;
  }
  if (Notification.permission !== 'granted') return;
  try {
    const r = await fetch('/api/locacoes/notificacoes', { cache: 'no-store' });
    if (!r.ok) return;
    const lista = await r.json();
    if (!lista || !lista.length) return;
    // Mostra a primeira notificação pendente (as demais serão mostradas na próxima verificação)
    const n = lista[0];
    await navigator.serviceWorker.ready;
    const reg = await navigator.serviceWorker.ready;
    // Envia notificação via service worker (funciona mesmo com o app fechado no PWA)
    // Opção 1: Push é server-side (mais complexo). Opção 2: mostrar local se app estiver aberto.
    if (document.visibilityState === 'visible') {
      // App aberto: mostra toast + badge no sidebar
      toast('🔔 ' + n.mensagem, 'aviso');
    }
    // Tenta notificação nativa
    if ('showNotification' in reg) {
      reg.showNotification('Gestão RM · Locações', {
        body: n.mensagem,
        icon: '/icon-192.png',
        badge: '/favicon-64.png',
        vibrate: [200, 100, 200],
        tag: 'locacao-' + n.id,
        data: { url: '/locacoes' },
      });
    }
  } catch (e) { /* falha silenciosa */ }
}

/* ============================================================
   REGISTRO DO "SELECIONAR TODOS" DAS 9 ABAS COM SELEÇÃO
   Fica no fim do arquivo de propósito: `cfg.selecao` é lido na hora da chamada e os
   `const SELECAO_*` não hasteiam (TDZ). Aqui em baixo todos já existem, e os `render*`/
   filtros são declarações de função (essas hasteiam).
   `lista` tem de devolver EXATAMENTE o que a tabela desenha — ver as três exceções.
   ============================================================ */
const SEL_TODOS_FROTA = criarSelecionarTodos({
  id: 'selTodosFrota', selecao: SELECAO_FROTA,
  chave: (v) => v.placa, // ⚠️ a Frota é a única que guarda PLACA; as outras 8 guardam id
  lista: aplicarFiltros, aoMudar: renderTabela,
});
const SEL_TODOS_MULTAS = criarSelecionarTodos({
  id: 'selTodosMultas', selecao: SELECAO_MULTAS, chave: (m) => m.id,
  lista: aplicarFiltrosMulta, aoMudar: renderMultas,
});
const SEL_TODOS_RAST = criarSelecionarTodos({
  id: 'selTodosRast', selecao: SELECAO_RAST, chave: (r) => r.id,
  lista: aplicarFiltrosRast, aoMudar: renderRast,
});
const SEL_TODOS_CONTR = criarSelecionarTodos({
  id: 'selTodosContr', selecao: SELECAO_CONTR, chave: (c) => c.id,
  lista: aplicarFiltrosContr, aoMudar: renderContratos,
});
const SEL_TODOS_ALMOX = criarSelecionarTodos({
  id: 'selTodosAlmox', selecao: SELECAO_ALMOX, chave: (r) => r.id,
  lista: almoxFiltradas, aoMudar: renderAlmoxTabela,
});
const SEL_TODOS_EPI_FICHA = criarSelecionarTodos({
  id: 'selTodosEpiFicha', selecao: SELECAO_EPI_FICHA, chave: (m) => m.id,
  lista: epiFiltradasFichas, aoMudar: renderEpiFichas,
});
const SEL_TODOS_MNT = criarSelecionarTodos({
  id: 'selTodosMnt', selecao: SELECAO_MNT, chave: (e) => e.id,
  // ⚠️ mntFiltrados() NÃO conhece as abas Todos/Corretiva/Preventiva — quem aplica
  // `mntTipoTab` é o renderEventosMnt. Sem repetir isso aqui, "todos" marcaria preventivas
  // que não estão na tela.
  lista: () => { const b = mntFiltrados(); return mntTipoTab === 'all' ? b : b.filter((e) => (mntTipoTab === 'Corretiva') === ehCorretiva(e)); },
  aoMudar: renderEventosMnt,
});
const SEL_TODOS_ABT = criarSelecionarTodos({
  id: 'selTodosAbt', selecao: SELECAO_ABT, chave: (t) => t.id,
  lista: () => abtFiltrados(), aoMudar: () => renderTransacoesAbt(),
});
const SEL_TODOS_FUNC = criarSelecionarTodos({
  id: 'selTodosFunc', selecao: SELECAO_FUNC, chave: (f) => f.id,
  // ⚠️ a tabela Detalhes recebe `ativos`, não `funcFiltrados()` cru: as visões de ativos
  // escondem os Desligados. Cru, "todos" marcaria desmobilizados invisíveis — e o
  // "⬇ Exportar selecionados" os traria.
  lista: () => funcFiltrados().filter((f) => (f.status || 'Ativo') !== 'Desligado'),
  // A .func-topo é compartilhada pelas 6 visões; o controle só faz sentido na tabela.
  visivel: () => funcEstado.vis === 'detalhes',
  aoMudar: renderFuncionarios,
});
// Integração › Acompanhamento (1.55.40): só convites NÃO concluídos são selecionáveis (concluído
// não se exclui) e só quem EDITA a Integração vê o controle.
// Ex.: filtro "Aguardando" com 12 linhas → "Selecionar todos (12)" marca as 12 e a barra oferece "Excluir selecionados".
const SEL_TODOS_ACMP = criarSelecionarTodos({
  id: 'selTodosAcmp', selecao: SELECAO_ACMP, chave: (a) => a.id,
  lista: () => (permissaoAtual('integracao') === 'editar' ? acmpSelecionaveis(acmpFiltrados()) : []),
  visivel: () => permissaoAtual('integracao') === 'editar',
  aoMudar: renderAcompanhamento,
});

/* ============================================================
   REDIMENSIONAMENTO DE COLUNAS (estilo Excel) — GLOBAL
   Vale para QUALQUER `<table>` dentro de `.tabela-wrap`, atual ou futura,
   sem configurar tela a tela. Como as ~190 funções render* reescrevem o
   innerHTML do thead/tbody a cada filtro/ordenação/página, NADA aqui vive
   dentro do <th>: a divisória é detectada por proximidade da borda direita
   (mousemove delegado no document) e a largura mora num `<colgroup
   data-redim>` — irmão do thead/tbody, que os render* não destroem.
   O modo `table-layout: fixed` (.ds-tabela-redim) só liga na PRIMEIRA vez
   que a tabela é redimensionada (opt-in — zero regressão), congelando antes
   as larguras atuais para não haver salto visual. Persistência em
   localStorage (chave `colw-<tabela>`, mapa {coluna: px} casado por
   data-campo/data-ord — coluna nova ou reordenada não quebra), no mesmo
   espírito da densidade (`dens-<sectionId>`): escolha de exibição, não dado
   do sistema. Um MutationObserver reaplica quando a tabela é recriada.
   Desativado em <768px (lá as tabelas viram cartões, design-mobile.css).
   CSS par: design-system/10-tabela-resize.css.
   As divisórias são VISÍVEIS em permanência no cabeçalho (linha fina no
   ::after de cada th folha — CSS par) e o arraste é COMPARTILHADO como no
   Excel: mover a divisória entre A e B alarga A e encolhe B (a largura
   total da tabela não muda); só a última coluna, sem vizinha, muda sozinha.
   Exemplo de uso (é automático, mas dá para operar por código):
     - arrastar a divisória entre "Descrição" e "Data" nas Multas 50px à
       direita → Descrição +50, Data −50, e o mapa
       localStorage['colw-tabelaMultas'] vira {"descricao": 470, "dataInfracao": 60};
       sobrevive a filtro, paginação, ordenação e F5;
     - duplo clique na mesma divisória → remove só "descricao" do mapa
       (a coluna volta ao automático, as demais ficam);
     - botão ↔ na toolbar da aba (aparece só com largura salva) →
       resetarTabelaColw(t) em cada tabela da section, apagando tudo.
   ============================================================ */
(() => {
  const COLW_MIN = 48; // px — menor largura de coluna permitida no arraste
  const COLW_MAX = 640; // px — maior largura de coluna permitida no arraste
  const COLW_PADRAO = 120; // px — coluna nova/sem valor salvo numa tabela já redimensionada e oculta
  const COLW_ZONA_PX = 8; // px da borda direita do th que contam como "divisória"
  const mqColwDesktop = window.matchMedia('(min-width: 768px)');

  // Identidade estável da tabela para a chave do localStorage. Prioridade:
  // data-colw-id (desempate manual) > id da tabela > id do tr do cabeçalho
  // (padrão `cabecalho*` do projeto) > sectionId + posição.
  function chaveTabelaColw(table) {
    if (table.dataset.colwId) return table.dataset.colwId;
    if (table.id) return table.id;
    const tr = table.tHead && table.tHead.querySelector('tr[id]');
    if (tr && tr.id) return tr.id;
    const sec = table.closest('section[id]');
    if (!sec) return '';
    const todas = Array.from(sec.querySelectorAll('.tabela-wrap table'));
    return sec.id + '-t' + todas.indexOf(table);
  }
  function chaveStorageColw(table) {
    const k = chaveTabelaColw(table);
    return k ? 'colw-' + k : '';
  }
  function lerColw(table) {
    try {
      const k = chaveStorageColw(table);
      const bruto = k && localStorage.getItem(k);
      const mapa = bruto ? JSON.parse(bruto) : null;
      return mapa && typeof mapa === 'object' ? mapa : null;
    } catch (e) { return null; }
  }
  function salvarColw(table, mapa) {
    try {
      const k = chaveStorageColw(table);
      if (k) localStorage.setItem(k, JSON.stringify(mapa));
    } catch (e) { /* ignora */ }
  }
  function apagarColw(table) {
    try {
      const k = chaveStorageColw(table);
      if (k) localStorage.removeItem(k);
    } catch (e) { /* ignora */ }
  }

  // A linha de referência é a ÚLTIMA do thead (a que tem as colunas-folha);
  // th com colspan > 1 é agrupador e não oferece divisória.
  function linhaCabecalhoColw(table) {
    const h = table.tHead;
    return h && h.rows.length ? h.rows[h.rows.length - 1] : null;
  }
  function chaveColunaColw(th, indiceFolha) {
    return th.dataset.campo || th.dataset.ord || ('i' + indiceFolha);
  }
  function totalColunasFolha(tr) {
    let n = 0;
    for (const th of tr.cells) n += th.colSpan || 1;
    return n;
  }
  function indiceFolhaDoTh(tr, th) {
    let i = 0;
    for (const c of tr.cells) {
      if (c === th) return i;
      i += c.colSpan || 1;
    }
    return -1;
  }

  // Cria/sincroniza o <colgroup data-redim> com o nº de colunas-folha atual.
  function garanteColgroupColw(table) {
    const tr = linhaCabecalhoColw(table);
    if (!tr || !tr.cells.length) return null;
    const n = totalColunasFolha(tr);
    let cg = table.querySelector(':scope > colgroup[data-redim]');
    if (!cg) {
      cg = document.createElement('colgroup');
      cg.dataset.redim = '1';
      table.insertBefore(cg, table.firstChild);
    }
    while (cg.children.length < n) cg.appendChild(document.createElement('col'));
    while (cg.children.length > n) cg.removeChild(cg.lastChild);
    return cg;
  }

  // A largura da TABELA é gravada em px = soma dos <col>. Sem isso o browser
  // decide sozinho: `width:auto` clampa no wrapper e espreme as colunas;
  // `width:max-content` mede o CONTEÚDO das células mesmo em fixed e infla
  // coluna encolhida (os dois testados no Chromium). Falta largura em algum
  // <col> (coluna recém-restaurada ao automático) → devolve o controle ao CSS
  // (min-width:100%).
  function sincronizarLarguraColw(table, cg) {
    let soma = 0;
    for (const col of cg.children) {
      const w = parseFloat(col.style.width);
      if (!isFinite(w)) { table.style.width = ''; return; }
      soma += w;
    }
    table.style.width = soma + 'px';
  }

  // Liga o modo largura-manual: congela as larguras ATUAIS nos <col> antes de
  // ativar table-layout:fixed — sem isso a tabela "pula" no primeiro arraste.
  function ativarColw(table) {
    const cg = garanteColgroupColw(table);
    if (!cg) return null;
    if (!table.classList.contains('ds-tabela-redim')) {
      const tr = linhaCabecalhoColw(table);
      let i = 0;
      for (const th of tr.cells) {
        if ((th.colSpan || 1) === 1 && cg.children[i] && !cg.children[i].style.width) {
          cg.children[i].style.width = th.offsetWidth + 'px';
        }
        i += th.colSpan || 1;
      }
      table.classList.add('ds-tabela-redim');
      sincronizarLarguraColw(table, cg);
    }
    return cg;
  }

  // Reaplica as larguras salvas (boot, troca de aba, tabela recriada). Coluna
  // que não está no mapa recebe o tamanho ATUAL (ou COLW_PADRAO se a tabela
  // estiver oculta) — todo <col> precisa de largura para a soma da tabela
  // fechar e as salvas valerem EXATAS, sem redistribuição do browser.
  function aplicarColwSalvas(table) {
    const mapa = lerColw(table);
    if (!mapa || !Object.keys(mapa).length) return;
    const tr = linhaCabecalhoColw(table);
    if (!tr || !tr.cells.length) return;
    const cg = garanteColgroupColw(table);
    if (!cg) return;
    let i = 0, aplicou = false;
    for (const th of tr.cells) {
      if ((th.colSpan || 1) === 1 && cg.children[i]) {
        const w = mapa[chaveColunaColw(th, i)];
        if (typeof w === 'number' && isFinite(w)) {
          cg.children[i].style.width = Math.min(COLW_MAX, Math.max(COLW_MIN, w)) + 'px';
          aplicou = true;
        } else if (!cg.children[i].style.width) {
          cg.children[i].style.width = (th.offsetWidth || COLW_PADRAO) + 'px';
        }
      }
      i += th.colSpan || 1;
    }
    if (aplicou) {
      table.classList.add('ds-tabela-redim');
      sincronizarLarguraColw(table, cg);
    }
  }

  // Volta a tabela inteira ao layout automático original.
  function resetarTabelaColw(table) {
    apagarColw(table);
    table.classList.remove('ds-tabela-redim');
    table.style.width = '';
    const cg = table.querySelector(':scope > colgroup[data-redim]');
    if (cg) cg.remove();
  }

  // ---- divisória: detecção por proximidade (nenhum elemento injetado) ----
  // A zona vale dos DOIS lados da linha: perto da borda direita do th, ou perto
  // da borda esquerda do th seguinte (que é a MESMA divisória — devolve o anterior).
  function thDivisoriaColw(e) {
    if (!mqColwDesktop.matches) return null;
    const alvo = e.target;
    const th = alvo && alvo.closest ? alvo.closest('.tabela-wrap th') : null;
    if (!th) return null;
    const r = th.getBoundingClientRect();
    if ((th.colSpan || 1) === 1 && (r.right - e.clientX) <= COLW_ZONA_PX && e.clientX <= r.right) return th;
    const ant = th.previousElementSibling;
    if (ant && ant.tagName === 'TH' && (ant.colSpan || 1) === 1
      && (e.clientX - r.left) <= COLW_ZONA_PX && e.clientX >= r.left) return ant;
    return null;
  }

  // Vizinha da direita (coluna-folha): com ela o arraste é COMPARTILHADO como no
  // Excel — a divisória move o par (A cresce, B encolhe) sem mudar a largura
  // total da tabela. Sem vizinha (última coluna), só a própria coluna muda.
  function thVizinhoColw(th) {
    const viz = th.nextElementSibling;
    return viz && viz.tagName === 'TH' && (viz.colSpan || 1) === 1 ? viz : null;
  }

  let thBorda = null; // th atualmente marcado com .ds-col-borda
  let arrasto = null; // estado do arraste em curso

  // O cursor vai TAMBÉM inline: regra legada por #id (ex.: `#cstTabelaLanc
  // [data-cstord] { cursor: pointer }`) venceria a classe, e !important é
  // proibido — inline ganha de qualquer seletor.
  function marcarBordaColw(th) {
    th.classList.add('ds-col-borda');
    th.style.cursor = 'col-resize';
  }
  function desmarcarBordaColw(th) {
    th.classList.remove('ds-col-borda');
    th.style.cursor = '';
  }

  document.addEventListener('mousemove', (e) => {
    if (arrasto) return;
    const th = thDivisoriaColw(e);
    if (th === thBorda) return;
    if (thBorda) desmarcarBordaColw(thBorda);
    thBorda = th;
    if (th) marcarBordaColw(th);
  }, { passive: true });

  // cruzou o breakpoint (desktop ↔ celular): não deixa marcação órfã para trás
  mqColwDesktop.addEventListener('change', () => {
    if (thBorda) { desmarcarBordaColw(thBorda); thBorda = null; }
  });

  document.addEventListener('pointerdown', (e) => {
    if (e.button !== 0) return;
    const th = thDivisoriaColw(e);
    if (!th) return;
    const table = th.closest('table');
    const tr = table && linhaCabecalhoColw(table);
    if (!tr || th.parentElement !== tr) return;
    e.preventDefault(); // não inicia seleção de texto nem foco
    const thViz = thVizinhoColw(th);
    arrasto = {
      table, th, thViz,
      indice: indiceFolhaDoTh(tr, th),
      xIni: e.clientX,
      wIni: th.offsetWidth,
      wIniViz: thViz ? thViz.offsetWidth : 0,
      col: null, // criado no primeiro movimento (clique parado não liga o modo)
      colViz: null,
    };
    th.classList.add('ds-col-redimensionando'); // linha-guia acesa durante o arraste
    document.body.classList.add('ds-redimensionando');
  }, true);

  document.addEventListener('pointermove', (e) => {
    if (!arrasto) return;
    if (!arrasto.col) {
      const cg = ativarColw(arrasto.table);
      arrasto.col = cg && cg.children[arrasto.indice];
      if (!arrasto.col) {
        arrasto.th.classList.remove('ds-col-redimensionando');
        arrasto = null;
        document.body.classList.remove('ds-redimensionando');
        return;
      }
      // parte da largura RENDIDA (não da gravada): se o min-width:100% esticou
      // a tabela, o rendido difere do <col> e o gesto começaria com um salto
      arrasto.col.style.width = arrasto.wIni + 'px';
      if (arrasto.thViz) {
        arrasto.colViz = cg.children[arrasto.indice + 1] || null;
        if (arrasto.colViz) arrasto.colViz.style.width = arrasto.wIniViz + 'px';
      }
    }
    // Excel: a divisória é COMPARTILHADA — dx entra na coluna da esquerda e sai
    // da vizinha, com o clamp valendo para as DUAS (o movimento para quando
    // qualquer uma bate em COLW_MIN/COLW_MAX; a largura total não muda).
    let dx = e.clientX - arrasto.xIni;
    dx = Math.max(COLW_MIN - arrasto.wIni, Math.min(COLW_MAX - arrasto.wIni, dx));
    if (arrasto.colViz) {
      dx = Math.max(arrasto.wIniViz - COLW_MAX, Math.min(arrasto.wIniViz - COLW_MIN, dx));
      arrasto.colViz.style.width = (arrasto.wIniViz - dx) + 'px';
    }
    arrasto.col.style.width = (arrasto.wIni + dx) + 'px'; // tempo real
    sincronizarLarguraColw(arrasto.table, arrasto.col.parentElement);
  }, true);

  function terminarArrastoColw() {
    if (!arrasto) return;
    const a = arrasto;
    arrasto = null;
    a.th.classList.remove('ds-col-redimensionando');
    document.body.classList.remove('ds-redimensionando');
    if (a.col) { // houve movimento de fato → persiste o SNAPSHOT completo:
      // todas as colunas explícitas garantem que, após F5, as larguras valem
      // exatas (nenhuma "auto" para o browser redistribuir por cima)
      const mapa = lerColw(a.table) || {};
      const tr = linhaCabecalhoColw(a.table);
      const cg = a.col.parentElement;
      let i = 0;
      for (const th of tr.cells) {
        if ((th.colSpan || 1) === 1 && cg.children[i]) {
          const w = parseFloat(cg.children[i].style.width);
          if (isFinite(w)) mapa[chaveColunaColw(th, i)] = Math.round(w);
        }
        i += th.colSpan || 1;
      }
      salvarColw(a.table, mapa);
      atualizarBotoesResetColw();
    }
    // o click que o navegador dispara ao soltar NÃO pode ordenar a coluna —
    // mata nas duas convenções de sort (th.onclick e delegação data-ord)
    const mata = (ev) => { ev.stopPropagation(); ev.preventDefault(); };
    document.addEventListener('click', mata, { capture: true, once: true });
    setTimeout(() => document.removeEventListener('click', mata, { capture: true }), 0);
  }
  document.addEventListener('pointerup', terminarArrastoColw, true);
  document.addEventListener('pointercancel', terminarArrastoColw, true);

  // Duplo clique na divisória = restaura SÓ aquela coluna (gesto do Excel).
  document.addEventListener('dblclick', (e) => {
    const th = thDivisoriaColw(e);
    if (!th) return;
    const table = th.closest('table');
    const tr = table && linhaCabecalhoColw(table);
    if (!tr || th.parentElement !== tr) return;
    e.preventDefault();
    const i = indiceFolhaDoTh(tr, th);
    const cg = table.querySelector(':scope > colgroup[data-redim]');
    if (cg && cg.children[i]) {
      cg.children[i].style.width = '';
      sincronizarLarguraColw(table, cg); // sem largura em um <col> → devolve ao min-width:100%
    }
    const mapa = lerColw(table);
    if (mapa) {
      delete mapa[chaveColunaColw(th, i)];
      if (Object.keys(mapa).length) salvarColw(table, mapa);
      else resetarTabelaColw(table);
    }
    atualizarBotoesResetColw();
  }, true);

  // ---- botão "restaurar" na toolbar (molde do injetarTogglesDensidade) ----
  function injetarBotoesResetColw() {
    const html =
      '<button type="button" class="v2-colw-reset" data-colw-reset hidden ' +
      'title="Restaurar largura das colunas" aria-label="Restaurar largura das colunas">' +
      '<svg viewBox="0 0 16 16" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
      '<path d="M2 3v10M14 3v10M4.5 8h7M6.5 6 4.5 8l2 2M9.5 6l2 2-2 2"/></svg></button>';
    document.querySelectorAll('main section.ds-modulo').forEach((sec) => {
      if (!sec.id || !sec.querySelector('.tabela-wrap')) return;
      sec.querySelectorAll('.toolbar').forEach((tb) => {
        if (!tb.querySelector('[data-colw-reset]')) tb.insertAdjacentHTML('beforeend', html);
      });
    });
    atualizarBotoesResetColw();
  }
  function atualizarBotoesResetColw() {
    document.querySelectorAll('main section.ds-modulo').forEach((sec) => {
      const btns = sec.querySelectorAll('[data-colw-reset]');
      if (!btns.length) return;
      const tem = Array.from(sec.querySelectorAll('.tabela-wrap table')).some((t) => {
        const m = lerColw(t);
        return m && Object.keys(m).length;
      });
      btns.forEach((b) => { b.hidden = !tem; });
    });
  }
  document.addEventListener('click', (e) => {
    const b = e.target.closest ? e.target.closest('[data-colw-reset]') : null;
    if (!b) return;
    const sec = b.closest('section');
    if (sec) sec.querySelectorAll('.tabela-wrap table').forEach((t) => resetarTabelaColw(t));
    atualizarBotoesResetColw();
    toast('Largura das colunas restaurada.', 'ok');
  });

  // ---- auto-inicialização: boot + MutationObserver (tabela recriada/aba nova) ----
  let varreduraAgendada = false;
  function varrerColw() {
    if (!mqColwDesktop.matches) return;
    document.querySelectorAll('.tabela-wrap table').forEach((t) => {
      const mapa = lerColw(t);
      if (!mapa || !Object.keys(mapa).length) return;
      const tr = linhaCabecalhoColw(t);
      if (!tr || !tr.cells.length) return;
      const cg = t.querySelector(':scope > colgroup[data-redim]');
      // já aplicado e íntegro → não faz nada (mantém o observer sem laço)
      if (cg && t.classList.contains('ds-tabela-redim') && cg.children.length === totalColunasFolha(tr)) return;
      aplicarColwSalvas(t);
    });
  }
  new MutationObserver(() => {
    if (varreduraAgendada) return;
    varreduraAgendada = true;
    requestAnimationFrame(() => { varreduraAgendada = false; varrerColw(); });
  }).observe(document.documentElement, { childList: true, subtree: true });

  injetarBotoesResetColw();
  varrerColw();
})();
